document.addEventListener('DOMContentLoaded', () => {
            const canvas = document.getElementById('gameCanvas');
            const ctx = canvas.getContext('2d');
            
            // These are WORLD dimensions, which every piece of gameplay code
            // already treats them as: bounds clamping, cover placement, spawn
            // points, pickups and the arena painters all measure in these units.
            // Normally the world is exactly the size of the canvas, but an arena
            // may declare a `worldScale` (see ARENAS.zeropoint) to make the
            // playable space larger than the screen. The extra size is absorbed by
            // the draw transform, which scales world units down to fit — so the
            // arena is genuinely bigger and is viewed further out, and not one line
            // of gameplay code has to know that.
            let canvasLogicalW = 1058.67;
            let canvasLogicalH = 808.667;
            let canvasDpr = 1;
            // The scale in force for the arena currently loaded. Set only by
            // resizeCanvas, so the transform and the world dimensions can never
            // disagree about which arena they were computed for.
            let worldScale = 1;

            // ── STRICT ERROR MODE ───────────────────────────────────────
            // The game loop wraps update()/draw() in a try/catch so one bad frame
            // cannot end a player's match. That is right for a shipped build and
            // wrong while developing: a swallowed exception keeps the loop running
            // on corrupted state, so the real failure surfaces seconds later as
            // something unrelated. When this is on the loop simply lets the error
            // throw. Defaults on for localhost and file://, off on itch.io; force it
            // either way with ?debug=1 or ?debug=0, or toggle it in the dev menu.
            let debugStrictErrors = (() => {
                let param = null;
                try {
                    param = new URLSearchParams(location.search).get('debug');
                } catch (e) {}
                if (param !== null) return param !== '0' && param !== 'false';
                const h = (location.hostname || '').toLowerCase();
                if (h.endsWith('itch.io') || h.endsWith('itch.zone')) return false;
                return h === 'localhost' || h === '127.0.0.1' || h === '[::1]' || h === '' ||
                    location.protocol === 'file:';
            })();

            // ── LOCAL BUILD DETECTION ───────────────────────────────────
            // "Is this a developer's own copy?" — true only for localhost and
            // file://, and never for a hosted build. Deliberately narrower than
            // isDevMenuHost(), which also returns true for a valid tester
            // code: that unlocks the dev menu for trusted players on the
            // shipped build, which is exactly who must NOT see unfinished
            // prototypes. Anything gated on this is invisible and inert in the
            // shipped game, whatever a save file happens to claim.
            function isLocalBuild() {
                const h = (location.hostname || '').toLowerCase();
                if (h.endsWith('itch.io') || h.endsWith('itch.zone')) return false;
                return h === 'localhost' || h === '127.0.0.1' || h === '[::1]' || h === '' ||
                    location.protocol === 'file:';
            }

            // ── BATTLE CLOCK ────────────────────────────────────────────
            // Every combat timer — cooldowns, stuns, freezes, chokes, burns, reloads,
            // shields, the Snap's charge, Jabba's guards — is an absolute time
            // compared against "now". They used to read the wall clock
            // (Date.now()), which keeps running under the pause menu and in a
            // hidden tab: pause as Thanos for 25 seconds and the Snap came back
            // charged, a pause ended your stun, finished your reload, threw away
            // the rest of a Force Choke and burned Giant-Man's fifteen seconds.
            //
            // gameNow() is the wall clock minus every millisecond spent paused,
            // and it stands still while a pause is open. Because every in-battle
            // timer is set AND checked against it, pausing shifts them all together
            // and nothing has to be walked and adjusted on resume. Menus, contracts,
            // saves and history keep the real clock — they are about real days.
            // Anything that decides a fight must use gameNow() (or frameNow, which
            // the loop stamps from it), never Date.now().
            let battleClockPausedMs = 0;   // total wall-clock time spent paused
            let battleClockPausedAt = 0;   // wall-clock time the open pause began, 0 if none
            function gameNow() {
                return (battleClockPausedAt || Date.now()) - battleClockPausedMs;
            }
            function freezeBattleClock() {
                if (!battleClockPausedAt) battleClockPausedAt = Date.now();
            }
            function resumeBattleClock() {
                if (!battleClockPausedAt) return;
                battleClockPausedMs += Date.now() - battleClockPausedAt;
                battleClockPausedAt = 0;
            }

            // ── SAVE DATA SCHEMA VERSIONING & MIGRATION ─────────────────
            // Every persisted localStorage key under the 'galacticDuel' prefix is
            // stored wrapped in a small envelope ({ _v, data }) instead of raw JSON.
            // This lets the shape of what lives under a key change over time
            // (renamed fields, new required fields, array -> object, etc.) without
            // silently breaking existing players' saves — including saves restored
            // from an older exported save file via Load Save.
            //
            // To change a key's stored shape in the future:
            //   1. Bump CURRENT_SCHEMA_VERSION.
            //   2. Add a migration function to SAVE_MIGRATIONS[key] at index
            //      (CURRENT_SCHEMA_VERSION - 1). It receives the data as it was at
            //      that version and must return the upgraded data.
            // Old, pre-versioning saves (plain JSON with no envelope, or an older
            // exported save file) are treated as version 0 and migrated forward
            // automatically the next time they're loaded.
            const CURRENT_SCHEMA_VERSION = 2;

            const SAVE_MIGRATIONS = {
                // galacticDuelSettings: [
                //     (old) => ({ ...old, someNewField: defaultValue }), // v0 -> v1
                // ],
                galacticDuelUnlocks: [
                    undefined, // v0 -> v1: envelope introduction only, no shape change
                    (old) => { // v1 -> v2: secretFaction renamed to ultimatePalpatine
                        if (!old || typeof old !== 'object') return old;
                        const { secretFaction, ...rest } = old;
                        return { ...rest, ultimatePalpatine: !!(rest.ultimatePalpatine || secretFaction) };
                    },
                ],
            };

            // Reads and parses whatever's stored at `key`, migrating it up to
            // CURRENT_SCHEMA_VERSION if it's behind, re-persisting the migrated
            // result so this only has to happen once, and returning the plain
            // (unwrapped) value. Returns `fallback` if nothing is stored, the
            // data is corrupt, or localStorage itself throws.
            function loadVersioned(key, fallback) {
                let raw;
                try {
                    raw = localStorage.getItem(key);
                } catch (e) {
                    return fallback;
                }
                if (raw === null || raw === undefined) return fallback;

                let parsed;
                try {
                    parsed = JSON.parse(raw);
                } catch (e) {
                    return fallback;
                }

                // Unwrap the versioned envelope if present. Anything else (plain
                // object/array, or an envelope-shaped object missing our markers)
                // is treated as pre-versioning data at version 0.
                let version = 0;
                let value = parsed;
                if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
                    typeof parsed._v === 'number' && 'data' in parsed) {
                    version = parsed._v;
                    value = parsed.data;
                }

                const migrations = SAVE_MIGRATIONS[key] || [];
                const startingVersion = version;
                while (version < CURRENT_SCHEMA_VERSION) {
                    const step = migrations[version];
                    // A hop with no registered migration function means that bump
                    // didn't change this key's data shape (e.g. it only introduced
                    // the envelope itself, or changed an unrelated key) — carry the
                    // value through unchanged and still advance the version tag so
                    // it's accurately marked current.
                    if (typeof step === 'function') {
                        try {
                            value = step(value);
                        } catch (e) {
                            break; // don't let a bad migration corrupt data further; keep last-good value/version
                        }
                    }
                    version++;
                }

                // Re-persist any time the stored version tag was behind current,
                // even if every hop was an identity carry-through (no-op data
                // changes still need their envelope's _v brought up to date).
                if (version !== startingVersion) saveVersioned(key, value, version);
                return value;
            }

            // Writes `value` under `key` wrapped in a versioned envelope so it can
            // be migrated correctly on future loads (including after export/import
            // round-trips through collectSaveData / Load Save).
            function saveVersioned(key, value, version = CURRENT_SCHEMA_VERSION) {
                try {
                    localStorage.setItem(key, JSON.stringify({ _v: version, data: value }));
                } catch (e) {}
            }

            // A save is plain JSON that players edit by hand and pass around as
            // files, so a number read from one is checked before it is used:
            // finite, and inside the range the game itself would ever write.
            function savedNumber(v, min, max, fallback) {
                return (typeof v === 'number' && Number.isFinite(v)) ? Math.min(max, Math.max(min, v)) : fallback;
            }

            // Runs one start-up step so that a throw inside it costs that step and
            // nothing else. All of boot is one DOMContentLoaded handler, so a single
            // bad value in a save used to leave a dead page that reloading could
            // never fix. A warning rather than an error: the game carries on, and
            // smoke.js fails a run on console errors.
            function bootStep(fn) {
                try { fn(); } catch (e) { console.warn('Galactic Legends: a start-up step failed and was skipped.', e); }
            }

            const mobileControls = document.getElementById('mobileControls');
            const touchStickBase = document.getElementById('touchStickBase');
            const touchStickKnob = document.getElementById('touchStickKnob');
            const touchFireBtn = document.getElementById('touchFireBtn');
            const touchMove = { active: false, x: 0, y: 0 };
            const touchDodgeBtn    = document.getElementById('touchDodgeBtn');
            const touchReloadBtn   = document.getElementById('touchReloadBtn');
            const touchInteractBtn = document.getElementById('touchInteractBtn');
            const touchThrowBtn    = document.getElementById('touchThrowBtn');
            const touchPauseBtn    = document.getElementById('touchPauseBtn');
            let touchFire = false;
            // Held-state mirrors of the keyboard bindings these buttons stand in for:
            // Shift (dodge), R (reload) and E (interact). Holding the on-screen button
            // behaves exactly like holding the key, which matters for interact — it is
            // a hold-to-use prompt, not a tap.
            let touchDodge    = false;
            let touchReload   = false;
            let touchInteract = false;
            let touchThrow    = false; // stands in for Q / RMB — throws a melee blade

            function resetTouchInput() {
                touchMove.active = false;
                touchMove.x = 0;
                touchMove.y = 0;
                touchFire     = false;
                touchDodge    = false;
                touchReload   = false;
                touchInteract = false;
                touchThrow    = false;
                if (touchStickKnob) touchStickKnob.style.transform = 'translate(0,0)';
            }

            function updateMobileControlsVisibility() {
                if (!mobileControls) return;
                const inFight = canvas.style.display === 'block';
                const overlayEl = document.getElementById('messageOverlay');
                const dialogOpen = overlayEl && overlayEl.style.display === 'flex';
                const paused = typeof gamePaused !== 'undefined' && gamePaused;
                const coarsePointer = window.matchMedia('(pointer: coarse)').matches;
                const narrow = window.innerWidth <= 900;
                const show = inFight && !dialogOpen && !paused && (coarsePointer || narrow);
                mobileControls.classList.toggle('visible', show);
                mobileControls.setAttribute('aria-hidden', show ? 'false' : 'true');
                // Buttons stay pressed if the controls are torn down mid-hold (quit,
                // round end, pause) — the pointerup never lands on them.
                if (!show) {
                    touchFire     = false;
                    touchDodge    = false;
                    touchReload   = false;
                    touchInteract = false;
                    touchThrow    = false;
                }
            }

            // Contextual visibility for the right-hand action cluster, refreshed each
            // frame from gameLoop(). Reload only means something for weapons carrying
            // a magazine, Interact only while a hold-prompt is live, and Jabba cannot
            // dodge at all — showing dead buttons would just be noise.
            let lastTouchActionState = '';
            function updateTouchActionButtons() {
                if (!touchDodgeBtn) return;
                const p = mainPlayer;
                const canDodge  = !!(p && p.isAlive && p.characterId !== 'jabba');
                const canReload = !!(p && p.isAlive && p.weaponConfig && p.weaponConfig.magSize != null);
                // Interact covers two unrelated things now: the carbonite rescue
                // hold, and Vader's Force Choke.
                const canInteract = !!(p && p.isAlive && (isCarboniteRescuePhase() || hasInteractAbility(p)));
                // A live neck snap lights the button back up even mid-choke-cooldown
                // — that press does something, so it must not look greyed out.
                const canSnap = !!(p && findNeckSnapTarget(p));
                const interactReady = !!(p && (canSnap || interactAbilityReady(p)));
                const dodgeReady = !!(p && gameNow() > p.dodgeCooldown);
                // The secondary button covers two things: throwing a melee blade,
                // and firing a droid's sidearm. Throw is greyed while the blade is
                // already out or its cooldown has not elapsed; the sidearm greys
                // on its own cooldown.
                const hasSidearm = !!(p && getSidearmConfig(p));
                // Ant-Man's fists cannot be thrown, but the same button is how a
                // touch player grows him (Q on a keyboard).
                const antGrow = canAntManResize(p);
                // And how a Halloween commander raises his skeletons. Once a round,
                // so the button stays up and greys out once it has been spent
                // rather than vanishing and leaving the player to wonder.
                const summoner = !!(p && p.isAlive && p.isMainEntity && HALLOWEEN_SUMMONS[p.characterId]);
                const canThrow = !!(p && p.isAlive && ((p.weaponConfig && p.weaponConfig.melee && !p.weaponConfig.noThrow) || hasSidearm || antGrow || summoner));
                const throwReady = !!(canThrow && (summoner ? canHalloweenSummon(p) : antGrow ? p.antForm !== 'giant' : hasSidearm
                    ? gameNow() - p.lastSidearmShotTime > getSidearmConfig(p).cooldown
                    : gameNow() >= (p.throwReadyAt || 0) && !hasBladeInFlight(p)));

                const stateKey = `${canDodge}|${canReload}|${canInteract}|${interactReady}|${canSnap}|${dodgeReady}|${canThrow}|${throwReady}|${hasSidearm}|${antGrow}|${summoner}`;
                if (stateKey === lastTouchActionState) return;
                lastTouchActionState = stateKey;

                touchDodgeBtn.hidden = !canDodge;
                touchDodgeBtn.classList.toggle('on-cooldown', canDodge && !dodgeReady);
                if (touchReloadBtn)   touchReloadBtn.hidden   = !canReload;
                if (touchInteractBtn) {
                    touchInteractBtn.hidden = !canInteract;
                    touchInteractBtn.classList.toggle('on-cooldown', canInteract && !interactReady);
                    // Swap the glyph while a snap is live so the finisher announces
                    // itself — the window is two seconds and easy to miss.
                    touchInteractBtn.textContent = canSnap ? '💀' : '✋';
                    touchInteractBtn.setAttribute('aria-label', canSnap ? 'Snap neck' : 'Interact (hold)');
                }
                if (touchThrowBtn) {
                    touchThrowBtn.hidden = !canThrow;
                    touchThrowBtn.classList.toggle('on-cooldown', canThrow && !throwReady);
                    // Same button, two jobs — say which one it is doing.
                    touchThrowBtn.textContent = antGrow ? '⬆️' : hasSidearm ? '🔫' : '🌀';
                    touchThrowBtn.setAttribute('aria-label', antGrow ? 'Grow' : hasSidearm ? 'Fire blaster' : 'Throw blade');
                }
                if (!canDodge)    touchDodge = false;
                if (!canReload)   touchReload = false;
                if (!canInteract) touchInteract = false;
                if (!canThrow)    touchThrow = false;
            }

            function bindMobileTouchControls() {
                if (!touchStickBase || !touchStickKnob || !touchFireBtn) return;
                const updateStick = (e) => {
                    const r = touchStickBase.getBoundingClientRect();
                    const cx = r.left + r.width / 2;
                    const cy = r.top + r.height / 2;
                    const max = r.width * 0.36;
                    let dx = e.clientX - cx;
                    let dy = e.clientY - cy;
                    const dist = Math.hypot(dx, dy);
                    if (dist > max && dist > 0) {
                        dx = (dx / dist) * max;
                        dy = (dy / dist) * max;
                    }
                    touchStickKnob.style.transform = `translate(${dx}px, ${dy}px)`;
                    const nx = max > 0 ? dx / max : 0;
                    const ny = max > 0 ? dy / max : 0;
                    touchMove.active = true;
                    touchMove.x = nx;
                    touchMove.y = ny;
                };
                const resetStick = () => {
                    touchMove.active = false;
                    touchMove.x = 0;
                    touchMove.y = 0;
                    touchStickKnob.style.transform = 'translate(0,0)';
                };
                touchStickBase.addEventListener('pointerdown', (e) => {
                    e.preventDefault();
                    touchStickBase.setPointerCapture(e.pointerId);
                    updateStick(e);
                });
                touchStickBase.addEventListener('pointermove', (e) => {
                    if (!touchStickBase.hasPointerCapture(e.pointerId)) return;
                    e.preventDefault();
                    updateStick(e);
                });
                touchStickBase.addEventListener('pointerup', (e) => {
                    if (touchStickBase.hasPointerCapture(e.pointerId)) {
                        touchStickBase.releasePointerCapture(e.pointerId);
                    }
                    resetStick();
                });
                touchStickBase.addEventListener('pointercancel', resetStick);
                touchStickBase.addEventListener('lostpointercapture', resetStick);

                const setFire = (v) => { touchFire = v; };
                touchFireBtn.addEventListener('pointerdown', (e) => {
                    e.preventDefault();
                    touchFireBtn.setPointerCapture(e.pointerId);
                    setFire(true);
                });
                touchFireBtn.addEventListener('pointerup', (e) => {
                    if (touchFireBtn.hasPointerCapture(e.pointerId)) {
                        touchFireBtn.releasePointerCapture(e.pointerId);
                    }
                    setFire(false);
                });
                touchFireBtn.addEventListener('pointercancel', () => setFire(false));
                touchFireBtn.addEventListener('lostpointercapture', () => setFire(false));

                // Hold-style action buttons. Each one drives the same held-state flag
                // its keyboard equivalent sets, so the update loop needs no special
                // casing for touch.
                const bindHoldButton = (btn, set) => {
                    if (!btn) return;
                    btn.addEventListener('pointerdown', (e) => {
                        e.preventDefault();
                        btn.setPointerCapture(e.pointerId);
                        set(true);
                    });
                    btn.addEventListener('pointerup', (e) => {
                        if (btn.hasPointerCapture(e.pointerId)) btn.releasePointerCapture(e.pointerId);
                        set(false);
                    });
                    btn.addEventListener('pointercancel', () => set(false));
                    btn.addEventListener('lostpointercapture', () => set(false));
                };
                bindHoldButton(touchDodgeBtn,    (v) => { touchDodge = v; });
                bindHoldButton(touchReloadBtn,   (v) => { touchReload = v; });
                bindHoldButton(touchInteractBtn, (v) => { touchInteract = v; });
                bindHoldButton(touchThrowBtn,    (v) => { touchThrow = v; });

                if (touchPauseBtn) {
                    touchPauseBtn.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        resetTouchInput();
                        openPauseMenu();
                    });
                }
            }
            bindMobileTouchControls();
            bindMouseAim();

            // ── GAMEPAD SUPPORT ────────────────────────────────────────
            // Standard-mapping layout, Xbox button names (PlayStation in brackets):
            //   Left stick / D-pad     → move
            //   A [✕] or Right Trigger → shoot
            //   B [○] or either bumper → dodge
            //   X [□]                  → reload
            //   Y [△]                  → interact (hold)
            //   Start                  → pause / resume
            // Polled on its own requestAnimationFrame loop rather than inside
            // gameLoop, because opening the pause menu cancels gameLoop — Start has
            // to keep being read or there would be no way to un-pause with the pad.
            // The loop only runs while a pad is actually connected.
            const padState = { active: false, moveX: 0, moveY: 0, fire: false, dodge: false, reload: false, interact: false,
                               aimX: 0, aimY: 0, aimHeldAngle: null, throwBlade: false };
            const PAD_DEADZONE = 0.25;
            let padPollId = 0;
            let padLastUsedAt = 0;
            let lastKeyboardUseAt = 0;

            function readGamepad() {
                const pads = navigator.getGamepads ? navigator.getGamepads() : [];
                for (const pad of pads) {
                    if (pad && pad.connected && pad.mapping === 'standard') return pad;
                }
                // No pad reported the standard mapping — take whatever is connected and
                // hope the indices line up rather than ignoring the controller entirely.
                for (const pad of pads) {
                    if (pad && pad.connected) return pad;
                }
                return null;
            }

            function clearPadState() {
                padState.active = false;
                padState.moveX = 0;
                padState.moveY = 0;
                padState.fire = false;
                padState.dodge = false;
                padState.reload = false;
                padState.interact = false;
                padState.aimX = 0;
                padState.aimY = 0;
                padState.aimHeldAngle = null;
                padState.throwBlade = false;
            }

            // ── GAMEPAD UI NAVIGATION ──────────────────────────────────
            // The pad drives the whole game, not just the fight — menus, rosters,
            // overlays, the shop and the pause screen are all reachable without ever
            // touching the keyboard or mouse. Text fields are the one exception: the
            // pad can focus them, but typing still needs a keyboard.
            //
            // Focus moves spatially rather than in DOM order, scoring each candidate
            // on how far it sits in the requested direction against how far it drifts
            // off-axis. The rosters, arena picker and difficulty row are all wrapped
            // grids whose DOM order does not match their visual layout, so a flat
            // next/previous walk would jump around unpredictably.
            const NAV_REPEAT_DELAY_MS = 420; // hold this long before auto-repeat starts
            const NAV_REPEAT_RATE_MS  = 120;
            const NAV_PAGE_JUMP       = 8;   // items skipped by the shoulder buttons
            const NAV_SELECTOR = 'button, input[type="range"], input[type="text"], a[href]';

            // Topmost first — whichever of these is on screen owns the pad. The
            // loading screen is listed so it swallows input while assets stream in:
            // it holds no buttons, so nothing is navigable until it goes away.
            const UI_LAYER_IDS = [
                'loadingScreen',
                // Above every menu it covers, below confirm: the card is modal, but
                // a confirmation raised over it would still have to win.
                'confirmOverlay', 'seasonCardOverlay',
                // The Halloween event's two cards sit over the splash like the
                // season card does, and a confirm over them still wins.
                'halloweenDisclaimer', 'halloweenTeamOverlay',
                'pauseOverlay', 'controlsOverlay', 'shopOverlay',
                'armoryOverlay', 'creatorOverlay',
                'creditsOverlay', 'dossierOverlay', 'spritesOverlay',
                'devMenuPanel', 'settingsPanel', 'messageOverlay',
                'opponentMenu', 'mainMenu', 'splashMenu'
            ];
            // Settings, fullscreen and the dev toggle float outside the menu
            // containers, so they have to be folded into those screens by hand or the
            // pad could never reach them.
            const BASE_SCREEN_IDS  = ['splashMenu', 'mainMenu', 'opponentMenu', 'messageOverlay'];
            const FLOATING_BTN_IDS = ['settingsBtn', 'fullscreenBtn', 'devMenuToggle'];

            let navDir = '';
            let navNextRepeatAt = 0;
            let navPrevLayer = null;
            const padPrevButtons = {};

            // Rect first: a display:none element measures zero, so filtered-out roster
            // entries bail here without paying for getComputedStyle. This runs over
            // every candidate on each focus move, and the roster is ~195 buttons.
            function isShown(el) {
                if (!el || el.hidden) return false;
                const r = el.getBoundingClientRect();
                if (r.width <= 0 || r.height <= 0) return false;
                const cs = window.getComputedStyle(el);
                if (cs.display === 'none' || cs.visibility === 'hidden') return false;
                // A collapsed Secret or season section hides its contents with opacity and a
                // 0fr grid row. The buttons inside keep a real layout box, so the rect
                // test above still passes them — focus would vanish into a section the
                // player cannot see. checkVisibility understands ancestor opacity;
                // the closest() check covers browsers that lack it.
                if (typeof el.checkVisibility === 'function' &&
                    !el.checkVisibility({ opacityProperty: true, visibilityProperty: true })) {
                    return false;
                }
                return !el.closest('.secret-collapse-wrapper.collapsed');
            }

            function getActiveUiLayer() {
                for (const id of UI_LAYER_IDS) {
                    const el = document.getElementById(id);
                    if (isShown(el)) return el;
                }
                return null;
            }

            function getNavigables(layer) {
                if (!layer) return [];
                const items = Array.from(layer.querySelectorAll(NAV_SELECTOR)).filter(el =>
                    !el.disabled && !el.classList.contains('star-btn') && isShown(el)
                );
                if (BASE_SCREEN_IDS.includes(layer.id)) {
                    for (const id of FLOATING_BTN_IDS) {
                        const el = document.getElementById(id);
                        if (isShown(el)) items.push(el);
                    }
                }
                return items;
            }

            function clearNavFocus() {
                document.querySelectorAll('.gamepad-focus').forEach(el => el.classList.remove('gamepad-focus'));
            }

            function setNavFocus(el) {
                if (!el) return;
                clearNavFocus();
                el.classList.add('gamepad-focus');
                try {
                    el.focus({ preventScroll: true });
                } catch (err) {
                    el.focus();
                }
                if (typeof el.scrollIntoView === 'function') {
                    el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
                }
            }

            function navFocusFirst(layer) {
                const items = getNavigables(layer);
                if (!items.length) return;
                // Keep whatever is already focused inside this layer — coming back from
                // a closed overlay shouldn't throw the player back to the top of a
                // 195-entry roster.
                const current = items.indexOf(document.activeElement);
                setNavFocus(current >= 0 ? items[current] : items[0]);
            }

            function adjustRange(input, direction) {
                const step = parseFloat(input.step) || 1;
                const min  = parseFloat(input.min);
                const max  = parseFloat(input.max);
                let value  = (parseFloat(input.value) || 0) + step * direction * 4;
                if (!Number.isNaN(min)) value = Math.max(min, value);
                if (!Number.isNaN(max)) value = Math.min(max, value);
                input.value = value;
                input.dispatchEvent(new Event('input',  { bubbles: true }));
                input.dispatchEvent(new Event('change', { bubbles: true }));
            }

            function navMove(dir) {
                const items = getNavigables(getActiveUiLayer());
                if (!items.length) return;

                const current = items.includes(document.activeElement) ? document.activeElement : null;
                if (!current) {
                    setNavFocus(items[0]);
                    return;
                }

                // A focused slider swallows left/right so volume can be set with the pad.
                if (current.type === 'range' && (dir === 'left' || dir === 'right')) {
                    adjustRange(current, dir === 'right' ? 1 : -1);
                    return;
                }

                const cr = current.getBoundingClientRect();
                const cx = cr.left + cr.width / 2;
                const cy = cr.top + cr.height / 2;

                let best = null;
                let bestScore = Infinity;
                for (const el of items) {
                    if (el === current) continue;
                    const r = el.getBoundingClientRect();
                    const dx = (r.left + r.width / 2) - cx;
                    const dy = (r.top + r.height / 2) - cy;

                    let along, across;
                    if (dir === 'left')       { along = -dx; across = Math.abs(dy); }
                    else if (dir === 'right') { along =  dx; across = Math.abs(dy); }
                    else if (dir === 'up')    { along = -dy; across = Math.abs(dx); }
                    else                      { along =  dy; across = Math.abs(dx); }

                    if (along <= 1) continue; // behind us, or level with us
                    // Off-axis drift is weighted heavily so focus prefers to stay in
                    // the same row or column instead of cutting diagonally.
                    const score = along + across * 2.5;
                    if (score < bestScore) {
                        bestScore = score;
                        best = el;
                    }
                }
                if (best) {
                    setNavFocus(best);
                } else if (dir === 'up' || dir === 'down') {
                    // Nothing left to focus this way. Overlays like Achievements and
                    // Match History are read-only lists whose only button is Close, so
                    // without this a pad could open them but never read past the fold.
                    scrollActiveLayer(dir === 'down' ? 1 : -1);
                }
            }

            // Deepest scrolling container in the layer. Only called when a focus move
            // found nothing, so walking the subtree is not on the hot path.
            function findScrollable(layer) {
                if (!layer) return null;
                const candidates = [layer, ...layer.querySelectorAll('div, ul, table, section')];
                for (const el of candidates) {
                    if (el.scrollHeight > el.clientHeight + 4) {
                        const overflowY = window.getComputedStyle(el).overflowY;
                        if (overflowY === 'auto' || overflowY === 'scroll') return el;
                    }
                }
                return null;
            }

            function scrollActiveLayer(direction) {
                const el = findScrollable(getActiveUiLayer());
                if (el) el.scrollTop += 120 * direction;
            }

            function navPage(direction) {
                const items = getNavigables(getActiveUiLayer());
                if (!items.length) return;
                const idx = items.indexOf(document.activeElement);
                const from = idx >= 0 ? idx : 0;
                const next = Math.max(0, Math.min(items.length - 1, from + NAV_PAGE_JUMP * direction));
                setNavFocus(items[next]);
            }

            function navActivate() {
                const items = getNavigables(getActiveUiLayer());
                if (!items.length) return;
                const el = items.includes(document.activeElement) ? document.activeElement : items[0];
                if (!items.includes(document.activeElement)) {
                    setNavFocus(el);
                    return;
                }
                // Text fields have nothing to activate — hand them the caret and let
                // the player type on a keyboard.
                if (el.tagName === 'INPUT' && el.type === 'text') {
                    el.focus();
                    return;
                }
                el.click();
            }

            // B backs out of whatever is on top. Each layer closes the way its own
            // close button does, so any bookkeeping those handlers do still happens.
            function navBack() {
                const layer = getActiveUiLayer();
                if (!layer) return;
                const active = document.activeElement;
                if (active && active.tagName === 'INPUT' && active.type === 'text') {
                    active.blur();
                    return;
                }
                const clickById = (id) => {
                    const b = document.getElementById(id);
                    if (b && isShown(b)) b.click();
                };
                switch (layer.id) {
                    case 'confirmOverlay':      clickById('confirmCancelBtn'); break;
                    case 'halloweenDisclaimer':  clickById('halloweenDisclaimerBackBtn'); break;
                    case 'halloweenTeamOverlay': clickById('halloweenTeamBackBtn'); break;
                    case 'pauseOverlay':        closePauseMenu(); break;
                    case 'controlsOverlay':     closeControlsOverlay(); break;
                    case 'shopOverlay':         clickById('shopCloseBtn'); break;
                    case 'armoryOverlay':       clickById('armoryCloseBtn'); break;
                    case 'creatorOverlay':      clickById('creatorCloseBtn'); break;
                    case 'creditsOverlay':      clickById('creditsCloseBtn'); break;
                    case 'dossierOverlay':      clickById('dossierCloseBtn'); break;
                    case 'spritesOverlay':      clickById('spritesCloseBtn'); break;
                    case 'devMenuPanel':        layer.style.display = 'none'; break;
                    case 'settingsPanel':       setSettingsOpen(false); break;
                    case 'messageOverlay':      clickById('restartButton'); break;
                    case 'opponentMenu':        clickById('backBtn'); break;
                    case 'mainMenu':            showSplashMenu(); break;
                    default: break; // splash is the root — nothing to back out to
                }
            }

            // X toggles the favourite star on a focused roster entry. The star is its
            // own nested button, which is excluded from navigation so it cannot eat a
            // spatial move aimed at the character button wrapping it.
            function navToggleFavorite() {
                const el = document.activeElement;
                if (!el || !el.dataset || !el.dataset.character) return;
                const star = el.querySelector('.star-btn');
                if (star) star.click();
            }

            function handleNavDirection(mx, my, dpad) {
                let dir = '';
                const DEAD = 0.5;
                if (dpad.left)       dir = 'left';
                else if (dpad.right) dir = 'right';
                else if (dpad.up)    dir = 'up';
                else if (dpad.down)  dir = 'down';
                else if (Math.abs(mx) >= DEAD || Math.abs(my) >= DEAD) {
                    dir = Math.abs(mx) > Math.abs(my)
                        ? (mx < 0 ? 'left' : 'right')
                        : (my < 0 ? 'up' : 'down');
                }

                if (!dir) {
                    navDir = '';
                    return;
                }
                const now = Date.now();
                if (dir !== navDir) {
                    navDir = dir;
                    navNextRepeatAt = now + NAV_REPEAT_DELAY_MS;
                    navMove(dir);
                } else if (now >= navNextRepeatAt) {
                    navNextRepeatAt = now + NAV_REPEAT_RATE_MS;
                    navMove(dir);
                }
            }

            function pollGamepad() {
                const pad = readGamepad();
                if (!pad) {
                    clearPadState();
                    clearNavFocus();
                    navPrevLayer = null;
                    padPollId = 0;
                    return;
                }

                const btn = (i) => !!(pad.buttons[i] && pad.buttons[i].pressed);
                const axis = (i) => {
                    const v = pad.axes[i] || 0;
                    return Math.abs(v) < PAD_DEADZONE ? 0 : v;
                };
                const pressed = (i) => btn(i) && !padPrevButtons[i];

                const dpad = { left: btn(14), right: btn(15), up: btn(12), down: btn(13) };
                let mx = axis(0);
                let my = axis(1);
                if (dpad.left)  mx -= 1;
                if (dpad.right) mx += 1;
                if (dpad.up)    my -= 1;
                if (dpad.down)  my += 1;
                mx = Math.max(-1, Math.min(1, mx));
                my = Math.max(-1, Math.min(1, my));

                let anyInput = mx !== 0 || my !== 0;
                for (let i = 0; !anyInput && i < pad.buttons.length; i++) {
                    if (btn(i)) anyInput = true;
                }
                if (anyInput) padLastUsedAt = Date.now();

                const uiLayer = getActiveUiLayer();
                if (uiLayer) {
                    // Menus own the pad — zero the gameplay flags so the player is not
                    // also firing and dodging behind whatever is on screen.
                    clearPadState();
                    if (uiLayer !== navPrevLayer) {
                        navPrevLayer = uiLayer;
                        navFocusFirst(uiLayer);
                    }
                    handleNavDirection(mx, my, dpad);
                    if (pressed(0)) navActivate();
                    if (pressed(1)) navBack();
                    if (pressed(2)) navToggleFavorite();
                    if (pressed(4)) navPage(-1);
                    if (pressed(5)) navPage(1);
                } else {
                    if (navPrevLayer !== null) {
                        navPrevLayer = null;
                        navDir = '';
                        clearNavFocus();
                    }
                    padState.moveX = mx;
                    padState.moveY = my;
                    padState.active = mx !== 0 || my !== 0;
                    padState.fire     = btn(0) || btn(7);
                    padState.dodge    = btn(1) || btn(4) || btn(5);
                    padState.reload   = btn(2);
                    padState.interact = btn(3);
                    // Left trigger throws a melee blade. Dodge already owns both
                    // bumpers and B, so LT is the only free shoulder input.
                    padState.throwBlade = btn(6);

                    // Right stick aims (twin-stick style). The last non-zero
                    // direction is remembered so releasing the stick holds the
                    // current facing instead of snapping to angle 0.
                    padState.aimX = axis(2);
                    padState.aimY = axis(3);
                    if (padState.aimX !== 0 || padState.aimY !== 0) {
                        padState.aimHeldAngle = Math.atan2(padState.aimY, padState.aimX);
                        aimSource = 'pad';
                    }
                }

                // Start is edge-triggered — holding it must not thrash the pause menu.
                if (pressed(9)) {
                    if (gamePaused) closePauseMenu();
                    else if (isInBattle()) openPauseMenu();
                }

                for (let i = 0; i < pad.buttons.length; i++) padPrevButtons[i] = btn(i);
                padPollId = requestAnimationFrame(pollGamepad);
            }

            function startGamepadPolling() {
                if (padPollId) return;
                padPollId = requestAnimationFrame(pollGamepad);
            }

            window.addEventListener('gamepadconnected', () => {
                padLastUsedAt = Date.now();
                startGamepadPolling();
            });
            window.addEventListener('gamepaddisconnected', () => {
                if (!readGamepad()) {
                    cancelAnimationFrame(padPollId);
                    padPollId = 0;
                    clearPadState();
                }
            });
            // Browsers only surface a pad after its first button press, so the event
            // above is the usual entry point — but a pad can already be visible on a
            // reload, and that case would otherwise go unnoticed until it is unplugged.
            if (readGamepad()) startGamepadPolling();

            // ── PLAYER AIMING ──────────────────────────────────────────
            // The player used to fire at whatever getClosestEnemy() returned, which
            // meant there was no way to miss and no way to choose a target. Now the
            // shot goes wherever the player is pointing.
            //
            // Which aiming mode is live is decided by the last input actually used,
            // not by sniffing the device — that is what makes hybrid machines (a
            // touchscreen laptop, a tablet with a mouse, a phone with a gamepad)
            // behave sensibly without a special case for each:
            //
            //   aimSource 'mouse' → aim at the cursor's position on the canvas
            //   aimSource 'pad'   → aim along the right stick
            //   aimSource 'none'  → nothing has pointed anywhere yet, so fall back
            //                       to auto-aim. This is the permanent state on a
            //                       phone, where the only inputs are the stick and
            //                       the fire button and manual aiming with a thumb
            //                       already covering the screen is hopeless.
            //
            // The Auto-Aim setting forces the fallback on regardless of input, for
            // players who would rather just concentrate on movement.
            let autoAimEnabled = false;
            let mouseFire = false;  // left mouse button held over the canvas
            let mouseThrow = false; // right mouse button — throws a melee blade
            // One-time nudge on the first fight after this update, so returning
            // players who were used to shots homing in are told what changed and
            // where the switch to put it back is.
            let seenAimHint = false;
            // The first-fight coach card, shown once over the arena of a cold
            // save's first match. Written the moment the card is raised, so a
            // reload mid-card does not earn a second one.
            let seenFirstFightCard = false;
            // ── KEY BINDINGS ───────────────────────────────────────────
            // Which key does each battle action. Values are normalizeKey() names:
            // one lowercase character, or a KeyboardEvent.key name like 'Shift'.
            // The arrow keys are not in here and always move as well, so a player
            // who rebinds W A S D somewhere odd can still walk with the arrows.
            // Rebound from Settings ▸ Controls (see the CONTROLS OVERLAY block),
            // saved in galacticDuelSettings as `keyBindings`.
            //
            // Esc and Enter are not bindable: Esc is pause and backs out of the
            // capture itself, and Enter confirms in menus.
            const DEFAULT_KEY_BINDINGS = Object.freeze({
                up: 'w', left: 'a', down: 's', right: 'd',
                fire: ' ', throw: 'q', dodge: 'Shift', reload: 'r', interact: 'e'
            });
            const RESERVED_KEYS = new Set(['Escape', 'Enter', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab', 'Meta', 'OS']);
            let keyBindings = { ...DEFAULT_KEY_BINDINGS };
            /** Read a saved bindings object, keeping only known actions with a usable
             *  key and dropping any key bound twice, so a hand-edited or corrupt save
             *  cannot leave two actions fighting over one key or an action unbound. */
            function sanitizeKeyBindings(saved) {
                const out = { ...DEFAULT_KEY_BINDINGS };
                if (!saved || typeof saved !== 'object') return out;
                for (const action of Object.keys(DEFAULT_KEY_BINDINGS)) {
                    const k = saved[action];
                    // A real key: one printable character, or a key name such as
                    // Shift or F1. The label is drawn into the controls list.
                    const looksLikeKey = typeof k === 'string' &&
                        (/^[^\x00-\x1f\x7f]$/u.test(k) || /^[A-Za-z][A-Za-z0-9]{1,24}$/.test(k));
                    if (looksLikeKey && !RESERVED_KEYS.has(k)) out[action] = k;
                }
                const seen = new Set();
                for (const action of Object.keys(out)) {
                    if (seen.has(out[action])) return { ...DEFAULT_KEY_BINDINGS };
                    seen.add(out[action]);
                }
                return out;
            }
            /** How a binding reads on screen: 'Space' for ' ', 'W' for 'w'. */
            function keyLabel(k) {
                if (k === ' ') return 'Space';
                if (k && k.length === 1) return k.toUpperCase();
                return k || '?';
            }
            function boundKeyLabel(action) { return keyLabel(keyBindings[action]); }
            // Gates the Zero Event tile. A first-time player should not be able
            // to permanently retire most of the roster before they have played
            // a match — set on the first decided series the player wins.
            let hasWonSeries = false;
            // Shop item ids the player has already been shown, so the tile can say
            // how many are new since they last opened it.
            let shopSeenIds = [];
            let aimSource = 'none'; // 'none' | 'mouse' | 'pad'
            const mouseAim = { x: 0, y: 0, valid: false };
            // Reused so the ~14 shots/second a Beam or Flamethrower puts out do not
            // allocate a throwaway target object each. Every consumer reads .x/.y
            // immediately and keeps no reference.
            const aimScratch = { x: 0, y: 0 };

            // How far in front of the player the right stick's direction is projected
            // to make a concrete point to shoot at. Any distance works — only the
            // angle matters — but keeping it beyond the arena's diagonal means the
            // aim indicator never lands awkwardly close to the player's feet.
            const PAD_AIM_DISTANCE = 600;

            function isManualAimActive() {
                return !autoAimEnabled && aimSource !== 'none';
            }

            // Translates a viewport coordinate into the canvas's logical coordinate
            // space. Going through getBoundingClientRect rather than assuming the
            // canvas is displayed 1:1 keeps the crosshair under the cursor when the
            // element is letterboxed or CSS-scaled, and canvasDpr never enters into
            // it because everything is drawn in logical units.
            function setMouseAimFromEvent(clientX, clientY) {
                const rect = canvas.getBoundingClientRect();
                if (!rect.width || !rect.height) return;
                mouseAim.x = (clientX - rect.left) * (canvasLogicalW / rect.width);
                mouseAim.y = (clientY - rect.top) * (canvasLogicalH / rect.height);
                mouseAim.valid = true;
                aimSource = 'mouse';
            }

            // The single place that answers "where is the player shooting?". Returns
            // a real entity when auto-aiming (so nothing downstream changes) or a
            // point when aiming manually — both are consumed only as {x, y}.
            /*  ── AIMBOT (dev menu) ────────────────────────────────────────────
             *  Every projectile the player fires steers toward the nearest enemy for
             *  its whole flight. Not a lead, not an aim assist — the shot itself
             *  chases. Point anywhere and it curves onto the target.
             *
             *  It is applied in the Projectile constructor rather than at any of the
             *  places that fire one, because there are several of those: the ordinary
             *  trigger, each round of a multishot pair, a charged release. Marking the
             *  projectile as it is built catches all of them without any fire path
             *  knowing the option exists.
             *
             *  See the homing block in step() for the steering itself.               */
            let devAimbotEnabled = false;
            const AIMBOT_TURN = 0.22;   // radians per frame — hard enough to be a cheat

            function resolvePlayerAim(entity) {
                if (!entity || !isManualAimActive()) return getClosestEnemy(entity);

                if (aimSource === 'pad') {
                    // Hold the last stick direction when the stick is released, so
                    // letting go of it aims where you were pointing rather than
                    // snapping the shot back to due east.
                    const ax = padState.aimX, ay = padState.aimY;
                    const mag = Math.hypot(ax, ay);
                    if (mag > 0) {
                        aimScratch.x = entity.x + (ax / mag) * PAD_AIM_DISTANCE;
                        aimScratch.y = entity.y + (ay / mag) * PAD_AIM_DISTANCE;
                        return aimScratch;
                    }
                    if (padState.aimHeldAngle !== null) {
                        aimScratch.x = entity.x + Math.cos(padState.aimHeldAngle) * PAD_AIM_DISTANCE;
                        aimScratch.y = entity.y + Math.sin(padState.aimHeldAngle) * PAD_AIM_DISTANCE;
                        return aimScratch;
                    }
                    return getClosestEnemy(entity);
                }

                if (mouseAim.valid) {
                    // A shot fired from exactly under the cursor has no direction to
                    // travel in; fall back rather than emit a NaN-angle projectile.
                    if (Math.hypot(mouseAim.x - entity.x, mouseAim.y - entity.y) < 1) {
                        return getClosestEnemy(entity);
                    }
                    aimScratch.x = mouseAim.x;
                    aimScratch.y = mouseAim.y;
                    return aimScratch;
                }

                return getClosestEnemy(entity);
            }

            // Mouse aiming is bound on the canvas rather than the window so that
            // moving the cursor over a menu or the settings panel does not silently
            // re-point the player. pointermove covers mouse, pen and trackpad in one
            // listener; touch is filtered out because a thumb dragging the on-screen
            // stick would otherwise register as an aim and knock the game out of
            // auto-aim mode on exactly the devices that need it.
            function bindMouseAim() {
                if (!canvas) return;
                const onPointer = (e) => {
                    if (e.pointerType === 'touch') return;
                    setMouseAimFromEvent(e.clientX, e.clientY);
                };
                canvas.addEventListener('pointermove', onPointer, { passive: true });
                canvas.addEventListener('pointerdown', onPointer, { passive: true });
                // Firing with the mouse is a natural expectation once the cursor
                // aims; left click is an alias for the existing Space binding.
                canvas.addEventListener('mousedown', (e) => {
                    setMouseAimFromEvent(e.clientX, e.clientY);
                    if (e.button === 0) mouseFire = true;
                    else if (e.button === 2) mouseThrow = true;   // throw the blade
                });
                window.addEventListener('mouseup', (e) => {
                    if (e.button === 0) mouseFire = false;
                    else if (e.button === 2) mouseThrow = false;
                });
                // Losing the window mid-hold would otherwise leave the trigger stuck
                // down, exactly like the touch buttons torn down mid-press.
                window.addEventListener('blur', () => { mouseFire = false; mouseThrow = false; });
                canvas.addEventListener('contextmenu', (e) => e.preventDefault());
            }

            // The OS cursor is hidden while manually aiming in a fight — the drawn
            // crosshair replaces it — and restored for menus, auto-aim and touch.
            // Called every frame, so the style is only written when it changes.
            let lastAimCursor = null;
            function updateAimCursor() {
                if (!canvas) return;
                const inFight = canvas.style.display === 'block' && !gamePaused;
                const want = (inFight && isManualAimActive() && aimSource === 'mouse') ? 'none' : '';
                if (want === lastAimCursor) return;
                lastAimCursor = want;
                canvas.style.cursor = want;
            }

            function applyAutoAimSetting() {
                const btn = document.getElementById('autoAimBtn');
                if (btn) btn.textContent = autoAimEnabled ? '🎯 Auto-Aim: ON' : '🎯 Auto-Aim: OFF';
                updateAimCursor();
            }

            // ── WEAPON EMOJI MAP ───────────────────────────────────────
            const weaponEmoji = { lightsaber:'⚔️', darksaber:'🖤', blaster:'🔫', zap:'⚡', staff:'🪄', bowcaster:'🏹', wrench:'🔧', lightning:'🌩️', computer:'💻', minigun:'💥', beam:'🔆', guards:'🛡️', sniper:'🎯', vibroblade:'🗡️', flamethrower:'🔥', submachine:'🔫', unarmed:'✋', iceblast:'❄️', repulsor:'💠', webshooter:'🕸️', claws:'🦠', zeroenergy:'🌀', mjolnir:'🔨', laevateinn:'🗡️', icedagger:'🗡️', glock:'🔫', gammafists:'👊', thingfists:'👊', pantherclaws:'🐾', scimitar:'🗡️', grootfists:'🌳', stormbreaker:'🪓', lasercannon:'☄️', destroyergun:'🔆', bow:'🏹', dualglocks:'🔫', shield:'🛡️', sonictaser:'⚡', mongerfists:'👊', abomfists:'👊', gauntletfists:'👊', realitystaff:'🔮', antmanfists:'👊', antbite:'🐜', poisonspit:'☣️', quadblaster:'💥', hydrapistol:'🔫', katanas:'⚔️', skeletonsword:'🗡️', halloweenblaster:'🎃' };
            const factionEmoji = { heroes:'🔵', villains:'🔴', secret:'🟣' };


            /*  What the two faction headings say when no season view is on — the
             *  game’s own rosters, which is what the columns fall back to. Read by
             *  updateFactionHeadings() only in that case, which is exactly why a
             *  missing one is invisible until the seasons are switched off.      */
            const GALACTIC_FACTION_TITLES = {
                heroes:   'Grand Army & Heroes',
                villains: 'Sith & Separatists'
            };

            /*  ── THE MARVEL SEASON ────────────────────────────────────────────
             *  The same shape a content pack’s season has, and the same machinery drives
             *  two sides, and a toggle in the faction headings that swaps both columns
             *  over. Single season, so there is no table to index — add a second one
             *  here if that ever changes.
             *
             *  The season shipped free, with the toggle as the whole of the gate, so
             *  ownsAnyMarvelCharacter() is really asking "does the season have a cast"
             *  rather than "has the player paid" — and that still holds, because it is
             *  answered by the seventeen fighters who carry no secretUnlock.
             *
             *  Star-Lord is the exception and the only one: he carries a secretUnlock
             *  like a pack’s cast does, sits in the column as a locked hint button
             *  until he is bought, and changes nothing about the toggle. If a second
             *  paid Marvel fighter is ever added, this note is the thing to re-read —
             *  the moment the FREE cast could be empty, ownsAnyMarvelCharacter() is
             *  asking the wrong question and the toggle can vanish with fighters
             *  still listed behind it.                                               */
            const MARVEL_SEASON = {
                id: 'marvel',
                label: 'Marvel',
                // A `marvel: true` record in characters.secret is not enough on its
                // own — this is the list the two columns are actually built from, and
                // a fighter missing here simply never appears on the grid. validate.js
                // checks the two against each other for exactly that reason.
                // Black Panther sits here and not merely on the grid: avengerBackupPool()
                // reads this column directly rather than keeping a second list, so
                // adding him here is also what makes the Fury Sprite able to call him.
                // 'hulk' stays in this list and is filtered out downstream by
                // isCharacterRetired() rather than being struck from it — the same
                // way the vault treats everything else. 'bruce' takes his place in
                // the column, and reaching Hulk now means pressing Interact.
                heroes:   { title: 'The Avengers',           ids: ['ironman', 'spiderman', 'thor', 'bruce', 'hulk', 'thing', 'blackpanther', 'groot', 'rocket', 'starlord', 'fury', 'pepper', 'coulson', 'hill', 'hawkeye', 'widow', 'cap', 'peggy', 'bucky', 'eternity', 'antman', 'deadpool'] },
                // Retitled a second time, and for the same reason it was retitled for
                // Loki: the heading names what is in the column. 'Lies' was Loki alone,
                // and a stolen throne covers him and Killmonger both — which is the
                // whole of what Killmonger wants and most of what Loki has ever done.
                villains: { title: 'Symbiotes, Rings & Stolen Thrones', ids: ['venom', 'mandarin', 'loki', 'killmonger', 'laufey', 'stane', 'blonsky', 'redskull', 'ragnarok', 'thanos'] }
            };
            function marvelSeason() { return MARVEL_SEASON; }

            /*  ── THE HALLOWEEN SEASON ────────────────────────────────────────
             *  Built on MARVEL_SEASON's exact shape, so everything that already
             *  knows how to show a season — the two columns, the opponent screen,
             *  Surprise Me, the secret row standing down — shows this one simply
             *  by being handed it. The fighters live in characters.secret with
             *  `halloween: true`, the way the Marvel cast carries `marvel`, and
             *  validate.js checks the flag and this list against each other.
             *
             *  Four of the six are free with the toggle. Lord Treat and Lord Trick
             *  are earned, each by five round wins as the general below them — see
             *  HALLOWEEN_LORD_UNLOCKS. Neither is sold in the Shop: the general is
             *  the price.
             *
             *  The Halloween event (THE HALLOWEEN EVENT, further down) draws its
             *  good guys from the heroes column here, so a fighter added to it later
             *  is eligible for the event without its code having to learn his name.*/
            const HALLOWEEN_SEASON = {
                id: 'halloween',
                label: 'Halloween',
                heroes:   { title: 'The Bone Guard',   ids: ['skeleton', 'hawlo', 'lordtreat'] },
                villains: { title: 'The Burnt Legion', ids: ['burntskeleton', 'wheen', 'lordtrick'] }
            };
            function halloweenSeason() { return HALLOWEEN_SEASON; }

            // ── DIFFICULTY ─────────────────────────────────────────────
            let currentDifficulty = 'normal';
            const diffSettings = {
                easy:    { aiSpread: 0.85, aiSpeed: 0.55, hpMult: 0.8,  alliesCount: 2, blockChance: 0.25 },
                normal:  { aiSpread: 0.65, aiSpeed: 0.70, hpMult: 1.0,  alliesCount: 3, blockChance: 0.40 },
                legend:  { aiSpread: 0.15, aiSpeed: 1.05, hpMult: 1.45, alliesCount: 5, blockChance: 0.75 },
                hard:    { aiSpread: 0.25, aiSpeed: 0.90, hpMult: 1.25, alliesCount: 4, blockChance: 0.60 }
            };

            const cloneBackupArmy = {
                rex:    { unitId: '501st', name: '501st Trooper' },
                cody:   { unitId: '212th', name: '212th Trooper' },
                wolffe: { unitId: '104th', name: '104th Trooper' },
                bly:    { unitId: '327th', name: '327th Trooper' },
                gree:   { unitId: '41st', name: '41st Trooper' },
                fox:    { unitId: 'coruscant', name: 'Coruscant Trooper' },
                bacara: { unitId: '21st', name: '21st Marine' },
                neyo:   { unitId: '91st', name: '91st Trooper' },
                appo:   { unitId: '501st', name: '501st Trooper' },
                doom:   { unitId: '442nd', name: '442nd Trooper' },
                ponds:  { unitId: '187th', name: '187th Trooper' },
                thorn:  { unitId: 'coruscant', name: 'Coruscant Trooper' },
                ganch:  { unitId: '612th', name: '612th Trooper' },
                colt:   { unitId: 'rancor', name: 'Rancor ARC Trooper' },
                crane:  { unitId: '184th', name: '184th Trooper' },
                keeli:  { unitId: '52nd', name: '52nd Trooper' }
            };
            const cloneBackupLeaders = new Set(Object.keys(cloneBackupArmy));

            // Captains lead a battalion like the commanders do, but they answer to
            // one — so one fewer trooper answers the call.
            const cloneCaptains = new Set(['rex', 'keeli']);

            // How many troopers a clone leader brings in. Never fewer than one,
            // so the lowest difficulty still produces a squad.
            function battalionSize(baseId) {
                const ds = diffSettings[currentDifficulty];
                return Math.max(1, ds.alliesCount - (cloneCaptains.has(baseId) ? 1 : 0));
            }

            // Named clones who never held a command. They still belong to a
            // battalion — Fives, Jesse and Hardcase are all 501st — and calling for
            // backup means calling that battalion, not more of themselves.
            const cloneTrooperBattalion = {
                fives:    '501st',
                jesse:    '501st',
                hardcase: '501st'
            };

            // unitId -> the { unitId, name } pair every rank-and-file trooper of that
            // battalion is spawned from, so the squad a commander calls and the squad
            // one of his own troopers calls are named identically.
            const cloneUnitInfo = {};
            for (const info of Object.values(cloneBackupArmy)) cloneUnitInfo[info.unitId] = info;

            /** Which rank-and-file a clone calls in. Commanders and captains get their
             *  own battalion, a named trooper gets the battalion he serves in, and a
             *  rank-and-file trooper gets more of his own unit.
             *
             *  Returns null for a clone with no battalion on record. That case used to
             *  fall through to "spawn troopers named after me", which is how a wounded
             *  Hardcase called in a squad of Hardcases — each one a 50 HP copy carrying
             *  his characterId, so the roster's own named fighters were being duplicated
             *  as cannon fodder. Calling no one is the safe answer, and validate.js
             *  reports any clone that lands here so the gap does not stay silent. */
            function cloneBackupUnit(baseId) {
                if (cloneBackupLeaders.has(baseId)) return cloneBackupArmy[baseId];
                return cloneUnitInfo[cloneTrooperBattalion[baseId] || baseId] || null;
            }

            // Jedi Generals: maps a Jedi to the clone commander who serves under
            // them. When the Jedi calls for backup, that commander arrives
            // personally alongside two rank-and-file troopers of the battalion.
            const jediBackupArmy = {
                anakin:     'rex',
                obiwan:     'cody',
                ahsoka:     'rex',
                plokoan:    'wolffe',
                kiadimundi: 'bacara',
                aayla:      'bly',
                luminara:   'gree',
                yoda:       'gree',
                windu:      'ponds',
                mace_windu: 'ponds',
                shaakti:    'colt',
                jocastanu:  'fox'
            };
            const jediBackupLeaders = new Set(Object.keys(jediBackupArmy));

            // Who the dev menu's "Call for Backup" is offered to: Jedi Generals,
            // who call in the commander serving under them, and clone commanders
            // and captains, who call in their own battalion. Nobody outside the
            // Grand Army gets reinforcements — not the Empire, not the
            // Separatists, not the Rebellion. (Rank-and-file clones still round up
            // troopers on their own at low health; that is automatic, not a
            // button.)
            function canCallBackup(charId) {
                if (!charId) return false;
                return jediBackupLeaders.has(charId)
                    || cloneBackupLeaders.has(resolveCloneBaseId(charId));
            }

            // ── STARFIELD ──────────────────────────────────────────────
            const starLayers = [
                { stars: [], speed: 0.15, size: 0.8, count: 60,  alpha: 0.4 },
                { stars: [], speed: 0.35, size: 1.4, count: 40,  alpha: 0.65 },
                { stars: [], speed: 0.65, size: 2.0, count: 20,  alpha: 0.9 }
            ];
            function initStars() {
                starLayers.forEach(layer => {
                    layer.stars = [];
                    for (let i = 0; i < layer.count; i++) {
                        layer.stars.push({ x: Math.random() * canvasLogicalW, y: Math.random() * canvasLogicalH, twinkle: Math.random() * Math.PI * 2 });
                    }
                });
            }
            initStars();

            // ── GAME STATS ─────────────────────────────────────────────
            let killCount = 0;
            let gameStartTime = 0;
            let countdownActive = false;
            // Session token so delayed countdown / saber-hum timeouts from an old match
            // can't restart the timer or loop SFX after the player has left the fight.
            let battleSession = 0;
            let countdownTimerId = null;
            let saberHumTimerId = null;
            // Which blade's hum belongs to the fight in progress ('lightsaberHum' or
            // the Sith variant), or null when no saber is drawn. Pausing hard-stops
            // all SFX, so this is what closePauseMenu() brings back on resume.
            let activeSaberHumKey = null;
            let gameLoopId = 0; // declared early so stopBattleSystems can cancel safely
            let lastGameFrameTime = 0;
            let playerDamageDealt = 0;
            // Specials the player cast this match — Unibeam, Mk 1-5 fire, web
            // grenades, flame blast. Incremented in fireSpecial() and read only by
            // Stark's board, which is why it lives with the other match counters
            // rather than on the entity.
            let matchSpecialsUsed = 0;
            let playerShotsFired = 0;
            let playerHitsLanded = 0;
            /** Round clock counts down with game simulation time (same rAF as gameplay), not wall-clock setInterval — avoids “frozen canvas, running timer” when the tab is throttled or the main thread stalls.
             *  Despite the name it is a ROUND clock: every round gets the full three
             *  minutes. It used to be one clock for the whole series, set only when a
             *  series began, and that was an exploit — once it reached 0:00 every
             *  later round started already expired and was decided on its first frame,
             *  both fighters at full health, and a tie went to the player. Free series
             *  wins, Speed Demon, flawless contracts and win streaks for doing nothing.
             *  The name stays because the HUD and the results code read it. */
            let seriesTimeRemaining = 180;
            const SERIES_SECONDS = 180;

            // ── SERIES / ROUND TRACKING ────────────────────────────────
            let playerWins = 0;
            let enemyWins = 0;
            const SERIES_WINS_NEEDED = 3; // best of 5
            let isNextRound = false;
            let seriesPlayerCharId = null;
            let seriesEnemyCharId = null;

            // ── ARENA DEFINITIONS ──────────────────────────────────────
            // Declared up here rather than beside the arena-button wiring further
            // down: several setup-time helpers read it, and they run well before
            // this script reaches the button code.
            let currentArena = 'space';

            const ARENAS = {
                space: {
                    bg: (w, h, _tickScale) => {
                        const grad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, Math.max(w,h)*0.7);
                        grad.addColorStop(0, '#111827'); grad.addColorStop(1, '#030712');
                        ctx.fillStyle = grad; ctx.fillRect(0,0,w,h);
                    },
                    grid: 'rgba(255,255,255,0.025)',
                    coverColor: '#334455', coverBorder: '#4a6a8a'
                },
                deathstar: {
                    bg: (w, h, _tickScale) => {
                        ctx.fillStyle = '#0d0d0d'; ctx.fillRect(0,0,w,h);
                        // Trench lines
                        ctx.strokeStyle = 'rgba(80,80,80,0.18)'; ctx.lineWidth = 1;
                        for (let i = 0; i < w; i += 60) { ctx.beginPath(); ctx.moveTo(i,0); ctx.lineTo(i,h); ctx.stroke(); }
                        for (let i = 0; i < h; i += 60) { ctx.beginPath(); ctx.moveTo(0,i); ctx.lineTo(w,i); ctx.stroke(); }
                        // Superlaser glow
                        const g = ctx.createRadialGradient(w*0.15, h*0.5, 5, w*0.15, h*0.5, 80);
                        g.addColorStop(0,'rgba(0,200,80,0.12)'); g.addColorStop(1,'rgba(0,0,0,0)');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);
                    },
                    grid: 'rgba(0,200,80,0.04)',
                    coverColor: '#2a2a2a', coverBorder: '#555'
                },
                mustafar: {
                    bg: (w, h, _tickScale) => {
                        ctx.fillStyle = '#1a0a00'; ctx.fillRect(0,0,w,h);
                    },
                    grid: 'rgba(255,80,0,0.04)',
                    coverColor: '#3a1a00', coverBorder: '#7a3300'
                },
                hoth: {
                    bg: (w, h, tickScale = 1) => {
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#c8e4f4'); g.addColorStop(1,'#e8f4fc');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);
                        // Snow drift at bottom
                        const drift = ctx.createLinearGradient(0,h*0.8,0,h);
                        drift.addColorStop(0,'rgba(255,255,255,0)'); drift.addColorStop(1,'rgba(255,255,255,0.35)');
                        ctx.fillStyle = drift; ctx.fillRect(0,0,w,h);
                        // Blizzard particles (static snowflakes)
                        if (!ARENAS.hoth._snow) {
                            ARENAS.hoth._snow = Array.from({length:60},()=>({x:Math.random()*canvasLogicalW,y:Math.random()*canvasLogicalH,r:Math.random()*2+0.5}));
                        }
                        ARENAS.hoth._snow.forEach(s => {
                            s.x = (s.x - 0.6 * tickScale + w) % w;
                            ctx.fillStyle='rgba(255,255,255,0.55)';
                            ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2); ctx.fill();
                        });
                    },
                    grid: 'rgba(100,160,220,0.07)',
                    coverColor: '#c0d8ee', coverBorder: '#7ab0d0'
                },
                coruscant: {
                    bg: (w, h, _tickScale) => {
                        ctx.fillStyle = '#05080f'; ctx.fillRect(0,0,w,h);
                        // City light windows
                        if (!ARENAS.coruscant._windows) {
                            ARENAS.coruscant._windows = Array.from({length:120},()=>({
                                x:Math.random()*canvasLogicalW, y:Math.random()*canvasLogicalH,
                                w:Math.random()*6+2, h:Math.random()*4+1,
                                color:`hsl(${Math.random()*60+30},80%,${Math.random()*30+50}%)`,
                                blink: Math.random()*5
                            }));
                        }
                        const t = Date.now()*0.001;
                        ARENAS.coruscant._windows.forEach(win => {
                            const alpha = 0.4 + 0.35 * Math.sin(t * win.blink);
                            ctx.globalAlpha = alpha;
                            ctx.fillStyle = win.color;
                            ctx.fillRect(win.x, win.y, win.w, win.h);
                        });
                        ctx.globalAlpha = 1;
                        // Speeder lane glow streaks
                        const laneY = [h*0.3, h*0.6];
                        laneY.forEach(ly => {
                            const gLane = ctx.createLinearGradient(0,ly-6,0,ly+6);
                            gLane.addColorStop(0,'rgba(255,220,80,0)'); gLane.addColorStop(0.5,'rgba(255,220,80,0.06)'); gLane.addColorStop(1,'rgba(255,220,80,0)');
                            ctx.fillStyle = gLane; ctx.fillRect(0,ly-6,w,12);
                        });
                    },
                    grid: 'rgba(255,200,50,0.04)',
                    coverColor: '#1a1a2e', coverBorder: '#3a3a5e'
                },
                moseisley: {
                    bg: (w, h, _tickScale) => {
                        // Cantina interior - warm tan/brown tones
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#3d2b1f'); g.addColorStop(1,'#2a1d15');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);
                        
                        // Ambient warm light from center
                        const center = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, Math.max(w,h)*0.6);
                        center.addColorStop(0,'rgba(255,200,100,0.08)'); center.addColorStop(1,'rgba(0,0,0,0)');
                        ctx.fillStyle = center; ctx.fillRect(0,0,w,h);
                        
                        // Subtle wall texture
                        ctx.strokeStyle = 'rgba(180,140,80,0.03)';
                        ctx.lineWidth = 1;
                        for (let i = 0; i < w; i += 40) { ctx.beginPath(); ctx.moveTo(i,0); ctx.lineTo(i,h); ctx.stroke(); }
                        for (let i = 0; i < h; i += 40) { ctx.beginPath(); ctx.moveTo(0,i); ctx.lineTo(w,i); ctx.stroke(); }
                    },
                    grid: 'rgba(255,200,100,0.03)',
                    coverColor: '#5a4030', coverBorder: '#8a6a50'
                },
                naboo: {
                    bg: (w, h, _tickScale) => {
                        // Theed Palace reactor core — deep purples and gold
                        const g = ctx.createLinearGradient(0, 0, 0, h);
                        g.addColorStop(0, '#1a0a2e');
                        g.addColorStop(0.5, '#2d1b4e');
                        g.addColorStop(1, '#0e0618');
                        ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);

                        // Central reactor glow
                        const reactor = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, h * 0.4);
                        reactor.addColorStop(0, 'rgba(180, 100, 255, 0.18)');
                        reactor.addColorStop(0.5, 'rgba(100, 40, 180, 0.08)');
                        reactor.addColorStop(1, 'rgba(0, 0, 0, 0)');
                        ctx.fillStyle = reactor; ctx.fillRect(0, 0, w, h);

                        // Gold trim pillars on edges
                        ctx.strokeStyle = 'rgba(200, 170, 80, 0.12)';
                        ctx.lineWidth = 2;
                        for (let i = 0; i < w; i += 80) {
                            ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, h); ctx.stroke();
                        }
                        // Horizontal energy ring lines
                        const t = Date.now() * 0.001;
                        for (let ring = 0; ring < 3; ring++) {
                            const ry = h * 0.2 + ring * h * 0.3 + Math.sin(t * 0.5 + ring) * 8;
                            ctx.strokeStyle = `rgba(160, 80, 255, ${0.06 + ring * 0.02})`;
                            ctx.lineWidth = 1;
                            ctx.beginPath(); ctx.moveTo(0, ry); ctx.lineTo(w, ry); ctx.stroke();
                        }
                        // Plasma energy pulses rising from bottom
                        if (!ARENAS.naboo._pulses) {
                            ARENAS.naboo._pulses = Array.from({ length: 8 }, (_, i) => ({
                                x: (i / 8) * w + 30,
                                y: Math.random() * h,
                                speed: Math.random() * 0.4 + 0.2,
                                alpha: Math.random() * 0.3 + 0.05
                            }));
                        }
                        ARENAS.naboo._pulses.forEach(p => {
                            p.y -= p.speed;
                            if (p.y < -10) p.y = h + 10;
                            ctx.fillStyle = `rgba(180, 100, 255, ${p.alpha})`;
                            ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2); ctx.fill();
                        });
                    },
                    grid: 'rgba(180, 100, 255, 0.04)',
                    coverColor: '#2d1040', coverBorder: '#7b4fa0'
                },
                kashyyyk: {
                    bg: (w, h, _tickScale) => {
                        // Wookiee forest - deep greens and browns
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#1a3d1a'); g.addColorStop(0.5,'#0d2b0d'); g.addColorStop(1,'#051a05');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);
                        
                        // Tree trunks
                        ctx.fillStyle = '#3d2817';
                        for (let i = 0; i < w; i += 120) {
                            ctx.fillRect(i + 10, h*0.1, 25, h*0.8);
                        }
                        
                        // Foliage glow
                        const foliage = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, Math.max(w,h)*0.5);
                        foliage.addColorStop(0,'rgba(50,150,50,0.15)'); foliage.addColorStop(1,'rgba(0,0,0,0)');
                        ctx.fillStyle = foliage; ctx.fillRect(0,0,w,h);
                    },
                    grid: 'rgba(50,150,50,0.04)',
                    coverColor: '#2d4a2d', coverBorder: '#4a7a4a'
                },
                mandalore: {
                    bg: (w, h, tickScale = 1) => {
                        // Mandalore's surface, scarred by the Great Purge — rusty, ember-lit wasteland
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#3a1f14'); g.addColorStop(0.5,'#2a160e'); g.addColorStop(1,'#150a06');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);

                        // Distant ember glow on the horizon
                        const embers = ctx.createRadialGradient(w*0.5, h*0.88, 0, w*0.5, h*0.88, w*0.6);
                        embers.addColorStop(0,'rgba(255,110,40,0.12)'); embers.addColorStop(1,'rgba(0,0,0,0)');
                        ctx.fillStyle = embers; ctx.fillRect(0,0,w,h);

                        // Ruined durasteel silhouettes
                        ctx.fillStyle = 'rgba(20,12,8,0.6)';
                        for (let i = 0; i < w; i += 140) {
                            ctx.fillRect(i + 15, h*0.05, 30, h*0.35);
                        }

                        // Drifting ash
                        if (!ARENAS.mandalore._ash) {
                            ARENAS.mandalore._ash = Array.from({length:50},()=>({x:Math.random()*canvasLogicalW,y:Math.random()*canvasLogicalH,r:Math.random()*1.5+0.5}));
                        }
                        ARENAS.mandalore._ash.forEach(s => {
                            s.y = (s.y + 0.4 * tickScale) % h;
                            ctx.fillStyle='rgba(190,160,140,0.35)';
                            ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2); ctx.fill();
                        });
                    },
                    grid: 'rgba(255,120,60,0.05)',
                    coverColor: '#4a352a', coverBorder: '#8a6a40'
                },
                cloudcity: {
                    bg: (w, h, tickScale = 1) => {
                        // Bespin sky — banded gas-giant clouds in dusk orange/pink
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#ffb27a'); g.addColorStop(0.45,'#ff8f6b'); g.addColorStop(1,'#d96a6a');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);

                        // Drifting cloud bands
                        if (!ARENAS.cloudcity._bands) {
                            ARENAS.cloudcity._bands = Array.from({length:8},(_,i)=>({y: (i+0.5)/8*canvasLogicalH, x: Math.random()*canvasLogicalW, speed: Math.random()*0.3+0.1}));
                        }
                        ARENAS.cloudcity._bands.forEach(b => {
                            b.x = (b.x - b.speed * tickScale + w*1.5) % (w*1.5) - w*0.25;
                            ctx.fillStyle = 'rgba(255,255,255,0.10)';
                            ctx.fillRect(b.x, b.y - 4, w*0.5, 8);
                        });

                        // Platform railing silhouette at the base
                        ctx.fillStyle = 'rgba(200,160,140,0.25)';
                        ctx.fillRect(0, h*0.92, w, h*0.08);
                    },
                    grid: 'rgba(255,200,180,0.05)',
                    coverColor: '#c9a08a', coverBorder: '#e8c4a8'
                },
                endor: {
                    bg: (w, h, _tickScale) => {
                        // Forest moon — dappled dusk canopy, lighter/warmer than Kashyyyk
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#3a4a2a'); g.addColorStop(0.5,'#2a3a1f'); g.addColorStop(1,'#1a2412');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);

                        // Giant redwood trunks
                        ctx.fillStyle = '#5a3a20';
                        for (let i = 0; i < w; i += 150) {
                            ctx.fillRect(i + 20, 0, 34, h);
                        }

                        // Dappled sunlight shafts through canopy
                        const shaft = ctx.createRadialGradient(w*0.7, 0, 0, w*0.7, 0, h*0.9);
                        shaft.addColorStop(0,'rgba(255,220,140,0.14)'); shaft.addColorStop(1,'rgba(0,0,0,0)');
                        ctx.fillStyle = shaft; ctx.fillRect(0,0,w,h);
                    },
                    grid: 'rgba(140,200,100,0.05)',
                    coverColor: '#3a5228', coverBorder: '#6a8a48'
                },
                petranaki: {
                    bg: (w, h, tickScale = 1) => {
                        // Petranaki Arena — the first circle, dusty rust-colored gladiator pit
                        const g = ctx.createLinearGradient(0,0,0,h);
                        g.addColorStop(0,'#5a2f1f'); g.addColorStop(0.55,'#4a2415'); g.addColorStop(1,'#2e150c');
                        ctx.fillStyle = g; ctx.fillRect(0,0,w,h);

                        // Stone pillar silhouettes ringing the arena
                        ctx.fillStyle = 'rgba(40,20,12,0.55)';
                        for (let i = 0; i < w; i += 130) {
                            ctx.fillRect(i, h*0.08, 20, h*0.3);
                        }

                        // Drifting dust haze
                        if (!ARENAS.petranaki._dust) {
                            ARENAS.petranaki._dust = Array.from({length:45},()=>({x:Math.random()*canvasLogicalW,y:Math.random()*canvasLogicalH,r:Math.random()*1.8+0.6}));
                        }
                        ARENAS.petranaki._dust.forEach(s => {
                            s.x = (s.x + 0.35 * tickScale) % w;
                            ctx.fillStyle='rgba(220,160,110,0.3)';
                            ctx.beginPath(); ctx.arc(s.x,s.y,s.r,0,Math.PI*2); ctx.fill();
                        });
                    },
                    grid: 'rgba(255,140,80,0.05)',
                    coverColor: '#6a3a24', coverBorder: '#a5623a'
                },


                /*  Asgard — the Golden City on its shelf of rock, with the Bifrost
                 *  coming down behind it and the void underneath everything.
                 *
                 *  Built against Wakanda deliberately, because they are the season's
                 *  two city arenas and they must not read as the same painting in a
                 *  different palette. Wakanda is a dusk skyline on a savanna and its
                 *  horizon is HIGH — a third down — so the city is a band along the
                 *  top. Asgard's horizon is LOW, because the thing worth looking at
                 *  here is above the city rather than the city itself: the realm sits
                 *  in open space, so most of the canvas is sky and bridge.
                 *
                 *  The Bifrost is the one thing in the painting that moves. It is a
                 *  band of spectrum on a slow shimmer, and it is the arena's whole
                 *  identity — everything else is gold and dark. Cached like every
                 *  other arena's scenery; see ARENA_SCENERY_CACHES.               */
                asgard: {
                    bg: (w, h, tickScale = 1) => {
                        const horizon = h * 0.62;

                        // Deep space above, warming as it comes down to the realm.
                        const sky = ctx.createLinearGradient(0, 0, 0, horizon);
                        sky.addColorStop(0,    '#05060f');
                        sky.addColorStop(0.55, '#101a3a');
                        sky.addColorStop(1,    '#2b2450');
                        ctx.fillStyle = sky; ctx.fillRect(0, 0, w, horizon);

                        // Stars. Generated once — a field that re-rolls every frame
                        // reads as static rather than as space.
                        if (!ARENAS.asgard._stars) {
                            ARENAS.asgard._stars = Array.from({ length: 90 }, () => ({
                                x: Math.random() * canvasLogicalW,
                                y: Math.random() * canvasLogicalH * 0.62,
                                r: Math.random() * 1.3 + 0.3,
                                a: Math.random() * 0.5 + 0.25
                            }));
                        }
                        ARENAS.asgard._stars.forEach(s => {
                            ctx.globalAlpha = s.a;
                            ctx.fillStyle = '#dfe8ff';
                            ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill();
                        });
                        ctx.globalAlpha = 1;

                        /*  The Bifrost. Drawn as one thick diagonal of stacked
                         *  spectrum strips rather than a canvas gradient, because a
                         *  gradient blends the bands into a smear and the bridge has
                         *  to read as distinct colours side by side.
                         *
                         *  The shimmer is a phase offset on each strip's alpha, so it
                         *  travels along the bridge instead of pulsing all at once. */
                        ARENAS.asgard._shimmer = (ARENAS.asgard._shimmer || 0) + 0.018 * tickScale;
                        const BIFROST = ['#ff4d6d', '#ff9a3c', '#ffe14d', '#5ddb7a',
                                         '#4dc9ff', '#6d6dff', '#b86dff'];
                        ctx.save();
                        ctx.translate(w * 0.74, horizon);
                        ctx.rotate(-0.62);
                        BIFROST.forEach((col, i) => {
                            const band = 7;
                            ctx.globalAlpha = 0.22 + 0.16 * Math.sin(ARENAS.asgard._shimmer + i * 0.6);
                            ctx.fillStyle = col;
                            ctx.fillRect(-4, -(i + 1) * band, h * 1.5, band);
                        });
                        ctx.globalAlpha = 1;
                        ctx.restore();

                        // The palace: organ-pipe shafts, which is the one silhouette
                        // that reads as Asgard rather than as any other gold city.
                        if (!ARENAS.asgard._spires) {
                            ARENAS.asgard._spires = Array.from({ length: 11 }, (_, i) => ({
                                x: canvasLogicalW * (0.10 + i * 0.075) + Math.random() * 10,
                                w: 12 + Math.random() * 16,
                                hh: canvasLogicalH * (0.10 + Math.random() * 0.16)
                            }));
                        }
                        ARENAS.asgard._spires.forEach(p => {
                            const top = horizon - p.hh;
                            // Deliberately dimmer than the cover pillars in front of
                            // them. At full gold the palace and the destructible cover
                            // were the same colour and the same shape, and a player
                            // cannot be asked to work out which columns stop a bolt.
                            // Scenery loses the contrast fight on purpose.
                            const gold = ctx.createLinearGradient(0, top, 0, horizon);
                            gold.addColorStop(0, '#8a6f35');
                            gold.addColorStop(1, '#2e2411');
                            ctx.fillStyle = gold;
                            ctx.fillRect(p.x, top, p.w, p.hh);
                            // Rounded cap — the pipes are domed, not cut flat.
                            ctx.beginPath();
                            ctx.arc(p.x + p.w / 2, top, p.w / 2, Math.PI, 0);
                            ctx.fillStyle = '#9c7f42';
                            ctx.fill();
                        });

                        // The terrace the fight happens on.
                        const ground = ctx.createLinearGradient(0, horizon, 0, h);
                        ground.addColorStop(0, '#3a2d16');
                        ground.addColorStop(1, '#17120a');
                        ctx.fillStyle = ground; ctx.fillRect(0, horizon, w, h - horizon);

                        // One bright line where the terrace meets the sky, so the
                        // horizon is an edge rather than a fade.
                        ctx.strokeStyle = 'rgba(247,217,140,0.35)';
                        ctx.lineWidth = 1.5;
                        ctx.beginPath(); ctx.moveTo(0, horizon); ctx.lineTo(w, horizon); ctx.stroke();
                    },
                    grid: 'rgba(240,198,106,0.05)',
                    coverColor: '#6b4f1e', coverBorder: '#f0c66a'
                },
                wakanda: {
                    bg: (w, h, _tickScale) => {
                        // Wakanda — the Golden City at dusk, seen from the terraces
                        // above it. Three bands: an equatorial sky, the skyline, and
                        // the savanna the fight actually happens on. The horizon sits
                        // high — a third of the way down rather than halfway — because
                        // the whole canvas is playfield, not just the ground: anything
                        // painted above that line is scenery fighters still walk over,
                        // so the city is a band along the top rather than half the map.
                        //
                        // The violet in the ground is the vibranium, and it is the
                        // only thing in the painting that moves. Everything else is
                        // generated once and cached, the way Coruscant's windows and
                        // Petranaki's dust are — see invalidateArenaCaches(), which
                        // has to drop both of this arena's caches or a resize leaves
                        // the city standing in the wrong place.
                        const horizon = h * 0.34;

                        const sky = ctx.createLinearGradient(0, 0, 0, horizon);
                        sky.addColorStop(0,    '#1b1038');
                        sky.addColorStop(0.55, '#5a2f4e');
                        sky.addColorStop(1,    '#d98a4a');
                        ctx.fillStyle = sky; ctx.fillRect(0, 0, w, horizon);

                        // Low sun sitting just off the spires
                        const sun = ctx.createRadialGradient(w * 0.30, horizon * 0.92, 0, w * 0.30, horizon * 0.92, h * 0.30);
                        sun.addColorStop(0,    'rgba(255,214,130,0.45)');
                        sun.addColorStop(0.45, 'rgba(255,170,90,0.12)');
                        sun.addColorStop(1,    'rgba(255,170,90,0)');
                        ctx.fillStyle = sun; ctx.fillRect(0, 0, w, horizon);

                        // The city: tapered shafts under a spire, which is the one
                        // silhouette that reads as Wakandan rather than as Coruscant
                        // with warmer lights.
                        if (!ARENAS.wakanda._towers) {
                            ARENAS.wakanda._towers = Array.from({ length: 16 }, (_, i) => ({
                                x: (i / 16) * canvasLogicalW + Math.random() * 28,
                                w: 18 + Math.random() * 34,
                                hh: canvasLogicalH * (0.07 + Math.random() * 0.17),
                                spire: 10 + Math.random() * 26,
                                wins: Array.from({ length: 3 + Math.floor(Math.random() * 4) }, () => ({
                                    dx: Math.random(), dy: Math.random(), r: Math.random() * 1.5 + 0.7
                                }))
                            }));
                        }
                        ARENAS.wakanda._towers.forEach(t => {
                            const top = horizon - t.hh;
                            const halfB = t.w / 2, halfT = t.w * 0.31;
                            ctx.fillStyle = '#2a1a2e';
                            ctx.beginPath();
                            ctx.moveTo(t.x - halfB, horizon);
                            ctx.lineTo(t.x - halfT, top);
                            ctx.lineTo(t.x + halfT, top);
                            ctx.lineTo(t.x + halfB, horizon);
                            ctx.closePath(); ctx.fill();
                            ctx.strokeStyle = '#d9b45a'; ctx.lineWidth = 1.4;
                            ctx.beginPath(); ctx.moveTo(t.x, top); ctx.lineTo(t.x, top - t.spire); ctx.stroke();
                            ctx.fillStyle = 'rgba(255,206,120,0.75)';
                            t.wins.forEach(win => {
                                // Windows follow the taper, so none of them floats
                                // off the side of a narrowing shaft.
                                const spanHalf = (halfT + (halfB - halfT) * win.dy) * 0.7;
                                ctx.beginPath();
                                ctx.arc(t.x + (win.dx - 0.5) * 2 * spanHalf, top + win.dy * t.hh, win.r, 0, Math.PI * 2);
                                ctx.fill();
                            });
                        });

                        const land = ctx.createLinearGradient(0, horizon, 0, h);
                        land.addColorStop(0,    '#6b4a2a');
                        land.addColorStop(0.35, '#8a6132');
                        land.addColorStop(1,    '#56391f');
                        ctx.fillStyle = land; ctx.fillRect(0, horizon, w, h - horizon);

                        // Vibranium seams. Same two-pass stroke the Zero Point's
                        // cracks use — a wide glowing line with a hot filament down
                        // the middle — and each breathes on its own offset so the
                        // ground glimmers unevenly rather than pulsing as one sheet.
                        if (!ARENAS.wakanda._seams) {
                            ARENAS.wakanda._seams = Array.from({ length: 7 }, (_, i) => {
                                let x = Math.random() * canvasLogicalW;
                                let y = canvasLogicalH * (0.52 + Math.random() * 0.44);
                                const pts = [{ x, y }];
                                for (let s = 0; s < 5; s++) {
                                    x += (Math.random() - 0.35) * 72;
                                    y += (Math.random() - 0.5) * 26;
                                    pts.push({ x, y });
                                }
                                return { pts, seed: i };
                            });
                        }
                        const t = Date.now() * 0.001;
                        ctx.save();
                        ctx.lineCap = 'round';
                        ARENAS.wakanda._seams.forEach(seam => {
                            const glow = 0.30 + 0.22 * Math.sin(t * 1.1 + seam.seed * 0.8);
                            ctx.globalAlpha = glow;
                            ctx.strokeStyle = '#7b5cc4';
                            ctx.lineWidth = 2.4;
                            if (effectsEnabled()) { ctx.shadowBlur = 10; ctx.shadowColor = '#c3b5e8'; }
                            ctx.beginPath();
                            ctx.moveTo(seam.pts[0].x, seam.pts[0].y);
                            for (let s = 1; s < seam.pts.length; s++) ctx.lineTo(seam.pts[s].x, seam.pts[s].y);
                            ctx.stroke();
                            ctx.globalAlpha = glow * 0.8;
                            ctx.strokeStyle = '#e6dcff';
                            ctx.lineWidth = 0.8;
                            ctx.shadowBlur = 0;
                            ctx.stroke();
                        });
                        ctx.restore();
                    },
                    grid: 'rgba(123,92,196,0.05)',
                    coverColor: '#7a5c3a', coverBorder: '#d9b45a'
                }
            };

            // ── DESTRUCTIBLE COVER ─────────────────────────────────────
            let coverObjects = [];

            // Arena-specific layout configs: each entry is { x (0-1), y (0-1), w, h, shape }
            // shape: 'rect' | 'L' | 'T' — affects how the cover is drawn
            const ARENA_LAYOUTS = {
                // Space: Scattered asteroid debris — diamond cluster
                space: [
                    { x:0.20, y:0.25, w:55, h:20 }, { x:0.80, y:0.25, w:55, h:20 },
                    { x:0.50, y:0.20, w:20, h:55 },
                    { x:0.30, y:0.55, w:20, h:55 }, { x:0.70, y:0.55, w:20, h:55 },
                    { x:0.50, y:0.75, w:70, h:18 }
                ],
                // Cloud City: Carbon-freezing chamber gantries — open catwalks
                cloudcity: [
                    { x:0.30, y:0.30, w:18, h:65 }, { x:0.70, y:0.30, w:18, h:65 },
                    { x:0.50, y:0.45, w:70, h:18 },
                    { x:0.25, y:0.70, w:60, h:18 }, { x:0.75, y:0.70, w:60, h:18 }
                ],
                // Endor: Redwood trunks — dense, staggered trunk cover
                endor: [
                    { x:0.18, y:0.30, w:26, h:75 }, { x:0.82, y:0.30, w:26, h:75 },
                    { x:0.45, y:0.55, w:26, h:65 }, { x:0.60, y:0.20, w:26, h:65 },
                    { x:0.30, y:0.75, w:55, h:18 }
                ],
                // Petranaki Arena: the first circle — gladiator-pit ring formation
                petranaki: [
                    { x:0.20, y:0.35, w:22, h:22 }, { x:0.80, y:0.35, w:22, h:22 },
                    { x:0.20, y:0.65, w:22, h:22 }, { x:0.80, y:0.65, w:22, h:22 },
                    { x:0.50, y:0.50, w:65, h:18 }
                ],
                // Wakanda: stepped terraces above and below, and the middle left
                // deliberately bare. The centre of this map is the challenge ground
                // and it is also where the Border Shields close — cover inside that
                // box would let someone sit in the one square the arena is built to
                // make dangerous, which is the same reason the Zero Point's middle
                // is empty.
                // Asgard: two colonnades down the flanks and the bridge mouth left
                // open. The lane the Bifrost Beam rakes along is the middle of the
                // map, so the cover sits off it — stand in the clear and the arena
                // eventually charges you for it.
                asgard: [
                    { x:0.16, y:0.26, w:18, h:62 }, { x:0.84, y:0.26, w:18, h:62 },
                    { x:0.16, y:0.74, w:18, h:62 }, { x:0.84, y:0.74, w:18, h:62 },
                    { x:0.36, y:0.18, w:74, h:18 }, { x:0.64, y:0.82, w:74, h:18 },
                    { x:0.50, y:0.50, w:22, h:22 }
                ],
                wakanda: [
                    { x:0.18, y:0.24, w:80, h:18 }, { x:0.82, y:0.24, w:80, h:18 },
                    { x:0.30, y:0.40, w:18, h:58 }, { x:0.70, y:0.40, w:18, h:58 },
                    { x:0.14, y:0.58, w:18, h:58 }, { x:0.86, y:0.58, w:18, h:58 },
                    { x:0.38, y:0.82, w:70, h:18 }, { x:0.62, y:0.82, w:70, h:18 }
                ]
            };

            function spawnCover() {
                coverObjects = [];
                const w = canvasLogicalW, h = canvasLogicalH;
                const layout = ARENA_LAYOUTS[currentArena] || ARENA_LAYOUTS.space;
                layout.forEach(pos => {
                    coverObjects.push({
                        x: pos.x * w, y: pos.y * h,
                        w: pos.w, h: pos.h,
                        hp: 80, maxHp: 80, alive: true,
                        hitFlash: 0,
                        shape: pos.shape || 'rect'
                    });
                });
            }

            function drawCovers() {
                const arenaStyle = ARENAS[currentArena] || ARENAS.space;
                const isHoth = currentArena === 'hoth';
                const isMustafar = currentArena === 'mustafar';
                const isDeathStar = currentArena === 'deathstar';
                const isCantina = currentArena === 'moseisley';
                const isNaboo = currentArena === 'naboo';
                const isCoruscant = currentArena === 'coruscant';
                
                // Cache time for animations to avoid repeated Date.now() calls
                const animTime = Date.now();

                coverObjects.forEach(c => {
                    if (!c.alive) return;
                    const pct = c.hp / c.maxHp;
                    ctx.save();
                    const flashAlpha = animTime < c.hitFlash ? 0.75 : 1;
                    ctx.globalAlpha = flashAlpha;

                    // Arena-specific styling
                    let fillStyle = arenaStyle.coverColor;
                    let strokeStyle = arenaStyle.coverBorder;
                    let cornerR = 3;
                    let linePattern = null;

                    if (isHoth) {
                        // Ice/snow bunker — light blue with frost
                        fillStyle = `rgba(180, 210, 235, ${0.82 * pct + 0.18})`;
                        strokeStyle = '#7ab0d0';
                        cornerR = 2;
                    } else if (isMustafar) {
                        // Molten rock platforms — dark orange/brown
                        const heat = 0.5 + 0.5 * Math.sin(animTime * 0.003 + c.x * 0.01);
                        fillStyle = `rgb(${Math.round(60 + heat*30)}, ${Math.round(25 + heat*10)}, 5)`;
                        strokeStyle = `rgba(255, ${Math.round(80 + heat*80)}, 0, 0.8)`;
                        cornerR = 1;
                    } else if (isDeathStar) {
                        // Metal grid panels
                        fillStyle = '#222';
                        strokeStyle = '#555';
                        linePattern = [8, 4];
                        cornerR = 0;
                    } else if (isCantina) {
                        // Round tables/pillars — warm tan
                        fillStyle = '#5a3a28';
                        strokeStyle = '#9a6a50';
                        cornerR = c.w === c.h ? c.w/2 : 5; // circular for square shapes
                    } else if (isNaboo) {
                        // Plasma-lit walkways — purple tint
                        const pulse = 0.5 + 0.5 * Math.sin(animTime * 0.002 + c.x * 0.01);
                        fillStyle = `rgba(45, 18, 68, 0.9)`;
                        strokeStyle = `rgba(${Math.round(140 + pulse*60)}, ${Math.round(60 + pulse*20)}, 255, 0.9)`;
                        cornerR = 4;
                    } else if (isCoruscant) {
                        // City building facades
                        fillStyle = '#1a1a2e';
                        strokeStyle = '#4a4a7e';
                        linePattern = [12, 6];
                        cornerR = 2;
                    }

                    // Crack effect at low HP
                    if (pct < 0.4) {
                        ctx.setLineDash([3, 4]);
                    }
                    if (linePattern && pct >= 0.4) {
                        ctx.setLineDash(linePattern);
                    }

                    // Removed shadowBlur for performance

                    // Draw cover body
                    if (isDeathStar) {
                        // Flat rectangle for Death Star trench walls
                        ctx.fillStyle = fillStyle;
                        ctx.strokeStyle = strokeStyle;
                        ctx.lineWidth = 2;
                        ctx.fillRect(c.x - c.w/2, c.y - c.h/2, c.w, c.h);
                        ctx.strokeRect(c.x - c.w/2, c.y - c.h/2, c.w, c.h);
                        // Panel rivets
                        ctx.setLineDash([]);
                        ctx.fillStyle = '#444';
                        const rows = Math.max(1, Math.floor(c.h / 20));
                        const cols = Math.max(1, Math.floor(c.w / 20));
                        for (let rr = 0; rr < rows; rr++) {
                            for (let cc = 0; cc < cols; cc++) {
                                ctx.beginPath();
                                ctx.arc(c.x - c.w/2 + 10 + cc * 20, c.y - c.h/2 + 10 + rr * 20, 2, 0, Math.PI*2);
                                ctx.fill();
                            }
                        }
                    } else if (isCantina && c.w === c.h) {
                        // Circular pillar/table
                        ctx.fillStyle = fillStyle;
                        ctx.strokeStyle = strokeStyle;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.arc(c.x, c.y, c.w/2, 0, Math.PI*2);
                        ctx.fill(); ctx.stroke();
                        // Table top ring
                        ctx.strokeStyle = '#c89a70';
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.arc(c.x, c.y, c.w/2 - 4, 0, Math.PI*2);
                        ctx.stroke();
                    } else {
                        ctx.fillStyle = fillStyle;
                        ctx.strokeStyle = strokeStyle;
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.roundRect(c.x - c.w/2, c.y - c.h/2, c.w, c.h, cornerR);
                        ctx.fill(); ctx.stroke();

                        // Arena-specific details
                        if (isHoth && pct >= 0.4) {
                            // Ice crystal lines
                            ctx.setLineDash([]);
                            ctx.strokeStyle = 'rgba(200,230,255,0.35)';
                            ctx.lineWidth = 1;
                            ctx.beginPath();
                            ctx.moveTo(c.x - c.w/2 + 4, c.y - c.h/2 + 4);
                            ctx.lineTo(c.x + c.w/4, c.y + c.h/4);
                            ctx.stroke();
                        }
                        if (isCoruscant && pct >= 0.4) {
                            // Window lights
                            ctx.setLineDash([]);
                            const wLit = Math.floor(c.w / 8);
                            for (let wi = 0; wi < wLit; wi++) {
                                ctx.fillStyle = `rgba(255,220,80,${0.3 + Math.sin(Date.now()*0.002 + wi)*0.15})`;
                                ctx.fillRect(c.x - c.w/2 + 4 + wi * 7, c.y - c.h/2 + 4, 4, 3);
                            }
                        }
                    }

                    ctx.setLineDash([]);

                    // HP bar
                    const barY = c.y - c.h/2 - 8;
                    ctx.shadowBlur = 0;
                    ctx.fillStyle = 'rgba(0,0,0,0.5)';
                    ctx.fillRect(c.x - c.w/2, barY, c.w, 4);
                    const hpColor = pct > 0.5 ? '#00cc55' : pct > 0.25 ? '#ffaa00' : '#ff3333';
                    ctx.fillStyle = hpColor;
                    ctx.fillRect(c.x - c.w/2, barY, c.w * pct, 4);

                    ctx.restore();
                });
            }

            function checkBulletCoverCollision(bullet) {
                if (bullet.returnable && bullet.returning) return false;
                for (const c of coverObjects) {
                    if (!c.alive) continue;
                    const hw = c.w/2 + 4, hh = c.h/2 + 4;
                    if (bullet.x > c.x-hw && bullet.x < c.x+hw && bullet.y > c.y-hh && bullet.y < c.y+hh) {
                        c.hp -= bullet.damage * 0.6;
                        c.hitFlash = Date.now() + 80;
                        spawnImpactParticles(bullet.x, bullet.y, bullet.color, 5);
                        if (c.hp <= 0) {
                            c.alive = false;
                            triggerScreenShake(5, 10);
                            for (let k = 0; k < 12; k++) {
                                const a = Math.random()*Math.PI*2, sp = Math.random()*3+1;
                                if (deathParticles.length < MAX_DEATH_PARTICLES) deathParticles.push({x:c.x,y:c.y,dx:Math.cos(a)*sp,dy:Math.sin(a)*sp,life:28,maxLife:28,color:'#888',r:Math.random()*3+1});
                            }
                        }
                        return true;
                    }
                }
                return false;
            }

            function checkEntityCoverCollision(e, tickScale) {
                for (const c of coverObjects) {
                    if (!c.alive) continue;
                    const hw = c.w/2 + CHARACTER_SIZE, hh = c.h/2 + CHARACTER_SIZE;
                    if (e.x > c.x-hw && e.x < c.x+hw && e.y > c.y-hh && e.y < c.y+hh) {
                        // Push entity out of cover
                        const overlapX = (e.x > c.x) ? (c.x+hw - e.x) : -(e.x - (c.x-hw));
                        const overlapY = (e.y > c.y) ? (c.y+hh - e.y) : -(e.y - (c.y-hh));
                        if (Math.abs(overlapX) < Math.abs(overlapY)) e.x += overlapX * 0.4;
                        else e.y += overlapY * 0.4;
                        const damp = Math.pow(0.2, tickScale);
                        e.vx *= damp; e.vy *= damp;
                    }
                }
            }

            // ── AI TAKING COVER ────────────────────────────────────────
            // A hurt AI used to walk straight at the cover's centre point. It
            // can never reach that point: checkEntityCoverCollision() pushes it
            // back out of the block every tick, so it ended up pinned against
            // the nearest face, walking into the wall forever. And because
            // that branch outranks strafing, nothing else ever moved it, and
            // its health never climbs back over the threshold that sent it
            // there — it stood frozen for the rest of the round.
            //
            // Now it heads for the face *away* from its target, steps around
            // a corner when the block is in the way, holds there for a short
            // stint, then goes back to fighting for a while before it is
            // allowed to hide again. A watchdog drops the plan if it stops
            // making progress, so no geometry can pin it again.
            const AI_COVER_HOLD_MS = 2200;   // longest it hides in one go
            const AI_COVER_BREAK_MS = 3500;  // then fights before hiding again
            const AI_COVER_STALL_MS = 900;   // no progress this long = give up

            function coverHideSpot(c, target) {
                const hw = c.w/2 + CHARACTER_SIZE + 6, hh = c.h/2 + CHARACTER_SIZE + 6;
                let ux = c.x - target.x, uy = c.y - target.y;
                const len = Math.hypot(ux, uy) || 1;
                ux /= len; uy /= len;
                // Where the ray from the target through the block leaves it.
                const t = Math.min(ux ? hw / Math.abs(ux) : Infinity, uy ? hh / Math.abs(uy) : Infinity);
                return {
                    x: Math.max(CHARACTER_SIZE, Math.min(canvasLogicalW - CHARACTER_SIZE, c.x + ux * t)),
                    y: Math.max(CHARACTER_SIZE, Math.min(canvasLogicalH - CHARACTER_SIZE, c.y + uy * t))
                };
            }

            // Does the segment a→b pass through the block (grown by the body)?
            function segmentCrossesCover(ax, ay, bx, by, c) {
                const hw = c.w/2 + CHARACTER_SIZE - 1, hh = c.h/2 + CHARACTER_SIZE - 1;
                let t0 = 0, t1 = 1;
                const dx = bx - ax, dy = by - ay;
                const clip = (p, q) => {
                    if (p === 0) return q >= 0;
                    const r = q / p;
                    if (p < 0) { if (r > t1) return false; if (r > t0) t0 = r; }
                    else       { if (r < t0) return false; if (r < t1) t1 = r; }
                    return true;
                };
                return clip(-dx, ax - (c.x - hw)) && clip(dx, (c.x + hw) - ax)
                    && clip(-dy, ay - (c.y - hh)) && clip(dy, (c.y + hh) - ay) && t0 < t1;
            }

            /** The corner of c that gets e to (tx, ty) by the shorter trip. */
            function coverCornerToward(e, c, tx, ty) {
                const cw = c.w/2 + CHARACTER_SIZE + 4, ch = c.h/2 + CHARACTER_SIZE + 4;
                let goal = { x: tx, y: ty }, best = Infinity;
                for (const [sx, sy] of [[1, 1], [1, -1], [-1, 1], [-1, -1]]) {
                    const kx = c.x + sx * cw, ky = c.y + sy * ch;
                    if (segmentCrossesCover(e.x, e.y, kx, ky, c)) continue;
                    const trip = Math.hypot(kx - e.x, ky - e.y) + Math.hypot(tx - kx, ty - ky);
                    if (trip < best) { best = trip; goal = { x: kx, y: ky }; }
                }
                return goal;
            }

            /** Closing on a target with a block in between had the same flaw as
             *  hiding did: walk straight at it, get pinned on the face. When the
             *  nearest block in the way is close, this hands back the corner to
             *  go round instead; otherwise null, and the AI walks as it did. */
            function aiCoverDetour(e, tx, ty) {
                let hit = null, nearest = Infinity;
                for (const c of coverObjects) {
                    if (!c.alive) continue;
                    const d = Math.hypot(c.x - e.x, c.y - e.y) - Math.max(c.w, c.h) / 2;
                    if (d > 60 || d >= nearest) continue;
                    if (!segmentCrossesCover(e.x, e.y, tx, ty, c)) continue;
                    nearest = d; hit = c;
                }
                return hit ? coverCornerToward(e, hit, tx, ty) : null;
            }

            /** Moves e toward a hiding spot behind c. Returns false when it
             *  should not (or can no longer) hide, so the caller falls through
             *  to ordinary movement. */
            function aiTakeCover(e, c, target, moveSpeed, tickScale, now) {
                if (e.coverRef !== c) {
                    e.coverRef = c;
                    e.coverSince = now;
                    e.coverAnchorX = e.x; e.coverAnchorY = e.y;
                    e.coverProgressAt = now;
                }
                const spot = coverHideSpot(c, target);
                const hidden = Math.hypot(spot.x - e.x, spot.y - e.y) < 10;
                // Progress is ground actually covered, not distance to the spot:
                // the way round a corner starts by moving away from it.
                if (hidden || Math.hypot(e.x - e.coverAnchorX, e.y - e.coverAnchorY) > 6) {
                    e.coverAnchorX = e.x; e.coverAnchorY = e.y;
                    e.coverProgressAt = now;
                }
                if (now - e.coverProgressAt > AI_COVER_STALL_MS || now - e.coverSince > AI_COVER_HOLD_MS) {
                    e.coverRef = null;
                    e.coverBreakUntil = now + AI_COVER_BREAK_MS;
                    return false;
                }
                if (hidden) return true;

                // Straight there, or round the corner that makes the shorter trip.
                const goal = segmentCrossesCover(e.x, e.y, spot.x, spot.y, c)
                           ? coverCornerToward(e, c, spot.x, spot.y) : spot;
                const gd = Math.hypot(goal.x - e.x, goal.y - e.y) || 1;
                const step = Math.min(moveSpeed * tickScale, gd);
                e.x += (goal.x - e.x) / gd * step;
                e.y += (goal.y - e.y) / gd * step;
                return true;
            }

            // ── ARENA HAZARDS ──────────────────────────────────────────
            // The thirteen arenas used to be wallpaper: ARENAS supplied a
            // background painter and ARENA_LAYOUTS a set of cover rectangles, and
            // that was the whole of it. Mustafar had a comment about a "lava
            // crossing" that was really just three blocks. Every arena played
            // identically, which meant twelve of them were art rather than design.
            //
            // Rather than thirteen bespoke mechanics, there are four primitives
            // configured per arena. Four systems to get right instead of thirteen,
            // and adding an arena is a data entry rather than new code:
            //
            //   zone     a region that damages, ignites or slows whoever stands in
            //            it. Lava, tar, tide.
            //   sweeper  a body that crosses the arena on a cycle, hitting and
            //            shoving whatever it catches. Speeders, logs, beasts.
            //   barrier  a rectangle that switches on and off, blocking bolts and
            //            bodies while lit. Blast doors, Naboo's plasma shields.
            //   wind     a directional push on everything, wandering over time.
            //            Blizzards, ash storms, updrafts.
            //
            // Hazards are deliberately symmetrical: they have no team and hurt the
            // player and the AI on identical terms. An arena should change how a
            // fight goes, not who wins it.
            let hazards = [];
            let hazardWind = { x: 0, y: 0, angle: 0, targetAngle: 0, nextShiftAt: 0 };
            // Off switch for the whole system, read by spawnHazards(). No settings
            // entry yet — it exists so hazards can be disabled in one place while
            // they are tuned, and so a future toggle has something to bind to.
            let hazardsEnabled = true;
            // Own alive-sweep buffer: updateHazards runs inside update(), which is
            // already iterating aliveScratch, and the scratch buffers explicitly
            // must not be nested.
            const hazardScratch = [];

            // Fractional coordinates, so a hazard sits in the same place relative
            // to the arena however large the window is — matching ARENA_LAYOUTS.
            const ARENA_HAZARDS = {
                // Zero-g: nothing here is anchored, so everything drifts.
                space: { kind: 'wind', strength: 0.055, shiftMs: 5200, label: 'Zero-G Drift' },
                // Blast doors on a slow cycle — the trench opens and closes.
                deathstar: { kind: 'barrier', label: 'Blast Doors', color: '#ff3b3b',
                    onMs: 3400, offMs: 3000, offsetMs: 0,
                    rects: [ { x:0.36, y:0.50, w:22, h:300 }, { x:0.64, y:0.50, w:22, h:300 } ] },
                // The lava the arena is named for finally burns.
                mustafar: { kind: 'zone', label: 'Lava', color: '#ff5a1e', ignite: true,
                    damage: 5, intervalMs: 420,
                    circles: [ { x:0.12, y:0.18, r:78 }, { x:0.88, y:0.82, r:78 },
                               { x:0.50, y:0.12, r:58 }, { x:0.50, y:0.88, r:58 } ] },
                hoth: { kind: 'wind', strength: 0.10, shiftMs: 3400, label: 'Blizzard' },
                // Lane traffic: fast, frequent, and it comes in straight lines you
                // can learn.
                coruscant: { kind: 'sweeper', label: 'Speeder Traffic', color: '#ffd24a',
                    damage: 14, radius: 15, speed: 7.4, spawnMs: 2100, axis: 'h', knockback: 9 },
                moseisley: { kind: 'sweeper', label: 'Runaway Loader', color: '#d4a574',
                    damage: 12, radius: 20, speed: 3.1, spawnMs: 3400, axis: 'any', knockback: 11 },
                // The Duel of the Fates shields. Fast cycle, so they genuinely
                // interrupt a duel rather than decorating it.
                naboo: { kind: 'barrier', label: 'Plasma Shields', color: '#8fd4ff',
                    onMs: 2300, offMs: 2100, offsetMs: 1100,
                    rects: [ { x:0.30, y:0.50, w:20, h:340 }, { x:0.50, y:0.50, w:20, h:340 },
                             { x:0.70, y:0.50, w:20, h:340 } ] },
                // Slows instead of damaging — the only zone that costs tempo
                // rather than health, which is worse for a kiter than for a brawler.
                kashyyyk: { kind: 'zone', label: 'Root Tangle', color: '#4a7a4a',
                    damage: 0, slow: 0.45, intervalMs: 400,
                    circles: [ { x:0.22, y:0.30, r:82 }, { x:0.78, y:0.70, r:82 },
                               { x:0.50, y:0.50, r:66 } ] },
                mandalore: { kind: 'wind', strength: 0.085, shiftMs: 4200, label: 'Ash Storm' },
                endor: { kind: 'sweeper', label: 'Log Trap', color: '#8fbf6a',
                    damage: 18, radius: 22, speed: 4.6, spawnMs: 4200, axis: 'v', knockback: 16 },
                petranaki: { kind: 'sweeper', label: 'Arena Beast', color: '#d98a4a',
                    damage: 24, radius: 30, speed: 2.7, spawnMs: 5200, axis: 'any', knockback: 18 },
                cloudcity: { kind: 'wind', strength: 0.115, shiftMs: 3000, label: 'Updrafts' },

                /*  The bridge firing across the terrace. A sweeper rather than a
                 *  zone because the Bifrost is a thing that ARRIVES — it should
                 *  cross the arena and be gone, not sit in a corner being avoided.
                 *
                 *  Sits between Endor’s log trap (18 at speed 4.6) and Petranaki’s
                 *  beast (24 at 2.7): harder than the log and faster than the beast,
                 *  on a long enough timer that it is an event rather than weather.  */
                asgard: { kind: 'sweeper', label: 'Bifrost Beam', color: '#8fd0ff',
                    damage: 22, radius: 26, speed: 5.2, spawnMs: 4600, axis: 'h', knockback: 14 },

                wakanda: { kind: 'barrier', label: 'Border Shields', color: '#6fe3c4',
                    onMs: 2600, offMs: 2200, offsetMs: 900,
                    rects: [ { x:0.50, y:0.30, w:260, h:20 }, { x:0.50, y:0.70, w:260, h:20 },
                             { x:0.36, y:0.50, w:20, h:230 }, { x:0.64, y:0.50, w:20, h:230 } ] },
                // The anomaly itself. Not a zone — a zone would grind you down for
                // standing in it, and this does something far worse and far more
                // interesting: it hurts you once and then puts you somewhere else
                // entirely. Losing your position mid-duel is the real cost.
                //
                // radiusPct is a fraction of the SMALLER world dimension so the
                // circle stays circular and stays proportionate on any window.

            };

            // What the Zero Point becomes once the event is over. Not a new arena —
            // the same key, the same button, a different anomaly. Beating Geno takes
            // the place apart, and the singularity at the middle of it stops merely
            // moving you and starts throwing you out of the fight entirely.
            //
            // 50 damage instead of 20, and instead of relocating you inside the
            // arena it drops you into a different one against a different opponent.
            // See zeroPointBanish().
            // Wider than the stable one as well as more dangerous. The Zero Point is
            // always there and it is always big: after the event it takes up a
            // noticeably larger share of the field, so fighting around it is a
            // constant consideration rather than an occasional mistake. Still well
            // under the third-of-the-arena ceiling validate.js enforces.
            const UNSTABLE_ZERO_POINT_HAZARD = {
                kind: 'singularity', label: 'The Unstable Zero Point', color: '#ff5bd1',
                x: 0.5, y: 0.5, radiusPct: 0.17,
                damage: 50, cooldownMs: 1800, unstable: true
            };

            function currentHazardConfig() {
                // The unstable anomaly is what the Zero Point becomes AFTER the
                // event, and only outside it. During a run it is always the ordinary
                // one, whatever the save says.
                //
                // gameUnlocks.zeroEventCleared is a legacy save flag: the Zero Event
                // is gone, so nothing sets it any more. A save that cleared the event
                // while it existed still gets the anomaly it earned.
                if (currentArena === 'zeropoint' && gameUnlocks.zeroEventCleared) {
                    return UNSTABLE_ZERO_POINT_HAZARD;
                }
                return ARENA_HAZARDS[currentArena] || null;
            }

            /** Arena scenery is generated once and cached against the size it was
             *  built for, so anything that changes that size — or swaps which arena
             *  is being painted at all — has to drop the lot. Extracted from
             *  resizeCanvas() when the Unstable Zero Point gained the ability to
             *  borrow another arena's ground mid-fight and became the second caller. */
            /*  Which arenas cache generated scenery, and into which fields. A
             *  table rather than a run of assignments because a content pack can
             *  add arenas of its own, and every entry is checked for existence
             *  before it is cleared — the pack may simply not be loaded.       */
            const ARENA_SCENERY_CACHES = {
                hoth:       ['_snow'],
                coruscant:  ['_windows'],
                naboo:      ['_pulses'],
                mandalore:  ['_ash'],
                petranaki:  ['_dust'],
                // Two caches, and both have to go: the skyline is positioned off
                // the old width and the seams are drawn at absolute points in the
                // old ground, so keeping either leaves the city and the vibranium
                // standing somewhere the arena no longer is.
                wakanda:    ['_towers', '_seams'],
                // The starfield and the palace are both placed off the old canvas
                // size; the shimmer is a running phase and is fine to keep.
                asgard:     ['_stars', '_spires']
            };

            function invalidateArenaCaches() {
                Object.keys(ARENA_SCENERY_CACHES).forEach(key => {
                    const arena = ARENAS[key];
                    if (!arena) return;
                    ARENA_SCENERY_CACHES[key].forEach(field => { arena[field] = null; });
                });
            }

            /** Which world's ground is currently showing through the Zero Point's
             *  floor, or null for its own void. Read by the arena's bg painter. */
            let zeroPointTerrain = null;

            /** Touching the unstable anomaly, after the event, throws the player out
             *  of the fight entirely: a genuinely different arena, a different
             *  opponent, and whatever health the 50 damage left them with.
             *
             *  This is the AFTER state, and it is a real relocation — you do not end
             *  up somewhere that still has a Zero Point in the middle of it, you end
             *  up somewhere else. Changing the ground underfoot without moving is
             *

             *  Implemented as an immediate re-setup, because the arena really does
             *  change: world scale, cover placement and hazard geometry are all
             *  decided during setup and read every frame afterwards, and setupGame()
             *  is the one path that gets all of that right. matchOpts.carryHp is what
             *  makes it a continuation rather than a fresh start. */
            function unstableZeroPointBanish() {
                if (!mainPlayer || !pCharData) return;
                const carried = Math.max(1, Math.round(mainPlayer.health));
                const playerId = pCharData.id;

                const arenaKeys = playableArenaKeys().filter(a => a !== 'zeropoint');
                if (!arenaKeys.length) return;
                const nextArena = arenaKeys[Math.floor(Math.random() * arenaKeys.length)];

                const nextOpp = pickUnstableOpponent();
                if (!nextOpp) return;

                currentArena = nextArena;
                syncArenaSelection();
                showAnnouncement(
                    `The Zero Point spits you out somewhere else. ${nextOpp.name} is already here.`,
                    '#ff5bd1', 4500, `🌀 ${String(nextArena).toUpperCase()}`, 100, true);

                // Deferred out of the frame rather than called straight from the
                // hazard loop. setupGame() cancels the pending animation frame and
                // starts a countdown that queues its own — but the gameLoop call
                // that led here is still mid-flight and queues one too when it
                // finishes. Both land in the single gameLoopId, one gets orphaned,
                // and a later match can end up with two loops running against the
                // same entities. Letting the frame finish first means setupGame is
                // the only thing scheduling anything.
                const banishFrom = battleSession;
                setTimeout(() => {
                    if (banishFrom !== battleSession) return;
                    setupGame(playerId, nextOpp.id, { carryHp: carried });
                }, 0);
            }

            function pickUnstableOpponent() {
                const playerId = pCharData ? pCharData.id : null;
                const currentId = mainEnemy ? mainEnemy.characterId : null;
                const pool = [...characters.heroes, ...characters.villains, ...characters.secret]
                    .filter(c => c.id !== playerId && c.id !== currentId && isCharacterAvailableAsOpponent(c));
                return pool.length ? pool[Math.floor(Math.random() * pool.length)] : null;
            }

            /** Every arena the player may currently be sent to or pick.
             *
             *  Cluster Coast comes off the list once the Zero Event is cleared. It is
             *  Cluster's beach and Cluster is one of the fighters the event ends, so
             *  the place goes with him — the same logic that retires a character,
             *  applied to a location. Kept in ARENAS rather than deleted so old saves
             *  and match history that reference it still resolve. */
            function playableArenaKeys() {
                return Object.keys(ARENAS).filter(a => !isArenaRetired(a));
            }

            function isArenaRetired(key) {
                // The Zero Point goes the same way, and for the same reason: Thanos
                // snaps the place out of existence, so it stops being somewhere you
                // can be sent or choose. Retired, not deleted — ARENAS.zeropoint and
                // every painter, hazard and terrain rule it owns stay exactly as they
                // are, so the Zero Event's own stages still run there and old saves
                // and match history that name it still resolve.
                if (key === 'zeropoint' && snapHasHappened()) return true;
                return false;
            }

            /** Build the live hazard state for the current arena. Called from the
             *  same place as spawnCover(), so a hazard's lifetime is exactly one
             *  round and nothing has to be torn down by hand. */
            function spawnHazards() {
                hazards = [];
                hazardWind.x = 0; hazardWind.y = 0;
                hazardWind.angle = Math.random() * Math.PI * 2;
                hazardWind.targetAngle = hazardWind.angle;
                hazardWind.nextShiftAt = 0;
                if (!hazardsEnabled) return;
                // The Halloween event promises that only an enemy can kill a team
                // fighter, and Endor's log trap would make a liar of it.
                if (halloweenRun) return;

                const cfg = currentHazardConfig();
                if (!cfg) return;
                const w = canvasLogicalW, h = canvasLogicalH;

                if (cfg.kind === 'zone') {
                    for (const c of cfg.circles) {
                        hazards.push({ kind: 'zone', cfg, x: c.x * w, y: c.y * h, r: c.r, phase: Math.random() * Math.PI * 2 });
                    }
                } else if (cfg.kind === 'barrier') {
                    cfg.rects.forEach((r, i) => {
                        hazards.push({
                            kind: 'barrier', cfg, x: r.x * w, y: r.y * h, w: r.w, h: r.h,
                            // Staggering by index means the doors do not all shut at
                            // once, so there is always a way through if you look.
                            phaseOffset: (cfg.offsetMs || 0) * i
                        });
                    });
                } else if (cfg.kind === 'sweeper') {
                    hazards.push({ kind: 'sweeper', cfg, active: false, nextSpawnAt: 0, x: 0, y: 0, dx: 0, dy: 0, spin: 0 });
                } else if (cfg.kind === 'wind') {
                    hazards.push({ kind: 'wind', cfg });
                } else if (cfg.kind === 'singularity') {
                    hazards.push({
                        kind: 'singularity', cfg,
                        x: cfg.x * w, y: cfg.y * h,
                        r: cfg.radiusPct * Math.min(w, h),
                        // Purely decorative arcs inside the core, generated once so
                        // the fracture pattern is stable rather than boiling.
                        arcs: Array.from({ length: 7 }, (_, i) => ({
                            a: (i / 7) * Math.PI * 2,
                            rr: 0.32 + (i % 4) * 0.16,
                            speed: (i % 2 ? 1 : -1) * (0.12 + (i % 3) * 0.06)
                        }))
                    });
                }
            }

            /** True while a barrier is lit and solid. */
            function barrierIsUp(hz, now) {
                const cfg = hz.cfg;
                const period = cfg.onMs + cfg.offMs;
                const t = ((now + hz.phaseOffset) % period + period) % period;
                return t < cfg.onMs;
            }

            /** How close a barrier is to changing state, 0..1. Drives the warning
             *  flash — a barrier that snaps on with no tell is just a cheap hit. */
            function barrierPhase(hz, now) {
                const cfg = hz.cfg;
                const period = cfg.onMs + cfg.offMs;
                const t = ((now + hz.phaseOffset) % period + period) % period;
                return t < cfg.onMs ? t / cfg.onMs : (t - cfg.onMs) / cfg.offMs;
            }

            /** Movement multiplier from any slowing zone the entity is standing in.
             *  1 when clear. Mirrors swingMoveScale() so the movement code reads
             *  the same way for both. */
            function hazardMoveScale(e) {
                if (!hazards.length) return 1;
                let scale = 1;
                for (const hz of hazards) {
                    if (hz.kind !== 'zone' || !hz.cfg.slow) continue;
                    if (Math.hypot(e.x - hz.x, e.y - hz.y) <= hz.r) scale = Math.min(scale, hz.cfg.slow);
                }
                return scale;
            }

            /** Does a solid barrier block this point? Used by both the bullet and
             *  the entity collision paths. */
            function hazardBlocksPoint(x, y, pad, now) {
                for (const hz of hazards) {
                    if (hz.kind !== 'barrier' || !barrierIsUp(hz, now)) continue;
                    const hw = hz.w / 2 + pad, hh = hz.h / 2 + pad;
                    if (x > hz.x - hw && x < hz.x + hw && y > hz.y - hh && y < hz.y + hh) return hz;
                }
                return null;
            }

            function updateHazards(tickScale) {
                if (!hazards.length) return;
                const now = frameNow;
                const w = canvasLogicalW, h = canvasLogicalH;
                const alive = collectAlive(hazardScratch);

                for (const hz of hazards) {
                    if (hz.kind === 'zone') {
                        const cfg = hz.cfg;
                        for (const e of alive) {
                            if (Math.hypot(e.x - hz.x, e.y - hz.y) > hz.r) continue;
                            if (!cfg.damage) continue;
                            if (now < (e.hazardNextTickAt || 0)) continue;
                            e.hazardNextTickAt = now + cfg.intervalMs;
                            applyHazardDamage(e, cfg.damage, cfg.color);
                            if (cfg.ignite) igniteBurn(e, null);
                        }
                    } else if (hz.kind === 'sweeper') {
                        const cfg = hz.cfg;
                        if (!hz.active) {
                            if (!hz.nextSpawnAt) hz.nextSpawnAt = now + cfg.spawnMs;
                            if (now >= hz.nextSpawnAt) launchSweeper(hz, w, h);
                            continue;
                        }
                        hz.x += hz.dx * tickScale;
                        hz.y += hz.dy * tickScale;
                        hz.spin += 0.06 * tickScale;
                        // Off the far edge — park it until the next pass.
                        const m = cfg.radius + 60;
                        if (hz.x < -m || hz.x > w + m || hz.y < -m || hz.y > h + m) {
                            hz.active = false;
                            hz.nextSpawnAt = now + cfg.spawnMs;
                            continue;
                        }
                        for (const e of alive) {
                            if (Math.hypot(e.x - hz.x, e.y - hz.y) > cfg.radius + CHARACTER_SIZE) continue;
                            if (now < (e.hazardNextTickAt || 0)) continue;
                            e.hazardNextTickAt = now + 600;
                            applyHazardDamage(e, cfg.damage, cfg.color);
                            const a = Math.atan2(e.y - hz.y, e.x - hz.x);
                            e.vx += Math.cos(a) * cfg.knockback;
                            e.vy += Math.sin(a) * cfg.knockback;
                        }
                    } else if (hz.kind === 'singularity') {
                        const cfg = hz.cfg;
                        for (const e of alive) {
                            if (Math.hypot(e.x - hz.x, e.y - hz.y) > hz.r + CHARACTER_SIZE * 0.5) continue;
                            if (now < (e.hazardNextTickAt || 0)) continue;
                            e.hazardNextTickAt = now + cfg.cooldownMs;
                            applyHazardDamage(e, cfg.damage, cfg.color);
                            // Damage first, then displacement: an entity killed by
                            // the touch should die at the anomaly, not be flung
                            // across the map as a corpse.
                            if (!e.isAlive) continue;
                            // The stable anomaly moves you inside the arena. The
                            // unstable one moves you to a different arena against a
                            // different opponent — and only ever the player, because
                            // rebuilding the match around an AI that wandered into
                            // the middle would throw the player out of a fight they
                            // were not standing in.
                            if (cfg.unstable && e === mainPlayer) {
                                unstableZeroPointBanish();
                                return;
                            }
                            banishToRandomSpot(e, hz);
                        }
                    } else if (hz.kind === 'wind') {
                        const cfg = hz.cfg;
                        if (now >= hazardWind.nextShiftAt) {
                            hazardWind.nextShiftAt = now + cfg.shiftMs;
                            hazardWind.targetAngle = Math.random() * Math.PI * 2;
                        }
                        // Ease toward the new heading so the arena never yanks the
                        // fighters sideways without warning.
                        const diff = Math.atan2(Math.sin(hazardWind.targetAngle - hazardWind.angle),
                                                Math.cos(hazardWind.targetAngle - hazardWind.angle));
                        hazardWind.angle += diff * Math.min(1, 0.02 * tickScale);
                        hazardWind.x = Math.cos(hazardWind.angle) * cfg.strength;
                        hazardWind.y = Math.sin(hazardWind.angle) * cfg.strength;
                        for (const e of alive) {
                            e.x += hazardWind.x * tickScale;
                            e.y += hazardWind.y * tickScale;
                        }
                    }
                }

                // Barriers shove anyone caught in the doorway clear as they close,
                // rather than trapping them inside a solid object.
                for (const e of alive) {
                    const hz = hazardBlocksPoint(e.x, e.y, CHARACTER_SIZE, now);
                    if (!hz) continue;
                    const hw = hz.w / 2 + CHARACTER_SIZE, hh = hz.h / 2 + CHARACTER_SIZE;
                    const ox = (e.x > hz.x) ? (hz.x + hw - e.x) : -(e.x - (hz.x - hw));
                    const oy = (e.y > hz.y) ? (hz.y + hh - e.y) : -(e.y - (hz.y - hh));
                    if (Math.abs(ox) < Math.abs(oy)) e.x += ox;
                    else e.y += oy;
                }
            }

            /** Hazard damage has no attacker, so it cannot go through
             *  applyStatusAndDamage — that reads projectile.owner for knockback,
             *  damage credit and the Boom Boom splash. This is the smaller path:
             *  health, the flash, a number, and the achievement flag. */
            function applyHazardDamage(e, amount, color) {
                if (!e || !e.isAlive) return;
                if (e === mainPlayer && invincibilityEnabled) return;
                if (isInvulnerable(e, frameNow)) { spawnDodgeNegation(e); return; }
                e.updateHealth(amount);
                e.hitFlashUntil = frameNow + 90;
                if (e.team === 'player' && e.isMainEntity) playerTookDamage = true;
                spawnHitSparks(e.x, e.y, color, 8);
                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: e.x + (Math.random() - 0.5) * 18, y: e.y - CHARACTER_SIZE - 8,
                        text: Math.round(amount), life: 40, maxLife: 40, dy: -1.1,
                        color: color, glow: color
                    });
                }
            }

            /** Throw an entity to a random point elsewhere on the map.
             *
             *  Rejection-sampled rather than computed, because "somewhere valid" is
             *  a set of awkward constraints — outside the anomaly (or it would
             *  re-trigger and chain), clear of solid cover (or the push-out would
             *  immediately shove it somewhere arbitrary anyway), and inside the
             *  bounds. Sampling until one sticks is both shorter and easier to
             *  trust than solving it. The final fallback is the far corner from the
             *  anomaly, which is always legal.
             *
             *  Momentum is cleared: arriving at speed in a random direction reads
             *  as being flung, when the anomaly is meant to feel like being
             *  *placed* somewhere else. */
            function banishToRandomSpot(e, hz) {
                const w = canvasLogicalW, h = canvasLogicalH;
                const margin = CHARACTER_SIZE + 12;
                // Far enough out that the arrival is never inside the core's pull.
                const clearOfCore = hz.r + CHARACTER_SIZE * 2.5;

                let nx = null, ny = null;
                for (let attempt = 0; attempt < 60; attempt++) {
                    const cx = margin + Math.random() * (w - margin * 2);
                    const cy = margin + Math.random() * (h - margin * 2);
                    if (Math.hypot(cx - hz.x, cy - hz.y) < clearOfCore) continue;
                    let blocked = false;
                    for (const c of coverObjects) {
                        if (!c.alive) continue;
                        if (cx > c.x - c.w / 2 - CHARACTER_SIZE && cx < c.x + c.w / 2 + CHARACTER_SIZE &&
                            cy > c.y - c.h / 2 - CHARACTER_SIZE && cy < c.y + c.h / 2 + CHARACTER_SIZE) { blocked = true; break; }
                    }
                    if (blocked) continue;
                    nx = cx; ny = cy;
                    break;
                }
                if (nx == null) {
                    nx = e.x < hz.x ? w - margin : margin;
                    ny = e.y < hz.y ? h - margin : margin;
                }

                spawnHitSparks(e.x, e.y, '#a855f7', 16);
                spawnImpactParticles(e.x, e.y, '#7c3aed', 10);
                e.x = nx; e.y = ny;
                e.vx = 0; e.vy = 0;
                // A swing committed on one side of the map must not land on the
                // other — the blade went with the fighter, the cut did not.
                cancelMeleeSwing(e);
                spawnHitSparks(nx, ny, '#d8b4fe', 18);
                spawnImpactParticles(nx, ny, '#7c3aed', 12);
                if (e.isMainEntity) triggerScreenShake(6, 12);
            }

            function launchSweeper(hz, w, h) {
                const cfg = hz.cfg;
                let axis = cfg.axis;
                if (axis === 'any') axis = Math.random() < 0.5 ? 'h' : 'v';
                const m = cfg.radius + 40;
                if (axis === 'h') {
                    const fromLeft = Math.random() < 0.5;
                    hz.x = fromLeft ? -m : w + m;
                    hz.y = h * (0.15 + Math.random() * 0.7);
                    hz.dx = (fromLeft ? 1 : -1) * cfg.speed;
                    hz.dy = 0;
                } else {
                    const fromTop = Math.random() < 0.5;
                    hz.x = w * (0.15 + Math.random() * 0.7);
                    hz.y = fromTop ? -m : h + m;
                    hz.dx = 0;
                    hz.dy = (fromTop ? 1 : -1) * cfg.speed;
                }
                hz.active = true;
                hz.spin = 0;
            }

            function drawHazards() {
                if (!hazards.length) return;
                const now = frameNow;
                for (const hz of hazards) {
                    const cfg = hz.cfg;
                    if (hz.kind === 'zone') {
                        const pulse = 0.5 + 0.5 * Math.sin(now / 520 + hz.phase);
                        ctx.save();
                        const grad = ctx.createRadialGradient(hz.x, hz.y, hz.r * 0.15, hz.x, hz.y, hz.r);
                        grad.addColorStop(0, cfg.color);
                        grad.addColorStop(1, 'rgba(0,0,0,0)');
                        ctx.globalAlpha = cfg.damage ? 0.30 + 0.14 * pulse : 0.20 + 0.08 * pulse;
                        ctx.fillStyle = grad;
                        ctx.beginPath(); ctx.arc(hz.x, hz.y, hz.r, 0, Math.PI * 2); ctx.fill();
                        ctx.globalAlpha = 0.5;
                        ctx.strokeStyle = cfg.color;
                        ctx.lineWidth = 2;
                        ctx.setLineDash([7, 7]);
                        ctx.lineDashOffset = -now / 45;
                        ctx.beginPath(); ctx.arc(hz.x, hz.y, hz.r, 0, Math.PI * 2); ctx.stroke();
                        ctx.restore();
                    } else if (hz.kind === 'barrier') {
                        const up = barrierIsUp(hz, now);
                        const phase = barrierPhase(hz, now);
                        // Telegraph: the last quarter of the "off" phase flashes so
                        // a closing door can be read and beaten.
                        const arming = !up && phase > 0.75;
                        ctx.save();
                        if (up) {
                            ctx.globalAlpha = 0.30 + 0.12 * Math.sin(now / 90);
                            ctx.fillStyle = cfg.color;
                            ctx.fillRect(hz.x - hz.w / 2, hz.y - hz.h / 2, hz.w, hz.h);
                            ctx.globalAlpha = 0.95;
                            ctx.strokeStyle = cfg.color;
                            ctx.lineWidth = 2;
                            if (effectsEnabled()) { ctx.shadowBlur = 16; ctx.shadowColor = cfg.color; }
                            ctx.strokeRect(hz.x - hz.w / 2, hz.y - hz.h / 2, hz.w, hz.h);
                        } else {
                            ctx.globalAlpha = arming ? 0.30 + 0.35 * Math.sin(now / 55) : 0.16;
                            ctx.strokeStyle = cfg.color;
                            ctx.lineWidth = arming ? 2 : 1;
                            ctx.setLineDash([5, 8]);
                            ctx.strokeRect(hz.x - hz.w / 2, hz.y - hz.h / 2, hz.w, hz.h);
                        }
                        ctx.restore();
                    } else if (hz.kind === 'singularity') {
                        const t = now / 1000;
                        ctx.save();

                        // Outer haze, so the edge of the danger is legible against a
                        // floor that is already nearly black.
                        const halo = ctx.createRadialGradient(hz.x, hz.y, hz.r * 0.7, hz.x, hz.y, hz.r * 1.55);
                        halo.addColorStop(0, 'rgba(124,58,237,0.28)');
                        halo.addColorStop(1, 'rgba(124,58,237,0)');
                        ctx.fillStyle = halo;
                        ctx.beginPath(); ctx.arc(hz.x, hz.y, hz.r * 1.55, 0, Math.PI * 2); ctx.fill();

                        // The core. Black at the centre going to a deep violet at
                        // the rim — the colour lives at the edge, and the middle is
                        // a hole rather than a disc.
                        const core = ctx.createRadialGradient(hz.x, hz.y, 0, hz.x, hz.y, hz.r);
                        core.addColorStop(0,    '#000000');
                        core.addColorStop(0.55, '#0a0212');
                        core.addColorStop(0.85, '#2e1065');
                        core.addColorStop(1,    '#4c1d95');
                        ctx.fillStyle = core;
                        ctx.beginPath(); ctx.arc(hz.x, hz.y, hz.r, 0, Math.PI * 2); ctx.fill();

                        // Cracks across the surface of the core, turning slowly in
                        // both directions so it never settles into a single spin.
                        ctx.globalAlpha = 0.85;
                        ctx.lineCap = 'round';
                        for (const arc of hz.arcs) {
                            const a = arc.a + t * arc.speed;
                            const inner = hz.r * 0.12;
                            const outer = hz.r * arc.rr + hz.r * 0.42;
                            const midA = a + Math.sin(t * 0.8 + arc.rr * 5) * 0.16;
                            ctx.strokeStyle = '#8b5cf6';
                            ctx.lineWidth = 2;
                            if (effectsEnabled()) { ctx.shadowBlur = 14; ctx.shadowColor = '#a855f7'; }
                            ctx.beginPath();
                            ctx.moveTo(hz.x + Math.cos(a) * inner, hz.y + Math.sin(a) * inner);
                            ctx.lineTo(hz.x + Math.cos(midA) * (outer * 0.6), hz.y + Math.sin(midA) * (outer * 0.6));
                            ctx.lineTo(hz.x + Math.cos(a - 0.1) * outer, hz.y + Math.sin(a - 0.1) * outer);
                            ctx.stroke();
                        }

                        // Rim, pulsing — the boundary you must not cross.
                        ctx.globalAlpha = 0.55 + 0.3 * Math.sin(t * 1.9);
                        ctx.shadowBlur = effectsEnabled() ? 22 : 0;
                        ctx.shadowColor = '#a855f7';
                        ctx.strokeStyle = '#a855f7';
                        ctx.lineWidth = 2.5;
                        ctx.beginPath(); ctx.arc(hz.x, hz.y, hz.r, 0, Math.PI * 2); ctx.stroke();
                        ctx.restore();
                    } else if (hz.kind === 'sweeper' && hz.active) {
                        ctx.save();
                        ctx.translate(hz.x, hz.y);
                        ctx.rotate(hz.spin);
                        ctx.globalAlpha = 0.9;
                        ctx.fillStyle = cfg.color;
                        if (effectsEnabled()) { ctx.shadowBlur = 18; ctx.shadowColor = cfg.color; }
                        ctx.beginPath();
                        ctx.roundRect(-cfg.radius, -cfg.radius * 0.6, cfg.radius * 2, cfg.radius * 1.2, 6);
                        ctx.fill();
                        ctx.globalAlpha = 0.95;
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 1.5;
                        ctx.stroke();
                        ctx.restore();
                    }
                }

                // Wind is invisible on its own, so it is drawn as streaks. Without
                // this the player only sees themselves sliding and reads it as a
                // control bug rather than as weather.
                if (hazardWind.x || hazardWind.y) {
                    const cfg = currentHazardConfig();
                    const count = reducedMotion ? 8 : 26;
                    ctx.save();
                    ctx.globalAlpha = 0.20;
                    ctx.strokeStyle = '#cfe8ff';
                    ctx.lineWidth = 1.5;
                    const len = 26 + Math.hypot(hazardWind.x, hazardWind.y) * 130;
                    for (let i = 0; i < count; i++) {
                        // Seeded off i so the streaks are stable frame to frame and
                        // drift with the wind rather than flickering randomly.
                        const sx = ((i * 8191) % 1000) / 1000 * canvasLogicalW;
                        const sy = (((i * 6151) % 1000) / 1000 * canvasLogicalH
                                    + frameNow * 0.05 * (cfg ? cfg.strength * 9 : 1)) % canvasLogicalH;
                        ctx.beginPath();
                        ctx.moveTo(sx, sy);
                        ctx.lineTo(sx + hazardWind.x * len, sy + hazardWind.y * len);
                        ctx.stroke();
                    }
                    ctx.restore();
                }
            }

            // ── ACHIEVEMENT UNLOCKABLES ────────────────────────────────
            const achievements = {
                droidSlayer:   { id:'droidSlayer',   label:'Droid Slayer',      desc:'Win a battle against a Droid',           done: false },
                hothSurvivor:  { id:'hothSurvivor',  label:'Hoth Survivor',     desc:'Win on the Hoth arena',                  done: false },
                saberMaster:   { id:'saberMaster',   label:'Saber Master',       desc:'Win 3 battles with a lightsaber user',   done: false },
                noHits:        { id:'noHits',        label:'Untouchable',        desc:'Win a round without taking damage',       done: false },
                highGround:    { id:'highGround',    label:'I have the high ground!', desc:'Win on Mustafar as Obi-Wan against Sith Anakin', done: false },
                // New achievements
                winStreak3:     { id:'winStreak3',     label:'Hot Streak',        desc:'Win 3 matches in a row',                done: false },
                winStreak5:     { id:'winStreak5',     label:'On Fire',           desc:'Win 5 matches in a row',                done: false },
                winStreak10:    { id:'winStreak10',    label:'Unstoppable',       desc:'Win 10 matches in a row',               done: false },
                perfectVictory: { id:'perfectVictory', label:'Perfect Victory',   desc:'Win without taking any damage',         done: false },
                jabbaUnlock:    { id:'jabbaUnlock',    label:'Jabba Unleashed',   desc:'Defeat Jabba after freeing Carbonite Han on Cloud City', done: false },
                speedDemon:     { id:'speedDemon',     label:'Speed Demon',       desc:'Win a match in under 30 seconds',        done: false },
                comboMaster:    { id:'comboMaster',    label:'Combo Master',      desc:'Kill 3 enemies within 5 seconds',       done: false },
                // Mastery achievements
                blasterMaster:  { id:'blasterMaster',  label:'Blaster Master',    desc:'Win 5 matches with a blaster',          done: false },
                saberMaster2:   { id:'saberMaster2',   label:'Saber Master II',   desc:'Win 5 matches with a lightsaber',       done: false },
                // Arena specialist
                spaceSpecialist:{ id:'spaceSpecialist',label:'Space Specialist',  desc:'Win 5 matches in Deep Space',            done: false },
                // New: milestone & exploration achievements
                firstWin:       { id:'firstWin',       label:'First Blood',       desc:'Win your very first battle',        done: false },
                arenaExplorer:  { id:'arenaExplorer',  label:'Arena Explorer',    desc:'Win in 5 different arenas',             done: false },
                villainSlayer:  { id:'villainSlayer',  label:'Villain Slayer',    desc:'Defeat 5 different villain characters', done: false },
                vaderSlayer:    { id:'vaderSlayer',    label:'I Am Your Father',  desc:'Defeat Darth Vader',                   done: false },
                bountyHunter:   { id:'bountyHunter',   label:'Bounty Hunter',     desc:'Win a match as a bounty hunter',        done: false },
                millenniumRun:  { id:'millenniumRun',  label:'Kessel Run',        desc:'Win 3 matches as Han Solo',             done: false },
                // Vader mastery
                vaderConquest:  { id:'vaderConquest',  label:'Dark Lord\'s Reign',desc:'Win 10 consecutive matches as Darth Vader',      done: false },
                jediHunter:     { id:'jediHunter',     label:'Jedi Hunter',      desc:'Win 10 matches as a villain',   done: false },
                // Internal id stays 'snap' on purpose — it is the key this is saved
                // under in localStorage, so renaming it would silently revoke the
                // achievement from everyone who already has it. Only the player-
                // facing label and description changed.
                snap:           { id:'snap',            label:'Krk!',             desc:'Kill Commander Fox with a neck snap on Coruscant', creditsReward: 250, done: false },
                mandoDarksaber: { id:'mandoDarksaber',  label:'This Is The Way',  desc:'Defeat Moff Gideon as The Mandalorian on Mandalore', done: false },
                bazeUnlock:     { id:'bazeUnlock',      label:'Guardian of the Whills', desc:'Defeat Director Krennic as Admiral Raddus on the Death Star', done: false },
            };

            let gameUnlocks = { ultimatePalpatine: false, charredAnakin: false, senatorPalpatine: false, jabbaUnlock: false, devTeam: false, tarffulUnlock: false, thorn: false, pazvizsla: false, fox_elite: false, shaagi: false, sithAnakin: false, zeroEventCleared: false, zeroUnit: false, starlord: false, thanos: false, eternity: false, lordtreat: false, lordtrick: false };

            /*  ── THE HALLOWEEN EVENT: THE FALLEN ─────────────────────────────────
             *  A fighter killed on the Halloween team is dead until bought back in
             *  the Shop. Kept apart from gameUnlocks because that table means "the
             *  player has this", and a flag meaning the opposite would read wrong in
             *  every loop over it. It lives under the galacticDuel prefix, so Clear
             *  Data and the save download pick it up with everything else.
             *
             *  Declared here, next to gameUnlocks, because isCharacterRetired()
             *  reads it and that runs during boot — long before the event's own
             *  block further down the file (THE HALLOWEEN EVENT) would have
             *  declared it. The Skeleton Warrior never lands in here: see
             *  HALLOWEEN_EXPENDABLE_IDS there.                                    */
            let halloweenFallen = {};   // id -> true while that fighter is dead

            function isHalloweenFallen(id) { return !!halloweenFallen[id]; }
            function persistHalloweenFallen() {
                saveVersioned('galacticDuelHalloween', { fallen: halloweenFallen });
            }
            function loadHalloweenFallen() {
                halloweenFallen = {};
                try {
                    const saved = loadVersioned('galacticDuelHalloween', {});
                    const fallen = saved && saved.fallen;
                    if (fallen && typeof fallen === 'object') {
                        Object.keys(fallen).forEach(id => { if (fallen[id]) halloweenFallen[id] = true; });
                    }
                } catch (e) { halloweenFallen = {}; }
            }

            /*  What a revive costs: 5% under what the fighter is worth, as the plan
             *  priced it. Fox and Cody are free, so their worth comes from the Shop:
             *  Thorn (160 HP, minigun) sells for 200; the Armory prices a minigun at
             *  300 and a blaster at 150, so swapping it for their blaster takes off
             *  150, and Paz Vizsla's 250 for 35 more HP puts a point of health at
             *  about 1.4 credits. The Halloween heroes are priced the same way, with
             *  something on top for a shield and a gun that explodes.             */
            const HALLOWEEN_WORTH = { fox: 36, cody: 43, skeleton: 60, hawlo: 100, lordtreat: 170 };
            function halloweenRevivePrice(id) {
                const worth = HALLOWEEN_WORTH[id];
                return worth ? Math.round(worth * 0.95) : 50;
            }

            // Elite/reskinned characters count as their base character for achievement
            // and unlock-condition purposes (e.g. Darth Vader (Elite) still counts as
            // "Vader" for the Snap! achievement, Vader Slayer, etc).
            const ELITE_BASE_IDS = {
                darth_vader: 'vader',
                darth_maul: 'maul',
                jango_fett: 'jango',
                mace_windu: 'windu',
                finn_elite: 'finn',
                fox_elite: 'fox',
                mando_elite: 'mando'
            };
            function achievementCharId(charData) {
                if (!charData) return null;
                return ELITE_BASE_IDS[charData.id] || charData.id;
            }

            // Resolve any elite/variant character id (e.g. 'fox_elite') to the base
            // roster id it's a reskin of (e.g. 'fox'). Used anywhere we look a raw
            // characterId/id up in a table keyed by base ids — clone-commander rank
            // detection, "call backup" unit selection, commander-death flee logic,
            // etc. — so that any current or future elite/variant character is treated
            // as its base character for those purposes instead of being mistaken for
            // an unrecognized rank-and-file trooper.
            function resolveCloneBaseId(rawId) {
                return ELITE_BASE_IDS[rawId] || rawId;
            }

            function persistGalacticUnlocks() {
                saveVersioned('galacticDuelUnlocks', gameUnlocks);
            }

            // Single source of truth for "can the player see and use this secret
            // character". A pack’s entries are no different from any other: each
            // is unlocked by its own flag and nothing else. There is no separate
            // pack to own on top of that, and the music toggle is only ever audio
            // — it must never gate a character.
            //
            // Everything that reveals a secret character routes through here (the
            // section header, the roster grid, the opponent picker). The code this
            // replaced checked the same condition in four separate places against
            // two different flags, so a player who owned a fighter but switched
            // the music off saw them listed and then found them locked.
            /** A character who has been superseded and is off the roster for good.
             *  `retiredBy` names the gameUnlocks flag that ends them: The Visitor is
             *  retired by 'geno', because winning that fight does not add a fighter
             *  to the roster, it replaces one. Retirement is checked wherever the
             *  game lists characters to choose from — it deliberately does NOT
             *  reach the data itself, so a save still loads, achievements earned as
             *  The Visitor still count, and the Boom Sniper pattern his shop entry
             *  unlocked stays in the armory.
             *
             *  `retiredBy` may name one flag or several. The Visitor needs both:
             *  'geno' ends him the moment that fight is won, and the Zero Event ends
             *  him along with the rest of that roster whether or not the
             *  player ever stood at the Zero Point. Either flag alone is enough —
             *  a character is retired when ANY of the reasons has happened, because
             *  two things that each end a fighter do not have to agree on which one
             *  got there first. */
            /*  ══ THE VAULT — INDEX ═════════════════════════════════════════════
             *
             *  Vaulted means out of rotation, not gone: the data stays exactly where
             *  it is and one flag brings it back. Nothing in this game is deleted to
             *  remove it. Every vault is enforced at the point of USE, never at the
             *  point of definition, so the records keep resolving for saves that
             *  already own the thing.
             *
             *  This is the whole vault as it stands. Every entry below is tagged
             *  `VAULTED` in a comment at its own site, so:
             *
             *      grep -n "VAULTED" game.js       lists every vault in the file
             *      node validate.js                prints what is currently vaulted
             *
             *  No line numbers below on purpose — they rot. Each row names the tag
             *  to jump to and the flag to flip, and both are greppable forever.
             *
             *  ── THE OLD SEASON LAYER ──  now a content pack, see applyContentPack()
             *      20 characters, Cluster Coast + Zero Point arenas, the shop pack,
             *      the season view and the poiRoi achievement. Enforced in
             *      isCharacterRetired(), which is why "retired" and "vaulted" are one
             *      code path and not two.
             *
             *  ── VAULTED: ELEVEN WEAPONS ──  flip: drop `vaulted: true`
             *      lancehead, burstrifle, focusshotgun, boomsniper, assaultrifle,
             *      enhancedar, deadeyear, excaliber, submachine, warforgedar,
             *      seekerssword. Out of the commission pool and out of the
             *      fabricator; WEAPON_LIBRARY still resolves every one of them, so a
             *      fighter or a forged weapon already carrying one is untouched.
             *      See isWeaponVaulted().
             *
             *  ── VAULTED: THE SHAPELESS SPRITE ──  flip: drop `vaulted: true`
             *      Out of drops and out of the shop's recovery list. Anyone who
             *      already owns one keeps it equipped and working — vaulting stops
             *      the handing out, it does not confiscate.
             *
             *  ── VAULTED: FOUR FORGE PATTERNS ──  flip: drop `vaulted: true`
             *      lancehead, burstrifle, focusshotgun, boomsniper — the
             *      pack-exclusive commissions. Their base weapons left with the pack
             *      too, so isPatternVaulted() would hold them back either way; the
             *      row's own flag is what makes that independent of the weapon's.
             *      getForgePattern() must still resolve them, or a weapon already
             *      forged from one prices at ∞.
             *
             *  ── VAULTED: THE SNAP INTRO ──  flip: SNAP_INTRO_VAULTED = false
             *      Thanos no longer walks on by himself. A new save opens to the
             *      menu the Snap leaves behind, settled through SnapIntro.skip(),
             *      and the THANOS redeem code (or the dev menu) plays the whole
             *      sequence on request. snap-intro.js is otherwise unchanged. See
             *      offerSnapIntro() / replaySnapIntro().
             *
             *  ── VAULTED: THE SEASON CARD ──  flip: SEASON_CARD_VAULTED = false
             *      The After the Snap card and its soundtrack question. The Snap
             *      ends on the menu now; the soundtrack is chosen in Settings.
             *      Filtered in openSeasonCard(); markup and styles untouched.
             *
             *  ── VAULTED: TWO MUSIC TRACKS ──  flip: put the 2 files in music/
             *      The only vault whose data is genuinely absent: the .mp3/.m4a
             *      files were removed for size. What is kept is the part worth
             *      keeping — the names, and which track played where.
             *
             *  ── NOT IN THE VAULT ──────────────────────────────────────────────
             *      Three things were deleted outright rather than vaulted, on an
             *      explicit call, and are recorded here so nobody goes looking for a
             *      flag that does not exist:
             *
             *        · THE ZERO EVENT. The five-stage boss run, its overlay, its
             *          status strip, its result screen, its relics and its 13
             *          unplayable cast. `gameUnlocks.zeroEventCleared` survives as a
             *          legacy save field — nothing sets it any more, but a save that
             *          cleared the event keeps what it earned (Wrixel, the Unstable
             *          Zero Point). The Zero Point arena itself is untouched and is
             *          out with the pack, not with the run.
             *        · FIVE WEAPONS. spindash, minersword, cubebolt, voidlance,
             *          iocannon — carried only by that cast, so nothing else lost a
             *          weapon. iceblast stayed: The Mandarin carries it too.
             *        · THE CONTINUE TILE, and the `lastLoadout` record behind it.
             *          Freeplay is one tile again.
             *        · POISON SPIT, the Abomination's ranged attack.
             *          `POISON_SPIT_VAULTED`, filtered in canPoisonSpit(). The
             *          config, the fire routine and the whole poison status system
             *          (applyPoison/tickPoison, and the `poisonMs` branch in
             *          applyStatusAndDamage) are retained and now unreached —
             *          nothing else in the game carries `poisonMs`. It went because
             *          the Abomination is gamma rather than venomous; the note at
             *          the switch says what removing it costs him.
             *        · HULK, as a pickable fighter. `vaulted: true` on the record,
             *          which isCharacterRetired() now honours. He is not gone — he
             *          is what Bruce Banner turns into on Interact, and
             *          TRANSFORM_FORMS.bruce is the only thing that reaches him. The
             *          record stays because it is still the source of his numbers,
             *          and Hulk Smash moved to Banner's throw key with him.
             *
             *  Adding to the vault: add a `vaulted: true` field (data) or a
             *  `*_VAULTED` const (feature), tag the site `VAULTED: <THING>`, filter
             *  at the point of use, and add a row above. Do not delete the record.
             */

            /*  ── CONTENT PACKS ───────────────────────────────────
             *  An optional add-on: a season of fighters, weapons, arenas, shop
             *  entries and unlock flags living in its own file and folded into the
             *  tables below at load. The base game ships with none and index.html
             *  loads none, so all of this is inert until a pack file is added.
             *
             *  TO ADD ONE: drop the pack file in beside this one and give it a
             *  <script> tag in index.html ABOVE game.js. That is the whole of it.
             *  The pack sets window.GL_CONTENT_PACK and applyContentPack() merges
             *  it, so nothing downstream can tell a packed fighter from a built-in
             *  one.
             *
             *  TO TAKE IT OUT AGAIN: delete the script tag. Saves are untouched —
             *  the unlock flags for anything already bought stay in the save and
             *  come back with the pack.
             *
             *  One pack at a time: the season toggle in the faction headings is a
             *  single control and activeSeason() would have to choose between two.  */
            let contentPack = null;

            /** The loaded pack's season, or null when there is no pack. Every caller
             *  has to cope with null — see paintToggle() and packFactionColumn(). */
            function packSeason() {
                return (contentPack && contentPack.season) ? contentPack.season : null;
            }

            /*  Folds a pack into the live tables. Called once, straight after the
             *  character table is built, which is the first moment every table it
             *  touches exists and still well before anything reads them.
             *
             *  Stamps `packId` on the records it adds. That is what marks a fighter
             *  or a shop row as belonging to a pack rather than to the base game,
             *  and it is what ownsAnyPackCharacter() and the season view read. */
            function applyContentPack() {
                const pack = (typeof window !== 'undefined') ? window.GL_CONTENT_PACK : null;
                if (!pack) return;
                contentPack = pack;

                (pack.characters || []).forEach(c => { c.packId = pack.id; characters.secret.push(c); });
                (pack.shopItems  || []).forEach(i => { i.packId = pack.id; shopItems.push(i); });
                (pack.forgePatterns || []).forEach(p => FORGE_PATTERNS.push(p));
                (pack.sprites || []).forEach(sp => SPRITE_CATALOG.push(sp));
                Object.assign(WEAPON_LIBRARY, pack.weapons || {});
                Object.assign(weaponEmoji,    pack.weaponEmoji || {});
                Object.assign(ARENAS,         pack.arenas || {});
                Object.assign(ARENA_HAZARDS,  pack.arenaHazards || {});
                Object.assign(achievements,   pack.achievements || {});
                Object.assign(ELITE_BASE_IDS, pack.eliteBaseIds || {});
                Object.assign(ARENA_LAYOUTS,  pack.arenaLayouts || {});
                Object.assign(ARENA_SCENERY_CACHES, pack.arenaCaches || {});
                // Never clobber a flag the save has already set.
                Object.keys(pack.unlocks || {}).forEach(k => {
                    if (!(k in gameUnlocks)) gameUnlocks[k] = !!pack.unlocks[k];
                });
                // Last, so a pack can touch anything the merge just created —
                // arena buttons, for one, which are wired further down the file.
                if (typeof pack.install === 'function') pack.install();
            }
            function isCharacterRetired(char) {
                /*  The vault, stated here rather than at each call site, because
                 *  "retired" already means exactly this: out of every rotation, with
                 *  the record left exactly where it is. One line here covers the
                 *  roster, the opponent picker, Surprise Me, the secret row,
                 *  ownsAnyPackCharacter() (so the season toggle disappears) and
                 *  shopItemIsRetired() (so the shop delists the pack).             */
                // VAULTED: a flat `vaulted: true` on the record, for a fighter who
                // is out unconditionally rather than on an unlock flag. `retiredBy`
                // below answers "retired once you own their replacement"; this
                // answers "not in the game any more, record retained". Hulk is the
                // first, because Bruce Banner is now the only door to him.
                if (char && char.vaulted) return true;
                // FALLEN: killed on the Halloween team and not yet bought back. One
                // line here is what takes them off every roster, the opponent
                // picker and the team card at once, until the Shop puts them back.
                if (char && isHalloweenFallen(char.id)) return true;
                if (!char || !char.retiredBy) return false;
                const keys = Array.isArray(char.retiredBy) ? char.retiredBy : [char.retiredBy];
                return keys.some(k => !!gameUnlocks[k]);
            }

            function isSecretCharUnlocked(char) {
                if (!char) return false;
                if (char.id === 'ultimate_palp') return gameUnlocks.ultimatePalpatine;
                if (char.secretUnlock) return gameUnlocks[char.secretUnlock];
                return false;
            }

            /** What the secret row actually lists — which is never a season
             *  fighter. They live in the two main faction columns and appear only
             *  while that season’s toggle is on; this row is for the Galactic
             *  secrets alone (Ultimate Palpatine, Charred Anakin, Jabba, the
             *  Cousin Crew and so on).
             *
             *  This used to exclude them only while the season view was on, which
             *  meant they sat in the secret row the rest of the time and the same
             *  character had two homes depending on a toggle. One home is the
             *  point: the toggle is now the only way to see them, and the row
             *  below the roster no longer changes shape when it is flipped. */
            function visibleSecretChars() {
                return characters.secret.filter(c =>
                    isSecretCharUnlocked(c) && !isCharacterRetired(c) && !c.packId && !c.marvel && !c.halloween);
            }

            /*  The secret row sits under the two faction columns, and it lists the
             *  Galactic secrets — never a season fighter (see visibleSecretChars).
             *  So while a season view owns the columns above it, the row underneath
             *  is the other roster entirely: turning Marvel on and still seeing
             *  Jabba and the Cousin Crew below reads as the switch half-working.
             *  It stands down for the duration and comes back with the columns.  */
            function updateSecretFactionSectionVisibility() {
                const el = document.getElementById('secret-faction-wrapper');
                if (!el) return;
                const show = !activeSeason() && visibleSecretChars().length > 0;
                el.style.display = show ? 'flex' : 'none';
            }

            // Ultimate Emperor Palpatine unlocks by defeating Sith C-3PO —
            // a distinct character from any of the other secret-roster
            // unlocks (Charred Anakin, Senator Palpatine, Tarfful, Jabba,
            // Cousin Crew). Those still each unlock their own character only.
            function unlockUltimatePalpatine() {
                if (gameUnlocks.ultimatePalpatine) return;
                gameUnlocks.ultimatePalpatine = true;
                persistGalacticUnlocks();
                rebuildSecretRoster();
                updateSecretFactionSectionVisibility();
                showAnnouncement("Sith C-3PO's destruction reveals a deeper conspiracy. Ultimate Emperor Palpatine has joined your roster.", "#9900ff", 6000, "🔓 CHARACTER UNLOCKED", 100);
            }

            // The Zero Point encounter. Every other unlock in this file adds a
            // fighter; this one trades one for another, which is why it rebuilds all
            // three columns rather than just the secret row — The Visitor has to
            // leave the roster in the same breath Geno joins it, and with the season
            // faction view on the two of them are not even in the same column.
            function unlockGeno() {
                if (gameUnlocks.geno) return;
                gameUnlocks.geno = true;
                persistGalacticUnlocks();
                rebuildAllRosters();
                updateSecretFactionSectionVisibility();
                showAnnouncement('The Visitor does not walk away from the Zero Point. Something finished does — Geno has taken his place, and he is not on your side.',
                    '#e8f0ff', 7000, '⚔️ THE VISITOR IS GONE', 100);
            }

            function loadGalacticUnlocks() {
                try {
                    const u = loadVersioned('galacticDuelUnlocks', {});
                    Object.keys(u).forEach(key => {
                        gameUnlocks[key] = !!u[key];
                    });
                    // Wrixel is what clearing the Zero Event gives you, and a save
                    // that cleared it before he was written still cleared it. Costs
                    // nothing to grant and there is nothing to take back, so the
                    // migration is this line rather than a version bump.
                    if (gameUnlocks.zeroEventCleared) gameUnlocks.wrixel = true;
                } catch(e) {}
                updateSecretFactionSectionVisibility();
            }
            let saberWinCount = 0;
            let playerTookDamage = false;
            let comboKills = [];
            let lastKillTime = 0;
            let blasterWinCount = 0;
            let saberWinCount2 = 0;
            let spaceWinCount = 0;
            let totalWins = 0;
            let hanWinCount = 0;
            let arenasWonIn = new Set();
            let villainsDefeated = new Set();
            let vaderConsecutiveWins = 0;
            let lastPlayedCharacterId = null;
            let villainWinCount = 0;
            const BOUNTY_HUNTER_IDS = new Set(['boba','jango','jango_fett','cadbane','bossk','dengar','ig88','aurrasing','embo']);

            // `immediate` marks an achievement earned *during* a fight rather than
            // as a result of one. Announcements are deferred while a match is in
            // progress, and the queue is wiped at the next setupGame(), so a
            // mid-fight unlock that queues is shown long after the moment it
            // describes — or, in a series that keeps going, never shown at all.
            // Anything earned in the arena passes true; end-of-match unlocks leave
            // it false and ride the normal queue with the rest of the results.
            function tryUnlockAchievement(id, immediate = false) {
                const a = achievements[id];
                if (!a || a.done) return;
                a.done = true;
                try {
                    const saved = loadVersioned('galacticDuelAchievements', {});
                    saved[id] = true;
                    // Always persist progress counters so they survive refreshes
                    saved._saberWinCount   = saberWinCount;
                    saved._saberWinCount2  = saberWinCount2;
                    saved._blasterWinCount = blasterWinCount;
                    saved._spaceWinCount   = spaceWinCount;
                    saved._totalWins       = totalWins;
                    saved._hanWinCount     = hanWinCount;
                    saved._arenasWonIn     = [...arenasWonIn];
                    saved._villainsDefeated= [...villainsDefeated];
                    saved._villainWinCount = villainWinCount;
                    saveVersioned('galacticDuelAchievements', saved);
                } catch(e) {}
                if (a.creditsReward) {
                    const gained = awardCredits(a.creditsReward);
                    saveGameSettings();
                    updateCreditsDisplay();
                    showAnnouncement(creditAwardLine(gained), '#ffd700', 3000, 'CREDITS', 40, immediate);
                }
                showAchievementToast(a, immediate);
                rebuildSecretRoster();
                rebuildHeroRoster();
                rebuildVillainRoster();
            }

            // Unlocks an achievement-gated character and, the first time it
            // actually triggers, shows a narrative "X has joined your
            // roster" announcement. Safe to call every frame/hit — the
            // announcement only fires once, on the transition to done.
            function tryUnlockAchievementWithAnnouncement(id, message, color, immediate = false) {
                const alreadyDone = !!(achievements[id] && achievements[id].done);
                tryUnlockAchievement(id, immediate);
                if (!alreadyDone && achievements[id] && achievements[id].done) {
                    showAnnouncement(message, color, 6000, '🔓 CHARACTER UNLOCKED', 100, immediate);
                }
            }

            function persistAchievementCounters() {
                try {
                    const saved = loadVersioned('galacticDuelAchievements', {});
                    saved._saberWinCount   = saberWinCount;
                    saved._saberWinCount2  = saberWinCount2;
                    saved._blasterWinCount = blasterWinCount;
                    saved._spaceWinCount   = spaceWinCount;
                    saved._totalWins       = totalWins;
                    saved._hanWinCount     = hanWinCount;
                    saved._arenasWonIn     = [...arenasWonIn];
                    saved._villainsDefeated= [...villainsDefeated];
                    saved._vaderConsecutiveWins = vaderConsecutiveWins;
                    saved._lastPlayedCharacterId = lastPlayedCharacterId;
                    saved._villainWinCount = villainWinCount;
                    saveVersioned('galacticDuelAchievements', saved);
                } catch(e) {}
            }

            function loadAchievements() {
                try {
                    const saved = loadVersioned('galacticDuelAchievements', {});
                    Object.keys(saved).forEach(id => {
                        if (Object.prototype.hasOwnProperty.call(achievements, id)) achievements[id].done = true;
                    });
                    // Restore persistent progress counters. Checked the way every
                    // other save field is, since a save file is editable JSON.
                    const count = v => Math.floor(savedNumber(v, 0, Number.MAX_SAFE_INTEGER, 0));
                    const ids = v => Array.isArray(v) ? v.filter(x => typeof x === 'string') : [];
                    saberWinCount  = count(saved._saberWinCount);
                    saberWinCount2 = count(saved._saberWinCount2);
                    blasterWinCount= count(saved._blasterWinCount);
                    spaceWinCount  = count(saved._spaceWinCount);
                    totalWins      = count(saved._totalWins);
                    hanWinCount    = count(saved._hanWinCount);
                    arenasWonIn    = new Set(ids(saved._arenasWonIn));
                    villainsDefeated = new Set(ids(saved._villainsDefeated));
                    villainWinCount = count(saved._villainWinCount);
                    vaderConsecutiveWins = count(saved._vaderConsecutiveWins);
                    lastPlayedCharacterId = typeof saved._lastPlayedCharacterId === 'string' ? saved._lastPlayedCharacterId : null;
                } catch(e) {}
            }
            loadAchievements();

            function showAchievementToast(a, immediate = false) {
                // Achievements share the announcement banner with everything
                // else — see the announcement stack below.
                showAnnouncement(`${a.label}: ${a.desc}`, '#ffd700', 4500, '🏆 ACHIEVEMENT UNLOCKED', 90, immediate);
            }

            // ── ANNOUNCEMENT STACK ──────────────────────────────────────
            // A new notification shows the instant it is made, on top. Up to
            // two are on screen at once; a third pushes the oldest off, so a
            // third box never appears.
            //
            // History, so nobody walks it back by accident. The banner used to
            // stack three, ordered by priority, and a fourth waited in a queue
            // that drained in batches every 5s, so news arrived after the
            // moment it was about. Then newest-on-top with the oldest bumped;
            // then one at a time, with the replaced one fading slowly, which let
            // several fading boxes pile up; then one at a time with a 2.5s
            // minimum before anything could replace it, which the owner found
            // made notifications late. Two at once is what lets things that fire
            // in the same instant (an achievement and the character it unlocks,
            // an achievement and its credit reward) both be read without
            // anything having to wait. The `priority` argument is still accepted
            // from the call sites but no longer orders anything.
            const MAX_VISIBLE_ANNOUNCEMENTS = 2;
            // Rewards held during a battle are released at the end of the round
            // one per gap, because released in one frame a burst bigger than two
            // would push its own first items off before anyone saw them. At 1.2s
            // each one is up for at least 2.4s (until two newer ones arrive);
            // a six-item burst plays out in about 7s.
            const ANNOUNCEMENT_RELEASE_GAP_MS = 1200;
            let announcementStack = [];
            let announcementIdSeq = 0;
            // Held during a battle (deferAnnouncements), released into
            // announcementReleaseQueue at the end of every round.
            let pendingAnnouncementQueue = [];
            let announcementReleaseQueue = [];
            let announcementReleaseTimer = null;
            let deferAnnouncements = false; // When true, queue announcements instead of showing immediately

            function renderAnnouncementStack() {
                const banner = document.getElementById('announcementBanner');
                if (!banner) return;
                // Counted from the DOM, not the stack: an expired item leaves the
                // stack at once but stays in the banner for its 250ms fade, and
                // hiding the banner mid-fade would cut the fade off.
                banner.classList.toggle('has-items', banner.children.length > 0);
            }

            /** Take one item off the stack and fade it out. Safe to call twice
             *  (its own timer and a push-off can race); the second is a no-op. */
            function dismissAnnouncement(item) {
                if (!announcementStack.includes(item)) return;
                clearTimeout(item.el._hideTimer);
                announcementStack = announcementStack.filter(a => a !== item);
                item.el.classList.add('ann-leaving');
                setTimeout(() => {
                    item.el.remove();
                    renderAnnouncementStack();
                }, 250);
            }

            // During a Zero Event run the banner is reserved. Only two things may
            // speak: a stage changing, and a new enemy arriving. Everything else the
            // game would normally say — casualties, unlocks, credits, achievement
            // pops, sprite notices — is dropped rather than queued, because a run is
            // five long fights and a queue would simply deliver all of it later.
            //
            /** Clears the banner outright. The event shows one notice at a time, so
             *  a new one replaces whatever is up rather than stacking on it. */
            function clearAnnouncements() {
                announcementStack.forEach(a => {
                    if (a.el._hideTimer) clearTimeout(a.el._hideTimer);
                });
                const banner = document.getElementById('announcementBanner');
                if (banner) banner.replaceChildren();
                announcementStack = [];
                pendingAnnouncementQueue = [];
                announcementReleaseQueue = [];
                clearTimeout(announcementReleaseTimer);
                announcementReleaseTimer = null;
                renderAnnouncementStack();
            }

            function showAnnouncement(msg, color = '#00cfff', duration = 4500, title = '⚡ TRANSMISSION', priority = 50, forceShow = false) {
                // If deferring announcements and not forced to show, hold it for
                // the end of the round instead
                if (deferAnnouncements && !forceShow) {
                    pendingAnnouncementQueue.push({ msg, color, duration, title, priority });
                    return;
                }

                const banner = document.getElementById('announcementBanner');
                if (!banner) return;

                // Full: the oldest goes, at once rather than fading, because a
                // fading box is still a box and the cap is two on screen. This
                // applies to forced (mid-battle) callouts too, which once skipped
                // the cap entirely.
                while (announcementStack.length >= MAX_VISIBLE_ANNOUNCEMENTS) {
                    const oldest = announcementStack.shift();
                    clearTimeout(oldest.el._hideTimer);
                    oldest.el.remove();
                }
                // Boxes still fading after running out their own time count too,
                // so they go until there is room, oldest (lowest) first.
                for (const el of [...banner.children].reverse()) {
                    if (banner.children.length < MAX_VISIBLE_ANNOUNCEMENTS) break;
                    if (el.classList.contains('ann-leaving')) el.remove();
                }

                const id = ++announcementIdSeq;
                const inner = document.createElement('div');
                inner.className = 'ann-inner';
                inner.style.color = color;
                inner.style.borderColor = color;
                inner.style.boxShadow = `0 0 24px rgba(0,0,0,0.7), 0 0 16px ${color}55`;

                const titleEl = document.createElement('div');
                titleEl.className = 'ann-title';
                titleEl.textContent = title;
                titleEl.style.color = color;

                const msgEl = document.createElement('div');
                msgEl.className = 'ann-msg';
                msgEl.textContent = msg;
                msgEl.style.color = '#fff';

                inner.appendChild(titleEl);
                inner.appendChild(msgEl);

                const item = { id, el: inner, priority };
                announcementStack.push(item);
                // Prepended, never re-sorted: the newest goes on top and nothing
                // else moves, so an item fading out stays where it was instead of
                // jumping to the top while it fades.
                banner.prepend(inner);
                renderAnnouncementStack();

                inner._hideTimer = setTimeout(() => dismissAnnouncement(item), duration);
            }

            /** Show the next released reward, then come back after the gap.
             *  Deliberately does not check deferAnnouncements: these were
             *  released at the end of a round, so if the player clicks Next Round
             *  or Rematch before they have all shown, the rest carry on into the
             *  countdown instead of being lost. */
            function releaseNextAnnouncement() {
                if (announcementReleaseTimer || announcementReleaseQueue.length === 0) return;
                const next = announcementReleaseQueue.shift();
                showAnnouncement(next.msg, next.color, next.duration, next.title, next.priority, true);
                announcementReleaseTimer = setTimeout(() => {
                    announcementReleaseTimer = null;
                    releaseNextAnnouncement();
                }, ANNOUNCEMENT_RELEASE_GAP_MS);
            }

            /** Release what a battle held back, oldest first. Called at the end
             *  of EVERY round, not just the series: it used to run only when the
             *  series was decided, and Next Round emptied the held queue, so
             *  anything earned in rounds 1-4 of a best-of-five (round-end unlocks
             *  such as Senator Palpatine and Tarfful, Speed Demon) was never shown
             *  at all. The version before that also set deferAnnouncements back to
             *  true after every item it showed, so menu notifications after a
             *  match sat in the queue. */
            function flushAnnouncementQueue() {
                deferAnnouncements = false;
                announcementReleaseQueue.push(...pendingAnnouncementQueue);
                pendingAnnouncementQueue = [];
                releaseNextAnnouncement();
            }

            // ── SHARED RESET HELPERS ────────────────────────────────────
            // Used by restartButton, rematchButton, and pauseQuitBtn — these
            // three handlers used to duplicate this logic independently,
            // which is how the confetti-clear line almost got missed in one
            // of them. Keep new "reset between matches" state here instead
            // of copy-pasting into each handler.
            function resetSeriesAndEffects() {
                playerWins = 0; enemyWins = 0; isNextRound = false;
                deathParticles = [];
                floatNums = [];
                const confettiLayer = document.getElementById('confettiLayer');
                if (confettiLayer) confettiLayer.innerHTML = '';
                // Backup budget is per series, so it survives Next Round but not a
                // rematch or a trip back to the menu.
                resetPauseBackupBudget();
            }
            // resetAchievementCounters() used to sit here and was called by Return
            // to Base, Rematch and Quit. It zeroed the saber, blaster, Deep Space,
            // Han and Vader win counts in memory, and the next round won saved those
            // zeros over the real totals. A series pays at most three round wins, so
            // Blaster Master, Saber Master II, Space Specialist (5 each) and Dark
            // Lord's Reign (10, Darth Vader (Elite)) could only be earned by
            // reloading the page between series. The counts are lifetime totals and
            // nothing resets them now. The one count that is meant to break — Vader's
            // consecutive wins — breaks on a loss, in endGame.

            // ── SERIES VICTORY CONFETTI ─────────────────────────────────
            const CONFETTI_COLORS = ['#00cfff', '#ffd700', '#ff6666', '#cc99ff', '#66ff99', '#ff9d7a'];
            function spawnVictoryConfetti(count = 90) {
                if (reducedMotion) return;
                if (performanceMode === 'low') count = Math.min(count, 25);
                else if (performanceMode === 'balanced') count = Math.min(count, 50);
                const layer = document.getElementById('confettiLayer');
                if (!layer) return;
                layer.innerHTML = '';
                for (let i = 0; i < count; i++) {
                    const piece = document.createElement('div');
                    piece.className = 'confetti-piece';
                    const size = 6 + Math.random() * 6;
                    const isCircle = Math.random() < 0.35;
                    piece.style.left = `${Math.random() * 100}vw`;
                    piece.style.width = `${size}px`;
                    piece.style.height = `${isCircle ? size : size * 2.2}px`;
                    piece.style.background = CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)];
                    piece.style.borderRadius = isCircle ? '50%' : '2px';
                    piece.style.animationDuration = `${2.2 + Math.random() * 1.6}s`;
                    piece.style.animationDelay = `${Math.random() * 0.4}s`;
                    layer.appendChild(piece);
                }
                if (layer._clearTimer) clearTimeout(layer._clearTimer);
                layer._clearTimer = setTimeout(() => { layer.innerHTML = ''; }, 4500);
            }

            // ── IN-GAME CONFIRM DIALOG ──────────────────────────────────
            // NOTE FOR FUTURE DEV: this is the in-game replacement for the
            // browser-native window.confirm(). Every "are you sure?" prompt
            // in this game (clearing data, clearing history, etc.) should go
            // through showConfirm() instead of confirm()/alert()/prompt(),
            // so it always renders as part of the game's own UI instead of
            // popping a native OS/browser dialog box. Usage:
            //   showConfirm('Clear all data?', { title: 'CLEAR DATA', okLabel: 'Clear', danger: true })
            //       .then(confirmed => { if (confirmed) { ... } });
            const confirmOverlay = document.getElementById('confirmOverlay');
            const confirmBox = document.getElementById('confirmBox');
            const confirmTitleEl = document.getElementById('confirmTitle');
            const confirmIconEl = document.getElementById('confirmIcon');
            const confirmMessageEl = document.getElementById('confirmMessage');
            const confirmOkBtnEl = document.getElementById('confirmOkBtn');
            const confirmCancelBtnEl = document.getElementById('confirmCancelBtn');
            let confirmResolve = null;

            function closeConfirm(result) {
                if (!confirmOverlay) return;
                confirmOverlay.style.display = 'none';
                document.removeEventListener('keydown', handleConfirmKeydown);
                if (confirmResolve) {
                    const resolve = confirmResolve;
                    confirmResolve = null;
                    resolve(result);
                }
            }

            function handleConfirmKeydown(e) {
                if (e.key === 'Escape') { e.preventDefault(); closeConfirm(false); }
                else if (e.key === 'Enter') { e.preventDefault(); closeConfirm(true); }
            }

            function showConfirm(message, options = {}) {
                if (!confirmOverlay) return Promise.resolve(false);
                const {
                    title = 'CONFIRM',
                    icon = '⚠️',
                    okLabel = 'OK',
                    cancelLabel = 'Cancel',
                    danger = false
                } = options;

                confirmTitleEl.textContent = title;
                confirmIconEl.textContent = icon;
                confirmMessageEl.textContent = message;
                confirmOkBtnEl.textContent = okLabel;
                confirmCancelBtnEl.textContent = cancelLabel;

                const okColor = danger ? '#ff3333' : '#00A4FF';
                const okTextColor = danger ? '#ff6666' : '#00cfff';
                confirmOkBtnEl.style.borderColor = okColor;
                confirmOkBtnEl.style.color = okTextColor;
                confirmOkBtnEl.style.background = danger ? 'rgba(255,51,51,0.12)' : 'rgba(0,164,255,0.15)';
                confirmTitleEl.style.color = danger ? '#ff6666' : '#00cfff';

                confirmOverlay.style.display = 'flex';
                document.addEventListener('keydown', handleConfirmKeydown);
                setTimeout(() => confirmOkBtnEl.focus(), 0);

                return new Promise(resolve => { confirmResolve = resolve; });
            }

            if (confirmOkBtnEl) confirmOkBtnEl.addEventListener('click', () => closeConfirm(true));
            if (confirmCancelBtnEl) confirmCancelBtnEl.addEventListener('click', () => closeConfirm(false));
            if (confirmOverlay) {
                confirmOverlay.addEventListener('click', (e) => {
                    if (e.target === confirmOverlay) closeConfirm(false);
                });
            }

            // ── STAT PREVIEW CARD ──────────────────────────────────────
            const statCard = document.getElementById('statCard');
            
            // Function to map hex color to nearest rainbow color name
            function getRainbowColorName(hexColor) {
                // Parse hex to RGB
                const r = parseInt(hexColor.slice(1, 3), 16) / 255;
                const g = parseInt(hexColor.slice(3, 5), 16) / 255;
                const b = parseInt(hexColor.slice(5, 7), 16) / 255;
                
                const max = Math.max(r, g, b);
                const min = Math.min(r, g, b);
                const delta = max - min;
                
                // Check for grayscale colors first
                if (delta < 0.05) {
                    const avg = (r + g + b) / 3;
                    if (avg < 0.1) return 'Black';
                    if (avg > 0.9) return 'White';
                    return 'Gray';
                }
                
                // Calculate hue
                let hue;
                if (delta === 0) {
                    hue = 0;
                } else if (max === r) {
                    hue = ((g - b) / delta) % 6;
                } else if (max === g) {
                    hue = (b - r) / delta + 2;
                } else {
                    hue = (r - g) / delta + 4;
                }
                hue = Math.round(hue * 60);
                if (hue < 0) hue += 360;
                
                // Map hue to rainbow color
                if (hue >= 345 || hue < 15) return 'Red';
                if (hue >= 15 && hue < 45) return 'Orange';
                if (hue >= 45 && hue < 75) return 'Yellow';
                if (hue >= 75 && hue < 165) return 'Green';
                if (hue >= 165 && hue < 195) return 'Cyan';
                if (hue >= 195 && hue < 255) return 'Blue';
                if (hue >= 255 && hue < 285) return 'Purple';
                if (hue >= 285 && hue < 315) return 'Magenta';
                if (hue >= 315 && hue < 345) return 'Pink';
                
                return 'Red';
            }
            
            function showStatCard(char, anchorEl, isLocked = false) {
                if (isLocked) {
                    let hint;
                    if (char.unlockAchievement) {
                        const achievement = achievements[char.unlockAchievement];
                        hint = achievement ? achievement.desc : 'Complete achievements to unlock this character';
                    } else if (char.secretUnlock) {
                        const shopItem = shopItems.find(item => item.id === char.secretUnlock);
                        if (shopItem && shopItemIsEventLocked(shopItem)) {
                            // Sending someone to the Shop for a fighter the Shop
                            // will not sell them yet is worse than telling them
                            // nothing, so the gate is named instead of the price.
                            hint = `Clear The Zero Event to put them on sale — then ${shopItem.cost} credits at the Shop`;
                        } else if (shopItem) {
                            hint = `Purchase from Shop: ${shopItem.description} (Cost: ${shopItem.cost} credits)`;
                        } else {
                            // Special unlock conditions for non-shop secrets
                            const unlockHints = {
                                'charredAnakin': 'Special unlock: Win as Obi-Wan vs Sith Anakin on Mustafar',
                                'senatorPalpatine': 'Special unlock: Win as Darth Maul vs Qui-Gon on Naboo, OR lose as Qui-Gon vs Maul on Naboo',
                                'jabbaUnlock': achievements.jabbaUnlock ? achievements.jabbaUnlock.desc : 'Defeat Jabba after freeing Carbonite Han on Cloud City',
                                'tarffulUnlock': 'Special unlock: Defeat Commander Gree as Yoda on Kashyyyk',
                                'ultimatePalpatine': 'Special unlock: Defeat Sith C-3PO',
                                'geno': 'Special unlock: Win as The Visitor vs Vengeance Jones at the Zero Point — and The Visitor is spent doing it',
                                'wrixel': 'Free with the Zero Event: clear the event and he is on the roster, at no cost and from no shop',
                                // Read off the table that grants them, so the hint
                                // cannot quote a different number from the rule.
                                'lordtreat': `Special unlock: Win ${HALLOWEEN_LORD_UNLOCKS.lordtreat.wins} rounds as General Hawlo`,
                                'lordtrick': `Special unlock: Win ${HALLOWEEN_LORD_UNLOCKS.lordtrick.wins} rounds as General Wheen`,
                            };
                            hint = unlockHints[char.secretUnlock] || 'Unlock through special conditions';
                        }
                    } else {
                        hint = 'Complete achievements to unlock this character';
                    }
                    statCard.innerHTML = `
                        <div class="sc-name" style="color:#666666">🔒 Locked Character</div>
                        <div class="sc-bio" style="margin-top:8px;color:#888888;font-style:italic">"${hint}"</div>
                    `;
                } else {
                    const w = getWeapon(char);
                    const hpPct = Math.round((char.hp / 500) * 100);
                    const tags = [];
                    if (char.isDroid) tags.push('Droid');
                    if (char.isClone) tags.push('Clone');
                    const tagStr = tags.length ? ` <span style="opacity:0.5;font-size:0.7rem">[${tags.join(', ')}]</span>` : '';
                    statCard.innerHTML = `
                        <div class="sc-name" style="color:${char.color}">${weaponEmoji[char.weapon]||'⚔️'} ${char.name}${tagStr}</div>
                        <div class="sc-row"><span>HP</span><span>${char.hp}</span></div>
                        <div class="sc-bar-wrap"><div class="sc-bar-fill" style="width:${hpPct}%;background:${char.color}"></div></div>
                        <div class="sc-row"><span>Weapon</span><span>${w.label}</span></div>
                        <div class="sc-row"><span>Damage</span><span>${w.realityRoll ? '0 – their HP' : `${Math.floor(w.damage * (1 - (w.variance||0)))} – ${Math.ceil(w.damage * (1 + (w.variance||0)))}`}</span></div>
                        <div class="sc-row"><span>Fire Rate</span><span>${w.cooldown > 0 ? Math.round(1000/w.cooldown*10)/10 + '/s' : '∞ (continuous)'}</span></div>
                        ${char.saberColor ? `<div class="sc-row"><span>Saber</span><span style="color:${char.saberColor}">■ ${getRainbowColorName(char.saberColor)}</span></div>` : ''}
                        ${char.bio ? `<div class="sc-bio">${char.bio}</div>` : ''}
                    `;
                }
                const rect = anchorEl.getBoundingClientRect();
                let left = rect.right + 8;
                if (left + 220 > window.innerWidth) left = rect.left - 228;
                statCard.style.left = left + 'px';
                statCard.style.top = Math.min(rect.top, window.innerHeight - 260) + 'px';
                statCard.style.display = 'block';
            }
            function hideStatCard() { statCard.style.display = 'none'; }

            const mainMenu = document.getElementById('mainMenu');
            const splashMenu = document.getElementById('splashMenu');
            const opponentMenu = document.getElementById('opponentMenu');

            // ── SPLASH STAR FIELD ──────────────────────────────────────
            function buildStarField(containerId, count) {
                const container = document.getElementById(containerId);
                if (!container) return;
                for (let i = 0; i < count; i++) {
                    const s = document.createElement('div');
                    s.className = 'splash-star';
                    const size = Math.random() * 2.2 + 0.5;
                    const dur  = (Math.random() * 4 + 2).toFixed(2);
                    const delay = (Math.random() * 6).toFixed(2);
                    const maxOp = (Math.random() * 0.6 + 0.2).toFixed(2);
                    s.style.cssText = `
                        width:${size}px; height:${size}px;
                        left:${Math.random()*100}%; top:${Math.random()*100}%;
                        --dur:${dur}s; --max-opacity:${maxOp};
                        animation-delay:${delay}s;
                    `;
                    container.appendChild(s);
                }
            }
            buildStarField('splashStars', 90);
            buildStarField('loadingStars', 60);

            // ── FREEPLAY BUTTON ────────────────────────────────────────
            // One tile, one job. Freeplay used to double as a Continue tile that
            // resumed the last fighter, arena and difficulty; that is gone, along
            // with the `lastLoadout` record it read.
            const btnFreeplay = document.getElementById('btnFreeplay');
            if (btnFreeplay) {
                btnFreeplay.addEventListener('click', () => { showMainMenu(); });
            }

            // ── SPRITES ───────────────────────────────────────────────────
            // A sprite is a persistent carried powerup, not a per-match pickup:
            // once equipped it stays equipped across rounds, series and sessions
            // until one of exactly two things happens —
            //   1. the player unequips it in Settings ▸ Sprites, or
            //   2. they LOSE it, which is what any defeat costs them — a single
            //      lost round is enough, not just a lost series.
            // A lost sprite leaves the inventory entirely, which is what makes
            // carrying a Mythic one a gamble rather than a straight upgrade.
            //
            // How a sprite is obtained, in order of how it is meant to be met:
            //   - FOUND in battle. Sprites drop as contested pickups at odds set by
            //     their rarity, and the opponent races the player for them.
            //   - BOUGHT BACK, but only after a defeat took one. Sprites are never
            //     otherwise on sale; the listing appears when it is lost and
            //     disappears again the moment it is repurchased.
            //   - GRANTED from the dev menu, for testing. That one button is still
            //     gated on isLocalBuild(), because it is a cheat rather than a way
            //     in — see devGrantBoomBoom.
            //
            // This shipped as a prototype behind isLocalBuild(), so nothing here
            // rendered off-build and isSpriteEquipped() was hard-false whatever the
            // save said. That gate is gone: sprites now drop, equip, apply and are
            // lost on every build. A save file that has been carrying an equipped
            // sprite since the prototype days will therefore start working rather
            // than sitting inert — which also means it can now be lost, so the
            // first defeat after this ships will take it.
            //
            // Kept out of the `shopItems` array on purpose: every entry in that
            // array must unlock a character, and validate.js enforces it.
            // spawnChance is the odds that any given battlefield pickup spawn comes
            // up as this sprite instead of an ordinary health/shield/ammo/spread
            // drop. Rarer means scarcer: a Mythic surfaces on roughly one pickup in
            // twelve, and pickups come every PICKUP_SPAWN_TIME (15s), so it is a
            // few minutes of fighting between sightings. Add rarer tiers below
            // Mythic with smaller numbers as the catalog grows.
            const SPRITE_RARITIES = {
                // Epic sits one step under Mythic and is priced and dropped like it:
                // half again as likely to surface (roughly one pickup in eight rather
                // than one in twelve), and correspondingly cheaper to buy back. An
                // Epic effect should be worth carrying without being worth reshaping
                // a fight around — which for the Fury Sprite is what the roll is for.
                epic:   { label: 'Epic',   color: '#b45cff', spawnChance: 0.12 },
                mythic: { label: 'Mythic', color: '#ff5bd1', spawnChance: 0.08 }
            };

            const SPRITE_CATALOG = [
                {
                    id: 'boomBoom',
                    name: 'Boom Boom',
                    icon: '💥',
                    rarity: 'mythic',
                    cost: 2500,
                    description: 'Every weapon you carry detonates on impact. Each hit you land also blasts every other enemy within range for a share of the damage, falling off with distance.',
                    effect: 'Splash damage on every weapon'
                },
                /*  Drops anywhere, on any arena, like Boom Boom does.
                 *
                 *  It used to be locked to battles on the Unstable Zero Point and to
                 *  saves that had cleared the Zero Event. With that layer gone,
                 *  both of those became unreachable — zeroEventCleared can no
                 *  longer be set by anything, and isArenaRetired() takes zeropoint out
                 *  of the rotation — so between them they made the sprite strictly
                 *  impossible to find. A mythic nobody can obtain is not rare, it is
                 *  absent, so both gates are gone.
                 *
                 *  The creation requirement stays, and is the only one left. It is not
                 *  a leftover from that layer: the whole effect is calling in one of the
                 *  player's own fighters, so a sprite that can do nothing for you
                 *  should not be on the floor tempting you away from cover.        */
                {
                    // The id stays 'zeroSprite'. It is what ownedSprites, lostSprites,
                    // equippedSpriteId, guardianSkinSpriteId and the dev grant are all
                    // keyed on, so renaming it would orphan every save that owns one.
                    // Only the display name changed.
                    id: 'zeroSprite',
                    name: 'Kamino Sprite',
                    icon: '🌀',
                    rarity: 'mythic',
                    cost: 3000,
                    // Named for the cloners, and the effect is the reason: what it does
                    // is stand a copy of one of your own fighters up beside you. The
                    // old wording sent the player to the ruins of the Zero Point, which
                    // is a place they can no longer be.
                    description: 'A clone of something you made at Kamino can be called back to fight beside you, once, when the fight turns. It only ever shows itself to someone who has built a fighter of their own.',
                    effect: 'Chance to call in a clone of one of your own creations',
                    eligible: () => createdCharacters.length > 0
                },

                /*  The first Epic, and the tier is the whole design. It does what the
                 *  Kamino Sprite does — stands somebody up next to you when the fight
                 *  turns — but where that one is Mythic, scarce and certain, this is
                 *  Epic, common and a coin toss. Finding one is easier; relying on it
                 *  is not.
                 *
                 *  No `eligible` gate. The Kamino Sprite needs one because it can only
                 *  call the player's own creations and a player who has built nothing
                 *  would be picking up a brick; the Avengers are on the roster for
                 *  everybody, unlockable by nobody, so this always has someone to
                 *  call.                                                            */
                {
                    id: 'furySprite',
                    name: 'Fury Sprite',
                    icon: '🕶️',
                    rarity: 'epic',
                    cost: 1800,
                    description: 'When you are hurt badly enough to need it, Fury puts the call out. An Avenger may answer and fight beside you for the rest of the round — may, not will. Unless you are Fury: in his own hands it is not a request, and somebody always comes.',
                    effect: 'Chance to call in an Avenger — a certainty as Fury'
                }
            ];

            function getSprite(id) {
                return SPRITE_CATALOG.find(s => s.id === id) || null;
            }

            function spriteRarity(sprite) {
                return SPRITE_RARITIES[sprite && sprite.rarity] || { label: 'Common', color: '#aaa' };
            }

            // Inventory and the single equipped slot. Persisted through
            // galacticDuelSettings so they ride along in exported save files.
            let ownedSprites = {};
            let equippedSpriteId = null;
            // Sprites the player has LOST and may buy back. This is the only thing
            // that puts a sprite in the Shop: it is never on sale otherwise, so a
            // sprite is first obtained by finding it on the battlefield (or from
            // the dev menu), and the Shop is purely a second chance after a defeat.
            // Buying it back clears the flag and the listing vanishes again.
            let lostSprites = {};

            // The sprite whose plating The Guardian is wearing, or null for factory
            // cobalt. Purely cosmetic and entirely separate from equippedSpriteId:
            // fitting a sprite to the mech does not equip it, does not consume it,
            // and does not give the mech its power. Declared up here with the rest
            // of the sprite state because loadGameSettings() restores it long before
            // the Zero Point code that reads it exists.
            let guardianSkinSpriteId = null;
            let wrixelColor = null;

            // Sprites the OPPONENT has picked up. Kept out of the entities so it
            // survives a round change — an enemy that takes the sprite in round one
            // keeps it for the rest of the series, and setupGame clears this when a
            // fresh series starts. Nothing here is ever persisted: the opponent's
            // claim dies with the series, unlike the player's, which is permanent.
            let enemySpriteGrants = {};

            function playerOwnsSprite(id) { return !!ownedSprites[id]; }

            /** Has this sprite ever been in the player's hands? Owning it and having
             *  lost it are the same answer here, because between them they are the
             *  whole history — loseSprite() moves an id from one table to the other
             *  and buying it back moves it straight back, so nothing that was ever
             *  held is missing from both. The Guardian's plating is the only thing
             *  that asks: a skin is a trophy for having carried the sprite, and a
             *  defeat taking the sprite must not also strip the paint. */
            function spriteEverOwned(id) { return !!(ownedSprites[id] || lostSprites[id]); }

            /** The one question every sprite effect must ask: is this sprite both
             *  owned and in the slot? Owning it is not enough — a sprite sitting
             *  unequipped in the inventory does nothing. */
            function isSpriteEquipped(id) {
                return equippedSpriteId === id && !!ownedSprites[id];
            }

            /** Does this fighter have the sprite's power right now? The player's
             *  comes from their equipped slot; anyone else's from a battlefield
             *  pickup that lasts only as long as the series. */
            function entityHasSprite(entity, id) {
                if (!entity) return false;
                if (entity === mainPlayer) return isSpriteEquipped(id);
                return !!(entity.spriteGrants && entity.spriteGrants[id]);
            }

            function grantSprite(id) {
                const sprite = getSprite(id);
                if (!sprite) return;
                ownedSprites[id] = true;
                saveGameSettings();
                renderShopItems();
                renderSpritesOverlay();
            }

            /** Removes a sprite from the inventory outright — the "lose it" path.
             *  Unequips first so nothing keeps pointing at a sprite that's gone,
             *  and flags it for buy-back, which is what puts it in the Shop. */
            function loseSprite(id) {
                if (!ownedSprites[id]) return;
                delete ownedSprites[id];
                if (equippedSpriteId === id) equippedSpriteId = null;
                // The arena rather than a bare `true`, so the Shop tile can say where
                // it went. Still truthy, so buyableSprites() and every older save that
                // stored `true` keep working unchanged.
                lostSprites[id] = currentArena || true;
                saveGameSettings();
                renderShopItems();
                renderSpritesOverlay();
            }

            /** Sprites currently on sale — only ones the player has lost. */
            /** A vaulted sprite is out of circulation: it cannot drop, cannot be
             *  bought back, and cannot be granted. It is deliberately NOT checked by
             *  playerOwnsSprite/isSpriteEquipped — one already in a save keeps working
             *  exactly as before, because vaulting stops the handing out and nothing
             *  else. */
            function isSpriteVaulted(sprite) { return !!(sprite && sprite.vaulted); }

            function buyableSprites() {
                return SPRITE_CATALOG.filter(s =>
                    !isSpriteVaulted(s) && lostSprites[s.id] && !playerOwnsSprite(s.id));
            }

            /** Someone walked onto a sprite drop. The two sides keep it on very
             *  different terms, which is the whole tension of contesting one:
             *
             *   - The PLAYER keeps it for good. It enters the collection equipped,
             *     exactly as if bought, and is theirs until they unequip or lose it.
             *   - The OPPONENT only borrows it, for this match and the rest of the
             *     series. Nothing is persisted for them and setupGame drops it when
             *     a new series begins.
             *
             *  Taking it also clears any pending buy-back: recovering it by hand on
             *  the field means there is nothing left to repurchase. */
            function claimSpritePickup(entity, spriteId) {
                const sprite = getSprite(spriteId);
                if (!sprite) return;
                const rarity = spriteRarity(sprite);
                spawnHitSparks(entity.x, entity.y, rarity.color, 18);
                spawnBoomBlast(entity.x, entity.y, 90);

                if (entity === mainPlayer) {
                    delete lostSprites[spriteId];
                    grantSprite(spriteId);
                    equipSprite(spriteId, { silent: true });
                    showAnnouncement(`${sprite.name} is yours — ${sprite.effect.toLowerCase()}. It stays with you after the match, until you unequip it or lose one.`,
                        rarity.color, 5000, `${sprite.icon} SPRITE CLAIMED`, 100, true);
                    return;
                }

                enemySpriteGrants[spriteId] = true;
                entity.spriteGrants = entity.spriteGrants || {};
                entity.spriteGrants[spriteId] = true;
                showAnnouncement(`${entity.name} reached ${sprite.name} first — ${sprite.effect.toLowerCase()}, for the rest of this series.`,
                    rarity.color, 5000, `${sprite.icon} OPPONENT CLAIMED IT`, 100, true);
            }

            // `silent` is for equipping mid-battle off a pickup, where
            // claimSpritePickup raises its own forced announcement instead. The
            // normal one would be queued behind the match and surface minutes
            // later, describing something the player did long ago.
            function equipSprite(id, opts = {}) {
                if (!ownedSprites[id]) return;
                equippedSpriteId = id;
                saveGameSettings();
                renderSpritesOverlay();
                if (opts.silent) return;
                const sprite = getSprite(id);
                showAnnouncement(`${sprite.name} equipped — ${sprite.effect}. Lose a single match while carrying it and it is gone.`,
                    spriteRarity(sprite).color, 5000, `${sprite.icon} SPRITE EQUIPPED`, 100);
            }

            function unequipSprite() {
                const sprite = getSprite(equippedSpriteId);
                if (!sprite) return;
                equippedSpriteId = null;
                saveGameSettings();
                renderSpritesOverlay();
                showAnnouncement(`${sprite.name} unequipped. It stays in your collection.`,
                    spriteRarity(sprite).color, 3500, '✨ SPRITE');
            }

            // Settings ▸ Sprites — the unequip menu.
            const spritesOverlay = document.getElementById('spritesOverlay');
            const spritesList = document.getElementById('spritesList');
            const spritesEmpty = document.getElementById('spritesEmpty');
            const spritesBtn = document.getElementById('spritesBtn');
            const spritesCloseBtn = document.getElementById('spritesCloseBtn');

            function renderSpritesOverlay() {
                if (!spritesList) return;
                const owned = SPRITE_CATALOG.filter(s => playerOwnsSprite(s.id));
                spritesList.innerHTML = '';
                if (spritesEmpty) {
                    spritesEmpty.style.display = owned.length ? 'none' : 'block';
                    // Only send them to the Shop when there is genuinely something
                    // waiting there. Sprites are never on general sale — the Shop
                    // lists one solely as a buy-back after a defeat took it — so
                    // this line is right for a player who has just lost theirs and
                    // wrong for one who has never owned any. buyableSprites() is
                    // the same source the Shop itself renders from, so the two can
                    // never disagree about whether that listing exists.
                    spritesEmpty.textContent = buyableSprites().length
                        ? 'You own no sprites. Buy one back in the Shop.'
                        : 'You own no sprites.';
                }

                owned.forEach(sprite => {
                    const rarity = spriteRarity(sprite);
                    const equipped = equippedSpriteId === sprite.id;

                    const row = document.createElement('div');
                    row.style.cssText = `
                        background: rgba(255,255,255,0.05);
                        border: 1px solid ${equipped ? rarity.color : '#666'};
                        border-radius: 8px;
                        padding: 12px;
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                        gap: 12px;
                    `;
                    row.innerHTML = `
                        <div style="flex:1;">
                            <div style="font-family:${getUiFontStack()};font-size:0.9rem;color:${equipped ? rarity.color : '#fff'};margin-bottom:4px;">
                                ${sprite.icon} ${sprite.name}
                                <span style="font-size:0.65rem;letter-spacing:1px;color:${rarity.color};">— ${rarity.label.toUpperCase()}</span>
                            </div>
                            <div style="font-size:0.75rem;color:rgba(255,255,255,0.6);">${sprite.description}</div>
                        </div>
                        <button
                            class="sprite-equip-btn"
                            style="
                                background: ${equipped ? 'none' : rarity.color};
                                color: ${equipped ? rarity.color : '#000'};
                                border: 1px solid ${rarity.color};
                                border-radius: 6px;
                                padding: 8px 16px;
                                font-family:${getUiFontStack()};
                                font-size: 0.8rem;
                                cursor: pointer;
                                font-weight: bold;
                                white-space: nowrap;
                            "
                        >${equipped ? 'UNEQUIP' : 'EQUIP'}</button>
                    `;
                    row.querySelector('.sprite-equip-btn').addEventListener('click', () => {
                        if (equipped) unequipSprite(); else equipSprite(sprite.id);
                    });
                    spritesList.appendChild(row);
                });
            }

            /** Sprites is a normal Settings entry on every build now. The dev grant
             *  button beside it is not — that one hands you a Mythic for free, so it
             *  stays local-only. */
            function updateSpritesUiVisibility() {
                if (spritesBtn) spritesBtn.style.display = 'block';
                const local = isLocalBuild();
                ['devGrantBoomBoom', 'devGrantZeroSprite', 'devGrantShapelessSprite',
                 'devGrantFurySprite'].forEach(id => {
                    const btn = document.getElementById(id);
                    if (btn) btn.style.display = local ? 'block' : 'none';
                });
            }

            if (spritesBtn) {
                spritesBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    renderSpritesOverlay();
                    spritesOverlay.style.display = 'flex';
                });
            }
            if (spritesCloseBtn) {
                spritesCloseBtn.addEventListener('click', () => { spritesOverlay.style.display = 'none'; });
            }
            if (spritesOverlay) {
                spritesOverlay.addEventListener('click', (e) => {
                    if (e.target === spritesOverlay) spritesOverlay.style.display = 'none';
                });
            }

            // ── SHOP BUTTON ───────────────────────────────────────────────
            const shopOverlay = document.getElementById('shopOverlay');
            const shopCloseBtn = document.getElementById('shopCloseBtn');
            const shopItemsContainer = document.getElementById('shopItems');

            const shopItems = [
                { id: 'shaagi', name: "Sha'a Gi", cost: 75, description: "Unlocks Sha'a Gi with lightsaber weapon" },
                { id: 'thorn', name: 'Commander Thorn', cost: 200, description: 'Unlocks Commander Thorn with minigun weapon' },
                { id: 'pazvizsla', name: 'Paz Vizsla', cost: 250, description: 'Unlocks Paz Vizsla with minigun weapon (higher HP than Thorn)' },
                { id: 'fox_elite', name: 'Commander Fox (Elite)', cost: 1200, description: 'Unlocks Commander Fox (Elite) with the continuous-fire Beam weapon — the strongest weapon in the game' },
                // The season’s one paid fighter. No `packId` — that field marks a
                // fighter as belonging to a content pack, and would take him out
                // with a pack he has nothing to do with. 900 puts him between The Guardian's 750
                // and Commander Fox's 1200, which is where the third-hardest gun in
                // the game belongs: under the Beam, over everything automatic.
                { id: 'starlord', name: 'Star-Lord', cost: 900, description: 'Unlocks Star-Lord and the Quad Blasters — four rounds a pull, and every one of them explodes where it lands' },
                { id: 'sithAnakin', name: 'Sith Anakin', cost: 450, description: 'Unlocks Sith Anakin — Anakin the moment he turned, a shade below Charred Anakin. You can fight him on Mustafar without owning him.' },
                // 2000: second only to the Dev Team, which is where the owner put
                // him. It is also what the Snap is worth. Nothing else in the
                // Shop sells a button that can end a round outright, and the
                // next dearest fighter, Fox (Elite) at 1200, buys the strongest
                // gun — the Snap is a bigger thing than any gun.
                { id: 'thanos', name: 'Thanos', cost: 2000, description: 'Unlocks Thanos and the Infinity Gauntlet — and the Snap on Interact, a coin toss that ends whoever it lands on' },
                { id: 'devTeam', name: 'Dev Team', cost: 3000, description: 'Unlocks Cousin Crew character in secret characters' },
                // The dearest thing in the Shop, by the owner's call, and the gap
                // over the Dev Team is deliberate. What 5000 buys is an ally on
                // demand for the whole round, drawn from both Marvel columns,
                // plus a staff whose every hit is a dice roll on the target's
                // own health bar. Nothing else sold here is a second fighter.
                { id: 'eternity', name: 'Eternity', cost: 5000, description: 'Unlocks Eternity and the Reality Staff, whose every hit rolls anywhere from nothing to all of the target\'s health — and on Interact, a fighter from either Marvel column to fight beside her, one at a time, with no cooldown' }
            ];

            /** Is the fighter this shop entry sells off the roster for good?
             *
             *  A shop item and the character it unlocks are joined only by the
             *  `secretUnlock` key, so retirement has to be looked up through it —
             *  the item itself knows nothing about who it grants. */
            function shopItemIsRetired(item) {
                const all = [...characters.heroes, ...characters.villains, ...characters.secret];
                const granted = all.filter(c => c.secretUnlock === item.id);
                return granted.length > 0 && granted.every(isCharacterRetired);
            }

            /** Is this entry one the Zero Event has to be cleared for first?
             *
             *  The mirror of `shopItemIsRetired`: that one delists a fighter the
             *  event has ended, this one holds back a fighter the event has yet to
             *  bring in. Both read the same `zeroEventCleared` flag from opposite
             *  sides, and between them the pack half of the Shop is entirely
             *  before-or-after. */
            function shopItemIsEventLocked(item) {
                return !!item.requiresZeroEvent && !gameUnlocks.zeroEventCleared;
            }

            function renderShopItems() {
                shopItemsContainer.innerHTML = '';
                shopItems.forEach(item => {
                    // Every item is on sale, pack entries included — `item.packId` now
                    // only records which pack an entry came from, and no longer
                    // decides whether it is listed.
                    //
                    // Retirement is the one thing that does delist an entry. The shop
                    // had no idea characters could be retired, so after the Zero Event
                    // it went on selling The Voidblade, Cluster, Geno and the rest —
                    // fighters the story had already ended. Buying one took the
                    // credits, set the flag and delivered nobody, because every roster
                    // that could have shown them filters retirement out.
                    if (shopItemIsRetired(item)) return;
                    // Vaulted: the pack is out of rotation, so it is off the shelf
                    // whether or not the fighter it grants is retired. Already-bought
                    // entries are gone from here too, but only because a purchased
                    // fighter needs no shop row — the save keeps the flag and the
                    // roster keeps the fighter.
                        const isPurchased = gameUnlocks[item.id];
                    const eventLocked = shopItemIsEventLocked(item);
                    // A locked entry never reads as affordable, however many
                    // credits are banked. Folding the gate in here is what makes
                    // the border, the button colour, the cursor and the click
                    // handler below all agree without four separate checks.
                    const canAfford = !eventLocked && credits >= item.cost;
                    
                    const itemEl = document.createElement('div');
                    itemEl.style.cssText = `
                        background: rgba(255,255,255,0.05);
                        border: 1px solid ${isPurchased ? '#44ff44' : canAfford ? '#ffd700' : '#666'};
                        border-radius: 8px;
                        padding: 12px;
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                        gap: 12px;
                    `;
                    
                    itemEl.innerHTML = `
                        <div style="flex:1;">
                            <div style="font-family:${getUiFontStack()};font-size:0.9rem;color:${isPurchased ? '#44ff44' : eventLocked ? 'rgba(255,255,255,0.5)' : '#fff'};margin-bottom:4px;">
                                ${eventLocked ? '🔒 ' : ''}${item.name} ${isPurchased ? '✓' : ''}
                            </div>
                            <div style="font-size:0.75rem;color:rgba(255,255,255,0.6);">${item.description}</div>
                            ${eventLocked ? `<div style="font-size:0.7rem;color:#a274ff;margin-top:5px;letter-spacing:0.5px;">⬢ Locked — clear The Zero Event to put them on sale.</div>` : ''}
                        </div>
                        <button 
                            class="shop-purchase-btn"
                            data-item-id="${item.id}"
                            data-cost="${item.cost}"
                            style="
                                background: ${isPurchased ? '#44ff44' : canAfford ? '#ffd700' : '#666'};
                                color: ${isPurchased || canAfford ? '#000' : '#888'};
                                border: none;
                                border-radius: 6px;
                                padding: 8px 16px;
                                font-family:${getUiFontStack()};
                                font-size: 0.8rem;
                                cursor: ${isPurchased || eventLocked ? 'default' : canAfford ? 'pointer' : 'not-allowed'};
                                font-weight: bold;
                            "
                            ${isPurchased || eventLocked ? 'disabled' : ''}
                        >
                            ${isPurchased ? 'PURCHASED' : eventLocked ? '🔒 LOCKED' : `${item.cost} CR`}
                        </button>
                    `;
                    
                    if (!isPurchased && canAfford) {
                        itemEl.querySelector('.shop-purchase-btn').addEventListener('click', () => purchaseShopItem(item));
                    }
                    
                    shopItemsContainer.appendChild(itemEl);
                });

                renderSpriteShopItems();
                renderHalloweenReviveItems();
            }

            // Sprites are NOT normally on sale. This block is purely a buy-back
            // counter: it is empty — heading and all — until a defeat takes a
            // sprite off the player, and it empties again the moment they buy it
            // back. A sprite the player has never owned is found in battle, not
            // bought.
            function renderSpriteShopItems() {
                const forSale = buyableSprites();
                if (forSale.length === 0) return;

                const heading = document.createElement('div');
                heading.style.cssText = `font-family:${getUiFontStack()};font-size:0.7rem;letter-spacing:2px;color:rgba(255,255,255,0.35);margin-top:8px;`;
                heading.textContent = '✨ RECOVER LOST SPRITE';
                shopItemsContainer.appendChild(heading);

                forSale.forEach(sprite => {
                    const rarity = spriteRarity(sprite);
                    const owned = playerOwnsSprite(sprite.id);
                    const canAfford = credits >= sprite.cost;

                    const el = document.createElement('div');
                    el.style.cssText = `
                        background: rgba(255,255,255,0.05);
                        border: 1px solid ${owned ? '#44ff44' : canAfford ? rarity.color : '#666'};
                        border-radius: 8px;
                        padding: 12px;
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                        gap: 12px;
                    `;
                    el.innerHTML = `
                        <div style="flex:1;">
                            <div style="font-family:${getUiFontStack()};font-size:0.9rem;color:${owned ? '#44ff44' : '#fff'};margin-bottom:4px;">
                                ${sprite.icon} ${sprite.name} ${owned ? '✓' : ''}
                                <span style="font-size:0.65rem;letter-spacing:1px;color:${rarity.color};">— ${rarity.label.toUpperCase()} SPRITE</span>
                            </div>
                            <div style="font-size:0.75rem;color:rgba(255,255,255,0.6);">${sprite.description}</div>
                        </div>
                        <button
                            class="sprite-purchase-btn"
                            style="
                                background: ${owned ? '#44ff44' : canAfford ? rarity.color : '#666'};
                                color: ${owned || canAfford ? '#000' : '#888'};
                                border: none;
                                border-radius: 6px;
                                padding: 8px 16px;
                                font-family:${getUiFontStack()};
                                font-size: 0.8rem;
                                cursor: ${owned ? 'default' : canAfford ? 'pointer' : 'not-allowed'};
                                font-weight: bold;
                            "
                            ${owned ? 'disabled' : ''}
                        >${owned ? 'OWNED' : `${sprite.cost} CR`}</button>
                    `;
                    if (!owned && canAfford) {
                        el.querySelector('.sprite-purchase-btn').addEventListener('click', () => purchaseSprite(sprite));
                    }
                    shopItemsContainer.appendChild(el);
                });
            }

            function purchaseSprite(sprite) {
                if (credits < sprite.cost) return;
                if (playerOwnsSprite(sprite.id)) return;

                credits -= sprite.cost;
                // Recovered — it leaves the Shop again until it is lost anew.
                delete lostSprites[sprite.id];
                // grantSprite saves and re-renders both the Shop and the Sprites menu.
                grantSprite(sprite.id);
                updateCreditsDisplay();

                const rarity = spriteRarity(sprite);
                showAnnouncement(`${sprite.name} is yours. Equip it in Settings ▸ Sprites.`,
                    rarity.color, 5000, `${sprite.icon} ${rarity.label.toUpperCase()} SPRITE ACQUIRED`, 100);
            }

            /*  Fallen Halloween fighters. Like the sprite buy-back above, the block
             *  is empty — heading and all — until a run has cost someone, and empties
             *  again the moment they are bought back. Not a shopItems entry: those
             *  are unlocks keyed to secretUnlock, and a revive is neither. Prices
             *  are HALLOWEEN_WORTH less 5%, worked out up by gameUnlocks.          */
            function renderHalloweenReviveItems() {
                const fallen = Object.keys(halloweenFallen).map(findRosterChar).filter(Boolean);
                if (!fallen.length) return;

                const heading = document.createElement('div');
                heading.style.cssText = `font-family:${getUiFontStack()};font-size:0.7rem;letter-spacing:2px;color:rgba(255,255,255,0.35);margin-top:8px;`;
                heading.textContent = '🎃 REVIVE A FALLEN FIGHTER';
                shopItemsContainer.appendChild(heading);

                fallen.forEach(char => {
                    const cost = halloweenRevivePrice(char.id);
                    const canAfford = credits >= cost;
                    const el = document.createElement('div');
                    el.style.cssText = `
                        background: rgba(255,255,255,0.05);
                        border: 1px solid ${canAfford ? '#ff8c1a' : '#666'};
                        border-radius: 8px;
                        padding: 12px;
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                        gap: 12px;
                    `;
                    el.innerHTML = `
                        <div style="flex:1;">
                            <div style="font-family:${getUiFontStack()};font-size:0.9rem;color:#fff;margin-bottom:4px;">
                                💀 ${char.name}
                                <span style="font-size:0.65rem;letter-spacing:1px;color:#ff8c1a;">— FELL IN THE HALLOWEEN EVENT</span>
                            </div>
                            <div style="font-size:0.75rem;color:rgba(255,255,255,0.6);">Buy them back and they return to every roster, ready for the next run.</div>
                        </div>
                        <button
                            class="revive-purchase-btn"
                            style="
                                background: ${canAfford ? '#ff8c1a' : '#666'};
                                color: ${canAfford ? '#000' : '#888'};
                                border: none;
                                border-radius: 6px;
                                padding: 8px 16px;
                                font-family:${getUiFontStack()};
                                font-size: 0.8rem;
                                cursor: ${canAfford ? 'pointer' : 'not-allowed'};
                                font-weight: bold;
                            "
                        >${cost} CR</button>
                    `;
                    if (canAfford) {
                        el.querySelector('.revive-purchase-btn').addEventListener('click', () => reviveHalloweenFighter(char));
                    }
                    shopItemsContainer.appendChild(el);
                });
            }

            function reviveHalloweenFighter(char) {
                const cost = halloweenRevivePrice(char.id);
                if (!isHalloweenFallen(char.id) || credits < cost) return;
                credits -= cost;
                delete halloweenFallen[char.id];
                persistHalloweenFallen();
                saveGameSettings();
                updateCreditsDisplay();
                renderShopItems();
                rebuildAllRosters();
                updateSecretFactionSectionVisibility();
                showAnnouncement(`${char.name} is back on the roster.`, char.color, 4000, '🎃 REVIVED', 100);
            }

            // Shop id → how the unlock is announced. Keyed off the shop entry
            // rather than the character so an entry whose name differs from the
            // character it grants (devTeam → Cousin Crew) still reads correctly.
            const shopUnlockAnnouncements = {
                shaagi:         { name: "Sha'a Gi",                  color: '#33ff66' },
                thorn:          { name: 'Commander Thorn',           color: '#ff0000' },
                pazvizsla:      { name: 'Paz Vizsla',                color: '#4a5560' },
                fox_elite:      { name: 'Commander Fox (Elite)',     color: '#cc0000' },
                cluster:        { name: 'Cluster',                   color: '#ffc93c' },
                voidblade:      { name: 'The Voidblade',             color: '#a45cff' },
                dylan:          { name: 'Dylan',                     color: '#ff4d94' },
                visitor:        { name: 'The Visitor',               color: '#ff9d2e' },
                vengeancejones: { name: 'Vengeance Jones',           color: '#d8b48a' },
                order:          { name: 'The Order',                 color: '#dd2b3e' },
                rivalhope:      { name: 'Rival Hope',                color: '#2fbfa0' },
                prophecy:       { name: 'The Prophecy',              color: '#6ff2d4' },
                slone:          { name: 'Doctor Slone',              color: '#a8482a' },
                innovation:     { name: 'The Innovation',            color: '#e2723f' },
                singularity:    { name: 'The Singularity',           color: '#6d5cf0' },
                phantom:        { name: 'Phantom',                   color: '#5a6875' },
                bastian:        { name: 'Bastian',                   color: '#1f8f85' },
                sonic:          { name: 'Sonic',                     color: '#2a8fef' },
                big_chuggus:    { name: 'Big Chuggus',               color: '#3fe0d0' },
                poseidon:       { name: 'Poseidon',                  color: '#1aa5c9' },
                hush:           { name: 'Hush',                      color: '#ff2a3c' },
                guardian:       { name: 'The Guardian',              color: '#4d8bf0' },
                sithAnakin:     { name: 'Sith Anakin',               color: '#8b0000' },
                // Star-Lord was missing from this table, so buying him took the
                // credits in silence — the one purchase with no unlock banner.
                starlord:       { name: 'Star-Lord',                 color: '#c9553d' },
                thanos:         { name: 'Thanos',                    color: '#7b5ea7' },
                eternity:       { name: 'Eternity',                  color: '#6f86ff' },
                devTeam:        { name: 'Cousin Crew',               color: '#808080' }
            };

            function purchaseShopItem(item) {
                if (credits < item.cost) return;
                if (gameUnlocks[item.id]) return;
                // Nothing in the UI can reach either of these -- a locked entry's
                // button is never wired up, and a vaulted one is never drawn. They
                // are here so the rules live with the purchase rather than only with
                // the drawing of it.
                if (shopItemIsEventLocked(item)) return;
                
                credits -= item.cost;
                gameUnlocks[item.id] = true;
                persistGalacticUnlocks();
                saveGameSettings();
                updateCreditsDisplay();
                renderShopItems();

                // Every shop entry unlocks a character, and which roster that
                // character lives in is an implementation detail of the roster
                // data, not of the purchase. Rebuilding all three (plus the
                // secret section's visibility) is what makes a purchase show up
                // on the splash screen immediately — the per-item rebuilds this
                // replaced covered only some of the entries, so buying Thorn,
                // Paz Vizsla, Sha'a Gi, Fox (Elite), Vengeance Jones or The Order
                // left the roster stale until the page was reloaded.
                rebuildAllRosters();
                updateSecretFactionSectionVisibility();

                const unlocked = shopUnlockAnnouncements[item.id];
                if (unlocked) {
                    // A pack fighter is not on the roster the moment you buy
                    // them — they are only ever in the two faction columns with
                    // the season toggle on. Without this line the purchase
                    // reads as broken: the toast says unlocked, the roster shows
                    // nothing new, and the toggle that would reveal them may have
                    // only just appeared for the first time.
                    const where = item.packId
                        ? ` Switch the season toggle on above either faction to field them.`
                        : '';
                    showAnnouncement(`${unlocked.name} has been unlocked!${where}`, unlocked.color, item.packId ? 6000 : 4000, '🔓 CHARACTER UNLOCKED', 100);
                }
            }

            // Kamino inherits fighter-building from the retired Zero Point, which
            // is what makes "your creations transfer" true rather than a promise:
            // it is the same screen and the same galacticDuelCreations record, so
            // everything already made is listed, editable and playable there.
            const btnKamino = document.getElementById('btnKamino');
            if (btnKamino) btnKamino.addEventListener('click', openCreator);

            const btnShop = document.getElementById('btnShop');
            if (btnShop) {
                btnShop.addEventListener('click', () => {
                    updateCreditsDisplay();
                    renderShopItems();
                    // Everything on the shelf has now been shown, so the tile's
                    // "n new" pill only counts what is listed after this.
                    markShopSeen();
                    shopOverlay.style.display = 'flex';
                });
            }
            shopCloseBtn.addEventListener('click', () => {
                shopOverlay.style.display = 'none';
                refreshSplashState();   // a purchase changes credits and the sub-line
            });
            shopOverlay.addEventListener('click', (e) => {
                if (e.target === shopOverlay) shopOverlay.style.display = 'none';
            });

            // Credits overlay
            const creditsOverlay = document.getElementById('creditsOverlay');
            const creditsCloseBtn = document.getElementById('creditsCloseBtn');
            // Credits moved off the splash menu into Settings when the splash
            // went to a 2x2 tile grid — the fourth tile is the Zero Point now.
            const creditsBtn = document.getElementById('creditsBtn');
            if (creditsBtn) {
                creditsBtn.addEventListener('click', () => {
                    setSettingsOpen(false);
                    creditsOverlay.style.display = 'flex';
                });
            }
            creditsCloseBtn.addEventListener('click', () => {
                creditsOverlay.style.display = 'none';
            });
            creditsOverlay.addEventListener('click', (e) => {
                if (e.target === creditsOverlay) creditsOverlay.style.display = 'none';
            });

            const vsBannerPlayer = document.getElementById('vsBannerPlayer');
            const surpriseBtn = document.getElementById('surpriseBtn');
            const backBtn = document.getElementById('backBtn');
            const messageOverlay = document.getElementById('messageOverlay');

            const defaultMenuMusicSrc = 'music/CantinaBand.mp3';
            const defaultBattleMusicSrc = 'music/DueloftheFates.mp3';
            // ── MARVEL SOUNDTRACK ──────────────────────────────────────
            // One lobby track, one battle track, switched on and off in Settings
            // and off by default — Star Wars is what plays until it is asked for.
            // A single battle track means updateMusicSources() sets the src once
            // and playBattleMusic() just plays it; there is no rotation to manage.
            // A missing src fails silently: play() rejects and the .catch(() => {})
            // below swallows it, so the symptom is no music rather than an error.
            const marvelMenuMusicSrc   = 'music/HelpArrives.mp3';
            const marvelBattleMusicSrc = 'music/AvengersUnite.mp3';
            /*  VAULTED: FOUR MUSIC TRACKS.
             *  The two pairs this switch
             *  used to carry. Nothing selects them: the switch plays Marvel, and off
             *  plays Star Wars.
             *
             *  The four audio files are NOT in music/ and that is deliberate — together
             *  they outweighed the rest of the game, and all four are freely
             *  downloadable, so shipping them bought nothing. What is kept here is the
             *  part worth keeping: which track played where. Dropping the four files
             *  back into music/ under these names is the whole of restoring them.
             *
             *  Left as declared constants rather than deleted so the mapping survives
             *  and so a future switch can name them without anyone having to work out
             *  what used to play. Do not wire them to an <audio> without checking the
             *  files are actually present — a missing src fails silently, and the
             *  symptom is no music rather than an error.                            */

            // The season soundtrack is a preference and nothing else. There is no
            // flag that unlocks it and it gates no content.
            //
            // What it decides is whether the season tracks
            // play instead of the Star Wars ones. It is audio and nothing else, it
            // gates no content, and it starts OFF so a new player hears Cantina
            // Band and Duel of the Fates first. A save that had it on keeps it on.
            let marvelSoundtrackEnabled = false;
            // Which universe the two main-menu columns are showing. A pure view
            // preference — see packFactionViewActive().
            let packFactionsEnabled = false;
            // Same preference, for the Marvel season. Separate flags rather than one
            // "which season" string so a save written before this reads as off
            // without a migration.
            let marvelFactionsEnabled = false;
            // And the Halloween season, on its own flag for the same reason.
            let halloweenFactionsEnabled = false;
            let aurebeshEnabled = false;
            let aurebeshUnlocked = false;
            let musicVolume = 0.55;
            let sfxVolume   = 1.0; // 0–1 multiplier; declared here so loadGameSettings() can read it
            let credits = 0;
            /*  A ceiling on EARNING, not a ceiling on the balance.
             *
             *  Every award site used to read `credits = Math.min(5000, credits + n)`,
             *  which is a different rule: it confiscates. A balance can sit above
             *  the cap legitimately — the two refund paths (the Armory at
             *  scrapCreation, the Creator at its own refund) hand back what a build
             *  cost without clamping, and the dev slider goes to 100000 — and the
             *  next coin earned then slammed the whole balance down to the cap.
             *  Anyone banked above it lost the difference the moment they won a
             *  series, claimed a contract or cleared an achievement.
             *
             *  The Math.max is the whole fix: an award can carry a balance up to
             *  the cap and never past it, and can never take a credit off someone
             *  already over it. Returns what was actually added, so a banner
             *  cannot promise +25 and hand over 5.
             *
             *  The cap itself was 5000, which is under two of the dearest thing
             *  the Shop sells (3000) — tight enough that a player saving for a
             *  second one met the ceiling and watched awards stop counting.
             *  100000 is the number the dev slider already used, and it is far
             *  enough above the whole catalogue that ordinary play never reaches
             *  it; it is here to stop a total running away, not to ration.    */
            const CREDIT_CAP = 100000;
            function awardCredits(amount) {
                const before = credits;
                credits = Math.max(credits, Math.min(CREDIT_CAP, credits + amount));
                return credits - before;
            }
            /** The banner for an award, which has to be able to say "none". */
            function creditAwardLine(gained) {
                return gained > 0
                    ? `+${gained} Credits Earned!`
                    : `Credits full — ${CREDIT_CAP.toLocaleString()} is the cap`;
            }
            // The tester code this browser unlocked the dev menu with, kept so it can
            // be checked again on every load. devCodeVerified is the answer to that
            // check; it starts false and turns true once the fingerprint matches.
            let devAccessCode = '';
            let devCodeVerified = false;
            // Systems/tech settings
            let performanceMode = 'high'; // 'low' | 'balanced' | 'high'
            let reducedMotion = false;
            let showFpsMeter = false;
            const osPrefersReducedMotion = (() => {
                try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; }
                catch (e) { return false; }
            })();
            // Particle/effect caps declared early so applyPerformanceMode() never hits a TDZ error
            let MAX_HIT_SPARKS = 80;
            let MAX_IMPACT_PARTICLES = 140;
            let MAX_SABER_TRAILS = 60;
            let MAX_DEATH_PARTICLES = 80;
            let MAX_FLOATS = 60;
            let MAX_CLASH_PARTICLES = 120;
            const MAX_BULLETS = 200;

            // ── TESTER CODES ───────────────────────────────────────────
            // Players vetted over Discord are sent a personal code, and entering it
            // in Settings opens the dev menu on any host, itch.io included.
            //
            // The codes themselves are not in this file. Each entry is a PBKDF2
            // fingerprint of one code (SHA-256, the salt below, 100,000 rounds), so
            // reading the source gives nothing to type in, and the rounds make
            // guessing slow. It used to be a list of itch.io usernames in plain
            // text, one of them the studio's own public account name.
            //
            // To add a tester, make a fingerprint of their code (upper case,
            // letters and digits only) with the same settings and add a row. To
            // take someone's access away, delete their row: their saved code
            // stops matching on the next load.
            const DEV_TESTER_CODES = [
                { who: 'commanderfox77', fingerprint: '392b5f86ab8636795a291fa8dea75999f20b330cbd185a8b45309af3aa917a51' },
                { who: 'Cousin Crew Studios', fingerprint: 'c8536951789ee9ec04204b59a90ba90c2e66e6142a9d49a7f3c5cfc9f0537c99' },
            ];
            const DEV_CODE_SALT = 'galactic-legends/dev-menu/v1';
            const DEV_CODE_ROUNDS = 100000;

            /** Case, spaces and dashes are ignored: "ab-12 " and "AB12" are one code. */
            function normalizeDevCode(raw) {
                return String(raw || '').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 64);
            }

            /** Resolves true when the code's fingerprint is on the list. Async because
             *  the browser's own crypto is; it needs a secure page (https, which
             *  itch.io is, or localhost), and anywhere else no code is accepted. */
            async function isValidDevCode(raw) {
                const code = normalizeDevCode(raw);
                if (!code || !(window.crypto && crypto.subtle)) return false;
                try {
                    const enc = new TextEncoder();
                    const key = await crypto.subtle.importKey('raw', enc.encode(code), 'PBKDF2', false, ['deriveBits']);
                    const bits = await crypto.subtle.deriveBits(
                        { name: 'PBKDF2', salt: enc.encode(DEV_CODE_SALT), iterations: DEV_CODE_ROUNDS, hash: 'SHA-256' },
                        key, 256);
                    const fingerprint = [...new Uint8Array(bits)].map(b => b.toString(16).padStart(2, '0')).join('');
                    return DEV_TESTER_CODES.some(t => t.fingerprint === fingerprint);
                } catch (e) {
                    return false;
                }
            }

            function isDevMenuVerifiedUser() {
                return devCodeVerified;
            }

            function isItchHost() {
                const h = (location.hostname || '').toLowerCase();
                return h.endsWith('itch.io') || h.endsWith('itch.zone');
            }

            function effectsEnabled() {
                return !reducedMotion && performanceMode !== 'low';
            }

            // Touch/phone detection. Used both to pick a sane default graphics
            // preset and to cap the canvas device-pixel-ratio on mobile.
            function isCoarsePointer() {
                try {
                    if (window.matchMedia('(pointer: coarse)').matches) return true;
                } catch (e) {}
                return (navigator.maxTouchPoints || 0) > 0 && Math.min(window.innerWidth, window.innerHeight) <= 900;
            }

            // First-run graphics preset. 'high' is the right default on a desktop
            // GPU and completely wrong on a phone, where full-resolution glow work
            // drops the game to single-digit framerates.
            function detectDefaultPerformanceMode() {
                try {
                    const cores = navigator.hardwareConcurrency || 8;
                    const mem   = navigator.deviceMemory || 8;
                    if (isCoarsePointer()) return (cores <= 4 || mem <= 4) ? 'low' : 'balanced';
                    if (cores <= 4 && mem <= 4) return 'balanced';
                } catch (e) {}
                return 'high';
            }

            // Particle arrays live at module scope so applyPerformanceMode never hits TDZ.
            // (They used to be declared much later; typeof on a later `let` still throws.)
            let hitSparks = [];
            let impactParticles = [];
            let saberTrails = [];
            let clashParticles = [];
            let deathParticles = [];
            // Expanding shockwave rings from the Boom Boom sprite's detonations.
            let boomBlasts = [];
            let floatNums = [];

            /** Find a free spot for a floating number on its first frame.
             *
             *  Every spawn site drops its number at the same point over the head,
             *  give or take ten pixels of jitter, so a saber combo, a burn tick
             *  and a trooper's bolt landing together printed "13", "11" and "10"
             *  on top of each other as one unreadable smudge. Fixing it here, once,
             *  on the draw side covers all fourteen spawn sites without touching
             *  any of them.
             *
             *  Beside before above: a number bumped upward starts inside the band
             *  the older ones are still rising through, and chains into them;
             *  beside it keeps its own column. When every slot is taken it goes
             *  wherever the fewest others are, so a big burst degrades into some
             *  overlap rather than a column climbing off the fighter. Held inside
             *  the arena edge for the same reason as the name plate.
             *
             *  Two beside-slots each way, not one: in a corner the wall clamp
             *  folds the near ones back onto the spot that was taken, and in the
             *  top row "above" is clamped onto the same line, so the spare row
             *  goes below there instead. A fighter pinned in the top-left corner
             *  was the case that printed three numbers in one place.
             *
             *  Expects ctx.font already set to the number's spawn size. */
            function placeFloatNum(fn, list) {
                fn.placed = true;
                fn.w = ctx.measureText(String(fn.text)).width;
                const lineH = 13;
                // A number grows from 11px to 15px as it fades, so the gap is
                // sized for the late frame: at +6 "11" and "13" read as "1113".
                const step = fn.w + 12;
                const up = fn.y - lineH >= lineH ? -1 : 1;
                const slots = [[0, 0], [-1, 0], [1, 0], [-2, 0], [2, 0], [0, up], [-1, up], [1, up]];
                const baseX = fn.x, baseY = fn.y;
                let best = null, bestHits = Infinity;
                for (const [sx, sy] of slots) {
                    const half = fn.w / 2 + 2;
                    const x = Math.min(Math.max(baseX + sx * step, half), canvasLogicalW - half);
                    const y = Math.max(baseY + sy * lineH, lineH);
                    let hits = 0;
                    for (const o of list) {
                        if (o === fn) break;
                        if (!o.placed || o.life <= 0) continue;
                        if (Math.abs(o.x - x) < (o.w + fn.w) / 2 + 8 &&Math.abs(o.y - y) < lineH) hits++;
                    }
                    if (hits < bestHits) { best = [x, y]; bestHits = hits; }
                    if (hits === 0) break;
                }
                fn.x = best[0];
                fn.y = best[1];
            }

            let screenShake = { intensity: 0, duration: 0 };
            let slowMotion = { active: false, scale: 1, duration: 0 };
            let killCamera = { active: false, target: null, zoom: 1, duration: 0 };
            let particlesReady = true;

            function applyPerformanceMode() {
                if (performanceMode === 'low') {
                    MAX_HIT_SPARKS = 20;
                    MAX_IMPACT_PARTICLES = 30;
                    MAX_SABER_TRAILS = 12;
                    MAX_DEATH_PARTICLES = 20;
                    MAX_FLOATS = 20;
                    MAX_CLASH_PARTICLES = 24;
                } else if (performanceMode === 'balanced') {
                    MAX_HIT_SPARKS = 50;
                    MAX_IMPACT_PARTICLES = 80;
                    MAX_SABER_TRAILS = 36;
                    MAX_DEATH_PARTICLES = 50;
                    MAX_FLOATS = 40;
                    MAX_CLASH_PARTICLES = 60;
                } else {
                    MAX_HIT_SPARKS = 80;
                    MAX_IMPACT_PARTICLES = 140;
                    MAX_SABER_TRAILS = 60;
                    MAX_DEATH_PARTICLES = 80;
                    MAX_FLOATS = 60;
                    MAX_CLASH_PARTICLES = 120;
                }
                if (particlesReady) {
                    if (hitSparks.length > MAX_HIT_SPARKS) hitSparks.length = MAX_HIT_SPARKS;
                    if (impactParticles.length > MAX_IMPACT_PARTICLES) impactParticles.length = MAX_IMPACT_PARTICLES;
                    if (saberTrails.length > MAX_SABER_TRAILS) saberTrails.length = MAX_SABER_TRAILS;
                    if (deathParticles.length > MAX_DEATH_PARTICLES) deathParticles.length = MAX_DEATH_PARTICLES;
                    if (floatNums.length > MAX_FLOATS) floatNums.length = MAX_FLOATS;
                    if (clashParticles.length > MAX_CLASH_PARTICLES) clashParticles.length = MAX_CLASH_PARTICLES;
                }

                document.querySelectorAll('.perf-btn').forEach(btn => {
                    btn.classList.toggle('selected', btn.dataset.perf === performanceMode);
                });
                // Re-apply DPR cap when graphics preset changes mid-session
                if (typeof resizeCanvas === 'function') {
                    try { resizeCanvas(); } catch (e) {}
                }
            }

            function applyReducedMotion() {
                document.body.classList.toggle('reduced-motion', !!reducedMotion);
                const btn = document.getElementById('reducedMotionBtn');
                if (btn) btn.textContent = reducedMotion ? '♿ Reduced Motion: ON' : '♿ Reduced Motion: OFF';
                if (reducedMotion && particlesReady) {
                    screenShake.intensity = 0;
                    screenShake.duration = 0;
                    killCamera.active = false;
                    killCamera.zoom = 1;
                    slowMotion.active = false;
                    slowMotion.scale = 1;
                }
            }

            function updateFpsMeterVisibility() {
                const el = document.getElementById('fpsMeter');
                const toggle = document.getElementById('devToggleFps');
                if (el) {
                    el.style.display = showFpsMeter ? 'block' : 'none';
                    el.setAttribute('aria-hidden', showFpsMeter ? 'false' : 'true');
                }
                if (toggle) toggle.textContent = `FPS Meter: ${showFpsMeter ? 'ON' : 'OFF'}`;
            }

            function loadGameSettings() {
                try {
                    const saved = loadVersioned('galacticDuelSettings', {});
                    // The switch had two earlier names before it was Marvel
                    // Music. A save written under the old name keeps its preference.
                    marvelSoundtrackEnabled = !!(saved.marvelSoundtrackEnabled !== undefined
                        ? saved.marvelSoundtrackEnabled : saved.seasonSoundtrackEnabled);
                    // An old `unlocked` flag is deliberately not read. That content is
                    // no longer something a save can be without, so an old save
                    // that never redeemed the code opens with the whole thing
                    // available — which is the point of the change. The key is
                    // left in place in existing saves and simply ignored.
                    // This preference was persisted as `dlcFactionsEnabled` before
                    // the rename, so an existing save is read under either key —
                    // the new name wins, the old one is the fallback. Nothing
                    // writes the old key any more, so a save that came in under it
                    // is migrated the first time anything calls saveGameSettings().
                    marvelFactionsEnabled = !!saved.marvelFactionsEnabled;
                    halloweenFactionsEnabled = !!saved.halloweenFactionsEnabled;
                    starkContractsClaimed = Math.max(0, Number(saved.starkContractsClaimed) || 0);
                    grootContractsClaimed = Math.max(0, Number(saved.grootContractsClaimed) || 0);
                    // The older name is still read so a save predating the rename
                    // keeps its setting. Moot without a pack loaded, since the
                    // toggle is hidden then anyway.
                    packFactionsEnabled = 'packFactionsEnabled' in saved
                        ? !!saved.packFactionsEnabled
                        : !!saved.dlcFactionsEnabled;
                    aurebeshEnabled = !!saved.aurebeshEnabled;
                    aurebeshUnlocked = !!saved.aurebeshUnlocked;
                    // buildItLobbyEnabled / buildItLobbyUnlocked used to live here.
                    // The lobby-only Build It switch is gone — that track is now the
                    // menu half of the post-event soundtrack and nothing else — so a
                    // save carrying those two keys is read past and stops writing
                    // them on the next saveGameSettings().
                    // Clamped, not just type-checked: an audio element throws on a
                    // volume outside 0–1, and that happens after this try, so a save
                    // holding 50 used to stop the game from booting at all.
                    musicVolume = savedNumber(saved.musicVolume, 0, 1, musicVolume);
                    sfxVolume   = savedNumber(saved.sfxVolume,   0, 1, sfxVolume);
                    credits = savedNumber(saved.credits, 0, Number.MAX_SAFE_INTEGER, 0);
                    // Checked against the fingerprints after boot, by recheckDevCode().
                    // An old save's devVerifiedUsername is a username, not a code, so
                    // it is read past and dropped on the next save.
                    devAccessCode = normalizeDevCode(saved.devAccessCode);
                    if (saved.performanceMode === 'low' || saved.performanceMode === 'balanced' || saved.performanceMode === 'high') {
                        performanceMode = saved.performanceMode;
                    } else {
                        performanceMode = detectDefaultPerformanceMode();
                    }
                    if (typeof saved.reducedMotion === 'boolean') {
                        reducedMotion = saved.reducedMotion;
                    } else if (osPrefersReducedMotion) {
                        reducedMotion = true;
                    }
                    showFpsMeter = !!saved.showFpsMeter;
                    autoAimEnabled = !!saved.autoAimEnabled;
                    seenAimHint = !!saved.seenAimHint;
                    // Absent on every save written before this feature, which
                    // reads as false — the correct value for both: a save that
                    // has never seen the card, and one whose next series win
                    // will unlock the Zero Event. No migration.
                    seenFirstFightCard = !!saved.seenFirstFightCard;
                    keyBindings = sanitizeKeyBindings(saved.keyBindings);
                    hasWonSeries = !!saved.hasWonSeries;
                    shopSeenIds = Array.isArray(saved.shopSeenIds) ? saved.shopSeenIds.filter(id => typeof id === 'string') : [];
                    // Sprites — kept verbatim rather than filtered by build, so a
                    // save round-tripped through the shipped game comes back to a
                    // local build with its collection intact. isSpriteEquipped()
                    // is what actually keeps the effect off non-local builds.
                    // Unknown ids (a prototype sprite that was since renamed or
                    // dropped) are discarded here so they can't linger equipped.
                    ownedSprites = {};
                    lostSprites = {};
                    if (saved.ownedSprites && typeof saved.ownedSprites === 'object') {
                        SPRITE_CATALOG.forEach(s => {
                            if (saved.ownedSprites[s.id]) ownedSprites[s.id] = true;
                        });
                    }
                    if (saved.lostSprites && typeof saved.lostSprites === 'object') {
                        SPRITE_CATALOG.forEach(s => {
                            // Owning it again outranks a stale lost flag, so a save
                            // can never list a sprite as both held and for sale.
                            // The stored value is kept rather than flattened to true:
                            // loseSprite() writes the arena there, which is what lets
                            // the Shop tile say where it went. Older saves hold `true`.
                            // Anything that does not look like an arena key reads as the
                            // older `true`: the value goes into a selector and a label.
                            const where = saved.lostSprites[s.id];
                            if (where && !ownedSprites[s.id]) {
                                lostSprites[s.id] = (typeof where === 'string' && /^[A-Za-z0-9_-]{1,40}$/.test(where)) ? where : true;
                            }
                        });
                    }
                    equippedSpriteId = (typeof saved.equippedSpriteId === 'string' &&
                        Object.prototype.hasOwnProperty.call(ownedSprites, saved.equippedSpriteId)) ? saved.equippedSpriteId : null;
                    // Checked against the catalog rather than against the inventory:
                    // a skin outlives losing the sprite it came from (see
                    // spriteEverOwned), so only an id that no longer exists at all is
                    // dropped. The roster entry is repainted later, in the init block
                    // — `characters` is not declared yet at this point.
                    guardianSkinSpriteId = SPRITE_CATALOG.some(s => s.id === saved.guardianSkinSpriteId)
                        ? saved.guardianSkinSpriteId : null;
                    // Validated on the way out by activeWrixelColor() rather than
                    // here: loadGameSettings() runs thousands of lines before the
                    // Wrixel block is declared, so calling anything from it here
                    // would be a temporal dead zone throw — swallowed by the catch
                    // below, and the setting would silently never load.
                    wrixelColor = typeof saved.wrixelColor === 'string' ? saved.wrixelColor : null;
                } catch (e) {}
                updateMusicSources();
                updateCreditsDisplay();
                updateSpritesUiVisibility();
                renderSpritesOverlay();
                applyAurebeshMode();
                applyAutoAimSetting();
                // Particle caps are declared later; applyPerformanceMode is called again after they exist
                applyReducedMotion();
                updateFpsMeterVisibility();
            }

            function saveGameSettings() {
                saveVersioned('galacticDuelSettings', {
                    marvelSoundtrackEnabled,
                    packFactionsEnabled,
                    marvelFactionsEnabled,
                    halloweenFactionsEnabled,
                    starkContractsClaimed,
                    grootContractsClaimed,
                    aurebeshEnabled,
                    aurebeshUnlocked,
                    musicVolume,
                    sfxVolume,
                    credits,
                    devAccessCode,
                    performanceMode,
                    reducedMotion,
                    showFpsMeter,
                    autoAimEnabled,
                    seenAimHint,
                    seenFirstFightCard,
                    keyBindings,
                    hasWonSeries,
                    shopSeenIds,
                    ownedSprites,
                    equippedSpriteId,
                    lostSprites,
                    guardianSkinSpriteId,
                    wrixelColor
                });
            }

            function getUiFontStack() {
                return aurebeshEnabled ? "'Aurebesh', 'Inter', sans-serif" : "'Inter', sans-serif";
            }

            function getCanvasFontFamily() {
                return aurebeshEnabled ? 'Aurebesh' : 'Orbitron';
            }

            function applyAurebeshMode() {
                document.body.classList.toggle('aurebesh-mode', !!aurebeshEnabled);
            }

            function updateAurebeshToggleVisibility() {
                const btn = document.getElementById('aurebeshToggleBtn');
                if (!btn) return;
                btn.style.display = aurebeshUnlocked ? 'block' : 'none';
                btn.textContent = aurebeshEnabled ? '🔤 Aurebesh: ON' : '🔤 Aurebesh: OFF';
            }

            function toggleAurebeshMode() {
                aurebeshEnabled = !aurebeshEnabled;
                aurebeshUnlocked = true;
                applyAurebeshMode();
                saveGameSettings();
                updateAurebeshToggleVisibility();
                showAnnouncement('Aurebesh ' + (aurebeshEnabled ? 'Enabled' : 'Disabled') + '.', '#8ae1ff', 3000, '🔤 AUREBESH');
            }

            function updateCreditsDisplay() {
                const display = document.getElementById('shopCreditsDisplay');
                if (display) display.textContent = credits;
                const armoryDisplay = document.getElementById('armoryCreditsDisplay');
                if (armoryDisplay) armoryDisplay.textContent = credits;
                const creatorDisplay = document.getElementById('creatorCreditsDisplay');
                if (creatorDisplay) creatorDisplay.textContent = credits;
                // The splash chip and the Dossier header are two more readouts of the
                // same number, so they belong here rather than in updaters of their
                // own — a purchase, a claim and a series win all already call this.
                const splashChip = document.getElementById('splashCredits');
                if (splashChip) splashChip.textContent = `🪙 ${credits.toLocaleString()}`;
                const dossierChip = document.getElementById('dossierCredits');
                if (dossierChip) dossierChip.textContent = `🪙 ${credits.toLocaleString()}`;
            }

            // ── MATCH STATS ────────────────────────────────────────────────
            /*  galacticDuelHistory stores display names only — no ids, no arena, no
             *  weapon — and trims at MAX_HISTORY_ENTRIES, so neither mastery nor most
             *  contracts can be derived from it. This is the record they read.
             *
             *  Written in exactly one place (recordMatchStats, off the back of the
             *  round result). Nothing here is touched from the game loop.            */
            let matchStats = { fighters: {}, arenasPlayed: [], weaponsUsed: [] };

            function loadMatchStats() {
                const s = loadVersioned('galacticDuelStats', null) || {};
                matchStats = {
                    fighters:     (s.fighters && typeof s.fighters === 'object') ? s.fighters : {},
                    arenasPlayed: Array.isArray(s.arenasPlayed) ? s.arenasPlayed : [],
                    weaponsUsed:  Array.isArray(s.weaponsUsed)  ? s.weaponsUsed  : []
                };
            }
            function saveMatchStats() { saveVersioned('galacticDuelStats', matchStats); }

            /** The per-fighter row, created on first sight. Keyed by the id
             *  achievementCharId() returns, so an elite skin banks into its base
             *  fighter rather than opening a second, near-empty card. */
            function fighterStats(id) {
                if (!matchStats.fighters[id]) {
                    matchStats.fighters[id] = { fights: 0, wins: 0, damage: 0, kills: 0, xp: 0 };
                }
                return matchStats.fighters[id];
            }

            // Cumulative XP at which each level starts. The listed thresholds are the
            // spec's; past the end the step keeps growing by 100, which is what its
            // last two steps do (300 → 400 → 500).
            const MASTERY_THRESHOLDS = [0, 100, 250, 450, 700, 1000, 1400, 1900];

            function masteryFor(xp) {
                const t = MASTERY_THRESHOLDS.slice();
                let step = t[t.length - 1] - t[t.length - 2];
                while (t[t.length - 1] <= xp) { step += 100; t.push(t[t.length - 1] + step); }
                let level = 1;
                while (level < t.length && xp >= t[level]) level++;
                const base = t[level - 1], next = t[level];
                return { level, base, next, into: xp - base, span: next - base,
                         pct: Math.max(0, Math.min(100, ((xp - base) / (next - base)) * 100)) };
            }

            /*  What a level is worth. Every one of these is cosmetic by design — the
             *  moment mastery touches damage, health, cooldown or reach it stops being
             *  a reason to take a 40th fighter out and becomes a reason not to.
             *  The reward system itself is not built yet; 3.0 ships the ladder.      */
            const MASTERY_REWARDS = [
                'a bolt tint in their own colour',
                'a longer saber trail',
                'a second colour slot',
                'a nameplate flourish',
                'a deeper bolt tint',
                'a trail that outlives the swing',
                'a third colour slot'
            ];
            function masteryRewardFor(level) {
                return MASTERY_REWARDS[(level - 1) % MASTERY_REWARDS.length];
            }

            /** An arena's display name, read off the picker button so there is no
             *  second table of names to keep in step. */
            function arenaLabel(key) {
                const btn = document.querySelector(`.arena-btn[data-arena="${key}"]`);
                if (!btn) return key;
                return btn.textContent.trim().replace(/^\S+\s*/, '');
            }

            // ── DAILY CONTRACTS ────────────────────────────────────────────
            /*  A second, steadier source of credits than a series win. Every entry
             *  reads a counter the game already keeps: nothing here adds per-frame
             *  tracking, and all of it advances from the one round-result call.     */
            const CONTRACT_POOL = [
                { id: 'hardWin',     icon: '🎯', reward: 150, target: 1,
                  label: 'Win a series on Hard or above',
                  advance: c => (c.seriesWon && (c.difficulty === 'hard' || c.difficulty === 'legend')) ? 1 : 0 },
                { id: 'saberWins',   icon: '⚔️', reward: 80,  target: 3,
                  label: 'Win three fights with a saber',
                  advance: c => (c.won && c.isSaber) ? 1 : 0 },
                { id: 'blasterWins', icon: '🔫', reward: 80,  target: 3,
                  label: 'Win three fights with a blaster',
                  advance: c => (c.won && c.isBlaster) ? 1 : 0 },
                { id: 'newArena',    icon: '🗺️', reward: 150, target: 1,
                  label: 'Fight in an arena you have never picked',
                  advance: c => c.arenaIsNew ? 1 : 0 },
                { id: 'villainDown', icon: '💀', reward: 120, target: 2,
                  label: 'Beat two villains',
                  advance: c => (c.won && c.enemyIsVillain) ? 1 : 0 },
                { id: 'damage',      icon: '💥', reward: 120, target: 1200,
                  label: 'Deal 1,200 damage',
                  advance: c => c.damage },
                { id: 'accuracy',    icon: '🏹', reward: 100, target: 1,
                  label: 'Finish a fight above 60% accuracy',
                  advance: c => (c.accuracy !== null && c.accuracy > 60) ? 1 : 0 },
                { id: 'kills',       icon: '⚡', reward: 100, target: 15,
                  label: 'Score 15 kills',
                  advance: c => c.kills }
            ];
            const contractById = id => CONTRACT_POOL.find(c => c.id === id);

            /*  ── THE IRON MAN MARKS ────────────────────────────────────────
             *  He arrives as the Mk 1 and is built up out of claimed contracts: one
             *  claim, one mark, to a ceiling of 85.
             *
             *  Counted lifetime rather than read off contractState, which is rolled
             *  fresh every local day and would take the suit apart with it. Three
             *  contracts a day means the Mk 85 is about four weeks of clearing the
             *  board — long, deliberately: it is the last suit, not a weekly.
             *
             *  Two phases, and the split is at Mk 5:
             *    • Mk 1-5   the special is fire, and every mark makes it burn wider,
             *               hotter, further and more often. Health and damage do not
             *               move: early marks are a flamethrower in a tin suit.
             *    • Mk 6-85  the Unibeam comes online and stops changing, and the
             *               suit itself starts growing instead — health and repulsor
             *               damage scale the rest of the way.                        */
            const IRONMAN_MAX_MARK = 85;
            const IRONMAN_FIRE_MAX_MARK = 5;    // last mark that flies on fire alone
            const IRONMAN_BASE_HP = 190;        // the Mk 1, and what the roster entry ships as
            const IRONMAN_MAX_HP = 330;
            const IRONMAN_BASE_DMG = 16;        // one repulsor bolt at Mk 5
            const IRONMAN_MAX_DMG = 26;
            let starkContractsClaimed = 0;

            /*  STARK'S OWN BOARD. The marks used to come off the daily contracts,
             *  which meant the suit could only be built three steps a day and then
             *  not at all until the clock turned over. These are his: one order
             *  standing at a time, and claiming it posts the next one immediately, so
             *  the only thing between the Mk 1 and the Mk 85 is fighting.
             *
             *  The daily board is untouched and still pays credits. This one pays in
             *  marks and nothing else — two boards, two currencies, no overlap.
             *
             *  Every entry reads the same round-result context the dailies do, so
             *  nothing here adds tracking. Nothing in the pool can become impossible
             *  either, which matters far more here than on the daily board: with one
             *  order standing, a contract that could never complete would wedge the
             *  whole track. That is why 'an arena you have never picked' is a daily
             *  and not one of these — it runs out.                                  */
            const STARK_POOL = [
                // -- IN THE SUIT ------------------------------------------------
                { id: 'stark_suit',      icon: '🦾', target: 1,
                  label: 'Win a fight in the suit',              advance: c => (c.won && c.isIronMan) ? 1 : 0 },
                { id: 'stark_suit3',     icon: '🦾', target: 3,
                  label: 'Win three fights in the suit',         advance: c => (c.won && c.isIronMan) ? 1 : 0 },
                { id: 'stark_chest',     icon: '🔆', target: 5,
                  label: 'Fire the chest piece five times',      advance: c => c.isIronMan ? c.specials : 0 },
                { id: 'stark_repulsor',  icon: '💠', target: 700,
                  label: 'Deal 700 damage on repulsors',         advance: c => c.weaponKey === 'repulsor' ? c.damage : 0 },
                { id: 'stark_suitdmg',   icon: '🦾', target: 1200,
                  label: 'Deal 1,200 damage in the suit',        advance: c => c.isIronMan ? c.damage : 0 },
                { id: 'stark_suithard',  icon: '🎯', target: 1,
                  label: 'Win in the suit on Hard or above',     advance: c => (c.won && c.isIronMan && (c.difficulty === 'hard' || c.difficulty === 'legend')) ? 1 : 0 },
                { id: 'stark_suitclean', icon: '✨', target: 1,
                  label: 'Win in the suit without taking a hit', advance: c => (c.won && c.isIronMan && c.flawless) ? 1 : 0 },

                // -- THE REST OF THE SEASON -------------------------------------
                { id: 'stark_marvel2',   icon: '🦸', target: 2,
                  label: 'Win two fights as a Marvel fighter',   advance: c => (c.won && c.isMarvel) ? 1 : 0 },
                { id: 'stark_marveldown',icon: '🦹', target: 2,
                  label: 'Beat two Marvel fighters',             advance: c => (c.won && c.enemyIsMarvel) ? 1 : 0 },
                { id: 'stark_spider',    icon: '🕸️', target: 1,
                  label: 'Win a fight as Spider-Man',            advance: c => (c.won && c.charId === 'spiderman') ? 1 : 0 },
                { id: 'stark_webs',      icon: '🕸️', target: 3,
                  label: 'Throw three web grenades',             advance: c => c.charId === 'spiderman' ? c.specials : 0 },
                { id: 'stark_venom',     icon: '🦠', target: 1,
                  label: 'Win a fight as Venom',                 advance: c => (c.won && c.charId === 'venom') ? 1 : 0 },
                { id: 'stark_mandarin',  icon: '💍', target: 1,
                  label: 'Win a fight as the Mandarin',          advance: c => (c.won && c.charId === 'mandarin') ? 1 : 0 },
                { id: 'stark_rings',     icon: '🔥', target: 4,
                  label: 'Loose the rings four times',           advance: c => c.charId === 'mandarin' ? c.specials : 0 },
                { id: 'stark_thor',      icon: '🔨', target: 1,
                  label: 'Win a fight as Thor',                  advance: c => (c.won && c.charId === 'thor') ? 1 : 0 },
                { id: 'stark_godblast',  icon: '⚡', target: 4,
                  label: 'Call down four God Blasts',            advance: c => c.charId === 'thor' ? c.specials : 0 },
                { id: 'stark_loki',      icon: '🐍', target: 1,
                  label: 'Win a fight as Loki',                  advance: c => (c.won && c.charId === 'loki') ? 1 : 0 },
                { id: 'stark_shift',     icon: '🪞', target: 3,
                  label: 'Wear three stolen shapes',             advance: c => c.charId === 'loki' ? c.specials : 0 },
                { id: 'stark_fury',      icon: '🕶️', target: 1,
                  label: 'Win a fight as Nick Fury',             advance: c => (c.won && c.charId === 'fury') ? 1 : 0 },
                { id: 'stark_specials',  icon: '💫', target: 8,
                  label: 'Use a special ability eight times',    advance: c => c.specials },

                // -- GENERAL ----------------------------------------------------
                { id: 'stark_damage',    icon: '💥', target: 900,
                  label: 'Deal 900 damage',                      advance: c => c.damage },
                { id: 'stark_kills',     icon: '⚡', target: 10,
                  label: 'Score 10 kills',                       advance: c => c.kills },
                { id: 'stark_wins',      icon: '🏆', target: 2,
                  label: 'Win two fights',                       advance: c => c.won ? 1 : 0 },
                { id: 'stark_series',    icon: '🥇', target: 1,
                  label: 'Win a series',                         advance: c => c.seriesWon ? 1 : 0 },
                { id: 'stark_villain',   icon: '💀', target: 2,
                  label: 'Beat two villains',                    advance: c => (c.won && c.enemyIsVillain) ? 1 : 0 },
                { id: 'stark_clean',     icon: '✨', target: 1,
                  label: 'Win a fight without taking a hit',     advance: c => (c.won && c.flawless) ? 1 : 0 },
                { id: 'stark_accuracy',  icon: '🏹', target: 1,
                  label: 'Finish a fight above 55% accuracy',    advance: c => (c.accuracy !== null && c.accuracy > 55) ? 1 : 0 },
                { id: 'stark_sharp',     icon: '🏹', target: 1,
                  label: 'Finish a fight above 75% accuracy',    advance: c => (c.accuracy !== null && c.accuracy > 75) ? 1 : 0 },
                { id: 'stark_hard',      icon: '🎯', target: 1,
                  label: 'Win a fight on Hard or above',         advance: c => (c.won && (c.difficulty === 'hard' || c.difficulty === 'legend')) ? 1 : 0 },
                { id: 'stark_legend',    icon: '👑', target: 1,
                  label: 'Win a fight on Legend',                advance: c => (c.won && c.difficulty === 'legend') ? 1 : 0 },
                { id: 'stark_saber',     icon: '⚔️', target: 2,
                  label: 'Win two fights with a saber',          advance: c => (c.won && c.isSaber) ? 1 : 0 },
                { id: 'stark_blaster',   icon: '🔫', target: 3,
                  label: 'Win three fights with a blaster',      advance: c => (c.won && c.isBlaster) ? 1 : 0 }
            ];
            const starkDef = id => STARK_POOL.find(p => p.id === id);

            // One order, or null once the Mk 85 is standing and there is nothing left
            // to build towards.
            let starkContract = null;

            function starkBoardClosed() { return ironManMark() >= IRONMAN_MAX_MARK; }
            function starkReady() { return !!(starkContract && starkContract.progress >= starkContract.target); }

            /** Never the same order twice running: repeating one the player has just
             *  finished reads as the board being broken rather than random. */
            function rollStarkContract(excludeId) {
                if (starkBoardClosed()) { starkContract = null; }
                else {
                    const pool = STARK_POOL.filter(p => p.id !== excludeId);
                    const pick = pool[Math.floor(Math.random() * pool.length)] || STARK_POOL[0];
                    starkContract = { id: pick.id, target: pick.target, progress: 0 };
                }
                saveVersioned('galacticDuelStark', starkContract);
            }

            function loadStarkContract() {
                const saved = loadVersioned('galacticDuelStark', null);
                if (saved && saved.id && starkDef(saved.id) && !starkBoardClosed()) {
                    starkContract = { id: saved.id, target: saved.target,
                                      progress: Math.max(0, Number(saved.progress) || 0) };
                } else {
                    rollStarkContract(null);
                }
            }

            function advanceStarkContract(ctx) {
                if (!starkContract || starkReady()) return;
                const def = starkDef(starkContract.id);
                if (!def) return;
                const step = def.advance(ctx) || 0;
                if (step > 0) {
                    starkContract.progress = Math.min(starkContract.target, starkContract.progress + step);
                    saveVersioned('galacticDuelStark', starkContract);
                }
            }

            /*  Claimed rather than auto-granted, exactly as the daily board is: the
             *  claim is the moment the player sees the suit change.                 */
            function claimStarkContract() {
                if (!starkReady()) return;
                const before = ironManMark();
                starkContractsClaimed++;
                applyIronManMark();
                const after = ironManMark();
                rollStarkContract(starkContract.id);
                saveGameSettings();

                if (after !== before) {
                    const line = after >= IRONMAN_MAX_MARK
                        ? 'The last suit. There is nothing left to build.'
                        : after === IRONMAN_FIRE_MAX_MARK + 1
                            ? 'The Unibeam comes online.'
                            : after <= IRONMAN_FIRE_MAX_MARK
                                ? 'The flamethrowers burn hotter.'
                                : 'Heavier plating, harder repulsors.';
                    showAnnouncement(line, '#f0a500', 3400, '🦾 MK ' + after, 60);
                    // The roster button, its stat card and the opponent columns all
                    // read the record applyIronManMark() just rewrote.
                    rebuildAllRosters();
                    rebuildOpponentRosters();
                }
                renderDossier();
                refreshSplashState();
            }

            function ironManMark() {
                return Math.max(1, Math.min(IRONMAN_MAX_MARK, 1 + starkContractsClaimed));
            }

            /** 0 at Mk 1, 1 at Mk 5 — how far through the fire phase he is. */
            function ironManFireProgress() {
                return (Math.min(ironManMark(), IRONMAN_FIRE_MAX_MARK) - 1) / (IRONMAN_FIRE_MAX_MARK - 1);
            }

            /** 0 at Mk 5, 1 at Mk 85 — how far through the suit phase he is. */
            function ironManSuitProgress() {
                const mark = ironManMark();
                if (mark <= IRONMAN_FIRE_MAX_MARK) return 0;
                return (mark - IRONMAN_FIRE_MAX_MARK) / (IRONMAN_MAX_MARK - IRONMAN_FIRE_MAX_MARK);
            }

            /*  Writes the current mark onto the roster record itself rather than
             *  applying it at match start. Everything downstream — the roster button,
             *  the stat card, setupGame(), the opponent picker — already reads `hp`
             *  and `weaponDamage` off the character, so one write here is the whole
             *  of it and nothing needs a second code path for him.
             *
             *  Must not run before `characters` exists: it is a const declared well
             *  below this, and touching it in its temporal dead zone would abort the
             *  whole DOMContentLoaded handler. Called from the setup tail and from
             *  claimContract(), both of which are long past that point.            */
            function applyIronManMark() {
                const char = characters.secret.find(c => c.id === 'ironman');
                if (!char) return;
                const mark = ironManMark();
                char.name = 'Iron Man Mk ' + mark;
                // The roster button carries the mark; the label over his head in the
                // arena does not need to.
                char.arenaName = 'Iron Man';
                if (mark <= IRONMAN_FIRE_MAX_MARK) {
                    char.hp = IRONMAN_BASE_HP;
                    // Deleted rather than set to the base: an absent weaponDamage means
                    // "whatever the weapon says", which is what the early marks are.
                    delete char.weaponDamage;
                } else {
                    const t = ironManSuitProgress();
                    char.hp = Math.round(IRONMAN_BASE_HP + (IRONMAN_MAX_HP - IRONMAN_BASE_HP) * t);
                    char.weaponDamage = Math.round(IRONMAN_BASE_DMG + (IRONMAN_MAX_DMG - IRONMAN_BASE_DMG) * t);
                }
            }

            /** What the Dossier says about the suit, under the contracts that build it. */
            function ironManMarkHint() {
                const mark = ironManMark();
                if (mark >= IRONMAN_MAX_MARK) return 'Mk ' + mark + ' · the last suit. Nothing left to build.';
                const next = mark + 1;
                const phase = next <= IRONMAN_FIRE_MAX_MARK
                    ? 'hotter fire'
                    : next === IRONMAN_FIRE_MAX_MARK + 1
                        ? 'the Unibeam comes online'
                        : 'more health and harder repulsors';
                return 'Mk ' + mark + ' of ' + IRONMAN_MAX_MARK + ' · one order at a time, no daily wait · next: ' + phase + '.';
            }

            /*  ── GROOT'S BOARD ────────────────────────────────────────────────
             *  Stark's machinery, re-run for a second fighter: one order standing at
             *  a time, claiming it posts the next immediately, and the pay is the
             *  fighter getting better rather than credits. Everything below mirrors
             *  the block above function for function, deliberately — two boards that
             *  behave identically are easier to reason about than one clever one that
             *  serves both, and Groot's numbers have nothing in common with Stark's.
             *
             *  Where it differs from Iron Man is WHAT the level moves. A mark rewrites
             *  Iron Man's health and his Interact special while his weapon stays a
             *  repulsor throughout. A Groot level rewrites the WEAPON itself: levels
             *  1-4 are the same fists hitting harder each time, and level 5 swaps them
             *  for the axe. His health never moves.
             *
             *  Five levels, so four claims from end to end — against Stark's
             *  eighty-four. This board is meant to be finished.                      */
            const GROOT_MAX_LEVEL = 5;
            const GROOT_FIST_MAX_LEVEL = 4;   // last level that fights with hands
            const GROOT_HP = 235;             // flat at every level; see the roster entry
            // 14 rather than the 10 this shipped with. The ladder's top is fixed at 25
            // and the shape is fixed at "stronger every level", so the only room to
            // make the early game less miserable is the floor: a level 1 Groot was
            // landing 10 a punch, which is under half a blaster bolt, and the board
            // asks you to fight several rounds at that number before it moves.
            const GROOT_FIST_MIN_DMG = 14;    // level 1
            const GROOT_FIST_MAX_DMG = 25;    // level 4 — interpolation gives 14/18/21/25
            let grootContractsClaimed = 0;

            /*  His own orders, and none of them is one of Stark's. The overlap would
             *  have been easy — both boards read the same roundCtx — but a player
             *  working both at once would see the same row twice and reasonably assume
             *  one of them was broken.
             *
             *  Most ask for Groot specifically, which is the flavour; three do not, so
             *  the board can always be moved even by someone who has not warmed to a
             *  level 1 sapling yet. No 'arena you have never picked' here for the same
             *  reason Stark's board has none: it runs out.                           */
            const GROOT_POOL = [
                // -- IN THE BRANCHES --------------------------------------------
                { id: 'groot_win',      icon: '🌱', target: 1,
                  label: 'Win a fight as Groot',                advance: c => (c.won && c.isGroot) ? 1 : 0 },
                { id: 'groot_win3',     icon: '🌳', target: 3,
                  label: 'Win three fights as Groot',           advance: c => (c.won && c.isGroot) ? 1 : 0 },
                { id: 'groot_dmg',      icon: '👊', target: 600,
                  label: 'Deal 600 damage as Groot',            advance: c => c.isGroot ? c.damage : 0 },
                { id: 'groot_kills',    icon: '🪵', target: 6,
                  label: 'Score six kills as Groot',            advance: c => c.isGroot ? c.kills : 0 },
                // Reads the weapon rather than the fighter, so it keeps working after
                // level 5 takes the fists away — it simply stops advancing, which is
                // correct: there are no branches left to swing.
                { id: 'groot_branches', icon: '🤜', target: 500,
                  label: 'Deal 500 damage with the branches',   advance: c => c.weaponKey === 'grootfists' ? c.damage : 0 },
                { id: 'groot_hard',     icon: '🔥', target: 1,
                  label: 'Win as Groot on Hard or above',       advance: c => (c.won && c.isGroot && (c.difficulty === 'hard' || c.difficulty === 'legend')) ? 1 : 0 },
                { id: 'groot_clean',    icon: '✨', target: 1,
                  label: 'Win as Groot without taking a hit',   advance: c => (c.won && c.isGroot && c.flawless) ? 1 : 0 },
                { id: 'groot_series',   icon: '🏆', target: 1,
                  label: 'Win a series as Groot',               advance: c => (c.isGroot && c.seriesWon) ? 1 : 0 },

                // -- THE REST OF THE CREW ---------------------------------------
                // The one order that names the other Guardian. He is the reason Groot
                // is on this roster at all, so the board says so once.
                { id: 'groot_rocket',   icon: '🦝', target: 1,
                  label: 'Win a fight as Rocket',               advance: c => (c.won && c.charId === 'rocket') ? 1 : 0 },

                // -- ANYONE -----------------------------------------------------
                { id: 'groot_any_dmg',  icon: '💥', target: 700,
                  label: 'Deal 700 damage',                     advance: c => c.damage },
                { id: 'groot_any_kills',icon: '⚡', target: 8,
                  label: 'Score eight kills',                   advance: c => c.kills },
                { id: 'groot_any_wins', icon: '🥇', target: 2,
                  label: 'Win two fights',                      advance: c => c.won ? 1 : 0 }
            ];
            const grootDef = id => GROOT_POOL.find(p => p.id === id);

            let grootContract = null;

            function grootBoardClosed() { return grootLevel() >= GROOT_MAX_LEVEL; }
            function grootReady() { return !!(grootContract && grootContract.progress >= grootContract.target); }

            function rollGrootContract(excludeId) {
                if (grootBoardClosed()) { grootContract = null; }
                else {
                    const pool = GROOT_POOL.filter(p => p.id !== excludeId);
                    const pick = pool[Math.floor(Math.random() * pool.length)] || GROOT_POOL[0];
                    grootContract = { id: pick.id, target: pick.target, progress: 0 };
                }
                saveVersioned('galacticDuelGroot', grootContract);
            }

            function loadGrootContract() {
                const saved = loadVersioned('galacticDuelGroot', null);
                if (saved && saved.id && grootDef(saved.id) && !grootBoardClosed()) {
                    grootContract = { id: saved.id, target: saved.target,
                                      progress: Math.max(0, Number(saved.progress) || 0) };
                } else {
                    rollGrootContract(null);
                }
            }

            function advanceGrootContract(ctx) {
                if (!grootContract || grootReady()) return;
                const def = grootDef(grootContract.id);
                if (!def) return;
                const step = def.advance(ctx) || 0;
                if (step > 0) {
                    grootContract.progress = Math.min(grootContract.target, grootContract.progress + step);
                    saveVersioned('galacticDuelGroot', grootContract);
                }
            }

            function claimGrootContract() {
                if (!grootReady()) return;
                const before = grootLevel();
                grootContractsClaimed++;
                applyGrootLevel();
                const after = grootLevel();
                rollGrootContract(grootContract.id);
                saveGameSettings();

                if (after !== before) {
                    const line = after >= GROOT_MAX_LEVEL
                        ? 'He sets the handle on it himself. Stormbreaker.'
                        : 'Thicker branches. They land harder.';
                    showAnnouncement(line, '#7a5b3a', 3400, '🌳 GROOT LV ' + after, 60);
                    // Same three rebuilds the mark does: the roster button, its stat
                    // card and the opponent columns all read the record that
                    // applyGrootLevel() just rewrote.
                    rebuildAllRosters();
                    rebuildOpponentRosters();
                }
                renderDossier();
                refreshSplashState();
            }

            function grootLevel() {
                return Math.max(1, Math.min(GROOT_MAX_LEVEL, 1 + grootContractsClaimed));
            }

            /** What the branches hit for at a given level — 14 at 1, 25 at 4, and the
             *  two steps between. Level 5 has no answer here because level 5 is not
             *  the fists at all; callers that can be asked about it check first.
             *
             *  Its own function because three places need the number and only one of
             *  them can read it off the roster record: the dev slider paints before
             *  applyGrootLevel() has run at load, so `char.weaponDamage` is still
             *  undefined there and the readout said "branches undefined a hit". One
             *  formula, three readers, rather than the expression written out twice
             *  and a third caller reaching for a field that may not exist yet. */
            function grootFistDamage(level) {
                const t = (Math.min(level, GROOT_FIST_MAX_LEVEL) - 1) / (GROOT_FIST_MAX_LEVEL - 1);
                return Math.round(GROOT_FIST_MIN_DMG + (GROOT_FIST_MAX_DMG - GROOT_FIST_MIN_DMG) * t);
            }

            /*  Writes the level onto the roster record, exactly as applyIronManMark()
             *  writes the mark — and for the same reason: the roster button, the stat
             *  card, setupGame() and the opponent picker all read `weapon`, `hp` and
             *  `weaponDamage` off the character already, so one write here is the
             *  whole of it.
             *
             *  This one also rewrites `weapon`, which the mark never does. getWeapon()
             *  resolves WEAPON_LIBRARY[char.weapon] fresh every time a fighter is
             *  built, so swapping the string is the entire level 5 transition — there
             *  is no second code path for the axe.
             *
             *  Must not run before `characters` exists (it is a const declared well
             *  below this), for the same temporal-dead-zone reason the mark carries.  */
            function applyGrootLevel() {
                const char = characters.secret.find(c => c.id === 'groot');
                if (!char) return;
                const lvl = grootLevel();
                char.name = lvl >= GROOT_MAX_LEVEL ? 'Groot · Stormbreaker' : 'Groot · Lv ' + lvl;
                // The roster button carries the level; the label over his head does not.
                char.arenaName = 'Groot';
                char.hp = GROOT_HP;
                if (lvl >= GROOT_MAX_LEVEL) {
                    char.weapon = 'stormbreaker';
                    // Deleted rather than set: an absent weaponDamage means "whatever
                    // the weapon says", and the axe says 40.
                    delete char.weaponDamage;
                } else {
                    char.weapon = 'grootfists';
                    char.weaponDamage = grootFistDamage(lvl);
                }
            }

            /** What the Dossier says about Groot, under the contracts that grow him. */
            function grootLevelHint() {
                const lvl = grootLevel();
                if (lvl >= GROOT_MAX_LEVEL) return 'Level ' + lvl + ' · Stormbreaker. There is nothing left to grow.';
                const next = lvl + 1;
                const phase = next >= GROOT_MAX_LEVEL
                    ? 'Stormbreaker'
                    : 'heavier branches (' + grootFistDamage(next) + ' a hit)';
                return 'Level ' + lvl + ' of ' + GROOT_MAX_LEVEL + ' · one order at a time, no daily wait · next: ' + phase + '.';
            }

            let contractState = { day: '', list: [] };
            const contractDayKey = () => new Date().toLocaleDateString();

            /** Rolls a new set if — and only if — the local day has turned over.
             *  Never rerolls inside a day and never resets progress on one, which is
             *  why the day is compared rather than the list being rebuilt on open. */
            function rollContractsIfNewDay() {
                const today = contractDayKey();
                if (contractState.day === today && contractState.list.length) return false;
                const pool = CONTRACT_POOL.slice();
                const picked = [];
                while (picked.length < 3 && pool.length) {
                    picked.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
                }
                contractState = {
                    day: today,
                    list: picked.map(p => ({ id: p.id, target: p.target, progress: 0,
                                             reward: p.reward, claimed: false }))
                };
                saveVersioned('galacticDuelContracts', contractState);
                return true;
            }

            function loadContracts() {
                const s = loadVersioned('galacticDuelContracts', null);
                // Each row is checked against the pool rather than taken as saved:
                // a null or an unknown id in a hand-edited save used to throw from
                // the splash's ready count and stop the game booting. An empty list
                // just rolls a fresh day.
                const list = (s && Array.isArray(s.list)) ? s.list.map(c => {
                    const p = c && typeof c === 'object' && CONTRACT_POOL.find(x => x.id === c.id);
                    if (!p) return null;
                    return { id: p.id,
                             target: savedNumber(c.target, 1, Number.MAX_SAFE_INTEGER, p.target),
                             progress: savedNumber(c.progress, 0, Number.MAX_SAFE_INTEGER, 0),
                             reward: savedNumber(c.reward, 0, Number.MAX_SAFE_INTEGER, p.reward),
                             claimed: c.claimed === true };
                }).filter(Boolean) : [];
                contractState = { day: (s && typeof s.day === 'string') ? s.day : '', list };
                rollContractsIfNewDay();
            }

            function contractsReadyCount() {
                return contractState.list.filter(c => !c.claimed && c.progress >= c.target).length
                     + (starkReady() ? 1 : 0);
            }

            /*  Claimed, never auto-granted: the claim is the moment the player sees
             *  the reward, and it is what keeps the tile's "2 ready" pill honest.
             *  Follows the achievement award path — the 5000 cap included.          */
            function claimContract(id) {
                const c = contractState.list.find(x => x.id === id);
                if (!c || c.claimed || c.progress < c.target) return;
                const gained = awardCredits(c.reward);
                c.claimed = true;
                saveGameSettings();
                saveVersioned('galacticDuelContracts', contractState);
                updateCreditsDisplay();
                showAnnouncement(creditAwardLine(gained), '#ffd700', 3000, 'CREDITS', 40);
                renderDossier();
                refreshSplashState();
            }

            /** Does the player actually have a pack fighter to their name?
             *
             *  This is what the season view is gated on. Offering a season view to
             *  someone whose column would be a row of ’???’ entries is offering
             *  them an empty room, so the honest question is not "is a pack loaded"
             *  but "is there anything for these columns to show".
             *
             *  Retired fighters do not count. If every pack character a player owns
             *  is struck off, the columns are empty again and the toggle goes away
             *  with them — the same question, asked at a later moment. */
            function ownsAnyPackCharacter() {
                return [characters.heroes, characters.villains, characters.secret].some(roster =>
                    roster.some(c => c.packId && !isCharacterRetired(c) && isSecretCharUnlocked(c)));
            }

            /** The season columns are a view, not a state the rest of the game
             *  reads: characters stay in the rosters they were declared in,
             *  matchups are unaffected, and the opponent picker still offers the
             *  whole cast so a pack fighter can still be pointed at Vader.
             *
             *  Asks ownsAnyPackCharacter() as well as the saved preference, so a
             *  save carrying the view switched on cannot strand the player in
             *  columns they can no longer populate or a toggle they can no longer
             *  see. The preference itself is left alone in that case — it comes
             *  back into force the moment they own a pack fighter again. */
            function packFactionViewActive() {
                return !!packFactionsEnabled && ownsAnyPackCharacter();
            }

            /** Asks whether the season has a cast at all, not whether anything was
             *  bought — the Marvel fighters are free. Still worth asking: it keeps the
             *  toggle honest if the season is ever emptied or vaulted. */
            function ownsAnyMarvelCharacter() {
                return characters.secret.some(c => c.marvel && !isCharacterRetired(c));
            }

            function marvelFactionViewActive() {
                return !!marvelFactionsEnabled && ownsAnyMarvelCharacter();
            }

            /** The same question for Halloween. Four of its six are free, so this
             *  is again "does the season have a cast", not "has anything been won". */
            function ownsAnyHalloweenCharacter() {
                return characters.secret.some(c => c.halloween && !isCharacterRetired(c));
            }

            function halloweenFactionViewActive() {
                return !!halloweenFactionsEnabled && ownsAnyHalloweenCharacter();
            }

            /** Whichever season view is on, or null for the Galactic rosters. Marvel
             *  wins if somehow more than one is set, then Halloween: the toggles
             *  already turn each other off, so the order only settles an old save. */
            function activeSeason() {
                if (marvelFactionViewActive()) return marvelSeason();
                if (halloweenFactionViewActive()) return halloweenSeason();
                if (packFactionViewActive()) return packSeason();
                return null;
            }

            function updateFactionHeadings() {
                const season = activeSeason();

                // Four headings: the roster's two columns and the opponent screen's
                // two. They are the same two factions shown twice, so they are named
                // and switched together.
                const headings = [
                    ['hero-faction-name',        'heroes'],
                    ['villain-faction-name',     'villains'],
                    ['opp-hero-faction-name',    'heroes'],
                    ['opp-villain-faction-name', 'villains']
                ];
                headings.forEach(([id, side]) => {
                    const el = document.getElementById(id);
                    if (el) el.textContent = season ? season[side].title : GALACTIC_FACTION_TITLES[side];
                });

                // Every heading carries a button and all four drive the same switch —
                // the columns change together, so whichever one is clicked is the
                // same toggle.
                // Hidden until the player owns a pack fighter — see
                // ownsAnyPackCharacter(). It is gated on having the characters
                // rather than on the pack file merely being present.
                //
                // One helper for both season toggles: they are the same control shown
                // twice over, differing only in which season they name and whether that
                // season has anyone left in it.
                const paintToggle = (selector, offered, active, label) => {
                    document.querySelectorAll(selector).forEach(btn => {
                        btn.style.display = offered ? '' : 'none';
                        btn.classList.toggle('active', active);
                        btn.setAttribute('aria-pressed', active ? 'true' : 'false');
                        btn.title = active
                            ? 'Showing the ' + label + ' season. Click for the Galactic rosters.'
                            : 'Switch both columns to the ' + label + ' season.';
                    });
                };

                // No pack loaded means no season to name and nothing to offer.
                const ps = packSeason();
                paintToggle('.pack-faction-toggle', !!ps && ownsAnyPackCharacter(),
                            packFactionViewActive(), ps ? ps.label : '');
                paintToggle('.marvel-faction-toggle', ownsAnyMarvelCharacter(),
                            marvelFactionViewActive(), marvelSeason().label);
                paintToggle('.halloween-faction-toggle', ownsAnyHalloweenCharacter(),
                            halloweenFactionViewActive(), halloweenSeason().label);
            }

            function togglePackFactions() {
                // The button is hidden without a pack fighter, but a gamepad
                // or keyboard activation can still reach a stale node, so the
                // guard lives on the action rather than only on the display.
                if (!packSeason() || !ownsAnyPackCharacter()) return;
                packFactionsEnabled = !packFactionsEnabled;
                // The other two seasons' toggles turn this one off, and this one
                // turns them off in return — one cast in the columns at a time.
                if (packFactionsEnabled) { marvelFactionsEnabled = false; halloweenFactionsEnabled = false; }
                saveGameSettings();
                updateFactionHeadings();
                // Both columns and the secret row: the pack fighters move up into the
                // two faction columns while the view is on, so the secret row must
                // drop them or they are listed twice.
                rebuildAllRosters();
                rebuildOpponentRosters();
                updateSecretFactionSectionVisibility();

                const season = packSeason();
                if (packFactionsEnabled) {
                    showAnnouncement(season.heroes.title + ' against ' + season.villains.title + '.',
                        '#9146ff', 3500, '⚡ ' + season.label.toUpperCase() + ' SEASON', 100);
                } else {
                    showAnnouncement('Back to the Grand Army and the Sith.', '#9146ff', 3000, '⭐ GALACTIC ROSTER', 100);
                }
            }

            /*  The Marvel half of the same switch. Turning one season on turns the
             *  other off rather than stacking: the columns can only show one cast, and
             *  activeSeason() would silently pick for the player otherwise.          */
            function toggleMarvelFactions() {
                // Guard on the action, not only on the display — a gamepad or keyboard
                // activation can still reach a hidden button.
                if (!ownsAnyMarvelCharacter()) return;
                marvelFactionsEnabled = !marvelFactionsEnabled;
                if (marvelFactionsEnabled) { packFactionsEnabled = false; halloweenFactionsEnabled = false; }
                saveGameSettings();
                updateFactionHeadings();
                // Both columns, the opponent screen and the secret row: the season
                // fighters move up into the two faction columns while the view is on,
                // so the row below has to drop them or they are listed twice.
                rebuildAllRosters();
                rebuildOpponentRosters();
                updateSecretFactionSectionVisibility();

                const season = marvelSeason();
                if (marvelFactionsEnabled) {
                    showAnnouncement(season.heroes.title + ' against ' + season.villains.title + '.',
                        '#e23636', 3500, '🦸 ' + season.label.toUpperCase() + ' SEASON', 100);
                } else {
                    showAnnouncement('Back to the Grand Army and the Sith.', '#e23636', 3000, '⭐ GALACTIC ROSTER', 100);
                }
            }

            /*  The Halloween third of the same switch, on the same terms: turning it
             *  on turns the other two off.                                          */
            function toggleHalloweenFactions() {
                if (!ownsAnyHalloweenCharacter()) return;
                halloweenFactionsEnabled = !halloweenFactionsEnabled;
                if (halloweenFactionsEnabled) { packFactionsEnabled = false; marvelFactionsEnabled = false; }
                saveGameSettings();
                updateFactionHeadings();
                rebuildAllRosters();
                rebuildOpponentRosters();
                updateSecretFactionSectionVisibility();

                const season = halloweenSeason();
                if (halloweenFactionsEnabled) {
                    showAnnouncement(season.heroes.title + ' against ' + season.villains.title + '.',
                        '#ff7a1a', 3500, '🎃 ' + season.label.toUpperCase() + ' SEASON', 100);
                } else {
                    showAnnouncement('Back to the Grand Army and the Sith.', '#ff7a1a', 3000, '⭐ GALACTIC ROSTER', 100);
                }
            }

            /** Puts the ON/OFF state of the soundtrack preference on its button,
             *  and nothing else. Cluster Coast is a plain arena button in
             *  index.html now, always visible like every other one, so there is no
             *  longer an arena to reveal or an arena the player can be stranded on.
             *
             *  It deliberately does NOT refresh the faction headings any more.
             *  This runs during setup, before `const characters` is initialised,
             *  and updateFactionHeadings() now asks ownsAnyPackCharacter() —
             *  which reads that roster and would throw on the temporal dead zone.
             *  The headings are driven from rebuildAllRosters() instead, which
             *  runs after the roster exists and after every event that can change
             *  the answer. */
            function updateMarvelMusicButton() {
                const btn = document.getElementById('marvelToggleBtn');
                if (btn) {
                    btn.textContent = marvelSoundtrackEnabled ? '🎵 Marvel Music: ON' : '🎵 Marvel Music: OFF';
                }
            }

            const menuMusic = new Audio(defaultMenuMusicSrc);
            const battleMusic = new Audio(defaultBattleMusicSrc);
            // Pinned to the file, not to defaultMenuMusicSrc: the lobby default is
            // Help Arrives now, and this handle has to stay Cantina Band.
            const cantinaBandAudio = new Audio('music/CantinaBand.mp3'); // Always CantinaBand, never overridden by a season soundtrack
            // Arena-specific battle tracks
            const mustafar_music  = new Audio('music/BattleoftheHeroes.mp3');
            const deathstar_music = new Audio('music/ImperialMarch.mp3');
            // The Halloween event's own battle track (the owner's pick), heard in
            // event rounds and nowhere else: not on the menu, not on the season
            // toggle, not in a Freeplay fight on Endor.
            const halloweenBattleMusic = new Audio('music/ThisIsHalloween.mp3');
            mustafar_music.loop  = true;
            deathstar_music.loop = true;
            halloweenBattleMusic.loop = true;
            menuMusic.volume = musicVolume;
            menuMusic.loop = true;
            battleMusic.volume = musicVolume;
            battleMusic.loop = true;
            cantinaBandAudio.volume = musicVolume;
            cantinaBandAudio.loop = true;
            mustafar_music.volume = musicVolume;
            deathstar_music.volume = musicVolume;
            halloweenBattleMusic.volume = musicVolume;
            bootStep(loadGameSettings);
            updateMarvelMusicButton();
            updateAurebeshToggleVisibility();

            function applyMusicVolume() {
                menuMusic.volume = musicVolume;
                battleMusic.volume = musicVolume;
                halloweenBattleMusic.volume = musicVolume;
                cantinaBandAudio.volume = musicVolume;
                mustafar_music.volume  = musicVolume;
                deathstar_music.volume = musicVolume;
            }

            function updateMusicSources() {
                // Clearing the Zero Event does not add a control — it changes what
                // the old season soundtrack is, both halves of it, for good.
                const menuSrc   = marvelSoundtrackEnabled ? marvelMenuMusicSrc   : defaultMenuMusicSrc;
                const battleSrc = marvelSoundtrackEnabled ? marvelBattleMusicSrc : defaultBattleMusicSrc;
                if (!menuMusic.src.endsWith(menuSrc)) {
                    const wasPlaying = !menuMusic.paused && !menuMusic.ended;
                    menuMusic.pause();
                    menuMusic.currentTime = 0;
                    menuMusic.src = menuSrc;
                    menuMusic.load();
                    if (wasPlaying && currentMusic === menuMusic && musicStarted) {
                        menuMusic.play().catch(() => {});
                    }
                }
                if (!battleMusic.src.endsWith(battleSrc)) {
                    const wasPlaying = !battleMusic.paused && !battleMusic.ended;
                    battleMusic.pause();
                    battleMusic.currentTime = 0;
                    battleMusic.src = battleSrc;
                    battleMusic.load();
                    if (wasPlaying && currentMusic === battleMusic && musicStarted) {
                        battleMusic.play().catch(() => {});
                    }
                }
                applyMusicVolume();
            }

            // ── SOUND EFFECTS ─────────────────────────────────────────
            // Every SFX comes out of the "sounds" folder. No percent-encoding needed
            // now that the name has no space in it — if it ever regains one, encode
            // it here rather than relying on browsers to tolerate a literal space,
            // which is not safe across every static host.
            const SFX_DIR = 'sounds/';

            // Base levels are deliberately quiet — the replacement samples are
            // hotter than the ones they replace, so these are the old values
            // shaved by roughly 15%. Each is multiplied by the player's SFX
            // slider in applySfxVolume(), so this table is the *ceiling*.
            const sfxBaseVolumes = {
                zap:                  0.10,
                forceLightning:       0.09,  // new sample runs far longer than the old one — it sustains, so it sits lower
                bluntHit:             0.09,  // sits with the swing and dash rather than the clash — it fires on every landed hit
                blasterShot:          0.13,
                // Measured ~20% hotter than Blaster.mp3 over its loudest 150ms, so
                // it sits that much under the blaster to land at the same weight.
                quadBlasterShot:      0.11,
                // Measured 1dB over Blaster.mp3 and 1dB under the Quad over the
                // same loudest 150ms, so it sits between the two.
                halloweenBlasterShot: 0.12,
                bowcasterShot:        0.12,
                gunshot:              0.13,
                // Ten shots a second makes this the most-repeated sample in the
                // game, so it sits well under the single-shot weapons — same
                // reasoning as the saber swing sitting under the clash.
                minigun:              0.08,
                sniper:               0.14,  // one heavy shot every 950ms; it can afford the weight
                dash:                 0.09,
                lightsaberIgnite:     0.12,
                lightsaberIgniteSith: 0.12,
                lightsaberHum:        0.07,  // loops underneath everything for a whole match
                lightsaberHumSith:    0.07,
                lightsaberClash:      0.13,
                lightsaberDeflect:    0.10,
                lightsaberSwing:      0.09,  // fires on every swing, hit or miss — kept well under the clash
                lightsaberSwingSith:  0.09,
                lightsaberThrow:      0.11,
                lightsaberReturn:     0.10,
                // The Darksaber set mirrors the lightsaber levels exactly — same
                // role in the mix, same weapon class, so it should sit at the same
                // height. Only the samples differ.
                darksaberIgnite:      0.12,
                darksaberHum:         0.07,
                darksaberSwing:       0.09,
                darksaberThrow:       0.11,
                darksaberReturn:      0.10,
                // Electrostaff sits at the same levels again — same weapon class,
                // same job in the mix. Seven characters carry it, so the hum in
                // particular has to stay well under everything else.
                electrostaffIgnite:   0.12,
                electrostaffHum:      0.07,
                electrostaffSwing:    0.09,
                electrostaffThrow:    0.11,
                electrostaffClash:    0.13,  // matches lightsaberClash — it replaces it for staff impacts
                forceChoke:           0.11,  // one deliberate cast, not a rattle of shots — it can sit with the clash
                neckSnap:             0.14,  // a kill, and the loudest single thing Vader does — sits just above the clash
                flamethrower:         0.10,  // sustains under everything while the trigger is down, like the lightning stream
                // Marvel. The two web samples sit level with each other by
                // definition — they alternate at random on one weapon, so any gap
                // between them would read as the gun changing volume mid-burst.
                // 0.09 is the swing level, and for the same reason: this is the
                // fastest trigger in the season and it fires on every pull.
                webshooter1:          0.09,
                webshooter2:          0.09,
                // The draw runs for a full second underneath everything else, so it
                // sits at hum level rather than shot level. The release is a single
                // deliberate discharge and can sit up with the clash.
                repulsorCharge:       0.08,
                repulsorShoot:        0.12,
                // Hawkeye's, levelled with Iron Man's for the same reasons — a draw
                // that runs for a second sits at hum level, a release sits at shot
                // level. The two charge weapons with a voice should not be at
                // different heights in the mix.
                arrowCharge:          0.08,
                arrowShoot:           0.12,
                // A shade over bluntHit's 0.09, which it replaces for the fists and
                // only the fists. They are the hardest hits in the game — 115 a
                // landed swing, 172 inside a Hulk Smash — and the sample they used
                // to share is tuned for a wrench.
                punch:                0.12,
            };
            const sfxSounds = {
                zap:                  new Audio(SFX_DIR + 'Zap.mp3'),
                forceLightning:       new Audio(SFX_DIR + 'ForceLightning.mp3'),
                // Wrench / vibroblade impacts. This used to borrow
                // LightsaberClash.mp3 as a stand-in, which is why a wrench sounded
                // like a blade — the sounds folder ships BluntHit.mp3, so it uses it.
                bluntHit:             new Audio(SFX_DIR + 'BluntHit.mp3'),
                blasterShot:          new Audio(SFX_DIR + 'Blaster.mp3'),
                // Star-Lord's Quad Blasters. They borrowed Blaster.mp3 until this
                // shipped. 0.68s against a 620ms cooldown, so a held trigger barely
                // overlaps itself and it needs no entry in sfxMaxDurations.
                quadBlasterShot:      new Audio(SFX_DIR + 'QuadBlasterShot.mp3'),
                // The Halloween Blaster's own shot. 0.73s against an 850ms
                // cooldown, so it never overlaps itself and needs no entry in
                // sfxMaxDurations either.
                halloweenBlasterShot: new Audio(SFX_DIR + 'Halloween%20Blaster%20Shot.mp3'),
                bowcasterShot:        new Audio(SFX_DIR + 'Bowcaster.mp3'),
                gunshot:              new Audio(SFX_DIR + 'Gunshot.mp3'),
                // Both were borrowing other samples until now — the minigun fired
                // Blaster.mp3, the sniper fired Gunshot.mp3 alongside four other guns.
                minigun:              new Audio(SFX_DIR + 'Minigun.mp3'),
                sniper:               new Audio(SFX_DIR + 'Sniper.mp3'),
                dash:                 new Audio(SFX_DIR + 'Dash.mp3'),
                lightsaberIgnite:     new Audio(SFX_DIR + 'LightsaberIgnite.mp3'),
                lightsaberIgniteSith: new Audio(SFX_DIR + 'LightsaberIgniteSith.mp3'),
                lightsaberHum:        new Audio(SFX_DIR + 'LightsaberHum.mp3'),
                lightsaberHumSith:    new Audio(SFX_DIR + 'LightsaberHumSith.mp3'),
                lightsaberClash:      new Audio(SFX_DIR + 'LightsaberClash.mp3'),
                lightsaberDeflect:    new Audio(SFX_DIR + 'LightsaberDeflect.mp3'),
                lightsaberSwing:      new Audio(SFX_DIR + 'LightsaberSwing.mp3'),
                lightsaberSwingSith:  new Audio(SFX_DIR + 'LightsaberSwingSith.mp3'),
                lightsaberThrow:      new Audio(SFX_DIR + 'LightsaberThrow.mp3'),
                lightsaberReturn:     new Audio(SFX_DIR + 'LightsaberReturn.mp3'),
                // The Darksaber is one blade, not a faction — it gets a single set
                // rather than the Jedi/Sith split the lightsaber has. There is
                // deliberately no darksaberClash: it shares LightsaberClash.mp3.
                darksaberIgnite:      new Audio(SFX_DIR + 'DarksaberIgnite.mp3'),
                darksaberHum:         new Audio(SFX_DIR + 'DarksaberHum.mp3'),
                darksaberSwing:       new Audio(SFX_DIR + 'DarksaberSwing.mp3'),
                darksaberThrow:       new Audio(SFX_DIR + 'DarksaberThrow.mp3'),
                darksaberReturn:      new Audio(SFX_DIR + 'DarksaberReturn.mp3'),
                // Electrostaff — a crackling metal pole, not a plasma blade. Up to
                // now all seven of its wielders borrowed the lightsaber set outright.
                // Unlike the Darksaber this one does have its own clash. There is no
                // ElectrostaffReturn sample, so a thrown staff still comes home on
                // the lightsaber's — see bladeReturnSfx().
                electrostaffIgnite:   new Audio(SFX_DIR + 'ElectrostaffIgnite.mp3'),
                electrostaffHum:      new Audio(SFX_DIR + 'ElectrostaffHum.mp3'),
                electrostaffSwing:    new Audio(SFX_DIR + 'ElectrostaffSwing.mp3'),
                electrostaffThrow:    new Audio(SFX_DIR + 'ElectrostaffThrow.mp3'),
                electrostaffClash:    new Audio(SFX_DIR + 'ElectrostaffClash.mp3'),
                // Vader's Force Choke — see the FORCE CHOKE section further down.
                // Drop ForceChoke.mp3 into sounds/ to give it a voice; until then
                // the loading screen's error handler counts it as resolved and the
                // ability simply casts silently rather than blocking the boot.
                forceChoke:           new Audio(SFX_DIR + 'ForceChoke.mp3'),
                // The neck snap that finishes a choke — a short, dry one-shot.
                neckSnap:             new Audio(SFX_DIR + 'NeckSnap.mp3'),
                // A ~9s continuous roar. Looped and sustained rather than played
                // per shot — see pulseFlamethrower().
                flamethrower:         new Audio(SFX_DIR + 'Flamethrower.mp3'),

                // ── MARVEL ─────────────────────────────────────────────────
                // These four filenames carry spaces as they were authored, and the
                // space is written as %20 rather than left bare: an Audio src is a
                // URL, and a raw space is the one character that does not survive
                // every route this page is opened by (file://, a static host, an
                // itch.io zip). Rename the files and this is the only line to touch.
                //
                // Two web shooter samples, picked between at random on every pull —
                // see playWeaponFireSfx(). Nothing else in the game does this; it is
                // Spider-Man's alone and it is there because the primary is the
                // fastest trigger in the season at 190ms, so one sample repeated at
                // that rate reads as a stuck loop rather than as web-slinging.
                webshooter1:          new Audio(SFX_DIR + 'Webshooter%201.mp3'),
                webshooter2:          new Audio(SFX_DIR + 'Webshooter%202.mp3'),
                // Iron Man's draw and release. The chargeup is the only sample in
                // the game played through its ORIGINAL element rather than a clone,
                // because it is the only one that has to be STOPPED on command —
                // stopSound() reaches sfxSounds entries and a clone is unreachable
                // by name. One element models one draw, which is exactly the
                // constraint: chargeShot holds one draw at a time.
                repulsorCharge:       new Audio(SFX_DIR + 'Repulsor%20Chargeup.mp3'),
                repulsorShoot:        new Audio(SFX_DIR + 'Repulsor%20Shoot.mp3'),
                // Hawkeye's draw and loose, the second weapon to use the machinery
                // the Repulsors brought in. The draw sample is ~1.05s against the
                // bow's 1200ms full draw, so the last ~150ms of a maximum pull are
                // silent — the bow's timing is a documented balance number and the
                // sample bends to it rather than the other way round.
                arrowCharge:          new Audio(SFX_DIR + 'Arrow%20Charge.mp3'),
                arrowShoot:           new Audio(SFX_DIR + 'Arrow%20Shoot.mp3'),
                // A fist landing. Every blunt weapon in the game shared one clang
                // until this arrived; now the five fist sets get their own and
                // everything else — hammers, metal blades, claws, the shield —
                // keeps BluntHit. See the impact branch in applyStatusAndDamage.
                punch:                new Audio(SFX_DIR + 'Punch.mp3'),
            };

            sfxSounds.lightsaberHum.loop = true;
            sfxSounds.lightsaberHumSith.loop = true;
            // Same mechanics as the lightsaber hum: looped, started ~900ms after the
            // ignite, remembered in activeSaberHumKey so a pause can restore it.
            sfxSounds.darksaberHum.loop = true;
            sfxSounds.electrostaffHum.loop = true;
            // Sustained while the trigger is held — see pulseForceLightning()
            // and pulseFlamethrower().
            sfxSounds.forceLightning.loop = true;
            sfxSounds.flamethrower.loop = true;

            // Dark-side blades get their own ignite / hum / swing set. Roster
            // faction is the primary signal; the colour test is the fallback that
            // catches dark-siders living outside characters.villains (secret and
            // unplayable entries). Resolved lazily — `characters` is declared
            // further down this scope, and this is only ever asked mid-fight.
            let sithSaberIds = null;
            function usesSithSaber(entity) {
                if (!entity) return false;
                const wk = entity.weaponConfig ? entity.weaponConfig.key : entity.weapon;
                if (wk !== 'lightsaber' && wk !== 'darksaber') return false;
                if (sithSaberIds === null) {
                    sithSaberIds = new Set(characters.villains.map(c => c.id));
                }
                if (sithSaberIds.has(entity.characterId)) return true;
                const hex = /^#([0-9a-f]{6})$/i.exec(entity.saberColor || '');
                if (!hex) return false;
                const n = parseInt(hex[1], 16);
                const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
                return r > 120 && r > g * 1.8 && r > b * 1.8;
            }

            // Weapons that hit rather than cut: no hum, no ignition, nothing to hear
            // until they connect with something. Kept as one list because the two
            // places that used to spell it out had drifted — the swing counted the
            // vibroblade as blunt and the impact did not, so a thrown vibroblade
            // clanged on the throw and landed in silence.
            // Anything that is metal rather than energy belongs here. The three
            // weapons added with the Zero Event and Bastian were all missing, so all
            // three ignited on the countdown, hummed while carried and rang like a
            // lightsaber on every swing — a Minecraft sword and a hedgehog were
            // making Jedi noises, and so was a steel blade.
            const BLUNT_WEAPON_KEYS = new Set([
                'wrench', 'vibroblade', 'seekerssword',
                // Asgard's two, and both belong here for the reason above: a
                // hammer and a steel blade are metal, so they are silent through
                // the air and their whole voice is the impact.
                'mjolnir', 'laevateinn',
                // Fists, both sets. Nothing about a punch whistles, and the whole of
                // it is the landing — which is exactly the rule the two above are
                // here for.
                'gammafists', 'thingfists',
                // The rest of the Marvel melee, all of it missed when the season
                // landed. Every one of these is metal, rock, bark or claw, and every
                // one of them was whistling like a lightsaber on the swing and then
                // landing in silence — the two halves of the same omission, because
                // this list is read at both ends (the swing at ~15161, the impact at
                // ~15908, where anything not in here and not a saber makes no sound
                // at all). A vibranium shield does not hum through the air.
                //
                // The remaining three fist sets, for the reason the first two are
                // here.
                'grootfists', 'mongerfists', 'abomfists',
                // Thanos's. A gold glove full of stones is still a fist.
                'gauntletfists',
                // Ant-Man's, and his ants'. Fists at any size.
                'antmanfists', 'antbite',
                // Both sets of claws. They are keratin and metal on the ends of
                // arms; the noise is the rake landing.
                'claws', 'pantherclaws',
                // Wakanda's blade and Groot's axe. Worked metal, same as the
                // Vibroblade and Mjølnir respectively — and Stormbreaker in
                // particular is Mjølnir's sibling out of the same forge, so leaving
                // it out had the axe ringing like a saber while the hammer did not.
                'scimitar', 'stormbreaker',
                // Ice is matter. It is silent through the air and speaks when it
                // lands, the same as every blade above it.
                'icedagger',
                // The shield. It is thrown and caught far more than it is swung, and
                // a disc of vibranium is the least saber-like object on the roster.
                'shield',
                // Deadpool's katanas. Steel, so the same rule as the scimitar.
                'katanas',
                // The Skeleton Warriors' swords, burnt or not. Same rule again.
                'skeletonsword'
            ]);
            function isBluntWeapon(weaponKey) {
                return BLUNT_WEAPON_KEYS.has(weaponKey);
            }

            /*  The six fist sets — Hulk's, The Thing's, Groot's, the Iron Monger's,
             *  the Abomination's and Thanos's — which land on Punch.mp3 rather than
             *  on the clang every other blunt weapon shares.
             *
             *  Read off sprite-kit's own family table rather than listed again here.
             *  That table already has to know which weapons are fists (it is what
             *  gives them hands-forward poses with no hilt), and BLUNT_WEAPON_KEYS
             *  three lines up is a standing reminder of what happens when the same
             *  fact is written down in two places. A sixth pair of fists registers
             *  in sprite-kit and picks this up by existing.                       */
            function isFistWeapon(weaponKey) {
                return SpriteKit.familyOf(baseKeyOf(weaponKey)) === 'fists';
            }

            function bladeKeyOf(entity) {
                if (!entity) return null;
                return entity.weaponConfig ? entity.weaponConfig.key : entity.weapon;
            }
            function usesDarksaber(entity) {
                return bladeKeyOf(entity) === 'darksaber';
            }
            function usesElectrostaff(entity) {
                return bladeKeyOf(entity) === 'staff';
            }

            /** The three weapons that are energy rather than matter, and so the only
             *  ones with a voice while they are in the air. Everything else that
             *  throws — Mjølnir, Lævateinn, the Wakandan Scimitar, Stormbreaker, the
             *  Vibranium Shield — is silent out AND silent back, with its whole noise
             *  in the landing, which is the rule BLUNT_WEAPON_KEYS states.
             *
             *  One predicate rather than the condition written out at each site: the
             *  throw spelled it out inline and the catch did not, so every returnable
             *  metal weapon in the game left the hand silently and then came home on
             *  LightsaberReturn.mp3. That is the third time this exact drift has
             *  happened (see the note on BLUNT_WEAPON_KEYS), so it is a function now.
             *
             *  baseKeyOf() so a forged saber still counts as one. */
            function isEnergyBlade(weaponKey) {
                const k = baseKeyOf(weaponKey);
                return k === 'lightsaber' || k === 'darksaber' || k === 'staff';
            }

            /** Throw sample for a returnable blade, by weapon key. */
            function bladeThrowSfx(weaponKey) {
                if (weaponKey === 'darksaber') return 'darksaberThrow';
                if (weaponKey === 'staff') return 'electrostaffThrow';
                return 'lightsaberThrow';
            }
            /** Catch sample. No ElectrostaffReturn exists, so the staff borrows the
             *  lightsaber's — add one and give it a branch here. */
            function bladeReturnSfx(weaponKey) {
                return weaponKey === 'darksaber' ? 'darksaberReturn' : 'lightsaberReturn';
            }

            /** Pick the right variant of a saber sound for this wielder.
             *
             *  Three blades, one chokepoint: every ignite, hum and swing routes
             *  through here, so the Darksaber only had to be taught once. It is a
             *  single weapon rather than a faction, so it takes its own set outright
             *  instead of the Jedi/Sith split — Sabine, Mando Elite and Gideon all
             *  sound the same swinging it, which is the point.
             *
             *  Deliberately no clash entry: the Darksaber uses LightsaberClash.mp3,
             *  handled where impacts are keyed on projectile type. */
            function saberSfx(entity, baseName) {
                if (usesDarksaber(entity)) return baseName.replace('lightsaber', 'darksaber');
                if (usesElectrostaff(entity)) return baseName.replace('lightsaber', 'electrostaff');
                return usesSithSaber(entity) ? baseName + 'Sith' : baseName;
            }

            function applySfxVolume() {
                Object.keys(sfxSounds).forEach(k => {
                    sfxSounds[k].volume = (sfxBaseVolumes[k] || 0.12) * sfxVolume;
                });
            }
            applySfxVolume();

            // ── LOADING SCREEN ─────────────────────────────────────────
            (function initLoadingScreen() {
                const loadingScreen = document.getElementById('loadingScreen');
                const loadingRing = document.getElementById('loadingRing');
                const loadingRingFill = document.getElementById('loadingRingFill');
                const loadingPct = document.getElementById('loadingPct');
                const loadingTip = document.getElementById('loadingTip');
                const manifestLines = Array.from(document.querySelectorAll('#loadingManifest .loading-manifest-line'));
                if (!loadingScreen) return;

                // The ring is one stroked circle: draw it by shrinking the dash gap
                // from a full circumference down to nothing.
                const RING_LENGTH = 2 * Math.PI * 52; // r=52, matching the markup
                if (loadingRingFill) {
                    loadingRingFill.style.strokeDasharray = RING_LENGTH.toFixed(1);
                    loadingRingFill.style.strokeDashoffset = RING_LENGTH.toFixed(1);
                }

                // The reveal animations run about 1.6s before the card is fully
                // assembled. On a warm cache the audio resolves faster than that,
                // and the screen would blink out mid-animation. This holds the
                // intro just long enough to finish — it is not the old fake
                // progress pad: the ring below always tracks real bytes.
                const INTRO_MS = 2200;
                const startedAt = Date.now();

                const assetsToTrack = [
                    menuMusic, battleMusic, cantinaBandAudio,
                    mustafar_music, deathstar_music,
                    ...Object.values(sfxSounds)
                ];
                const total = assetsToTrack.length;
                let loaded = 0;
                let finished = false;

                // The ring reports real asset progress on every host. itch.io builds
                // used to pad it out to a fake ~10s minimum — a deliberately
                // stuttering illusion so the hints below had time to be read — which
                // meant players sat waiting on a timer rather than on the game. Hints
                // still cycle; they just show for however long the load really takes.
                // There was a tip here telling every player to verify an itch.io
                // username for the dev menu. That box is for players vetted over
                // Discord, so it is not advertised.
                const LOADING_HINTS = [
                    'Tip: Higher difficulty and tougher opponents earn you more credits.'
                ];
                let hintIndex = 0;
                let hintTimer = null;

                function startHintCycle() {
                    if (!loadingTip || LOADING_HINTS.length === 0) return;
                    loadingTip.textContent = LOADING_HINTS[0];
                    if (LOADING_HINTS.length < 2) return;
                    hintTimer = setInterval(() => {
                        hintIndex = (hintIndex + 1) % LOADING_HINTS.length;
                        loadingTip.classList.add('loading-tip-fade');
                        setTimeout(() => {
                            loadingTip.textContent = LOADING_HINTS[hintIndex];
                            loadingTip.classList.remove('loading-tip-fade');
                        }, 200);
                    }, 4500);
                }

                function stopHintCycle() {
                    if (hintTimer) { clearInterval(hintTimer); hintTimer = null; }
                }

                // Assets land in lumps — a dozen sound effects can resolve in the
                // same tick. Easing the drawn value toward the real one keeps the
                // ring sweeping and the number climbing instead of teleporting.
                let targetPct = 0;
                let shownPct = 0;
                let pctRafId = null;

                function paintProgress(value) {
                    const whole = Math.round(value);
                    if (loadingPct) loadingPct.textContent = whole;
                    if (loadingRingFill) {
                        loadingRingFill.style.strokeDashoffset =
                            (RING_LENGTH * (1 - value / 100)).toFixed(1);
                    }
                    // Light the manifest as the load passes each line's threshold;
                    // the first unlit line pulses so there is always a live one.
                    let activeTaken = false;
                    for (const line of manifestLines) {
                        const done = whole >= (Number(line.dataset.at) || 0);
                        line.classList.toggle('is-done', done);
                        line.classList.toggle('is-active', !done && !activeTaken);
                        if (!done) activeTaken = true;
                    }
                }

                function stepProgress() {
                    pctRafId = null;
                    shownPct += (targetPct - shownPct) * 0.12;
                    if (Math.abs(targetPct - shownPct) < 0.4) shownPct = targetPct;
                    paintProgress(shownPct);
                    if (shownPct !== targetPct) pctRafId = requestAnimationFrame(stepProgress);
                }

                function updateRealProgress() {
                    targetPct = total > 0 ? Math.min(100, Math.round((loaded / total) * 100)) : 100;
                    if (pctRafId === null) pctRafId = requestAnimationFrame(stepProgress);
                }

                function finishLoading() {
                    if (finished) return;
                    finished = true;
                    stopHintCycle();

                    targetPct = 100;
                    if (pctRafId === null) pctRafId = requestAnimationFrame(stepProgress);
                    if (loadingRing) loadingRing.classList.add('is-complete');
                    if (loadingTip) {
                        loadingTip.classList.remove('loading-tip-fade');
                        loadingTip.textContent = 'Ready!';
                    }

                    // Let the ring visibly close and the intro finish playing, then
                    // warp out. Both waits run at once, so a slow load — which has
                    // already outlasted the intro — only pays for the ring.
                    const introLeft = Math.max(0, INTRO_MS - (Date.now() - startedAt));
                    setTimeout(() => {
                        loadingScreen.classList.add('loading-done');
                        setTimeout(() => {
                            loadingScreen.style.display = 'none';
                            // The first time the splash is genuinely visible. It is up
                            // from the first paint, but behind this screen until now,
                            // and the intro measures live tile rects — so it cannot
                            // start any earlier than this. Vaulted, it only settles
                            // the menu: see offerSnapIntro().
                            offerSnapIntro();
                        }, 600);
                    }, Math.max(500, introLeft));
                }

                function bumpProgress() {
                    loaded++;
                    updateRealProgress();
                    if (loaded >= total) finishLoading();
                }

                startHintCycle();
                updateRealProgress();

                if (total === 0) {
                    finishLoading();
                    return;
                }

                assetsToTrack.forEach(audio => {
                    try { audio.preload = 'auto'; } catch (e) {}
                    if (audio.readyState >= 3) { // HAVE_FUTURE_DATA or better — already good to go
                        bumpProgress();
                        return;
                    }
                    const onReady = () => {
                        audio.removeEventListener('canplaythrough', onReady);
                        audio.removeEventListener('loadeddata', onReady);
                        audio.removeEventListener('error', onReady);
                        bumpProgress();
                    };
                    audio.addEventListener('canplaythrough', onReady, { once: true });
                    audio.addEventListener('loadeddata', onReady, { once: true });
                    audio.addEventListener('error', onReady, { once: true });
                    try { audio.load(); } catch (e) {}
                });

                // Safety net — never block the player indefinitely, e.g. if a browser
                // declines to fire load events while the tab is backgrounded. Set
                // above the old itch ceiling so a genuinely slow connection pulling
                // the ~36 MB of audio is not cut off early; on a warm cache or a local
                // build the assets resolve long before this and it never fires.
                setTimeout(finishLoading, 15000);
            })();

            // Cooldowns to prevent sound spam (ms timestamps). This used to be five
            // hardcoded `_last*` variables, which meant every sound outside that
            // list silently ignored the minGapMs its caller passed — force
            // lightning, saber throws and melee hits all asked to be rate-limited
            // and never were. One map covers every sound, new ones included.
            const _lastSfxPlay = new Map();

            // Every one-shot plays on a detached clone, so the elements sitting in
            // sfxSounds are not the ones actually making noise. This set is the only
            // handle on what is currently audible: silenceAllSfx() needs it to mute
            // instantly, and the length caps below need it to tell a clone that is
            // still playing from one that already finished.
            const _activeSfxClones = new Set();

            // ── ONE-SHOT LENGTH CAPS ───────────────────────────────────────
            // The samples in the sounds folder are uncut: several ring on past the
            // moment they illustrate. A fight then stacks those tails — a saber
            // throw still sustaining while the next throw, a clash and a deflect
            // all start — and overlapping tails sum, so the mix reads as one loud
            // wash instead of four separate events. Every one-shot is therefore
            // faded out and stopped at the cap below.
            //
            // Only the sounds listed here are capped — the saber throw is the one
            // one-shot long enough to be a problem (force lightning is the other
            // offender, but it loops, so it is handled by its own sustain window
            // instead: see LIGHTNING_SUSTAIN_MS). Everything absent plays in full.
            //
            // These are ceilings, not durations: a cap longer than its sample
            // never fires, because the clone reports `ended` and is released
            // first. Trim one if a sound still outstays its welcome.
            const SFX_FADE_MS = 70; // faded, not hard-stopped — a bare cut clicks
            const sfxMaxDurations = {
                lightsaberThrow: 550,  // the throw is the wind-up, not the flight
                // Same reasoning, same number: the raw sample runs ~4s, which is
                // most of a blade's round trip. The ignite, swing and clash are all
                // ~1s or under and stay uncapped, exactly like their lightsaber
                // counterparts.
                electrostaffThrow: 550,
                // ForceChoke.mp3 runs ~2s and the grip holds for 2s, so the sample
                // lands almost exactly on the release — nothing to cap. An 8s
                // cooldown also means it can never stack on itself the way the
                // saber throw does.
            };

            // Fades are tracked per element so a sound that restarts mid-fade can
            // cancel it and get its volume back — without this, retriggering a
            // fading sample leaves it stuck quiet, or silences it entirely when
            // the fade lands after the restart.
            const _sfxFades = new Map(); // element -> { timer, startVol }

            function cancelSfxFade(el) {
                const f = _sfxFades.get(el);
                if (!f) return;
                clearInterval(f.timer);
                _sfxFades.delete(el);
                try { el.volume = f.startVol; } catch (err) {}
            }

            /** Fade `el` to silence over `ms`, then stop it and restore its volume
             *  so the element can be played again. */
            function fadeOutAudio(el, ms, done) {
                cancelSfxFade(el);
                const startVol = el.volume;
                const steps = Math.max(1, Math.round(ms / 20));
                let step = 0;
                const timer = setInterval(() => {
                    step++;
                    try { el.volume = Math.max(0, startVol * (1 - step / steps)); } catch (err) {}
                    if (step >= steps) {
                        clearInterval(timer);
                        _sfxFades.delete(el);
                        el.pause();
                        try { el.currentTime = 0; } catch (err) {}
                        try { el.volume = startVol; } catch (err) {}
                        if (done) done();
                    }
                }, 20);
                _sfxFades.set(el, { timer, startVol });
            }

            // ── FORCE LIGHTNING: a sustained stream, not a burst ───────────
            // The weapon looses a projectile every 280ms, and playing the sample
            // once per projectile machine-gunned its attack transient. Instead the
            // sample loops from the first shot and is cut shortly after the wielder
            // stops firing: a tap is one clean crackle, a held trigger is continuous.
            // Sustain only has to outlast the weapon's 280ms cooldown (plus a frame
            // or two of slack) for a held trigger to sound continuous. It used to
            // run 450ms, which left the stream crackling well after the last bolt
            // and stacked under the next burst; 400 still covers the gap comfortably
            // while letting go sooner. The stop is faded, not cut — see
            // updateForceLightningLoop.
            const LIGHTNING_SUSTAIN_MS = 400;
            let lightningSustainUntil = 0;

            // Same treatment for the flamethrower, and for the same reason: the
            // sample is a ~9s continuous roar, and it fires every 70ms. Restarting
            // a 9-second sample seventy times a second would stack a hundred
            // overlapping copies into a wall of noise. It loops from the first
            // shot instead and is cut shortly after the last one.
            //
            // The window only has to outlast the weapon's 70ms cooldown plus a
            // frame or two of slack for held fire to sound unbroken. 200ms covers
            // it comfortably while still letting go promptly on release.
            const FLAME_SUSTAIN_MS = 200;
            let flameSustainUntil = 0;

            function playSound(name, minGapMs = 50) {
                if (sfxVolume === 0) return;
                const snd = sfxSounds[name];
                if (!snd) return;
                // Looping sounds (the saber hum, force lightning) are start/stop
                // rather than one-shots, so they bypass the throttle entirely.
                if (snd.loop) {
                    // Retriggering during the tail fade (lightning fired again just
                    // as the stream was being cut) must take its volume back first.
                    cancelSfxFade(snd);
                    if (snd.paused) snd.play().catch(() => {});
                    return;
                }
                const now = Date.now();
                if (now - (_lastSfxPlay.get(name) || 0) < minGapMs) return;
                _lastSfxPlay.set(name, now);
                // Clone for overlapping one-shots
                const clone = snd.cloneNode();
                clone.volume = snd.volume;
                _activeSfxClones.add(clone);
                // Release the reference however it finishes — played out, errored,
                // or rejected — so the set only ever holds what is really audible.
                const release = () => _activeSfxClones.delete(clone);
                clone.addEventListener('ended', release, { once: true });
                clone.addEventListener('error', release, { once: true });
                clone.play().catch(release);

                // Cut an over-long sample before its tail can pile onto the next one.
                const cap = sfxMaxDurations[name];
                if (cap) {
                    setTimeout(() => {
                        // Gone already — played out on its own, or stopped wholesale
                        // when the fight ended. Either way there is nothing to fade.
                        if (!_activeSfxClones.has(clone)) return;
                        fadeOutAudio(clone, SFX_FADE_MS, release);
                    }, Math.max(0, cap - SFX_FADE_MS));
                }
            }

            function stopSound(name) {
                const snd = sfxSounds[name];
                if (!snd) return;
                cancelSfxFade(snd);
                snd.pause();
                snd.currentTime = 0;
            }

            /** Stop the sustained sounds when a fight ends or the pause menu opens.
             *
             *  Only the looping originals are stopped. One-shots already in flight
             *  are deliberately left to finish: they are short, the long ones now
             *  fade out on their own (sfxMaxDurations), and cutting a volley of
             *  them mid-flight is the abrupt clipping this is all trying to avoid.
             *
             *  Force lightning is a loop too, so it has to go with the hums even
             *  though it is not one: pausing cancels the animation frame, and
             *  updateForceLightningLoop() is the only thing that would ever cut
             *  it — left running it would drone under the menu forever. */
            function stopAllSfx() {
                stopSound('lightsaberHum');
                stopSound('lightsaberHumSith');
                stopSound('darksaberHum');
                stopSound('electrostaffHum');
                if (!sfxSounds.forceLightning.paused) {
                    fadeOutAudio(sfxSounds.forceLightning, SFX_FADE_MS);
                }
                if (!sfxSounds.flamethrower.paused) {
                    fadeOutAudio(sfxSounds.flamethrower, SFX_FADE_MS);
                }
                // A silenced stream must not still believe it is sustaining, or it
                // would never restart on the next shot.
                lightningSustainUntil = 0;
                flameSustainUntil = 0;
            }

            /** Immediate, total silence — originals and in-flight one-shots alike.
             *  Only for muting: turning the SFX slider to zero has to take effect
             *  now, and clones carry the volume they were created with, so letting
             *  them ring out would keep playing sound the player just switched off. */
            function silenceAllSfx() {
                Object.keys(sfxSounds).forEach(k => stopSound(k));
                _activeSfxClones.forEach(clone => {
                    // Kill any in-flight length-cap fade first, or its timer keeps
                    // ticking against an element that is already stopped.
                    cancelSfxFade(clone);
                    clone.pause();
                    try { clone.currentTime = 0; } catch (e) {}
                });
                _activeSfxClones.clear();
                lightningSustainUntil = 0;
                flameSustainUntil = 0;
            }

            /** Start or extend the lightning stream. Called on every lightning shot. */
            function pulseForceLightning() {
                lightningSustainUntil = Date.now() + LIGHTNING_SUSTAIN_MS;
                playSound('forceLightning');
            }

            /** Start the lightning stream for a cast that holds it by its own beam
             *  rather than by a sustain window: the Unibeam and Zero Shock. Each is one
             *  cast on a long cooldown, not a held trigger, so there is no next shot
             *  for LIGHTNING_SUSTAIN_MS to bridge to. Both used to go through
             *  playSound('forceLightning') with no sustain at all, and since nothing
             *  else cuts this loop it crackled on until the sample ran out, long after
             *  the beam was gone. Now it lasts exactly as long as the beam:
             *  updateForceLightningLoop keeps it up while lightningBeamActive() says
             *  so, and lets go the frame that stops being true. */
            function startBoltHeldLightning() {
                lightningSustainUntil = Date.now();
                playSound('forceLightning');
            }

            /** Is a beam that holds the lightning stream still going? True while Zero
             *  Shock is open on a living Zero, or while any Unibeam or Zero Shock bolt
             *  is still in the air, so the crackle ends when the last bolt hits
             *  someone, is blocked or runs out of range. Plain loops, not .some():
             *  this runs every frame the stream is up. */
            function lightningBeamActive() {
                for (let i = 0; i < bullets.length; i++) {
                    const t = bullets[i].type;
                    if (t === 'unibeam' || t === 'zeroshock') return true;
                }
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (e.zeroShockUntil && e.isAlive && isZeroShocking(e)) return true;
                }
                return false;
            }

            /** Cut the lightning loop once firing stops. Driven from the game loop.
             *  Faded rather than paused outright: this sample sustains, so dropping
             *  it mid-crackle at full volume is audible as a click. */
            function updateForceLightningLoop() {
                // A live beam keeps the stream alive. Max, not assign, so a longer
                // sustain from ordinary lightning fire is never cut short by it.
                if (lightningSustainUntil && lightningBeamActive()) {
                    lightningSustainUntil = Math.max(lightningSustainUntil, Date.now());
                }
                if (lightningSustainUntil && Date.now() > lightningSustainUntil) {
                    lightningSustainUntil = 0;
                    fadeOutAudio(sfxSounds.forceLightning, SFX_FADE_MS);
                }
            }

            /** Start or extend the flame roar. Called on every flamethrower shot. */
            function pulseFlamethrower() {
                flameSustainUntil = Date.now() + FLAME_SUSTAIN_MS;
                playSound('flamethrower');
            }

            /** Cut the flame loop once firing stops. Faded, not paused — a 9-second
             *  roar chopped off at full volume clicks. */
            function updateFlamethrowerLoop() {
                if (flameSustainUntil && Date.now() > flameSustainUntil) {
                    flameSustainUntil = 0;
                    fadeOutAudio(sfxSounds.flamethrower, SFX_FADE_MS);
                }
            }

            /*  ── THE VOICE OF A DRAW ───────────────────────────────────────────
             *  A charged weapon may name a sample to run while it is being drawn
             *  back. Two do, and they set the sample against the draw from opposite
             *  directions:
             *
             *    Repulsors  the draw was tuned TO the sample — 1050ms of charge for
             *               1050ms of whine, so a full draw lands on its last frame
             *    Bow        the sample bends to the draw — 1200ms is a balance number
             *               with a documented cost attached, so the ~1.05s of arrow
             *               creak simply finishes early and the last 150ms are quiet
             *
             *  The Bowcaster and the Computer name nothing and stay silent, which is
             *  what an absent entry means rather than an omission.
             *
             *  Played through the original sfxSounds element, NOT through
             *  playSound(). playSound clones for overlap and a clone cannot be
             *  stopped by name afterwards — and stopping on command is the entire
             *  requirement here, because a draw can end early in more ways than it
             *  can end late: released at 20%, interrupted, weapon swapped, stunned,
             *  round over. One element is also the honest model, since chargeShot
             *  holds one draw at a time.
             *
             *  Player-only for that same reason. An AI Iron Man draws (aiChargeStart)
             *  and telegraphs it with the ring meter, but several of them can draw at
             *  once and one element cannot voice two. The SHOT is not player-only —
             *  that lives in playWeaponFireSfx and fires for everyone.              */
            const CHARGE_DRAW_SFX = { repulsor: 'repulsorCharge', bow: 'arrowCharge' };

            function chargeDrawSfxFor(weaponKey) {
                return CHARGE_DRAW_SFX[baseKeyOf(weaponKey)] || null;
            }

            function startChargeDrawSfx(weaponKey) {
                const name = chargeDrawSfxFor(weaponKey);
                if (!name || sfxVolume === 0) return;
                const el = sfxSounds[name];
                if (!el) return;
                // Restart from the top rather than resuming: a second draw is a
                // second wind-up, not the continuation of the first.
                cancelSfxFade(el);
                try { el.currentTime = 0; } catch (err) {}
                el.play().catch(() => {});
            }

            function stopChargeDrawSfx(weaponKey) {
                const name = chargeDrawSfxFor(weaponKey);
                if (name) stopSound(name);
            }

            /** The voice of a weapon being fired, for every shooter and every
             *  firing path.
             *
             *  This chain used to be written out three times — once in
             *  fireProjectile(), once in fireSpreadProjectiles() and once in the
             *  AI's shooting branch — and the copies had drifted: the Submachine
             *  Gun and the Warforged AR were missing from all three, so Big
             *  Chuggus and Poseidon fired in total silence while the five other
             *  rifles in the same family (and the same 🔫 in the HUD) all cracked.
             *  Same reasoning as BLUNT_WEAPON_KEYS above — one list, one place to
             *  add a weapon to, and no way for the paths to disagree again.
             *
             *  The two sustained weapons do not play here: they loop, and their
             *  pulse helpers extend a window that the game loop fades out once
             *  firing stops. Calling playSound on a looping sample directly would
             *  start something nothing ever ends.
             *
             *  Weapons deliberately absent are the silent ones: every melee key
             *  (a blade is heard when it lands, not when it swings), and the
             *  exotic energy weapons that ship no sample of their own. */
            function playWeaponFireSfx(weaponConfig) {
                const wk = weaponConfig.key;
                // Star-Lord's Quad Blasters have their own sample. They used to ride
                // Blaster.mp3 — four bolts out of two barrels, and that is already
                // the sound of a bolt leaving one — until QuadBlasterShot.mp3 was
                // made for them.
                //
                // Deliberately ONE call for the whole volley, not one per bolt.
                // Every multishot weapon looses its projectiles inside
                // fireSpreadProjectiles(), which calls this once afterwards, and the
                // AI's inlined branch is built the same way — so four bolts cost one
                // noise without either path having to know. Played per projectile
                // they would stack four copies on the same millisecond, which sums
                // into a single clipped crack instead of reading as a volley. The
                // 620ms cooldown clears the 60ms throttle comfortably, so no pull is
                // ever dropped for coming too quickly after the last.
                // The Hydra Pistol fires an energy round, so it takes the blaster's
                // sample rather than the gunshot. Its 260ms trigger clears the 60ms
                // throttle, so no pull is dropped.
                if (wk === 'blaster' || wk === 'hydrapistol') playSound('blasterShot', 60);
                else if (wk === 'quadblaster') playSound('quadBlasterShot', 60);
                // The Halloween Blaster has its own sample. Its 850ms trigger never
                // comes near the throttle.
                else if (wk === 'halloweenblaster') playSound('halloweenBlasterShot', 60);
                else if (wk === 'minigun') playSound('minigun', 60);
                else if (wk === 'flamethrower') pulseFlamethrower();
                else if (wk === 'sniper' || wk === 'boomsniper') playSound('sniper', 200);
                else if (wk === 'bowcaster') playSound('bowcasterShot', 100);
                // The Beam shares Force Lightning's sample, and has to share its
                // sustain machinery too: at a 15ms cooldown it fires nearly every frame.
                else if (wk === 'lightning' || wk === 'beam') pulseForceLightning();
                // The Computer fires a charged bolt, drawn as a zap and heard as
                // one. Its 600ms cooldown clears the 450ms throttle, so every shot
                // lands a sound even at full auto-fire.
                else if (wk === 'zap' || wk === 'computer' || wk === 'realitystaff') playSound('zap', 450);
                // The conventional firearms, all on one sample. The SMG's 92ms
                // cadence is the tightest here and still clears the 70ms throttle,
                // so it rattles rather than dropping every other shot.
                else if (wk === 'lancehead' || wk === 'burstrifle' || wk === 'assaultrifle'
                      || wk === 'enhancedar' || wk === 'deadeyear' || wk === 'glock'
                      || wk === 'dualglocks'
                      || wk === 'submachine' || wk === 'warforgedar') playSound('gunshot', 70);
                // Spider-Man, and the only weapon in the game that picks its sample
                // at random. Two shooters, two samples, one coin flip per pull — the
                // 190ms trigger is fast enough that a single repeated sample reads
                // as a stuck loop, and alternating breaks that up.
                //
                // The throttle is per SAMPLE NAME (see playSound), so two names means
                // two independent clocks and a coin flip can land two sounds inside
                // one throttle window. At a 190ms cadence that is the exception
                // rather than the rule, and when it happens it is a double-tap of
                // webbing rather than a glitch — which is the point of the mechanic.
                else if (wk === 'webshooter') {
                    playSound(Math.random() < 0.5 ? 'webshooter1' : 'webshooter2', 60);
                }
                // Iron Man's release. Lives here rather than beside the charge
                // release in the player block so an AI Iron Man is heard firing too —
                // the draw is player-only (one element, one draw) but the shot is not.
                else if (wk === 'repulsor') playSound('repulsorShoot', 80);
                // Hawkeye's loose, and it sounds for an AI archer too — which
                // matters more here than anywhere else, because the AI is the only
                // thing on the roster that draws a bow at you.
                else if (wk === 'bow') playSound('arrowShoot', 80);
                else if (wk === 'focusshotgun') playSound('gunshot', 110);
                // Heavier and slower than the rifles that share this sample, so it
                // gets more room between repeats.
                else if (wk === 'excaliber') playSound('gunshot', 200);
                // Sabers only. Blunt weapons are silent in the air — thrown or
                // swung — so a thrown vibroblade makes its one noise on landing.
                else if (weaponConfig.returnable && isEnergyBlade(wk)) {
                    playSound(bladeThrowSfx(wk), 300);
                }
            }

            /** Cancel countdown / delayed SFX / game loop and hide the match timer.
             *  Call whenever leaving a fight (end screen → menu, pause quit, new setup). */
            function stopBattleSystems() {
                battleSession++; // invalidate any pending timeouts bound to the old session
                countdownActive = false;
                if (countdownTimerId != null) {
                    clearTimeout(countdownTimerId);
                    countdownTimerId = null;
                }
                if (saberHumTimerId != null) {
                    clearTimeout(saberHumTimerId);
                    saberHumTimerId = null;
                }
                // The fight is over, so there is no blade left to resume humming.
                // Deliberately cleared here and not in stopAllSfx(), which the pause
                // menu also calls and which must not forget the current match.
                activeSaberHumKey = null;
                if (gameLoopId) {
                    cancelAnimationFrame(gameLoopId);
                    gameLoopId = 0;
                }
                lastGameFrameTime = 0;
                stopAllSfx();
                const hudTimer = document.getElementById('hudTimer');
                if (hudTimer) {
                    hudTimer.style.display = 'none';
                    hudTimer.classList.remove('sudden-death');
                }
                // The combo counter is only ever cleared by updateComboCounter(), which
                // runs from the game loop — once the loop stops it would hang on screen
                // over the end-of-match screen and the menu until its stale auto-hide
                // timeout happened to fire. Tear it down with the rest of the battle.
                comboKills = [];
                clearTimeout(window.comboTimeout);
                const comboEl = document.getElementById('comboCounter');
                if (comboEl) comboEl.classList.remove('active');
                // The loop that would normally restore the cursor and release the
                // trigger has just been cancelled, so do both here — otherwise the
                // cursor stays hidden over the end screen and a click held through
                // the last kill carries into the next round.
                mouseFire = false;
                updateAimCursor();
            }
            
            let musicStarted = false;
            let currentMusic = null;
            function playMenuMusic() {
                if (currentMusic === menuMusic) return;
                stopCurrentMusic();
                currentMusic = menuMusic;
                if (musicStarted) {
                    menuMusic.play().catch(() => {});
                }
            }
            
            function playBattleMusic() {
                // The Halloween event plays its own track over everything, the
                // Marvel switch included: the player chose the event, which is a
                // stronger ask than a preference set some other day. Every round
                // of a run calls this (setupGame does), and the early return keeps
                // the song running through the result screen between rounds
                // instead of restarting it; leaving the event goes through
                // showMainMenu, whose playMenuMusic() puts the lobby track back.
                if (halloweenRun) {
                    if (currentMusic === halloweenBattleMusic) return;
                    stopCurrentMusic();
                    currentMusic = halloweenBattleMusic;
                    if (musicStarted) halloweenBattleMusic.play().catch(() => {});
                    return;
                }

                // Season override: takes priority over all arena-specific music.
                // A season ships a single battle track, so updateMusicSources() has
                // already pointed battleMusic at it and there is nothing to pick —
                // the per-series track rotation the old layer needed is gone.
                //
                // The Marvel battle track wins over the arena-specific music the
                // same way the old one did — Mustafar and the Death Star included.
                // Turning the switch off gives those back.
                if (marvelSoundtrackEnabled) {
                    if (currentMusic === battleMusic) return;
                    stopCurrentMusic();
                    currentMusic = battleMusic;
                    if (musicStarted) {
                        battleMusic.play().catch(() => {});
                    }
                    return;
                }

                // Arena-specific overrides (only when the season soundtrack is disabled)
                if (currentArena === 'mustafar') {
                    if (currentMusic === mustafar_music) return;
                    stopCurrentMusic();
                    currentMusic = mustafar_music;
                    if (musicStarted) mustafar_music.play().catch(() => {});
                    return;
                }
                if (currentArena === 'deathstar') {
                    if (currentMusic === deathstar_music) return;
                    stopCurrentMusic();
                    currentMusic = deathstar_music;
                    if (musicStarted) deathstar_music.play().catch(() => {});
                    return;
                }
                if (currentArena === 'moseisley') {
                    if (currentMusic === cantinaBandAudio) return;
                    stopCurrentMusic();
                    currentMusic = cantinaBandAudio;
                    if (musicStarted) {
                        cantinaBandAudio.play().catch(() => {});
                    }
                    return;
                }
                
                // Default battle music
                if (currentMusic === battleMusic) return;
                stopCurrentMusic();
                currentMusic = battleMusic;
                if (musicStarted) {
                    battleMusic.play().catch(() => {});
                }
            }
            
            function stopCurrentMusic() {
                if (currentMusic) {
                    currentMusic.pause();
                    currentMusic.currentTime = 0;
                }
            }
            
            /*  AUTOPLAY. The music tries to start the moment the page opens. Chrome
             *  allows that on sites you already play media on a lot (that is why
             *  YouTube can), and refuses it everywhere else until the player has
             *  clicked, tapped or pressed a key. So the load attempt is backed by
             *  listeners on the first input of any kind, anywhere on the page.
             *
             *  The listeners stay until a play() actually succeeds. They used to
             *  be { once: true } and set musicStarted up front, so a first input
             *  the browser does not count as a gesture (Escape, a bare Shift) used
             *  them up and left the game silent for the rest of the session.     */
            const MUSIC_START_EVENTS = ['pointerdown', 'click', 'keydown', 'touchend'];
            function stopListeningForMusicStart() {
                MUSIC_START_EVENTS.forEach(ev => document.removeEventListener(ev, tryStartMusic, true));
            }
            function tryStartMusic() {
                if (musicStarted) return;
                // Whatever screen we are on decides the track; at boot that is
                // the splash, which uses the menu music.
                if (!currentMusic) currentMusic = menuMusic;
                const track = currentMusic;
                musicStarted = true;
                let attempt;
                try { attempt = track.play(); } catch (e) { attempt = Promise.reject(e); }
                Promise.resolve(attempt).then(() => {
                    stopListeningForMusicStart();
                }, () => {
                    // Blocked. Only stand down if the screen has not changed
                    // track in the meantime, then wait for the next input.
                    if (currentMusic === track) musicStarted = false;
                });
            }
            MUSIC_START_EVENTS.forEach(ev => document.addEventListener(ev, tryStartMusic, true));
            tryStartMusic();

            const settingsBtn = document.getElementById('settingsBtn');
            const settingsPanel = document.getElementById('settingsPanel');
            const marvelToggleBtn = document.getElementById('marvelToggleBtn');
            const redeemCodeInput = document.getElementById('redeemCodeInput');
            const redeemCodeBtn = document.getElementById('redeemCodeBtn');

            // ── VOLUME SLIDERS ──────────────────────────────────────────
            const musicVolumeSlider = document.getElementById('musicVolumeSlider');
            const sfxVolumeSlider   = document.getElementById('sfxVolumeSlider');

            // Sync sliders to loaded values
            if (musicVolumeSlider) musicVolumeSlider.value = musicVolume;
            if (sfxVolumeSlider) sfxVolumeSlider.value = sfxVolume;

            if (musicVolumeSlider) {
                musicVolumeSlider.addEventListener('input', (e) => {
                    e.stopPropagation();
                    tryStartMusic();
                    musicVolume = parseFloat(e.target.value);
                    applyMusicVolume();
                    saveGameSettings();
                });
            }

            if (sfxVolumeSlider) {
                sfxVolumeSlider.addEventListener('input', (e) => {
                    e.stopPropagation();
                    sfxVolume = parseFloat(e.target.value);
                    applySfxVolume();
                    if (sfxVolume === 0) silenceAllSfx();
                    saveGameSettings();
                });
            }

            // ── GRAPHICS PRESET + REDUCED MOTION ───────────────────────
            document.querySelectorAll('.perf-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const mode = btn.dataset.perf;
                    if (mode !== 'low' && mode !== 'balanced' && mode !== 'high') return;
                    performanceMode = mode;
                    perfUserOverride = true;
                    applyPerformanceMode();
                    saveGameSettings();
                    showAnnouncement(
                        mode === 'low' ? 'Graphics set to Low — fewer particles & effects.' :
                        mode === 'balanced' ? 'Graphics set to Balanced.' :
                        'Graphics set to High — full visual effects.',
                        '#00cfff', 2500, '🖥️ GRAPHICS'
                    );
                });
            });
            applyPerformanceMode(); // sync button highlight after DOM is ready

            const autoAimBtn = document.getElementById('autoAimBtn');
            if (autoAimBtn) {
                autoAimBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    autoAimEnabled = !autoAimEnabled;
                    applyAutoAimSetting();
                    saveGameSettings();
                    // Touch players are always auto-aimed regardless of this switch,
                    // so say that plainly rather than let the toggle look broken.
                    const touchOnly = aimSource === 'none' && isCoarsePointer();
                    showAnnouncement(
                        autoAimEnabled
                            ? 'Auto-aim on. Your shots track the nearest enemy — just focus on moving.'
                            : (touchOnly
                                ? 'Auto-aim off. Touch controls still aim for you — connect a mouse or controller to aim yourself.'
                                : 'Auto-aim off. Point with the mouse (or the right stick) to aim your shots.'),
                        '#ffd700', 3200, '🎯 AIMING'
                    );
                });
            }

            const reducedMotionBtn = document.getElementById('reducedMotionBtn');
            if (reducedMotionBtn) {
                reducedMotionBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    reducedMotion = !reducedMotion;
                    applyReducedMotion();
                    saveGameSettings();
                    showAnnouncement(
                        reducedMotion ? 'Reduced motion enabled. Screen shake, kill-cam & heavy FX off.' : 'Reduced motion disabled.',
                        '#8ae1ff', 2800, '♿ ACCESSIBILITY'
                    );
                });
            }

            function isSettingsOpen() {
                return !!settingsPanel && settingsPanel.style.display === 'flex';
            }

            function setSettingsOpen(open) {
                if (!settingsPanel) return;
                // Flex, not block: the panel is a column so only its scroll list scrolls.
                settingsPanel.style.display = open ? 'flex' : 'none';
                if (settingsBtn) settingsBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
            }

            if (settingsBtn) {
                settingsBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const isOpen = isSettingsOpen();
                    setSettingsOpen(!isOpen);
                });
            }

            document.addEventListener('click', (e) => {
                if (isSettingsOpen()) {
                    if (settingsBtn && (e.target === settingsBtn || settingsBtn.contains(e.target))) return;
                    if (settingsPanel.contains(e.target)) return;
                    setSettingsOpen(false);
                }
            });

            // Escape closes settings when not in battle pause (pause handler also uses Escape)
            document.addEventListener('keydown', (e) => {
                if (e.key !== 'Escape') return;
                if (isSettingsOpen()) {
                    // Don't steal Escape from an open confirm dialog
                    const confirmEl = document.getElementById('confirmOverlay');
                    if (confirmEl && confirmEl.style.display === 'flex') return;
                    // Marked handled so the window-level Escape (which steps back a
                    // screen from fighter select) does not also act on this press.
                    e.preventDefault();
                    setSettingsOpen(false);
                }
            });

            if (marvelToggleBtn) {
                marvelToggleBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleMarvelSoundtrack();
                });
            }

            /*  ── SEASON CARD ──────────────────────────────────────────────────
             *  Raised by snap-intro.js's `done` cue and by nothing else. The cue only
             *  fires at the tail of a sequence that actually played, so this is once
             *  per Snap rather than once per load — a save that has already seen
             *  the intro settles straight to the end state and never emits it.
             *
             *  Listening for the event rather than being called by the intro keeps the
             *  boundary that file already draws: it announces what it did, and what
             *  that means for the menu is decided here.
             *
             *  Closing is only ever through the two soundtrack buttons — no Escape,
             *  no backdrop click, no close box. There is one question on the card and
             *  both answers are on it, and a card that could be dismissed without
             *  answering would leave the preference at whatever it happened to be
             *  while implying it had been chosen.                                  */
            const seasonCardOverlay = document.getElementById('seasonCardOverlay');

            /*  VAULTED: THE SEASON CARD. The Snap now ends on the menu and nothing
             *  else: no card, no soundtrack question. The Snap only plays when it is
             *  asked for (the THANOS code), and a player who typed a code to watch
             *  a cutscene does not want a form at the end of it. The soundtrack is
             *  still chosen in Settings, which is where it always lived; the card
             *  only ever asked the same question in a second place.
             *
             *  Flip to false to bring it back. The markup, the styles, both buttons
             *  and the snapintro:done listener below are all still in place.     */
            const SEASON_CARD_VAULTED = true;

            function openSeasonCard() {
                if (SEASON_CARD_VAULTED) return;
                if (!seasonCardOverlay) return;
                seasonCardOverlay.style.display = 'flex';
                // Focus an exit as soon as the layer is up so the keyboard and the pad
                // both start on a real target rather than on nothing: getNavigables()
                // reads this overlay the moment it becomes the active layer.
                const first = document.getElementById('seasonCardStarWarsBtn');
                if (first) {
                    try { first.focus({ preventScroll: true }); } catch (e) { first.focus(); }
                }
            }

            function closeSeasonCard(marvel) {
                setMarvelSoundtrack(marvel, false);
                if (seasonCardOverlay) seasonCardOverlay.style.display = 'none';
            }

            const seasonCardStarWarsBtn = document.getElementById('seasonCardStarWarsBtn');
            if (seasonCardStarWarsBtn) {
                seasonCardStarWarsBtn.addEventListener('click', () => closeSeasonCard(false));
            }
            const seasonCardMarvelBtn = document.getElementById('seasonCardMarvelBtn');
            if (seasonCardMarvelBtn) {
                seasonCardMarvelBtn.addEventListener('click', () => closeSeasonCard(true));
            }

            document.addEventListener('snapintro:done', openSeasonCard);

            const aurebeshToggleBtn = document.getElementById('aurebeshToggleBtn');
            if (aurebeshToggleBtn) {
                aurebeshToggleBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    if (!aurebeshUnlocked) return;
                    toggleAurebeshMode();
                });
            }

            const clearDataBtn = document.getElementById('clearDataBtn');
            if (clearDataBtn) {
                clearDataBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    showConfirm('Are you sure you want to clear all data? This will reset achievements, unlocks, and settings.', {
                        title: 'CLEAR ALL DATA',
                        icon: '🗑️',
                        okLabel: 'Clear Data',
                        danger: true
                    }).then(confirmed => {
                        if (confirmed) {
                            // Only this game's own keys. itch.io serves every HTML
                            // game from one shared origin, so localStorage.clear()
                            // also wiped the saves of every other game the player
                            // had run there.
                            try {
                                Object.keys(localStorage)
                                    .filter(k => k.startsWith('galacticDuel') || k === 'gl-snap-intro')
                                    .forEach(k => localStorage.removeItem(k));
                            } catch (err) {}
                            location.reload();
                        }
                    });
                });
            }

            // ── SAVE FILE DOWNLOAD / LOAD ───────────────────────────────
            // All of this game's persisted state lives in localStorage under keys
            // prefixed 'galacticDuel' (unlocks, achievements, settings, history,
            // favorites, etc). Bundle those into one JSON file the player can save
            // externally and restore later, e.g. to move progress to another browser.
            //
            // Each individual key's value is itself wrapped in a { _v, data }
            // schema envelope (see loadVersioned/saveVersioned above), so a save
            // file exported from an older build still loads correctly here — any
            // out-of-date keys get migrated up to CURRENT_SCHEMA_VERSION the next
            // time they're read via loadVersioned, whether that happens right after
            // this import or on a later page load.
            function collectSaveData() {
                const data = {};
                for (let i = 0; i < localStorage.length; i++) {
                    const key = localStorage.key(i);
                    if (key && key.startsWith('galacticDuel')) {
                        data[key] = localStorage.getItem(key);
                    }
                }
                return data;
            }

            function buildSaveExportPayload() {
                const saveData = collectSaveData();
                const keys = Object.keys(saveData);
                // Lightweight integrity fingerprint (length + key count) — not crypto, just catches truncations
                let byteLen = 0;
                keys.forEach(k => { byteLen += (saveData[k] || '').length; });
                return {
                    game: 'galacticDuel',
                    version: 2,
                    schemaVersion: CURRENT_SCHEMA_VERSION,
                    savedAt: new Date().toISOString(),
                    keyCount: keys.length,
                    byteLength: byteLen,
                    performanceMode,
                    reducedMotion,
                    data: saveData
                };
            }

            const downloadSaveBtn = document.getElementById('downloadSaveBtn');
            if (downloadSaveBtn) {
                downloadSaveBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    try {
                        const payload = JSON.stringify(buildSaveExportPayload(), null, 2);
                        const blob = new Blob([payload], { type: 'application/json' });
                        const url = URL.createObjectURL(blob);
                        const a = document.createElement('a');
                        a.href = url;
                        const datestamp = new Date().toISOString().slice(0, 10);
                        a.download = `galactic-legends-save-${datestamp}.json`;
                        document.body.appendChild(a);
                        a.click();
                        a.remove();
                        setTimeout(() => URL.revokeObjectURL(url), 1000);
                        showAnnouncement('Save file downloaded.', '#44ff44', 3000, '💾 SAVE DOWNLOADED');
                    } catch (err) {
                        showAnnouncement('Could not create the save file.', '#ff6666', 3000, '❌ SAVE FAILED');
                    }
                });
            }

            const loadSaveBtn = document.getElementById('loadSaveBtn');
            const loadSaveFileInput = document.getElementById('loadSaveFileInput');
            if (loadSaveBtn && loadSaveFileInput) {
                loadSaveBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    loadSaveFileInput.value = '';
                    loadSaveFileInput.click();
                });
                loadSaveFileInput.addEventListener('change', (e) => {
                    const file = e.target.files && e.target.files[0];
                    if (!file) return;
                    const reader = new FileReader();
                    reader.onload = () => {
                        let parsed;
                        try {
                            parsed = JSON.parse(reader.result);
                        } catch (err) {
                            showAnnouncement('That file isn\'t a valid save file.', '#ff6666', 3500, '❌ LOAD FAILED');
                            return;
                        }
                        // Accept v1/v2 export envelopes or a raw key map
                        const incoming = parsed && parsed.data && typeof parsed.data === 'object'
                            ? parsed.data
                            : (parsed && typeof parsed === 'object' && Object.keys(parsed).some(k => k.startsWith('galacticDuel')) ? parsed : null);
                        if (!incoming || typeof incoming !== 'object') {
                            showAnnouncement('That file isn\'t a valid save file.', '#ff6666', 3500, '❌ LOAD FAILED');
                            return;
                        }
                        // Only this game's keys, each holding a string that parses,
                        // which is what every value in an export is. Anything else is
                        // left out here rather than written into storage to fail later.
                        const incomingKeys = Object.keys(incoming).filter(k => {
                            if (!k.startsWith('galacticDuel') || typeof incoming[k] !== 'string') return false;
                            try { JSON.parse(incoming[k]); return true; } catch (err) { return false; }
                        });
                        if (incomingKeys.length === 0) {
                            showAnnouncement('Save file contains no Galactic Legends data.', '#ff6666', 3500, '❌ LOAD FAILED');
                            return;
                        }
                        // Soft integrity check for v2 exports
                        if (typeof parsed.keyCount === 'number' && parsed.keyCount !== incomingKeys.length) {
                            showAnnouncement('Save file may be incomplete (key count mismatch).', '#ffaa00', 3500, '⚠️ SAVE WARNING');
                        }
                        const savedAtLabel = parsed.savedAt ? ` (exported ${String(parsed.savedAt).slice(0, 10)})` : '';
                        showConfirm(`Load this save file${savedAtLabel}? This will overwrite your current progress, unlocks, and settings.`, {
                            title: 'LOAD SAVE FILE',
                            icon: '📂',
                            okLabel: 'Load Save',
                            danger: true
                        }).then(confirmed => {
                            if (!confirmed) return;
                            // The current save is copied aside first and put back if
                            // the write fails part-way (a full storage quota, most
                            // likely). This used to delete first and write second, so
                            // a write that failed left the player with no save at all.
                            const ownKeys = () => Object.keys(localStorage).filter(k => k.startsWith('galacticDuel'));
                            const backup = {};
                            try {
                                ownKeys().forEach(k => { backup[k] = localStorage.getItem(k); });
                            } catch (err) {
                                showAnnouncement('Could not load that save file.', '#ff6666', 3500, '❌ LOAD FAILED');
                                return;
                            }
                            try {
                                ownKeys().forEach(k => localStorage.removeItem(k));
                                incomingKeys.forEach(k => localStorage.setItem(k, incoming[k]));
                            } catch (err) {
                                try {
                                    ownKeys().forEach(k => localStorage.removeItem(k));
                                    Object.keys(backup).forEach(k => localStorage.setItem(k, backup[k]));
                                } catch (restoreErr) {}
                                showAnnouncement('Could not load that save file. Your progress was kept.', '#ff6666', 3500, '❌ LOAD FAILED');
                                return;
                            }
                            location.reload();
                        });
                    };
                    reader.onerror = () => {
                        showAnnouncement('Could not read that file.', '#ff6666', 3500, '❌ LOAD FAILED');
                    };
                    reader.readAsText(file);
                });
            }

            /** Swaps the soundtrack, and does nothing else. It used to also mark
             *  the pack owned and rebuild the rosters and the shop, because
             *  flipping this was one of the two ways to acquire the pack. That content
             *  is unconditional now, so this is purely an audio preference and
             *  touching the rosters from here would be rebuilding them for nothing. */
            /** The one place the soundtrack preference changes. Settings' toggle and
             *  the season card both come through here, so "switch soundtrack" has a
             *  single definition: sources, save, button label, and restarting
             *  whatever is mid-track.
             *
             *  Guarded on an actual change rather than run unconditionally. The card
             *  offers Star Wars as a real choice and Star Wars is already the
             *  default, so the common answer sets the value it already had — and
             *  without this guard that confirmation would yank the lobby track back
             *  to zero for no reason the player could hear a cause for. The Settings
             *  toggle always flips, so nothing about it changes.
             *
             *  `announce` is off for the card: it has just asked the question in full
             *  sentences and does not need a banner repeating the answer back. */
            function setMarvelSoundtrack(on, announce = true) {
                const changed = marvelSoundtrackEnabled !== !!on;
                marvelSoundtrackEnabled = !!on;
                updateMusicSources();
                saveGameSettings();
                updateMarvelMusicButton();
                // Restart whatever is playing so the swap is heard immediately
                // rather than at the end of the current track.
                if (changed && musicStarted && currentMusic) {
                    currentMusic.pause();
                    currentMusic.currentTime = 0;
                    currentMusic.play().catch(() => {});
                }
                if (announce) {
                    showAnnouncement('Marvel Soundtrack ' + (marvelSoundtrackEnabled ? 'Enabled' : 'Disabled') + '.', '#e23636', 3000, '🎵 MARVEL');
                }
            }

            function toggleMarvelSoundtrack() {
                setMarvelSoundtrack(!marvelSoundtrackEnabled);
            }

            if (redeemCodeBtn) {
                redeemCodeBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const code = redeemCodeInput.value.trim().toUpperCase();
                    // BUILDIT used to be redeemable here for a lobby-only Build It
                    // track. That switch is gone: the only way to hear Build It now
                    // is to clear the Zero Event, which makes it the menu half of the
                    // season soundtrack. The code is no longer recognised.
                    if (code === 'AUREBESH') {
                        aurebeshUnlocked = true;
                        aurebeshEnabled = true;
                        applyAurebeshMode();
                        saveGameSettings();
                        updateAurebeshToggleVisibility();
                        showAnnouncement('Aurebesh activated! Use the Aurebesh toggle in settings.', '#8ae1ff', 4000, '🔓 UNLOCKED');
                    } else if (code === 'ZERO') {
                        /*  What is left of the code now the Zero Event is gone: it
                         *  hands over the fighter and nothing else. Zero was always
                         *  granted before the run began — "he is on the roster
                         *  whichever way the run goes" — so with no run to open, the
                         *  grant is the whole of it.                                */
                        const hadZero = !!gameUnlocks.zeroUnit;
                        gameUnlocks.zeroUnit = true;
                        persistGalacticUnlocks();
                        rebuildAllRosters();
                        updateSecretFactionSectionVisibility();
                        setSettingsOpen(false);
                        showAnnouncement(hadZero
                            ? 'The Zero Point is already open to you.'
                            : 'Something walked out of the Zero Point. Zero has joined your roster.',
                            '#a274ff', 4500, '⬢ ZERO', 100);
                    } else if (code === 'THANOS') {
                        /*  VAULTED: THE SNAP INTRO. The way back in now that the Snap
                         *  no longer plays by itself. Works every time it is entered,
                         *  not once per save: it changes nothing the Snap has not
                         *  already changed, so watching it again costs nothing. */
                        setSettingsOpen(false);
                        if (!replaySnapIntro()) {
                            showAnnouncement('The Snap is not loaded in this build.', '#ff6666', 3000, '❌ INVALID CODE');
                        }
                    } else if (code) {
                        showAnnouncement(`Code "${code}" is not recognized.`, '#ff6666', 3000, '❌ INVALID CODE');
                    }
                    redeemCodeInput.value = '';
                });
            }

            if (redeemCodeInput) {
                redeemCodeInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        if (redeemCodeBtn) redeemCodeBtn.click();
                    }
                });
            }

            // ── TESTER CODE ENTRY ──────────────────────────────────────
            // A vetted tester enters the code they were sent over Discord (see
            // DEV_TESTER_CODES above); a match unlocks the dev menu on this
            // browser, even on itch.io. The element ids still say itch from when
            // this box took an itch.io username.
            const itchVerifyInput = document.getElementById('itchVerifyInput');
            const itchVerifyBtn = document.getElementById('itchVerifyBtn');
            const itchVerifyStatus = document.getElementById('itchVerifyStatus');

            function updateItchVerifyStatus() {
                if (!itchVerifyStatus) return;
                if (isDevMenuVerifiedUser()) {
                    itchVerifyStatus.textContent = 'Tester code accepted — dev menu unlocked.';
                    itchVerifyStatus.style.display = 'block';
                    itchVerifyStatus.style.color = '#8affc1';
                } else {
                    itchVerifyStatus.style.display = 'none';
                    itchVerifyStatus.textContent = '';
                }
            }

            if (itchVerifyBtn) {
                itchVerifyBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const code = normalizeDevCode(itchVerifyInput.value);
                    if (!code || itchVerifyBtn.disabled) return;
                    itchVerifyInput.value = '';
                    // The check takes a moment (that is the point of the rounds), so
                    // the button sits out a second press until it answers.
                    itchVerifyBtn.disabled = true;
                    isValidDevCode(code).then(ok => {
                        itchVerifyBtn.disabled = false;
                        if (ok) {
                            devAccessCode = code;
                            devCodeVerified = true;
                            saveGameSettings();
                            refreshDevMenuVisibility();
                            updateItchVerifyStatus();
                            showAnnouncement('Tester code accepted. Dev menu unlocked.', '#8affc1', 4000, '🔓 VERIFIED');
                        } else {
                            showAnnouncement("That code isn't valid. Enter the exact code you were sent on Discord.", '#ff6666', 4000, '❌ NOT VERIFIED');
                        }
                    });
                });
            }

            if (itchVerifyInput) {
                itchVerifyInput.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        if (itchVerifyBtn) itchVerifyBtn.click();
                    }
                });
            }

            updateItchVerifyStatus();

            // ── FULLSCREEN ─────────────────────────────────────────────
            const fullscreenBtn = document.getElementById('fullscreenBtn');
            // iOS Safari (and other browsers without any Fullscreen API) can't
            // honor requestFullscreen — the button would silently no-op there,
            // so just hide it for the whole session.
            const fullscreenSupported = !!(
                document.documentElement.requestFullscreen ||
                document.documentElement.webkitRequestFullscreen ||
                document.documentElement.mozRequestFullScreen ||
                document.documentElement.msRequestFullscreen
            );
            if (fullscreenBtn) {
                if (!fullscreenSupported) {
                    fullscreenBtn.style.display = 'none';
                }
                function updateFullscreenIcon() {
                    if (!fullscreenBtn) return;
                    fullscreenBtn.textContent = document.fullscreenElement ? '✕' : '⛶';
                    fullscreenBtn.title = document.fullscreenElement ? 'Exit Fullscreen' : 'Fullscreen';
                    fullscreenBtn.setAttribute('aria-label', fullscreenBtn.title);
                }
                fullscreenBtn.addEventListener('click', () => {
                    if (!document.fullscreenElement) {
                        (document.documentElement.requestFullscreen || document.documentElement.webkitRequestFullscreen || (() => {})).call(document.documentElement);
                    } else {
                        (document.exitFullscreen || document.webkitExitFullscreen || (() => {})).call(document);
                    }
                });
                document.addEventListener('fullscreenchange', updateFullscreenIcon);
                document.addEventListener('webkitfullscreenchange', updateFullscreenIcon);
            }

            // ── CONTROLS OVERLAY ───────────────────────────────────────
            const controlsOverlay  = document.getElementById('controlsOverlay');
            const controlsGrid     = document.getElementById('controlsGrid');
            const controlsInputLabel = document.getElementById('controlsInputLabel');
            const controlsCloseBtn = document.getElementById('controlsCloseBtn');
            const controlsBtn      = document.getElementById('controlsBtn');
            // Coach-mode nodes. All three sit in the markup permanently and start
            // hidden; nothing but coach mode reveals them, so Settings ▸ Controls
            // is unchanged.
            const controlsTitle       = document.querySelector('.controls-box h2');
            const controlsSecondaryBtn = document.getElementById('controlsSecondaryBtn');
            const controlsSuppressRow  = document.getElementById('controlsSuppressRow');
            const controlsSuppress     = document.getElementById('controlsSuppress');
            const controlsResetBtn     = document.getElementById('controlsResetBtn');

            // Built on every open rather than once, because the key in each row is
            // whatever the player has bound it to. A row with an `action` is one
            // the player can rebind; see buildControlsGrid().
            function kbControls() {
                const b = boundKeyLabel;
                return [
                    { note: 'Click a key to change it. The arrow keys always move as well.', rebindOnly: true },
                    { key: b('up'),    action: 'up',    wide: false, desc: 'Move up' },
                    { key: b('left'),  action: 'left',  wide: false, desc: 'Move left' },
                    { key: b('down'),  action: 'down',  wide: false, desc: 'Move down' },
                    { key: b('right'), action: 'right', wide: false, desc: 'Move right' },
                    { key: 'Mouse',     wide: true,  desc: 'Aim — you fire toward the crosshair' },
                    { key: `${b('fire')} / LMB`, action: 'fire', wide: true, desc: 'Shoot — melee weapons swing. A swing commits: it locks to the direction you started it in, and slows you until it finishes' },
                    { key: `${b('fire')} / LMB`, wide: true, desc: 'DEFLECT — swing a lightsaber, darksaber or electrostaff as a shot arrives and the blade knocks it back at whoever fired it' },
                    { key: `${b('throw')} / RMB`, action: 'throw', wide: true, desc: 'Throw your blade (melee) — or fire your blaster (droids with a sidearm), or raise skeletons as a Halloween general or lord, once a round' },
                    { key: b('dodge'),  action: 'dodge',  wide: true,  desc: 'Dodge — you are invulnerable for the first part of the roll, not all of it. Also cancels a swing you have committed to' },
                    { key: b('reload'), action: 'reload', wide: false, desc: 'Reload' },
                    { key: b('interact'), action: 'interact', wide: true, desc: 'Interact — Force Choke as Vader; press again mid-choke to snap a neck at 50% HP or below. Switches weapons as Deadpool. As a Halloween fighter, hold it to keep your shield up' },
                    { key: 'Esc',       wide: false, desc: 'Pause' },
                    { key: 'Enter',     wide: false, desc: 'Confirm' },
                ];
            }

            const TOUCH_CONTROLS = [
                { key: 'Joystick',  wide: true,  desc: 'Move' },
                { key: '🔫',        wide: true,  desc: 'Shoot / Attack — aims for you automatically. A swing commits: it locks to the direction you started it in, and slows you until it finishes' },
                { key: '🔫',        wide: true,  desc: 'DEFLECT — swing a lightsaber, darksaber or electrostaff as a shot arrives and the blade knocks it back at whoever fired it' },
                { key: '🌀 / 🔫',   wide: true,  desc: 'Throw your blade (melee) — or fire your blaster (droids with a sidearm), or raise skeletons as a Halloween general or lord, once a round' },
                { key: '💨',        wide: true,  desc: 'Dodge — you are invulnerable for the first part of the roll, not all of it. Also cancels a swing you have committed to' },
                { key: '🔄',        wide: false, desc: 'Reload — appears for magazine weapons' },
                { key: '✋ / 💀',   wide: true,  desc: 'Interact — Force Choke as Vader; tap again mid-choke to snap a neck at 50% HP or below. Switches weapons as Deadpool. As a Halloween fighter, hold it to keep your shield up' },
                { key: '⏸',        wide: false, desc: 'Pause' },
            ];

            const GAMEPAD_CONTROLS = [
                { header: 'In battle' },
                { key: 'Left Stick / D-Pad', wide: true,  desc: 'Move' },
                { key: 'Right Stick', wide: true,  desc: 'Aim — you fire toward the crosshair' },
                { key: 'A / RT',      wide: true,  desc: 'Shoot — melee weapons swing. A swing commits: it locks to the direction you started it in, and slows you until it finishes' },
                { key: 'A / RT',      wide: true,  desc: 'DEFLECT — swing a lightsaber, darksaber or electrostaff as a shot arrives and the blade knocks it back at whoever fired it' },
                { key: 'LT',          wide: true,  desc: 'Throw your blade (melee) — or fire your blaster (droids with a sidearm), or raise skeletons as a Halloween general or lord, once a round' },
                { key: 'B / LB / RB', wide: true,  desc: 'Dodge — you are invulnerable for the first part of the roll, not all of it. Also cancels a swing you have committed to' },
                { key: 'X',           wide: false, desc: 'Reload' },
                { key: 'Y',           wide: true,  desc: 'Interact — Force Choke as Vader; press again mid-choke to snap a neck at 50% HP or below. Switches weapons as Deadpool. As a Halloween fighter, hold it to keep your shield up' },
                { key: 'Start',       wide: false, desc: 'Pause / Resume' },
                { header: 'In menus' },
                { key: 'Left Stick / D-Pad', wide: true,  desc: 'Move selection' },
                { key: 'A',           wide: false, desc: 'Select' },
                { key: 'B',           wide: false, desc: 'Back / Close' },
                { key: 'X',           wide: false, desc: 'Favourite a character' },
                { key: 'LB / RB',     wide: false, desc: 'Jump through long lists' },
                { key: 'Left / Right',wide: false, desc: 'Adjust a slider' },
            ];

            // A first-fight cut of the control lists: the six bindings a player needs
            // in their first match, plus the one thing a bindings list cannot say. The
            // descriptions are deliberately shortened — the deflect and choke rows are
            // not first-fight material and stay in the full overlay. A { note } entry
            // is a full-width line of prose; see buildControlsGrid().
            const FIRST_FIGHT_CONTROLS = {
                // A getter so the card shows the player's own bindings, the same
                // reason kbControls() is a function.
                get keyboard() { return [
                    { key: ['up', 'left', 'down', 'right'].map(boundKeyLabel).join(' '), wide: true, desc: 'Move' },
                    { key: 'Mouse',       wide: true,  desc: 'Aim — you fire toward the crosshair' },
                    { key: `${boundKeyLabel('fire')} / LMB`, wide: true, desc: 'Shoot — melee weapons swing' },
                    { key: boundKeyLabel('dodge'), wide: true, desc: 'Dodge — invulnerable for the first part of the roll' },
                    { key: boundKeyLabel('reload'), wide: false, desc: 'Reload' },
                    { key: 'Esc',         wide: false, desc: 'Pause' },
                    { header: 'How a match works' },
                    { note: 'Win three rounds to take the series — three minutes on the clock each round. Series wins pay credits; spend them in the Shop, the Armory, or on a fighter of your own.' }
                ]; },
                touch: [
                    { key: 'Joystick', wide: true,  desc: 'Move' },
                    { key: '🔫',       wide: true,  desc: 'Shoot / Attack — aims for you automatically' },
                    { key: '💨',       wide: true,  desc: 'Dodge — invulnerable for the first part of the roll' },
                    { key: '🔄',       wide: false, desc: 'Reload — appears for magazine weapons' },
                    { key: '⏸',       wide: false, desc: 'Pause' },
                    { header: 'How a match works' },
                    { note: 'Win three rounds to take the series — three minutes on the clock each round. Series wins pay credits; spend them in the Shop, the Armory, or on a fighter of your own.' }
                ],
                gamepad: [
                    { key: 'Left Stick / D-Pad', wide: true,  desc: 'Move' },
                    { key: 'Right Stick',        wide: true,  desc: 'Aim — you fire toward the crosshair' },
                    { key: 'A / RT',             wide: true,  desc: 'Shoot — melee weapons swing' },
                    { key: 'B / LB / RB',        wide: true,  desc: 'Dodge — invulnerable for the first part of the roll' },
                    { key: 'X',                  wide: false, desc: 'Reload' },
                    { key: 'Start',              wide: false, desc: 'Pause / Resume' },
                    { header: 'How a match works' },
                    { note: 'Win three rounds to take the series — three minutes on the clock each round. Series wins pay credits; spend them in the Shop, the Armory, or on a fighter of your own.' }
                ]
            };

            // The full list for a given input type, so coach mode's "All controls"
            // and openControlsOverlay() cannot drift apart.
            function fullControlsFor(type) {
                return type === 'gamepad' ? GAMEPAD_CONTROLS
                     : type === 'touch'   ? TOUCH_CONTROLS
                     : kbControls();
            }

            // Rows with an `action` become buttons only in the full keyboard list
            // (never the coach card, never touch or gamepad). Set by
            // buildControlsGrid's caller through the second argument.
            let controlsRebindable = false;

            function buildControlsGrid(list, rebindable = false) {
                cancelRebind();
                controlsRebindable = rebindable;
                controlsResetBtn.hidden = !rebindable;
                controlsGrid.innerHTML = '';
                list.forEach(({ key, wide, desc, header, note, action, rebindOnly }) => {
                    if (rebindOnly && !rebindable) return;
                    const row = document.createElement('div');
                    // A { header } entry is a section divider, not a binding — the
                    // gamepad list covers two contexts and needs to separate them.
                    if (header) {
                        row.className = 'control-section';
                        row.textContent = header;
                        controlsGrid.appendChild(row);
                        return;
                    }
                    // A { note } entry is a full-width line of prose, for the one
                    // thing a two-column key/description grid cannot express.
                    if (note) {
                        row.className = 'control-note';
                        row.textContent = note;
                        controlsGrid.appendChild(row);
                        return;
                    }
                    row.className = 'control-row';
                    if (rebindable && action) {
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = `control-key control-rebind${wide ? ' wide' : ''}`;
                        btn.textContent = key;
                        btn.title = 'Click, then press the key you want';
                        btn.addEventListener('click', () => startRebind(action, btn));
                        const d = document.createElement('span');
                        d.className = 'control-desc';
                        d.textContent = desc;
                        row.append(btn, d);
                    } else {
                        row.innerHTML = `<span class="control-key${wide ? ' wide' : ''}">${escapeHtmlText(key)}</span><span class="control-desc">${desc}</span>`;
                    }
                    controlsGrid.appendChild(row);
                });
            }

            /*  ── REBINDING ──────────────────────────────────────────────────
             *  Click a key chip, press a key. The capture listener sits on window
             *  in the capture phase, so it sees the press before the game's own
             *  keydown handler, the overlay's Escape handler and the pause toggle,
             *  and stops it there: the key being bound never also fires, and Esc
             *  cancels the capture instead of closing the overlay.
             *
             *  A key already bound to another action SWAPS with it rather than
             *  being refused or leaving that action unbound, so every action
             *  always has exactly one key.                                       */
            let rebindAction = null;
            let rebindBtn = null;
            function startRebind(action, btn) {
                cancelRebind();
                rebindAction = action;
                rebindBtn = btn;
                btn.classList.add('is-listening');
                btn.textContent = 'Press a key…';
            }
            function cancelRebind() {
                if (rebindBtn) {
                    rebindBtn.classList.remove('is-listening');
                    rebindBtn.textContent = boundKeyLabel(rebindAction);
                }
                rebindAction = null;
                rebindBtn = null;
            }
            function rebuildKeyboardControls() {
                buildControlsGrid(kbControls(), true);
            }
            window.addEventListener('keydown', (e) => {
                if (!rebindAction) return;
                e.preventDefault();
                e.stopImmediatePropagation();
                const k = normalizeKey(e);
                if (!k || k === 'Escape') { cancelRebind(); return; }
                if (RESERVED_KEYS.has(k)) {
                    rebindBtn.textContent = `${keyLabel(k)} is taken`;
                    return;
                }
                const other = Object.keys(keyBindings).find(a => a !== rebindAction && keyBindings[a] === k);
                if (other) keyBindings[other] = keyBindings[rebindAction];
                keyBindings[rebindAction] = k;
                rebindAction = null;
                rebindBtn = null;
                saveGameSettings();
                resetKeyboardInput();
                rebuildKeyboardControls();
            }, true);

            // A pad plugged in alongside a keyboard shouldn't hijack the overlay, so
            // whichever was touched most recently wins.
            function detectInputType() {
                if (readGamepad() && padLastUsedAt > lastKeyboardUseAt) return 'gamepad';
                const isTouchOnly = window.matchMedia('(pointer: coarse)').matches && !window.matchMedia('(pointer: fine)').matches;
                if (isTouchOnly) return 'touch';
                return 'keyboard';
            }

            // Set while the overlay is up in coach mode: the fight is waiting on the
            // player closing it, and every route out of the overlay (button, scrim,
            // Escape, gamepad B) runs through closeControlsOverlay().
            let coachOnDismiss = null;

            function openControlsOverlay(opts = {}) {
                const coach = !!opts.coach;
                const type = detectInputType();
                controlsInputLabel.textContent = type === 'gamepad' ? 'Gamepad'
                    : type === 'touch' ? 'Touchscreen'
                    : 'Keyboard';
                buildControlsGrid(coach ? FIRST_FIGHT_CONTROLS[type] : fullControlsFor(type),
                                  !coach && type === 'keyboard');

                controlsTitle.textContent = coach ? 'YOUR FIRST FIGHT' : 'CONTROLS';
                controlsCloseBtn.textContent = coach ? 'Fight ▶' : 'Close';
                controlsCloseBtn.classList.toggle('is-primary', coach);
                controlsSecondaryBtn.hidden = !coach;
                controlsSuppressRow.hidden = !coach;
                if (coach) controlsSuppress.checked = false;
                // Only a coach open touches the continuation. A plain open must not
                // clear one that is pending: the fight behind the card is waiting on
                // it, and dropping it would leave the countdown never started.
                if (coach) coachOnDismiss = opts.onDismiss || null;

                if (typeof setSettingsOpen === 'function') setSettingsOpen(false);
                else if (settingsPanel) settingsPanel.style.display = 'none';
                controlsOverlay.classList.add('open');
            }

            function closeControlsOverlay() {
                cancelRebind();
                controlsOverlay.classList.remove('open');
                // Cleared before the callback runs, so a handler that reopens the
                // overlay is not immediately re-armed with a stale continuation.
                const done = coachOnDismiss;
                coachOnDismiss = null;
                // Coach mode only. The flag is normally written the moment the card
                // is raised, so the checkbox is a promise the game has already kept —
                // this keeps it true regardless of which of the two writes lands first.
                if (done && controlsSuppress.checked && !seenFirstFightCard) {
                    seenFirstFightCard = true;
                    saveGameSettings();
                }
                if (done) done();
            }

            controlsBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                openControlsOverlay();
            });
            controlsCloseBtn.addEventListener('click', closeControlsOverlay);
            // "All controls" swaps the coach cut for the full list in place. The
            // fight is still waiting, so coachOnDismiss is deliberately untouched
            // and the primary button stays "Fight ▶".
            controlsResetBtn.addEventListener('click', () => {
                keyBindings = { ...DEFAULT_KEY_BINDINGS };
                saveGameSettings();
                resetKeyboardInput();
                rebuildKeyboardControls();
            });
            controlsSecondaryBtn.addEventListener('click', () => {
                buildControlsGrid(fullControlsFor(detectInputType()));
                controlsTitle.textContent = 'CONTROLS';
                controlsSecondaryBtn.hidden = true;
            });
            controlsOverlay.addEventListener('click', (e) => {
                if (e.target === controlsOverlay) closeControlsOverlay();
            });
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && controlsOverlay.classList.contains('open')) {
                    // Stops the bubble at document, one hop short of the window
                    // keydown handler that toggles pause. Without this, dismissing
                    // the coach card with Escape would start the fight and open the
                    // pause menu on the same keypress.
                    e.preventDefault();
                    e.stopPropagation();
                    closeControlsOverlay();
                }
            });

            // ── MATCH HISTORY OVERLAY ──────────────────────────────────
            const historyTableBody = document.getElementById('historyTableBody');
            const historyEmpty     = document.getElementById('historyEmpty');
            const historyTable     = document.getElementById('historyTable');
            const historyCount     = document.getElementById('historyCount');
            const MAX_HISTORY_ENTRIES = 100;

            /*  Renders into the nodes parked in #historyHome. The Dossier's History
             *  tab borrows those nodes while it is open and hands them back on close,
             *  so this fills whichever parent they happen to be sitting in. The old
             *  Settings ▸ Match History overlay is gone; the Dossier is the only way
             *  in, and #historyHome is now just where the table lives between visits. */
            function renderHistoryTable() {
                try {
                    const history = loadVersioned('galacticDuelHistory', []);
                    historyTableBody.innerHTML = '';
                    if (history.length === 0) {
                        historyEmpty.style.display = 'block';
                        historyTable.style.display = 'none';
                        if (historyCount) historyCount.textContent = '';
                    } else {
                        historyEmpty.style.display = 'none';
                        historyTable.style.display = 'table';
                        const fragment = document.createDocumentFragment();
                        history.forEach((m, i) => {
                            if (!m || typeof m !== 'object') return;
                            const tr = document.createElement('tr');
                            tr.style.borderBottom = '1px solid rgba(255,255,255,0.05)';
                            tr.style.background = (i % 2 === 1) ? 'rgba(255,255,255,0.025)' : 'transparent';
                            const win = m.result === 'W';
                            const resultColor = win ? '#00A4FF' : '#FF3333';
                            const dmg  = typeof m.damage   === 'number' ? m.damage   : '—';
                            const acc  = typeof m.accuracy === 'number' ? m.accuracy + '%' : '—';
                            tr.innerHTML = `
                                <td style="padding:6px 8px;color:rgba(255,255,255,0.45);">${escapeHtmlText(m.date||'—')}</td>
                                <td style="padding:6px 8px;color:#e8e8e8;max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtmlText(m.player)}</td>
                                <td style="padding:6px 8px;color:rgba(255,255,255,0.5);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtmlText(m.enemy)}</td>
                                <td style="padding:6px 8px;text-align:center;color:${resultColor};font-weight:bold;">${win ? '✓ WIN' : '✗ LOSS'}</td>
                                <td style="padding:6px 8px;text-align:center;color:#e8e8e8;">${dmg}</td>
                                <td style="padding:6px 8px;text-align:center;color:#e8e8e8;">${acc}</td>
                                <td style="padding:6px 8px;text-align:center;color:rgba(255,255,255,0.4);text-transform:capitalize;">${escapeHtmlText(m.difficulty||'—')}</td>
                            `;
                            fragment.appendChild(tr);
                        });
                        historyTableBody.appendChild(fragment);
                        if (historyCount) {
                            historyCount.textContent = history.length >= MAX_HISTORY_ENTRIES
                                ? `Showing most recent ${MAX_HISTORY_ENTRIES} matches (older matches are trimmed)`
                                : `${history.length} match${history.length === 1 ? '' : 'es'} recorded`;
                        }
                    }
                } catch(e) {}
            }

            const historyClearBtn = document.getElementById('historyClearBtn');
            if (historyClearBtn) {
                historyClearBtn.addEventListener('click', () => {
                    showConfirm('Clear all match history?', {
                        title: 'CLEAR HISTORY',
                        icon: '🗑️',
                        okLabel: 'Clear',
                        danger: true
                    }).then(confirmed => {
                        if (confirmed) {
                            localStorage.removeItem('galacticDuelHistory');
                            // Re-render in place rather than reopening: the table may
                            // be parented in the Dossier right now, not this overlay.
                            renderHistoryTable();
                            refreshSplashState();   // the record chip counted those
                        }
                    });
                });
            }
            // Achievements
            const achievementsList = document.getElementById('achievementsList');

            /*  Same arrangement as renderHistoryTable(): #achievementsList lives in
             *  #achievementsHome and is borrowed by the Dossier's Achievements tab.
             *  Settings no longer has an entry for it.                             */
            function renderAchievementsList() {
                achievementsList.innerHTML = '';
                const achievementIds = Object.keys(achievements).sort();
                let unlockedCount = 0;
                // The win-streak rows used to read playerWins, which is this series'
                // round count and never more than 3, so "On Fire" could not show
                // past 3/5. The real streak is the run of W at the top of the match
                // history — the same count endGame unlocks them from.
                let historyStreak = 0;
                try {
                    for (const h of loadVersioned('galacticDuelHistory', [])) {
                        if (h && h.result === 'W') historyStreak++; else break;
                    }
                } catch (e) {}

                achievementIds.forEach(id => {
                    const a = achievements[id];
                    // 'My POI get ROI' is won as Cluster on Cluster Coast and the vault
                    // has taken both, so it goes with them whether or not it was
                    // earned. achievements.poiRoi.done is untouched in the save — unvault
                    // and it reappears, still ticked for anyone who had it.
                    if (a.done) unlockedCount++;

                    // Get progress for achievements with counters
                    let progressText = a.done ? 'UNLOCKED' : 'LOCKED';
                    let progressPercent = a.done ? 100 : 0;
                    
                    if (!a.done) {
                        switch(id) {
                            case 'saberMaster':
                                progressText = `${Math.min(saberWinCount, 3)}/3`;
                                progressPercent = (saberWinCount / 3) * 100;
                                break;
                            case 'winStreak3':
                                progressText = `${Math.min(historyStreak, 3)}/3`;
                                progressPercent = (historyStreak / 3) * 100;
                                break;
                            case 'winStreak5':
                                progressText = `${Math.min(historyStreak, 5)}/5`;
                                progressPercent = (historyStreak / 5) * 100;
                                break;
                            case 'winStreak10':
                                progressText = `${Math.min(historyStreak, 10)}/10`;
                                progressPercent = (historyStreak / 10) * 100;
                                break;
                            case 'blasterMaster':
                                progressText = `${Math.min(blasterWinCount, 5)}/5`;
                                progressPercent = (blasterWinCount / 5) * 100;
                                break;
                            case 'saberMaster2':
                                progressText = `${Math.min(saberWinCount2, 5)}/5`;
                                progressPercent = (saberWinCount2 / 5) * 100;
                                break;
                            case 'spaceSpecialist':
                                progressText = `${Math.min(spaceWinCount, 5)}/5`;
                                progressPercent = (spaceWinCount / 5) * 100;
                                break;
                            case 'arenaExplorer':
                                progressText = `${arenasWonIn.size}/5`;
                                progressPercent = (arenasWonIn.size / 5) * 100;
                                break;
                            case 'villainSlayer':
                                progressText = `${villainsDefeated.size}/5`;
                                progressPercent = (villainsDefeated.size / 5) * 100;
                                break;
                            case 'millenniumRun':
                                progressText = `${Math.min(hanWinCount, 3)}/3`;
                                progressPercent = (hanWinCount / 3) * 100;
                                break;
                            case 'vaderConquest':
                                progressText = `${Math.min(vaderConsecutiveWins, 10)}/10`;
                                progressPercent = (vaderConsecutiveWins / 10) * 100;
                                break;
                            case 'jediHunter':
                                progressText = `${Math.min(villainWinCount, 10)}/10`;
                                progressPercent = (villainWinCount / 10) * 100;
                                break;
                        }
                    }

                    const item = document.createElement('div');
                    item.className = `achievement-item ${a.done ? 'unlocked' : ''}`;
                    item.innerHTML = `
                        <div class="achievement-icon">${a.done ? '🏆' : '🔒'}</div>
                        <div class="achievement-info">
                            <div class="achievement-name">${a.label}</div>
                            <div class="achievement-desc">${a.desc}</div>
                        </div>
                        <div class="achievement-status">${progressText}</div>
                    `;
                    achievementsList.appendChild(item);
                });
            }

            // ── THE DOSSIER ────────────────────────────────────────────────
            /*  Four tabs over one body. Contracts and Mastery are rendered here;
             *  Achievements and History are not re-implemented — the Dossier borrows
             *  the real nodes those two screens already own and hands them back on
             *  the way out, so there is exactly one renderer for each and the two
             *  entry points cannot drift apart.                                    */
            const dossierOverlay = document.getElementById('dossierOverlay');
            const dossierBody    = document.getElementById('dossierBody');
            const dossierTabs    = document.getElementById('dossierTabs');
            let dossierTab = 'contracts';

            // Where each borrowed node came from, so it always goes back to the
            // right parent and the right position among its siblings.
            const borrowedNodes = [];
            function borrowInto(host, ...els) {
                els.forEach(el => {
                    if (!el) return;
                    borrowedNodes.push({ el, parent: el.parentNode, next: el.nextSibling });
                    host.appendChild(el);
                });
            }
            function returnBorrowedNodes() {
                while (borrowedNodes.length) {
                    const { el, parent, next } = borrowedNodes.pop();
                    if (parent) parent.insertBefore(el, next);
                }
            }

            function dossierSection(label, hint) {
                const d = document.createElement('div');
                d.className = 'creator-section-label';
                d.textContent = label;
                if (hint) {
                    const h = document.createElement('span');
                    h.className = 'creator-hint';
                    h.textContent = ' ' + hint;
                    d.appendChild(h);
                }
                return d;
            }

            /** How long is left on today's set, in the same words the design uses. */
            function contractResetHint() {
                const now = new Date();
                const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1);
                const mins = Math.max(0, Math.round((midnight - now) / 60000));
                const h = Math.floor(mins / 60);
                return h > 0 ? `resets in ${h}h ${mins % 60}m` : `resets in ${mins}m`;
            }

            function dossierEmpty(text) {
                const el = document.createElement('div');
                el.className = 'dossier-empty';
                el.textContent = text;
                return el;
            }

            /*  Two kinds of contract, split by cadence rather than by kind. The
             *  daily three reroll at local midnight; a Scavenger Mandalorian
             *  contract is a standing bounty that is posted once and never resets,
             *  which is why it is listed apart from work that expires tonight.
             *
             *  Nothing is posted to the standing board yet. To add one: define it
             *  in CONTRACT_POOL as usual, hold its { progress, claimed } somewhere
             *  that is not keyed by day — contractState.list is wiped by
             *  rollContractsIfNewDay() — and render it with the same row loop
             *  below, which is already cadence-agnostic.                          */
            function renderContracts(host) {
                /*  Stark's board first: it is the one with no clock on it, so it is
                 *  the one a player can always act on. Built from the same row parts
                 *  as the dailies below rather than a second style, so the screen
                 *  reads as one board with two sources.                            */
                host.appendChild(dossierSection('Iron Man', ironManMarkHint()));
                if (!starkContract) {
                    host.appendChild(dossierEmpty('The Mk 85 is standing. There is nothing left to build.'));
                } else {
                    const def = starkDef(starkContract.id);
                    const ready = starkReady();
                    const row = document.createElement('div');
                    row.className = 'achievement-item' + (ready ? ' is-ready' : '');

                    const icon = document.createElement('div');
                    icon.className = 'achievement-icon';
                    icon.textContent = ready ? '✅' : def.icon;

                    const info = document.createElement('div');
                    info.className = 'achievement-info';
                    const name = document.createElement('div');
                    name.className = 'achievement-name';
                    name.textContent = def.label;
                    const desc = document.createElement('div');
                    desc.className = 'achievement-desc';
                    desc.textContent = ready
                        ? 'Ready · claim to fit the Mk ' + (ironManMark() + 1)
                        : `${starkContract.progress.toLocaleString()} of ${starkContract.target.toLocaleString()}`;
                    info.appendChild(name);
                    info.appendChild(desc);
                    if (!ready) {
                        const bar = document.createElement('div');
                        bar.className = 'contract-bar';
                        const fill = document.createElement('div');
                        fill.style.width = Math.min(100, (starkContract.progress / starkContract.target) * 100) + '%';
                        bar.appendChild(fill);
                        info.appendChild(bar);
                    }

                    row.appendChild(icon);
                    row.appendChild(info);
                    if (ready) {
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = 'contract-claim';
                        btn.textContent = 'FIT MK ' + (ironManMark() + 1);
                        btn.addEventListener('click', claimStarkContract);
                        row.appendChild(btn);
                    } else {
                        // The pay is the mark, not credits, so the badge says so.
                        const reward = document.createElement('div');
                        reward.className = 'contract-reward';
                        reward.textContent = 'MK ' + (ironManMark() + 1);
                        row.appendChild(reward);
                    }
                    host.appendChild(row);
                }

                /*  Groot's board, built from the same row parts as Stark's above and
                 *  the dailies below. Second on the screen rather than first because
                 *  Stark's is the older of the two and the ordering is the order they
                 *  were added, which is also roughly how long each takes to finish. */
                host.appendChild(dossierSection('Groot', grootLevelHint()));
                if (!grootContract) {
                    host.appendChild(dossierEmpty('The axe is in his hands. There is nothing left to grow.'));
                } else {
                    const gdef = grootDef(grootContract.id);
                    const gready = grootReady();
                    const grow = document.createElement('div');
                    grow.className = 'achievement-item' + (gready ? ' is-ready' : '');

                    const gicon = document.createElement('div');
                    gicon.className = 'achievement-icon';
                    gicon.textContent = gready ? '✅' : gdef.icon;

                    const ginfo = document.createElement('div');
                    ginfo.className = 'achievement-info';
                    const gname = document.createElement('div');
                    gname.className = 'achievement-name';
                    gname.textContent = gdef.label;
                    const gdesc = document.createElement('div');
                    gdesc.className = 'achievement-desc';
                    gdesc.textContent = gready
                        ? 'Ready · claim to grow to level ' + (grootLevel() + 1)
                        : `${grootContract.progress.toLocaleString()} of ${grootContract.target.toLocaleString()}`;
                    ginfo.appendChild(gname);
                    ginfo.appendChild(gdesc);
                    if (!gready) {
                        const gbar = document.createElement('div');
                        gbar.className = 'contract-bar';
                        const gfill = document.createElement('div');
                        gfill.style.width = Math.min(100, (grootContract.progress / grootContract.target) * 100) + '%';
                        gbar.appendChild(gfill);
                        ginfo.appendChild(gbar);
                    }

                    grow.appendChild(gicon);
                    grow.appendChild(ginfo);
                    if (gready) {
                        const gbtn = document.createElement('button');
                        gbtn.type = 'button';
                        gbtn.className = 'contract-claim';
                        // The last claim is the axe, so it says so rather than "LV 5".
                        gbtn.textContent = (grootLevel() + 1) >= GROOT_MAX_LEVEL
                            ? 'TAKE THE AXE' : 'GROW TO LV ' + (grootLevel() + 1);
                        gbtn.addEventListener('click', claimGrootContract);
                        grow.appendChild(gbtn);
                    } else {
                        // The pay is the level, not credits, so the badge says so.
                        const greward = document.createElement('div');
                        greward.className = 'contract-reward';
                        greward.textContent = (grootLevel() + 1) >= GROOT_MAX_LEVEL
                            ? '🪓 AXE' : 'LV ' + (grootLevel() + 1);
                        grow.appendChild(greward);
                    }
                    host.appendChild(grow);
                }

                host.appendChild(dossierSection('Daily', contractResetHint()));
                if (!contractState.list.length) {
                    host.appendChild(dossierEmpty('No contracts today.'));
                }
                contractState.list.forEach(c => {
                    const def = contractById(c.id);
                    if (!def) return;
                    const ready = !c.claimed && c.progress >= c.target;
                    const row = document.createElement('div');
                    row.className = 'achievement-item' + (ready ? ' is-ready' : '') + (c.claimed ? ' is-claimed' : '');

                    const icon = document.createElement('div');
                    icon.className = 'achievement-icon';
                    icon.textContent = c.claimed ? '✅' : ready ? '✅' : def.icon;

                    const info = document.createElement('div');
                    info.className = 'achievement-info';
                    const name = document.createElement('div');
                    name.className = 'achievement-name';
                    name.textContent = def.label;
                    const desc = document.createElement('div');
                    desc.className = 'achievement-desc';
                    desc.textContent = c.claimed ? 'Claimed'
                        : ready ? 'Ready · claim to collect'
                        : `${c.progress.toLocaleString()} of ${c.target.toLocaleString()}`;
                    info.appendChild(name);
                    info.appendChild(desc);
                    // A finished contract shows the claim button instead of a full
                    // bar — the bar has nothing left to say at that point.
                    if (!ready && !c.claimed) {
                        const bar = document.createElement('div');
                        bar.className = 'contract-bar';
                        const fill = document.createElement('div');
                        fill.style.width = Math.min(100, (c.progress / c.target) * 100) + '%';
                        bar.appendChild(fill);
                        info.appendChild(bar);
                    }

                    row.appendChild(icon);
                    row.appendChild(info);
                    if (ready) {
                        const btn = document.createElement('button');
                        btn.type = 'button';
                        btn.className = 'contract-claim';
                        btn.textContent = `CLAIM +${c.reward}`;
                        btn.addEventListener('click', () => claimContract(c.id));
                        row.appendChild(btn);
                    } else {
                        const reward = document.createElement('div');
                        reward.className = 'contract-reward';
                        reward.textContent = `+${c.reward}`;
                        row.appendChild(reward);
                    }
                    host.appendChild(row);
                });

                host.appendChild(dossierSection('Scavenger Mandalorian', 'a standing bounty — it does not reset'));
                host.appendChild(dossierEmpty('Nothing posted yet.'));
            }

            function renderMastery(host) {
                host.appendChild(dossierSection('Mastery', 'your three most-played'));

                const top = Object.keys(matchStats.fighters)
                    .map(id => ({ id, s: matchStats.fighters[id] }))
                    .filter(e => e.s.fights > 0)
                    .sort((a, b) => b.s.fights - a.s.fights)
                    .slice(0, 3);

                if (!top.length) {
                    host.appendChild(dossierEmpty('No fights recorded yet. Take someone out and they will appear here.'));
                } else {
                    const grid = document.createElement('div');
                    grid.className = 'mastery-grid';
                    top.forEach(({ id, s }) => {
                        const char = findRosterChar(id);
                        const color = (char && char.color) || '#7fe3ff';
                        const m = masteryFor(s.xp);
                        const card = document.createElement('div');
                        card.className = 'mastery-card';
                        card.innerHTML =
                            `<div class="mastery-head">` +
                                `<span class="mastery-portrait" style="color:${color}">${char ? rosterWeaponEmoji(char) : '⚔️'}</span>` +
                                `<span class="mastery-name">${escapeHtmlText((char ? char.name : id).toUpperCase())}</span>` +
                                `<span class="mastery-level" style="color:${color}">LV ${m.level}</span>` +
                            `</div>` +
                            `<div class="mastery-bar"><div style="width:${m.pct.toFixed(0)}%;background:${color}"></div></div>` +
                            `<div class="mastery-next">Next: ${escapeHtmlText(masteryRewardFor(m.level + 1))}</div>`;
                        grid.appendChild(card);
                    });
                    host.appendChild(grid);
                }

                // Said in the tab itself, not just the handoff: a mastery ladder that
                // touched damage or reach would be a power curve, and this is not one.
                host.appendChild(dossierSection('', 'Every mastery reward is cosmetic — a tint, a trail, a colour slot. Nothing here changes damage, health, cooldown or reach. The rewards themselves arrive with the reward system; 3.0 ships the ladder.'));
            }

            function renderDossier() {
                if (!dossierOverlay || dossierOverlay.style.display !== 'flex') return;
                returnBorrowedNodes();
                dossierBody.innerHTML = '';
                [...dossierTabs.querySelectorAll('.dossier-tab')].forEach(b => {
                    b.classList.toggle('active', b.dataset.tab === dossierTab);
                });

                if (dossierTab === 'contracts')      renderContracts(dossierBody);
                else if (dossierTab === 'mastery')   renderMastery(dossierBody);
                else if (dossierTab === 'achievements') {
                    // The real renderer, into the real node — just parented here.
                    renderAchievementsList();
                    borrowInto(dossierBody, achievementsList);
                } else if (dossierTab === 'history') {
                    renderHistoryTable();
                    borrowInto(dossierBody,
                        document.getElementById('historyTableWrap'),
                        document.getElementById('historyCount'),
                        document.getElementById('historyEmpty'),
                        document.getElementById('historyClearBtn'));
                }
            }

            function openDossier() {
                if (typeof setSettingsOpen === 'function') setSettingsOpen(false);
                // Checked on every open as well as at load: a session left running
                // over midnight should find a new set waiting, not yesterday's.
                rollContractsIfNewDay();
                dossierTab = 'contracts';
                updateCreditsDisplay();
                dossierOverlay.style.display = 'flex';
                renderDossier();
                setTimeout(() => focusFirstVisibleButton(dossierOverlay), 0);
            }

            function closeDossier() {
                returnBorrowedNodes();
                dossierBody.innerHTML = '';
                dossierOverlay.style.display = 'none';
                // A claim taken inside the panel changes the tile behind it.
                refreshSplashState();
            }

            const btnDossier = document.getElementById('btnDossier');
            if (btnDossier) btnDossier.addEventListener('click', openDossier);
            document.getElementById('dossierCloseBtn').addEventListener('click', closeDossier);
            dossierOverlay.addEventListener('click', (e) => {
                if (e.target === dossierOverlay) closeDossier();
            });
            dossierTabs.addEventListener('click', (e) => {
                const btn = e.target.closest('.dossier-tab');
                if (!btn) return;
                dossierTab = btn.dataset.tab;
                renderDossier();
            });
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && dossierOverlay.style.display === 'flex') {
                    e.preventDefault();
                    e.stopPropagation();
                    closeDossier();
                }
            });

            const messageText = document.getElementById('messageText');
            const restartButton = document.getElementById('restartButton');
            const hud = document.getElementById('hud');

            const playerHealthBar = document.getElementById('playerHealthBar');
            const enemyHealthBar = document.getElementById('enemyHealthBar');
            const playerLabel = document.getElementById('playerLabel');
            const enemyLabel = document.getElementById('enemyLabel');
            const playerHealthText = document.getElementById('playerHealthText');
            const enemyHealthText = document.getElementById('enemyHealthText');

            /** Motion & tuning values are normalized to this framerate (delta-time scaled in the game loop). */
            const TARGET_FPS = 60;
            const PLAYER_SPEED = 3.5;
            const CHARACTER_SIZE = 18;
            
            // WEAPON LIBRARY
            /*  ── VAULTED: ELEVEN WEAPONS ───────────────────────────────────
             *  `vaulted` on a library entry means the same thing it means on a forge
             *  pattern and on a sprite: out of rotation, not gone. The row keeps every
             *  number it had, so dropping the one word puts the weapon back exactly as
             *  it was — and every lookup still resolves, which is what keeps a save
             *  that already carries one working.
             *
             *  The eleven were the pack's guns and its thrown blade: the Lancehead
             *  Pistol, Burst Rifle, Extending Focus Shotgun, Boom Sniper, Assault
             *  Rifle, Enhanced AR, Deadeye AR, Ex-Caliber Rifle, Submachine Gun,
             *  Warforged AR and Seeker's Sword. Every carrier of every one of them is
             *  out of rotation with the pack itself, so this closes the
             *  last doors that did not go with them: the commission pool and the
             *  fabricator. See isWeaponVaulted().                                  */
            const WEAPON_LIBRARY = {
                blaster:    { key: 'blaster',    label: 'Blaster',        damage: 25, variance: 0.10, speed: 8,   cooldown: 400, spin: false, draw: 'bolt',   color: '#ffffff', length: 18 },
                // `deflects` marks an energy blade that can turn a blaster bolt
                // aside mid-swing — see tryDeflect(). It is deliberately NOT the
                // same thing as `melee`: a wrench and a vibroblade are melee
                // weapons that swing at flesh, but nothing about them stops a
                // bolt, so they do not carry it.
                lightsaber: { key: 'lightsaber', label: 'Lightsaber',     damage: 18, variance: 0.12, speed: 8,   cooldown: 500, spin: true,  draw: 'saber',  color: '#ffffff', length: 42, returnable: true, melee: true, reach: 38, deflects: true },
                wrench:     { key: 'wrench',     label: 'Wrench',         damage: 20, variance: 0.15, speed: 7,   cooldown: 400, spin: true,  draw: 'wrench', color: '#b8bec7', length: 24, vsDroidMultiplier: 2, returnable: true, melee: true, reach: 26 },
                zap:        { key: 'zap',        label: 'Zap',            damage: 12, variance: 0.08, speed: 9,   cooldown: 300, spin: false, draw: 'zap',    color: '#7efcff', length: 24 },
                staff:      { key: 'staff',      label: 'Electrostaff',   damage: 17, variance: 0.12, speed: 7.5, cooldown: 380, spin: true,  draw: 'staff',  color: '#c4ff6a', length: 34, returnable: true, melee: true, reach: 34, deflects: true },
                bowcaster:  { key: 'bowcaster',  label: 'Bowcaster',      damage: 25, variance: 0.10, speed: 9,   cooldown: 650, spin: false, draw: 'bolt',   color: '#33ff33', length: 22, charge: { ms: 1500, damageMult: 3, ring: '#33ff33', ringFull: '#aaffaa' } },
                darksaber:  { key: 'darksaber',  label: 'Darksaber',      damage: 22, variance: 0.12, speed: 8.5, cooldown: 480, spin: true,  draw: 'saber',  color: '#ffffff', length: 38, returnable: true, melee: true, reach: 36, deflects: true },
                lightning:  { key: 'lightning',  label: 'Force Lightning', damage: 22, variance: 0.08, speed: 12,  cooldown: 280, spin: true,  draw: 'zap',    color: '#cc00ff', length: 32 },
                computer:   { key: 'computer',   label: 'Computer',       damage: 47, variance: 0.06, speed: 9,   cooldown: 600, spin: false, draw: 'zap',    color: '#808080', length: 24, charge: { ms: 1500, damageMult: 3, ring: '#808080', ringFull: '#aaaaaa' } },
                guards:     { key: 'guards',     label: 'Guards',         damage: 14, variance: 0.10, speed: 8,   cooldown: 320, spin: false, draw: 'bolt',   color: '#cc3333', length: 16, multishot: 2, multishotArc: 0.15 },
                minigun:    { key: 'minigun',    label: 'Minigun',        damage: 15, variance: 0.08, speed: 10,  cooldown: 100, spin: false, draw: 'bolt',   color: '#ff6600', length: 20 },
                // Ice Blast — one of the Ten Rings, and the one The Mandarin holds
                // the trigger down on. It arrived here as the Ice King's Gauntlets,
                // the Mythic that boss dropped in Chapter 7 Season 2; the boss went
                // out with the Zero Event and the weapon stayed, because The Mandarin
                // carried it too and always did (see the note on content
                // packs). He is now the ONLY carrier, so the label is his rather than
                // the Mythic's: `label` is what the HUD, the character-select stat
                // card and the creator all print, and "Ice Gauntlets" was naming a
                // fighter who is no longer in the game on the one fighter who is.
                //
                // Renamed rather than re-keyed. The key is what sprite-kit.js, the
                // forge and every save on disk resolve against, and none of them care
                // what it is called — so this is a one-field change with nothing
                // downstream. The palm-forward `repulsor` hold stays right for it: a
                // ring throws its blast off the hand the same way a gauntlet does.
                //
                // Pairs with FLAME_BLAST_CONFIG on Interact, which is the second ring
                // and is named the same way — Ice Blast at any range, Flame Blast
                // inside 520px, which is exactly what his bio promises.
                //
                // `freezeMs` is read by applyFreeze() and by nothing else, and it is
                // the only weapon in the game that stops a target rather than hurting
                // one. Damage is low precisely because taking someone's turn away is
                // already the expensive part.
                iceblast:   { key: 'iceblast',   label: 'Ice Blast',      damage: 16, variance: 0.08, speed: 7.5, cooldown: 420, spin: false, draw: 'bolt',   color: '#cfe9f5', length: 24, freezeMs: 900 },
                // Beam: continuous fire, Commander Fox (Elite)'s and the strongest gun in the game.
                // It was cooldown 0, which passes the fire gate on every frame, so its damage was
                // set by the player's monitor rather than by this table: about 900 DPS at 60 Hz and
                // 2,160 at 144 Hz. 15ms pins it near the 60 Hz figure (~940 DPS nominal) on every
                // screen. Not 16: Date.now() frames at 60 Hz land 16 or 17ms apart, and a 16 would
                // drop every other 16ms frame. On a high-refresh screen it fires every second or
                // third frame, so it can come in a little under that, never over it.
                beam:       { key: 'beam',       label: 'Beam',           damage: 15, variance: 0.08, speed: 10,  cooldown: 15,  spin: false, draw: 'bolt',   color: '#ff2200', length: 22 },
                sniper:     { key: 'sniper',     label: 'Sniper Rifle',   damage: 48, variance: 0.04, speed: 16,  cooldown: 950, spin: false, draw: 'bolt',   color: '#88ccff', length: 28 },
                vibroblade: { key: 'vibroblade', label: 'Vibroblade',     damage: 21, variance: 0.12, speed: 8,   cooldown: 420, spin: true,  draw: 'blade',  color: '#c8d4e0', length: 30, returnable: true, melee: true, reach: 30 },
                // The Incinerator Trooper's flame, built to read as a shortened
                // Beam rather than as a stubby cone: it reaches twice as far, the
                // particles travel at nearly Beam speed so the stream keeps up
                // with the trigger instead of lobbing, and the fan is tight enough
                // to look like a jet. maxRange still stops it well inside the
                // arena — the duel opens ~529px apart, so 300 means closing the
                // distance is still the trooper's problem.
                //
                // Damage pays for the reach, and most of what is left has moved
                // off the impact and into the fire. At the original 9 this was
                // 386 sustained DPS, second only to the Beam, and the only thing
                // keeping that honest was having the shortest range in the game.
                //
                // Contact damage is now 3, so the jet itself barely stings —
                // 128 DPS of direct output. The weapon's real damage is the burn
                // it leaves behind (see BURN_TICK_DAMAGE and igniteBurn): 6 every
                // 400ms for 3 seconds, refreshed by each hit, which is 42 more
                // damage that keeps landing after the trigger is released.
                //
                // The flame particle's alpha fades on travelled/maxRange (see the
                // 'flame' draw branch), so the longer range stretches the fade out
                // with it and the jet stays bright along its whole length.
                flamethrower:{ key: 'flamethrower', label: 'Flamethrower', damage: 3,  variance: 0.18, speed: 9.5, cooldown: 70,  spin: false, draw: 'flame',  color: '#ff6622', length: 16, multishot: 3, multishotArc: 0.30, maxRange: 300 },

                // ── MARVEL ────────────────────────────────────────────────────
                // Priced against the roster's own baseline rather than any outside
                // source: a blaster is 25 damage every 400ms (63 dps), a lightsaber
                // lands about 36 a second, and the Minigun tops the table at 150.
                //
                // Repulsors fire in pairs, which is what the multishot is for — two
                // 16s on a 360ms trigger is ~89 dps, above the blaster and well under
                // the Minigun. The arc is deliberately tiny (0.09 rad): they are a
                // matched pair from one suit, not a shotgun.
                // Charged, and the fourth weapon in the game that is — see the
                // chargeShot block. 1050ms is not a balance number, it is the decoded
                // length of Repulsor Chargeup.mp3: a full draw ends on the last frame
                // of the sample, so the whine resolves into the shot instead of being
                // chopped off by it. Re-cut the sample and this number moves with it.
                // (Measured in the browser as `.duration`, not from the file size —
                // the frame-header estimate reads ~1.12s because it counts the tags.)
                //
                // damageMult 3 is the house figure — the Bowcaster, the Computer and
                // the Bow all charge to exactly 3x, and there is no reason for Iron
                // Man to be the one that does not.
                //
                // What that does to him: a tap is still the table row, two bolts at
                // 16, and a full draw is two at 48. Sustained output goes from 89 dps
                // held down to about 86 at a full draw every 1120ms, so he ends up
                // almost exactly where he was — but he now chooses between chipping
                // and committing, and he pays the charge block's 45% movement slug
                // while he commits. The Unibeam on Interact is untouched.
                //
                // No rangeMult. The Repulsors have no maxRange to extend — they fly
                // until they leave the arena — and chargedConfigFor() skips the
                // multiply when maxRange is 0 rather than turning it into a bolt that
                // despawns instantly, so this is stated rather than relied upon.
                repulsor:   { key: 'repulsor',   label: 'Repulsors',      damage: 16, variance: 0.09, speed: 11,  cooldown: 360, spin: false, draw: 'bolt',   color: '#bfefff', length: 20, multishot: 2, multishotArc: 0.09, charge: { ms: 1050, damageMult: 3, ring: '#bfefff', ringFull: '#eaffff' } },
                // Fast and light, and deliberately carrying NO freezeMs. Webbing that
                // held on the primary would be a stunlock: applyFreeze() extends an
                // existing hold rather than replacing it, so a 190ms trigger would
                // chain holds forever. The webbing lives on the grenade instead, where
                // an eight-second cooldown pays for it.
                webshooter: { key: 'webshooter', label: 'Web Shooters',   damage: 11, variance: 0.08, speed: 13,  cooldown: 190, spin: false, draw: 'bolt',   color: '#eef2ff', length: 16 },
                // Melee only, and it takes two flags to say so. No `returnable`
                // means a thrown blade never comes home; `noThrow` means it is
                // never thrown in the first place. Only the second one actually
                // stops the throw — the throw branches gate on `melee` alone, so
                // without it these would fly off and leave Venom empty-handed.
                // They are claws, on the ends of his arms: they do not detach.
                //
                // Venom pays for the reach with the roster's ordinary melee
                // damage and buys it back in health, and now also pays for it by
                // having no answer at all to someone backing off — closing the
                // distance is entirely his problem.
                claws:      { key: 'claws',      label: 'Symbiote Claws', damage: 28, variance: 0.14, speed: 8,   cooldown: 440, spin: true,  draw: 'blade',  color: '#d8d8e2', length: 30, melee: true, reach: 36, noThrow: true },
                // The Hulk's. Shaped exactly like the claws above — melee, never
                // thrown, and with no answer whatsoever to someone backing off — and
                // then made heavy.
                //
                // 82 is not the number the player sees. A swing cannot land further
                // away than `reach`, so every hit is inside applyStatusAndDamage's
                // 100px point-blank band and picks up its x1.4: what floats up is
                // 82 * 1.4 = 115 on average, 101 to 129 across the variance. The
                // table stores the base because that is what every other weapon
                // stores; 115 is what it means.
                //
                // The 900ms cooldown is what pays for that. At Venom's 440 this would
                // be 261 DPS against his 89 — three Venoms, on a fighter who also has
                // the most health in the season. At 900 it is 128: still the hardest
                // melee in the game by some way, but a miss costs most of a second and
                // the swing can be walked out of. Heavy means slow here, the same way
                // it does for the Siege Cannon and both snipers.
                gammafists: { key: 'gammafists', label: 'Gamma Fists', damage: 82, variance: 0.12, speed: 8,   cooldown: 900, spin: true,  draw: 'blade',  color: '#7ddc7d', length: 26, melee: true, reach: 38, noThrow: true },
                // The Thing's, and deliberately the Gamma Fists with a different
                // colour on them — same damage, same 900ms, same reach, same
                // everything. Two fighters who hit identically is the point rather
                // than an oversight: what separates them is the health they carry it
                // on and what their Interact button does, and copying the numbers
                // outright is what makes that comparison clean. If the fists are ever
                // retuned, both entries move together.
                //
                // Its own entry rather than a shared one because the label and the
                // colour are both part of what the player reads — "Fists" in the HUD,
                // orange rock on the knuckles — and neither can vary off a single
                // table row. See characters.secret.thing.
                thingfists: { key: 'thingfists', label: 'Fists', damage: 82, variance: 0.12, speed: 8,   cooldown: 900, spin: true,  draw: 'blade',  color: '#d2762e', length: 26, melee: true, reach: 38, noThrow: true },
                /*  Thanos's. The fists shape again — melee, never thrown, the
                 *  Gamma Fists' reach — tuned a step under Hulk's rather than
                 *  copied from them the way The Thing's are.
                 *
                 *  64 base lands as about 90 after the point-blank x1.4 every
                 *  punch picks up (see gammafists), and 760ms puts that at 118
                 *  sustained against Hulk's 128. Hulk's hands are the whole of
                 *  what he is. Thanos has the Snap, and a fighter who can end
                 *  the round on a coin toss should not also out-punch the Hulk
                 *  in between tosses. The quicker trigger is the glove: a Titan
                 *  who has done this before, not a rage that has to wind up.  */
                gauntletfists: { key: 'gauntletfists', label: 'Infinity Gauntlet', damage: 64, variance: 0.12, speed: 8, cooldown: 760, spin: true, draw: 'blade', color: '#e3b341', length: 26, melee: true, reach: 38, noThrow: true },
                /*  Ant-Man's. Ordinary punches, and the numbers say so: 30 base is
                 *  42 after the point-blank x1.4, and 520ms puts that at about 81 a
                 *  second, a normal fighter's output rather than a brawler's. What
                 *  changes the fight is the size he throws them at (see
                 *  ANT_MAN_FORMS). Giant-Man multiplies the damage and the reach,
                 *  and shrinking scales the reach down with the rest of him.   */
                antmanfists: { key: 'antmanfists', label: 'Fists', damage: 30, variance: 0.12, speed: 8, cooldown: 520, spin: true, draw: 'blade', color: '#c0392b', length: 22, melee: true, reach: 34, noThrow: true },
                /*  The ants'. `fixedDamage` means every hit is exactly this number:
                 *  applyStatusAndDamage sets it after the multipliers, so the
                 *  point-blank x1.4 every melee hit picks up cannot turn a 2 into
                 *  a 3. Reach 14 on a body a third the size means an ant has to
                 *  get right up against you.                                   */
                antbite: { key: 'antbite', label: 'Tiny Fists', damage: 2, variance: 0, speed: 8, cooldown: 500, spin: true, draw: 'blade', color: '#8a2a1f', length: 10, melee: true, reach: 14, noThrow: true, fixedDamage: true },

                // ── WAKANDA ───────────────────────────────────────────────────
                // The Panther's, and it is the Symbiote Claws repurposed: same entry
                // shape, same 'blade' draw, same `melee` + `noThrow` pair, because the
                // reason Venom's do not detach is the reason these do not either —
                // they are claws, on the ends of his hands.
                //
                // What it is NOT is the thingfists trick. That entry copies the Gamma
                // Fists number for number on purpose, because two fighters who punch
                // identically is a controlled comparison and the health is the
                // variable. It cannot be done twice: Venom's 215 is already the most
                // health a claws carrier is allowed, so an identical copy on less
                // health would be Venom with a worse bar and no compensation, and an
                // identical copy on MORE health would simply retire him. Venom has no
                // Interact button to be out-traded with either, so there is nothing
                // else in the design to pay the difference out of.
                //
                // So the claws are re-tuned instead, into the opposite reading of the
                // same hands — the Mjølnir/Lævateinn split applied to a pair of claws.
                // Venom's are the heavy set: 28 a cut every 440ms out to 36. These are
                // the quick set: 24 every 360ms out to 34. 67 base dps against his 64,
                // so sustained output is a wash and every other number is reversed —
                // less per cut, less reach, and the shortest melee trigger in the
                // season by 80ms. Nobody is strictly better, and the two play nothing
                // alike.
                //
                // Vibranium silver-violet rather than the symbiote's bone white. The
                // colour is the only thing on screen that separates one set of claws
                // from the other, so it carries the whole distinction.
                pantherclaws:{ key: 'pantherclaws', label: 'Vibranium Claws', damage: 24, variance: 0.12, speed: 8, cooldown: 360, spin: true, draw: 'blade', color: '#c3b5e8', length: 28, melee: true, reach: 34, noThrow: true },
                // Killmonger's, and the answer to the claws above rather than another
                // set of them. One long blade instead of eight short points: 38 a cut
                // is the hardest single swing in the season outside the two sets of
                // fists, the 620ms trigger is the slowest, and 61 base dps lands it in
                // the same 61-67 band every melee weapon in this season sits in. Same
                // output, biggest pieces, slowest hands.
                //
                // Reach 40 is the longest on the roster — past the Gamma Fists' 38 and
                // the lightsaber's — because it is a full-length sword and the only
                // melee weapon here that is one.
                //
                // `returnable` is the real differentiator, and it is the one thing the
                // Panther cannot have. Every claws and fists entry in this season is
                // `noThrow` and so has no answer at all to an opponent who simply
                // walks away; this is a blade in a hand, so it throws and it comes
                // back, the way Mjølnir and Lævateinn do. That is the whole shape of
                // the Wakanda pair: the hero has the rate and the villain has the
                // reach.
                //
                // No `deflects`. That belongs to the energy blades and the
                // Electrostaff — a bolt does not bounce off worked metal, which is the
                // same line the Vibroblade and the wrench sit on.
                scimitar:   { key: 'scimitar',   label: 'Wakandan Scimitar', damage: 38, variance: 0.12, speed: 8.5, cooldown: 620, spin: true,  draw: 'blade',  color: '#e0b44a', length: 36, returnable: true, melee: true, reach: 40 },

                // ── ASGARD ────────────────────────────────────────────────────
                // Mjolnir is the one weapon in the game `returnable` was already
                // describing before it existed: a melee weapon you throw, that
                // comes back to the hand that sent it. It needs no new mechanic,
                // only the two flags the thrown sabers already use.
                //
                // The heaviest swing on the roster and the slowest — 32 every
                // 520ms is 62 sustained dps, a shade under Venom's claws (64) out
                // of far fewer, far harder hits. That shape is the point: a miss
                // with the hammer costs more than a miss with anything else, and
                // the +40% melee-range bonus means a connected swing inside 100px
                // lands for about 45.
                //
                // It also puts people on the ground — see the 'mjolnir' branch in
                // applyStatusAndDamage(), which shares the Wrench's knockdown and
                // the Wrench's per-target immunity clock so a thrown hammer cannot
                // chain them. What it does NOT share is the anti-droid multiplier:
                // that one is the Wrench being a tool for opening droids, not a
                // hammer being heavy.
                mjolnir:    { key: 'mjolnir',    label: 'Mjølnir',        damage: 32, variance: 0.12, speed: 8.5, cooldown: 520, spin: true,  draw: 'wrench', color: '#b9c4d0', length: 26, returnable: true, melee: true, reach: 32 },
                // Lævateinn, the other way round: light, quick and the shortest
                // trigger of any blade here. 23 every 360ms is 64 dps — the same
                // sustained output as the hammer, arriving in half-sized pieces,
                // which is what a duelist's blade should feel like next to a
                // siege weapon.
                //
                // `returnable` because it is Loki's and nothing he carries stays
                // where you left it. No `deflects`: that belongs to the plasma
                // blades and the Electrostaff, and giving the trickster a parry on
                // top of the shape he is about to steal is one gift too many.
                /*  Laufey’s, and the only melee weapon in the game that stops the
                 *  fighter it hits. A Frost Giant forms it out of his own hand, so it
                 *  is `noThrow` for the reason the claws and the fists are: there is
                 *  no object to let go of.
                 *
                 *  55 sustained, and that is deliberately BELOW the season’s melee
                 *  band of 61-67 — the Vibranium Claws, the Symbiote Claws, the
                 *  Scimitar and Lævateinn all sit inside it. The six points he gives
                 *  up are what the freeze costs, because a hold is worth more than
                 *  the damage it replaces: a frozen fighter is not dodging, not
                 *  swinging and not walking away.
                 *
                 *  Reach 30 is the shortest melee on the roster, under the Panther’s
                 *  34 and well under the Scimitar’s 40. It is a dagger, and a
                 *  fighter who freezes people has to get closer than anyone to do it.
                 *
                 *  700ms at a 30% roll on a 400ms trigger works out to a hold about
                 *  every fourth swing. FREEZE_IMMUNITY_MS then buys the victim 1.4s
                 *  of protection afterwards, so the realistic ceiling is one freeze
                 *  every couple of seconds rather than a permanent stun.          */
                icedagger:  { key: 'icedagger',  label: 'Ice Dagger',     damage: 22, variance: 0.12, speed: 8,   cooldown: 400, spin: true,  draw: 'blade',  color: '#bfe9ff', length: 26, melee: true, reach: 30, noThrow: true, freezeMs: 700, freezeChance: 0.30 },
                laevateinn: { key: 'laevateinn', label: 'Lævateinn',      damage: 23, variance: 0.10, speed: 9,   cooldown: 360, spin: true,  draw: 'blade',  color: '#a8e6b8', length: 30, returnable: true, melee: true, reach: 32 },

                // ── GUARDIANS ─────────────────────────────────────────────────
                // Groot's, at every level below the last one. The damage in this
                // entry is the LEVEL 1 figure and it is the only one written down:
                // applyGrootLevel() overwrites `weaponDamage` on the roster record
                // for levels 2-4, and getWeapon() prefers that over the table (see
                // `charData?.weaponDamage ?? base.damage`). So this row is the floor
                // rather than the weapon — the 14 is what a sapling hits for, and it
                // is GROOT_FIST_MIN_DMG written twice. If that constant moves, this
                // row moves with it.
                //
                // The 'fists' family in sprite-kit.js is what makes these punch
                // rather than swing, and it also keeps a lit beam from being drawn
                // through them. A fists weapon missing from that list renders AND
                // swings as a lightsaber, which is exactly what happened to the
                // Panther's claws — see FAMILY_MEMBERS.
                //
                // 440ms flat at every level on purpose. The upgrade axis is damage
                // and only damage, so the fists feel like the same hands hitting
                // harder rather than a different weapon four times over; at level 4
                // that is 25 a punch on a 440ms trigger, 57 sustained.
                //
                // The trigger was 520 and the reach 34 in the first pass, which made a
                // level 4 Groot strictly worse than Venom in every column — less
                // damage, less reach, slower hands. 440 is the claws' own trigger and
                // 38 is the Gamma Fists' own arms, so what separates him from Venom
                // now is 25 against 28 a hit, bought back with the longest fists on
                // the roster and twenty more health.
                grootfists: { key: 'grootfists', label: 'Branches', damage: 14, variance: 0.14, speed: 8, cooldown: 440, spin: true, draw: 'blade', color: '#8d6b45', length: 24, melee: true, reach: 38, noThrow: true },
                // Level 5, and the whole reason the other four exist. Deliberately
                // shaped as Mjølnir's heavier sibling, because that is what it is —
                // same forge, same mould, and Groot is the one who set the handle on
                // it. 44 every 560ms is 79 sustained against the hammer's 62, and the
                // reach is 40 against its 32 — the longest melee reach in the game,
                // shared with the Wakandan Scimitar, because it is an axe on the end
                // of an arm that is also a tree.
                //
                // Still deliberately under the Gamma Fists, which remain the hardest
                // hands in the game at 128 effective against this axe's 110. Hulk also
                // keeps five more health and an Interact button; this is the second
                // heaviest thing on the roster and is meant to stay second.
                //
                // Simply better than Thor's hammer, and allowed to be: it is the end
                // of a four-contract chain rather than something a fighter starts
                // holding. The gate is the payment, exactly as the Mk 85 is better
                // than the Mk 1. What keeps Thor whole is that he has the hammer
                // immediately, never grinds for it, and carries the God Blast on
                // Interact — Groot has no special at all.
                //
                // `returnable` and no `noThrow`: it is thrown and it comes back, the
                // one behaviour every weapon out of that forge shares. No `deflects`
                // — that belongs to the plasma blades and the Electrostaff, and
                // Mjølnir does not have it either.
                stormbreaker:{ key: 'stormbreaker', label: 'Stormbreaker', damage: 44, variance: 0.12, speed: 8.5, cooldown: 560, spin: true, draw: 'wrench', color: '#cfe6ff', length: 30, returnable: true, melee: true, reach: 40 },
                // Rocket's, and the joke is the proportions: the biggest barrel on
                // the roster carried by the smallest fighter on it. Priced at the
                // blaster's output arriving in fewer, harder, faster shots — 34 every
                // 560ms is 61 dps against the blaster's 63, but each hit is half
                // again as large and travels at 14 rather than 8, so it punishes
                // standing still instead of rewarding volume.
                //
                // No magazine. The magazine idiom belongs to the pack's guns, and
                // hanging one on this would make it a rifle with a reload rather than
                // a cannon. What pays for the damage is the trigger.
                //
                // Not in any sprite-kit family list, and that is correct rather than
                // an omission: familyOf() falls through to 'rifle' for anything
                // ranged it does not recognise, and 'rifle' has no list to be in —
                // the fallback IS the registration for a gun.
                lasercannon:{ key: 'lasercannon', label: 'Laser Cannon', damage: 34, variance: 0.10, speed: 14, cooldown: 560, spin: false, draw: 'bolt', color: '#ff4fa3', length: 26 },
                /*  Star-Lord's, and the only weapon in the game that explodes on its
                 *  own. `explodes` is read in applyStatusAndDamage and routed into
                 *  detonateBoomBoom(), which is the Boom Boom sprite's machinery —
                 *  the whole of this feature is one flag and a pair of numbers,
                 *  because the sprite already had to solve falloff, friendly fire,
                 *  shields, escorts and the stat accounting.
                 *
                 *  WHAT THE BLAST ACTUALLY DOES, stated plainly because it is easy
                 *  to misread: it does NOT re-damage the fighter who was hit. They
                 *  already took the round. It reaches everyone ELSE inside 74px. So
                 *  in a one-on-one duel the explosion is spectacle — the flash, the
                 *  shake, the thump — and in a fight with clone backup, a droid
                 *  squad or Fury's Avengers on the field it is the reason to own
                 *  him. That is the same bargain the sprite makes and it is priced
                 *  as a weapon rather than as a rarity.
                 *
                 *  74px against the sprite's 130, and 0.35 of the hit against its
                 *  0.55, because four rounds leave the barrel per pull. At the
                 *  sprite's numbers one trigger pull was 2.2x the sprite's entire
                 *  output, four screen shakes and fifty-six particles.
                 *
                 *  FOUR BOLTS, which is the name: 20 a round on a 620ms trigger is
                 *  129 dps with all four in, the third hardest sustained output in
                 *  the game behind the Minigun and the Beam — and that is the
                 *  "very powerful" this was asked for. The 0.30 arc is what keeps it
                 *  honest, and it is Black Widow's trick at twice the width: 0.075
                 *  rad between bolts is about 8px at point-blank and about 39px at
                 *  the 520 range cap, so all four land in his face and one lands
                 *  across the arena. He is a brawler holding pistols.
                 *
                 *  maxRange 520 rather than none, so the falloff has an end: past it
                 *  the rounds die rather than crossing the map as single plinks.   */
                quadblaster:{ key: 'quadblaster', label: 'Quad Blasters', damage: 20, variance: 0.10, speed: 12, cooldown: 620, spin: false, draw: 'bolt', color: '#ff8a4a', length: 20, multishot: 4, multishotArc: 0.30, maxRange: 520, explodes: { radius: 74, fraction: 0.35 } },
                // Hawkeye's, and the third weapon in the game you draw back before you
                // let go — see the chargeShot block for the machinery. It is the only
                // one of the three whose charge buys REACH as well as damage, which is
                // the whole character: the shot is not the skill, the draw is.
                //
                // `maxRange` 380 is the number that makes the mechanic matter, because
                // a duel opens about 529px apart. A tapped arrow physically cannot
                // reach the fighter you started the round against — it despawns short —
                // so the opening move is either close the distance or hold the string.
                // At a full 1200ms draw, 2.6x takes it to 988, which is most of the
                // arena and further than anything else here shoots.
                //
                // 17 base and the same 3x the other two charge weapons use, so a full
                // arrow is 51 — a shade over Coulson's 55 in a straight line and the
                // second-largest single hit in the game. The 1200ms is most of the
                // price, and the rest is the 45% movement slug every draw carries:
                // standing still in the open is how a charged shot is paid for.
                //
                // Deliberately no multishot. Every trick arrow the character is known
                // for would be an Interact special, and he has none — the bow is the
                // whole of him, the same way the claws are the whole of Venom.
                bow:        { key: 'bow',        label: 'Bow',            damage: 17, variance: 0.08, speed: 13,  cooldown: 420, spin: false, draw: 'bolt',   color: '#c8a24a', length: 24, maxRange: 380, charge: { ms: 1200, damageMult: 3, rangeMult: 2.6, ring: '#c8a24a', ringFull: '#ffe9a8' }, spentVeer: { turn: 0.012, veerFrames: 22, damageMult: 2 } },

                // ── S.H.I.E.L.D. ──────────────────────────────────────────────
                // The Glock, and the point of it is that it is not special. Every
                // other weapon in this season is a suit, a symbiote, a hammer or a
                // ring; this is a sidearm, carried by the one man on the roster who
                // has no powers at all.
                //
                // `semiAuto` is authenticity rather than balance — a Glock fires one
                // round per pull — but it lands as balance anyway, exactly as it
                // does on the Lancehead: the cooldown becomes a ceiling, not a rate,
                // and the real output is however fast the player can click. The two
                // pistols then read as opposites. The Lancehead is 10 a round every
                // 130ms, a spray you steer. This is 15 every 200ms, a gun you aim:
                // half the ceiling rate for half again the damage, so 75 dps flat
                // out against the Lancehead's 77, arrived at completely differently.
                //
                // The magazine is the Glock 17's seventeen rounds, which is the one
                // number the weapon is actually named for. Seventeen at 200ms is 3.4
                // seconds of fire before a 2s reload — the fastest reload of any
                // magazine weapon here, because a pistol mag change is a pistol mag
                // change.
                //
                // Not modelled, for the same reasons the other guns list: hitscan,
                // headshots, and any falloff with distance.
                glock:      { key: 'glock',      label: 'Glock',           damage: 15, variance: 0.09, speed: 12,  cooldown: 200, spin: false, draw: 'bolt',   color: '#ffdca0', length: 18, magSize: 17, reloadMs: 2000, semiAuto: true },
                // Red Skull's, and the Glock's opposite number on the other side of
                // the war. Same class, same semi-automatic trigger, same "a gun you
                // aim" — the difference is what comes out of it. Hydra's sidearms
                // ran on the Tesseract, so the round is a blue energy bolt rather
                // than lead, and it is heard on Blaster.mp3 rather than the gunshot.
                //
                // Fewer, harder rounds. 20 every 260ms is a 77 dps ceiling against
                // the Glock's 75, so flat out the two are level. The magazine is
                // where it pays: ten rounds to the Glock's seventeen, so ten pulls
                // and a 2s reload works out to about 43 dps sustained against the
                // Glock's 47. It hits harder per click and stops sooner.
                //
                // No disintegration, no freeze, no special: a pistol-class gun
                // balanced as one, the same bargain every other sidearm here makes.
                hydrapistol: { key: 'hydrapistol', label: 'Hydra Pistol', damage: 20, variance: 0.09, speed: 13, cooldown: 260, spin: false, draw: 'bolt', color: '#5ad0ff', length: 20, magSize: 10, reloadMs: 2000, semiAuto: true },
                // Deadpool's, and the first weapon in the game that is half of a
                // loadout rather than the whole of one. He carries the Glock above as
                // well and swaps between the two on Interact — see WEAPON_SWAP_IDS —
                // so these only have to be the close half, not a full kit.
                //
                // 26 every 400ms is 65 base dps, inside the 61-67 band every melee
                // weapon in the season sits in. The two blades are one swing: one
                // hitbox, one damage roll, drawn as a pair (`twinBlade`, read by
                // Character.draw and by sprite-kit's WEAPON_SPECS). Two separate
                // hits per swing would have doubled the number without anyone
                // deciding to.
                //
                // Reach 34, Lævateinn's 32 and the scimitar's 40 either side: a
                // katana is a long blade, but it is held one-handed here, twice.
                //
                // `returnable`, because a thrown sword that stays thrown disarms him
                // in the half of the loadout he chose to be in. No `deflects` — worked
                // steel, the same line the Vibroblade and the scimitar sit on.
                katanas:    { key: 'katanas',    label: 'Dual Katanas',    damage: 26, variance: 0.12, speed: 8.5, cooldown: 400, spin: true,  draw: 'blade',  color: '#d8dee6', length: 32, returnable: true, melee: true, reach: 34, twinBlade: true },

                // ── HALLOWEEN ─────────────────────────────────────────────────
                // Both Skeleton Warriors'. A Vibroblade a step slower and a point
                // lighter (19 every 450ms against 21 every 420ms), because the
                // fighter holding it also carries a shield the Vibroblade's owners
                // never had — and because a Lord can put three of them on the
                // field at once. Steel, so it is in BLUNT_WEAPON_KEYS and in
                // sprite-kit's blade family; thrown and caught like any blade.
                skeletonsword: { key: 'skeletonsword', label: 'Skeleton Sword', damage: 19, variance: 0.12, speed: 8, cooldown: 450, spin: true, draw: 'blade', color: '#d9dde2', length: 30, returnable: true, melee: true, reach: 30 },
                /*  The generals' and the lords', and "it gives off the boom boom
                 *  effect" is meant literally: `explodes` routes every hit through
                 *  detonateBoomBoom(), the Boom Boom sprite's own machinery, the
                 *  same one flag the Quad Blasters use. So the blast does NOT hit
                 *  the fighter it struck a second time; it reaches everyone else
                 *  within 110px — the skeletons around a general, the backup
                 *  around you.
                 *
                 *  One round a pull, so it can afford a blast much nearer the
                 *  sprite's (130px, 0.55) than Star-Lord's four-round 74px. The
                 *  price is the trigger: 30 every 850ms is about 35 dps in a
                 *  straight line, a little over half the Blaster's 63. "Fires
                 *  relatively slowly" is that number. In a duel it is a slow gun;
                 *  in a crowd it is the reason to bring one.
                 *
                 *  A round that lands on a raised shield still goes off — see
                 *  applyStatusAndDamage — so a wall of shields is not safe from
                 *  it, only the fighter holding the one it hit.               */
                halloweenblaster: { key: 'halloweenblaster', label: 'Halloween Blaster', damage: 30, variance: 0.10, speed: 9, cooldown: 850, spin: false, draw: 'bolt', color: '#ff7a1a', length: 22, explodes: { radius: 110, fraction: 0.5 } },
                // Obadiah Stane's, and the mechanic is the Mandarin's rather than a
                // new one: `freezeMs` is read by applyFreeze() and by nothing else, and
                // it is the only thing in the game that stops a fighter instead of
                // hurting one. The Ice Blast holds for 900ms, the Web Grenade for
                // 1500; this holds for 850.
                //
                // 15 every 460ms is 33 sustained, which is the second-lowest of any
                // gun here and entirely deliberate. A weapon that takes someone's turn
                // away does not also get to take their health — and Stane's damage is
                // not supposed to be in his hands anyway, it is in the suit he climbs
                // into when this stops being enough. See IRON_MONGER_IDS.
                //
                // Drawn as a zap rather than a bolt: it is a discharge, not a round.
                sonictaser: { key: 'sonictaser', label: 'Sonic Taser', damage: 15, variance: 0.10, speed: 9, cooldown: 460, spin: false, draw: 'zap', color: '#b8e04a', length: 24, freezeMs: 850 },
                // The Abomination's, and deliberately the Gamma Fists number for
                // number — same 82, same 900ms, same 38 reach. That is the third time
                // this table does that (see thingfists) and it is the same reasoning:
                // three fighters who punch identically is a controlled comparison, and
                // what separates them is the health carrying the fists and what else
                // they can do. Hulk has the smash and The Thing has Clobberin'.
                //
                // This one had the Poison Spit and no longer does — see VAULTED:
                // POISON SPIT. He is the plain set of the three now, and the note at
                // that switch says what that costs and what would fix it.
                //
                // Its own row rather than a shared one because the label and the colour
                // are both read by the player — "Abomination Fists" in the HUD, scaled
                // green on the knuckles — and neither can vary off one table entry.
                abomfists:  { key: 'abomfists',  label: 'Abomination Fists', damage: 82, variance: 0.12, speed: 8, cooldown: 900, spin: true, draw: 'blade', color: '#7fae4a', length: 26, melee: true, reach: 38, noThrow: true },
                // What the Iron Monger swings, and never carried by a roster entry —
                // ironMongerTransform() writes it onto the fighter mid-round, which is
                // the only way anyone ever holds it.
                //
                // 75 every 880ms is 85 sustained before the melee bonus and about 105
                // after it, which puts the suit just under the Gamma Fists (128) and
                // just over the Stormbreaker (110). It is meant to be in that company:
                // it is the back half of a fighter who spends the front half at 175
                // health holding a taser.
                mongerfists: { key: 'mongerfists', label: 'Iron Monger Fists', damage: 75, variance: 0.12, speed: 8, cooldown: 880, spin: true, draw: 'blade', color: '#aab4c0', length: 26, melee: true, reach: 38, noThrow: true },
                // Captain America's, and the only weapon in the game that is defined
                // by what it stops rather than by what it does.
                //
                // `deflects` on a physical object is an exception, and a deliberate
                // one. Every other entry states the rule the other way — the Vibroblade,
                // the Wrench and the Wakandan Scimitar all go without it because a bolt
                // does not bounce off worked metal. This is the single object in the
                // whole roster whose entire reputation is that a bolt DOES bounce off
                // it, so it is the exception that the rule was worth writing down for.
                // See tryDeflect().
                //
                // `returnable` with no `noThrow`, which is the flag pair Mjølnir
                // already described: a melee weapon you throw, that comes back to the
                // hand that sent it. Nothing new was needed for the throw.
                //
                // 26 every 440ms is 59 sustained, which puts it at the bottom of the
                // season's melee band (61-67) — and that is correct, because it is the
                // only one of them that also blocks. The deflect is paid for in damage.
                shield:     { key: 'shield',     label: 'Vibranium Shield', damage: 26, variance: 0.10, speed: 9, cooldown: 440, spin: true, draw: 'wrench', color: '#c8d8e8', length: 26, returnable: true, melee: true, reach: 34, deflects: true },
                // Black Widow's, and the same Glock twice rather than a bigger one.
                // Two rounds leave per pull, one from each hand, which is where every
                // number below comes from.
                //
                // 10 a round against the single Glock's 15, so a pull that lands both
                // is 20 — up on Fury's 15, and well up on his 75 dps if the player can
                // click at the 200ms ceiling. What stops that being a straight upgrade
                // is `multishotArc`: 0.12 is wide for a pair, deliberately. The
                // Repulsors sit at 0.09 because they are a matched pair bolted to one
                // suit; these are two hands, and past mid-range the second round is
                // simply not on the target. Close up she is the hardest sidearm in the
                // game and at distance she is worse than Fury — which is the whole
                // character, and why the roster entry puts her on the 'duelist' band
                // rather than leaving her at arm's length.
                //
                // 34 rounds is two 17-round magazines, and 2600ms to change is both of
                // them. The single Glock reloads in 2000 for one.
                //
                // `semiAuto` for the same reason the Glock carries it: one round per
                // pull is what the weapon is. On a two-barrel weapon it also stops the
                // pair becoming a held-trigger stream, which would be a submachine gun
                // with extra steps.
                dualglocks: { key: 'dualglocks', label: 'Dual Glocks', damage: 10, variance: 0.09, speed: 12, cooldown: 200, spin: false, draw: 'bolt', color: '#ffdca0', length: 18, multishot: 2, multishotArc: 0.12, magSize: 34, reloadMs: 2600, semiAuto: true },
                // Coulson's, and the exact opposite of the Glock above it in every
                // column that matters — which is why the two sit together. The
                // sidearm is fifteen a round twice a second; this is one shot that
                // ends the conversation and then a very long second of nothing.
                //
                // 55 is the largest single number any weapon in the game puts on a
                // target: past the Sniper Rifle's 48 and past even the Gamma Fists'
                // 82-before-the-melee-bonus, because those 82s only land inside 38px
                // and this crosses the arena. The 1100ms trigger is the entire price —
                // 50 sustained dps, level with the sniper and the lowest of any gun
                // here, so a miss costs more than a miss with anything else.
                //
                // Speed 10 rather than the sniper's 16, and deliberately slower than
                // the ordinary blaster's 8 is fast: it is a discharge rather than a
                // bullet, it should be seen crossing the room, and a heavy shot that
                // can be stepped out of is what keeps 55 fair. Carries Coulson's
                // 'calculated' profile partly for this reason — alwaysPredictive means
                // the AI leads its target, which a projectile this slow needs.
                //
                // No knockback, though the film is entirely knockback. The Wrench and
                // Mjølnir share a knockdown with a per-target immunity clock, and
                // adding a third carrier means touching that clock; it is a real
                // option rather than an oversight, and it is not in this change.
                destroyergun:{ key: 'destroyergun', label: 'Destroyer Gun', damage: 55, variance: 0.10, speed: 10, cooldown: 1100, spin: false, draw: 'bolt', color: '#ffb03a', length: 34 },

                /*  Eternity's. A ranged staff: it fires, it is not swung, and
                 *  sprite-kit's staff family is only how she holds it.
                 *
                 *  `realityRoll` is the whole weapon. Every hit that lands deals a
                 *  whole number from 0 to the target's current health, inclusive,
                 *  rolled in applyStatusAndDamage after every multiplier, so no
                 *  bonus can push it past the bar or pull it under 0. The top of
                 *  the range is a kill, 1 in (health + 1). On a fresh 200 that is
                 *  a longshot. On a fighter she has already worn down to 3 it is
                 *  1 in 4.
                 *
                 *  So the weapon hits hardest on someone healthy and trails off:
                 *  on average each hit takes half of what is left. That shape is
                 *  why the trigger is slow. At 900ms the opening hit is worth
                 *  about 100 against a 200-health target, which is Minigun money
                 *  for one shot, and it is paid for by every later hit being
                 *  worth half the one before.
                 *
                 *  `damage: 30` is never dealt to a fighter. Two things still read
                 *  the table's number: cover, which bullets chip for 60% of it,
                 *  and weaponPowerScore. 30 gives both a sensible middling figure
                 *  instead of a zero that makes the staff pass through walls.   */
                realitystaff:{ key: 'realitystaff', label: 'Reality Staff', damage: 30, variance: 0, speed: 10, cooldown: 900, spin: false, draw: 'zap', color: '#9fb2ff', length: 30, realityRoll: true },

                // What is left of the Zero Point, carried. Draws as a zap rather than
                // a bolt because it is energy off a broken singularity and should not
                // read as a gun.
                //
                // 26 every 300ms is 87 sustained. It was 19, which worked out at 63 —
                // the blaster's own figure to within a rounding error, on the one
                // weapon in the game you need a redeem code to hold. "A little above
                // the blaster" was the intent and the arithmetic never matched it.
                //
                // 87 is deliberately the Repulsors' old number rather than anything
                // higher: it is the hardest ordinary trigger on the roster, and it
                // still sits a long way under the Minigun's 150 and under the Beam,
                // which are the two weapons that are supposed to end the argument.
                // The trigger stays at 300ms — this should read as a stream of
                // something pouring out of him, not as a heavier gun.
                zeroenergy: { key: 'zeroenergy', label: 'Zero Energy',    damage: 26, variance: 0.10, speed: 12,  cooldown: 300, spin: false, draw: 'zap',    color: '#a274ff', length: 26 },
                // Submachine Gun — the fastest trigger in the game, and the weakest
                // round behind it.
                //
                // Rate of fire and magazine track the wiki: roughly eleven rounds a
                // second out of a 30-round magazine, which is about 2.7 seconds of
                // fire before a long reload. Damage is scaled to this roster like
                // every other gun of its kind — at 9 it lands around 82 dps, a shade
                // over the Assault Rifle's 80 and nowhere near the Minigun's 150.
                //
                // That near-tie with the rifle is the point rather than an accident.
                // An SMG normally buys its rate with terrible range, and this
                // game models no distance falloff at all — so if it also out-damaged
                // the rifle it would simply be a better rifle. What it gets instead
                // is the shortest gap between shots of any gun here, which is
                // what makes it feel like an SMG, and a magazine that empties in
                // under three seconds, which is what makes it cost something.
                //
                // Not modelled, because the game has no equivalent: hipfire accuracy,
                // the range falloff above, and the headshot multiplier.
                // UNVAULTED. It went out with the season pack for one reason: its only
                // carrier was a pack fighter and left with it. Bucky carries it
                // now and is not pack content — so the reason has expired, and it comes back exactly the way the forge
                // patterns describe the same test ("every other pattern in this table
                // has at least one Star Wars carrier").
                //
                // Vaulting never stopped it working — WEAPON_LIBRARY always resolved
                // it and a carrier would have fired it fine. What it stopped was the
                // handing out: the character fabricator's weapon list. Leaving it
                // vaulted would have meant a weapon visibly in play that the game also
                // reports as out of rotation and refuses to let you build with.
                submachine:  { key: 'submachine',  label: 'Submachine Gun', damage: 9, variance: 0.10, speed: 12, cooldown: 92, spin: false, draw: 'bolt', color: '#8fe9f5', length: 16, magSize: 30, reloadMs: 2400 },
                // Carries nothing. `weapon` is a required field on every character
                // and everything downstream expects a config to exist, so "no
                // weapon" is a weapon rather than a missing one — this is the entry
                // that says so out loud instead of parking an unused blaster on
                // someone who cannot fire it.
                //
                // An infinite cooldown means no firing path can ever loose a round,
                // whatever calls it: `now - lastShotTime > Infinity` is never true.
                unarmed:    { key: 'unarmed',    label: 'Unarmed',        damage: 0,  variance: 0,    speed: 0,   cooldown: Infinity, spin: false, draw: 'none', color: '#888888', length: 0 }
            };

            function getWeapon(charData) {
                const base = WEAPON_LIBRARY[charData?.weapon || 'blaster'] || WEAPON_LIBRARY.blaster;
                return { ...base, damage: charData?.weaponDamage ?? base.damage };
            }

            // ══════════════════════════════════════════════════════════════
            // THE ARMORY — player-forged weapons
            // ══════════════════════════════════════════════════════════════
            //
            // A forged weapon is not a parallel weapon system. It is a real
            // WEAPON_LIBRARY entry, compiled at load time from a saved recipe and
            // registered under a namespaced key ('forged:<id>'). Everything
            // downstream — getWeapon(), the Character constructor, Bullet, the
            // `draw` dispatch, magazine handling, multishot — already resolves a
            // library key, so none of it needs to know forging exists.
            //
            // The one thing a forged entry carries that a hand-written one does
            // not is `baseKey`: the pattern it was struck from. Code that
            // identifies a weapon by comparing its key against a literal
            // ('wrench', 'zap', the saber lists) must compare against the base
            // key, or a forged wrench stops being blunt. baseKeyOf() below is
            // that lookup, and Bullet sets its `type` from baseKey for the same
            // reason.

            // Recipes as persisted: { id, name, baseKey, mods: [modId], forgedAt }.
            let forgedWeapons = [];
            // charId -> forged weapon id. A character with no entry carries the
            // weapon its roster entry specifies, as before.
            let equippedForged = {};

            // Resolves any weapon key to the hand-authored library key it behaves
            // as. Plain keys pass through untouched, so this is safe to wrap
            // around any existing comparison.
            function baseKeyOf(key) {
                const w = WEAPON_LIBRARY[key];
                return (w && w.baseKey) || key;
            }

            // Patterns the armorer will strike from. Deliberately a curated list
            // rather than "every entry in WEAPON_LIBRARY" — Beam (0ms cooldown)
            // and Guards are balance outliers that exist as rewards, and Unarmed
            // is the explicit no-weapon entry. `requires` gates a pattern behind
            // owning the character who carries it.
            const FORGE_PATTERNS = [
                { baseKey: 'wrench',       cost: 140 },
                { baseKey: 'blaster',      cost: 150 },
                { baseKey: 'bowcaster',    cost: 180 },
                { baseKey: 'staff',        cost: 190 },
                { baseKey: 'lightsaber',   cost: 200 },
                { baseKey: 'vibroblade',   cost: 210 },
                { baseKey: 'flamethrower', cost: 250 },
                { baseKey: 'sniper',       cost: 260 },
                // VAULTED: FOUR FORGE PATTERNS.
                // `vaulted` takes a pattern out of the commission pool without taking
                // it out of the game: the row keeps its cost and its `requires`, so
                // deleting the one word puts it back exactly as it was. It is not
                // cosmetic — getForgePattern() still has to resolve these, or a
                // weapon a save already forged from one would price at Infinity.
                //

                { baseKey: 'minigun',      cost: 300, requires: 'thorn' },
                // No `requires`. It used to ask for Paz Vizsla, who carries a minigun
                // and has never carried a Darksaber — the gate was simply wrong. Its
                // three real carriers are Sabine Wren, Moff Gideon and The Mandalorian
                // (Elite); the first two are base roster, so there is nothing to buy
                // and nothing to gate on. It sits with the lightsaber now, which is
                // the company it always should have kept.
                { baseKey: 'darksaber',    cost: 320 },
            ];

            // Every modifier gives and takes. That is the whole balance model:
            // with no strictly-positive mod available, no combination of two can
            // produce a weapon that dominates the hand-tuned roster, and the
            // player is choosing a role for the weapon rather than rolling for
            // stats. `fits` hides mods that would be inert on a given pattern
            // (a magazine mod on a weapon with no magazine, etc.).
            const FORGE_MODS = [
                { id: 'beskar',    label: 'Beskar Weave',      cost: 150,
                  desc: 'Heavier hits: +25% damage, +18% cooldown',
                  apply: w => { w.damage *= 1.25; w.cooldown *= 1.18; } },
                { id: 'phrik',     label: 'Phrik Alloy',       cost: 130,
                  desc: 'Faster shots that land easier: +20% speed, −10% damage',
                  fits: w => !w.melee,
                  apply: w => { w.speed *= 1.2; w.damage *= 0.9; } },
                { id: 'honed',     label: 'Honed Edge',        cost: 160,
                  desc: 'Longer, harder swings: +18% damage, +15% reach, +15% cooldown',
                  fits: w => !!w.melee,
                  apply: w => { w.damage *= 1.18; w.reach *= 1.15; w.cooldown *= 1.15; } },
                { id: 'lightframe', label: 'Light Frame',      cost: 150,
                  desc: 'Faster but shorter: −22% cooldown, −15% reach, −12% damage',
                  fits: w => !!w.melee,
                  apply: w => { w.cooldown *= 0.78; w.reach *= 0.85; w.damage *= 0.88; } },
                { id: 'extmag',    label: 'Extended Magazine', cost: 120,
                  desc: 'Longer bursts: +50% magazine, +25% reload time',
                  fits: w => !!w.magSize,
                  apply: w => { w.magSize = Math.ceil(w.magSize * 1.5); w.reloadMs *= 1.25; } },
                { id: 'quickload', label: 'Quickload Rig',     cost: 120,
                  desc: 'Back in the fight sooner: −30% reload time, −20% magazine',
                  fits: w => !!w.magSize,
                  apply: w => { w.reloadMs *= 0.7; w.magSize = Math.max(1, Math.floor(w.magSize * 0.8)); } },
                // The damage cut scales with the projectile count, because adding
                // a projectile is worth far more to a weapon that fires one than
                // to a flamethrower that already fires three. A flat penalty made
                // this a straight +40% on single-shot weapons and a downgrade on
                // spread ones. n/(n+1) is the break-even split; the 1.08 is the
                // small edge that makes it worth paying for, bought against a
                // wider fan that rarely lands in full.
                { id: 'scatter',   label: 'Scatter Barrel',    cost: 210,
                  desc: '+1 projectile per shot, damage divided across the volley',
                  fits: w => !w.melee && !w.burst,
                  apply: w => { const n = w.multishot || 1;
                                w.multishot = n + 1;
                                w.multishotArc = (w.multishotArc || 0.22) * 1.15;
                                w.damage *= (n / (n + 1)) * 1.08; } },
            ];

            const FORGE_MAX_MODS = 2;
            // Scrapping returns half of what the weapon cost to make.
            const FORGE_SCRAP_RATE = 0.5;

            function getForgeMod(id) { return FORGE_MODS.find(m => m.id === id) || null; }
            function getForgePattern(baseKey) { return FORGE_PATTERNS.find(p => p.baseKey === baseKey) || null; }

            function isPatternAvailable(p) {
                return !p.requires || !!gameUnlocks[p.requires];
            }

            /*  Deliberately not folded into isPatternAvailable(). "Locked" and
             *  "vaulted" are different answers to the player — one is something they
             *  can go and buy, the other is out of rotation for everyone — and the
             *  forge needs to tell them apart to say so. */
            function isPatternVaulted(p) {
                return !!(p && (p.vaulted || isWeaponVaulted(p.baseKey)));
            }

            /** Is this weapon out of rotation?
             *
             *  Enforced at the point of USE, never at the point of definition — the
             *  entry is still in WEAPON_LIBRARY and still resolves, so a fighter or a
             *  forged weapon that already carries one is untouched. What this closes
             *  is the handing out of new ones. */
            function isWeaponVaulted(key) {
                const w = WEAPON_LIBRARY[key];
                return !!(w && w.vaulted);
            }

            // What a recipe costs to forge: the pattern plus every modifier on it.
            function forgeCost(baseKey, modIds) {
                const p = getForgePattern(baseKey);
                if (!p) return Infinity;
                return modIds.reduce((sum, id) => sum + (getForgeMod(id)?.cost || 0), p.cost);
            }

            // Compiles a saved recipe into a live WEAPON_LIBRARY entry. Spreading
            // the base is what carries `draw`, `melee`, `returnable`, `magSize`,
            // `semiAuto`, `burst` and friends across untouched — a forged wrench
            // still draws as a wrench and still knocks droids down.
            //
            // Note which identity goes where. The weapon is *stored* in the
            // library under a unique slot name ('forged:<id>'), but its `key`
            // stays the base key. `key` is behavioural identity: a dozen sfx and
            // effect branches switch on it to decide that this is a wrench, or a
            // saber, or a bowcaster. Leaving it as the pattern means every one of
            // those branches keeps working on a forged weapon without being
            // taught about forging. `forgedId` carries the unique identity for
            // the code that genuinely needs it (equipping, the armory UI).
            function compileForgedWeapon(rec) {
                const base = WEAPON_LIBRARY[rec.baseKey] || WEAPON_LIBRARY.blaster;
                const w = { ...base, key: rec.baseKey, baseKey: rec.baseKey,
                            forgedId: rec.id, label: rec.name, forged: true };
                (rec.mods || []).forEach(id => {
                    const mod = getForgeMod(id);
                    if (mod) { try { mod.apply(w); } catch (e) {} }
                });
                // Clamps. Modifiers are hand-picked and bounded, but rounding here
                // keeps the numbers whole for display and guarantees a forge can
                // never emit a 0ms-cooldown or 0-damage weapon by stacking.
                w.damage   = Math.max(1, Math.round(w.damage));
                w.cooldown = Math.max(60, Math.round(w.cooldown));
                w.variance = Math.max(0, Math.min(0.6, +w.variance.toFixed(3)));
                w.speed    = +w.speed.toFixed(2);
                if (w.reach)    w.reach    = Math.round(w.reach);
                if (w.magSize)  w.magSize  = Math.max(1, Math.round(w.magSize));
                if (w.reloadMs) w.reloadMs = Math.round(w.reloadMs);
                return w;
            }

            // Registers every saved recipe into WEAPON_LIBRARY. Must run after the
            // library literal has been evaluated and before any character is built
            // from an equipped forged key.
            function registerForgedWeapons() {
                forgedWeapons.forEach(rec => {
                    WEAPON_LIBRARY['forged:' + rec.id] = compileForgedWeapon(rec);
                });
            }

            // The weapon a character actually carries: their forged loadout if one
            // is equipped and still exists, otherwise their roster weapon.
            function getEquippedWeaponKey(charId, fallbackKey) {
                const fid = equippedForged[charId];
                if (fid && WEAPON_LIBRARY['forged:' + fid]) return 'forged:' + fid;
                return fallbackKey;
            }

            // Emoji for any weapon key, forged slots included — a forged weapon
            // wears the icon of the pattern it was struck from.
            function weaponEmojiFor(key) {
                return weaponEmoji[key] || weaponEmoji[baseKeyOf(key)] || '⚔️';
            }

            // The icon a roster entry should show, accounting for a forged loadout.
            function rosterWeaponEmoji(char) {
                return weaponEmojiFor(getEquippedWeaponKey(char.id, char.weapon));
            }

            // A forged weapon as read from a save, or null. Its name lands in
            // innerHTML (the rack, the HUD label) and its mods are walked when it
            // is compiled at boot, so a hand-edited or shared save is held to what
            // the forge itself writes, the same way creations are.
            function sanitizeForgedRecord(r) {
                if (!r || typeof r !== 'object') return null;
                if (typeof r.id !== 'string' || !/^[A-Za-z0-9_-]{1,48}$/.test(r.id)) return null;
                if (typeof r.baseKey !== 'string' || r.baseKey.startsWith('forged:') ||
                    !Object.prototype.hasOwnProperty.call(WEAPON_LIBRARY, r.baseKey)) return null;
                return { ...r, name: sanitizeForgeName(r.name) || armoryPatternLabel(r.baseKey),
                         mods: Array.isArray(r.mods) ? r.mods.filter(m => typeof m === 'string') : [],
                         cost: savedNumber(r.cost, 0, Number.MAX_SAFE_INTEGER, 0) };
            }

            function loadArmory() {
                const saved = loadVersioned('galacticDuelArmory', null);
                if (saved && typeof saved === 'object') {
                    forgedWeapons = Array.isArray(saved.forged) ? saved.forged.map(sanitizeForgedRecord).filter(Boolean) : [];
                    equippedForged = (saved.equipped && typeof saved.equipped === 'object' && !Array.isArray(saved.equipped))
                        ? saved.equipped : {};
                }
                registerForgedWeapons();
                // Drop equips pointing at weapons that no longer exist (a save
                // edited by hand, or a recipe dropped by the filter above), and
                // equips on anyone who is not a creation — only the Zero Point's
                // characters may carry forged weapons, and a save predating that
                // rule can still hold assignments to shipped characters.
                Object.keys(equippedForged).forEach(cid => {
                    if (!WEAPON_LIBRARY['forged:' + equippedForged[cid]] || !isCreatedCharacter(cid)) {
                        delete equippedForged[cid];
                    }
                });
            }

            function saveArmory() {
                saveVersioned('galacticDuelArmory', { forged: forgedWeapons, equipped: equippedForged });
            }

            // ── ARMORY UI ──────────────────────────────────────────────────
            const armoryOverlay = document.getElementById('armoryOverlay');

            // Weapon names are player-typed and land in innerHTML in several
            // places (the rack, the HUD label). Strip the characters that would
            // let a name break out of its element.
            function sanitizeForgeName(raw) {
                return String(raw || '').replace(/[<>&"']/g, '').trim().slice(0, 24);
            }

            // The in-progress commission. Not persisted — an unforged design is
            // discarded when the overlay closes. `editingId` set means this is a
            // rework of an existing weapon rather than a new commission: the
            // weapon keeps its id (so anything carrying it keeps carrying it)
            // and the player settles the difference in price rather than paying
            // the whole cost again.
            let forgeSel = { baseKey: null, mods: [], editingId: null };

            function armoryPatternLabel(baseKey) {
                return (WEAPON_LIBRARY[baseKey] && WEAPON_LIBRARY[baseKey].label) || baseKey;
            }

            // Mods that would do nothing on this pattern are hidden rather than
            // shown disabled — an Extended Magazine on a magazineless blaster is
            // not a choice the player is failing to afford, it is meaningless.
            function availableModsFor(baseKey) {
                const base = WEAPON_LIBRARY[baseKey];
                if (!base) return [];
                return FORGE_MODS.filter(m => !m.fits || m.fits(base));
            }

            function renderArmoryPatterns() {
                const host = document.getElementById('armoryPatterns');
                if (!host) return;
                host.innerHTML = '';
                /*  Vaulted patterns are off the board entirely — the vault is not a
                 *  display shelf, and a commission screen should only offer things
                 *  that can be commissioned.
                 *
                 *  The one exception is the pattern currently being worked on. A
                 *  rework of a weapon already forged from a vaulted pattern is still
                 *  allowed (see forgeWeapon), and hiding its tile unconditionally
                 *  would leave that edit with nothing selected on a board that had
                 *  silently dropped the answer. It comes back disabled and marked, so
                 *  it reads as "this is what you are reworking" rather than as
                 *  something still on offer — and switching away from it during the
                 *  edit is a one-way door, which is correct: that is a new
                 *  commission, and the vault is shut.                             */
                FORGE_PATTERNS.filter(p => !isPatternVaulted(p) || forgeSel.baseKey === p.baseKey)
                              .forEach(p => {
                    const vaulted = isPatternVaulted(p);
                    const available = !vaulted && isPatternAvailable(p);
                    const btn = document.createElement('button');
                    btn.className = 'armory-pattern'
                        + (forgeSel.baseKey === p.baseKey ? ' selected' : '')
                        + (vaulted ? ' vaulted' : '');
                    btn.disabled = !available;
                    if (vaulted) {
                        btn.title = 'Vaulted — out of the commission pool. Anything already '
                                  + 'forged from this pattern still works and can still be reworked.';
                    }
                    const nameHtml = `<span class="ap-name">${weaponEmojiFor(p.baseKey)} ${armoryPatternLabel(p.baseKey)}</span>`;
                    btn.innerHTML = available
                        ? `${nameHtml}<span class="ap-cost">${p.cost} cr</span>`
                        : vaulted
                            ? `${nameHtml}<span class="ap-lock ap-vault">🗄️ Vaulted</span>`
                            : `${nameHtml}<span class="ap-lock">🔒 Locked</span>`;
                    btn.addEventListener('click', () => {
                        forgeSel.baseKey = p.baseKey;
                        // Drop mods that don't apply to the new pattern.
                        const valid = new Set(availableModsFor(p.baseKey).map(m => m.id));
                        forgeSel.mods = forgeSel.mods.filter(id => valid.has(id));
                        renderArmoryForge();
                    });
                    host.appendChild(btn);
                });
            }

            function renderArmoryMods() {
                const host = document.getElementById('armoryMods');
                if (!host) return;
                host.innerHTML = '';
                if (!forgeSel.baseKey) {
                    host.innerHTML = '<div class="armory-empty">Choose a pattern first.</div>';
                    return;
                }
                const mods = availableModsFor(forgeSel.baseKey);
                mods.forEach(m => {
                    const selected = forgeSel.mods.includes(m.id);
                    const atCap = forgeSel.mods.length >= FORGE_MAX_MODS && !selected;
                    const btn = document.createElement('button');
                    btn.className = 'armory-mod' + (selected ? ' selected' : '');
                    btn.disabled = atCap;
                    btn.innerHTML = `<span><span class="am-name">${selected ? '✓ ' : ''}${m.label}</span><br>
                                     <span class="am-desc">${m.desc}</span></span>
                                     <span class="am-cost">${m.cost} cr</span>`;
                    btn.addEventListener('click', () => {
                        if (selected) forgeSel.mods = forgeSel.mods.filter(id => id !== m.id);
                        else if (forgeSel.mods.length < FORGE_MAX_MODS) forgeSel.mods.push(m.id);
                        renderArmoryForge();
                    });
                    host.appendChild(btn);
                });
            }

            // Stat lines for a compiled weapon, with the direction of each change
            // against the pattern it came from. Only the fields that exist on this
            // weapon are listed, so a saber doesn't advertise an empty magazine.
            function forgeStatRows(base, made) {
                // Spread is deliberately absent: no modifier alters variance any
                // more, so the row could only ever print the pattern's own value
                // unchanged. compileForgedWeapon still clamps variance, so a
                // future spread mod would work — it would just need its row back.
                const rows = [
                    { label: 'Damage',      a: base.damage,   b: made.damage,   better: 'up' },
                    { label: 'Cooldown',    a: base.cooldown, b: made.cooldown, better: 'down', unit: 'ms' },
                ];
                if (!base.melee) rows.push({ label: 'Speed', a: base.speed, b: made.speed, better: 'up', dp: 2 });
                if (base.reach)   rows.push({ label: 'Reach',    a: base.reach,    b: made.reach,    better: 'up' });
                if (base.magSize) rows.push({ label: 'Magazine', a: base.magSize,  b: made.magSize,  better: 'up' });
                if (base.reloadMs) rows.push({ label: 'Reload',  a: base.reloadMs, b: made.reloadMs, better: 'down', unit: 'ms' });
                if (made.multishot > 1 || base.multishot > 1) {
                    rows.push({ label: 'Projectiles', a: base.multishot || 1, b: made.multishot || 1, better: 'up' });
                }
                return rows;
            }

            // One stat line. Colour alone carries whether a change is good or bad
            // — an earlier version also appended ▲/▼ for the numeric direction,
            // which meant rows like a red ▲ on cooldown, where the arrow and the
            // colour appeared to contradict each other. The before → after pair
            // already shows which way the number moved.
            function renderForgeStatRow(r) {
                const dp = r.dp || 0;
                const fmt = v => (dp ? Number(v).toFixed(dp) : Math.round(v)) + (r.unit || '');
                if (r.b === r.a) {
                    return `<div class="apv-row"><span class="apv-label">${r.label}</span>` +
                           `<span class="apv-from"></span><span class="apv-arrow"></span>` +
                           `<span class="apv-to apv-same">${fmt(r.b)}</span></div>`;
                }
                const improved = r.better === 'up' ? r.b > r.a : r.b < r.a;
                return `<div class="apv-row"><span class="apv-label">${r.label}</span>` +
                       `<span class="apv-from">${fmt(r.a)}</span><span class="apv-arrow">→</span>` +
                       `<span class="apv-to ${improved ? 'apv-up' : 'apv-down'}">${fmt(r.b)}</span></div>`;
            }

            function renderArmoryPreview() {
                const host = document.getElementById('armoryPreview');
                if (!host) return;
                if (!forgeSel.baseKey) {
                    host.innerHTML = '<div class="armory-placeholder">Choose a pattern to see what the armorer would make.</div>';
                    return;
                }
                const base = WEAPON_LIBRARY[forgeSel.baseKey];
                // Compile a throwaway recipe so the preview runs the exact same
                // path as the real forge — no second implementation to drift.
                const made = compileForgedWeapon({ id: '__preview', name: 'Preview',
                                                   baseKey: forgeSel.baseKey, mods: forgeSel.mods });
                host.innerHTML = forgeStatRows(base, made).map(renderForgeStatRow).join('');
            }

            function editingForgeRecord() {
                return forgeSel.editingId ? forgeWeaponRecord(forgeSel.editingId) : null;
            }

            function forgeWeaponRecord(id) {
                return forgedWeapons.find(r => r.id === id) || null;
            }

            function renderArmoryForge() {
                renderArmoryPatterns();
                renderArmoryMods();
                renderArmoryPreview();
                const costEl = document.getElementById('armoryCost');
                const btn = document.getElementById('armoryForgeBtn');
                const nameEl = document.getElementById('armoryNameInput');
                const banner = document.getElementById('armoryEditBanner');
                const cancelBtn = document.getElementById('armoryCancelEditBtn');
                const editing = editingForgeRecord();

                if (banner) {
                    banner.style.display = editing ? 'block' : 'none';
                    if (editing) banner.innerHTML = `Reworking <strong>${editing.name}</strong>. ` +
                        `It keeps its place in the Armory — anyone carrying it keeps carrying it.`;
                }
                if (cancelBtn) cancelBtn.style.display = editing ? 'inline-block' : 'none';
                if (!costEl || !btn) return;

                if (!forgeSel.baseKey) {
                    costEl.textContent = '—';
                    costEl.classList.remove('unaffordable');
                    btn.disabled = true;
                    btn.textContent = editing ? 'Save changes' : 'Forge';
                    return;
                }
                const cost = forgeCost(forgeSel.baseKey, forgeSel.mods);
                const named = sanitizeForgeName(nameEl && nameEl.value).length > 0;

                // Reworking settles the difference: a costlier build is charged
                // the extra, a cheaper one refunds it. Paying the full price
                // again would mean editing a weapon cost more than scrapping it
                // and starting over, which would make the button pointless.
                const delta = editing ? cost - (editing.cost || 0) : cost;
                const affordable = credits >= Math.max(0, delta);

                if (editing) {
                    costEl.textContent = delta === 0 ? `${cost} cr — no change`
                                       : delta > 0  ? `${cost} cr (pay ${delta})`
                                                    : `${cost} cr (refund ${-delta})`;
                } else {
                    costEl.textContent = `${cost} cr`;
                }
                costEl.classList.toggle('unaffordable', !affordable);
                btn.disabled = !affordable || !named;
                btn.textContent = !affordable ? 'Not enough credits'
                                : !named ? 'Name it first'
                                : editing ? 'Save changes' : 'Forge';
            }

            // Loads an existing weapon back into the commission form.
            function beginEditForgedWeapon(id) {
                const rec = forgeWeaponRecord(id);
                if (!rec) return;
                forgeSel = { baseKey: rec.baseKey, mods: [...(rec.mods || [])], editingId: rec.id };
                const nameEl = document.getElementById('armoryNameInput');
                if (nameEl) nameEl.value = rec.name;
                setArmoryTab('forge');
                renderArmoryForge();
            }

            function cancelForgeEdit() {
                forgeSel = { baseKey: null, mods: [], editingId: null };
                const nameEl = document.getElementById('armoryNameInput');
                if (nameEl) nameEl.value = '';
                renderArmoryForge();
            }

            function forgeWeapon() {
                if (!forgeSel.baseKey) return;
                const pattern = getForgePattern(forgeSel.baseKey);
                if (!pattern || !isPatternAvailable(pattern)) return;
                const nameEl = document.getElementById('armoryNameInput');
                const name = sanitizeForgeName(nameEl && nameEl.value);
                if (!name) return;
                const cost = forgeCost(forgeSel.baseKey, forgeSel.mods);
                const editing = editingForgeRecord();
                // A vaulted pattern is out of the pool, not confiscated: a weapon
                // already on the rack can still be reworked and stays equipped to
                // whoever carries it. Only a *new* commission is refused. The grid
                // disables these tiles anyway, so this is the rule living with the
                // action rather than only with the drawing of it — the same reason
                // purchaseShopItem() re-checks its own lock.
                if (isPatternVaulted(getForgePattern(forgeSel.baseKey)) && !editing) return;
                const delta = editing ? cost - (editing.cost || 0) : cost;
                if (credits < Math.max(0, delta)) return;

                let rec;
                if (editing) {
                    // Mutated in place, keeping the id. That is what lets a
                    // reworked weapon stay equipped to whoever was carrying it —
                    // equippedForged maps character ids to this id, and the
                    // library slot is named from it too.
                    rec = editing;
                    rec.name = name;
                    rec.baseKey = forgeSel.baseKey;
                    rec.mods = [...forgeSel.mods];
                    rec.cost = cost;
                    rec.reworkedAt = new Date().toISOString();
                } else {
                    rec = {
                        id: 'w' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
                        name,
                        baseKey: forgeSel.baseKey,
                        mods: [...forgeSel.mods],
                        cost,                   // remembered so scrapping can refund against it
                        forgedAt: new Date().toISOString()
                    };
                    forgedWeapons.push(rec);
                }

                credits -= delta;
                WEAPON_LIBRARY['forged:' + rec.id] = compileForgedWeapon(rec);
                saveArmory();
                saveGameSettings();
                updateCreditsDisplay();
                // A reworked weapon can change the icon a roster button shows.
                rebuildAllRosters();

                forgeSel = { baseKey: null, mods: [], editingId: null };
                if (nameEl) nameEl.value = '';
                renderArmoryForge();
                renderArmoryRack();
                setArmoryTab('rack');
                if (editing) {
                    showAnnouncement(`The armorer reworks ${rec.name}.`, '#ff8c42', 3500, '🔨 REFORGED', 100);
                } else {
                    showAnnouncement(`The armorer hands you ${rec.name}.`, '#ff8c42', 4000, '🔨 WEAPON FORGED', 100);
                }
            }

            function scrapWeapon(id) {
                const idx = forgedWeapons.findIndex(r => r.id === id);
                if (idx === -1) return;
                const rec = forgedWeapons[idx];
                const refund = Math.floor((rec.cost || 0) * FORGE_SCRAP_RATE);

                forgedWeapons.splice(idx, 1);
                delete WEAPON_LIBRARY['forged:' + id];
                // Scrapping the weapon currently loaded in the form would leave
                // the commission editing something that no longer exists.
                if (forgeSel.editingId === id) forgeSel = { baseKey: null, mods: [], editingId: null };
                // Any character carrying it falls back to their issued weapon.
                Object.keys(equippedForged).forEach(cid => {
                    if (equippedForged[cid] === id) delete equippedForged[cid];
                });
                credits += refund;
                saveArmory();
                saveGameSettings();
                updateCreditsDisplay();
                renderArmoryRack();
                renderArmoryForge();
                rebuildAllRosters();
                showAnnouncement(`${rec.name} melted down for ${refund} credits.`, '#cc7777', 3000, '♻️ SCRAPPED', 90);
            }

            // Only the Zero Point's creations may carry forged weapons. The
            // shipped roster fights with what it was written to carry — their
            // stat blocks are balanced around those weapons, and letting a
            // forged Beskar sniper onto a 280HP Palpatine would undo that in one
            // click. A creation, by contrast, was paid for at a price that
            // already scaled with its power, so arming it further is the
            // player spending twice on the same character.
            function equippableCharacters() {
                return createdCharacters.map(rec =>
                    characters.heroes.concat(characters.villains).find(c => c.id === rec.id)
                ).filter(Boolean);
            }

            function renderArmoryRack() {
                const host = document.getElementById('armoryRack');
                const countEl = document.getElementById('armoryRackCount');
                if (countEl) countEl.textContent = forgedWeapons.length ? `(${forgedWeapons.length})` : '';
                if (!host) return;
                host.innerHTML = '';
                if (!forgedWeapons.length) {
                    host.innerHTML = '<div class="armory-empty">The armorer has made nothing for you yet.</div>';
                    return;
                }

                const chars = equippableCharacters();
                forgedWeapons.forEach(rec => {
                    const made = WEAPON_LIBRARY['forged:' + rec.id];
                    if (!made) return;
                    const base = WEAPON_LIBRARY[rec.baseKey];
                    const holderId = Object.keys(equippedForged).find(cid => equippedForged[cid] === rec.id);
                    const holder = holderId && chars.find(c => c.id === holderId);

                    const el = document.createElement('div');
                    el.className = 'armory-weapon';

                    const modNames = (rec.mods || []).map(id => getForgeMod(id)?.label).filter(Boolean);
                    el.innerHTML = `
                        <div class="armory-weapon-head">
                            <div>
                                <div class="armory-weapon-name">${weaponEmojiFor(rec.baseKey)} ${rec.name}</div>
                                <div class="armory-weapon-base">${armoryPatternLabel(rec.baseKey)} pattern</div>
                            </div>
                            ${holder ? `<span class="armory-equipped-tag">Carried by ${holder.name}</span>` : ''}
                        </div>
                        <div class="armory-weapon-stats">${forgeStatRows(base, made).map(renderForgeStatRow).join('')}</div>
                        ${modNames.length ? `<div class="armory-weapon-mods">${modNames.join(' · ')}</div>` : ''}
                    `;

                    const actions = document.createElement('div');
                    actions.className = 'armory-weapon-actions';

                    const select = document.createElement('select');
                    select.className = 'armory-equip-select';
                    select.innerHTML = '<option value="">— Not carried —</option>' +
                        chars.map(c => `<option value="${c.id}"${holderId === c.id ? ' selected' : ''}>${c.name}</option>`).join('');
                    select.addEventListener('change', () => {
                        // One weapon per character, and one character per weapon:
                        // clear this weapon's old holder, then clear whatever the
                        // new holder was carrying, before assigning.
                        Object.keys(equippedForged).forEach(cid => {
                            if (equippedForged[cid] === rec.id) delete equippedForged[cid];
                        });
                        if (select.value) equippedForged[select.value] = rec.id;
                        saveArmory();
                        renderArmoryRack();
                        rebuildAllRosters();
                    });
                    actions.appendChild(select);

                    const editBtn = document.createElement('button');
                    editBtn.className = 'edit-btn';
                    editBtn.textContent = 'Edit';
                    editBtn.addEventListener('click', () => beginEditForgedWeapon(rec.id));
                    actions.appendChild(editBtn);

                    const scrapBtn = document.createElement('button');
                    scrapBtn.className = 'armory-scrap-btn';
                    scrapBtn.textContent = `Scrap (+${Math.floor((rec.cost || 0) * FORGE_SCRAP_RATE)} cr)`;
                    scrapBtn.addEventListener('click', () => scrapWeapon(rec.id));
                    actions.appendChild(scrapBtn);

                    el.appendChild(actions);
                    host.appendChild(el);
                });
            }

            function setArmoryTab(tab) {
                document.querySelectorAll('.armory-tab').forEach(b => {
                    b.classList.toggle('active', b.dataset.tab === tab);
                });
                const forgeBody = document.getElementById('armoryForgeTab');
                const rackBody = document.getElementById('armoryRackTab');
                const forgeRow = document.getElementById('armoryForgeRow');
                if (forgeBody) forgeBody.style.display = tab === 'forge' ? 'flex' : 'none';
                if (rackBody)  rackBody.style.display  = tab === 'rack'  ? 'flex' : 'none';
                // The price and Forge button live outside the tab bodies now, so
                // they have to be hidden explicitly when the rack is showing.
                if (forgeRow)  forgeRow.style.display  = tab === 'forge' ? 'flex' : 'none';
            }

            function openArmory() {
                forgeSel = { baseKey: null, mods: [], editingId: null };
                const nameEl = document.getElementById('armoryNameInput');
                if (nameEl) nameEl.value = '';
                updateCreditsDisplay();
                renderArmoryForge();
                renderArmoryRack();
                setArmoryTab('forge');
                if (armoryOverlay) armoryOverlay.style.display = 'flex';
            }

            document.querySelectorAll('.armory-tab').forEach(b => {
                b.addEventListener('click', () => setArmoryTab(b.dataset.tab));
            });
            const armoryNameInput = document.getElementById('armoryNameInput');
            if (armoryNameInput) armoryNameInput.addEventListener('input', renderArmoryForge);
            const armoryForgeBtn = document.getElementById('armoryForgeBtn');
            if (armoryForgeBtn) armoryForgeBtn.addEventListener('click', forgeWeapon);
            const armoryCancelEditBtn = document.getElementById('armoryCancelEditBtn');
            if (armoryCancelEditBtn) armoryCancelEditBtn.addEventListener('click', cancelForgeEdit);
            const armoryCloseBtn = document.getElementById('armoryCloseBtn');
            if (armoryCloseBtn) armoryCloseBtn.addEventListener('click', () => {
                if (armoryOverlay) armoryOverlay.style.display = 'none';
                refreshSplashState();   // the rack count on the tile behind it
            });
            if (armoryOverlay) armoryOverlay.addEventListener('click', (e) => {
                if (e.target === armoryOverlay) armoryOverlay.style.display = 'none';
            });
            const btnArmory = document.getElementById('btnArmory');
            if (btnArmory) btnArmory.addEventListener('click', openArmory);

            // ══════════════════════════════════════════════════════════════
            // THE ZERO POINT — character creation
            // ══════════════════════════════════════════════════════════════
            //
            // In the fiction it is named for, the Zero Point is the heart of all reality
            // and the origin of the Power of Creation — an energy that "can
            // fabricate entirely new souls, create entirely new lifeforms, and
            // construct entirely new realities". That is the in-fiction excuse
            // for a character creator, and the reason this panel is themed on
            // its blue-going-violet orb rather than on anything Imperial.
            //
            // A created character is stored as a recipe and spliced into the
            // live roster (characters.heroes / characters.villains) at load, so
            // the roster grid, the opponent picker, isCharacterUnlocked() and
            // setupGame()'s id lookup all treat it exactly like a shipped
            // character. Nothing downstream needs to know it was made here.

            const creatorOverlay = document.getElementById('creatorOverlay');

            let createdCharacters = [];

            // Ids of created characters that chose the Sith nature. The dark-aura
            // pulse in Character.draw() keys off VILLAIN_ID_SET, which is faction
            // membership — but nature and allegiance are independent choices here,
            // so a Sith-natured hero would otherwise lose its aura and a plain
            // character placed among the villains would gain one it never picked.
            // This set is the explicit answer, checked alongside that one.
            const CUSTOM_SITH_IDS = new Set();

            function sanitizeCharName(raw) {
                return String(raw || '').replace(/[<>&"']/g, '').trim().slice(0, 22);
            }

            const CREATOR_BIO_MAX = 200;

            // Bios keep their punctuation. A name is stripped of the characters
            // that matter to HTML, which is fine for a short label but would gut
            // a sentence — no apostrophes means no "she's". So a bio is stored
            // as the player typed it and escaped at the point it is compiled
            // into a roster entry, which is the thing that reaches innerHTML.
            // Control characters go, since the stat card is a single flow of text.
            function sanitizeCharBio(raw) {
                return String(raw || '')
                    .replace(/[\x00-\x1f\x7f]/g, ' ')   // newlines and control chars -> space
                    .replace(/\s+/g, ' ')
                    .trim()
                    .slice(0, CREATOR_BIO_MAX);
            }

            const HTML_ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
            function escapeHtmlText(s) {
                return String(s == null ? '' : s).replace(/[&<>"']/g, c => HTML_ESCAPES[c]);
            }

            // The three natures. `weapon` set means the choice is forced and the
            // weapon step is locked — a droid is assembled around its zap emitter.
            const CREATOR_TYPES = [
                { id: 'normal', label: 'Normal',
                  desc: 'A person. No special properties — picks any weapon.',
                  surcharge: 0 },
                { id: 'droid',  label: 'Droid',
                  desc: 'Built, not born. Comes with Zap. Immune to stun and knockdown, but takes double damage from wrenches.',
                  surcharge: 120, weapon: 'zap', isDroid: true },
                { id: 'sith',   label: 'Sith',
                  desc: 'Made out of the dark. Carries the pulsing Sith aura.',
                  surcharge: 80, isSith: true },
            ];

            // The two factions the roster is actually split into, matching the
            // section headings on the character select screen.
            const CREATOR_FACTIONS = [
                { id: 'heroes',   label: 'Grand Army & Heroes', desc: 'Fights on the light side of the roster.' },
                { id: 'villains', label: 'Sith & Separatists',  desc: 'Fights on the dark side of the roster.' },
            ];

            // Base weapons a creation may be issued. Kept to the unrestricted
            // roster weapons — the reward and pack weapons stay earned rather than
            // purchasable through the back door, and a creation can always be
            // handed something better from the Armory later.
            // Filtered through the weapon vault on the way out rather than hand-kept
            // in step with it: nothing on this list is vaulted today, and if one ever
            // is, the fabricator stops offering it without a second edit.
            const CREATOR_WEAPONS = ['blaster', 'zap', 'bowcaster', 'lightsaber', 'staff', 'vibroblade', 'wrench', 'sniper']
                .filter(k => !isWeaponVaulted(k));

            const CREATOR_BASE_COST = 150;
            const CREATOR_BASE_HP = 80;      // the cheapest possible creation
            const CREATOR_HP_RATE = 2.5;     // credits per point of health above the base
            // Credits per point of weapon DPS. Health spans 180 points and the
            // weapon list only spans ~27 DPS, so this rate has to be several
            // times the health rate for the weapon choice to register in the
            // price at all rather than being swamped by the slider.
            const CREATOR_POWER_RATE = 5.0;
            const CREATOR_REFUND_RATE = 0.5;

            // Sustained damage per second, reload downtime included. This is the
            // same measure used to rank the shipped roster, so a creation's price
            // tracks how strong its weapon actually is rather than a hand-set
            // tier — a Sniper Rifle costs more than a Zap because it does more.
            function weaponPowerScore(weaponKey) {
                const w = WEAPON_LIBRARY[weaponKey];
                if (!w || !isFinite(w.cooldown)) return 0;
                const cd = Math.max(w.cooldown, 1000 / 60);
                const perShot = w.damage * (w.multishot || 1);
                if (w.magSize) {
                    const cycleMs = w.magSize * cd + (w.reloadMs || 0);
                    return (perShot * w.magSize) / (cycleMs / 1000);
                }
                return perShot / (cd / 1000);
            }

            // Stronger creations cost more: health above the floor, the weapon's
            // real damage output, and a surcharge for a nature that carries
            // mechanical advantages.
            function creationCost(sel) {
                const type = CREATOR_TYPES.find(t => t.id === sel.type);
                if (!type) return Infinity;
                const weapon = type.weapon || sel.weapon;
                if (!weapon) return Infinity;
                const hp = Math.max(CREATOR_BASE_HP, sel.hp || CREATOR_BASE_HP);
                return Math.round(
                    CREATOR_BASE_COST +
                    (hp - CREATOR_BASE_HP) * CREATOR_HP_RATE +
                    weaponPowerScore(weapon) * CREATOR_POWER_RATE +
                    type.surcharge
                );
            }

            // Turns a stored recipe into a roster entry of exactly the shape the
            // shipped characters use.
            function compileCreatedCharacter(rec) {
                const type = CREATOR_TYPES.find(t => t.id === rec.type) || CREATOR_TYPES[0];
                return {
                    id: rec.id,
                    name: rec.name,
                    color: rec.color,
                    hp: rec.hp,
                    weapon: type.weapon || rec.weapon,
                    saberColor: rec.saberColor || rec.color,
                    isDroid: !!type.isDroid,
                    created: true,
                    // Escaped here rather than stripped at input, so the player's
                    // punctuation survives into the stat card — which renders this
                    // through innerHTML. A blank bio falls back to the house line.
                    bio: rec.bio ? escapeHtmlText(rec.bio) : `Fabricated at ${creatorPlaceName()}.`
                };
            }

            function isCreatedCharacter(charId) {
                return createdCharacters.some(r => r.id === charId);
            }

            // Splices every creation into the live roster arrays. Called once at
            // load and again after any create/delete, so the character select
            // screen and the opponent picker stay in step with the Zero Point.
            function applyCreatedCharacters() {
                // Drop the previous pass first — this runs again after every
                // change, and without it a rename would leave the old entry
                // sitting in the roster beside the new one.
                characters.heroes   = characters.heroes.filter(c => !c.created);
                characters.villains = characters.villains.filter(c => !c.created);
                CUSTOM_SITH_IDS.clear();

                createdCharacters.forEach(rec => {
                    const entry = compileCreatedCharacter(rec);
                    if (rec.type === 'sith') CUSTOM_SITH_IDS.add(rec.id);
                    if (rec.faction === 'villains') characters.villains.push(entry);
                    else characters.heroes.push(entry);
                });
            }

            // A creation as read from a save, or null if it cannot be one. Save
            // files are plain JSON that players edit and share, and a creation's
            // name and colour reach innerHTML and inline styles across the roster,
            // so a shared save could carry a script in a name. Every field is held
            // to what the fabricator itself writes.
            const CREATOR_MAX_HP = 260;   // the HP slider's max in index.html
            function sanitizeCreationRecord(r) {
                if (!r || typeof r !== 'object') return null;
                if (typeof r.id !== 'string' || !/^[A-Za-z0-9_-]{1,48}$/.test(r.id)) return null;
                const name = sanitizeCharName(r.name);
                if (!name) return null;
                const isHex = v => typeof v === 'string' && /^#[0-9a-fA-F]{3,8}$/.test(v);
                const type = CREATOR_TYPES.find(t => t.id === r.type) || CREATOR_TYPES[0];
                const color = isHex(r.color) ? r.color : '#8fbcff';
                const weapon = (typeof r.weapon === 'string' && !r.weapon.startsWith('forged:') &&
                    Object.prototype.hasOwnProperty.call(WEAPON_LIBRARY, r.weapon)) ? r.weapon : (type.weapon || 'blaster');
                return { ...r, id: r.id, name, bio: sanitizeCharBio(r.bio), type: type.id,
                         faction: r.faction === 'villains' ? 'villains' : 'heroes',
                         weapon, hp: Math.round(savedNumber(r.hp, CREATOR_BASE_HP, CREATOR_MAX_HP, 140)),
                         color, saberColor: isHex(r.saberColor) ? r.saberColor : color,
                         cost: savedNumber(r.cost, 0, Number.MAX_SAFE_INTEGER, 0) };
            }

            function loadCreatedCharacters() {
                const saved = loadVersioned('galacticDuelCreations', null);
                if (Array.isArray(saved)) {
                    createdCharacters = saved.map(sanitizeCreationRecord).filter(Boolean);
                }
                applyCreatedCharacters();
            }

            function saveCreatedCharacters() {
                saveVersioned('galacticDuelCreations', createdCharacters);
            }

            // ── ZERO POINT UI ──────────────────────────────────────────────
            // `editingId` set means this is a remake of an existing creation.
            // The character keeps its id, so its forged loadout, its favourite
            // star and anything else keyed to it survive the edit.
            let creatorSel = { type: null, faction: null, weapon: null, hp: 140, color: '#8fbcff', bio: '', editingId: null };

            function createdCharacterRecord(id) {
                return createdCharacters.find(r => r.id === id) || null;
            }

            function editingCreationRecord() {
                return creatorSel.editingId ? createdCharacterRecord(creatorSel.editingId) : null;
            }

            // The weapon a selection will actually ship with — a droid's is
            // decided by its nature, not by the weapon step.
            function creatorResolvedWeapon(sel) {
                const type = CREATOR_TYPES.find(t => t.id === sel.type);
                return (type && type.weapon) || sel.weapon || null;
            }

            function renderCreatorTypes() {
                const host = document.getElementById('creatorTypes');
                if (!host) return;
                host.innerHTML = '';
                CREATOR_TYPES.forEach(t => {
                    const btn = document.createElement('button');
                    btn.className = 'creator-choice' + (creatorSel.type === t.id ? ' selected' : '');
                    btn.innerHTML = `<span class="cc-name">${t.label}</span>
                                     <span class="cc-desc">${t.desc}</span>` +
                                    (t.surcharge ? `<span class="cc-cost">+${t.surcharge} cr</span>` : '');
                    btn.addEventListener('click', () => {
                        creatorSel.type = t.id;
                        // A droid's weapon is not the player's to pick.
                        if (t.weapon) creatorSel.weapon = t.weapon;
                        renderCreator();
                    });
                    host.appendChild(btn);
                });
            }

            function renderCreatorFactions() {
                const host = document.getElementById('creatorFactions');
                if (!host) return;
                host.innerHTML = '';
                CREATOR_FACTIONS.forEach(f => {
                    const btn = document.createElement('button');
                    btn.className = 'creator-choice' + (creatorSel.faction === f.id ? ' selected' : '');
                    btn.innerHTML = `<span class="cc-name">${f.label}</span><span class="cc-desc">${f.desc}</span>`;
                    btn.addEventListener('click', () => { creatorSel.faction = f.id; renderCreator(); });
                    host.appendChild(btn);
                });
            }

            function renderCreatorWeapons() {
                const host = document.getElementById('creatorWeapons');
                if (!host) return;
                host.innerHTML = '';
                const type = CREATOR_TYPES.find(t => t.id === creatorSel.type);
                const forced = type && type.weapon;
                if (forced) {
                    host.innerHTML = `<div class="creator-placeholder">A droid is assembled around its ` +
                                     `${WEAPON_LIBRARY[forced].label} emitter — ${creatorPlaceName()} will not fit it ` +
                                     `with anything else.</div>`;
                    return;
                }
                CREATOR_WEAPONS.forEach(key => {
                    const w = WEAPON_LIBRARY[key];
                    if (!w) return;
                    const btn = document.createElement('button');
                    btn.className = 'creator-choice' + (creatorSel.weapon === key ? ' selected' : '');
                    btn.innerHTML = `<span class="cc-name">${weaponEmojiFor(key)} ${w.label}</span>
                                     <span class="cc-cost">${Math.round(weaponPowerScore(key))} DPS</span>`;
                    btn.addEventListener('click', () => { creatorSel.weapon = key; renderCreator(); });
                    host.appendChild(btn);
                });
            }

            function creatorStatRow(label, value) {
                return `<div class="apv-row"><span class="apv-label">${label}</span>` +
                       `<span class="apv-from"></span><span class="apv-arrow"></span>` +
                       `<span class="apv-to apv-same">${value}</span></div>`;
            }

            function renderCreatorPreview() {
                const host = document.getElementById('creatorPreview');
                if (!host) return;
                const weapon = creatorResolvedWeapon(creatorSel);
                if (!creatorSel.type || !creatorSel.faction || !weapon) {
                    host.innerHTML = '<div class="creator-placeholder">Choose a nature, an allegiance and a weapon.</div>';
                    return;
                }
                const type = CREATOR_TYPES.find(t => t.id === creatorSel.type);
                const faction = CREATOR_FACTIONS.find(f => f.id === creatorSel.faction);
                const traits = [
                    type.isDroid ? 'Immune to stun &amp; knockdown' : null,
                    type.isDroid ? 'Takes 2× wrench damage' : null,
                    type.isSith ? 'Sith dark aura' : null,
                ].filter(Boolean);
                host.innerHTML =
                    creatorStatRow('Nature', type.label) +
                    creatorStatRow('Allegiance', faction.label) +
                    creatorStatRow('Weapon', `${weaponEmojiFor(weapon)} ${WEAPON_LIBRARY[weapon].label}`) +
                    creatorStatRow('Health', `${creatorSel.hp} HP`) +
                    creatorStatRow('Output', `${Math.round(weaponPowerScore(weapon))} DPS`) +
                    (traits.length ? `<div class="creator-hint" style="margin-top:6px;display:block;">${traits.join(' · ')}</div>` : '') +
                    `<div class="cc-bio">${escapeHtmlText(
                        sanitizeCharBio(creatorSel.bio) || `Fabricated at ${creatorPlaceName()}.`)}</div>`;
            }

            function renderCreator() {
                renderCreatorTypes();
                renderCreatorFactions();
                renderCreatorWeapons();
                renderCreatorPreview();

                const hpValue = document.getElementById('creatorHpValue');
                if (hpValue) hpValue.textContent = `${creatorSel.hp} HP`;

                const bioCount = document.getElementById('creatorBioCount');
                if (bioCount) bioCount.textContent = `${sanitizeCharBio(creatorSel.bio).length} / ${CREATOR_BIO_MAX}`;

                const costEl = document.getElementById('creatorCost');
                const btn = document.getElementById('creatorMakeBtn');
                const nameEl = document.getElementById('creatorNameInput');
                const banner = document.getElementById('creatorEditBanner');
                const cancelBtn = document.getElementById('creatorCancelEditBtn');
                const editing = editingCreationRecord();

                if (banner) {
                    banner.style.display = editing ? 'block' : 'none';
                    if (editing) banner.innerHTML = `Remaking <strong>${editing.name}</strong>. ` +
                        `They keep any forged weapon already assigned to them.`;
                }
                if (cancelBtn) cancelBtn.style.display = editing ? 'inline-block' : 'none';
                if (!costEl || !btn) return;

                const weapon = creatorResolvedWeapon(creatorSel);
                const named = sanitizeCharName(nameEl && nameEl.value).length > 0;
                const complete = !!(creatorSel.type && creatorSel.faction && weapon);
                if (!complete) {
                    costEl.textContent = '—';
                    costEl.classList.remove('unaffordable');
                    btn.disabled = true;
                    btn.textContent = editing ? 'Save changes' : 'Create';
                    return;
                }
                const cost = creationCost(creatorSel);
                // Same settle-the-difference rule as the Armory's rework.
                const delta = editing ? cost - (editing.cost || 0) : cost;
                const affordable = credits >= Math.max(0, delta);

                if (editing) {
                    costEl.textContent = delta === 0 ? `${cost} cr — no change`
                                       : delta > 0  ? `${cost} cr (pay ${delta})`
                                                    : `${cost} cr (refund ${-delta})`;
                } else {
                    costEl.textContent = `${cost} cr`;
                }
                costEl.classList.toggle('unaffordable', !affordable);
                btn.disabled = !affordable || !named;
                btn.textContent = !affordable ? 'Not enough credits'
                                : !named ? 'Name it first'
                                : editing ? 'Save changes' : 'Create';
            }

            function beginEditCreation(id) {
                const rec = createdCharacterRecord(id);
                if (!rec) return;
                creatorSel = {
                    type: rec.type, faction: rec.faction, weapon: rec.weapon,
                    hp: rec.hp, color: rec.color, bio: rec.bio || '', editingId: rec.id
                };
                const nameEl = document.getElementById('creatorNameInput');
                if (nameEl) nameEl.value = rec.name;
                const bioEl = document.getElementById('creatorBioInput');
                if (bioEl) bioEl.value = rec.bio || '';
                const hpSlider = document.getElementById('creatorHpSlider');
                if (hpSlider) hpSlider.value = rec.hp;
                const colorEl = document.getElementById('creatorColorInput');
                if (colorEl) colorEl.value = rec.color;
                setCreatorTab('make');
                renderCreator();
            }

            function cancelCreationEdit() {
                creatorSel = { type: null, faction: null, weapon: null, hp: 140, color: '#8fbcff', bio: '', editingId: null };
                const nameEl = document.getElementById('creatorNameInput');
                if (nameEl) nameEl.value = '';
                const bioEl = document.getElementById('creatorBioInput'); if (bioEl) bioEl.value = '';
                const hpSlider = document.getElementById('creatorHpSlider');
                if (hpSlider) hpSlider.value = 140;
                const colorEl = document.getElementById('creatorColorInput');
                if (colorEl) colorEl.value = creatorSel.color;
                renderCreator();
            }

            function createCharacter() {
                const weapon = creatorResolvedWeapon(creatorSel);
                if (!creatorSel.type || !creatorSel.faction || !weapon) return;
                const nameEl = document.getElementById('creatorNameInput');
                const name = sanitizeCharName(nameEl && nameEl.value);
                if (!name) return;
                // Optional — an empty bio is stored as empty and the roster entry
                // falls back to the house line at compile time.
                const bioEl = document.getElementById('creatorBioInput');
                const bio = sanitizeCharBio(bioEl && bioEl.value);
                const cost = creationCost(creatorSel);
                const editing = editingCreationRecord();
                const delta = editing ? cost - (editing.cost || 0) : cost;
                if (credits < Math.max(0, delta)) return;

                const type = CREATOR_TYPES.find(t => t.id === creatorSel.type);
                // A Sith creation gets a red blade by default; everyone else's
                // blade matches their own colour.
                const saberColor = type.isSith ? '#ff2222' : creatorSel.color;

                let rec;
                if (editing) {
                    // Mutated in place so the id survives — equippedForged, the
                    // favourites set and match history all key off it.
                    rec = editing;
                    Object.assign(rec, {
                        name, bio, type: creatorSel.type, faction: creatorSel.faction,
                        weapon, hp: creatorSel.hp, color: creatorSel.color,
                        saberColor, cost, remadeAt: new Date().toISOString()
                    });
                } else {
                    rec = {
                        // Namespaced so a creation's id can never collide with a
                        // shipped character's, which the roster looks up by id.
                        id: 'zp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
                        name,
                        bio,
                        type: creatorSel.type,
                        faction: creatorSel.faction,
                        weapon,
                        hp: creatorSel.hp,
                        color: creatorSel.color,
                        saberColor,
                        cost,
                        createdAt: new Date().toISOString()
                    };
                    createdCharacters.push(rec);
                }

                credits -= delta;
                applyCreatedCharacters();
                saveCreatedCharacters();
                saveGameSettings();
                updateCreditsDisplay();
                rebuildAllRosters();

                const wasEditing = !!editing;
                creatorSel = { type: null, faction: null, weapon: null, hp: 140, color: creatorSel.color, bio: '', editingId: null };
                if (nameEl) nameEl.value = '';
                if (bioEl) bioEl.value = '';
                const hpSlider = document.getElementById('creatorHpSlider');
                if (hpSlider) hpSlider.value = 140;
                renderCreator();
                renderCreatorRoster();
                setCreatorTab('roster');
                if (wasEditing) {
                    showAnnouncement(`${creatorPlaceNameCap()} reshapes ${rec.name}.`, '#8fbcff', 3500, '✨ REMADE', 100);
                } else {
                    showAnnouncement(`${creatorPlaceNameCap()} gives form to ${rec.name}.`, '#8fbcff', 4000, '✨ CREATED', 100);
                }
            }

            function deleteCreatedCharacter(id) {
                const idx = createdCharacters.findIndex(r => r.id === id);
                if (idx === -1) return;
                const rec = createdCharacters[idx];
                const refund = Math.floor((rec.cost || 0) * CREATOR_REFUND_RATE);

                createdCharacters.splice(idx, 1);
                // Anything the Armory had assigned to them goes back on the rack
                // rather than pointing at a character that no longer exists.
                if (equippedForged[id]) { delete equippedForged[id]; saveArmory(); }
                // Unmaking whoever is loaded in the form would leave it editing
                // a character the Zero Point no longer holds.
                if (creatorSel.editingId === id) {
                    creatorSel = { type: null, faction: null, weapon: null, hp: 140, color: '#8fbcff', bio: '', editingId: null };
                    const nameEl = document.getElementById('creatorNameInput');
                    if (nameEl) nameEl.value = '';
                    const bioEl = document.getElementById('creatorBioInput'); if (bioEl) bioEl.value = '';
                }
                credits += refund;
                applyCreatedCharacters();
                saveCreatedCharacters();
                saveGameSettings();
                updateCreditsDisplay();
                renderCreatorRoster();
                renderCreator();
                rebuildAllRosters();
                showAnnouncement(`${rec.name} returns to ${creatorPlaceName()}. ${refund} credits recovered.`,
                                 '#cc7777', 3000, '✨ UNMADE', 90);
            }

            function renderCreatorRoster() {
                const host = document.getElementById('creatorRoster');
                const countEl = document.getElementById('creatorRosterCount');
                if (countEl) countEl.textContent = createdCharacters.length ? `(${createdCharacters.length})` : '';
                if (!host) return;
                host.innerHTML = '';
                if (!createdCharacters.length) {
                    host.innerHTML = '<div class="creator-placeholder">Nothing has been made here yet.</div>';
                    return;
                }
                createdCharacters.forEach(rec => {
                    const type = CREATOR_TYPES.find(t => t.id === rec.type) || CREATOR_TYPES[0];
                    const faction = CREATOR_FACTIONS.find(f => f.id === rec.faction) || CREATOR_FACTIONS[0];
                    const carried = equippedForged[rec.id] && WEAPON_LIBRARY['forged:' + equippedForged[rec.id]];

                    const el = document.createElement('div');
                    el.className = 'creator-made';
                    el.style.borderLeftColor = rec.color;
                    el.innerHTML = `
                        <div class="creator-made-head">
                            <div>
                                <div class="creator-made-name" style="color:${rec.color}">${weaponEmojiFor(rec.weapon)} ${rec.name}</div>
                                <div class="creator-made-sub">${type.label} · ${faction.label}</div>
                            </div>
                        </div>
                        <div>
                            ${creatorStatRow('Health', rec.hp + ' HP')}
                            ${creatorStatRow('Weapon', carried ? carried.label + ' (forged)' : WEAPON_LIBRARY[rec.weapon]?.label || rec.weapon)}
                        </div>
                        ${rec.bio ? `<div class="cc-bio">${escapeHtmlText(rec.bio)}</div>` : ''}`;

                    const actions = document.createElement('div');
                    actions.className = 'creator-made-actions';
                    const edit = document.createElement('button');
                    edit.className = 'edit-btn';
                    edit.textContent = 'Edit';
                    edit.addEventListener('click', () => beginEditCreation(rec.id));
                    actions.appendChild(edit);
                    const del = document.createElement('button');
                    del.className = 'creator-unmake-btn';
                    del.textContent = `Unmake (+${Math.floor((rec.cost || 0) * CREATOR_REFUND_RATE)} cr)`;
                    del.addEventListener('click', () => deleteCreatedCharacter(rec.id));
                    actions.appendChild(del);
                    el.appendChild(actions);
                    host.appendChild(el);
                });
            }

            /** Is there anybody to customize? Both fighters are optional and neither
             *  is bought the same way — the mech is a purchase, Wrixel is what
             *  clearing the Zero Event leaves behind — so the tab appears for either
             *  and disappears for neither. */
            function anyCustomizableUnlocked() {
                return wrixelUnlocked() || guardianUnlocked();
            }

            /** Which fighter's panel is open inside Character Customization. Kept
             *  across opens of the creator, so a player who was last in Wrixel's
             *  blocks comes back to them. */
            let creatorCustomSubTab = 'wrixel';

            function setCreatorSubTab(which) {
                // Fall through to whichever is actually owned. Asking for a panel
                // whose fighter is not on the roster shows the other one rather than
                // an empty body under a hidden button.
                if (which === 'wrixel' && !wrixelUnlocked()) which = 'guardian';
                if (which === 'guardian' && !guardianUnlocked()) which = 'wrixel';
                creatorCustomSubTab = which;

                document.querySelectorAll('.creator-subtab').forEach(b => {
                    b.classList.toggle('active', b.dataset.subtab === which);
                });
                const wrixelPanel = document.getElementById('creatorWrixelPanel');
                const guardianPanel = document.getElementById('creatorGuardianPanel');
                if (wrixelPanel)   wrixelPanel.style.display   = which === 'wrixel'   && wrixelUnlocked()   ? 'flex' : 'none';
                if (guardianPanel) guardianPanel.style.display = which === 'guardian' && guardianUnlocked() ? 'flex' : 'none';
            }

            function setCreatorTab(tab) {
                // Character Customization only exists while somebody can be
                // customized. A save that owns neither (or loses both to Clear All
                // Data with the panel open) falls back to Create rather than showing
                // a body whose tab button is hidden.
                if (tab === 'custom' && !anyCustomizableUnlocked()) tab = 'make';
                document.querySelectorAll('.creator-tab').forEach(b => {
                    b.classList.toggle('active', b.dataset.tab === tab);
                });
                const makeBody = document.getElementById('creatorMakeTab');
                const rosterBody = document.getElementById('creatorRosterTab');
                const customBody = document.getElementById('creatorCustomTab');
                const makeRow = document.getElementById('creatorMakeRow');
                if (makeBody)     makeBody.style.display     = tab === 'make'     ? 'flex' : 'none';
                if (rosterBody)   rosterBody.style.display   = tab === 'roster'   ? 'flex' : 'none';
                if (customBody)   customBody.style.display   = tab === 'custom'   ? 'flex' : 'none';
                // The cost/Create row belongs to the Create form alone — the other
                // two tabs make nothing and charge nothing.
                if (makeRow)      makeRow.style.display      = tab === 'make'     ? 'flex' : 'none';
                if (tab === 'custom') setCreatorSubTab(creatorCustomSubTab);
            }

            /*  The screen answers to whichever door is still standing. Before the
             *  Snap it is The Zero Point; afterwards that tile is gone and Kamino
             *  is the only way in, so wearing the old name would be a dead
             *  signpost. Everything below the header is shared — same builder,
             *  same galacticDuelCreations record, same creations listed.        */
            function applyCreatorBranding() {
                const kamino = snapHasHappened();
                const title = document.getElementById('creatorTitle');
                const quote = document.getElementById('creatorQuote');
                if (title) title.textContent = kamino ? '\u2601 KAMINO' : 'THE ZERO POINT';
                if (title) title.style.color = kamino ? '#a8d8ff' : '#8fbcff';
                if (quote) {
                    quote.innerHTML = kamino
                        ? '"The cloners of Kamino take a template and make an army of it."<br>' +
                          'The Zero Point is gone. Its work carried here intact \u2014 everything you built is below, and Kamino will keep building.'
                        : '"In the beginning there was Nothing. Then, in a burst of pure creation, the Zero Point sprang into being."<br>' +
                          'It can fabricate new souls and new lifeforms. Tell it what to make.';
                }
            }

            function openCreator() {
                applyCreatorBranding();
                creatorSel = { type: null, faction: null, weapon: null, hp: 140, color: '#8fbcff', bio: '', editingId: null };
                const nameEl = document.getElementById('creatorNameInput');
                if (nameEl) nameEl.value = '';
                const bioEl = document.getElementById('creatorBioInput'); if (bioEl) bioEl.value = '';
                const hpSlider = document.getElementById('creatorHpSlider');
                if (hpSlider) hpSlider.value = 140;
                const colorEl = document.getElementById('creatorColorInput');
                if (colorEl) colorEl.value = creatorSel.color;
                updateCreditsDisplay();
                renderCreator();
                renderCreatorRoster();
                // Rebuilt on every open rather than at purchase time: this is the one
                // way into the panel, so it is the one place the tab can appear.
                updateCustomizationTabVisibility();
                renderWrixelCustomization();
                renderGuardianCustomization();
                setCreatorTab('make');
                if (creatorOverlay) creatorOverlay.style.display = 'flex';
            }

            document.querySelectorAll('.creator-tab').forEach(b => {
                b.addEventListener('click', () => setCreatorTab(b.dataset.tab));
            });
            document.querySelectorAll('.creator-subtab').forEach(b => {
                // The reset button borrows the sub-tab's styling and is not one, so
                // it must not be wired up as one.
                if (!b.dataset.subtab) return;
                b.addEventListener('click', () => setCreatorSubTab(b.dataset.subtab));
            });
            const wrixelColorInput = document.getElementById('wrixelColorInput');
            // 'input' rather than 'change': the roster swatch and the preview follow
            // the picker while it is being dragged, which is how the Create tab's
            // colour step behaves one panel over.
            if (wrixelColorInput) wrixelColorInput.addEventListener('input', () => {
                setWrixelColor(wrixelColorInput.value);
            });
            const wrixelColorResetBtn = document.getElementById('wrixelColorResetBtn');
            if (wrixelColorResetBtn) wrixelColorResetBtn.addEventListener('click', () => {
                setWrixelColor(null);
            });
            const creatorNameInput = document.getElementById('creatorNameInput');
            if (creatorNameInput) creatorNameInput.addEventListener('input', renderCreator);
            const creatorBioInput = document.getElementById('creatorBioInput');
            if (creatorBioInput) creatorBioInput.addEventListener('input', () => {
                creatorSel.bio = creatorBioInput.value;
                renderCreator();
            });
            const creatorHpSlider = document.getElementById('creatorHpSlider');
            if (creatorHpSlider) creatorHpSlider.addEventListener('input', () => {
                creatorSel.hp = parseInt(creatorHpSlider.value, 10) || CREATOR_BASE_HP;
                renderCreator();
            });
            const creatorColorInput = document.getElementById('creatorColorInput');
            if (creatorColorInput) creatorColorInput.addEventListener('input', () => {
                creatorSel.color = creatorColorInput.value;
                renderCreator();
            });
            const creatorMakeBtn = document.getElementById('creatorMakeBtn');
            if (creatorMakeBtn) creatorMakeBtn.addEventListener('click', createCharacter);
            const creatorCancelEditBtn = document.getElementById('creatorCancelEditBtn');
            if (creatorCancelEditBtn) creatorCancelEditBtn.addEventListener('click', cancelCreationEdit);
            const creatorCloseBtn = document.getElementById('creatorCloseBtn');
            if (creatorCloseBtn) creatorCloseBtn.addEventListener('click', () => {
                if (creatorOverlay) creatorOverlay.style.display = 'none';
                refreshSplashState();   // the created-fighter count on the tile
            });
            if (creatorOverlay) creatorOverlay.addEventListener('click', (e) => {
                if (e.target === creatorOverlay) creatorOverlay.style.display = 'none';
            });
            /** What the fighter-building screen is called at this moment. The
             *  Snap retires The Zero Point and hands its work to Kamino, so every
             *  line the screen says about itself has to follow the door that is
             *  actually standing. */
            function creatorPlaceName() { return snapHasHappened() ? 'Kamino' : 'the Zero Point'; }
            function creatorPlaceNameCap() { return snapHasHappened() ? 'Kamino' : 'The Zero Point'; }

            /** Has the Snap already retired the Zero Point and the Zero Event?
             *  Read from the intro's own flag so there is one source of truth for
             *  whether those two screens still exist. */
            function snapHasHappened() {
                try { return localStorage.getItem('gl-snap-intro') === '1'; } catch (e) { return false; }
            }

            /*  VAULTED: THE SNAP INTRO. Thanos no longer walks onto the splash on
             *  his own. A save that has never seen him opens to the menu the Snap
             *  leaves behind (Kamino in the slot, the Zero Point tile and arena
             *  gone) with none of the sequence, which is exactly what reduced motion
             *  already gave the players who asked for less movement. snap-intro.js
             *  is untouched apart from offering that road as SnapIntro.skip().
             *
             *  It is still in the game, just not on by itself: the THANOS redeem code
             *  and the dev menu's Play Snap Cutscene both run it from the top through
             *  replaySnapIntro(). The season card that used to follow it is vaulted
             *  separately (SEASON_CARD_VAULTED).
             *
             *  Flip to false to bring the automatic showing back. It only reaches a
             *  save that has not loaded while this was true: skipping still marks
             *  the Snap as having happened, because snapHasHappened() is what
             *  retires the Zero Point arena and renames the creator Kamino, and a
             *  menu showing Kamino over a creator titled The Zero Point would be
             *  two menus at once.                                                */
            const SNAP_INTRO_VAULTED = true;

            /** The splash is on screen: offer the Snap, or settle straight to its
             *  end state while it is vaulted. Every automatic showing comes through
             *  here (boot, the loading screen lifting, every return to the splash),
             *  which is what makes this the vault's one point of use. */
            function offerSnapIntro() {
                if (!window.SnapIntro) return;
                if (SNAP_INTRO_VAULTED && typeof window.SnapIntro.skip === 'function') {
                    window.SnapIntro.skip();
                    return;
                }
                window.SnapIntro.maybePlay();
            }

            /** Plays the Snap from the top, on request. SnapIntro.play() resets its
             *  own state first, so this is a true replay rather than a second
             *  showing stacked on the first, and it ignores the vault — asking for
             *  it is the point. The intro mounts inside #splashMenu and animates the
             *  tiles there, so it goes back to the splash and gives it one frame to
             *  be on screen before it is measured. Returns false when the intro
             *  script is not loaded, so each caller can say so in its own words. */
            function replaySnapIntro() {
                if (!window.SnapIntro || typeof window.SnapIntro.play !== 'function') return false;
                showSplashMenu();
                requestAnimationFrame(() => window.SnapIntro.play());
                return true;
            }

            /*  The Zero Point tile has no handler on purpose. It is scenery for
             *  the Snap and nothing else now: Kamino opens the creator, and this
             *  tile exists to be disintegrated in front of the player.
             *
             *  It was already unreachable from both ends before the handler came
             *  off — snap-intro.js swallows every splash click in the capture
             *  phase while the Snap is owed, and afterwards the tile is hidden. */

            // ══════════════════════════════════════════════════════════════
            // GUARDIAN CUSTOMIZATION
            // ══════════════════════════════════════════════════════════════
            //
            // The Guardian is a mech with a sprite in the cockpit, and this is where
            // the player says which sprite. It sits under Character Customization on
            // the Zero Point rather than in a panel of its own because the Zero Point
            // is already the place a fighter's body is decided — the difference is
            // that this one ships whole and only its plating is up for discussion.
            // Its sub-button does not exist until the mech is bought (see
            // updateCustomizationTabVisibility).
            //
            // Cosmetic, and that word is load-bearing. Fitting a sprite repaints the
            // chassis and lights it up; it does nothing else. No splash, no stat, no
            // reach, no advantage of any kind — and it does not equip the sprite
            // either, so Boom Boom fitted to the mech is still sitting unequipped in
            // the inventory unless it is also equipped in Settings ▸ Sprites.
            //
            // The plating shows on The Guardian whoever is fighting as it, the
            // player or the opponent. It is paint on a character rather than a
            // loadout on a fighter, and one mech that looks like two depending on
            // which side of the arena it spawned on would be the stranger rule.
            const GUARDIAN_CHAR_ID = 'guardian';
            const GUARDIAN_BASE_COLOR = '#4d8bf0';

            // What a fitted sprite does to the chassis. `aura` names the effect
            // drawGuardianSkinAura() paints around the mech; a sprite listed without
            // one is a repaint and nothing more, and a sprite with no entry here at
            // all is still wearable — it falls back to its rarity colour, so a sprite
            // added to the catalog tomorrow is plating on the day it ships.
            const GUARDIAN_SKINS = {
                boomBoom: {
                    color: '#ff9a3c',
                    name: 'Blast plating',
                    desc: 'Cobalt goes blast orange and the shockwave a detonation throws pulses off the plating on a loop. The shape of splash damage with none of the splash damage — nothing standing beside it takes a point.',
                    aura: 'blast'
                }
            };

            function guardianUnlocked() {
                return !!gameUnlocks.guardian;
            }

            // ══════════════════════════════════════════════════════════════
            // WRIXEL CUSTOMIZATION
            // ══════════════════════════════════════════════════════════════
            //
            // He is a colour. That is the whole feature: pick one, and it is the
            // colour he is — on the roster grid, on his stat card, in the opponent
            // picker and on the field, because all four read char.color and this
            // writes to the roster entry itself.
            //
            // Deliberately a colour well rather than a list of named sets. Named
            // sets would be the same thing wearing a costume: eight fixed colours
            // dressed up as materials, with descriptions implying they are made of
            // something. They are not. The Create tab next door already picks a
            // fighter's colour with exactly this control, and Wrixel is the one
            // fighter on the roster who works the same way.
            //
            // Nothing else changes. Obsidian-dark Wrixel takes damage exactly as
            // grass-green Wrixel does.
            const WRIXEL_CHAR_ID = 'wrixel';
            const WRIXEL_BASE_COLOR = '#63c74d';

            function wrixelUnlocked() {
                return !!gameUnlocks.wrixel;
            }

            /** A colour the game is willing to paint with, or null for the default.
             *  Anything that is not a six-digit hex is treated as no choice at all —
             *  the input element only ever produces that shape, but the save is a
             *  file on disk and a colour is written straight into inline styles. */
            function normalizeWrixelColor(value) {
                if (typeof value !== 'string') return null;
                const hex = value.trim().toLowerCase();
                if (!/^#[0-9a-f]{6}$/.test(hex)) return null;
                return hex === WRIXEL_BASE_COLOR ? null : hex;
            }

            /** The chosen colour, or null when he is still the green he arrived in. */
            function activeWrixelColor() {
                return normalizeWrixelColor(wrixelColor);
            }

            function wrixelDisplayColor() {
                return activeWrixelColor() || WRIXEL_BASE_COLOR;
            }

            /** Paints the roster entry, which is what puts the colour everywhere at
             *  once. Exactly how applyGuardianSkin() works, and for the same reason. */
            function applyWrixelColor() {
                const entry = characters.secret.find(c => c.id === WRIXEL_CHAR_ID);
                if (!entry) return;
                entry.color = wrixelDisplayColor();
            }

            function setWrixelColor(value) {
                if (!wrixelUnlocked()) return;
                const next = normalizeWrixelColor(value);
                if (next === activeWrixelColor()) return;
                wrixelColor = next;
                applyWrixelColor();
                saveGameSettings();
                renderWrixelCustomization();
                // The roster button carries the character's colour, so the swatch on
                // the select screen changes with him.
                rebuildAllRosters();
            }

            function renderWrixelCustomization() {
                const input = document.getElementById('wrixelColorInput');
                const preview = document.getElementById('wrixelColorPreview');
                const color = wrixelDisplayColor();

                // Only written when it differs: setting .value on a colour input the
                // player is currently dragging would fight them for the picker.
                if (input && input.value.toLowerCase() !== color) input.value = color;

                if (preview) {
                    preview.innerHTML =
                        creatorStatRow('Colour', `<span style="color:${color}">${escapeHtmlText(color.toUpperCase())}</span>`) +
                        creatorStatRow('Weapon', 'Assault Rifle') +
                        creatorStatRow('Combat', 'Unchanged') +
                        '<div class="creator-hint" style="margin-top:6px;display:block;">' +
                        'Colour only — it changes nothing about how he fights.</div>' +
                        '<div class="cc-bio">Be the blocks you wish to see in the world.</div>';
                }
            }

            function guardianSkinChoices() {
                return SPRITE_CATALOG.filter(s => spriteEverOwned(s.id));
            }

            function guardianSkinDef(spriteId) {
                return (spriteId && GUARDIAN_SKINS[spriteId]) || null;
            }

            function guardianSkinColor(spriteId) {
                const skin = guardianSkinDef(spriteId);
                if (skin && skin.color) return skin.color;
                const sprite = getSprite(spriteId);
                return sprite ? spriteRarity(sprite).color : GUARDIAN_BASE_COLOR;
            }

            /** The fitted skin, or null for factory cobalt. Re-asks the inventory
             *  every time rather than trusting the stored id, so plating from a
             *  sprite that is not in the save's history never reaches the field. */
            function activeGuardianSkinId() {
                return guardianSkinSpriteId && spriteEverOwned(guardianSkinSpriteId)
                    ? guardianSkinSpriteId : null;
            }

            /** Paints the roster entry itself, which is what puts the skin
             *  everywhere at once: the roster grid, the stat card, the opponent
             *  picker and the fighter on the field all read char.color, so there is
             *  one thing to keep in step rather than four. Fighters already on the
             *  field keep the colour they spawned with — this is only reachable from
             *  a menu, so there are none. */
            function applyGuardianSkin() {
                const entry = characters.secret.find(c => c.id === GUARDIAN_CHAR_ID);
                if (!entry) return;
                const id = activeGuardianSkinId();
                entry.color = id ? guardianSkinColor(id) : GUARDIAN_BASE_COLOR;
            }

            function setGuardianSkin(spriteId) {
                if (!guardianUnlocked()) return;   // no mech, nothing to paint
                const id = spriteId && spriteEverOwned(spriteId) ? spriteId : null;
                if (id === activeGuardianSkinId()) return;
                guardianSkinSpriteId = id;
                applyGuardianSkin();
                saveGameSettings();
                renderGuardianCustomization();
                // The roster button carries the character's colour, so the swatch on
                // the select screen changes with the mech.
                rebuildAllRosters();

                if (id) {
                    const sprite = getSprite(id);
                    const skin = guardianSkinDef(id);
                    showAnnouncement(
                        `${sprite.name} plating fitted to The Guardian. ${skin ? skin.name : 'The paint'} is cosmetic — it fights exactly as it did.`,
                        guardianSkinColor(id), 3500, '🤖 GUARDIAN', 90);
                } else {
                    showAnnouncement('The Guardian goes back to factory plating.',
                        GUARDIAN_BASE_COLOR, 3000, '🤖 GUARDIAN', 90);
                }
            }

            function guardianSkinButton(sprite, activeId) {
                const id = sprite ? sprite.id : null;
                const btn = document.createElement('button');
                btn.className = 'creator-choice' + (activeId === id ? ' selected' : '');
                if (sprite) {
                    const skin = guardianSkinDef(id);
                    const color = guardianSkinColor(id);
                    const held = playerOwnsSprite(id);
                    btn.innerHTML =
                        `<span class="cc-name">${sprite.icon} ${escapeHtmlText(sprite.name)}</span>` +
                        `<span class="cc-desc">${escapeHtmlText(skin ? skin.desc
                            : "Repaints the chassis in this sprite's colour.")}</span> ` +
                        `<span class="cc-cost" style="color:${color}">` +
                        `${escapeHtmlText(skin ? skin.name : spriteRarity(sprite).label + ' plating')}` +
                        `${held ? '' : ' · lost, plating kept'}</span>`;
                } else {
                    btn.innerHTML =
                        `<span class="cc-name">🛡️ Factory plating</span>` +
                        `<span class="cc-desc">Cobalt, as the mech left the assembly line. No sprite fitted.</span>`;
                }
                btn.addEventListener('click', () => setGuardianSkin(id));
                return btn;
            }

            function renderGuardianCustomization() {
                const host = document.getElementById('guardianSkinChoices');
                const preview = document.getElementById('guardianSkinPreview');
                const activeId = activeGuardianSkinId();

                if (host) {
                    host.innerHTML = '';
                    const choices = guardianSkinChoices();
                    if (!choices.length) {
                        // Deliberately not phrased as a purchase: sprites are found in
                        // battle, and the Shop only ever sells one back after a defeat.
                        host.innerHTML = '<div class="creator-placeholder">You have never carried a sprite. ' +
                            'Find one on the battlefield and its plating turns up here — and stays here, ' +
                            'whatever becomes of the sprite afterwards.</div>';
                    } else {
                        host.appendChild(guardianSkinButton(null, activeId));
                        choices.forEach(s => host.appendChild(guardianSkinButton(s, activeId)));
                    }
                }

                if (preview) {
                    const skin = guardianSkinDef(activeId);
                    const sprite = activeId ? getSprite(activeId) : null;
                    const color = activeId ? guardianSkinColor(activeId) : GUARDIAN_BASE_COLOR;
                    preview.innerHTML =
                        creatorStatRow('Chassis', `<span style="color:${color}">` +
                            `${sprite ? escapeHtmlText(sprite.name) + ' plating' : 'Factory cobalt'}</span>`) +
                        // Kept short: .apv-to is nowrap, and a sentence in that column
                        // would run off the side of the panel.
                        creatorStatRow('Effect', skin && skin.aura === 'blast' ? 'Pulsing blast wave' : 'None') +
                        creatorStatRow('Combat', 'Unchanged') +
                        '<div class="creator-hint" style="margin-top:6px;display:block;">' +
                        'Cosmetic only — the plating deals no damage and carries none of the sprite&rsquo;s power.</div>' +
                        '<div class="cc-bio">One small Sprite. One big mech.</div>';
                }
            }

            /** The tab, and the two buttons inside it. Rebuilt on every open of the
             *  creator rather than at the moment either fighter is acquired: this is
             *  the one way into the panel, so it is the one place any of it can
             *  appear. */
            function updateCustomizationTabVisibility() {
                const tabBtn = document.getElementById('creatorCustomTabBtn');
                if (tabBtn) tabBtn.style.display = anyCustomizableUnlocked() ? '' : 'none';

                const wrixelBtn = document.getElementById('creatorWrixelSubBtn');
                if (wrixelBtn) wrixelBtn.style.display = wrixelUnlocked() ? '' : 'none';
                const guardianBtn = document.getElementById('creatorGuardianSubBtn');
                if (guardianBtn) guardianBtn.style.display = guardianUnlocked() ? '' : 'none';

                // The row of sub-buttons is worth nothing when there is only one of
                // them: a single button that cannot be switched away from is a label
                // pretending to be a control.
                const row = document.querySelector('.creator-subtabs');
                if (row) row.style.display = (wrixelUnlocked() && guardianUnlocked()) ? 'flex' : 'none';
            }

            // Gates firing for weapons that carry a magazine (magSize set, e.g. Lancehead Pistol).
            // Finishes an in-progress reload once its timer elapses, and force-starts a
            // reload (auto — covers AI, who can't press R) the instant the mag hits empty.
            // Returns true if the entity is clear to fire this frame.
            function canFireWeapon(e, now) {
                if (e.weaponConfig.magSize == null) return true;
                if (e.isReloading) {
                    if (now >= e.reloadEndsAt) {
                        e.isReloading = false;
                        e.magAmmo = e.weaponConfig.magSize;
                    } else {
                        return false;
                    }
                }
                if (e.magAmmo <= 0) {
                    e.isReloading = true;
                    e.reloadEndsAt = now + e.weaponConfig.reloadMs;
                    return false;
                }
                return true;
            }

            // ── RELOADING ──────────────────────────────────────────────
            // Advances an in-progress reload for *any* entity, whoever owns it.
            // Firing used to be the only thing that could finish one — the check
            // lived inside canFireWeapon() and the player's input block — so an AI
            // that ran dry and then lost sight of its target sat mid-reload
            // indefinitely, finishing the instant it next pulled the trigger. Now
            // that the opponent's magazine is on the HUD that stall would be
            // visible, so the timer runs every frame for everyone.
            function tickReload(e, now) {
                if (!e.isReloading) return;
                if (now >= e.reloadEndsAt) {
                    e.isReloading = false;
                    e.magAmmo = e.weaponConfig.magSize;
                }
            }

            /** Starts a reload when one is worth starting. A dry magazine always
             *  reloads; a partial one only when `isSafeNow()` says this is a lull —
             *  no line of fire, or the target still out of range — which is the
             *  moment a decent player tops up rather than walking into the next
             *  opening with three rounds left. The predicate is a function so its
             *  line-of-fire raycast is only paid for on the frames that need it. */
            function beginReloadIfNeeded(e, now, isSafeNow) {
                const cfg = e.weaponConfig;
                if (!cfg || cfg.magSize == null || e.magAmmo == null) return;
                if (e.isReloading || e.magAmmo >= cfg.magSize) return;
                const lowMag = e.magAmmo <= Math.max(1, Math.ceil(cfg.magSize * 0.3));
                if (!lowMag) return;
                if (e.magAmmo > 0 && !isSafeNow()) return;
                e.isReloading = true;
                e.reloadEndsAt = now + cfg.reloadMs;
            }

            // ── AMMO BOOST ─────────────────────────────────────────────
            // The Ammo pickup used to set the cooldown to 0 for every weapon.
            // A cooldown of 0 passes the fire gate on every frame, so a boosted
            // gun fired once per rendered frame, and how hard it hit depended on
            // the monitor: a Sniper went from 51 DPS to about 2,900 at 60 Hz, a
            // Reality Staff rolled sixty times a second (a certain kill), and
            // the AI goes out of its way to collect the pickup, so the player
            // was usually the one on the end of it.
            //
            // Now it halves a gun's cooldown, which doubles its rate of fire for
            // the four seconds — still the best pickup on the floor for a
            // shooter, and still more for a fast gun than a slow one in absolute
            // terms, but never past one shot per AMMO_BOOST_MIN_COOLDOWN. A
            // weapon already faster than the floor (the Beam) keeps its own.
            //
            // Melee keeps the old 0: meleeSwingCooldown() already floors swings
            // at MELEE_SWING_MIN_COOLDOWN and the swing commitment sits on top of
            // that, so blades were never the problem and their boost is unchanged.
            const AMMO_BOOST_COOLDOWN_MULT = 0.5;
            const AMMO_BOOST_MIN_COOLDOWN = 40;   // ms — 25 shots a second, at any frame rate

            function ammoBoostedCooldown(weaponConfig, boosted) {
                const base = weaponConfig.cooldown;
                if (!boosted) return base;
                if (weaponConfig.melee) return 0;
                return Math.min(base, Math.max(base * AMMO_BOOST_COOLDOWN_MULT, AMMO_BOOST_MIN_COOLDOWN));
            }

            // ── BURST FIRE ─────────────────────────────────────────────
            // A burst weapon fires `burst` rounds per group: rounds inside the
            // group are burstDelay apart, and after the last one the weapon sits
            // out its full cooldown. Rather than queueing the remaining rounds
            // and spawning them from a second code path, the *gate between two
            // shots* is shortened while a group is in progress — so bursts fall
            // out of the firing loops every path already runs (player, AI, ammo
            // boost, magazine, reload) with no duplicated projectile spawning.
            //
            // Returns the cooldown to use for the next shot, and is safe to call
            // every frame for any weapon: a non-burst weapon gets its cooldown
            // back untouched.
            function burstAwareCooldown(e, baseCooldown, now) {
                const burst = e.weaponConfig.burst;
                if (!burst || burst < 2) return baseCooldown;
                // A group that goes quiet for longer than the full cooldown was
                // abandoned mid-burst (trigger released, target lost, reload) —
                // the next shot opens a fresh group rather than resuming.
                if (now - e.lastShotTime > baseCooldown) e.burstShot = 0;
                return e.burstShot > 0 && e.burstShot < burst ? e.weaponConfig.burstDelay : baseCooldown;
            }

            // ── FOCUSING SPREAD ────────────────────────────────────────
            // The Extending Focus Shotgun's pellet spread narrows the longer it is
            // fired without a break and springs back open once the shooter stops.
            // Same shape as burstAwareCooldown() above: the count of consecutive
            // shots lives on the entity, and the value every firing path already
            // asks for — here the spread arc — is derived from it.
            //
            // Returns the arc to fire this shot at; a weapon without focusStep gets
            // its plain multishotArc back.
            function focusedArc(e, weaponConfig, now) {
                const base = weaponConfig.multishotArc || 0.3;
                if (!weaponConfig.focusStep) return base;
                // Shots further apart than a couple of cooldowns are not continuous
                // fire — that includes anything with a reload in the middle.
                if (now - e.lastShotTime > weaponConfig.cooldown * 2) e.focusShots = 0;
                const t = Math.min(1, (e.focusShots || 0) * weaponConfig.focusStep);
                return base + (weaponConfig.focusMinArc - base) * t;
            }

            // Every ranged firing path records its shot here instead of assigning
            // lastShotTime directly, so burst weapons advance through their group
            // and focusing weapons tighten up.
            function noteShotFired(e, now) {
                e.lastShotTime = now;
                if (e.weaponConfig.burst > 1) e.burstShot = (e.burstShot || 0) + 1;
                if (e.weaponConfig.focusStep) e.focusShots = (e.focusShots || 0) + 1;
            }

            // ── DROID SIDEARMS ─────────────────────────────────────────
            // The Separatist combat droids are built on the `zap` weapon — that
            // stun-bolt crackle is their signature — but they carry blasters too,
            // and only ever got to use one of the two. These entries give them
            // both barrels: zap stays on the primary trigger, the blaster goes on
            // the secondary one.
            //
            // Only combat droids belong here. R2-D2, C-3PO, BB-8 and Sith C-3PO
            // are also on `zap` and are deliberately left off — none of them
            // carries a blaster.
            //
            // Player-only for now: the AI still fights with its primary alone, so
            // adding a droid here does not silently buff every enemy that uses it.
            const DROID_SIDEARMS = {
                b1droid:    'blaster',
                superdroid: 'blaster',
                droideka:   'blaster'
            };

            function getSidearmKey(characterId) {
                return DROID_SIDEARMS[characterId] || null;
            }

            /** The secondary weapon config for an entity, or null if it has none. */
            function getSidearmConfig(entity) {
                const key = entity && getSidearmKey(entity.characterId);
                return key ? (WEAPON_LIBRARY[key] || null) : null;
            }

            /** HUD weapon name — "ZAP / BLASTER" for anything carrying a sidearm. */
            function weaponLabelFor(charData) {
                const primary = getWeapon(charData).label;
                const key = charData && getSidearmKey(charData.id);
                if (!key) return primary.toUpperCase();
                const secondary = WEAPON_LIBRARY[key] ? WEAPON_LIBRARY[key].label : key;
                return `${primary} / ${secondary}`.toUpperCase();
            }

            // ── TACTICAL AI PROFILES ───────────────────────────────────
            // Each profile shapes HOW an AI-controlled entity fights: how close it
            // wants to be to its target (minRange/maxRange define the "comfortable"
            // engagement band — below minRange it backs off, above maxRange it
            // closes in, and between the two it strafes), how readily it dives for
            // cover or bails out at low health (retreatHealthPct), how often it
            // tries to flank vs. brawl head-on (flankMult), how tight its aim is
            // (spreadMult, lower = more accurate), how fast it moves relative to
            // the difficulty baseline (speedMult), and whether it's disciplined
            // enough to lead a moving target even on easier difficulties
            // (alwaysPredictive).
            const TACTICAL_PROFILES = {
                // Standard lightsaber/darksaber duelist fallback — balanced,
                // closes to a comfortable mid-close range. Luke, Rey, Ahsoka,
                // generic saber-wielders without a more specific profile.
                duelist:     { minRange: 60,  maxRange: 140, retreatHealthPct: 0.25, dodgeMult: 1.0, flankMult: 1.0, spreadMult: 1.0,  speedMult: 1.0,  alwaysPredictive: false },
                // Reckless, all-out aggression — closes distance and stays there,
                // barely acknowledges its own danger. Anakin, Grievous, Maul, etc.
                berserker:   { minRange: 25,  maxRange: 85,  retreatHealthPct: 0.08, dodgeMult: 0.5, flankMult: 0.5, spreadMult: 1.15, speedMult: 1.15, alwaysPredictive: false },
                // Patient, controlled, technically precise masters — Windu, Dooku,
                // Yoda, Vader. Fight with intent, not panic.
                calculated:  { minRange: 90,  maxRange: 190, retreatHealthPct: 0.35, dodgeMult: 1.3, flankMult: 1.4, spreadMult: 0.75, speedMult: 0.95, alwaysPredictive: true  },
                // Bounty hunters, snipers and assassin droids — keep their
                // distance, reposition constantly, rarely brawl.
                kiter:       { minRange: 170, maxRange: 340, retreatHealthPct: 0.45, dodgeMult: 1.4, flankMult: 1.3, spreadMult: 0.65, speedMult: 1.05, alwaysPredictive: true  },
                // Standard trained soldier — clones, troopers, rebels. Balanced,
                // uses cover, holds a sane mid-range.
                disciplined: { minRange: 100, maxRange: 220, retreatHealthPct: 0.30, dodgeMult: 1.0, flankMult: 1.0, spreadMult: 0.9,  speedMult: 1.0,  alwaysPredictive: false },
                // Melee tanks and brutes — Chewbacca, Zeb, Royal Guard,
                // MagnaGuards. Get in close and absorb the hit.
                brawler:     { minRange: 15,  maxRange: 75,  retreatHealthPct: 0.15, dodgeMult: 0.65, flankMult: 0.4, spreadMult: 1.0,  speedMult: 1.05, alwaysPredictive: false },
                // Mass-produced cannon fodder — B1 droids. Charges in with no
                // sense of self-preservation and shoots wildly.
                reckless:    { minRange: 40,  maxRange: 100, retreatHealthPct: 0.05, dodgeMult: 0.35, flankMult: 0.35, spreadMult: 1.3,  speedMult: 1.1,  alwaysPredictive: false },
                // Heavy-weapon suppressors — miniguns, droidekas. Plant themselves
                // at range and let the volume of fire do the work.
                turret:      { minRange: 140, maxRange: 260, retreatHealthPct: 0.30, dodgeMult: 0.5, flankMult: 0.2, spreadMult: 0.9,  speedMult: 0.6,  alwaysPredictive: false },
                // Force-lightning casters — Palpatine, Snoke. Stay at range and
                // pour on ranged damage rather than closing to melee.
                caster:      { minRange: 150, maxRange: 300, retreatHealthPct: 0.30, dodgeMult: 1.1, flankMult: 0.8, spreadMult: 0.7,  speedMult: 0.9,  alwaysPredictive: true  }
            };

            // Explicit per-character overrides for cases where lore doesn't match
            // the generic weapon/faction fallback below (e.g. Vader isn't a
            // berserker despite wielding a lightsaber; Chewbacca isn't a kiter
            // despite carrying a bowcaster).
            const TACTICAL_ID_OVERRIDES = {
                berserker:   ['anakin', 'grievous', 'maul', 'darth_maul', 'savage', 'ventress', 'kylo', 'malak', 'nihilus', 'krell', 'charred_anakin', 'sith_anakin', 'sith_c3po', 'reva', 'fifthbrother'],
                // The Voidblade is 'calculated' rather than the disciplined default:
                // she picks her shots with a surgical burst rifle, and her Shock Rock
                // jumps make her hard to pin down — precise aim, heavy dodging.
                calculated:  ['windu', 'mace_windu', 'dooku', 'yoda', 'obiwan', 'quigon', 'revan', 'vader', 'darth_vader', 'thrawn', 'plokoan', 'kiadimundi', 'shaakti', 'luminara', 'yaddle', 'bxcommando', 'voidblade'],
                kiter:       ['boba', 'jango', 'jango_fett', 'cadbane', 'bossk', 'dengar', 'ig88', 'ig11', 'aurrasing', 'embo', 'zuckuss', '4lom', 'fennec', 'greedo', 'hondo', 'hk47', 'xizor', 'crosshair'],
                brawler:     ['wrecker', 'gamorrean', 'magnaguard', 'darktrooper', 'k2so'],
                turret:      ['thorn', 'pazvizsla', 'droideka', 'superdroid', 'baze'],
                reckless:    ['b1droid']
            };
            const TACTICAL_ID_LOOKUP = {};
            for (const [profileName, ids] of Object.entries(TACTICAL_ID_OVERRIDES)) {
                for (const id of ids) TACTICAL_ID_LOOKUP[id] = profileName;
            }

            function getTacticalProfile(e) {
                // A profile carried on the entity itself wins over everything below.
                // Two things use it: roster entries that name their own profile
                // (the whole Zero Event cast does), copied onto the entity at spawn
                // the same way speedMult is; and a live transformation swapping one
                // fighter's behaviour for another's mid-round.
                //
                // Both were dead before this existed. The cast's `tacticalProfile`
                // field was written thirteen times and read nowhere, so Twisted
                // Sonic was not a berserker, the IO Tank was not a turret and the
                // Void Voyager did not kite — every one of them silently fell
                // through to the weapon-based default.
                const carried = e.tacticalProfileOverride && TACTICAL_PROFILES[e.tacticalProfileOverride];
                if (carried) return carried;

                const overrideProfile = TACTICAL_ID_LOOKUP[e.characterId];
                if (overrideProfile) return TACTICAL_PROFILES[overrideProfile];

                if (e.isWookiee) return TACTICAL_PROFILES.brawler;
                if (e.isClone) return TACTICAL_PROFILES.disciplined;

                const wk = e.weaponConfig ? e.weaponConfig.key : null;
                if (wk === 'bowcaster') return TACTICAL_PROFILES.kiter;
                if (wk === 'staff') return TACTICAL_PROFILES.brawler;
                // A shotgun is only worth carrying at knife-fighting range, so its
                // users close in rather than hold the disciplined mid-range default.
                if (wk === 'focusshotgun') return TACTICAL_PROFILES.brawler;
                // A sniper wants the range its scope was built for. The base Sniper
                // Rifle's users get here through TACTICAL_ID_OVERRIDES (Crosshair is
                // listed as a kiter); the Boom Sniper is a pack weapon whose whole
                // identity is the distance, so it says so by weapon rather than by
                // id. Kept so the rule is already right when the pack is added.
                if (wk === 'boomsniper') return TACTICAL_PROFILES.kiter;
                // Stated rather than left to the fallback below, which happens to be
                // the same profile: the wiki calls the Assault Rifle good at every
                // range and best at medium, which is exactly what 'disciplined' is —
                // a sane mid-range band with cover use. That match should be on
                // purpose, not an accident of ordering that a future edit to the
                // default would silently undo.
                if (wk === 'assaultrifle' || wk === 'enhancedar') return TACTICAL_PROFILES.disciplined;
                // Six rounds and no spare: the Ex-Caliber's owner picks shots and
                // keeps moving rather than trading fire out of a magazine he does
                // not have.
                if (wk === 'excaliber') return TACTICAL_PROFILES.calculated;
                // See the Deadeye's library entry: the accuracy its name promises is
                // in how it is fought with rather than in a stat.
                if (wk === 'deadeyear') return TACTICAL_PROFILES.calculated;
                if (wk === 'minigun') return TACTICAL_PROFILES.turret;
                if (wk === 'lightning') return TACTICAL_PROFILES.caster;
                if (wk === 'lightsaber' || wk === 'darksaber') return TACTICAL_PROFILES.duelist || TACTICAL_PROFILES.disciplined;

                return TACTICAL_PROFILES.disciplined;
            }

            // ── AI REACTIONS ───────────────────────────────────────────────
            // Difficulty used to be nothing but numbers: diffSettings scaled the
            // AI's aim cone, its speed, its HP and how many allies it brought.
            // Legend was not a cleverer opponent, it was the same opponent with a
            // tighter group and more health — which reads as the game cheating
            // rather than as being outplayed, because losing to it never taught you
            // anything you could have done differently.
            //
            // These are the things a *thinking* opponent does, and difficulty gates
            // the behaviour itself rather than the arithmetic:
            //
            //   threat    notices a bolt already in the air and rolls out of it
            //   punish    recognises that you are reloading or locked in a swing,
            //             and presses exactly then
            //   los       stops firing into the back of a crate, and moves instead
            //   hazard    stops standing in lava
            //
            // Easy genuinely has none of it and is meant to feel like a training
            // dummy. reactionMs is how far ahead the AI is allowed to see a shot
            // arriving — a human needs ~250ms to react, so Legend's 90ms is
            // deliberately superhuman while Normal's 320ms is roughly fair.
            const AI_REACTIONS = {
                easy:   { threat: false, reactionMs: 0,   punish: 0,    los: false, hazard: false },
                normal: { threat: true,  reactionMs: 320, punish: 0.25, los: true,  hazard: false },
                hard:   { threat: true,  reactionMs: 190, punish: 0.55, los: true,  hazard: true  },
                legend: { threat: true,  reactionMs: 90,  punish: 0.85, los: true,  hazard: true  }
            };

            function aiReactions() {
                return AI_REACTIONS[currentDifficulty] || AI_REACTIONS.normal;
            }

            /** The most urgent bolt currently on course to hit `e`, or null.
             *
             *  Works in the bullet's own frame: project the offset to the entity
             *  onto the bullet's heading to get how far along its path we are
             *  (`along`) and how far off that line we sit (`lateral`). A bolt that
             *  has already passed, or that will miss anyway, is not a threat and is
             *  not worth burning a dodge on. */
            function findIncomingThreat(e, reactionMs) {
                let best = null;
                let bestMs = Infinity;
                for (let i = 0; i < bullets.length; i++) {
                    const b = bullets[i];
                    if (!b.owner || b.owner.team === e.team) continue;
                    const speed = Math.hypot(b.dx, b.dy);
                    if (speed < 0.01) continue;
                    const ux = b.dx / speed, uy = b.dy / speed;
                    const rx = e.x - b.x, ry = e.y - b.y;
                    const along = rx * ux + ry * uy;
                    if (along <= 0) continue;                       // already gone by
                    const lateral = Math.abs(rx * uy - ry * ux);
                    if (lateral > CHARACTER_SIZE + 8) continue;     // going to miss
                    // Bullet speeds are per frame at TARGET_FPS, so frames → ms.
                    const ms = (along / speed) * (1000 / TARGET_FPS);
                    if (ms > reactionMs) continue;                  // too far off to have noticed
                    if (ms < bestMs) { bestMs = ms; best = { bullet: b, ux, uy, ms }; }
                }
                return best;
            }

            /** Is there a clear shot from (fx,fy) to (tx,ty)?
             *
             *  Sampled rather than solved analytically: cover and barriers are all
             *  axis-aligned boxes, and walking the segment in ~16px steps is both
             *  short enough to catch every box in this game and far cheaper to
             *  reason about than a swept-box intersection. The AI used to empty
             *  magazines into the back of a crate; this is what stops that. */
            function hasLineOfFire(fx, fy, tx, ty) {
                const dx = tx - fx, dy = ty - fy;
                const dist = Math.hypot(dx, dy);
                if (dist < 1) return true;
                const steps = Math.min(48, Math.max(2, Math.ceil(dist / 16)));
                const now = frameNow;
                for (let i = 1; i < steps; i++) {
                    const t = i / steps;
                    const px = fx + dx * t, py = fy + dy * t;
                    for (const c of coverObjects) {
                        if (!c.alive) continue;
                        if (px > c.x - c.w / 2 && px < c.x + c.w / 2 &&
                            py > c.y - c.h / 2 && py < c.y + c.h / 2) return false;
                    }
                    if (hazardBlocksPoint(px, py, 0, now)) return false;
                }
                return true;
            }

            /** True when the target is in a state that cannot answer back — mid
             *  reload, or committed to a swing that has not landed yet. These are
             *  precisely the windows the mechanics added for the player to exploit,
             *  so the AI is taught to see them too. */
            function targetIsPunishable(target, now) {
                if (!target) return false;
                if (target.isReloading) return true;
                if (isCommittedToSwing(target, now)) return true;
                if (now < target.stunnedUntil || now < target.knockedOutUntil) return true;
                return false;
            }

            /** A damaging hazard this entity is currently standing in, or null.
             *
             *  The singularity counts: an AI that walks into the Zero Point and
             *  gets scattered across the map, repeatedly, looks broken rather than
             *  unlucky. Slowing-only zones do not count — roots cost tempo, and
             *  fleeing them would just make the AI refuse to fight on half the
             *  Kashyyyk map. */
            function standingInHarm(e) {
                for (const hz of hazards) {
                    if (hz.kind === 'singularity') {
                        // A wider berth than the hitbox: being adjacent to it is
                        // already a mistake, and the escape needs to start before
                        // the touch rather than after it.
                        if (Math.hypot(e.x - hz.x, e.y - hz.y) <= hz.r * 1.35) return hz;
                        continue;
                    }
                    if (hz.kind !== 'zone' || !hz.cfg.damage) continue;
                    if (Math.hypot(e.x - hz.x, e.y - hz.y) <= hz.r) return hz;
                }
                return null;
            }

            // --- MASSIVE ROSTER EXPANSION ---
            const characters = {
                heroes: [
                    // --- CLONE COMMANDERS & LEGIONS ---
                    { id: '501st', name: '501st Legion Trooper', arenaName: '501st Trooper', color: '#0077ff', hp: 140, weapon: 'blaster', isClone: true, bio: 'Anakin Skywalker\'s elite legion. Led by Captain Rex, they served with distinction across the Clone Wars.' },
                    { id: '212th', name: '212th Attack Battalion Trooper', arenaName: '212th Trooper', color: '#ff9900', hp: 130, weapon: 'blaster', isClone: true, bio: 'Led by Commander Cody and Obi-Wan Kenobi. Known for their distinctive orange armor and siege tactics.' },
                    { id: '104th', name: '104th Wolfpack Trooper', arenaName: '104th Trooper', color: '#999999', hp: 125, weapon: 'blaster', isClone: true, bio: 'Led by Commander Wolffe and Jedi Master Plo Koon. Elite reconnaissance unit with distinctive grey armor.' },
                    { id: 'coruscant', name: 'Coruscant Guard Trooper', arenaName: 'Coruscant Trooper', color: '#ff0000', hp: 110, weapon: 'blaster', isClone: true, bio: 'Elite security force protecting the Galactic Senate and Supreme Chancellor. Led by Commander Fox.' },
                    { id: '327th', name: '327th Star Corps Trooper', arenaName: '327th Trooper', color: '#ffff00', hp: 120, weapon: 'blaster', isClone: true, bio: 'Led by Commander Bly and Aayla Secura. Distinguished by their yellow armor and rapid deployment tactics.' },
                    { id: '41st', name: '41st Elite Corps Trooper', arenaName: '41st Trooper', color: '#44ff44', hp: 130, weapon: 'blaster', isClone: true, bio: 'Specialized in jungle and swamp warfare. Led by Commander Gree and Jedi Master Luminara Unduli.' },
                    { id: '52nd', name: '52nd Star Corps Trooper', arenaName: '52nd Trooper', color: '#8b4513', hp: 125, weapon: 'blaster', isClone: true, bio: 'Led by Captain Keeli. Known for their fierce loyalty and combat effectiveness in planetary assaults.' },
                    { id: '91st', name: '91st Recon Corps Trooper', arenaName: '91st Trooper', color: '#ff4444', hp: 115, weapon: 'blaster', isClone: true, bio: 'Specialized reconnaissance and scouting unit. Led by Commander Neyo with distinctive red armor.' },
                    { id: '187th', name: '187th Legion Trooper', arenaName: '187th Trooper', color: '#a000ff', hp: 125, weapon: 'blaster', isClone: true, bio: 'Led by Commander Bacara and Jedi Master Ki-Adi-Mundi. Elite legion with purple markings.' },
                    { id: '21st', name: '21st Nova Corps Marine', arenaName: '21st Marine', color: '#800000', hp: 135, weapon: 'blaster', isClone: true, bio: 'Elite special forces unit. Led by Commander Ponds and Jedi Master Mace Windu. The best of the best.' },
                    { id: '442nd', name: '442nd Siege Battalion Trooper', arenaName: '442nd Trooper', color: '#008000', hp: 120, weapon: 'blaster', isClone: true, bio: 'Specialized in heavy assault and siege breaking. Led by Commander Doom with distinctive green armor.' },
                    { id: '612th', name: '612th Attack Battalion Trooper', arenaName: '612th Trooper', color: '#ff6666', hp: 115, weapon: 'blaster', isClone: true, bio: 'Elite attack battalion with red and grey armor markings. Led by Commander Ganch under Jedi Bolla Ropal.' },
                    { id: 'rancor', name: 'Rancor Battalion ARC Trooper', arenaName: 'Rancor ARC Trooper', color: '#cc66cc', hp: 125, weapon: 'blaster', isClone: true, bio: 'Elite ARC trooper battalion that trained cadets on Kamino. Led by Commander Colt under Shaak Ti with maroon and grey armor.' },
                    { id: '184th', name: '184th Attack Battalion Trooper', arenaName: '184th Trooper', color: '#666699', hp: 118, weapon: 'blaster', isClone: true, bio: 'Infantry battalion with distinctive blue-grey armor. Led by Commander Crane under Jedi Jor Aerith.' },
                    { id: 'rex', name: 'Captain Rex', color: '#00d4ff', hp: 165, weapon: 'blaster', isClone: true, bio: 'Anakin Skywalker\'s second-in-command. One of the most respected clones in the Grand Army. Refused to execute Order 66.' },
                    { id: 'fives', name: 'Fives', color: '#00b8e6', hp: 160, weapon: 'blaster', isClone: true, bio: 'ARC trooper who uncovered the inhibitor chip conspiracy. Died trying to warn the Jedi.' },
                    { id: 'jesse', name: 'Jesse', color: '#00a0cc', hp: 155, weapon: 'blaster', isClone: true, bio: 'Loyal 501st trooper under Rex. Fought through the worst of the Clone Wars — and Order 66.' },
                    { id: 'hardcase', name: 'Hardcase', color: '#0090b8', hp: 155, weapon: 'minigun', isClone: true, bio: 'Reckless heavy gunner of the 501st. Charged droid lines for fun and paid the ultimate price on Umbara.' },
                    { id: 'cody', name: 'Commander Cody', color: '#ff9900', hp: 155, weapon: 'blaster', isClone: true, bio: 'Obi-Wan Kenobi\'s loyal commander. Led the 212th with distinction. Tragically carried out Order 66 on Utapau.' },
                    { id: 'wolffe', name: 'Commander Wolffe', color: '#999999', hp: 150, weapon: 'blaster', isClone: true, bio: 'Leader of the Wolfpack under Plo Koon. Lost his eye in battle but never lost his fighting spirit.' },
                    { id: 'bly', name: 'Commander Bly', color: '#ffff00', hp: 155, weapon: 'blaster', isClone: true, bio: 'Aayla Secura\'s trusted commander. Led the 327th with honor. Executed Order 66 on Felucia.' },
                    { id: 'gree', name: 'Commander Gree', color: '#44ff44', hp: 155, weapon: 'blaster', isClone: true, bio: 'Expert in jungle warfare under Luminara Unduli. Executed Order 66 on Kashyyyk alongside Yoda.' },
                    { id: 'fox', name: 'Commander Fox', color: '#ff0000', hp: 150, weapon: 'blaster', isClone: true, bio: 'Leader of the Coruscant Guard. Fiercely loyal to the Chancellor. Executed Fives to protect Order 66.' },
                    { id: 'fox_elite', name: 'Commander Fox (Elite)', color: '#cc0000', hp: 165, weapon: 'beam', isClone: true, secretUnlock: 'fox_elite', bio: 'The Coruscant Guard commander who faced down Vader himself, now wielding a continuous-fire beam weapon.' },
                    { id: 'bacara', name: 'Commander Bacara', color: '#800000', hp: 160, weapon: 'blaster', isClone: true, bio: 'Ki-Adi-Mundi\'s commander. Led the 187th in the Outer Rim sieges. Executed Order 66 on Mygeeto.' },
                    { id: 'neyo', name: 'Commander Neyo', color: '#ff4444', hp: 155, weapon: 'blaster', isClone: true, bio: 'Leader of the 91st Recon Corps. Executed Order 66 on Stass Allie during a speeder bike patrol.' },
                    { id: 'appo', name: 'Commander Appo', color: '#0077ff', hp: 150, weapon: 'blaster', isClone: true, bio: 'Rex\'s successor as commander of the 501st. Led the raid on the Jedi Temple under Vader.' },
                    { id: 'doom', name: 'Commander Doom', color: '#00aa00', hp: 160, weapon: 'blaster', isClone: true, bio: 'Leader of the 442nd Siege Battalion. Expert in heavy assault tactics and breaking fortified positions.' },
                    { id: 'ponds', name: 'Commander Ponds', color: '#a000ff', hp: 150, weapon: 'blaster', isClone: true, bio: 'Mace Windu\'s trusted second-in-command. Led the 21st Nova Corps with distinction. Captured and executed by Grievous.' },
                    { id: 'thorn', name: 'Commander Thorn', color: '#ff0000', hp: 160, weapon: 'minigun', isClone: true, secretUnlock: 'thorn', bio: 'Coruscant Guard commander. Heroically sacrificed himself defending Senator Amidala on Scipio.' },
                    { id: 'keeli', name: 'Captain Keeli', color: '#8b4513', hp: 155, weapon: 'blaster', isClone: true, bio: 'Leader of the Outer Rim Garrison. Died defending a medical station on Ryloth, buying time for civilians to escape.' },
                    { id: 'ganch', name: 'Commander Ganch', color: '#ff6666', hp: 150, weapon: 'blaster', isClone: true, bio: 'Leader of the 612th Attack Battalion. Served under Jedi Bolla Ropal with distinctive red and grey armor.' },
                    { id: 'colt', name: 'Commander Colt', color: '#cc66cc', hp: 165, weapon: 'blaster', isClone: true, bio: 'ARC Commander of the Rancor Battalion. Trained cadets on Kamino alongside Shaak Ti. Killed during the Battle of Kamino.' },
                    { id: 'crane', name: 'Commander Crane', color: '#666699', hp: 155, weapon: 'blaster', isClone: true, bio: 'Leader of the 184th Attack Battalion under Jor Aerith. Tragically executed Order 66 on his own general.' },

                    // --- JEDI & FORCE USERS ---
                    { id: 'anakin', name: 'Anakin Skywalker', color: '#0077ff', hp: 220, weapon: 'lightsaber', saberColor: '#5599ff', bio: 'The Chosen One. His fall to the dark side shattered the Jedi Order.' },
                    { id: 'obiwan', name: 'Obi-Wan Kenobi', color: '#00ccff', hp: 200, weapon: 'lightsaber', saberColor: '#55bbff', bio: 'Master of Soresu. "Hello there."' },
                    { id: 'quigon', name: 'Qui-Gon Jinn', color: '#00ff00', hp: 200, weapon: 'lightsaber', saberColor: '#00ff00', bio: 'A maverick Jedi Master who trusted the Living Force above the Council.' },
                    { id: 'ahsoka', name: 'Ahsoka Tano', color: '#33ff00', hp: 185, weapon: 'lightsaber', saberColor: '#ccffee', bio: 'Anakin\'s former Padawan. She walked away from the Order — and survived.' },
                    { id: 'yoda', name: 'Yoda', color: '#44ff00', hp: 250, weapon: 'lightsaber', saberColor: '#66ff44', bio: 'Do or do not. There is no try. 900 years of wisdom in a very small package.' },
                    { id: 'windu', name: 'Mace Windu', color: '#a000ff', hp: 235, weapon: 'lightsaber', saberColor: '#cc44ff', bio: 'The only Jedi to wield a purple lightsaber through Vaapad mastery.' },
                    { id: 'mace_windu', name: 'Mace Windu (Elite)', color: '#9900cc', hp: 245, weapon: 'lightsaber', saberColor: '#aa00dd', unlockAchievement: 'winStreak5', bio: 'Unlocked through mastery. His power is unmatched in the Council.' },
                    { id: 'luke', name: 'Luke Skywalker', color: '#8ae1ff', hp: 205, weapon: 'lightsaber', saberColor: '#9ce9ff', bio: 'Farm boy turned Jedi Knight. Redeemed his father with hope instead of hate.' },
                    { id: 'rey', name: 'Rey Skywalker', color: '#ffff00', hp: 200, weapon: 'lightsaber', saberColor: '#ffff00', bio: 'Rose from scavenger to the last Jedi. Her power rivals any who came before.' },
                    { id: 'calkestis', name: 'Cal Kestis', color: '#ff9900', hp: 190, weapon: 'lightsaber', saberColor: '#0088ff', bio: 'A Padawan who survived Order 66 and rebuilt the Holocron of Jedi younglings.' },
                    { id: 'kanan', name: 'Kanan Jarrus', color: '#00ccff', hp: 185, weapon: 'lightsaber', saberColor: '#0055ff', bio: 'Hera\'s co-pilot and mentor of Ezra. Gave his sight — then his life — for the crew.' },
                    { id: 'ezra', name: 'Ezra Bridger', color: '#00ff00', hp: 180, weapon: 'lightsaber', saberColor: '#00ff00', bio: 'A street kid from Lothal who became a Jedi and helped free his home planet.' },
                    { id: 'kitfisto', name: 'Kit Fisto', color: '#00ff88', hp: 210, weapon: 'lightsaber', saberColor: '#00ff88', bio: 'Jedi Master known for his smile and skill in underwater combat. Fought bravely in the Clone Wars.' },
                    { id: 'plokoan', name: 'Plo Koon', color: '#888888', hp: 220, weapon: 'lightsaber', saberColor: '#00aaff', bio: 'Jedi Master and Kel Dor who discovered Ahsoka Tano. Commander of the 104th Wolfpack.' },
                    { id: 'kiadimundi', name: 'Ki-Adi-Mundi', color: '#0066ff', hp: 215, weapon: 'lightsaber', saberColor: '#0066ff', bio: 'Jedi Master with a binary brain. Led the 187th Legion and served on the Jedi Council.' },
                    { id: 'aayla', name: 'Aayla Secura', color: '#00ffff', hp: 195, weapon: 'lightsaber', saberColor: '#00ffff', bio: 'Twilek Jedi Master skilled in Form IV. Led the 327th Star Corps with Commander Bly.' },
                    { id: 'shaakti', name: 'Shaak Ti', color: '#ff6699', hp: 200, weapon: 'lightsaber', saberColor: '#ff6699', bio: 'Togruta Jedi Master who trained clone cadets on Kamino. Survived Order 66 and went into hiding.' },
                    { id: 'luminara', name: 'Luminara Unduli', color: '#00ffaa', hp: 190, weapon: 'lightsaber', saberColor: '#00ffaa', bio: 'Mirialan Jedi Master and master of Barriss Offee. Led the 41st Elite Corps on Kashyyyk.' },
                    { id: 'barriss', name: 'Barriss Offee', color: '#00cc88', hp: 175, weapon: 'lightsaber', saberColor: '#00cc88', bio: 'Mirialan Jedi Padawan who betrayed the Order. Framed Ahsoka for terrorism.' },
                    { id: 'saseetee', name: 'Saesee Tiin', color: '#6666ff', hp: 205, weapon: 'lightsaber', saberColor: '#6666ff', bio: 'Iktotchi Jedi Master and pilot. Served on the Jedi Council and fought in many battles.' },
                    { id: 'evenpiell', name: 'Even Piell', color: '#ff9966', hp: 180, weapon: 'lightsaber', saberColor: '#ff9966', bio: 'Lannik Jedi Master known for his toughness and combat skills. Survived the Citadel prison break.' },
                    { id: 'coleman', name: 'Coleman Kcaj', color: '#ffcc00', hp: 190, weapon: 'lightsaber', saberColor: '#ffcc00', bio: 'Ongree Jedi Master on the High Council. Skilled strategist and diplomat.' },
                    { id: 'oppo', name: 'Oppo Rancisis', color: '#9966ff', hp: 185, weapon: 'lightsaber', saberColor: '#9966ff', bio: 'Thisspiasian Jedi Master and military strategist. Served on the Council for decades.' },
                    { id: 'yaddle', name: 'Yaddle', color: '#44ff44', hp: 220, weapon: 'lightsaber', saberColor: '#44ff44', bio: 'Female Jedi Master of Yoda\'s species. Wise and powerful, though rarely seen.' },
                    { id: 'depabillaba', name: 'Depa Billaba', color: '#ff6666', hp: 200, weapon: 'lightsaber', saberColor: '#ff6666', bio: 'Human Jedi Master who trained Kanan Jarrus. Led the 91st Recon Corps on Haruun Kal.' },
                    { id: 'krell', name: 'Pong Krell', color: '#9933ff', hp: 230, weapon: 'lightsaber', saberColor: '#9933ff', bio: 'Besalisk Jedi Master who turned traitor. Wielded two double-bladed lightsabers. Executed by clones.' },
                    { id: 'eeth', name: 'Eeth Koth', color: '#ffaa00', hp: 195, weapon: 'lightsaber', saberColor: '#ffaa00', bio: 'Iridonian Zabrak Jedi Master. Served on the Council and survived Order 66 initially.' },
                    { id: 'adi', name: 'Adi Gallia', color: '#ff6666', hp: 190, weapon: 'lightsaber', saberColor: '#ff6666', bio: 'Tholothian Jedi Master and skilled pilot. Killed by Savage Opress during the Clone Wars.' },
                    { id: 'agen', name: 'Agen Kolar', color: '#006600', hp: 200, weapon: 'lightsaber', saberColor: '#006600', bio: 'Zabrak Jedi Master known for his combat skills. Killed by Palpatine alongside other Jedi.' },
                    { id: 'stass', name: 'Stass Allie', color: '#6699ff', hp: 185, weapon: 'lightsaber', saberColor: '#6699ff', bio: 'Tholothian Jedi Master and cousin of Adi Gallia. Executed by Commander Neyo on Saleucami.' },
                    { id: 'jocastanu', name: 'Jocasta Nu', color: '#ccbbff', hp: 175, weapon: 'lightsaber', saberColor: '#ccbbff', bio: 'Chief Archivist of the Jedi Temple Library. Calls on the Coruscant Guard, led by Commander Fox, to defend her archives.' },
                    { id: 'shaagi', name: "Sha'a Gi", color: '#2e8b6e', hp: 190, weapon: 'lightsaber', saberColor: '#33ff66', secretUnlock: 'shaagi', bio: 'Nautolan Jedi Master of the Clone Wars era. Fell in battle against General Grievous over Saleucami.' },

                    // --- REBELS, RESISTANCE & SMUGGLERS ---
                    { id: 'padme', name: 'Padmé Amidala', color: '#ffffff', hp: 150, weapon: 'blaster', bio: 'Senator, queen, and secret wife of Anakin. She never stopped believing in the Republic.' },
                    { id: 'han', name: 'Han Solo', color: '#ffcc00', hp: 160, weapon: 'blaster', bio: 'Made the Kessel Run in 12 parsecs. Shot first. Reluctant hero of the galaxy.' },
                    { id: 'leia', name: 'Leia Organa', color: '#ffffff', hp: 155, weapon: 'blaster', bio: 'General, princess, and Force-sensitive rebel leader. Never lost hope.' },
                    { id: 'lando', name: 'Lando Calrissian', color: '#00ccff', hp: 150, weapon: 'blaster', bio: 'Administrator of Cloud City and smooth-talking gambler. He came through in the end.' },
                    { id: 'finn', name: 'Finn', color: '#ff9900', hp: 155, weapon: 'blaster', bio: 'Stormtrooper FN-2187 who chose the Resistance. "That\'s not how the Force works!"' },
                    { id: 'finn_elite', name: 'Finn (Elite)', color: '#0066ff', hp: 170, weapon: 'lightsaber', saberColor: '#0088ff', unlockAchievement: 'firstWin', bio: 'Former stormtrooper who found his true calling. Now wields a blue lightsaber in defense of the Resistance.' },
                    { id: 'poe', name: 'Poe Dameron', color: '#ff4444', hp: 150, weapon: 'blaster', bio: 'The best pilot in the Resistance. Black Leader. Never leaves a wingman behind.' },
                    { id: 'jyn', name: 'Jyn Erso', color: '#aaaaaa', hp: 155, weapon: 'blaster', bio: 'Stole the Death Star plans and paid the ultimate price. Rebellions are built on hope.' },
                    { id: 'cassian', name: 'Cassian Andor', color: '#666666', hp: 150, weapon: 'blaster', bio: 'Intelligence officer who\'s done terrible things for the Rebellion. Has a droid.' },
                    { id: 'baze', name: 'Baze Malbus', color: '#7a6a55', hp: 200, weapon: 'minigun', unlockAchievement: 'bazeUnlock', bio: 'Former Guardian of the Whills turned heavy-weapons gunman. Carries a relic cannon that shreds anything in its path.' },
                    { id: 'k2so', name: 'K-2SO', color: '#c8ccd1', hp: 195, weapon: 'blaster', isDroid: true, bio: 'Reprogrammed Imperial security droid. Blunt, loyal, and built like a tank. "I find that answer vague and unconvincing."' },
                    { id: 'hera', name: 'Hera Syndulla', color: '#00ff00', hp: 145, weapon: 'blaster', bio: 'Captain of the Ghost. One of the best pilots in the Rebel Alliance.' },
                    { id: 'sabine', name: 'Sabine Wren', color: '#ff00ff', hp: 160, weapon: 'darksaber', saberColor: '#000000', bio: 'Mandalorian artist and explosives expert. Wields the Darksaber with flair.' },
                    { id: 'zeb', name: 'Zeb Orrelios', color: '#a000ff', hp: 180, weapon: 'staff', bio: 'Last surviving Lasat Honor Guard. Massive, loyal, and deadly with his bo-rifle.' },
                    { id: 'chewie', name: 'Chewbacca', color: '#8b4513', hp: 215, weapon: 'bowcaster', isWookiee: true, bio: 'Han\'s co-pilot and best friend. 200-year-old Wookiee warrior. Always pays his debts.' },
                    { id: 'mando', name: 'The Mandalorian', color: '#b0b5b9', hp: 190, weapon: 'blaster', bio: 'This is the way. Din Djarin — bounty hunter and protector of Grogu, armed with his trusty blaster.' },
                    { id: 'mando_elite', name: 'The Mandalorian (Elite)', color: '#8a8f99', hp: 205, weapon: 'darksaber', saberColor: '#000000', weaponDamage: 25, unlockAchievement: 'mandoDarksaber', bio: 'Din Djarin, having bested Moff Gideon on Mandalore, now wields the Darksaber as its rightful bearer.' },
                    { id: 'bokatan', name: 'Bo-Katan Kryze', color: '#0077ff', hp: 170, weapon: 'blaster', bio: 'Rightful ruler of Mandalore. Fights to reclaim her people\'s home and honor.' },
                    { id: 'ackbar', name: 'Admiral Ackbar', color: '#ffaa00', hp: 140, weapon: 'blaster', bio: 'It\'s a trap! Supreme Commander of the Rebel fleet at the Battle of Endor.' },
                    { id: 'wedge', name: 'Wedge Antilles', color: '#ff6600', hp: 145, weapon: 'blaster', bio: 'Legendary pilot who flew in both Death Star battles. Founder of Rogue Squadron.' },
                    { id: 'biggs', name: 'Biggs Darklighter', color: '#ffaa00', hp: 140, weapon: 'blaster', bio: 'Luke\'s childhood friend from Tatooine. Died protecting Luke during the Battle of Yavin.' },
                    { id: 'crix', name: 'Crix Madine', color: '#666666', hp: 135, weapon: 'blaster', bio: 'Imperial officer who defected to the Rebellion. Planned the Endor mission.' },
                    { id: 'jan', name: 'Jan Dodonna', color: '#888888', hp: 130, weapon: 'blaster', bio: 'Veteran of the Clone Wars who became a Rebel general. Briefed pilots before Yavin.' },
                    { id: 'raddus', name: 'Admiral Raddus', color: '#0088ff', hp: 150, weapon: 'blaster', bio: 'Mon Calamari admiral who led the Rogue One mission. Sacrificed himself at Scarif.' },
                    { id: 'holdo', name: 'Vice Admiral Holdo', color: '#ff66cc', hp: 145, weapon: 'blaster', bio: 'Brave leader who made the ultimate sacrifice. Her hyperspace ram will never be forgotten.' },
                    { id: 'rose', name: 'Rose Tico', color: '#ff9966', hp: 130, weapon: 'blaster', bio: 'Resistance mechanic who found her courage. "Not fighting what we hate, saving what we love."' },
                    { id: 'zorii', name: 'Zorii Bliss', color: '#666699', hp: 140, weapon: 'blaster', bio: 'Leader of the Spice Runners of Kijimi. Former associate of Poe Dameron.' },
                    { id: 'jannah', name: 'Jannah', color: '#00cc99', hp: 145, weapon: 'blaster', bio: 'Former First Order stormtrooper who defected. Skilled with heavy weapons.' },
                    { id: 'qira', name: 'Qi\'ra', color: '#996633', hp: 135, weapon: 'blaster', bio: 'Han Solo\'s first love from Corellia. Rose from slavery to lead the Crimson Dawn.' },
                    { id: 'enfys', name: 'Enfys Nest', color: '#663333', hp: 140, weapon: 'staff', bio: 'Leader of the Cloud-Riders. Fights for the oppressed with fierce determination.' },

                    // --- BAD BATCH ---
                    { id: 'hunter', name: 'Hunter', color: '#555555', hp: 165, weapon: 'vibroblade', bio: 'Leader of the Bad Batch with enhanced senses. Skilled tracker who favors a close-range vibroblade.' },
                    { id: 'wrecker', name: 'Wrecker', color: '#444444', hp: 200, weapon: 'blaster', bio: 'Heavy weapons specialist of the Bad Batch. Loves explosions and big guns.' },
                    { id: 'tech', name: 'Tech', color: '#777777', hp: 145, weapon: 'blaster', bio: 'Genius strategist and tech expert of the Bad Batch. Can hack any system.' },
                    { id: 'echo', name: 'Echo', color: '#666666', hp: 150, weapon: 'blaster', bio: 'Cybernetically-enhanced soldier. Former ARC trooper who survived the Citadel.' },
                    { id: 'crosshair', name: 'Crosshair', color: '#333333', hp: 150, weapon: 'sniper', bio: 'Sharpshooter with genetic modifications for precision. One shot, one kill.' },
                    { id: 'omega', name: 'Omega', color: '#e8c89a', hp: 130, weapon: 'blaster', bio: 'Unmodified clone and heart of the Bad Batch. Curious, brave, and wiser than her years.' },

                    // --- REBELS & ALLIES ---
                    { id: 'saw', name: 'Saw Gerrera', color: '#8b4513', hp: 170, weapon: 'blaster', bio: 'Partisan leader who fought the Empire with extreme methods. "If you\'re not with me, then you\'re my enemy."' },
                    { id: 'chirrut', name: 'Chirrut Îmwe', color: '#c4a35a', hp: 155, weapon: 'staff', bio: 'Blind Guardian of the Whills. "I am one with the Force, and the Force is with me."' },
                    { id: 'galen_erso', name: 'Galen Erso', color: '#6b8e9f', hp: 125, weapon: 'blaster', bio: 'Brilliant scientist forced to design the Death Star — and the one who built its fatal weakness.' },

                    // --- DROIDS & OTHERS ---
                    { id: 'babu', name: 'Babu Frik', color: '#d9b38c', hp: 110, weapon: 'wrench', bio: 'Droidsmith from Kijimi who helped reprogram droids. Small but skilled technician.' },
                    { id: 'r2d2', name: 'R2-D2', color: '#a8f0ff', hp: 125, weapon: 'zap', isDroid: true, bio: 'Astromech droid who served the Jedi and the Rebellion. Brave and resourceful companion.' },
                    { id: 'c3po', name: 'C-3PO', color: '#ffd700', hp: 120, weapon: 'zap', isDroid: true, bio: 'Protocol droid fluent in over six million forms of communication. Loyal but anxious.' },
                    { id: 'bb8', name: 'BB-8', color: '#ff8c42', hp: 115, weapon: 'zap', isDroid: true, bio: 'Astromech droid who served Poe Dameron. Cheerful and brave companion.' },
                    { id: 'ig11', name: 'IG-11', color: '#bbbbbb', hp: 150, weapon: 'blaster', isDroid: true, bio: 'Bounty hunter droid reprogrammed to protect. Self-destructed to save his friends.' },

                ],
                villains: [
                    // --- SITH & DARK SIDE ---
                    // Sith Anakin sits one notch under Charred Anakin (160 HP / 18 dmg)
                    // deliberately — he is the turn, not the aftermath. `alwaysOpponent`
                    // is what keeps the Charred Anakin unlock reachable without buying
                    // him: the shop entry sells the right to PLAY as him, not the right
                    // to face him. See isCharacterAvailableAsOpponent().
                    // Still his own blue blade — he turned before he took a red one.
                    { id: 'sith_anakin', name: 'Sith Anakin', color: '#8b0000', hp: 150, weapon: 'lightsaber', saberColor: '#5599ff', weaponDamage: 17, secretUnlock: 'sithAnakin', alwaysOpponent: true, bio: 'Anakin at the moment he turned — Vader in all but name, before the suit and before the fire. Defeat him on Mustafar and the Chosen One is remade.' },
                    { id: 'vader', name: 'Darth Vader', color: '#ff0000', hp: 280, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Once the Chosen One. Now the Emperor\'s enforcer. His breathing alone inspires fear.' },
                    { id: 'darth_vader', name: 'Darth Vader (Elite)', color: '#cc0000', hp: 300, weapon: 'lightsaber', saberColor: '#ff0000', weaponDamage: 28, unlockAchievement: 'vaderConquest', bio: 'His full power is unleashed only through conquest. Ten consecutive victories prove his dominance.' },
                    { id: 'palpatine', name: 'The Emperor', color: '#ff0000', hp: 245, weapon: 'lightning', saberColor: '#cc00ff', bio: 'Sheev Palpatine — 1000 years of Sith planning in one sinister body.' },
                    { id: 'maul', name: 'Darth Maul', color: '#ff0000', hp: 210, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Zabrak Sith assassin. Cut in half. Came back angrier. Double-bladed and deadly.' },
                    { id: 'darth_maul', name: 'Darth Maul (Elite)', color: '#cc0000', hp: 220, weapon: 'lightsaber', saberColor: '#ff0000', weaponDamage: 20, unlockAchievement: 'speedDemon', bio: 'His full power is unlocked only for the fastest warriors.' },
                    { id: 'kylo', name: 'Kylo Ren', color: '#d60000', hp: 215, weapon: 'lightsaber', saberColor: '#ff3300', bio: 'Ben Solo turned villain. His crossguard saber crackles with raw, unstable power.' },
                    { id: 'dooku', name: 'Count Dooku', color: '#ff0000', hp: 200, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Fallen Jedi, Separatist leader. His curved hilt is as elegant as his deception.' },
                    { id: 'ventress', name: 'Asajj Ventress', color: '#ff3333', hp: 175, weapon: 'lightsaber', saberColor: '#ff4444', bio: 'Dooku\'s assassin and former Nightsister. Betrayed by everyone — feared by all.' },
                    { id: 'savage', name: 'Savage Opress', color: '#ffff00', hp: 225, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Maul\'s brother. Enhanced by Nightsister magic into a warrior of savage fury.' },
                    { id: 'revan', name: 'Darth Revan', color: '#800080', hp: 250, weapon: 'lightsaber', saberColor: '#800080', bio: 'Jedi turned Sith Lord turned Jedi again. The most complex warrior in the galaxy.' },
                    { id: 'malak', name: 'Darth Malak', color: '#ff0000', hp: 240, weapon: 'lightsaber', saberColor: '#ff0000', bio: 'Revan\'s apprentice who betrayed his master and conquered the galaxy in his place.' },
                    { id: 'nihilus', name: 'Darth Nihilus', color: '#222222', hp: 245, weapon: 'lightsaber', saberColor: '#ff0000', bio: 'A wound in the Force itself. He drains life from entire planets to sustain himself.' },
                    { id: 'snoke', name: 'Supreme Leader Snoke', color: '#ffccaa', hp: 200, weapon: 'zap', bio: 'Puppet master of the First Order. More powerful — and more disposable — than he knew.' },

                    // --- INQUISITORS ---
                    { id: 'inquisitor', name: 'Grand Inquisitor', color: '#ff0000', hp: 175, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Leader of the Inquisitorius hunting Jedi survivors. Former Jedi Temple Guard turned to the dark side.' },
                    { id: 'secondsister', name: 'Second Sister', color: '#ff0000', hp: 190, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Trilla Suduri — fierce Inquisitor who hunted Cal Kestis. Former Padawan of Cere Junda.' },
                    { id: 'ninthsister', name: 'Ninth Sister', color: '#ff0000', hp: 220, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Masana Tide — large and powerful Inquisitor. Uses her size and strength to overwhelm opponents.' },
                    { id: 'reva', name: 'Third Sister', color: '#ff0000', hp: 185, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Reva Sevander — a Jedi Temple survivor turned Inquisitor, burning with a vendetta against Vader himself.' },
                    { id: 'fifthbrother', name: 'Fifth Brother', color: '#ff0000', hp: 210, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Hulking, relentless Inquisitor who corners his prey and rarely lets it escape.' },

                    // --- BOUNTY HUNTERS & SCUM ---
                    { id: 'boba', name: 'Boba Fett', color: '#00ff00', hp: 160, weapon: 'blaster', bio: 'Clone of Jango Fett. Survived the Sarlacc. Now rules Tatooine from Jabba\'s throne.' },
                    { id: 'jango', name: 'Jango Fett', color: '#0077ff', hp: 155, weapon: 'blaster', bio: 'The template for the entire clone army. Died at Geonosis without breaking a sweat.' },
                    { id: 'jango_fett', name: 'Jango Fett (Elite)', color: '#0066cc', hp: 165, weapon: 'blaster', weaponDamage: 28, unlockAchievement: 'comboMaster', bio: 'His full arsenal is unlocked for those who master rapid eliminations.' },
                    { id: 'cadbane', name: 'Cad Bane', color: '#b000ff', hp: 150, weapon: 'blaster', bio: 'The galaxy\'s most feared bounty hunter before Boba rose. Fast draw, cold heart.' },
                    { id: 'bossk', name: 'Bossk', color: '#ffaa00', hp: 180, weapon: 'bowcaster', bio: 'Trandoshan hunter with a deep hatred of Wookiees. Deadly and utterly ruthless.' },
                    { id: 'dengar', name: 'Dengar', color: '#aaaaaa', hp: 160, weapon: 'blaster', bio: 'Battered bounty hunter with a personal grudge against Han Solo.' },
                    { id: 'ig88', name: 'IG-88', color: '#888888', hp: 165, weapon: 'blaster', isDroid: true, bio: 'An assassin droid who hunts for profit with machine-cold precision.' },
                    { id: 'aurrasing', name: 'Aurra Sing', color: '#ff5500', hp: 155, weapon: 'bowcaster', bio: 'Former Jedi Padawan turned deadly sniper. Ruthless and precise.' },
                    { id: 'embo', name: 'Embo', color: '#00aa00', hp: 170, weapon: 'bowcaster', bio: 'Kyuzo bounty hunter. Throws his hat like a boomerang and catches it on the way back.' },
                    { id: 'pazvizsla', name: 'Paz Vizsla', color: '#4a5560', hp: 195, weapon: 'minigun', secretUnlock: 'pazvizsla', bio: 'Mandalorian heavy-weapons specialist of the Tribe. Cuts down enemies with his signature minigun.' },

                    // --- IMPERIAL LEADERS & GUARDS ---
                    { id: 'thrawn', name: 'Admiral Thrawn', color: '#0077ff', hp: 145, weapon: 'blaster', bio: 'Brilliant Chiss tactician. Studied art to understand his enemies.' },
                    { id: 'gideon', name: 'Moff Gideon', color: '#ff0000', hp: 130, weapon: 'darksaber', saberColor: '#000000', bio: 'Imperial warlord seeking to restore the Empire. Wields the stolen Darksaber.' },
                    { id: 'tarkin', name: 'Grand Moff Tarkin', color: '#aaaaaa', hp: 120, weapon: 'blaster', bio: 'Governor of the Outer Rim. Ordered the destruction of Alderaan without hesitation.' },
                    { id: 'krennic', name: 'Director Krennic', color: '#ffffff', hp: 130, weapon: 'blaster', bio: 'Director of the Death Star project. Ambitious and ruthless.' },
                    { id: 'yularen', name: 'Admiral Yularen', color: '#0066ff', hp: 115, weapon: 'blaster', bio: 'ISB officer who served in both the Republic and Empire. Loyal and efficient.' },
                    { id: 'konstantine', name: 'Adm. Konstantine', color: '#666666', hp: 110, weapon: 'blaster', bio: 'Imperial admiral who served under Thrawn. Questioned his unconventional tactics.' },
                    { id: 'sloane', name: 'Grand Admiral Sloane', color: '#ff6666', hp: 135, weapon: 'blaster', bio: 'Rising star in the Imperial Navy. Competent and ambitious officer.' },
                    { id: 'royalguard', name: 'Royal Guard', color: '#ff0000', hp: 150, weapon: 'staff', bio: 'Elite red-robed guards who protect the Emperor.' },
                    { id: 'praetorian', name: 'Praetorian Guard', color: '#ff0000', hp: 160, weapon: 'staff', bio: 'Elite guards of Supreme Leader Snoke. Deadly in melee combat.' },
                    { id: 'phasma', name: 'Captain Phasma', color: '#cccccc', hp: 165, weapon: 'blaster', bio: 'Chrome-armored captain of the First Order. Trained Finn and other stormtroopers.' },
                    { id: 'hux', name: 'General Hux', color: '#222222', hp: 120, weapon: 'blaster', bio: 'Arrogant general of the First Order. Desperate to prove himself to Supreme Leader Snoke.' },

                    // --- TROOPERS & SEPARATISTS ---
                    { id: 'stormtrooper', name: 'Stormtrooper', color: '#ffffff', hp: 80, weapon: 'blaster', bio: 'The backbone of the Imperial military. Accurate shots... supposedly.' },
                    { id: 'deathtrooper', name: 'Death Trooper', color: '#444444', hp: 115, weapon: 'blaster', bio: 'Elite special forces stormtroopers. Terrifying and deadly.' },
                    { id: 'incinerator', name: 'Incinerator Trooper', color: '#ff4400', hp: 130, weapon: 'flamethrower', bio: 'Imperial specialist armed with a flamethrower. Turns cover — and enemies — to ash.' },
                    { id: 'starkiller', name: 'Starkiller', color: '#aa22ff', hp: 230, weapon: 'lightning', bio: 'Galen Marek — Vader\'s secret apprentice. Unleashed Force power that can tear starships from the sky.' },
                    { id: 'scouttrooper', name: 'Scout Trooper', color: '#ffffff', hp: 85, weapon: 'blaster', bio: 'Light reconnaissance trooper. Skilled with speeder bikes and long-range weapons.' },
                    { id: 'snowtrooper', name: 'Snowtrooper', color: '#dddddd', hp: 90, weapon: 'blaster', bio: 'Cold assault trooper trained for frozen environments like Hoth.' },
                    { id: 'sithtrooper', name: 'Sith Trooper', color: '#ff0000', hp: 100, weapon: 'blaster', bio: 'Elite soldiers of the Final Order. Fanatically loyal to the Sith Eternal.' },
                    { id: 'grievous', name: 'Gen. Grievous', color: '#00ffcc', hp: 265, weapon: 'lightsaber', saberColor: '#44ff88', weaponDamage: 72, unlockAchievement: 'jediHunter', bio: 'Kaleesh cyborg supreme commander. Hunted Jedi for sport and collected their lightsabers.' },
                    { id: 'b1droid', name: 'B1 Battle Droid', color: '#b6b6b6', hp: 90, weapon: 'zap', isDroid: true, bio: 'Mass-produced battle droid of the Separatist Alliance. Weak in numbers, strong in numbers.' },
                    { id: 'superdroid', name: 'Super Battle Droid', color: '#7f7f7f', hp: 130, weapon: 'zap', isDroid: true, bio: 'Heavier version of the B1. More durable and dangerous.' },
                    { id: 'droideka', name: 'Droideka', color: '#4fd1c5', hp: 170, weapon: 'zap', isDroid: true, bio: 'Destroyer droid with shield generator. Can roll into a ball for rapid deployment.' },
                    { id: 'magnaguard', name: 'MagnaGuard', color: '#9cf542', hp: 160, weapon: 'staff', isDroid: true, bio: 'Grievous\'s elite droid bodyguards. Skilled in melee combat.' },
                    { id: 'bxcommando', name: 'BX Commando Droid', color: '#444444', hp: 130, weapon: 'staff', isDroid: true, bio: 'Elite commando droids used by the Separatists for special operations.' },
                    { id: 'darktrooper', name: 'Dark Trooper', color: '#111111', hp: 180, weapon: 'blaster', isDroid: true, bio: 'Imperial battle droid project. Phase III dark troopers are nearly unstoppable.' },
                    { id: 'hk47', name: 'HK-47', color: '#ff5555', hp: 140, weapon: 'blaster', isDroid: true, bio: 'Assassin droid from the Old Republic era. "Meatbag" is his favorite insult.' },
                    { id: 'greedo', name: 'Greedo', color: '#00ff00', hp: 85, weapon: 'blaster', bio: 'Rodian bounty hunter who tried to collect on Han Solo. Shot first... or did he?' },
                    { id: '4lom', name: '4-LOM', color: '#888888', hp: 130, weapon: 'blaster', isDroid: true, bio: 'Protocol droid turned bounty hunter. Partnered with Zuckuss.' },
                    { id: 'zuckuss', name: 'Zuckuss', color: '#666666', hp: 140, weapon: 'blaster', bio: 'Gand findsman and bounty hunter. Uses mystical traditions to track targets.' },
                    { id: 'fennec', name: 'Fennec Shand', color: '#ff9966', hp: 145, weapon: 'blaster', bio: 'Elite mercenary and assassin. Partner of Boba Fett on Tatooine.' },
                    { id: 'hondo', name: 'Hondo Ohnaka', color: '#ff6600', hp: 125, weapon: 'blaster', bio: 'Pirate leader with a heart of gold... sometimes. "We are only in this for the money."' },
                    { id: 'xizor', name: 'Prince Xizor', color: '#00ff00', hp: 155, weapon: 'blaster', bio: 'Leader of Black Sun and rival to Vader. One of the most powerful crime lords in the galaxy.' },
                    { id: 'gamorrean', name: 'Gamorrean', color: '#cc3333', hp: 95, weapon: 'blaster', weaponDamage: 35, bio: 'Pig-like brute from Gamorr. Loyal guard to crime lords. Strong but not bright.' },
                    { id: 'knightsren', name: 'Knights of Ren', color: '#990000', hp: 180, weapon: 'lightsaber', saberColor: '#ff2200', bio: 'Elite warriors who serve Kylo Ren. Deadly and mysterious.' },
                    { id: 'jet', name: 'Jet Trooper', color: '#0066ff', hp: 95, weapon: 'blaster', bio: 'First Order aerial assault trooper. Equipped with jetpacks for vertical engagement.' },
                    { id: 'firstorder', name: 'FO Officer', color: '#222222', hp: 90, weapon: 'blaster', bio: 'Officer in the First Order military. Ruthless and disciplined.' },

                ],
                secret: [
                    /*  --- MARVEL SEASON ---
                     *  In `secret` rather than in the two faction columns, which is
                     *  where season fighters live: the toggle lifts them into those
                     *  columns while it is on, and visibleSecretChars() drops them from
                     *  the row below, so a fighter has one home rather than two
                     *  depending on a switch. They carry no secretUnlock — the season
                     *  is not something to buy, it is something to switch to.
                     *
                     *  Most of the season has a special on Interact (E / ✋ / Y); see
                     *  UNIBEAM_IDS, WEB_GRENADE_IDS, FLAME_BLAST_IDS, GOD_BLAST_IDS,
                     *  SHAPESHIFT_IDS and HULK_SMASH_IDS. Venom has none on purpose: he
                     *  is the plain melee one, and the claws plus 215 health are the
                     *  whole of what he is. Nick Fury has none either — the Fury Sprite
                     *  is his contribution instead.
                     *
                     *  Thor is the other melee fighter and is NOT a second Venom: the
                     *  hammer comes back when it is thrown, and the God Blast is the
                     *  reach Venom deliberately does without. Loki is the lightest
                     *  fighter in the season because the shape he steals is meant to
                     *  be his health bar, not his own.                              */
                    { id: 'ironman', name: 'Iron Man', color: '#f0a500', hp: 190, weapon: 'repulsor', marvel: true, bio: 'Tony Stark in the suit he built in a cave, forty times over. The Unibeam is the point.' },
                    { id: 'spiderman', name: 'Spider-Man', color: '#e23636', hp: 165, weapon: 'webshooter', marvel: true, bio: 'Fast, light and hard to pin down. The webs are homework that got out of hand.' },
                    { id: 'venom', name: 'Venom', color: '#2a2a33', hp: 215, weapon: 'claws', marvel: true, bio: 'The symbiote and its host, and neither of them is in charge. Gets close, stays close.' },
                    { id: 'mandarin', name: 'The Mandarin', color: '#5bc8d4', hp: 185, weapon: 'iceblast', marvel: true, bio: 'Ten rings, and he does not need all ten. Freezes at range, burns whatever closes.' },
                    // Storm blue rather than the red of the cape: the colour is the
                    // whole sprite here, and a fighter the colour of Spider-Man
                    // standing next to Spider-Man reads as a palette swap. The
                    // saberColour is what Mjølnir trails, so it is the lightning.
                    //
                    // 'brawler' by profile, which for a melee fighter changes how he
                    // takes a hit rather than where he stands: the AI band is already
                    // overridden to the weapon's real reach, so what this buys is a
                    // fighter who does not back off at a quarter health.
                    { id: 'thor', name: 'Thor', color: '#3d6fd0', hp: 205, weapon: 'mjolnir', saberColor: '#dff0ff', marvel: true, tacticalProfile: 'brawler', bio: 'Ask him to leave the hammer in his hand and see how that goes. God Blast on Interact.' },
                    { id: 'loki', name: 'Loki', color: '#2f9e5f', hp: 170, weapon: 'laevateinn', saberColor: '#a8e6b8', marvel: true, tacticalProfile: 'duelist', bio: 'The lightest fighter here, and the only one who can be someone else. Shapeshift on Interact.' },
                    // The third melee fighter in the season, and the one the other two
                    // are measured against now. Venom is ordinary melee damage bought
                    // with health; Thor's hammer comes back when thrown. This is
                    // neither: 115 a landed swing is more than double anything else in
                    // the game, and the entire cost of it is written into the weapon —
                    // a 900ms wind-up and no way at all to touch someone who keeps
                    // walking away. See WEAPON_LIBRARY.gammafists.
                    //
                    // 240 health is the most in the season, which is the one place he
                    // is allowed to be simply better: he has no ranged option, no
                    // thrown option, and every point of damage he deals requires
                    // crossing the floor first. Venom's 215 buys the same trade at a
                    // third of the damage, so the twenty-five point gap is the reach
                    // he does not have.
                    //
                    // Green rather than the purple, for the same reason Thor is storm
                    // blue rather than red: the colour is the whole sprite here, and
                    // the trousers are not the character. saberColor is what the swing
                    // arc trails, so it is the gamma.
                    /*  VAULTED: HULK. Not deleted — the record is the whole of what
                     *  Bruce turns into, so it stays exactly where it is and
                     *  isCharacterRetired() takes it off every roster, every
                     *  opponent list, Surprise Me and Fury's backup pool. The way in
                     *  is Bruce Banner below, and TRANSFORM_FORMS.bruce reads these
                     *  numbers rather than restating them.                         */
                    { id: 'hulk', name: 'Hulk', color: '#4d9e3f', hp: 240, weapon: 'gammafists', saberColor: '#8cff6b', marvel: true, tacticalProfile: 'brawler', vaulted: true, bio: 'Banner is not driving. Nothing hits harder and nothing is slower.' },
                    /*  ── BRUCE BANNER ──────────────────────────────────────────
                     *  The third fighter in the season who is two fighters, and the
                     *  most lopsided of the three — see TRANSFORM_FORMS, which all
                     *  three share:
                     *
                     *    Stane    175 · a stun gun  ->  250 · fists at 75
                     *    Blonsky  160 · a pistol    ->  255 · fists at 82, nothing else
                     *    Banner   140 · a pistol    ->  240 · fists at 82, and a smash
                     *
                     *  140 is the lowest health in the game, one under Maria Hill's
                     *  145, and it should be: he is the only one of the three who is
                     *  not a soldier, a spy or an arms dealer. He is a physicist with
                     *  a sidearm he does not want to be holding, and the entire point
                     *  of him is the button.
                     *
                     *  His Glock is the sixth on the roster and carries no
                     *  `weaponDamage` override, exactly as Blonsky's does not: the
                     *  sidearm is a stopgap he is meant to stop using rather than an
                     *  identity, so it does not need a corner on the triangle Fury,
                     *  Pepper and Hill already fill out.
                     *
                     *  'kiter' rather than Blonsky's 'calculated', and it is the one
                     *  place the pair genuinely differ before the change: Blonsky
                     *  walks toward the problem because Blonsky wants this. Banner
                     *  holds 170-340 and leaves at 45% health, because the whole of
                     *  his pre-transform game is staying alive long enough to not
                     *  need the gun.
                     *
                     *  Lab purple-grey, deliberately nowhere near the #4d9e3f he
                     *  turns into — the step has to read as a different fighter
                     *  arriving, which is the opposite of the Blonsky/Abomination
                     *  pair, where the point was the same thing getting worse.    */
                    { id: 'bruce', name: 'Bruce Banner', color: '#6d6f9c', hp: 140, weapon: 'glock', marvel: true, tacticalProfile: 'kiter', bio: 'A physicist holding a gun he does not want. Interact to stop holding it back, then Interact again to smash.' },
                    // The fourth melee fighter, and the only one who is another
                    // fighter's numbers on purpose. The fists are the Gamma Fists
                    // recoloured — same 82, same 900ms, same 38 reach — so the two of
                    // them are a controlled comparison: identical hands, and the
                    // difference is entirely the health they are carried on and what
                    // Interact does.
                    //
                    // 225 sits between Hulk's 240 and Venom's 215. Clobberin' is the
                    // reason it is not 240: where Hulk's window makes each punch hit
                    // half again as hard, this one makes them land three times as
                    // often and takes the movement penalty off, so it covers ground
                    // as well as damage. That is the more useful of the two windows
                    // in a fight you are losing, and fifteen health is what it costs.
                    //
                    // Rock orange rather than the blue trunks, for the same reason
                    // Thor is storm blue and Hulk is green: the colour is the whole
                    // sprite, and the trousers are not the character. saberColor is
                    // what the punch arc trails, so it is the hot side of the rock.
                    { id: 'thing', name: 'The Thing', color: '#c8763a', hp: 225, weapon: 'thingfists', saberColor: '#ffb066', marvel: true, tacticalProfile: 'brawler', bio: "Ben Grimm, and there is no going back to the other shape. Hits exactly as hard as the big green one and does it far more often. Clobberin' on Interact." },
                    /*  ── WAKANDA ────────────────────────────────────────────────
                     *  A pair, and the first two fighters in the season that are each
                     *  other's answer rather than each other's copy. See
                     *  WEAPON_LIBRARY.pantherclaws and .scimitar — the claws are the
                     *  quick hands with no reach at all, the scimitar is the slow one
                     *  that throws. Neither carries an Interact special, for Venom's
                     *  reason: what each of them is, is entirely in the weapon.       */

                    // 195, and the twenty under Venom is the reach and the weight of
                    // the cut. Venom's claws hit for 28 out to 36 and this set hits for
                    // 24 out to 34; they come 80ms quicker, which is what the health
                    // pays for. Five over Fury's 150 and ten over Spider-Man's 165
                    // puts him where a trained human in powered armour belongs — above
                    // the man with the sidearm, below everything that is not a person.
                    //
                    // 'calculated' by profile rather than the brawler the other melee
                    // fighters get, and it is the right read twice over: he is the
                    // trained, patient one of the pair, and the profile's heavy dodge
                    // and flank are the suit doing what the suit does. Worth saying
                    // plainly that the profile is AI-side only — it changes how he
                    // fights you, not how he feels in your hands.
                    //
                    // Vibranium violet rather than the black of the suit, for the same
                    // reason Thor is storm blue and Hulk is green: the colour is the
                    // whole sprite, and a near-black fighter standing next to Venom's
                    // near-black fighter reads as a palette swap of the one he already
                    // shares a weapon with. saberColor is what the swing arc trails,
                    // so it is the claws.
                    { id: 'blackpanther', name: 'Black Panther', color: '#7b5cc4', hp: 195, weapon: 'pantherclaws', saberColor: '#c3b5e8', marvel: true, tacticalProfile: 'calculated', bio: 'T\'Challa, and the suit is Wakanda\'s rather than his. The quickest hands in the season and no answer whatsoever to someone backing away.' },
                    // 185, the lowest of the season's melee fighters by ten, and the
                    // scimitar is why: it is the only melee weapon on this side of the
                    // roster that can be thrown, so he is the only one of the five who
                    // does not have to be in the fight to be in it. Venom's 215 and the
                    // Panther's 195 both buy a weapon with no reach; thirty and ten
                    // less respectively is what reach costs.
                    //
                    // 'berserker' by profile, and the only fighter in the season with
                    // it. retreatHealthPct 0.08 means he does not back off when he is
                    // nearly dead — he presses, on a 1.15 speed multiplier, with the
                    // dodging mostly switched off. That is the whole character, and it
                    // is also the counterweight to the low health: he will spend it.
                    //
                    // Jaguar gold rather than the black-and-gold of the suit, because
                    // the gold is the half of it that is not already Black Panther.
                    // saberColor is what the swing arc trails, so it is the blade.
                    { id: 'killmonger', name: 'Killmonger', color: '#d4a017', hp: 185, weapon: 'scimitar', saberColor: '#e0b44a', marvel: true, tacticalProfile: 'berserker', bio: 'Erik Stevens, N\'Jadaka, and he has a claim he means to collect. Throws the blade, and it comes back.' },

                    /*  ── GUARDIANS ──────────────────────────────────────────────
                     *  Groot is the second fighter in the game who is built rather than
                     *  picked, and the only one besides Iron Man. His `name`, `weapon`
                     *  and `weaponDamage` are all rewritten by applyGrootLevel() at load
                     *  and on every claim, so the four fields below are the LEVEL 1
                     *  record and nothing more — the entry a save with no progress in it
                     *  starts from. See GROOT_POOL for the board that moves them.       */

                    // 235 at every level, flat, and deliberately so: the upgrade axis is
                    // the fists and only the fists. That is Iron Man's own early phase
                    // copied honestly — the Mk 1 through Mk 5 all sit at 190 while the
                    // fire scales, and the suit does not start growing until the fire
                    // stops. Groot never reaches a second phase, so his health never
                    // moves at all.
                    //
                    // 235 rather than the 210 this shipped with. He is the only melee
                    // fighter in the season with no Interact special AND no reach until
                    // level 5, and he is the only fighter of any kind who has to be
                    // built before he is worth picking — the health is what pays for
                    // all three. It puts him second on the roster behind Hulk's 240 and
                    // ten over The Thing, which is the right order: those two hit
                    // harder than he does and both have a button.
                    //
                    // A level 1 Groot is still meant to be weak — 14 a punch and
                    // nothing on Interact — but weak is not the same as pointless, and
                    // at 10 a punch on 210 health it was the latter.
                    //
                    // Moss green, and it was bark brown until it was looked at on a
                    // screen. Wakanda's ground runs #8a6132 to #56391f, and a brown
                    // fighter standing on it disappeared — the sprite's own shading
                    // takes the colour down again, so dark brown on mid brown left
                    // nothing to see. In-arena legibility wins over grid variety here,
                    // because it is paid every fight rather than once at the picker.
                    //
                    // Kept well clear of Hulk's #4d9e3f all the same, since the two sit
                    // three tiles apart in the same column: this is pale and yellow
                    // where his is saturated and deep — the moss on the bark rather than
                    // the gamma. saberColor is the Stormbreaker's trail at level 5; the
                    // fists draw no beam at all (the 'fists' family has no blade), so it
                    // is unused until then.
                    { id: 'groot', name: 'Groot', color: '#8fbf5e', hp: 235, weapon: 'grootfists', saberColor: '#cfe6ff', marvel: true, tacticalProfile: 'brawler', bio: 'A sapling with a board to work through. Four contracts of getting harder to hit, and then the axe.' },
                    // The lightest fighter in the game bar none — five under Nick Fury,
                    // who held the record — and the biggest gun on the roster is what he
                    // is carrying. That is the whole character: he cannot take a hit and
                    // he does not intend to be where one lands.
                    //
                    // Raccoon grey rather than a brown, for the same reason Groot stopped
                    // being one: the pair arrive together and were both sinking into the
                    // same ground. Grey is free in this column — every other grey on the
                    // roster is a Star Wars trooper — and it throws the cannon's magenta
                    // forward, which is the half of him a player actually has to read.
                    //
                    // 'kiter' by profile, which for a ranged fighter is the real stat:
                    // a 170-340 band, the heaviest dodging and flanking multipliers in
                    // the table, and a retreat at 45% health. He leaves early and often.
                    { id: 'rocket', name: 'Rocket Raccoon', color: '#9aa3ad', hp: 145, weapon: 'lasercannon', marvel: true, tacticalProfile: 'kiter', bio: 'Do not call him a raccoon. The cannon is bigger than he is and that is not an accident.' },
                    /*  ── STAR-LORD ─────────────────────────────────────────────
                     *  THE FIRST MARVEL FIGHTER WITH A PRICE ON HIM, and that is a
                     *  deliberate break from the rule stated at MARVEL_SEASON: the
                     *  season shipped free with the faction toggle as the whole of
                     *  the gate. He carries a `secretUnlock` like a pack's cast
                     *  did, so he sits in the Avengers column as a locked hint
                     *  button until he is bought, and the toggle itself is
                     *  unaffected — ownsAnyMarvelCharacter() still answers yes off
                     *  the seventeen free fighters beside him.
                     *
                     *  170, which is the top of the season's un-powered bracket and
                     *  below everything enhanced: over Spider-Man's 165 and Pepper's
                     *  165, under Bucky's 180. Right for a man with no powers, a very
                     *  good jacket and the best guns on the roster — the Quad
                     *  Blasters are what he is, so the health is not also allowed to
                     *  be the reason to pick him.
                     *
                     *  'duelist' for Black Widow's reason exactly, because he has her
                     *  problem twice over: a 60-140 band, because a 0.30 arc across
                     *  four rounds only pays inside it. He is a ranged fighter the
                     *  AI walks into knife range, and that is the character —
                     *  everything he does is loud and close.
                     *
                     *  Ravager rust-red for the coat. Said plainly: this column is
                     *  out of colours and has been since Bucky, and this sits nearer
                     *  The Thing's #c8763a than anything else in it. It is redder
                     *  where his is orange, and the two are never confusable in
                     *  motion — one is a rock the size of a door — but if they ever
                     *  do read as the same fighter, this is the one to move.      */
                    { id: 'starlord', name: 'Star-Lord', color: '#c9553d', hp: 170, weapon: 'quadblaster', marvel: true, tacticalProfile: 'duelist', secretUnlock: 'starlord', bio: 'Peter Quill, and he would rather you used the name. Four barrels, and everything he hits goes off.' },
                    // One of the two fighters in the season with no powers — it was
                    // "the one" until Pepper turned up below with the same sidearm —
                    // and the health says so: 150 is the lowest on this side of the
                    // roster bar Rocket.
                    // What he has instead is a sidearm he is very good with and the
                    // phone numbers of everyone else in the column — see the Fury
                    // Sprite in SPRITE_CATALOG, which is where the assembling lives.
                    // He carries no Interact special himself on purpose: the sprite is
                    // his contribution, and a sprite anyone can equip is a better
                    // version of that idea than a button only he gets.
                    //
                    // 'calculated' by profile — patient, precise, heavy on the dodge —
                    // which is what a man with a handgun has to be in this company.
                    { id: 'fury', name: 'Nick Fury', color: '#3f4a5c', hp: 150, weapon: 'glock', marvel: true, tacticalProfile: 'calculated', bio: 'No suit, no hammer, no symbiote. One sidearm, one eye, and everybody else on call.' },
                    // The second Glock, and it is the same Glock — the key, not a copy
                    // of it. Two fighters sharing one weapon key is ordinary here;
                    // forty of them share `blaster`. What separates the two carriers is
                    // `weaponDamage`, which is the roster's own way of saying "this one
                    // handles it differently" and is already how Jango's elite, the
                    // Gamorrean and Vader's elite all differ from their base weapon.
                    //
                    // So the pair is an explicit trade rather than a tier. Fury shoots
                    // for 15 on 150 health; she shoots for 12 on 165. He ends fights
                    // faster, she is harder to end — 60 dps against his 75, bought with
                    // fifteen more health. Neither is the other with a worse number.
                    //
                    // 165 on the person in this column least likely to have held a gun
                    // before looks wrong until you remember she has Extremis in her:
                    // she is not better trained than the Director of S.H.I.E.L.D. and
                    // the damage says so, she is just very hard to put down.
                    //
                    // 'kiter' rather than Fury's 'calculated', which is the whole
                    // difference in how the two fight: he closes to 90-190 and stays
                    // there, she holds 170-340 and leaves at 45% health. A trained
                    // shooter walks toward the problem; she does not.
                    //
                    // Warm rose because it is the one warm hue this column has left —
                    // amber, red, orange, moss and violet are all spoken for — and
                    // because she would otherwise be a third grey standing between
                    // Rocket and Fury.
                    { id: 'pepper', name: 'Pepper Potts', color: '#e07a8f', hp: 165, weapon: 'glock', weaponDamage: 12, marvel: true, tacticalProfile: 'kiter', bio: 'Ran the company while he played in the workshop. Picks the gun up when it is the thing that needs doing.' },
                    // 150, the same as Fury exactly, and that is the point of the pair:
                    // two S.H.I.E.L.D. men with no powers between them, identical to
                    // put down, and the entire difference is what they are holding.
                    // Fury's sidearm is 75 sustained dps in fifteens; this is 50 in one
                    // 55 that crosses the room. Neither is a tier above the other, they
                    // are the fast answer and the final one.
                    //
                    // 'calculated' rather than a third profile invented for him. It is
                    // Fury's, and it is right twice: the patient, precise band is what
                    // a man with one shot fights in, and alwaysPredictive is close to
                    // required on a projectile this slow — see WEAPON_LIBRARY.destroyergun.
                    //
                    // Teal, because the column had run out of anything else. Amber,
                    // red, blue, green, orange, violet, moss and rose are all taken,
                    // and a dark suit would have made him the third grey silhouette
                    // standing next to Fury and Rocket.
                    { id: 'coulson', name: 'Agent Coulson', color: '#3f9c8f', hp: 150, weapon: 'destroyergun', marvel: true, tacticalProfile: 'calculated', bio: 'Level Seven. Brought the prototype down off the shelf and asked Loki if he wanted to see what it did.' },
                    // The third Glock, which makes the sidearm the most carried weapon
                    // in the season — and the three of them are a triangle rather than
                    // a queue. Every one is the same gun key with its own
                    // `weaponDamage`, so the whole spread lives in two numbers each:
                    //
                    //   Fury    150 hp · 15 a round · 75 dps — the middle of it
                    //   Pepper  165 hp · 12 a round · 60 dps — survives, does not finish
                    //   Hill    145 hp · 17 a round · 85 dps — finishes, does not survive
                    //
                    // She is the best shot of the three because she is the only one of
                    // the three who does it for a living; Fury runs an agency and
                    // Pepper runs a company. 145 is the price and it is the lowest
                    // health in the season — one point under Rocket, who at least gets
                    // to stand 340px away while he works.
                    //
                    // 'disciplined' is what the weapon fallback would have given her
                    // anyway, and it is stated rather than left implied for the same
                    // reason the Assault Rifle states it: a match that happens to be
                    // right is one edit away from being wrong. It is also the honest
                    // profile — trained soldier, holds a sane mid-range, uses cover.
                    //
                    // Deep crimson. The column's other reds are Spider-Man's scarlet
                    // and Pepper's pale rose, and this is neither; navy tactical gear
                    // would have put her on top of Fury's slate.
                    { id: 'hill', name: 'Maria Hill', color: '#9e3b52', hp: 145, weapon: 'glock', weaponDamage: 17, marvel: true, tacticalProfile: 'disciplined', bio: 'Deputy Director, and the only one of the three who shoots for a living. Hits hardest, folds fastest.' },
                    // 160, which is the middle of the three people here with no powers
                    // — over Hill's 145, under Pepper's 165 — and right where a man who
                    // has to stand still to do his job belongs. A full draw is 1200ms
                    // spent at 45% movement speed, so his health is partly paying for
                    // the fact that the best thing he does cannot be done while moving.
                    //
                    // 'calculated' rather than 'kiter', and the difference matters more
                    // for him than for anyone else on the roster: `alwaysPredictive`
                    // makes the AI lead its target. An arrow that has to be aimed where
                    // someone will be is the entire weapon. The 90-190 band also keeps
                    // an AI Hawkeye inside the bow's uncharged 380 reach — the AI never
                    // charges, so a kiter's 170-340 would have left him plinking from
                    // outside his own range half the time.
                    //
                    // Bow-stave gold. The column is nearly out of hues, and this is the
                    // one it did not have: a warm desaturated tan that is neither Iron
                    // Man's amber nor The Thing's orange, and reads clearly against both
                    // Wakanda's brown and the dark arenas.
                    { id: 'hawkeye', name: 'Hawkeye', color: '#c8a24a', hp: 160, weapon: 'bow', marvel: true, tacticalProfile: 'calculated', bio: 'Hold the trigger and the shot grows teeth. Let it go early and it falls out of the air short.' },
                    // 155, between Coulson's 150 and Hawkeye's 160, and the fourth
                    // fighter in this column with no powers and a handgun. The health
                    // is nearly the only thing ordinary about her: the Dual Glocks are
                    // the hardest close-range sidearm in the game and the worst one
                    // past mid-range, so what she actually costs is having to be there.
                    //
                    // 'duelist' is the point of her, not a detail. It is a 60-140 band
                    // — the closest any ranged fighter on the roster is asked to stand
                    // — and it exists because her weapon's spread only pays inside it.
                    // Fury holds 90-190 and shoots straight; she walks into knife range
                    // and puts two rounds in. Loki is otherwise the only duelist in the
                    // season, which suits: they are the two who close.
                    //
                    // Near-white for the Endgame suit, and because it is the only thing
                    // this column had left. Every warm hue is taken twice over, the
                    // greys belong to Rocket and Fury, and a black-suit Widow would
                    // have been the thing Groot already had to stop being — a dark
                    // fighter that vanishes into a dark arena.
                    { id: 'widow', name: 'Black Widow', color: '#dce6f2', hp: 155, weapon: 'dualglocks', marvel: true, tacticalProfile: 'duelist', bio: 'Red in her ledger and a pistol in each hand. Gets close enough that both of them land.' },
                    // 200, second only to Thor among the season's non-monsters, and the
                    // shield is why it is not higher: he is the only melee fighter here
                    // who can turn a bolt aside mid-swing, so some of what would have
                    // been health is sitting in `deflects` instead. The weapon is also
                    // the softest melee in the season at 59 dps for the same reason —
                    // he pays for the block twice, once in health and once in damage.
                    //
                    // 'duelist' rather than a third brawler or a fourth calculated. The
                    // 60-140 band is balanced and closes, the 0.25 retreat means he
                    // does not back off early, and the dodge and flank multipliers stay
                    // at 1.0 — he does not need to roll out of things, he has a shield.
                    //
                    // Flag blue, and it sits closer to Thor's storm blue than anything
                    // else in this column does to its neighbour. The warm half of the
                    // spectrum is spoken for three times over and the greys belong to
                    // Rocket, Fury and Widow, so this is what was left. Deeper and more
                    // saturated than Thor's #3d6fd0, which is a periwinkle — but if the
                    // two read as the same fighter at speed, this is the one to change.
                    { id: 'cap', name: 'Captain America', color: '#2a5cae', hp: 200, weapon: 'shield', saberColor: '#dfe7ee', marvel: true, tacticalProfile: 'duelist', bio: 'Throws it, catches it, and stands behind it in between. Could do this all day.' },
                    /*  The fourth Glock, and the last one this weapon can carry. The
                     *  first three were a triangle with real corners:
                     *
                     *    Fury    150 hp · 15 · 75 dps — the middle of it
                     *    Pepper  165 hp · 12 · 60 dps — survives, does not finish
                     *    Hill    145 hp · 17 · 85 dps — finishes, does not survive
                     *
                     *  There is no fourth corner. Peggy is placed honestly as the
                     *  midpoint of Fury and Pepper — 160 and 14, so 70 dps — which
                     *  makes her a sidegrade rather than a new idea, and that is
                     *  stated here rather than dressed up. A fifth would have nothing
                     *  left at all; the next sidearm carrier needs a different gun.
                     *
                     *  'calculated', which is Fury's own profile and shared on purpose:
                     *  she founded the agency he would end up running, and the patient,
                     *  heavy-dodge band is the same answer to the same problem — a
                     *  trained human holding a pistol in a fight full of gods.
                     *
                     *  Khaki, for the SSR, and because it was genuinely the last unused
                     *  hue in this column. See the note on Bucky below.              */
                    { id: 'peggy', name: 'Peggy Carter', color: '#9a9654', hp: 160, weapon: 'glock', weaponDamage: 14, marvel: true, tacticalProfile: 'calculated', bio: 'Founded the agency the rest of them answer to. Still the steadiest hand in the room.' },
                    // 180, under Cap's 200 and over everything else here without a
                    // suit. He has the same serum Cap does, which is what buys the gap
                    // over the ordinary humans; what he does not have is the shield,
                    // which is what the twenty to Cap pays for.
                    //
                    // The Submachine Gun is the fastest trigger in the game at 92ms —
                    // 98 dps flat out, above every other gun here — and the magazine is
                    // the whole of what keeps it honest: thirty rounds is 2.8 seconds
                    // of fire, then 2.4 seconds of nothing. He is the only fighter in
                    // the season whose danger is a countdown.
                    //
                    // 'disciplined' — the trained-soldier band at 100-220, cover use,
                    // no panic. It is Hill's profile too, and the two of them are the
                    // only fighters here who were actually soldiers.
                    //
                    // Gunmetal blue for the arm. Worth saying plainly: this column is
                    // out of colours. Sixteen fighters have taken every warm hue twice
                    // over, both greys, the violet, the moss and the teal, and this is
                    // a muted blue sitting between Fury's slate and Cap's flag blue.
                    // It is distinguishable rather than distinct, and if Bucky and Cap
                    // read as the same fighter in motion, one of them has to move.
                    { id: 'bucky', name: 'Bucky Barnes', color: '#68809b', hp: 180, weapon: 'submachine', marvel: true, tacticalProfile: 'disciplined', bio: 'The arm is the least of it. Thirty rounds, and he does not miss with many of them.' },
                    /*  A VILLAIN, and placed in that column rather than this one —
                     *  he is the man who had Tony killed and took the company. It also
                     *  solves a problem the hero column has and the villain column does
                     *  not: four fighters over there against seventeen here, so there
                     *  is still colour left to give him.
                     *
                     *  175 is the lowest health of any villain in the season and lower
                     *  than every hero bar Rocket and Hill, and the Sonic Taser is the
                     *  second-weakest gun in the game. Both are on purpose: everything
                     *  Stane is worth is on the Interact key. Until he presses it he is
                     *  a man in a suit holding a stun gun, and after it he is 250 health
                     *  swinging the second-hardest fists on the roster.
                     *
                     *  'calculated' for the half of the round before that — patient,
                     *  heavy on the dodge, staying out of reach. IRON_MONGER_IDS
                     *  overrides it to 'brawler' the moment he transforms, because the
                     *  suit has no reason to keep its distance.
                     *
                     *  Rust, for the foundry, and chosen to be as far from the Iron
                     *  Monger's gunmetal as the palette allows: the whole point of the
                     *  transform is that you can see it happen.                       */
                    { id: 'stane', name: 'Obadiah Stane', color: '#b0553a', hp: 175, weapon: 'sonictaser', marvel: true, tacticalProfile: 'calculated', bio: 'Signed the cheques, armed both sides, and built a bigger one in the basement. Interact to get in it.' },
                    /*  The second villain who is two fighters, and the pair is on
                     *  purpose — see TRANSFORM_FORMS, which they share. Both spend the
                     *  opening of a round as an ordinary man and the rest of it as
                     *  something that should not be allowed, and the difference is
                     *  what each is before and after:
                     *
                     *    Stane    175 · a stun gun   ->  250 · fists at 75, nothing else
                     *    Blonsky  160 · a pistol     ->  255 · fists at 82, nothing else
                     *
                     *  So Stane is the earlier, softer transform with a tool in front
                     *  of it, and Blonsky is the harder one with an answer to range
                     *  behind it. 160 is the price of that: he is the most fragile
                     *  fighter in the season until he is the least.
                     *
                     *  His Glock is the fifth on the roster, which is one more than the
                     *  weapon had room for — and it is fine here for the same reason
                     *  Stane's taser is: neither of them is a sidearm character. It is
                     *  a stopgap he is meant to stop using, not an identity, so it does
                     *  not need a corner of its own on the triangle. No `weaponDamage`
                     *  override for exactly that reason — he carries Fury's, plainly.
                     *
                     *  'calculated' before, 'brawler' after, applied by the transform.
                     *
                     *  Sickly yellow-green, well clear of Loki's #2f9e5f — the villain
                     *  column's only other green — and chosen so the step to the
                     *  Abomination's deeper #6f8f3a reads as the same thing getting
                     *  worse rather than as a different fighter.                      */
                    /*  ── LAUFEY ────────────────────────────────────────────────
                     *  King of the Frost Giants, and Loki’s father — which is the
                     *  reason he is in this column rather than a new one. The season’s
                     *  villains are symbiotes, rings and stolen thrones, and a stolen
                     *  throne is exactly what he and his son are arguing about.
                     *
                     *  205, second only to Venom’s 215 among the villains and above
                     *  every other one. He is a giant and should read as one. It is
                     *  not 215, because he is the only fighter here who can take a
                     *  turn away from you — the ten points are the second half of
                     *  what the freeze costs, the first being his damage.
                     *
                     *  ‘brawler’, and it is forced by the weapon rather than chosen:
                     *  reach 30 with no thrown option and nothing at range means the
                     *  AI has to close or do nothing at all. The profile also keeps
                     *  him coming at a quarter health, which is the right read on a
                     *  king who does not believe he can lose to his own son.
                     *
                     *  Glacial blue, kept deliberately deep and cold. The Mandarin’s
                     *  #5bc8d4 is the other ice in this column and it is a bright
                     *  cyan; this is the colour under a glacier rather than the
                     *  colour of a ring going off. saberColor is what the swing arc
                     *  trails, so it is the frost coming off the blade.           */
                    { id: 'laufey', name: 'Laufey', color: '#3f6f9e', hp: 205, weapon: 'icedagger', saberColor: '#bfe9ff', marvel: true, tacticalProfile: 'brawler', bio: 'King of the Frost Giants, and the father Loki will not admit to. The cold does not kill you — it holds you still while he closes.' },
                    { id: 'blonsky', name: 'Emil Blonsky', color: '#a8bf4a', hp: 160, weapon: 'glock', marvel: true, tacticalProfile: 'calculated', bio: 'Took the first dose and asked for more. Interact for the rest of it.' },
                    /*  ── RED SKULL ──────────────────────────────────────────────
                     *  Johann Schmidt, head of Hydra, and the first villain in the
                     *  season who is a soldier rather than a monster or a king. Free
                     *  with the toggle like the rest of the column, not locked.
                     *
                     *  170, a shade over Blonsky's 160 and Fury's 150: he took the
                     *  serum before Rogers did, so he is tougher than a man with a
                     *  gun, but he is still a man with a gun and not a giant.
                     *
                     *  'calculated', the same as Fury and Blonsky. A sidearm wants
                     *  range and patience, and the Hydra Pistol's short magazine
                     *  punishes the AI for spraying anyway.
                     *
                     *  Deep crimson, kept darker than Ant-Man's #c0392b and well
                     *  clear of Stane's rust #b0553a, so the skull reads as blood
                     *  red rather than as either of them.                          */
                    { id: 'redskull', name: 'Red Skull', color: '#9e1b1b', hp: 170, weapon: 'hydrapistol', marvel: true, tacticalProfile: 'calculated', bio: 'Johann Schmidt. Took the serum first and wore what it did to him as a face. Cut off one head and two more shall take its place.' },
                    /*  ── RAGNAROK ───────────────────────────────────────────────
                     *  The Thor clone from Civil War, built from a strand of his
                     *  hair, and a straight copy of him on purpose: same 205 health,
                     *  same Mjølnir, same God Blast (see GOD_BLAST_IDS), same
                     *  'brawler' profile and so the same AI. Nothing about how he
                     *  plays is allowed to drift from Thor's — if Thor is retuned,
                     *  retune this line with him.
                     *
                     *  The one difference is the colour, and it is only there so
                     *  the mirror match is readable: a gunmetal navy, well darker
                     *  than Thor's #3d6fd0, for the black armour the clone wore.
                     *  Free with the toggle, like Red Skull.                        */
                    { id: 'ragnarok', name: 'Ragnarok', color: '#2b3550', hp: 205, weapon: 'mjolnir', saberColor: '#dff0ff', marvel: true, tacticalProfile: 'brawler', bio: 'A clone of Thor, built from a strand of his hair. Same hammer, same lightning, none of the restraint. God Blast on Interact.' },
                    /*  ── THANOS ─────────────────────────────────────────────────
                     *  The Mad Titan, and the fighter the whole splash screen is
                     *  about: the Snap intro is his. Sold in the Shop rather than
                     *  free with the toggle, the same as Star-Lord, so the column
                     *  shows him as a locked hint until he is bought.
                     *
                     *  230 puts him over Venom's 215, the top of the villains, and
                     *  under the 240 Bruce Banner becomes as the Hulk. A Titan
                     *  should be the hardest thing on his side to put down. He is
                     *  not the hardest in the season, because the Snap means the
                     *  fight may never get that far.
                     *
                     *  'brawler' for the same reason as Laufey: fists with no
                     *  throw leave the AI nothing to do but close. An AI Thanos
                     *  punches and never snaps, which is the season's rule for
                     *  every Interact special (see SNAP_IDS). A coin toss that
                     *  ends the round is something to hold, not to be handed.
                     *
                     *  Purple for the skin. Nothing else in the Marvel columns is
                     *  violet. Zero's #a274ff is the nearest, and he lives in the
                     *  secret row, so the two are never side by side.            */
                    { id: 'thanos', name: 'Thanos', color: '#7b5ea7', hp: 230, weapon: 'gauntletfists', saberColor: '#e3b341', marvel: true, tacticalProfile: 'brawler', secretUnlock: 'thanos', bio: 'Perfectly balanced, as all things should be. Interact to Snap: half the time, whoever is standing across from him is simply gone.' },
                    /*  ── ETERNITY ───────────────────────────────────────────────
                     *  The universe, in a form that can stand in an arena. Neither
                     *  side's, which is why her Interact draws from BOTH columns.
                     *  She is listed under the heroes only because a fighter has to
                     *  live in exactly one column (validate.js checks it), and she
                     *  is the one who ends up standing with whoever she calls.
                     *
                     *  180 is deliberately modest for the dearest fighter in the
                     *  Shop. She never fights alone for long: Interact puts a second
                     *  fighter on the field whenever the last one is down, and the
                     *  staff's opening hit can take half a bar. Her own health is the
                     *  one place left to charge for all of that.
                     *
                     *  'kiter': a slow ranged trigger wants distance, and the ally
                     *  she calls is the one meant to be standing in the middle.
                     *  An AI Eternity uses the staff but never summons, which is
                     *  the season's rule for every Interact special.
                     *
                     *  A cosmic blue, the one colour neither column is using. */
                    { id: 'eternity', name: 'Eternity', color: '#6f86ff', hp: 180, weapon: 'realitystaff', saberColor: '#9fb2ff', marvel: true, tacticalProfile: 'kiter', secretUnlock: 'eternity', bio: 'The universe, given a shape. Every hit rolls from nothing to everything the target has left. Interact to call a fighter from either side, one at a time, as often as they fall.' },
                    /*  ── ANT-MAN ───────────────────────────────────────────────
                     *  Scott Lang, free with the Marvel toggle like the rest of the
                     *  Avengers. The only fighter in the game with two specials:
                     *  Q grows him into Giant-Man and E shrinks him, 15 seconds
                     *  each, then he is back to normal. Q is free for it because
                     *  his fists are noThrow, so the throw key had nothing to do.
                     *
                     *  He also calls ants, the way playable Jabba calls Gamorrean
                     *  guards: one every 2.2 seconds, never more than six standing.
                     *  Each ant hits for exactly 2. See ANT_SPAWN_MS.
                     *
                     *  170, the middle of the Avengers. Giant-Man is a bigger target
                     *  as well as a harder hitter, and the ants soak attention, so
                     *  the health itself needs to be nothing special.
                     *
                     *  'brawler': fists, so the AI has to close. An AI Ant-Man never
                     *  resizes (the season's rule for specials) but does call ants,
                     *  because those are automatic rather than a button.        */
                    { id: 'antman', name: 'Ant-Man', color: '#c0392b', hp: 170, weapon: 'antmanfists', saberColor: '#ff7a66', marvel: true, tacticalProfile: 'brawler', bio: 'Scott Lang, and the suit does the heavy lifting. Q to go giant, E to go small, fifteen seconds each. The ants come on their own.' },
                    /*  ── DEADPOOL ──────────────────────────────────────────────
                     *  Wade Wilson, and the only fighter in the game with two
                     *  weapons: the Dual Katanas and the Glock, swapped on Interact
                     *  (E by default). See WEAPON_SWAP_IDS for the swap itself.
                     *
                     *  Free with the toggle like the rest of the column, not locked.
                     *
                     *  150, at the bottom of the column with Fury and Coulson. Two
                     *  weapons is the advantage, so the bar is where it is paid for:
                     *  he always has the right tool for the range and never the
                     *  health to stand there long with it.
                     *
                     *  The Glock is the same Glock everyone else carries — the key,
                     *  not a copy — and like Blonsky's it is not his identity, so it
                     *  takes no corner of the sidearm triangle either.
                     *
                     *  'duelist', the 60-140 band. It is the one profile that suits
                     *  both halves: close enough for the swords to matter, far
                     *  enough that the gun is not wasted.
                     *
                     *  Bright saturated red, deliberately not Ant-Man's brick
                     *  #c0392b, which is the other red in this column.           */
                    { id: 'deadpool', name: 'Deadpool', color: '#d4142a', hp: 150, weapon: 'katanas', saberColor: '#d8dee6', marvel: true, tacticalProfile: 'duelist', bio: 'Wade Wilson. Two swords, one Glock, no filter. Interact to switch between them.' },

                    /*  ── THE HALLOWEEN SEASON ─────────────────────────────────
                     *  Six fighters in two mirrored lines — a skeleton, a general
                     *  and a lord on each side — with the villains' half burnt.
                     *  Every one of them carries a shield, up while Interact is
                     *  held and back down the moment it is let go (see
                     *  HALLOWEEN_SHIELD_IDS), and the four commanders raise
                     *  skeletons on Q once a round (see HALLOWEEN_SUMMONS).
                     *
                     *  The two sides are the same numbers on purpose, the way Thor
                     *  and Ragnarok are: retune a line and retune its mirror. What
                     *  tells them apart is the look and Wheen's 2% call.
                     *
                     *  110 for a skeleton is low because a skeleton is mostly what
                     *  the generals bring with them: three at once off a Lord is
                     *  330 health of extra bodies, and the shield is most of what
                     *  keeps one standing. The generals sit at 190, a shade over a
                     *  clone commander, and the lords at 230 — the extra 40 and the
                     *  third skeleton are the whole of what five wins buy.
                     *
                     *  `arenaName` is for the name plate: it cuts at sixteen
                     *  characters, and "Skeleton Warrior" is exactly sixteen, but
                     *  three Burnt Skeleton Warriors would all read "Burnt
                     *  Skeleto…". The Shop, roster and announcements keep the
                     *  full name. */
                    { id: 'skeleton', name: 'Skeleton Warrior', color: '#e8e2cf', hp: 110, weapon: 'skeletonsword', saberColor: '#d9dde2', halloween: true, tacticalProfile: 'brawler', bio: 'Bone, a sword and a shield, and nothing left to lose. Hold Interact to raise the shield.' },
                    { id: 'hawlo', name: 'General Hawlo', color: '#ff8c1a', hp: 190, weapon: 'halloweenblaster', halloween: true, tacticalProfile: 'disciplined', bio: 'Commands the Bone Guard from behind a shield. Hold Interact to block, and Q raises two Skeleton Warriors once a round.' },
                    { id: 'lordtreat', name: 'Lord Treat', color: '#ffc21a', hp: 230, weapon: 'halloweenblaster', halloween: true, tacticalProfile: 'calculated', secretUnlock: 'lordtreat', bio: 'Lord of the Bone Guard. Hold Interact to block, and Q raises three Skeleton Warriors once a round.' },
                    { id: 'burntskeleton', name: 'Burnt Skeleton Warrior', arenaName: 'Burnt Skeleton', color: '#3c3c40', hp: 110, weapon: 'skeletonsword', saberColor: '#b9b2aa', halloween: true, tacticalProfile: 'brawler', bio: 'A Skeleton Warrior that went through the fire and kept the heat. Hold Interact to raise the shield.' },
                    { id: 'wheen', name: 'General Wheen', color: '#7a2fbf', hp: 190, weapon: 'halloweenblaster', halloween: true, tacticalProfile: 'disciplined', bio: 'Commands the Burnt Legion. Hold Interact to block, and Q raises two Burnt Skeleton Warriors once a round. Now and then Lord Trick answers too.' },
                    { id: 'lordtrick', name: 'Lord Trick', color: '#9b1b4a', hp: 230, weapon: 'halloweenblaster', halloween: true, tacticalProfile: 'calculated', secretUnlock: 'lordtrick', bio: 'Lord of the Burnt Legion. Hold Interact to block, and Q raises three Burnt Skeleton Warriors once a round.' },

                    /*  Reachable only by redeeming ZERO in Settings, which is also the
                     *  only door left to the event he is named for. No `marvel` flag on
                     *  purpose — he is what the Zero Point left behind, not part of the
                     *  season, so he belongs in the secret row rather than in a column
                     *  the toggle swaps.
                     *
                     *  235, and the gate is the argument. A redeem code is the rarest
                     *  door in the game — rarer than the Shop, rarer than an
                     *  achievement — and what came through it was a 200 health
                     *  fighter holding a re-skinned blaster. That put him under
                     *  Captain America and Thor, who cost nothing but the toggle.
                     *
                     *  235 places him against the company he actually keeps: below
                     *  Ultimate Palpatine's 280, level with the heaviest things on
                     *  the roster, and clear of everything freely picked. It is not
                     *  a boss number — the Cousin Crew's 500 is what that looks
                     *  like — it is the top of the playable range.               */
                    { id: 'zero', name: 'Zero', color: '#a274ff', hp: 235, weapon: 'zeroenergy', secretUnlock: 'zeroUnit', bio: 'The Zero Point was fractured, not wiped. What came back through is not finished with anyone.' },

                    { id: 'ultimate_palp', name: 'Ultimate Emperor Palpatine', color: '#9900ff', hp: 280, weapon: 'lightning', saberColor: '#9900ff', weaponDamage: 32, isDroid: false, secretUnlock: 'ultimatePalpatine', bio: 'The Emperor at his full power. Unleashed only by defeating the dark protocols of Sith C-3PO.' },
                    { id: 'charred_anakin', name: 'Charred Anakin', color: '#4a0000', hp: 160, weapon: 'lightsaber', saberColor: '#0066ff', isDroid: false, secretUnlock: 'charredAnakin', bio: 'Anakin Skywalker after his defeat on Mustafar. Scarred and broken, but still powerful.' },
                    { id: 'senator_palpatine', name: 'Senator Palpatine', color: '#c8a84b', hp: 95, weapon: 'blaster', isDroid: false, secretUnlock: 'senatorPalpatine', bio: 'The Chancellor before revealing his true identity. Deceptively mild-mannered.' },
                    { id: 'jabba', name: 'Jabba the Hutt', color: '#a67a1c', hp: 260, weapon: 'guards', isDroid: false, secretUnlock: 'jabbaUnlock', bio: 'Crime lord of Tatooine. Massive, wealthy, and utterly ruthless. Fights through his loyal guards.' },
                    { id: 'tarfful', name: 'Tarfful', color: '#8b7355', hp: 225, weapon: 'bowcaster', isWookiee: true, secretUnlock: 'tarffulUnlock', bio: 'Wookiee chieftain and longtime friend of Chewbacca. Fiercer and stronger than most Wookiees.' },
                    { id: 'cousin_crew', name: 'Cousin Crew', color: '#808080', hp: 500, weapon: 'computer', isDroid: false, secretUnlock: 'devTeam', bio: 'The developers themselves. Unlocked only by those who know the secret ways.' },


                ],
                unplayable: [
                    // Frozen solid: no weapon, and no health bar in the HUD. He is
                    // scenery to be freed, not an opponent to be worn down, and a
                    // ticking HP bar over him invites the player to shoot the thing
                    // they are supposed to walk up to.
                    { id: 'carbonite_han', name: 'Carbonite Han', color: '#888888', hp: 180, weapon: 'unarmed', isFrozen: true, noHealthBar: true, bio: 'Han Solo, frozen in carbonite at Cloud City. A trophy bound for Jabba\'s palace — if he ever leaves this platform.' },
                    { id: 'sith_c3po', name: 'Sith C-3PO', color: '#ffd700', hp: 320, weapon: 'zap', isDroid: true, weaponDamage: 24, bio: 'C-3PO corrupted by dark protocols. A nightmare version of the beloved droid.' }
                ]
            };

            // Every table a pack merges into exists by now, and nothing has read
            // the roster yet, so this is the moment to fold one in.
            applyContentPack();

            // Villain lookup for the Sith aura in Character.draw(). That ran a linear
            // scan of the ~70-entry villain list per entity per frame — with backup
            // squads on the field that is 10+ entities × 70 comparisons × 60fps.
            // Built as a Set rather than an isVillain flag on the constructor because
            // characterId is assigned after construction in several spawn paths, so a
            // constructor-time flag would be stale for exactly those entities.
            const VILLAIN_ID_SET = new Set(characters.villains.map(c => c.id));

            // Build Menus
            let mobilePreviewState = { active: false, char: null, btn: null };
            
            // Favorites management
            let favorites = new Set();
            
            function loadFavorites() {
                try {
                    const saved = loadVersioned('galacticDuelFavorites', null);
                    if (Array.isArray(saved)) {
                        favorites = new Set(saved.filter(id => typeof id === 'string'));
                    }
                } catch(err) {}
            }
            
            function saveFavorites() {
                saveVersioned('galacticDuelFavorites', [...favorites]);
            }
            
            function toggleFavorite(charId) {
                if (favorites.has(charId)) {
                    favorites.delete(charId);
                } else {
                    favorites.add(charId);
                }
                saveFavorites();
                rebuildAllRosters();
            }
            
            function isFavorite(charId) {
                return favorites.has(charId);
            }
            
            loadFavorites();
            
            function isMobileView() {
                return window.innerWidth < 700;
            }
            
            function makeRosterButton(char, cssClass, clickFn) {
                const btn = document.createElement('button');
                btn.className = cssClass;
                btn.dataset.character = char.id;
                const em = rosterWeaponEmoji(char);
                btn.innerHTML = `<span style="margin-right:5px;font-size:0.9em">${em}</span>${char.name}`;
                btn.style.borderLeftColor = char.color;
                btn.style.borderLeftWidth = '3px';
                
                // Add star button
                const starBtn = document.createElement('button');
                starBtn.className = 'star-btn';
                starBtn.innerHTML = '☆';
                starBtn.title = 'Toggle favorite';
                if (isFavorite(char.id)) {
                    starBtn.classList.add('favorited');
                    starBtn.innerHTML = '★';
                }
                starBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    e.preventDefault();
                    toggleFavorite(char.id);
                });
                btn.appendChild(starBtn);
                
                if (isMobileView()) {
                    // Mobile: tap-once-to-preview, tap-again-to-confirm
                    btn.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        
                        if (mobilePreviewState.active && mobilePreviewState.char === char) {
                            // Second tap on same button: confirm selection
                            hideStatCard();
                            mobilePreviewState.active = false;
                            mobilePreviewState.char = null;
                            mobilePreviewState.btn = null;
                            clickFn();
                        } else {
                            // First tap: show preview
                            if (mobilePreviewState.btn) {
                                mobilePreviewState.btn.style.borderColor = '';
                                mobilePreviewState.btn.style.filter = '';
                            }
                            mobilePreviewState.active = true;
                            mobilePreviewState.char = char;
                            mobilePreviewState.btn = btn;
                            showStatCard(char, btn);
                            btn.style.borderColor = '#00A4FF';
                            btn.style.filter = 'brightness(1.3)';
                        }
                    });
                } else {
                    // Desktop: hover behavior. Gamepad focus mirrors hover so pad
                    // players still get the stat card, which they would otherwise
                    // never see — they generate no mouseenter. Gated on the pad's own
                    // focus class so ordinary click/Tab focus keeps its old behaviour
                    // and no card pops up just from landing on the menu.
                    btn.addEventListener('click', clickFn);
                    btn.addEventListener('mouseenter', () => showStatCard(char, btn));
                    btn.addEventListener('mouseleave', hideStatCard);
                    btn.addEventListener('focus', () => {
                        if (btn.classList.contains('gamepad-focus')) showStatCard(char, btn);
                    });
                    btn.addEventListener('blur', hideStatCard);
                }

                return btn;
            }

            function makeLockedHintButton(char, cssClass) {
                const btn = document.createElement('button');
                btn.className = cssClass;
                btn.style.opacity = '0.4';
                btn.style.cursor = 'help';
                btn.innerHTML = '???';
                btn.style.borderLeftColor = '#666666';
                btn.style.borderLeftWidth = '3px';
                
                if (isMobileView()) {
                    btn.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        if (mobilePreviewState.btn) {
                            mobilePreviewState.btn.style.borderColor = '';
                            mobilePreviewState.btn.style.filter = '';
                        }
                        mobilePreviewState.active = true;
                        mobilePreviewState.char = char;
                        mobilePreviewState.btn = btn;
                        showStatCard(char, btn, true);
                        btn.style.borderColor = '#00A4FF';
                        btn.style.filter = 'brightness(1.3)';
                    });
                } else {
                    btn.addEventListener('mouseenter', () => showStatCard(char, btn, true));
                    btn.addEventListener('mouseleave', hideStatCard);
                    btn.addEventListener('focus', () => {
                        if (btn.classList.contains('gamepad-focus')) showStatCard(char, btn, true);
                    });
                    btn.addEventListener('blur', hideStatCard);
                }

                return btn;
            }

            const heroContainer = document.getElementById('hero-roster');
            const villainContainer = document.getElementById('villain-roster');
            const searchInput = document.getElementById('searchInput');

            // Favourites to the top, then alphabetical. Shared by all three columns so
            // they cannot drift apart.
            function rosterOrder(a, b) {
                const aFav = isFavorite(a.id);
                const bFav = isFavorite(b.id);
                if (aFav !== bFav) return aFav ? -1 : 1;
                return a.name.localeCompare(b.name);
            }

            function findRosterChar(id) {
                for (const faction of ['heroes', 'villains', 'secret']) {
                    const hit = characters[faction].find(c => c.id === id);
                    if (hit) return hit;
                }
                return null;
            }

            /** The season's side of the roster, or null when the season view is off and
             *  the column should show its Galactic cast instead. */
            function packFactionColumn(side) {
                const season = packSeason();
                if (!season || !packFactionViewActive()) return null;
                return season[side].ids.map(findRosterChar).filter(Boolean);
            }

            /*  Which roster Surprise Me is allowed to draw from, and which half of
             *  it is facing the player.
             *
             *  The rule is that a fighter answers to their own roster and no other:
             *  pick a Marvel fighter and the surprise is another Marvel fighter from
             *  the opposing column, pick a Galactic one and it is Galactic.
             *
             *  The button used to ignore this completely for Marvel. The season lives
             *  in characters.secret, so the caller's lookup through
             *  characters.heroes/villains came back undefined and the pool fell all
             *  the way through to the entire Galactic cast — choosing Iron Man and
             *  pressing Surprise Me fought a Star Wars character, while the two
             *  columns behind the button were showing nothing but Marvel.
             *
             *  Keyed on the fighter's own `marvel` / `packId` flags rather than on
             *  which faction toggle happens to be lit. The toggle is UI state and the
             *  question here is about the fighter, so reading the flag gives the same
             *  answer in every reachable case and a sane one in the rest.
             *
             *  A fighter in neither column of their own roster — a secret-roster pick
             *  like Zero or Jabba, who sit outside both — has no opposite number, so
             *  for them the whole roster is fair game.                              */
            function surpriseRosterOf(playerChar) {
                const season = playerChar && playerChar.marvel ? marvelSeason()
                             : playerChar && playerChar.halloween ? halloweenSeason()
                             : playerChar && playerChar.packId && packSeason() ? packSeason()
                             : null;
                const heroes = season
                    ? season.heroes.ids.map(findRosterChar).filter(Boolean)
                    : characters.heroes;
                const villains = season
                    ? season.villains.ids.map(findRosterChar).filter(Boolean)
                    : characters.villains;
                const id = playerChar && playerChar.id;
                const onHeroSide = heroes.some(c => c.id === id);
                const onVillainSide = villains.some(c => c.id === id);
                return {
                    sides: [...heroes, ...villains],
                    opposing: onHeroSide ? villains
                            : onVillainSide ? heroes
                            : [...heroes, ...villains]
                };
            }

            /** One resolver for every column in the game: the roster's two and the
             *  opponent screen's two. Returns null when no season view is on, which is
             *  the signal to fall back to the Galactic cast. */
            function seasonFactionColumn(side) {
                const season = activeSeason();
                if (!season) return null;
                return season[side].ids.map(findRosterChar).filter(Boolean);
            }

            /** Every character column in the game renders through here — the roster's
             *  two, and the opponent screen's two. They differ only in which list goes
             *  in, what counts as available, and what a click does; everything else
             *  (order, search, the locked '???' with its hover card, retirement) is
             *  shared, which is the point. The opponent screen used to have its own
             *  copy of all of it and had drifted: a second sort that no longer matched
             *  this one, and a search that hid buttons with inline styles instead of
             *  rendering the matches — which reached the favourite stars nested inside
             *  them, and left the villain column unfiltered entirely.
             *
             *  isCharacterUnlocked covers shop/secret unlocks as well as achievements.
             *  The roster used to test the achievement alone, which left every
             *  shop-gated character in these columns (Thorn, Fox Elite, Sha'a Gi, Sith
             *  Anakin) fully playable without being bought. Locked entries still take a
             *  slot, as a '???' whose hover card names what unlocks them — for a pack's
             *  fighters that is the shop entry, which is on sale in plain sight
             *  anyway. */
            function renderRosterColumn(container, list, cssClass, opts = {}) {
                const box = opts.searchBox || searchInput;
                const isAvailable = opts.isAvailable || isCharacterUnlocked;
                const onPick = opts.onPick || (char => showOpponentPicker(char.id));
                const searchTerm = box.value.toLowerCase();

                container.innerHTML = '';
                [...list].sort(rosterOrder).forEach(char => {
                    // Catches retired fighters too, so none of them reaches
                    // even a locked hint button: a locked entry is an invitation to go
                    // and buy it, and the shop no longer opens that door.
                    if (isCharacterRetired(char)) return;
                    if (searchTerm && !char.name.toLowerCase().includes(searchTerm)) return;
                    if (!isAvailable(char)) {
                        container.appendChild(makeLockedHintButton(char, cssClass));
                        return;
                    }
                    const btn = makeRosterButton(char, cssClass, () => onPick(char));
                    if (opts.decorate) opts.decorate(btn, char);
                    container.appendChild(btn);
                });
            }

            function rebuildHeroRoster() {
                renderRosterColumn(heroContainer, seasonFactionColumn('heroes') || characters.heroes, 'game-button hero-button');
            }

            function rebuildVillainRoster() {
                renderRosterColumn(villainContainer, seasonFactionColumn('villains') || characters.villains, 'game-button villain-button');
            }

            function rebuildSecretRoster() {
                secretContainer.innerHTML = '';
                const searchTerm = searchInput.value.toLowerCase();

                visibleSecretChars().sort(rosterOrder).forEach(char => {
                    if (searchTerm && !char.name.toLowerCase().includes(searchTerm)) return;
                    secretContainer.appendChild(makeRosterButton(char, 'game-button secret-button', () => showOpponentPicker(char.id)));
                });
            }

            function rebuildAllRosters() {
                // The season toggle appears the moment a first pack fighter is
                // owned, and every path that can change that — a shop purchase,
                // the Zero Point encounter, a dev unlock, a loaded save — already
                // comes through here. Refreshing the headings from this one place
                // is what stops the toggle from waiting for a page reload.
                updateFactionHeadings();
                rebuildHeroRoster();
                rebuildVillainRoster();
                rebuildSecretRoster();
            }

            // Search functionality
            searchInput.addEventListener('input', rebuildAllRosters);

            document.querySelectorAll('.pack-faction-toggle').forEach(btn => {
                btn.addEventListener('click', togglePackFactions);
            });
            document.querySelectorAll('.marvel-faction-toggle').forEach(btn => {
                btn.addEventListener('click', toggleMarvelFactions);
            });
            document.querySelectorAll('.halloween-faction-toggle').forEach(btn => {
                btn.addEventListener('click', toggleHalloweenFactions);
            });

            const secretContainer = document.getElementById('secret-roster');

            // Before the unlocks: loadGalacticUnlocks() ends by refreshing the secret
            // section, which asks isCharacterRetired(), which reads the fallen list.
            bootStep(loadHalloweenFallen);
            bootStep(loadGalacticUnlocks);
            // Creations first: they splice themselves into characters.heroes /
            // characters.villains, and loadArmory() below needs that roster in
            // place to tell whether an equip points at a creation or at someone
            // no longer allowed to carry a forged weapon.
            bootStep(loadCreatedCharacters);
            // After the unlocks (forge patterns are gated on them) and after the
            // WEAPON_LIBRARY literal above, which the recipes compile against.
            bootStep(loadArmory);
            // The Guardian's plating is restored with the settings but painted onto
            // the roster entry here: loadGameSettings() runs long before the
            // `characters` table exists, and the colour has to be on the entry before
            // the first paint or the mech shows factory cobalt until something else
            // rebuilds the grid.
            applyGuardianSkin();
            // Wrixel's colour is restored and painted on exactly the same terms,
            // and for the same reason.
            applyWrixelColor();
            // All three rosters are built here rather than earlier, so the first
            // paint already shows forged loadouts — roster buttons take their icon
            // from the weapon a character is actually carrying.
            rebuildAllRosters();
            // Same reasoning for the arena row: a save that has already cleared the
            // Zero Event must not be offered Cluster Coast on the first paint.
            refreshArenaButtons();

            const devMenuToggle = document.getElementById('devMenuToggle');
            const devMenuPanel = document.getElementById('devMenuPanel');

            function isDevMenuHost() {
                if (isDevMenuVerifiedUser()) return true;
                const h = (location.hostname || '').toLowerCase();
                if (h.endsWith('itch.io') || h.endsWith('itch.zone')) return false;
                return h === 'localhost' || h === '127.0.0.1' || h === '[::1]' || h === '' || location.protocol === 'file:';
            }

            function refreshDevMenuVisibility() {
                const on = isDevMenuHost();
                if (on) {
                    devMenuToggle.style.display = '';
                    devMenuToggle.classList.add('is-visible');
                } else {
                    devMenuToggle.classList.remove('is-visible');
                }
                // The toggle occupies the same top-right corner as the splash status
                // strip. It is a sibling of #splashMenu and comes after it, so no CSS
                // selector reaches back from one to the other — the body carries the
                // flag instead, and only a dev build pays for the offset.
                document.body.classList.toggle('has-dev-toggle', on);
            }

            refreshDevMenuVisibility();

            // A saved tester code is checked again on every load, so deleting its
            // row from DEV_TESTER_CODES takes the menu away on the next visit. The
            // answer arrives after boot; until then the menu shows only where it
            // always would (a local copy).
            function recheckDevCode() {
                if (!devAccessCode) return;
                isValidDevCode(devAccessCode).then(ok => {
                    devCodeVerified = ok;
                    refreshDevMenuVisibility();
                    updateItchVerifyStatus();
                });
            }
            bootStep(recheckDevCode);

            devMenuToggle.addEventListener('click', (e) => {
                e.stopPropagation();
                // Flex, not block: the panel is a column so only its scroll list
                // scrolls. Tested against 'flex' rather than 'none' because the
                // property starts empty — the CSS hides it, not an inline style.
                const open = devMenuPanel.style.display !== 'flex';
                devMenuPanel.style.display = open ? 'flex' : 'none';
                devMenuToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
            });

            // Secret faction collapsible toggle
            const secretFactionToggle = document.getElementById('secret-faction-toggle');
            const secretCollapseWrapper = document.querySelector('.secret-collapse-wrapper');
            const secretChevron = document.getElementById('secret-faction-chevron');
            
            if (secretFactionToggle && secretCollapseWrapper && secretChevron) {
                secretFactionToggle.addEventListener('click', () => {
                    secretCollapseWrapper.classList.toggle('collapsed');
                    const isCollapsed = secretCollapseWrapper.classList.contains('collapsed');
                    secretChevron.textContent = isCollapsed ? '▶' : '▼';
                });
            }

            document.addEventListener('click', (e) => {
                if (!isDevMenuHost() || devMenuPanel.style.display !== 'flex') return;
                if (e.target === devMenuToggle || devMenuToggle.contains(e.target)) return;
                if (devMenuPanel.contains(e.target)) return;
                devMenuPanel.style.display = 'none';
                devMenuToggle.setAttribute('aria-expanded', 'false');
            });

            const devUnlockAchievements = document.getElementById('devUnlockAchievements');
            if (devUnlockAchievements) {
                devUnlockAchievements.addEventListener('click', () => {
                    Object.keys(achievements).forEach(id => { achievements[id].done = true; });
                    try {
                        // Preserve existing progress counters (_saberWinCount etc.) —
                        // only overwrite the per-achievement done flags.
                        const saved = loadVersioned('galacticDuelAchievements', {});
                        Object.keys(achievements).forEach(id => { saved[id] = true; });
                        saveVersioned('galacticDuelAchievements', saved);
                    } catch(err) {}
                    persistGalacticUnlocks();
                    rebuildHeroRoster();
                    rebuildVillainRoster();
                    showAnnouncement('All achievements unlocked. Elite characters are now available!', '#ffd700', 4000, '🏆 DEV: ALL ACHIEVEMENTS');
                });
            }
            const devToggleInvincibility = document.getElementById('devToggleInvincibility');
            if (devToggleInvincibility) {
                devToggleInvincibility.addEventListener('click', () => {
                    invincibilityEnabled = !invincibilityEnabled;
                    devToggleInvincibility.textContent = `Invincibility: ${invincibilityEnabled ? 'ON' : 'OFF'}`;
                });
            }
            const devToggleAimbot = document.getElementById('devToggleAimbot');
            if (devToggleAimbot) {
                devToggleAimbot.addEventListener('click', () => {
                    devAimbotEnabled = !devAimbotEnabled;
                    devToggleAimbot.textContent = `Aimbot: ${devAimbotEnabled ? 'ON' : 'OFF'}`;
                });
            }
            const devToggleGatedOpponents = document.getElementById('devToggleGatedOpponents');
            if (devToggleGatedOpponents) {
                devToggleGatedOpponents.addEventListener('click', () => {
                    devAllowGatedOpponents = !devAllowGatedOpponents;
                    devToggleGatedOpponents.textContent = `Allow unlocked gated opponents: ${devAllowGatedOpponents ? 'ON' : 'OFF'}`;
                    // Refresh the opponent picker in place if it's currently open, so the
                    // toggle takes effect immediately without needing to back out and reselect.
                    if (opponentMenu.style.display !== 'none' && selectedPlayerCharId) {
                        showOpponentPicker(selectedPlayerCharId);
                    }
                });
            }
            const devToggleFps = document.getElementById('devToggleFps');
            if (devToggleFps) {
                devToggleFps.addEventListener('click', () => {
                    showFpsMeter = !showFpsMeter;
                    fpsFrames = 0;
                    fpsAccumMs = 0;
                    updateFpsMeterVisibility();
                    saveGameSettings();
                });
            }
            // Deliberately not persisted: strict mode is a debugging session, not a
            // preference, and leaving it on by accident would let one bad frame end
            // a real match.
            const devToggleStrictErrors = document.getElementById('devToggleStrictErrors');
            function updateStrictErrorsLabel() {
                if (devToggleStrictErrors) {
                    devToggleStrictErrors.textContent = `Strict Errors: ${debugStrictErrors ? 'ON' : 'OFF'}`;
                }
            }
            if (devToggleStrictErrors) {
                devToggleStrictErrors.addEventListener('click', () => {
                    debugStrictErrors = !debugStrictErrors;
                    updateStrictErrorsLabel();
                });
                updateStrictErrorsLabel();
            }
            const devUnlockAllSecrets = document.getElementById('devUnlockAllSecrets');
            if (devUnlockAllSecrets) {
                devUnlockAllSecrets.addEventListener('click', () => {
                    gameUnlocks.ultimatePalpatine = true;
                    gameUnlocks.charredAnakin = true;
                    gameUnlocks.senatorPalpatine = true;
                    gameUnlocks.tarffulUnlock = true;
                    gameUnlocks.jabbaUnlock = true;
                    // Retires The Visitor as well as granting Geno, which is why this
                    // rebuilds every column instead of only the secret row.
                    gameUnlocks.geno = true;
                    // Wrixel was the Zero Event's reward and the event is gone, so
                    // this is now the only thing that hands him over besides a save
                    // that cleared the event while it still existed.
                    gameUnlocks.wrixel = true;
                    // Zero is otherwise behind the ZERO code.
                    gameUnlocks.zeroUnit = true;
                    // The two Halloween lords, otherwise five wins as their general.
                    gameUnlocks.lordtreat = true;
                    gameUnlocks.lordtrick = true;
                    persistGalacticUnlocks();
                    rebuildAllRosters();
                    updateSecretFactionSectionVisibility();
                    showAnnouncement('All secrets are now unlocked!', '#ff00ff', 3500, '🔓 DEV: ALL SECRETS');
                });
            }

            // Straight-up cheat: hands over a Mythic that is otherwise earned by
            // finding it in battle. Deliberately gated on isLocalBuild() rather than
            // isDevMenuHost(), so a verified tester with the rest of the dev
            // menu still cannot hand themselves one. Grants and equips in one press,
            // since the point of the button is to get straight into a fight with it.
            const devGrantBoomBoom = document.getElementById('devGrantBoomBoom');
            if (devGrantBoomBoom) {
                devGrantBoomBoom.addEventListener('click', () => {
                    if (!isLocalBuild()) return;
                    grantSprite('boomBoom');
                    equipSprite('boomBoom');
                });
            }

            // The two Zero Event sprites, on the same terms as Boom Boom above:
            // local builds only, grant and equip in one press.
            //
            // These need the button more than Boom Boom does. Boom Boom turns up on
            // the battlefield in any match; neither of these can be reached without
            // finishing the whole event first — and then the Shapeless Sprite is a
            // 5% roll on top of that, so testing what it does would otherwise mean
            // repeating a five-boss run until it happened to drop.
            [['devGrantZeroSprite', 'zeroSprite'], ['devGrantShapelessSprite', 'shapelessSprite'],
             ['devGrantFurySprite', 'furySprite']]
                .forEach(([btnId, spriteId]) => {
                    const btn = document.getElementById(btnId);
                    if (!btn) return;
                    btn.addEventListener('click', () => {
                        if (!isLocalBuild()) return;
                        grantSprite(spriteId);
                        equipSprite(spriteId);
                    });
                });

            // Dev menu credits slider
            const devCreditsSlider = document.getElementById('devCreditsSlider');
            const devCreditsValue = document.getElementById('devCreditsValue');
            if (devCreditsSlider && devCreditsValue) {
                devCreditsSlider.value = credits;
                devCreditsValue.textContent = credits;
                devCreditsSlider.addEventListener('input', (e) => {
                    credits = parseInt(e.target.value);
                    devCreditsValue.textContent = credits;
                    saveGameSettings();
                    updateCreditsDisplay();
                });
            }

            /*  Sets the Mk outright. Drives starkContractsClaimed rather than a
             *  separate override, so everything downstream — the roster record, the
             *  special, the Dossier line, the standing order — sees exactly what it
             *  would see if the contracts had actually been claimed.
             *
             *  Re-rolls the standing order because the board closes at the Mk 85 and
             *  has to reopen if the slider comes back down.                        */
            const devMarkSlider = document.getElementById('devMarkSlider');
            const devMarkValue = document.getElementById('devMarkValue');
            if (devMarkSlider && devMarkValue) {
                const paintMark = () => {
                    devMarkSlider.value = ironManMark();
                    devMarkValue.textContent = 'Mk ' + ironManMark() +
                        (ironManOnFire() ? ' · fire' : ' · unibeam');
                };
                paintMark();
                devMarkSlider.addEventListener('input', (e) => {
                    starkContractsClaimed = Math.max(0, parseInt(e.target.value, 10) - 1);
                    applyIronManMark();
                    rollStarkContract(starkContract ? starkContract.id : null);
                    saveGameSettings();
                    paintMark();
                    rebuildAllRosters();
                    rebuildOpponentRosters();
                    renderDossier();
                });
            }

            /*  Groot's level, same contract as the Mk slider above: drives
             *  grootContractsClaimed rather than an override, so the roster record,
             *  the weapon swap at level 5, the Dossier line and the standing order all
             *  see what they would see had the orders actually been worked.
             *
             *  Re-rolls the standing order for the same reason too — the board closes
             *  at level 5 and has to reopen if the slider comes back down.          */
            /*  Replays the Snap from the top. SnapIntro.play() resets its own
             *  state and re-runs the sequence, so this is a true replay rather
             *  than a second showing stacked on the first.
             *
             *  The intro mounts inside #splashMenu and animates the tiles that
             *  live there, so it can only play from the splash. Rather than fail
             *  quietly somewhere else, this closes the dev menu, goes back to the
             *  splash, and plays from there.                                  */
            const devPlaySnap = document.getElementById('devPlaySnap');
            if (devPlaySnap) devPlaySnap.addEventListener('click', () => {
                devMenuPanel.style.display = 'none';
                if (!replaySnapIntro()) {
                    showAnnouncement('The Snap intro is not loaded.', '#ff6666', 2600, '\u26a0\ufe0f DEV');
                }
            });

            const devGrootSlider = document.getElementById('devGrootSlider');
            const devGrootValue = document.getElementById('devGrootValue');
            if (devGrootSlider && devGrootValue) {
                const paintGroot = () => {
                    const lvl = grootLevel();
                    devGrootSlider.value = lvl;
                    // grootFistDamage() rather than the roster record's weaponDamage:
                    // this paints once at wiring time, which is before the setup tail
                    // calls applyGrootLevel(), so the record is not written yet.
                    devGrootValue.textContent = 'Lv ' + lvl + (lvl >= GROOT_MAX_LEVEL
                        ? ' · stormbreaker'
                        : ' · branches ' + grootFistDamage(lvl) + ' a hit');
                };
                paintGroot();
                devGrootSlider.addEventListener('input', (e) => {
                    grootContractsClaimed = Math.max(0, parseInt(e.target.value, 10) - 1);
                    applyGrootLevel();
                    rollGrootContract(grootContract ? grootContract.id : null);
                    saveGameSettings();
                    paintGroot();
                    rebuildAllRosters();
                    rebuildOpponentRosters();
                    renderDossier();
                });
            }

            // ── ROSTER DATA VALIDATION (dev menu) ──────────────────────
            function validateRosterData() {
                const lines = [];
                const seenIds = new Map(); // id -> faction it was first seen in
                let errorCount = 0, warningCount = 0;
                let totalChars = 0;

                const requiredFields = ['id', 'name', 'color', 'hp', 'weapon'];

                Object.keys(characters).forEach(faction => {
                    const roster = characters[faction];
                    if (!Array.isArray(roster)) return;
                    roster.forEach((char, idx) => {
                        totalChars++;
                        const label = char && char.name ? `"${char.name}"` : `entry #${idx + 1}`;
                        const tag = char && char.id ? char.id : `${faction}[${idx}]`;

                        // Required fields
                        requiredFields.forEach(field => {
                            const val = char ? char[field] : undefined;
                            if (val === undefined || val === null || val === '') {
                                lines.push({ type: 'error', text: `[${faction}] ${label} (${tag}) — missing required field "${field}"` });
                                errorCount++;
                            }
                        });

                        // hp should be a positive number
                        if (char && char.hp !== undefined && (typeof char.hp !== 'number' || char.hp <= 0)) {
                            lines.push({ type: 'error', text: `[${faction}] ${label} (${tag}) — "hp" should be a positive number, got ${JSON.stringify(char.hp)}` });
                            errorCount++;
                        }

                        // Duplicate id check
                        if (char && char.id) {
                            if (seenIds.has(char.id)) {
                                lines.push({ type: 'error', text: `Duplicate id "${char.id}" — also used by ${seenIds.get(char.id)}` });
                                errorCount++;
                            } else {
                                seenIds.set(char.id, `[${faction}] ${label}`);
                            }
                        }

                        // Weapon must exist in WEAPON_LIBRARY
                        if (char && char.weapon && !WEAPON_LIBRARY[char.weapon]) {
                            lines.push({ type: 'error', text: `[${faction}] ${label} (${tag}) — unknown weapon "${char.weapon}" (no entry in WEAPON_LIBRARY)` });
                            errorCount++;
                        }

                        // unlockAchievement must reference a real achievement
                        if (char && char.unlockAchievement && !achievements[char.unlockAchievement]) {
                            lines.push({ type: 'error', text: `[${faction}] ${label} (${tag}) — unlockAchievement "${char.unlockAchievement}" does not match any achievement id` });
                            errorCount++;
                        }

                        // secretUnlock must reference a real gameUnlocks key
                        if (char && char.secretUnlock && !(char.secretUnlock in gameUnlocks)) {
                            lines.push({ type: 'error', text: `[${faction}] ${label} (${tag}) — secretUnlock "${char.secretUnlock}" does not match any gameUnlocks key` });
                            errorCount++;
                        }

                        // Lightsaber users without a saber color (cosmetic, non-blocking)
                        if (char && char.weapon === 'lightsaber' && !char.saberColor) {
                            lines.push({ type: 'warn', text: `[${faction}] ${label} (${tag}) — lightsaber user has no "saberColor" set` });
                            warningCount++;
                        }

                        // Missing bio (cosmetic, non-blocking)
                        if (char && !char.bio) {
                            lines.push({ type: 'warn', text: `[${faction}] ${label} (${tag}) — no "bio" set` });
                            warningCount++;
                        }
                    });
                });

                return { lines, errorCount, warningCount, totalChars };
            }

            const devValidateRoster = document.getElementById('devValidateRoster');
            if (devValidateRoster && isItchHost()) {
                devValidateRoster.style.display = 'none';
                const devValidationOutputEl = document.getElementById('devValidationOutput');
                if (devValidationOutputEl) devValidationOutputEl.style.display = 'none';
            }
            if (devValidateRoster) {
                devValidateRoster.addEventListener('click', () => {
                    const output = document.getElementById('devValidationOutput');
                    const { lines, errorCount, warningCount, totalChars } = validateRosterData();

                    const esc = (s) => String(s).replace(/[&<>]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;' }[c]));
                    let html = `<span class="dv-heading">ROSTER VALIDATION — ${totalChars} characters checked</span>`;
                    if (errorCount === 0 && warningCount === 0) {
                        html += `<span class="dv-ok">✓ No issues found.</span>`;
                    } else {
                        if (errorCount > 0) {
                            html += `<span class="dv-heading">Errors (${errorCount})</span>`;
                            lines.filter(l => l.type === 'error').forEach(l => {
                                html += `<span class="dv-error">✗ ${esc(l.text)}</span>\n`;
                            });
                        }
                        if (warningCount > 0) {
                            html += `<span class="dv-heading">Warnings (${warningCount})</span>`;
                            lines.filter(l => l.type === 'warn').forEach(l => {
                                html += `<span class="dv-warn">⚠ ${esc(l.text)}</span>\n`;
                            });
                        }
                    }
                    output.innerHTML = html;
                    output.style.display = 'block';

                    if (errorCount > 0) {
                        showAnnouncement(`Roster validation found ${errorCount} error${errorCount === 1 ? '' : 's'}${warningCount ? ` and ${warningCount} warning${warningCount === 1 ? '' : 's'}` : ''}. See dev menu for details.`, '#ff6666', 5000, '🔍 DEV: VALIDATION');
                    } else if (warningCount > 0) {
                        showAnnouncement(`Roster validation passed with ${warningCount} warning${warningCount === 1 ? '' : 's'}. See dev menu for details.`, '#ffcc55', 4000, '🔍 DEV: VALIDATION');
                    } else {
                        showAnnouncement(`Roster validation passed — all ${totalChars} characters look good!`, '#44dd88', 3500, '🔍 DEV: VALIDATION');
                    }
                });
            }

            let gamePaused = false;

            let entities = [];

            // ── PER-FRAME CLOCK & SCRATCH BUFFERS ───────────────────────
            // gameLoop stamps frameNow once per frame and update()/draw() read that
            // instead of calling Date.now() again — it was being called nine times a
            // frame, including once per entity inside the main sweep. A single stamp
            // is also more correct: every timer in a frame now resolves against the
            // same instant rather than drifting by however long the frame took.
            let frameNow = gameNow();

            // Reused across frames so the alive-entity sweeps stop allocating a fresh
            // array every tick. Compacted in place — never hand one of these to code
            // that keeps a reference, and never nest two passes over the same buffer.
            const aliveScratch = [];
            const hitTargetScratch = [];
            const subBarScratch = [];
            // Entities holding an open guard window this frame — see tryDeflect().
            // Usually empty or one long.
            const deflectorScratch = [];
            // Bullet-clash working set: the two team partitions plus the spatial hash.
            // The partitions and the Map are reused; only the per-cell bucket arrays
            // are fresh each frame, and there are at most a handful of occupied cells.
            const clashTeamA = [];
            const clashTeamB = [];
            const clashGrid = new Map();

            function collectAlive(out) {
                out.length = 0;
                for (let i = 0; i < entities.length; i++) {
                    if (entities[i].isAlive) out.push(entities[i]);
                }
                return out;
            }
            let mainPlayer, mainEnemy, pCharData, eCharData;
            // Which entity the enemy HUD panel reads. Normally mainEnemy, but the
            // Cloud City rescue hands it to Jabba once Han is freed — see
            // setEnemyHud(). Declared beside mainEnemy because it shadows its role.
            let hudEnemyEntity = null;
            let bullets = [];
            // Held-key state, keyed by NORMALIZED key name — see normalizeKey().
            // Never index this with a raw e.key.
            let keys = {};

            /** Canonical name for a key event, or null if the event carries no
             *  usable key.
             *
             *  Two separate hazards, both of which produced real bugs:
             *
             *  1. CASE. e.key reports the *character produced*, so the same
             *     physical key is 'w' on its own and 'W' with Shift or Caps Lock
             *     held. Holding W to move, tapping Shift to dodge, then releasing
             *     W sends keydown 'w' and keyup 'W' — so keys['w'] was set true
             *     and never cleared, and the player walked in that direction for
             *     the rest of the session. Lower-casing single characters makes
             *     the down and up agree on one name. (It also fixes movement
             *     simply not working while Caps Lock is on.)
             *
             *  2. MISSING KEY. e.key is not guaranteed to be present: browser
             *     autofill, IME composition and extension-dispatched events all
             *     fire keydown with it undefined. That threw on the dev-menu
             *     combo below and killed the rest of the handler.
             *
             *  Named keys ('ArrowLeft', 'Shift', 'Escape') are longer than one
             *  character and pass through untouched. */
            function normalizeKey(e) {
                const k = e && e.key;
                if (typeof k !== 'string' || k === '') return null;
                return k.length === 1 ? k.toLowerCase() : k;
            }

            /** Forget every held key.
             *
             *  A keyup that never arrives leaves its key stuck down forever: the
             *  browser does not deliver one if focus left the window mid-press
             *  (alt-tab, a fullscreen transition, devtools opening), and the game
             *  has no way to notice on its own. resetTouchInput() has always
             *  existed for the same reason on the touch side; this is its
             *  keyboard counterpart, and the two are now called together. */
            function resetKeyboardInput() {
                keys = {};
            }
            // gameLoopId / lastGameFrameTime declared earlier (with battle session state)
            let invincibilityEnabled = false;
            let devAllowGatedOpponents = false;
            // FPS meter (rolling average over ~30 frames)
            let fpsFrames = 0;
            let fpsAccumMs = 0;
            let fpsDisplay = 0;
            // hitSparks / impactParticles / saberTrails / clashParticles / deathParticles /
            // floatNums / screenShake / slowMotion / killCamera are declared earlier
            // (with the performance settings) to avoid TDZ crashes.
            let dodgeFlashes = [];
            let lowHealthVignette = false;

            // Re-apply graphics preset (arrays already live)
            applyPerformanceMode();

            // ── GLOW GATE ───────────────────────────────────────────────
            // ctx.shadowBlur is by far the most expensive 2D canvas operation on
            // mobile GPUs — every blurred draw is a separate offscreen blur pass,
            // and this file sets it at ~50 draw sites per frame. Rather than gating
            // each site by hand, intercept the property once and scale it by the
            // active graphics preset. Draw code stays unchanged.
            (function installGlowGate() {
                try {
                    const proto = Object.getPrototypeOf(ctx);
                    const desc = Object.getOwnPropertyDescriptor(proto, 'shadowBlur');
                    if (!desc || typeof desc.set !== 'function') return;
                    Object.defineProperty(ctx, 'shadowBlur', {
                        configurable: true,
                        get() { return desc.get.call(this); },
                        set(v) {
                            let out = v;
                            if (reducedMotion || performanceMode === 'low') out = 0;
                            else if (performanceMode === 'balanced') out = Math.min(v, 6);
                            desc.set.call(this, out);
                        }
                    });
                } catch (e) { /* non-standard engine: leave glow as-is */ }
            })();

            // ── AUTO GRAPHICS DOWNGRADE ─────────────────────────────────
            // If the device can't hold a playable framerate, step the preset down
            // instead of leaving the player stuck at single-digit FPS. Backs off
            // permanently once the player picks a preset by hand.
            let perfUserOverride = false;
            let perfBadSamples = 0;
            let perfAutoDowngrades = 0;
            function checkPerformanceWatchdog(fps) {
                if (perfUserOverride || perfAutoDowngrades >= 2) return;
                if (fps > 0 && fps < 24) perfBadSamples++;
                else { perfBadSamples = 0; return; }
                if (perfBadSamples < 4) return; // ~2s sustained, not one bad hitch
                perfBadSamples = 0;
                const next = performanceMode === 'high' ? 'balanced'
                           : performanceMode === 'balanced' ? 'low' : null;
                if (!next) { perfAutoDowngrades = 2; return; }
                performanceMode = next;
                perfAutoDowngrades++;
                applyPerformanceMode();
                saveGameSettings();
                showAnnouncement(
                    `Framerate was low, so graphics dropped to ${next === 'low' ? 'Low' : 'Balanced'}. You can change this any time in Settings.`,
                    // Fires mid-fight, and explains a change the player just watched
                    // happen — held back, it is an unexplained visual glitch instead.
                    '#ffc850', 3500, '🖥️ AUTO GRAPHICS', 50, true
                );
            }

            // ── PICKUP SYSTEM ───────────────────────────────────────────
            let pickups = [];
            let pickupSpawnTimer = 0;
            const PICKUP_SPAWN_TIME = 15000; // 15 seconds
            const PICKUP_TYPES = ['health', 'shield', 'ammo', 'spread'];

            /** Decides whether this pickup slot becomes a sprite, and which one.
             *  Returns the sprite, or null for an ordinary drop.
             *
             *  A sprite only drops when it is actually worth contesting: if the
             *  player already has it equipped there is nothing to win, and if the
             *  opponent has already claimed it this series, a second copy would let
             *  them re-take a prize they are holding. Note this deliberately DOES
             *  drop sprites the player owns but has unequipped, and ones they lost
             *  and have not re-bought — finding it in battle is the main way in,
             *  with the Shop only ever a paid second chance. */
            function rollSpriteDrop() {
                // A sprite may also declare its own condition — where it is allowed
                // to appear at all, rather than merely how often. The Zero Sprite
                // uses it to stay inside the Unstable Zero Point, and the Shapeless
                // Sprite uses it to stay out of the pickup rotation entirely, since
                // beating Geno is its only route in.
                const eligible = SPRITE_CATALOG.filter(s =>
                    !isSpriteVaulted(s) &&
                    !isSpriteEquipped(s.id) && !enemySpriteGrants[s.id] &&
                    (typeof s.eligible !== 'function' || s.eligible())
                );
                for (const sprite of eligible) {
                    if (Math.random() < (spriteRarity(sprite).spawnChance || 0)) return sprite;
                }
                return null;
            }

            /*  ── CHARGED SHOTS ────────────────────────────────────────────────
             *  Hold the trigger, let go, and what comes out is proportional to how
             *  long you held it. Three weapons do this now — the Bowcaster, the
             *  Computer and Hawkeye's Bow — and it is one code path rather than three.
             *
             *  It used to be two: two triples of module state, two copies of the
             *  fire block, two copies of a thirty-five line ring meter that differed
             *  only in a colour, and a movement penalty that named both weapons by
             *  key. Adding a third would have meant a third of each, and the Bow
             *  needs something the other two do not have — a charge that extends
             *  RANGE as well as damage — so the copy would not even have been a copy.
             *
             *  A weapon opts in by carrying a `charge` block (see WEAPON_LIBRARY):
             *
             *      ms          how long a full draw takes
             *      damageMult  damage at full charge, as a multiple of base
             *      rangeMult   optional; maxRange at full charge, same idea
             *      ring        the colour of the meter drawn around the player
             *
             *  Both existing weapons keep exactly the numbers they had — 1500ms to a
             *  3x shot, no range change — so this is a refactor for them and a
             *  feature only for the Bow.
             *
             *  One charge can be in flight at a time because one fighter is holding
             *  one weapon; `key` records which, so a weapon swap mid-draw cannot
             *  release someone else's arrow.                                        */
            let chargeShot = { key: null, amount: 0, startedAt: 0 };

            function chargeConfigOf(weaponConfig) {
                return (weaponConfig && weaponConfig.charge) || null;
            }

            /** True while the player is actually drawing something back. */
            function isCharging() { return !!chargeShot.key; }

            function resetChargeShot() {
                // The draw's voice dies with the draw, from EVERY route out — the
                // release below, a weapon swap, a round ending, setupGame() clearing
                // state between matches. One chokepoint rather than a stop beside
                // each caller, which is how a whine ends up outliving the fight it
                // belongs to. Stopping a sound that is not playing is a no-op, so
                // this is free for the three charge weapons that have no draw sample.
                stopChargeDrawSfx(chargeShot.key);
                chargeShot.key = null;
                chargeShot.amount = 0;
                chargeShot.startedAt = 0;
            }

            /*  The config a charged release actually fires with. Damage and range
             *  both interpolate from 1x at no draw to their multiplier at a full one,
             *  so a tapped shot is exactly the weapon's table row and a held one is
             *  the row scaled — nothing is special-cased at either end.
             *
             *  `maxRange` is only touched when the weapon has one to touch. A weapon
             *  with no maxRange flies until it leaves the arena, and multiplying zero
             *  would quietly turn that into a bolt that despawns instantly.          */
            /*  ── THE AI DRAWS TOO ─────────────────────────────────────────────
             *  Charged weapons used to be a player-only mechanic: the AI held a
             *  Bowcaster and fired it like a rifle, at 1x, forever. That was
             *  survivable for the Bowcaster, whose uncharged shot is a perfectly good
             *  25, and unsurvivable for the Bow, whose uncharged shot cannot even
             *  reach the fighter it opens the round against.
             *
             *  The AI's draw lives on the entity rather than in the module-level
             *  chargeShot, because there can be several of them drawing at once and
             *  only ever one player.
             *
             *  How full a draw it wants is the larger of two things:
             *
             *    the range it needs   an arrow has to physically reach the target, so
             *                         this is solved from the distance rather than
             *                         guessed, with 15% margin for the target moving
             *    the floor difficulty a Legend archer holds for a near-full 51; an
             *                         Easy one lets fly almost immediately            */
            const AI_DRAW_FLOOR = { easy: 0.15, normal: 0.40, hard: 0.65, legend: 0.85 };

            function aiNeededDraw(e, dist) {
                const cc = chargeConfigOf(e.weaponConfig);
                if (!cc) return 0;
                let need = AI_DRAW_FLOOR[currentDifficulty] ?? AI_DRAW_FLOOR.normal;
                const base = e.weaponConfig.maxRange || 0;
                if (cc.rangeMult && base > 0) {
                    // maxRange(a) = base * (1 + a * (rangeMult - 1)), solved for a.
                    const wanted = dist * 1.15;
                    const reach = (wanted / base - 1) / (cc.rangeMult - 1);
                    need = Math.max(need, reach);
                }
                return Math.min(1, Math.max(0, need));
            }

            /** Advances an AI's draw and reports whether it may loose the shot yet.
             *  Weapons that do not charge always may, so this is safe to put in front
             *  of the ordinary fire condition. */
            function aiChargeReady(e, now, dist) {
                const cc = chargeConfigOf(e.weaponConfig);
                if (!cc) return true;
                if (!e.aiChargeStart) { e.aiChargeStart = now; e.aiChargeAmount = 0; }
                e.aiChargeAmount = Math.min(1, (now - e.aiChargeStart) / cc.ms);
                return e.aiChargeAmount >= aiNeededDraw(e, dist);
            }

            function aiShotConfig(e) {
                return chargeConfigOf(e.weaponConfig)
                    ? chargedConfigFor(e.weaponConfig, e.aiChargeAmount || 0)
                    : e.weaponConfig;
            }

            function releaseAiCharge(e) { e.aiChargeStart = 0; e.aiChargeAmount = 0; }

            /** True while this entity is visibly drawing something back. Drives both
             *  the movement penalty and the ring meter, so the AI pays and telegraphs
             *  exactly what the player does. */
            function aiIsDrawing(e) {
                if (!e || !e.aiChargeStart) return false;
                const cc = chargeConfigOf(e.weaponConfig);
                if (!cc) return false;
                // A draw only advances on frames the fire branch is actually reached,
                // so one that has been open far longer than a full draw takes means
                // the shot stopped being possible — no line of fire, no target left.
                // Treated as not drawing, or the archer would wear the 45% movement
                // penalty for the rest of the round over a shot it never took.
                return (frameNow - e.aiChargeStart) < cc.ms * 3;
            }

            function chargedConfigFor(weaponConfig, amount) {
                const c = chargeConfigOf(weaponConfig);
                if (!c) return weaponConfig;
                const out = { ...weaponConfig };
                out.damage = weaponConfig.damage * (1 + amount * ((c.damageMult || 1) - 1));
                if (c.rangeMult && weaponConfig.maxRange > 0) {
                    out.maxRange = weaponConfig.maxRange * (1 + amount * (c.rangeMult - 1));
                }
                return out;
            }

            // ── SCREEN SHAKE ───────────────────────────────────────────
            function triggerScreenShake(intensity, duration) {
                if (!effectsEnabled()) return;
                screenShake.intensity = intensity;
                screenShake.duration = duration;
            }

            function updateScreenShake(tickScale) {
                if (screenShake.duration > 0) {
                    screenShake.duration -= tickScale;
                    if (screenShake.duration <= 0) {
                        screenShake.intensity = 0;
                    }
                }
            }

            function applyScreenShake() {
                if (screenShake.intensity > 0) {
                    const shakeX = (Math.random() - 0.5) * screenShake.intensity;
                    const shakeY = (Math.random() - 0.5) * screenShake.intensity;
                    ctx.translate(shakeX, shakeY);
                }
            }

            // ── HIT SPARKS ─────────────────────────────────────────────
            function spawnHitSparks(x, y, color, count = 12) {
                if (reducedMotion) count = Math.min(count, 3);
                else if (performanceMode === 'low') count = Math.ceil(count * 0.35);
                else if (performanceMode === 'balanced') count = Math.ceil(count * 0.65);
                for (let i = 0; i < count; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const speed = Math.random() * 4 + 2;
                    if (hitSparks.length < MAX_HIT_SPARKS) {
                        hitSparks.push({
                            x, y,
                            dx: Math.cos(angle) * speed,
                            dy: Math.sin(angle) * speed,
                            life: 20 + Math.random() * 10,
                            maxLife: 30,
                            color,
                            size: Math.random() * 2 + 1
                        });
                    }
                }
            }

            function updateHitSparks(tickScale) {
                hitSparks = hitSparks.filter(p => {
                    p.x += p.dx * tickScale;
                    p.y += p.dy * tickScale;
                    p.dx *= 0.92;
                    p.dy *= 0.92;
                    p.life -= tickScale;
                    return p.life > 0;
                });
            }

            function drawHitSparks() {
                const useGlow = effectsEnabled() && performanceMode === 'high';
                hitSparks.forEach(p => {
                    if (p.life <= 0) return;
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
                    ctx.fillStyle = p.color;
                    if (useGlow) {
                        ctx.shadowBlur = 10;
                        ctx.shadowColor = p.color;
                    }
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, Math.max(0, p.size), 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();
                });
            }

            // ── BLASTER IMPACT PARTICLES ───────────────────────────────
            function spawnImpactParticles(x, y, color, count = 8) {
                if (reducedMotion) count = Math.min(count, 2);
                else if (performanceMode === 'low') count = Math.ceil(count * 0.3);
                else if (performanceMode === 'balanced') count = Math.ceil(count * 0.6);
                for (let i = 0; i < count; i++) {
                    const angle = Math.random() * Math.PI * 2;
                    const speed = Math.random() * 3 + 1;
                    if (impactParticles.length < MAX_IMPACT_PARTICLES) {
                        impactParticles.push({
                            x, y,
                            dx: Math.cos(angle) * speed,
                            dy: Math.sin(angle) * speed,
                            life: 15 + Math.random() * 8,
                            maxLife: 23,
                            color,
                            size: Math.random() * 3 + 2
                        });
                    }
                }
            }

            function updateImpactParticles(tickScale) {
                impactParticles = impactParticles.filter(p => {
                    p.x += p.dx * tickScale;
                    p.y += p.dy * tickScale;
                    p.dx *= 0.9;
                    p.dy *= 0.9;
                    p.life -= tickScale;
                    return p.life > 0;
                });
            }

            function drawImpactParticles() {
                const useGlow = effectsEnabled() && performanceMode === 'high';
                impactParticles.forEach(p => {
                    if (p.life <= 0) return;
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
                    ctx.fillStyle = p.color;
                    if (useGlow) {
                        ctx.shadowBlur = 8;
                        ctx.shadowColor = p.color;
                    }
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, Math.max(0, p.size * (p.life / p.maxLife)), 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();
                });
            }

            // ── BOOM BLAST SHOCKWAVE (Boom Boom sprite) ────────────────
            // One expanding ring per detonation, drawn at the true blast radius so
            // the ring the player sees is exactly the area that took damage —
            // there is no other way to read a splash weapon's reach mid-fight.
            const MAX_BOOM_BLASTS = 12;

            function spawnBoomBlast(x, y, radius) {
                if (!effectsEnabled()) return;
                if (boomBlasts.length >= MAX_BOOM_BLASTS) return;
                boomBlasts.push({ x, y, radius, life: 18, maxLife: 18 });
            }

            function updateBoomBlasts(tickScale) {
                boomBlasts = boomBlasts.filter(b => {
                    b.life -= tickScale;
                    return b.life > 0;
                });
            }

            function drawBoomBlasts() {
                const useGlow = effectsEnabled() && performanceMode === 'high';
                boomBlasts.forEach(b => {
                    const t = 1 - (b.life / b.maxLife); // 0 at the flash, 1 at full reach
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, 1 - t) * 0.8;
                    ctx.strokeStyle = '#ff9a3c';
                    ctx.lineWidth = 3 * (1 - t) + 1;
                    if (useGlow) {
                        ctx.shadowBlur = 14;
                        ctx.shadowColor = '#ff5bd1';
                    }
                    ctx.beginPath();
                    ctx.arc(b.x, b.y, b.radius * t, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                });
            }

            // ── GUARDIAN SKIN AURA (cosmetic) ──────────────────────────
            // What a sprite fitted at the Zero Point looks like on the mech. Boom
            // Boom's is the blast: rings leaving the plating on a loop, the same
            // orange and the same shape drawBoomBlasts() paints for a real
            // detonation — deliberately, since that is what the sprite is — but they
            // are drawn here, from the draw call, and touch nothing. No entity is
            // read, no damage is dealt, no shake is triggered, and the radius is a
            // hand's width off the chassis rather than BOOM_BOOM_RADIUS, so it can
            // never be mistaken for the reach of an actual blast.
            //
            // Phase comes from the clock rather than from stored state, so it costs
            // nothing to keep running and survives any number of entities.
            const GUARDIAN_AURA_PERIOD = 1100;  // ms for one ring to travel out
            const GUARDIAN_AURA_REACH  = 22;    // px past the chassis edge

            function drawGuardianSkinAura(entity) {
                const skin = guardianSkinDef(activeGuardianSkinId());
                if (!skin || skin.aura !== 'blast') return;   // a repaint has nothing to draw
                const color = skin.color;
                const glow = effectsEnabled() && performanceMode === 'high';
                const now = Date.now();

                ctx.save();
                // Under-glow, sitting where the Sith aura sits and pulsing at the
                // same sort of rate. Held steady under reduced motion, which is what
                // that setting is for — the skin stays visible, the throb stops.
                ctx.globalAlpha = reducedMotion ? 0.16 : 0.14 + 0.08 * Math.sin(now / 320);
                ctx.fillStyle = color;
                if (glow) { ctx.shadowBlur = 16; ctx.shadowColor = color; }
                ctx.beginPath();
                ctx.arc(entity.x, entity.y, CHARACTER_SIZE + 10, 0, Math.PI * 2);
                ctx.fill();
                ctx.shadowBlur = 0;

                // Shockwave rings. Reduced motion gets one at rest instead of three
                // travelling, so the plating still reads as blast plating.
                const rings = reducedMotion ? 1 : 3;
                for (let i = 0; i < rings; i++) {
                    const t = reducedMotion ? 0.45
                            : ((now + (i * GUARDIAN_AURA_PERIOD) / rings) % GUARDIAN_AURA_PERIOD) / GUARDIAN_AURA_PERIOD;
                    ctx.globalAlpha = (1 - t) * 0.55;
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 2.5 * (1 - t) + 0.5;
                    if (glow) { ctx.shadowBlur = 12; ctx.shadowColor = color; }
                    ctx.beginPath();
                    ctx.arc(entity.x, entity.y, CHARACTER_SIZE + 4 + t * GUARDIAN_AURA_REACH, 0, Math.PI * 2);
                    ctx.stroke();
                }
                ctx.restore();
            }

            // ── SABER TRAILS ───────────────────────────────────────────
            // Takes the blade angle already resolved by the caller rather than
            // recomputing it from the target. During a committed swing the blade
            // is locked to the angle it was committed at, and a trail that kept
            // tracking the live target would smear away from the blade drawing it.
            function addSaberTrailPoint(entity, angle) {
                if (!entity || !Number.isFinite(angle)) return;
                // Only the energy blades leave a glowing trail — a wrench or a pipe
                // swinging through the air would not.
                const cfg = entity.weaponConfig;
                const trailing = cfg && cfg.melee && (cfg.key === 'lightsaber' || cfg.key === 'darksaber' || cfg.key === 'staff');
                if (!trailing) return;
                const reach = cfg.reach || 30;
                
                const startX = entity.x + Math.cos(angle) * CHARACTER_SIZE;
                const startY = entity.y + Math.sin(angle) * CHARACTER_SIZE;
                const endX = entity.x + Math.cos(angle) * (CHARACTER_SIZE + reach);
                const endY = entity.y + Math.sin(angle) * (CHARACTER_SIZE + reach);
                
                if (saberTrails.length < MAX_SABER_TRAILS) {
                    saberTrails.push({
                        startX, startY, endX, endY,
                        color: entity.saberColor || entity.color,
                        life: 8,
                        maxLife: 8,
                        width: entity.weapon === 'staff' ? 6 : 5
                    });
                }
            }

            function updateSaberTrails(tickScale) {
                saberTrails = saberTrails.filter(t => {
                    t.life -= tickScale;
                    return t.life > 0;
                });
            }

            function drawSaberTrails() {
                saberTrails.forEach(t => {
                    if (t.life <= 0) return;
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, (t.life / t.maxLife) * 0.4);
                    ctx.lineCap = 'round';
                    ctx.strokeStyle = t.color;
                    ctx.lineWidth = Math.max(0, t.width * (t.life / t.maxLife));
                    ctx.shadowBlur = 12;
                    ctx.shadowColor = t.color;
                    ctx.beginPath();
                    ctx.moveTo(t.startX, t.startY);
                    ctx.lineTo(t.endX, t.endY);
                    ctx.stroke();
                    ctx.restore();
                });
            }

            // ── SLOW MOTION ───────────────────────────────────────────
            function triggerSlowMotion(scale, duration) {
                slowMotion.active = true;
                slowMotion.scale = scale;
                slowMotion.duration = duration;
            }

            function updateSlowMotion(dt) {
                if (slowMotion.active) {
                    slowMotion.duration -= dt;
                    if (slowMotion.duration <= 0) {
                        slowMotion.active = false;
                        slowMotion.scale = 1;
                    }
                }
            }

            // ── KILL CAMERA ────────────────────────────────────────────
            function triggerKillCamera(target) {
                if (!effectsEnabled()) return;
                killCamera.active = true;
                killCamera.target = target;
                killCamera.zoom = 1;
                killCamera.duration = 60;
            }

            function updateKillCamera(tickScale) {
                if (killCamera.active) {
                    killCamera.duration -= tickScale;
                    if (killCamera.zoom < 1.5) {
                        killCamera.zoom += 0.01 * tickScale;
                    }
                    if (killCamera.duration <= 0) {
                        killCamera.active = false;
                        killCamera.zoom = 1;
                    }
                }
            }

            function applyKillCamera() {
                if (killCamera.active && killCamera.target) {
                    const targetX = killCamera.target.x;
                    const targetY = killCamera.target.y;
                    ctx.translate(canvasLogicalW / 2, canvasLogicalH / 2);
                    ctx.scale(killCamera.zoom, killCamera.zoom);
                    ctx.translate(-targetX, -targetY);
                }
            }

            // ── DODGE ─────────────────────────────────────────────────
            // The dodge used to be nothing but a burst of speed: `isDodging` was
            // set here and read in exactly one place — the movement multiplier —
            // so rolling through a blaster bolt still took the hit in full. The
            // i-frames below are what make it a dodge rather than a dash.
            //
            // They cover only the opening of the roll, not all of it. Diving
            // *out* of a shot that is already on its way works; diving *into* one
            // late does not, because by then the frames are spent and you are
            // still committed to the movement. That gap is the whole skill in it.
            const PLAYER_DODGE_MS        = 200;
            const PLAYER_DODGE_IFRAME_MS = 150;  // 75% of the roll
            const AI_DODGE_MS            = 150;
            const AI_DODGE_IFRAME_MS     = 105;  // 70% — the AI's roll is a touch less generous

            function isInvulnerable(e, now) {
                return !!e && now < (e.invulnUntil || 0);
            }

            /** Start a dodge. Both the player's Shift/💨/B and the AI's low-health
             *  evade come through here, so the i-frames, the cooldown, the flash
             *  and the launch impulse can never drift apart between the two. */
            function startDodge(e, now, angle, durationMs, iframeMs, impulse) {
                e.isDodging = true;
                e.dodgeEnd = now + durationMs;
                e.invulnUntil = now + iframeMs;
                e.vx += Math.cos(angle) * impulse;
                e.vy += Math.sin(angle) * impulse;
                spawnDodgeFlash(e);
            }

            /** Feedback for a hit that the i-frames ate. Without this a dodged
             *  shot is indistinguishable from one that simply missed, and the
             *  player never learns the timing that just worked. */
            function spawnDodgeNegation(target) {
                spawnHitSparks(target.x, target.y, '#ffffff', 6);
                if (target.isMainEntity && floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: target.x + (Math.random() - 0.5) * 20,
                        y: target.y - CHARACTER_SIZE - 10,
                        text: 'DODGE', life: 38, maxLife: 38, dy: -1.2,
                        color: '#8ae1ff', glow: '#00A4FF'
                    });
                }
            }

            /*  ── WHO DASHES OUT LOUD ───────────────────────────────────────────
             *  Dash.mp3 is a Force sound — the rising whoosh of someone pulling
             *  themselves through the air. It used to fire on every dodge on the
             *  roster, so Nick Fury, a B1 droid and Rocket Raccoon all rolled
             *  sideways sounding like Jedi.
             *
             *  Everyone else is SILENT, deliberately, rather than borrowing a
             *  stand-in: there is no roll, thruster or scramble sample in sounds/
             *  yet, and the wrong sound is worse than no sound. When one arrives,
             *  register it and give the `else` in spawnDodgeFlash() a playSound().
             *
             *  DERIVED FROM THE WEAPON rather than listed per fighter. Fifty-two
             *  fighters carry a lightsaber and a fifty-two-name list is a list that
             *  goes stale — see the note on BLUNT_WEAPON_KEYS for what that costs
             *  and how many times it has cost it. A lightsaber or Force lightning
             *  means the Force, and the three edits below are where that rule needs
             *  help:
             *
             *    MINUS Grievous. Four lightsabers and not a drop of the Force — he
             *          took them off the Jedi he killed.
             *    PLUS  the ones who have it without a blade in hand: Snoke, who is
             *          carrying the droid shock here; Palpatine as a senator, before
             *          he drew anything; and Leia, who is Force-sensitive but fights
             *          in this game with a blaster.
             *    PLUS  CUSTOM_SITH_IDS, which is the same call the Sith aura already
             *          makes in Character.draw(): a creation whose NATURE was chosen
             *          as Sith is a Force user whatever it ended up holding.
             *
             *  The Darksaber needs no entry and is worth saying so: Sabine, the
             *  Mandalorian and Gideon carry it and not one of the three is
             *  Force-sensitive. It is Mandalorian property, and the rule below
             *  already leaves all three silent by naming the lightsaber alone.
             *
             *  Leia is the one judgement call in here. She is Force-sensitive in
             *  canon and never once uses it in this game; delete the id if she
             *  should roll quietly with the rest of the Rebellion.
             *
             *  baseKeyOf() so a forged saber still counts as one.                  */
            const FORCE_DASH_WEAPONS = new Set(['lightsaber', 'lightning']);
            const FORCE_DASH_EXCLUDED_IDS = new Set(['grievous']);
            const FORCE_DASH_EXTRA_IDS = new Set(['snoke', 'senator_palpatine', 'leia']);

            function usesForceDash(e) {
                if (!e) return false;
                const id = e.characterId;
                if (id && FORCE_DASH_EXCLUDED_IDS.has(id)) return false;
                if (id && (FORCE_DASH_EXTRA_IDS.has(id) || CUSTOM_SITH_IDS.has(id))) return true;
                return FORCE_DASH_WEAPONS.has(baseKeyOf(e.weapon));
            }

            // ── DODGE FLASHES ─────────────────────────────────────────
            function spawnDodgeFlash(entity) {
                // Both the player dodge and the AI's low-health evade route through
                // here, so this is the one place the dash is guaranteed to fire.
                // Deliberately outside the cap below — a dodge past the particle
                // ceiling should still be audible.
                //
                // The flash itself is NOT gated: everyone still gets the visual
                // tell, because that is how a dodge is read on screen and taking it
                // away would change the fight rather than the mix.
                if (usesForceDash(entity)) playSound('dash', 120);
                if (dodgeFlashes.length < 40) {
                    dodgeFlashes.push({
                        x: entity.x,
                        y: entity.y,
                        life: 10,
                        maxLife: 10,
                        color: entity.color
                    });
                }
            }

            function updateDodgeFlashes(tickScale) {
                dodgeFlashes = dodgeFlashes.filter(f => {
                    f.life -= tickScale;
                    return f.life > 0;
                });
            }

            function drawDodgeFlashes() {
                dodgeFlashes.forEach(f => {
                    ctx.save();
                    ctx.globalAlpha = (f.life / f.maxLife) * 0.6;
                    ctx.strokeStyle = f.color;
                    ctx.lineWidth = 3;
                    ctx.shadowBlur = 15;
                    ctx.shadowColor = f.color;
                    ctx.beginPath();
                    ctx.arc(f.x, f.y, CHARACTER_SIZE + 8, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                });
            }

            // ── AIM RETICLE ────────────────────────────────────────────
            // Replaces the hidden OS cursor while aiming manually. Also drawn for
            // the right stick, where there is no cursor to replace and the reticle
            // is the only way to tell where the shot is going to go.
            //
            // A short lead line from the player out toward the reticle sells the
            // direction at a glance — useful for melee, where the throw travels a
            // fixed distance and lining it up matters more than with a blaster.
            function drawAimReticle() {
                if (!isManualAimActive()) return;
                if (!mainPlayer || !mainPlayer.isAlive) return;

                const aim = resolvePlayerAim(mainPlayer);
                if (!aim) return;
                // Auto-aim fallbacks return a live entity; that already has a health
                // bar and a name plate over it, so a reticle would just be clutter.
                if (aim !== aimScratch) return;

                const angle = Math.atan2(aim.y - mainPlayer.y, aim.x - mainPlayer.x);
                const color = mainPlayer.saberColor || mainPlayer.color || '#00cfff';

                ctx.save();
                ctx.globalAlpha = 0.5;
                ctx.strokeStyle = color;
                ctx.lineWidth = 1.5;
                ctx.setLineDash([4, 6]);
                ctx.beginPath();
                ctx.moveTo(mainPlayer.x + Math.cos(angle) * (CHARACTER_SIZE + 10),
                           mainPlayer.y + Math.sin(angle) * (CHARACTER_SIZE + 10));
                ctx.lineTo(aim.x - Math.cos(angle) * 16, aim.y - Math.sin(angle) * 16);
                ctx.stroke();
                ctx.setLineDash([]);

                // Reticle: a ring with four ticks, left open at the centre so it
                // never hides the thing being aimed at.
                ctx.globalAlpha = 0.95;
                ctx.lineWidth = 2;
                ctx.shadowBlur = effectsEnabled() ? 10 : 0;
                ctx.shadowColor = color;
                ctx.beginPath();
                ctx.arc(aim.x, aim.y, 10, 0, Math.PI * 2);
                ctx.stroke();

                ctx.beginPath();
                for (let i = 0; i < 4; i++) {
                    const a = (Math.PI / 2) * i;
                    const cos = Math.cos(a), sin = Math.sin(a);
                    ctx.moveTo(aim.x + cos * 5, aim.y + sin * 5);
                    ctx.lineTo(aim.x + cos * 15, aim.y + sin * 15);
                }
                ctx.stroke();
                ctx.restore();
            }

            // ── LOW HEALTH VIGNETTE ────────────────────────────────────
            function updateLowHealthVignette() {
                if (!mainPlayer) return;
                const healthPercent = mainPlayer.health / mainPlayer.maxHealth;
                lowHealthVignette = healthPercent < 0.3;
            }

            function drawLowHealthVignette() {
                if (!lowHealthVignette || !mainPlayer) return;
                const healthPercent = mainPlayer.health / mainPlayer.maxHealth;
                const intensity = (0.3 - healthPercent) / 0.3;
                
                ctx.save();
                ctx.globalAlpha = intensity * 0.4;
                const gradient = ctx.createRadialGradient(
                    canvasLogicalW / 2, canvasLogicalH / 2, 0,
                    canvasLogicalW / 2, canvasLogicalH / 2, Math.max(canvasLogicalW, canvasLogicalH) * 0.7
                );
                gradient.addColorStop(0, 'transparent');
                gradient.addColorStop(0.6, 'transparent');
                gradient.addColorStop(1, '#ff0000');
                ctx.fillStyle = gradient;
                ctx.fillRect(0, 0, canvasLogicalW, canvasLogicalH);
                ctx.restore();
            }

            // Difficulty button wiring
            document.querySelectorAll('.diff-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.diff-btn').forEach(b => b.classList.remove('selected'));
                    btn.classList.add('selected');
                    currentDifficulty = btn.dataset.diff;
                });
            });

            /** Makes the arena row show where the fight actually is.
             *
             *  `currentArena` is the truth, and several things move it without the
             *  player touching a button: the Unstable Zero Point throwing you into
             *  another arena, and every Zero Event stage setting its own. The row
             *  went on highlighting whatever was last clicked, so the picker and the
             *  game disagreed — leave a match you were banished out of, come back,
             *  and the Zero Point still looked selected while the next fight loaded
             *  wherever the anomaly had dropped you.
             *
             *  Syncing the highlight to the state, rather than restoring the state to
             *  the highlight, is deliberate: you really are somewhere else now, and
             *  the row should say so. Clicking the Zero Point takes you back. */
            function syncArenaSelection() {
                document.querySelectorAll('.arena-btn').forEach(b => {
                    if (!b.dataset.arena) return;
                    b.classList.toggle('selected', b.dataset.arena === currentArena);
                });
            }

            /** Takes retired arenas off the picker. The Random button already skips
             *  anything hidden, so hiding the button is the whole job — and a player
             *  who was standing on Cluster Coast when they cleared the event is moved
             *  somewhere that still exists rather than being left pointing at a place
             *  the picker will not show them again. */
            function refreshArenaButtons() {
                let currentHidden = false;
                document.querySelectorAll('.arena-btn').forEach(btn => {
                    const key = btn.dataset.arena;
                    if (!key) return;
                    const retired = isArenaRetired(key);
                    btn.style.display = retired ? 'none' : '';
                    if (retired) {
                        btn.classList.remove('selected');
                        if (currentArena === key) currentHidden = true;
                    }
                });
                if (currentHidden) {
                    const fallback = document.querySelector('.arena-btn[data-arena="space"]');
                    if (fallback) {
                        currentArena = 'space';
                        document.querySelectorAll('.arena-btn').forEach(b => b.classList.remove('selected'));
                        fallback.classList.add('selected');
                    }
                }
            }

            // Arena button wiring (currentArena itself is declared with ARENAS above)
            document.querySelectorAll('.arena-btn').forEach(btn => {
                btn.addEventListener('click', () => {
                    if (btn.id === 'randomArenaBtn') {
                        // Pick any visible real arena button (not the Random button itself)
                        const realBtns = [...document.querySelectorAll('.arena-btn')]
                            .filter(b => b.id !== 'randomArenaBtn' && b.style.display !== 'none');
                        if (!realBtns.length) return;
                        const pick = realBtns[Math.floor(Math.random() * realBtns.length)];
                        document.querySelectorAll('.arena-btn').forEach(b => b.classList.remove('selected'));
                        pick.classList.add('selected');
                        currentArena = pick.dataset.arena;
                        refreshZeroPointEncounter(selectedPlayerCharId);
                        return;
                    }
                    document.querySelectorAll('.arena-btn').forEach(b => b.classList.remove('selected'));
                    btn.classList.add('selected');
                    currentArena = btn.dataset.arena;
                    // The arena row sits on the opponent screen, so picking the Zero
                    // Point is what puts Vengeance Jones on the board — and picking
                    // anywhere else takes him back off it.
                    refreshZeroPointEncounter(selectedPlayerCharId);
                });
            });

            function getVisibleButtons(scope = document) {
                return Array.from(scope.querySelectorAll('button')).filter(btn => {
                    const style = window.getComputedStyle(btn);
                    return !btn.disabled && style.display !== 'none' && style.visibility !== 'hidden' && btn.offsetParent !== null;
                });
            }

            function focusFirstVisibleButton(scope = document) {
                const buttons = getVisibleButtons(scope);
                if (buttons.length > 0) {
                    buttons[0].focus();
                    return buttons[0];
                }
                return null;
            }

            /*  Everything the splash knows about the save, recomputed each time the
             *  screen is shown rather than once at load — credits, a record, a
             *  resumable loadout and four counts all move while the player is
             *  elsewhere in the game.                                              */
            function refreshSplashState() {
                updateCreditsDisplay();          // owns the credits chip
                // refreshZeroEventLock() was called here and went with the Zero Event
                // when the tile it locked was removed — the call outlived the function
                // by one commit. It threw a ReferenceError on EVERY invocation, which
                // made this whole function stop at line two: the record chip, the
                // resumable-loadout line and all four counts were never written, and
                // because the setup tail calls this immediately before
                // SnapIntro.applyIfSnapped(), the snapped end state was never applied
                // at load either. That is the Zero Point tile sitting in Kamino's slot
                // for the first few seconds of every load on a snapped save.

                const setSub  = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
                const setTag  = (id, n, word) => {
                    const el = document.getElementById(id);
                    if (!el) return;
                    el.style.display = n > 0 ? '' : 'none';
                    if (n > 0) el.textContent = `${n} ${word}`;
                };

                // ── Record ────────────────────────────────────────────────
                let wins = 0, losses = 0;
                try {
                    loadVersioned('galacticDuelHistory', []).forEach(m => {
                        if (m.result === 'W') wins++; else losses++;
                    });
                } catch (e) {}
                const recordChip = document.getElementById('splashRecordChip');
                const recordEl   = document.getElementById('splashRecord');
                if (recordChip) recordChip.style.display = (wins + losses) ? '' : 'none';
                if (recordEl)   recordEl.textContent = `${wins}W · ${losses}L`;

                // ── Freeplay ──────────────────────────────────────────────
                const fp = document.getElementById('btnFreeplay');
                if (fp) {
                    fp.className = 'splash-btn splash-btn-freeplay';
                    fp.textContent = 'Freeplay';
                }

                // ── Shop ──────────────────────────────────────────────────
                let sprites = [];
                try { sprites = buyableSprites(); } catch (e) {}
                if (sprites.length) {
                    const s = sprites[0];
                    // loseSprite() records where it went; older saves stored `true`,
                    // which reads as "somewhere" and drops the clause.
                    const where = typeof lostSprites[s.id] === 'string' ? ` on ${arenaLabel(lostSprites[s.id])}` : '';
                    setSub('shopSub', `${s.name} you lost${where} is listed · ${s.cost}`);
                } else {
                    setSub('shopSub', 'Sprites, patterns and one-offs');
                }
                setTag('shopNewTag', unseenShopIds().length, 'new');

                // ── Armory · Creator · Dossier ────────────────────────────
                setSub('armorySub',  `Forge a weapon from a pattern · ${forgedWeapons.length} on your rack`);
                // Kamino's, not the Zero Point's: that tile is scenery and is
                // about to be snapped out of existence in front of the player.
                setSub('kaminoSub',  `Clone a fighter · ${createdCharacters.length} created`);
                setTag('dossierReadyTag', contractsReadyCount(), 'ready');

                // ── Halloween ─────────────────────────────────────────────
                refreshHalloweenTile();
            }

            /** Shop listings the player has not been shown yet. Seeded on first run
             *  (see initDossierState) so an existing save does not open to a pill
             *  claiming two dozen things are new. */
            function unseenShopIds() {
                const listed = shopItems.map(i => i.id);
                try { buyableSprites().forEach(s => listed.push('sprite:' + s.id)); } catch (e) {}
                return listed.filter(id => !shopSeenIds.includes(id));
            }

            /** Called when the Shop is opened: everything on the shelf is now seen. */
            function markShopSeen() {
                const unseen = unseenShopIds();
                if (!unseen.length) return;
                shopSeenIds = shopSeenIds.concat(unseen);
                saveGameSettings();
            }

            function showSplashMenu() {
                splashMenu.style.display = 'flex';
                refreshSplashState();
                // Guarded internally by its own once-per-session flag, so this is
                // just "the splash is on screen" rather than "play it now" — and
                // while the Snap is vaulted it never plays from here at all.
                offerSnapIntro();
                // restore dev/settings visibility when showing menus
                const devMenuToggleEl = document.getElementById('devMenuToggle');
                const settingsBtnEl = document.getElementById('settingsBtn');
                const fullscreenBtnEl = document.getElementById('fullscreenBtn');
                if (devMenuToggleEl && typeof isDevMenuHost === 'function' && isDevMenuHost()) { devMenuToggleEl.style.display = ''; devMenuToggleEl.classList.add('is-visible'); }
                if (settingsBtnEl) settingsBtnEl.style.display = '';
                if (fullscreenBtnEl) {
                    const fsOk = !!(document.documentElement.requestFullscreen || document.documentElement.webkitRequestFullscreen || document.documentElement.mozRequestFullScreen || document.documentElement.msRequestFullscreen);
                    fullscreenBtnEl.style.display = fsOk ? '' : 'none';
                }
                mainMenu.style.display = 'none';
                opponentMenu.style.display = 'none';
                messageOverlay.style.display = 'none';
                updateMobileControlsVisibility();
                setTimeout(() => focusFirstVisibleButton(splashMenu), 0);
            }

            function showMainMenu() {
                stopBattleSystems();
                playMenuMusic();
                // The arena picker lives on this screen and downstream of it, and
                // isArenaRetired() now depends on a flag that can change mid-session
                // (the Snap). Re-read it on the way in rather than only at boot.
                refreshArenaButtons();
                splashMenu.style.display = 'none';
                // restore dev/settings visibility when showing menus
                const devMenuToggleEl = document.getElementById('devMenuToggle');
                const settingsBtnEl = document.getElementById('settingsBtn');
                const fullscreenBtnEl = document.getElementById('fullscreenBtn');
                if (devMenuToggleEl && typeof isDevMenuHost === 'function' && isDevMenuHost()) { devMenuToggleEl.style.display = ''; devMenuToggleEl.classList.add('is-visible'); }
                if (settingsBtnEl) settingsBtnEl.style.display = '';
                if (fullscreenBtnEl) {
                    // Always compute inline — never touch the later `const fullscreenSupported`
                    // (typeof on a TDZ let/const still throws in browsers).
                    const fsOk = !!(document.documentElement.requestFullscreen || document.documentElement.webkitRequestFullscreen || document.documentElement.mozRequestFullScreen || document.documentElement.msRequestFullscreen);
                    fullscreenBtnEl.style.display = fsOk ? '' : 'none';
                }
                mainMenu.style.display = 'flex';
                opponentMenu.style.display = 'none';
                messageOverlay.style.display = 'none';
                updateMobileControlsVisibility();
                setTimeout(() => focusFirstVisibleButton(mainMenu), 0);
            }

            // --- ENTITY CLASSES & LOGIC ---

            // ── SPRITE GAIT (render only) ──────────────────────────────────
            // SpriteKit.stateFor() decides 'walk' from vx/vy, but in this game
            // those carry knockback alone — locomotion writes x/y directly (see
            // the movement branches in update()). So the gait played while a
            // fighter was being shot and stayed still while it walked. Character
            // .draw() measures the ground actually covered instead.
            //
            // Neither value is a tuning knob: nothing outside draw() reads them,
            // and no speed, hitbox, reach or collision value is involved.
            //
            // The threshold is the squared per-frame distance, and it is the same
            // 0.04 SpriteKit already uses on vx/vy — just applied to the fields
            // that actually move. It sits clear of both ends: the windiest arena
            // drags a motionless fighter 0.115px a frame (0.013 squared), while
            // the slowest real walk in the game — Jabba at 0.3 inside a 0.45 slow
            // zone — still covers 0.47px (0.22 squared).
            const SPRITE_WALK_EPSILON_SQ = 0.04;
            // A short tail so a strafe reversal, a frame spent against cover or a
            // single stalled tick does not drop the gait and snap it back.
            const SPRITE_WALK_TAIL_MS = 120;

            class Character {
                constructor(x, y, color, name, maxHealth, weapon, saberColor, isDroid, isWookiee, team, isMainEntity, isClone, weaponDamage, characterId) {
                    this.x = x;
                    this.y = y;
                    this.color = color;
                    this.name = name;
                    this.maxHealth = maxHealth;
                    this.health = maxHealth;
                    this.isAlive = true;
                    this.weaponConfig = getWeapon({ weapon: weapon || 'blaster', weaponDamage: weaponDamage });
                    // Taken from the resolved config rather than the constructor
                    // argument, because `weapon` may be a forged library slot
                    // ('forged:<id>') while a dozen places compare this field
                    // against a plain pattern name to drive rendering and sfx.
                    // The config's `key` is always that plain name.
                    this.weapon = this.weaponConfig.key;
                    this.saberColor = saberColor || color;
                    this.isDroid = !!isDroid;
                    this.isWookiee = !!isWookiee;
                    this.team = team;
                    this.isMainEntity = !!isMainEntity;
                    this.isClone = !!isClone;
                    this.characterId = characterId;

                    this.hasCalledBackup = false;
                    this.lastShotTime = 0;
                    this.stunnedUntil = 0;
                    this.knockedOutUntil = 0;
                    this.wasStunned = false;
                    this.wasKnockedOut = false;
                    this.zapImmunityUntil = 0;
                    this.wrenchImmunityUntil = 0;
                    this.freezeImmunityUntil = 0;

                    // Burning — set by the flamethrower, bled off in tickBurn().
                    // Per-entity like every other status, so a new round wipes it
                    // simply by building new Characters.
                    this.burningUntil = 0;
                    this.burnNextTickAt = 0;
                    this.burnFromTeam = null;   // who lit it, for damage-dealt credit

                    // Force Choke — the grip this entity is currently held in, and
                    // (for Vader) when it may next be cast. All of it is per-entity,
                    // so a new round wipes it simply by building new Characters.
                    this.chokedUntil = 0;
                    this.chokedBy = null;
                    this.chokeDamageRemaining = 0;
                    this.chokeMsRemaining = 0;
                    this.chokeCredit = 0;      // fractional damage owed to the damage-dealt stat
                    this.chokeTickAccum = 0;   // damage banked toward the next floating number
                    this.chokeNextTickAt = 0;
                    this.forceChokeReadyAt = 0;
                    this.vx = 0;
                    this.vy = 0;
                    this.lastAimAngle = 0;
                    // Where this entity was the last frame it was drawn — see the
                    // SPRITE GAIT note above. Seeded to the spawn point so the
                    // first frame reads as standing still rather than teleporting.
                    this.lastDrawX = x;
                    this.lastDrawY = y;
                    this.spriteWalkUntil = 0;
                    this.hitFlashUntil = 0;
                    this.dodgeCooldown = 0;
                    this.isDodging = false;
                    this.dodgeEnd = 0;
                    // The i-frames a dodge actually buys. Separate from dodgeEnd
                    // because they cover only the opening of the roll — see
                    // startDodge() — so diving into a shot too late still eats it.
                    this.invulnUntil = 0;

                    // ── MELEE COMMITMENT & GUARD ───────────────────────────
                    // A swing is no longer instantaneous. beginMeleeSwing() locks
                    // in the direction and schedules the cut; resolveMeleeSwing()
                    // lands it once the windup has elapsed. Until then the blade
                    // is reared back and the entity is committed — it cannot turn
                    // the swing to chase a target that has already moved.
                    this.pendingSwingAt = 0;     // when the committed cut lands (0 = none)
                    this.pendingSwingAngle = 0;  // direction locked at commit time
                    this.swingRecoverUntil = 0;  // windup + recovery; movement is slowed
                    // Deflection window. Open while the blade is up, which is the
                    // windup plus a little past the cut — see tryDeflect().
                    this.guardUntil = 0;
                    this.guardAngle = 0;

                    // Pickup effects
                    this.shieldActive = false;
                    this.shieldUntil = 0;
                    this.ammoBoostUntil = 0;
                    this.spreadUntil = 0;
                    this.isFleeing = false;
                    this.hasFled = false;

                    // Droid repair-crew escorts (Anzellans / Babu Frik)
                    this.anzellanEscorts = [];
                    this.hasCalledAnzellans = false;

                    // Magazine/reload state — only used by weapons with a magSize (e.g. Lancehead Pistol)
                    this.magAmmo = this.weaponConfig.magSize ?? null;
                    this.isReloading = false;
                    this.reloadEndsAt = 0;

                    // Droid sidearm (see DROID_SIDEARMS) — its own clock, so the
                    // secondary trigger never eats the primary's cooldown.
                    this.lastSidearmShotTime = 0;

                    // Semi-automatic latch (Lancehead Pistol). Set false the moment a
                    // shot goes off and true again only when the trigger is fully
                    // released, so holding fire cannot loose a second round. Starts
                    // true so the very first press shoots — and it deliberately does
                    // not gate the AI, which already fires in discrete cooldown-paced
                    // shots rather than by holding a button.
                    this.triggerReleased = true;

                    // How far into the current burst group this entity is — 0
                    // between groups. Only read for weapons with a `burst`
                    // (the Burst Rifle); see burstAwareCooldown().
                    this.burstShot = 0;

                    // Consecutive shots without a break, for weapons whose spread
                    // tightens under continuous fire (the Extending Focus Shotgun).
                    // See focusedArc().
                    this.focusShots = 0;

                    // Melee blade-throw cooldown (see performMeleeSwing / hasBladeInFlight)
                    this.throwReadyAt = 0;

                    // Loki's stolen shape: the snapshot of who this entity really
                    // is while it is wearing someone else, and when the disguise
                    // drops. Per-entity like every other status, so a new round
                    // clears it simply by building new Characters.
                    this.shapeshiftFrom = null;
                    this.shapeshiftUntil = 0;
                    this.shapeshiftReadyAt = 0;

                    // Per-entity AI movement multiplier, on top of the tactical
                    // profile's own speedMult. 1 = normal.
                    this.speedMult = 1;

                    // Next moment an arena hazard may tick damage on this entity.
                    // One shared clock across every hazard type, so standing in
                    // lava while a speeder clips you cannot double-bill.
                    this.hazardNextTickAt = 0;
                }

                draw(target) {
                    // Progress through a committed swing, 0 at the windup's first
                    // frame. swingCurve() spends p 0→0.72 on the cut and rests
                    // after, so the swing's own duration maps onto that span: the
                    // windup closes at p 0.305 (the kit's own windup ends at 0.30),
                    // the cut runs to 0.48, and recovery lands on 0.72 exactly as
                    // swingRecoverUntil expires. Computed here rather than beside
                    // the drawFighter call because the blade below needs it too —
                    // one value, so the beam and the fist holding it cannot drift.
                    const swingMs = MELEE_WINDUP_MS + MELEE_RECOVER_MS;
                    const swinging = this.swingRecoverUntil && frameNow < this.swingRecoverUntil;
                    const swingPhase = swinging
                        ? ((frameNow - (this.swingRecoverUntil - swingMs)) / swingMs) * 0.72
                        : 0;

                    // Whether this weapon's business end is the host's job. paintBlade
                    // is the one kit weapon that stops at the hilt and leaves the rest
                    // to us — that is all `bladeless` means. Every other melee weapon
                    // the kit draws whole: fists, claws, the electrostaff's pole. So
                    // beaming anything carrying `melee: true` ran a lit blade through
                    // Hulk's fists and Venom's claws, and laid a second glowing rod
                    // over the staff. Needed both for the blade below and for the
                    // sprite's weapon colour further down, so it lives up here.
                    const hostDrawsBlade =
                        SpriteKit.familyOf(this.weapon, this.weaponConfig) === 'blade';

                    if (target) {
                        // A committed swing points where it was committed, not
                        // where the target is now. Drawing the blade at the live
                        // angle would quietly contradict the hitbox — the arc that
                        // actually cuts is the locked one — and would hide the
                        // commitment the whole mechanic depends on being visible.
                        const angle = this.pendingSwingAt
                            ? this.pendingSwingAngle
                            : Math.atan2(target.y - this.y, target.x - this.x);
                        // Cached because draw() is also called with no target
                        // (round end, spectator, death frames) and the sprite
                        // still has to face somewhere sensible.
                        this.lastAimAngle = angle;
                        // Blade length comes from the weapon's own `reach`, so a new
                        // melee weapon renders correctly by existing rather than by
                        // being added to a ternary chain here — and only the blade
                        // family gets a beam at all, per hostDrawsBlade above.
                        const reach = (this.weaponConfig.melee && hostDrawsBlade)
                            ? (this.weaponConfig.reach || 30)
                            : 0;

                        if (reach > 0) {
                            // The hand carrying the hilt sweeps through the cut,
                            // so the beam has to sweep with it — drawn on the bare
                            // committed angle it would sit still in the air while
                            // the hilt swung out from under it. The sweep is the
                            // same arc the hitbox commits to: resolveMeleeSwing
                            // cuts a cone about this angle, and the blade now
                            // shows that cone being crossed instead of only its
                            // centre line. The angle stays anchored to where the
                            // swing was committed, so the commitment still reads.
                            const bladeAngle = angle + (swinging ? SpriteKit.swingOffset(swingPhase) : 0);

                            // Add saber trail point
                            addSaberTrailPoint(this, bladeAngle);

                            // A `twinBlade` weapon (Deadpool's katanas) is one swing
                            // drawn as two blades, one per hand: the same beam twice,
                            // pushed out either side of the aim line. The hitbox is
                            // still the one cone about bladeAngle, which sits between
                            // them — the pair shows its edges.
                            const bladeOffsets = this.weaponConfig.twinBlade ? [-9.5, 9.5] : [0];
                            const perpX = -Math.sin(bladeAngle), perpY = Math.cos(bladeAngle);
                            for (const off of bladeOffsets) {
                                const startX = this.x + Math.cos(bladeAngle) * CHARACTER_SIZE + perpX * off;
                                const startY = this.y + Math.sin(bladeAngle) * CHARACTER_SIZE + perpY * off;
                                const endX = this.x + Math.cos(bladeAngle) * (CHARACTER_SIZE + reach) + perpX * off;
                                const endY = this.y + Math.sin(bladeAngle) * (CHARACTER_SIZE + reach) + perpY * off;
                                const isWrenchLike = this.weapon === 'wrench';
                                const glowColor = this.weapon === 'wrench' ? '#c9d1d9' : this.weapon === 'staff' ? WEAPON_LIBRARY.staff.color : this.saberColor;

                                ctx.save();
                                ctx.lineCap = 'round';
                                ctx.strokeStyle = glowColor;
                                ctx.lineWidth = isWrenchLike ? 6 : 7;
                                ctx.shadowBlur = 25;
                                ctx.shadowColor = glowColor;
                                ctx.globalAlpha = 0.6;
                                ctx.beginPath();
                                ctx.moveTo(startX, startY);
                                ctx.lineTo(endX, endY);
                                ctx.stroke();

                                ctx.strokeStyle = '#ffffff';
                                ctx.lineWidth = isWrenchLike ? 2 : 2.5;
                                ctx.shadowBlur = 8;
                                ctx.shadowColor = '#ffffff';
                                ctx.globalAlpha = 0.95;
                                ctx.beginPath();
                                ctx.moveTo(startX, startY);
                                ctx.lineTo(endX, endY);
                                ctx.stroke();

                                if (this.weapon === 'wrench') {
                                    ctx.strokeStyle = '#7b8794';
                                    ctx.lineWidth = 3;
                                    ctx.shadowBlur = 0;
                                    ctx.globalAlpha = 0.9;
                                    ctx.beginPath();
                                    ctx.moveTo(endX - 4, endY - 4);
                                    ctx.lineTo(endX + 4, endY + 4);
                                    ctx.stroke();
                                    ctx.beginPath();
                                    ctx.moveTo(endX - 4, endY + 4);
                                    ctx.lineTo(endX + 4, endY - 4);
                                    ctx.stroke();
                                }
                                ctx.restore();
                            }
                        }
                    }

                    if (this.hulkSmashUntil) drawHulkSmash(this);
                    if (this.clobberinUntil) drawClobberin(this);
                    if (this.zeroShockUntil) drawZeroShock(this);

                    const now = gameNow();
                    if (now < this.chokedUntil) {
                        // A choke is a stun, but it should not read as one — the
                        // zap's cyan ring says "shocked", this says "held".
                        drawForceChoke(this);
                    } else if (now < this.stunnedUntil) {
                        ctx.strokeStyle = '#7efcff';
                        ctx.lineWidth = 3;
                        ctx.setLineDash([6, 6]);
                        ctx.beginPath();
                        ctx.arc(this.x, this.y, CHARACTER_SIZE + 6, 0, Math.PI * 2);
                        ctx.stroke();
                        ctx.setLineDash([]);
                    } else if (now < this.knockedOutUntil) {
                        ctx.fillStyle = '#ffffff';
                        ctx.font = `14px ${getCanvasFontFamily()}`;
                        ctx.fillText('Zzz', this.x - 12, this.y - 25);
                    }

                    // Ground covered since the last frame this entity was drawn.
                    // draw() runs once per entity per frame, after update(), so
                    // this is exactly one frame of movement — locomotion, knockback,
                    // wind and cover push-out alike.
                    const stepX = this.x - this.lastDrawX;
                    const stepY = this.y - this.lastDrawY;
                    this.lastDrawX = this.x;
                    this.lastDrawY = this.y;
                    if (stepX * stepX + stepY * stepY > SPRITE_WALK_EPSILON_SQ) {
                        this.spriteWalkUntil = frameNow + SPRITE_WALK_TAIL_MS;
                    }
                    // Only fills the gap where the kit sees nothing happening: a
                    // swing, a dash and a shot all still outrank the gait, exactly
                    // as stateFor orders them.
                    let spriteState = SpriteKit.stateFor(this, frameNow);
                    if (spriteState === 'idle' && frameNow < this.spriteWalkUntil) {
                        spriteState = 'walk';
                    }

                    // Where this entity is inside the action the state names.
                    // Without it the kit falls back to a free-running clock, so a
                    // recoil plays on a 240ms loop of its own and only lands on a
                    // shot by luck — the gun mostly doesn't kick when it fires,
                    // and sometimes kicks when it didn't. Both actions are already
                    // timestamped for the hit logic, so the progress is known.
                    let spritePhase;
                    if (spriteState === 'fire') {
                        spritePhase = (frameNow - this.lastShotTime) / 240;
                    } else if (spriteState === 'swing' && swinging) {
                        // The same value the blade above was drawn on, so the
                        // beam and the hand holding it move as one.
                        spritePhase = swingPhase;
                    }

                    // Halloween: the burnt aura and the slung shield go UNDER the
                    // body; a raised shield goes over it, below.
                    drawBurntAura(this);
                    drawHalloweenShield(this, 'back');

                    SpriteKit.drawFighter(ctx, {
                        x: this.x, y: this.y,
                        scale: bodyScale(this),
                        angle: this.lastAimAngle || 0,
                        color: this.color,
                        kit: SpriteKit.kitFor(this),
                        weapon: this.weapon,
                        weaponConfig: this.weaponConfig,
                        // saberColor is a *blade* colour, and it defaults to the
                        // character's own body colour when a roster entry omits it
                        // — fine for a lightsaber, wrong for anything else. Venom
                        // carries no saberColor, so his claws were being tinted
                        // #2a2a33, his own near-black, and vanished into him. Only
                        // the blade family takes the per-character colour; every
                        // other weapon wears the colour its own config declares,
                        // which is what the spec sheet shows for all of them.
                        weaponColor: hostDrawsBlade
                            ? this.saberColor
                            : this.weaponConfig.color,
                        reach: this.weaponConfig.reach || 0,
                        bladeless: true,   // game.js owns the beam and its trail
                        state: spriteState,
                        phase: spritePhase,
                        // The kit flashes the torso inside the body transform, so
                        // the helmet, shoulders and weapon stay readable through a
                        // hit. The overlay this replaces was a flat disc in world
                        // space that covered the whole silhouette — every hit put
                        // the ball back.
                        hitFlash: frameNow < this.hitFlashUntil ? 1 : 0,
                        t: frameNow
                    });

                    drawHalloweenShield(this, 'front');

                    // Sith dark aura pulse. Villain membership carries it for the
                    // shipped roster; CUSTOM_SITH_IDS carries it for creations,
                    // whose nature is chosen separately from their allegiance —
                    // a Sith-natured hero keeps the aura, and a plain character
                    // filed among the villains does not get one.
                    if (this.characterId &&
                        (VILLAIN_ID_SET.has(this.characterId) || CUSTOM_SITH_IDS.has(this.characterId))) {
                        const pulseAlpha = 0.15 + 0.1 * Math.sin(Date.now() / 500);
                        ctx.save();
                        ctx.globalAlpha = pulseAlpha;
                        ctx.fillStyle = '#440000';
                        ctx.shadowBlur = 20;
                        ctx.shadowColor = '#660000';
                        ctx.beginPath();
                        ctx.arc(this.x, this.y, CHARACTER_SIZE + 12, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.restore();
                    }

                    // Whatever the Zero Point fitted to the mech. Cosmetic — see
                    // drawGuardianSkinAura, which is the whole of what a skin does
                    // beyond the chassis colour.
                    if (this.characterId === GUARDIAN_CHAR_ID) drawGuardianSkinAura(this);

                    // On fire. Licks of flame rising off the body, so a burning
                    // target is readable at a glance rather than only through the
                    // ticking damage numbers. Drawn from a time-seeded angle per
                    // tongue so they flicker without needing any stored state.
                    if (this.burningUntil && gameNow() < this.burningUntil) {
                        const t = Date.now() / 90;
                        ctx.save();
                        ctx.globalAlpha = 0.55 + 0.2 * Math.sin(t * 1.7);
                        ctx.shadowBlur = 14;
                        ctx.shadowColor = '#ff5500';
                        const tongues = reducedMotion ? 3 : 6;
                        for (let i = 0; i < tongues; i++) {
                            const a = (i / tongues) * Math.PI * 2 + Math.sin(t + i) * 0.35;
                            const rise = 6 + ((Math.sin(t * 1.3 + i * 2.1) + 1) / 2) * 10;
                            const fx = this.x + Math.cos(a) * (CHARACTER_SIZE * 0.7);
                            const fy = this.y + Math.sin(a) * (CHARACTER_SIZE * 0.5) - rise * 0.5;
                            const r = 3 + ((Math.sin(t * 2 + i) + 1) / 2) * 3;
                            const grad = ctx.createRadialGradient(fx, fy, 0, fx, fy, r);
                            grad.addColorStop(0, '#fff0a0');
                            grad.addColorStop(0.5, '#ff7722');
                            grad.addColorStop(1, 'rgba(255,40,0,0)');
                            ctx.fillStyle = grad;
                            ctx.beginPath(); ctx.arc(fx, fy, r, 0, Math.PI * 2); ctx.fill();
                        }
                        ctx.restore();
                    }

                    // Clone commander rank marker
                    if (this.isClone && this.characterId && cloneBackupLeaders.has(resolveCloneBaseId(this.characterId))) {
                        ctx.save();
                        ctx.fillStyle = '#ffd700';
                        ctx.shadowBlur = 8;
                        ctx.shadowColor = '#ffd700';
                        ctx.beginPath();
                        ctx.arc(this.x, this.y - CHARACTER_SIZE - 8, 4, 0, Math.PI * 2);
                        ctx.fill();
                        ctx.restore();
                    }

                    // Hit flash is drawn by the kit now — see the hitFlash option
                    // on drawFighter above.

                    // Force Choke recharge — Vader has no HUD meter of his own, so
                    // the cooldown is drawn as an arc under his feet.
                    if (this.isMainEntity && canForceChoke(this)) {
                        drawForceChokeCooldown(this);
                    }
                    // Player's only. The enemy's lead is a main entity too, and an
                    // AI Thanos never snaps, so an arc under him would be a lie.
                    if (this === mainPlayer && canInfinitySnap(this)) drawInfinitySnapCharge(this);

                    // Name plate above character
                    ctx.save();
                    ctx.font = `bold 10px ${getCanvasFontFamily()}, sans-serif`;
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    const label = this.name.length > 16 ? this.name.slice(0,14)+'…' : this.name;
                    const tw = ctx.measureText(label).width;
                    // Held inside the arena. A fighter can stand with their centre a
                    // body's width from the wall, and a plate centred on them then
                    // hung half off it — "akin Skywalker" at the left edge. The plate
                    // slides along the wall instead, so it stops being centred right
                    // where it would otherwise stop being readable.
                    const halfPlate = tw / 2 + 5;
                    const px = Math.min(Math.max(this.x, halfPlate + 2), canvasLogicalW - halfPlate - 2);
                    const py = Math.max(this.y - CHARACTER_SIZE - 14, 9);
                    ctx.fillStyle = 'rgba(0,0,0,0.55)';
                    ctx.beginPath(); ctx.roundRect(px - tw/2 - 5, py - 7, tw + 10, 14, 3); ctx.fill();
                    ctx.fillStyle = this.isMainEntity ? '#ffffff' : 'rgba(255,255,255,0.7)';
                    ctx.fillText(label, px, py);
                    ctx.restore();
                }

                updateHealth(damage) {
                    this.health = Math.max(0, this.health - damage);
                    // Under half a point is dead. Damage is fractional all over:
                    // variance, the point-blank x1.4, the choke's per-frame slices,
                    // splash. So health could come to rest at something like 0.3.
                    // The HUD rounds (hudStatusText), so that fighter read "HP: 0"
                    // with an empty bar and stayed on their feet, because this
                    // only ever checked for exactly zero. 0.5 is the rounding line
                    // itself: anything the HUD shows as 0 is now 0.
                    if (this.health < 0.5) this.health = 0;
                    if (this.health === 0 && this.isAlive) {
                        this.isAlive = false;
                        // A Halloween team fighter's death is saved the moment it
                        // happens, so quitting the fight cannot take it back.
                        if (halloweenRun && this.team === 'player' && this.halloweenSlot != null) onHalloweenTeamDeath(this);
                        // death explosion with screen shake
                        triggerScreenShake(8, 15);
                        for (let k = 0; k < 22; k++) {
                            const a = Math.random() * Math.PI * 2;
                            const sp = Math.random() * 4.5 + 1;
                            if (deathParticles.length < MAX_DEATH_PARTICLES) deathParticles.push({ x: this.x, y: this.y, dx: Math.cos(a)*sp, dy: Math.sin(a)*sp, life: 35, maxLife: 35, color: this.color, r: Math.random()*3+1.5 });
                        }
                        if (this.team === 'enemy') {
                            killCount++;
                            // Combo kill tracking
                            const now = gameNow();
                            comboKills.push(now);
                            comboKills = comboKills.filter(k => now - k < 5000);
                            updateComboCounter();
                            if (comboKills.length >= 3) {
                                // Earned mid-fight, off a five-second kill window —
                                // it has to land while that window still means
                                // something to the player.
                                tryUnlockAchievementWithAnnouncement('comboMaster', "Three kills within five seconds — a bounty hunter's deadly efficiency. Jango Fett (Elite) has joined your roster.", '#0066cc', true);
                            }
                            // Check if this was the final kill for slow motion
                            const aliveEnemies = entities.filter(e => e.team === 'enemy' && e.isAlive && e !== this);
                            // Not between waves: a Halloween round's board empties
                            // many times before the round is actually over.
                            if (aliveEnemies.length === 0 && !halloweenWaveHasMore()) {
                                triggerSlowMotion(0.3, 40);
                            }
                        }
                        // Clone commander death: make backup clones flee
                        if (this.isClone && this.isMainEntity && cloneBackupLeaders.has(resolveCloneBaseId(this.characterId))) {
                            entities.forEach(e => {
                                if (e.isClone && !e.isMainEntity && e.team === this.team && e.isAlive) {
                                    e.isFleeing = true;
                                    e.hasFled = true; // Mark as fled so they don't count as killed
                                    
                                    // Find the enemy to flee from
                                    const enemy = entities.find(ent => ent.team !== e.team && ent.isAlive);
                                    if (enemy) {
                                        // Flee away from the enemy
                                        const angleToEnemy = Math.atan2(enemy.y - e.y, enemy.x - e.x);
                                        const fleeAngle = angleToEnemy + Math.PI; // Opposite direction
                                        
                                        e.vx = Math.cos(fleeAngle) * 8;
                                        e.vy = Math.sin(fleeAngle) * 8;
                                    } else {
                                        // If no enemy found, flee towards nearest edge
                                        const distToLeft = e.x;
                                        const distToRight = canvasLogicalW - e.x;
                                        const distToTop = e.y;
                                        const distToBottom = canvasLogicalH - e.y;
                                        
                                        const minDist = Math.min(distToLeft, distToRight, distToTop, distToBottom);
                                        let fleeAngle;
                                        if (minDist === distToLeft) fleeAngle = Math.PI;
                                        else if (minDist === distToRight) fleeAngle = 0;
                                        else if (minDist === distToTop) fleeAngle = -Math.PI/2;
                                        else fleeAngle = Math.PI/2;
                                        
                                        e.vx = Math.cos(fleeAngle) * 8;
                                        e.vy = Math.sin(fleeAngle) * 8;
                                    }
                                }
                            });
                        }
                    }
                }
            }

            class Projectile {
                constructor(x, y, dx, dy, weaponConfig, owner) {
                    this.x = x;
                    this.y = y;
                    this.dx = dx;
                    this.dy = dy;
                    this.weaponConfig = weaponConfig;
                    this.owner = owner;
                    this.color = weaponConfig.color || owner.color;
                    this.damage = weaponConfig.damage;
                    this.variance = weaponConfig.variance || 0;
                    this.type = weaponConfig.key;
                    this.spin = !!weaponConfig.spin;
                    this.spinAngle = Math.random() * Math.PI * 2;
                    this.rotation = Math.atan2(dy, dx);
                    this.blocked = false;
                    this.travelled = 0;
                    this.maxRange = weaponConfig.maxRange || 0;
                    // Spent-flight behaviour. See the veer block in step(): a weapon
                    // carrying this does not blink out of existence the moment it
                    // reaches maxRange, it goes dead and keeps flying.
                    this.spentVeer = weaponConfig.spentVeer || null;
                    // Dev-menu aimbot. Stamped here so every way of firing — ordinary
                    // trigger, each round of a multishot, a charged release — is
                    // covered by one line. Only the player's shots ever carry it.
                    this.homing = !!(devAimbotEnabled && owner && owner === mainPlayer);
                    this.spent = false;
                    this.spentAge = 0;
                    this.veerDir = 0;
                }

                /** Turn a thrown blade around and start it flying home.
                 *
                 *  The return sound belongs here, at the moment the blade turns —
                 *  that is the sound of it being called back, and it needs to be
                 *  audible for the whole flight home. It used to fire on arrival
                 *  instead, by which point the return was already over.
                 *
                 *  Every site that starts a return goes through this: the blade can
                 *  turn at max distance, off the edge of the arena, on hitting cover,
                 *  or on hitting an enemy, and each used to set the flag by hand. */
                beginReturn() {
                    if (this.returning) return;
                    this.returning = true;
                    // Gated exactly as the throw is. A hammer that left the hand in
                    // silence must not come back on a lightsaber sample.
                    if (isEnergyBlade(this.type)) playSound(bladeReturnSfx(this.type), 200);
                }

                step(tickScale) {
                    /*  Homing, for the dev-menu aimbot. Turns the velocity toward the
                     *  nearest enemy by at most AIMBOT_TURN a frame, keeping the speed
                     *  it already had — so a homing bolt is the same bolt, steered,
                     *  rather than a faster or slower one.
                     *
                     *  Three things are deliberately excluded. A thrown blade on its
                     *  way home already has a steering rule and two would fight; a
                     *  spent arrow is dead and dead things do not chase; and a shot
                     *  whose owner has died has nothing to aim on its behalf.
                     *
                     *  Runs before the position update so the frame it is fired on is
                     *  already corrected, which is what stops a point-blank shot from
                     *  sailing past a target it was never pointed at.                */
                    if (this.homing && !this.spent && this.owner && this.owner.isAlive
                        && !(this.returnable && this.returning)) {
                        const mark = getClosestEnemy(this.owner);
                        if (mark) {
                            const speed = Math.hypot(this.dx, this.dy);
                            if (speed > 0) {
                                const want = Math.atan2(mark.y - this.y, mark.x - this.x);
                                const have = Math.atan2(this.dy, this.dx);
                                let diff = want - have;
                                while (diff > Math.PI) diff -= Math.PI * 2;
                                while (diff < -Math.PI) diff += Math.PI * 2;
                                const cap = AIMBOT_TURN * tickScale;
                                const ang = have + Math.max(-cap, Math.min(cap, diff));
                                this.dx = Math.cos(ang) * speed;
                                this.dy = Math.sin(ang) * speed;
                            }
                        }
                    }

                    this.x += this.dx * tickScale;
                    this.y += this.dy * tickScale;
                    this.rotation = Math.atan2(this.dy, this.dx);
                    if (this.spin) this.spinAngle += 0.42 * tickScale;

                    const stepDist = Math.hypot(this.dx * tickScale, this.dy * tickScale);
                    this.travelled += stepDist;

                    /*  Out of range. Two ways to end.
                     *
                     *  Without a `spentVeer` block the projectile is simply removed,
                     *  which is right for a flamethrower tongue or a shotgun pellet —
                     *  those are meant to fade out at the edge of their reach and the
                     *  player reads them as a cloud, not as objects.
                     *
                     *  An arrow is an object, and an arrow winking out in mid-air at
                     *  exactly 380px reads as the game breaking rather than as a shot
                     *  falling short. With the block it goes DEAD instead: it stops
                     *  being able to hurt anyone (see the `spent` guard in the bullet
                     *  filter), curves off the line it was aimed along, and flies out
                     *  of the arena under its own momentum, where the ordinary
                     *  off-screen cull takes it like any other missed shot.           */
                    if (this.maxRange > 0 && !this.returnable && this.travelled >= this.maxRange) {
                        if (!this.spentVeer) {
                            this.collected = true;
                            return;
                        }
                        if (!this.spent) {
                            this.spent = true;
                            // Which way it falls away is a coin flip, so two arrows
                            // that run out at the same spot do not curve in formation.
                            this.veerDir = Math.random() < 0.5 ? -1 : 1;
                            /*  A dead arrow that still connects hits twice as hard.
                             *
                             *  Done here, once, rather than at the point of impact:
                             *  applyStatusAndDamage() and every other consumer reads
                             *  `damage` straight off the projectile, so rewriting the
                             *  field at the moment it dies means none of them needs to
                             *  know the rule exists — and it cannot be applied twice.
                             *
                             *  Variance is rolled downstream of this, so a spent hit is
                             *  double the rolled value rather than a separate roll.     */
                            this.damage *= (this.spentVeer.damageMult || 2);
                        }
                    }

                    if (this.spent) {
                        this.spentAge += tickScale;
                        /*  The turn is applied for a fixed number of frames and then
                         *  stops, which is load-bearing rather than cosmetic. A
                         *  constant turn rate is a circle — at speed 13 the radius is
                         *  small enough to sit INSIDE the arena — so a permanently
                         *  veering arrow would orbit forever and never reach the cull.
                         *  It drifts for a third of a second, straightens, and leaves.
                         *
                         *  The total drift is `turn * veerFrames` radians, and it is
                         *  deliberately small. The first pass used 0.045 over 22
                         *  frames, which is 57 degrees — that does not read as an
                         *  arrow losing its line, it reads as an arrow deciding to go
                         *  somewhere else. 0.012 over 22 is about 15 degrees: enough
                         *  to see it fall away from where it was pointed, not enough
                         *  to look steered.                                          */
                        if (this.spentAge < (this.spentVeer.veerFrames || 22)) {
                            const turn = this.veerDir * (this.spentVeer.turn || 0.045) * tickScale;
                            const c = Math.cos(turn), sn = Math.sin(turn);
                            const ndx = this.dx * c - this.dy * sn;
                            const ndy = this.dx * sn + this.dy * c;
                            this.dx = ndx; this.dy = ndy;
                        }
                        // Belt and braces: nothing spent may outlive this, whatever
                        // the geometry does, so a dead arrow can never accumulate.
                        if (this.spentAge > 300) { this.collected = true; return; }
                    }

                    if (this.returnable && !this.returning) {
                        if (this.travelled >= this.maxDistance || this.x < -40 || this.x > canvasLogicalW + 40 || this.y < -40 || this.y > canvasLogicalH + 40) {
                            this.beginReturn();
                        }
                    }

                    if (this.returnable && this.returning && this.owner && this.owner.isAlive) {
                        const returnAngle = Math.atan2(this.owner.y - this.y, this.owner.x - this.x);
                        const speed = this.returnSpeed;
                        this.dx = Math.cos(returnAngle) * speed;
                        this.dy = Math.sin(returnAngle) * speed;
                        if (Math.hypot(this.owner.x - this.x, this.owner.y - this.y) < CHARACTER_SIZE) {
                            // Caught. The sound already played when it turned around.
                            this.collected = true;
                        }
                    }
                }

                draw() {
                    ctx.save();
                    ctx.translate(this.x, this.y);

                    const drawAngle = this.rotation + this.spinAngle;

                    if (this.weaponConfig.draw === 'zap') {
                        ctx.rotate(drawAngle);
                        ctx.strokeStyle = this.color;
                        ctx.lineWidth = 2.5;
                        ctx.shadowBlur = 12;
                        ctx.shadowColor = this.color;
                        ctx.beginPath();
                        ctx.moveTo(-2, 0); ctx.lineTo(5, -4); ctx.lineTo(10, 4); ctx.lineTo(16, -3); ctx.lineTo(22, 3);
                        ctx.stroke();

                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 1.2;
                        ctx.shadowBlur = 4;
                        ctx.beginPath();
                        ctx.moveTo(-2, 0); ctx.lineTo(5, -4); ctx.lineTo(10, 4); ctx.lineTo(16, -3); ctx.lineTo(22, 3);
                        ctx.stroke();
                    } else if (this.weaponConfig.draw === 'wrench') {
                        // No glow. Steel is lit by the arena, not by itself — the
                        // shadowBlur that used to be here gave a lump of tooling the
                        // same halo as a plasma blade, which is the one visual cue
                        // that is supposed to separate the two kinds of weapon.
                        ctx.rotate(drawAngle);
                        ctx.fillStyle = '#b8bec7';
                        ctx.strokeStyle = '#7b8794';
                        ctx.lineWidth = 2;
                        ctx.shadowBlur = 0;
                        ctx.beginPath(); ctx.roundRect(-10, -3, 18, 6, 2); ctx.fill(); ctx.stroke();
                        ctx.beginPath(); ctx.roundRect(5, -7, 10, 14, 3); ctx.fill(); ctx.stroke();
                        ctx.shadowBlur = 0;
                        ctx.fillStyle = '#7b8794';
                        ctx.beginPath(); ctx.arc(10, 0, 2.8, 0, Math.PI * 2); ctx.fill();
                    } else if (this.weaponConfig.draw === 'staff') {
                        ctx.rotate(drawAngle);
                        ctx.strokeStyle = this.color;
                        ctx.lineWidth = 6;
                        ctx.shadowBlur = 14;
                        ctx.shadowColor = this.color;
                        ctx.globalAlpha = 0.75;
                        ctx.beginPath(); ctx.moveTo(-this.weaponConfig.length / 2, 0); ctx.lineTo(this.weaponConfig.length / 2, 0); ctx.stroke();

                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 2;
                        ctx.shadowBlur = 4;
                        ctx.globalAlpha = 1;
                        ctx.beginPath(); ctx.moveTo(-this.weaponConfig.length / 2, 0); ctx.lineTo(this.weaponConfig.length / 2, 0); ctx.stroke();
                    } else if (this.weaponConfig.draw === 'saber') {
                        ctx.rotate(drawAngle);
                        ctx.lineCap = 'round';
                        ctx.strokeStyle = this.owner.saberColor || this.color;
                        ctx.lineWidth = 6;
                        ctx.shadowBlur = 16;
                        ctx.shadowColor = this.owner.saberColor || this.color;
                        ctx.globalAlpha = 0.7;
                        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(this.weaponConfig.length, 0); ctx.stroke();

                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 2;
                        ctx.shadowBlur = 5;
                        ctx.globalAlpha = 1;
                        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(this.weaponConfig.length, 0); ctx.stroke();
                    } else if (this.weaponConfig.draw === 'blade') {
                        // Steel blades — the Vibroblade, the Seeker's Sword and the
                        // Pickaxe. Sharpened metal, not plasma: the body is the
                        // weapon's own colour and the edge is a bright highlight
                        // along it, which is how a blade catches light. Nothing here
                        // emits any, so a physical sword can never be mistaken for a
                        // sabre at a glance.
                        ctx.rotate(drawAngle);
                        ctx.lineCap = 'round';
                        ctx.strokeStyle = this.weaponConfig.color || this.color;
                        ctx.lineWidth = 5;
                        ctx.shadowBlur = 0;
                        ctx.globalAlpha = 1;
                        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(this.weaponConfig.length, 0); ctx.stroke();
                        // The sharpened edge, drawn thin and offset so it reads as a
                        // highlight running down one side rather than a core.
                        ctx.strokeStyle = '#eef6ff';
                        ctx.lineWidth = 1.4;
                        ctx.globalAlpha = 0.9;
                        ctx.beginPath(); ctx.moveTo(2, -1.2); ctx.lineTo(this.weaponConfig.length - 2, -1.2); ctx.stroke();
                        ctx.globalAlpha = 1;
                        // Hilt
                        ctx.strokeStyle = '#555';
                        ctx.lineWidth = 4;
                        ctx.shadowBlur = 0;
                        ctx.beginPath(); ctx.moveTo(-4, 0); ctx.lineTo(4, 0); ctx.stroke();
                    } else if (this.weaponConfig.draw === 'flame') {
                        // Flamethrower particle — soft orange/yellow blob that fades with range
                        const lifeFade = this.maxRange > 0 ? Math.max(0.25, 1 - this.travelled / this.maxRange) : 0.9;
                        ctx.rotate(this.rotation);
                        ctx.globalAlpha = lifeFade;
                        const r = 6 + Math.random() * 4;
                        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                        grad.addColorStop(0, '#fff0a0');
                        grad.addColorStop(0.45, this.color || '#ff6622');
                        grad.addColorStop(1, 'rgba(255,40,0,0)');
                        ctx.fillStyle = grad;
                        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
                        ctx.globalAlpha = 1;
                    } else {
                        ctx.rotate(this.rotation);
                        ctx.fillStyle = this.color;
                        ctx.shadowBlur = 8;
                        ctx.shadowColor = this.color;
                        ctx.fillRect(0, -2, this.weaponConfig.length, 4);
                    }
                    ctx.restore();
                }
            }

            let selectedPlayerCharId = null;
            let specialCloudCityJabbaForce = false;
            let specialCloudCityJabbaHold = 0;
            let specialCloudCityJabbaSpawned = false;
            let specialCloudCityJabbaCharacter = null;
            let specialCloudCityGuardTimer = 0;
            let playableJabbaGuardCount = 0;
            let playableJabbaNextGuard = 0;

            function isCharacterUnlocked(char) {
                if (char.unlockAchievement && !achievements[char.unlockAchievement]?.done) return false;
                if (char.secretUnlock && !gameUnlocks[char.secretUnlock]) return false;
                return true;
            }

            // Gated characters (locked behind an achievement or shop/secret unlock) are never
            // fair game as an AI opponent by default — only the characters available from the
            // start can show up in the opponent selector or via the Surprise Me button. The dev
            // menu "Allow unlocked gated opponents" toggle lets locked-and-then-unlocked gated
            // characters (e.g. shop purchases) be selected as opponents too, for testing.
            function isCharacterAvailableAsOpponent(char) {
                // Some gated characters exist to be fought as much as to be bought.
                // Sith Anakin is the Charred Anakin unlock condition, so paywalling
                // him as an opponent would paywall a unlock that has always been
                // free — his shop entry gates playing AS him, nothing more.
                if (isCharacterRetired(char)) return false;
                // Turning the season faction view on is an explicit request for the
                // season roster, so owning one of its fighters is enough to point
                // them at each other. The dev-menu gate below is about gated
                // characters turning up where they were not asked for; this is the
                // opposite case.
                if (packFactionViewActive() && char.packId) return isCharacterUnlocked(char);
                if (marvelFactionViewActive() && char.marvel) return isCharacterUnlocked(char);
                if (halloweenFactionViewActive() && char.halloween) return isCharacterUnlocked(char);
                if (char.alwaysOpponent) return true;
                const isGated = !!(char.unlockAchievement || char.secretUnlock);
                if (!isGated) return true;
                if (!isCharacterUnlocked(char)) return false;
                return devAllowGatedOpponents;
            }

            // The Zero Point encounter: the single matchup that retires The Visitor
            // and puts Geno on the roster. Everything about it is stated here rather
            // than spread across the picker, the arena row and the win check.
            const ZERO_POINT_ENCOUNTER = {
                arena:      'zeropoint',
                playerId:   'visitor',
                opponentId: 'vengeancejones',
                unlocks:    'geno'
            };

            /** The opponent to put on the board for this encounter, or null when the
             *  conditions are not met. Owning Vengeance Jones is deliberately not one
             *  of them — the same call Sith Anakin's alwaysOpponent makes. Standing
             *  as The Visitor at the Zero Point gets you the fight; a 550-credit
             *  purchase should not be a gate on a character you cannot buy at all. */
            function zeroPointEncounterOpponent(playerCharId) {
                const e = ZERO_POINT_ENCOUNTER;
                if (gameUnlocks[e.unlocks]) return null;
                if (playerCharId !== e.playerId || currentArena !== e.arena) return null;
                const opp = characters.secret.find(c => c.id === e.opponentId) || null;
                // The Zero Event ended this opponent along with the rest of the
                // pack roster, and this row is the one place that puts a fighter
                // on the board without going through the ordinary availability
                // check — so a retired opponent would still be offered here.
                if (opp && isCharacterRetired(opp)) return null;
                // With the season view on he is already standing in the New Seven
                // column, so putting him in the encounter slot as well would list him
                // twice.
                if (opp && packFactionViewActive() && isCharacterUnlocked(opp)) return null;
                return opp;
            }

            /** Adds or removes the encounter button. Called when the picker opens and
             *  again on every arena change, because the arena row lives on the picker
             *  screen — the player chooses who to fight and where in either order. */
            function refreshZeroPointEncounter(playerCharId) {
                const container = document.getElementById('opp-villain-roster');
                if (!container) return;
                const existing = container.querySelector('.zero-point-encounter');
                if (existing) existing.remove();

                const opp = zeroPointEncounterOpponent(playerCharId);
                if (!opp) return;

                // Secret-roster styling rather than the villain column's, so it reads
                // as the one entry here that is not part of the ordinary roster.
                const btn = makeRosterButton(opp, 'game-button secret-button zero-point-encounter', () => {
                    hideStatCard();
                    mainMenu.style.display = 'none';
                    opponentMenu.style.display = 'none';
                    setupGame(playerCharId, opp.id);
                });
                container.prepend(btn);
            }

            const oppHeroContainer = document.getElementById('opp-hero-roster');
            const oppVillainContainer = document.getElementById('opp-villain-roster');
            const oppSearchInput = document.getElementById('oppSearchInput');

            /** The opponent screen's two columns. Same renderer, same order, same
             *  search behaviour and the same season faction view as the roster — the only
             *  differences are the ones that have to differ: who may be fought, and
             *  that a click starts the match instead of opening this screen.
             *
             *  Safe to call when the screen is closed; it just redraws hidden DOM. */
            function rebuildOpponentRosters() {
                if (!selectedPlayerCharId) return;

                const opts = {
                    searchBox: oppSearchInput,
                    isAvailable: isCharacterAvailableAsOpponent,
                    onPick: char => {
                        hideStatCard();
                        mainMenu.style.display = 'none';
                        opponentMenu.style.display = 'none';
                        setupGame(selectedPlayerCharId, char.id);
                    },
                    // The fighter you are already playing, marked where they appear in
                    // the opposing list — a mirror match is allowed, it just should not
                    // be picked by accident.
                    decorate: (btn, char) => {
                        if (char.id === selectedPlayerCharId) btn.style.outline = '2px dashed rgba(255,255,255,0.3)';
                    }
                };

                renderRosterColumn(oppHeroContainer, seasonFactionColumn('heroes') || characters.heroes, 'game-button hero-button', opts);
                renderRosterColumn(oppVillainContainer, seasonFactionColumn('villains') || characters.villains, 'game-button villain-button', opts);
                refreshZeroPointEncounter(selectedPlayerCharId);
            }

            // Attached once. This used to be wired up inside showOpponentPicker, so it
            // gained another copy of itself every time the screen was opened.
            if (oppSearchInput) oppSearchInput.addEventListener('input', rebuildOpponentRosters);

            function showOpponentPicker(playerCharId) {
                selectedPlayerCharId = playerCharId;
                const pChar = findRosterChar(playerCharId);
                if (!pChar) return;

                vsBannerPlayer.textContent = pChar.name;
                vsBannerPlayer.style.color = pChar.color;

                rebuildOpponentRosters();

                mainMenu.style.display = 'none';
                opponentMenu.style.display = 'flex';

                setTimeout(() => {
                    const surprise = document.getElementById('surpriseBtn');
                    if (surprise) surprise.focus();
                }, 50);
            }

            surpriseBtn.addEventListener('click', () => {
                if (!selectedPlayerCharId) return;
                const all = [...characters.heroes, ...characters.villains];
                // findRosterChar rather than a search of the two Galactic columns:
                // every season fighter lives in characters.secret, so the old lookup
                // could not see one at all. See surpriseRosterOf().
                const playerChar = findRosterChar(selectedPlayerCharId);
                const roster = surpriseRosterOf(playerChar);
                
                // Three steps out, and never further than it has to go. Each one is
                // filtered for availability rather than assumed, because an
                // unavailable fighter in the pool is how Surprise Me used to offer a
                // dead one like The Voidblade after the Zero Event.
                //
                //   1. The half of the player's own roster facing them. This is the
                //      answer in every ordinary case.
                //   2. The rest of their own roster, if their opposite number has
                //      nobody available. A Marvel pick can reach here and still be
                //      Marvel, which is the point.
                //   3. Everything else — and ONLY as the last resort, for a season
                //      whose entire cast can be retired out from under it. The Zero
                //      Event does exactly that to a pack roster, and a button
                //      that silently does nothing is worse than an off-roster
                //      opponent. Marvel cannot reach this step: none of its seven are
                //      gated or retirable, so step 1 always has somebody in it.
                let opponentPool = roster.opposing.filter(isCharacterAvailableAsOpponent);
                if (!opponentPool.length) {
                    opponentPool = roster.sides.filter(c =>
                        c.id !== selectedPlayerCharId && isCharacterAvailableAsOpponent(c));
                }
                if (!opponentPool.length) {
                    opponentPool = all.filter(c =>
                        c.id !== selectedPlayerCharId && isCharacterAvailableAsOpponent(c));
                }
                
                // Exception: Obi-Wan can randomly pick Sith Anakin for the Charred
                // Anakin unlock. This used to look for 'anakin' in characters.villains
                // — but Anakin lives in characters.heroes, so the lookup always came
                // back undefined and the `if (!random) return` below ate the click:
                // 15% of Obi-Wan's Surprise Me presses did nothing at all. Sith Anakin
                // is a villain, so the lookup now resolves, and the fallback covers it
                // regardless.
                let random;
                if (selectedPlayerCharId === 'obiwan' && !gameUnlocks.charredAnakin && Math.random() <= 0.15) {
                    random = characters.villains.find(c => c.id === 'sith_anakin');
                    if (!random) random = opponentPool.length > 0 ? opponentPool[Math.floor(Math.random() * opponentPool.length)] : null;
                } else if (currentArena === 'cloudcity' && selectedPlayerCharId === 'leia' && (specialCloudCityJabbaForce || Math.random() < 0.2)) {
                    random = characters.unplayable.find(c => c.id === 'carbonite_han');
                    specialCloudCityJabbaForce = false;
                    if (!random) random = opponentPool.length > 0 ? opponentPool[Math.floor(Math.random() * opponentPool.length)] : null;
                    // Tells the player what to do in the match that is about to
                    // start, so it must not sit in the queue behind it.
                    //
                    // Deliberately says nothing about what freeing Han sets off —
                    // Jabba turning up is the surprise, and naming him here would
                    // hand it over before the player has taken a step.
                    else showAnnouncement('Han is frozen in carbonite somewhere on this platform. Find him and hold ' + boundKeyLabel('interact') + ' to free him.', '#888888', 5000, '🧊 CARBONITE EVENT', 50, true);
                } else {
                    random = opponentPool.length > 0 ? opponentPool[Math.floor(Math.random() * opponentPool.length)] : null;
                }
                
                if (!random) return;
                opponentMenu.style.display = 'none';
                setupGame(selectedPlayerCharId, random.id);
            });

            backBtn.addEventListener('click', () => {
                playMenuMusic();
                opponentMenu.style.display = 'none';
                mainMenu.style.display = 'flex';
                selectedPlayerCharId = null;
            });

            // Fighter select → splash. See the note on #rosterBaseBtn in index.html.
            const rosterBaseBtn = document.getElementById('rosterBaseBtn');
            if (rosterBaseBtn) rosterBaseBtn.addEventListener('click', () => {
                selectedPlayerCharId = null;
                showSplashMenu();
            });

            /** A character's health as it stands now. Applied at the point the
             *  fighter is built rather than by rewriting the roster entry, so the
             *  data on disk stays the data that shipped. */
            function effectiveCharHp(charData) {
                if (!charData) return 0;
                return charData.hp;
            }
            // What the buttons the event borrows say when nothing has renamed
            // them. Taken from index.html, where they ship.
            const BORROWED_BTN_DEFAULTS = {
                nextRoundButton: 'Next Round ▶',
                restartButton: 'Return to Base',
                // The pause menu's Quit is borrowed as well: during a run it is the
                // only route to the phase-two penalty, and at any other point it
                // throws away every stage banked so far.
                pauseQuitBtn: '✕ Quit Battle'
            };

            /** Puts every borrowed button back to its shipped wording.
             *
             *  The Zero Event renames them — Next Round becomes Continue, Return to
             *  Base becomes Quit the Event, Quit Battle becomes Abandon the Run —
             *  and nothing changed them back. The labels are on nodes that live
             *  across matches, so once a player had run the event even once, every
             *  ordinary duel afterwards offered them 'Continue' and 'Quit the Event'
             *  for the rest of the session. */
            function resetBorrowedButtonLabels() {
                for (const [id, label] of Object.entries(BORROWED_BTN_DEFAULTS)) {
                    const btn = document.getElementById(id);
                    if (btn) btn.textContent = label;
                }
            }
            /*  Repaint the player's HUD card from whatever mainPlayer currently IS,
             *  rather than from the character they picked. Two things move that
             *  apart: the Zero Event handing the player a different body, and Loki
             *  wearing someone else's shape.
             *
             *  `weaponLabel` is for the second case only. The takeover rewrites
             *  pCharData before it calls here, so the roster-derived label is
             *  correct for it — and going through weaponLabelFor() is what keeps a
             *  droid's "ZAP / BLASTER" secondary in the label. A shapeshift must
             *  NOT rewrite pCharData (the end-of-round contract context reads it,
             *  and Loki's own contracts would stop counting), so it passes the
             *  label it is actually holding instead.                             */
            function syncPlayerHudCard(weaponLabel) {
                if (!mainPlayer) return;
                const portrait = document.getElementById('playerPortrait');
                if (portrait) {
                    portrait.textContent = weaponEmojiFor(mainPlayer.weapon);
                    portrait.style.color = mainPlayer.color;
                    portrait.style.borderColor = mainPlayer.color;
                    portrait.style.boxShadow = `0 0 10px ${mainPlayer.color}55`;
                }
                if (playerLabel) {
                    playerLabel.textContent = mainPlayer.name;
                    playerLabel.style.color = mainPlayer.color;
                }
                if (playerHealthBar) playerHealthBar.style.backgroundColor = mainPlayer.color;
                const label = document.getElementById('playerWeaponLabel');
                if (label) {
                    if (weaponLabel) label.textContent = weaponLabel;
                    else if (pCharData) label.textContent = weaponLabelFor(pCharData);
                }
            }

            /*  ── THE CARD AFTER A TRANSFORM ────────────────────────────────────
             *  A fighter who turns into something else changes all four things the
             *  top card is made of — portrait, name, colour and weapon — and the
             *  card used to keep showing whoever walked in. Stane spent the back
             *  half of a round labelled OBADIAH STANE · SONIC TASER while swinging
             *  the Iron Monger's fists, and an AI one did it where the player could
             *  read it the whole time.
             *
             *  Reads the live ENTITY, never a roster record, which is the whole
             *  reason this is not just another setEnemyHud() call: the roster entry
             *  still says Obadiah Stane and always will. After a transform the
             *  entity is the only thing telling the truth.
             *
             *  Safe to call for anyone. An entity that is neither the player nor the
             *  one the enemy panel is following is ignored, so a transformed backup
             *  fighter cannot repaint somebody else's card.                        */
            function refreshHudIdentity(e) {
                if (!e) return;
                const weaponText = ((e.weaponConfig && e.weaponConfig.label) || e.weapon || '').toUpperCase();

                if (e === mainPlayer) {
                    syncPlayerHudCard(weaponText);
                    return;
                }
                if (e !== (hudEnemyEntity || mainEnemy)) return;

                const portrait = document.getElementById('enemyPortrait');
                if (portrait) {
                    portrait.textContent = weaponEmojiFor(e.weapon);
                    portrait.style.color = e.color;
                    portrait.style.borderColor = e.color;
                    portrait.style.boxShadow = `0 0 10px ${e.color}55`;
                }
                if (enemyLabel) {
                    enemyLabel.textContent = e.name;
                    enemyLabel.style.color = e.color;
                }
                if (enemyHealthBar) enemyHealthBar.style.backgroundColor = e.color;
                const eLabel = document.getElementById('enemyWeaponLabel');
                if (eLabel) eLabel.textContent = weaponText;
            }
            // -- FREEZE -----------------------------------------------------

            /** The Ice Legion's whole contribution to stage 4: you stop being able
             *  to move away from the Ice King.
             *
             *  This reuses `stunnedUntil` rather than adding a parallel status —
             *  exactly as Force Choke does, and for the same reason. A stunned
             *  entity is already locked out of every action by the canAct() gate,
             *  already has its pending melee swing cancelled, and already draws with
             *  a hold ring. A second timer would have to re-earn all three and would
             *  disagree with the first one the moment both were running.
             *
             *  Never shortens an existing hold, so being frozen while choked does
             *  not release you early. */
            /*  ── FREEZE, AND WHY IT HAS AN IMMUNITY WINDOW ──────────────────
             *  The Ice Blast holds for 900ms on a 420ms trigger. Because this
             *  function EXTENDS an existing hold rather than replacing it, that
             *  meant a Mandarin who simply kept hitting re-froze a target roughly
             *  twice per freeze, and the target never got a frame back: an
             *  unbreakable lock that ended the fight on its own. Three Ice Legion
             *  firing at once in the Zero Event did the same thing three times as
             *  fast. It is the exact failure the Web Shooters were given no
             *  freezeMs to avoid — see the note on webshooter in WEAPON_LIBRARY.
             *
             *  The fix is the one the game already uses twice for the same shape
             *  of problem: the zap's 600ms stun on a 300ms trigger, and the
             *  wrench's knockdown, are both survivable only because a stagger buys
             *  a stretch of immunity to the next one. Freeze was the one hard
             *  control with no such window.
             *
             *  The window is stamped forward from the moment the hold is APPLIED,
             *  not granted when it expires. That distinction is the whole fix, and
             *  getting it wrong the obvious way does nothing at all: the zap and
             *  the wrench pay out their immunity from the per-entity update, on
             *  the frame the stagger lapses — but a hold under a chain of
             *  extensions never lapses, so that hook is never reached and the lock
             *  survives untouched. (The zap gets away with the same structure only
             *  because its 40% resist roll lets the stun drop on its own every few
             *  casts. Freeze has no resist roll, so it never dropped.) Covering
             *  "already held" and "just got out" with one forward stamp needs
             *  nothing to notice anything.
             *
             *  1400ms rather than the zap's 1000: this hold is half again as long
             *  and has no resist roll to fail. Against perfect aim the result is
             *  900 locked out of every 2300 — about the 39% the zap already sits
             *  at, instead of 100%.
             *
             *  Deliberately its own window rather than sharing zapImmunityUntil.
             *  Coupling them would let a zap trooper make someone immune to a
             *  Mandarin standing next to him, which is not a rule anyone could
             *  infer from watching.                                             */
            const FREEZE_IMMUNITY_MS = 1400;

            function applyFreeze(entity, ms) {
                if (!entity || !entity.isAlive) return;
                if (entity === mainPlayer && invincibilityEnabled) return;
                const now = gameNow();
                if (now < (entity.freezeImmunityUntil || 0)) {
                    spawnFreezeResist(entity);
                    return;
                }
                entity.stunnedUntil = Math.max(entity.stunnedUntil || 0, now + ms);
                // Still flagged as a stun so the zap's own window is paid out when
                // the hold lapses — a freeze is a stagger like any other.
                entity.wasStunned = true;
                entity.freezeImmunityUntil = now + ms + FREEZE_IMMUNITY_MS;
            }

            /** Feedback for a freeze the immunity window ate. Without it a shot
             *  that should have held someone and did not is indistinguishable from
             *  a miss, and the rule stays invisible. Mirrors spawnDodgeNegation. */
            function spawnFreezeResist(target) {
                spawnHitSparks(target.x, target.y, '#cfe9f5', 5);
                if (target.isMainEntity && floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: target.x + (Math.random() - 0.5) * 20,
                        y: target.y - CHARACTER_SIZE - 10,
                        text: 'RESIST', life: 38, maxLife: 38, dy: -1.2,
                        color: '#cfe9f5', glow: '#7fd4ff'
                    });
                }
            }

            // -- THE SHAPELESS MAN ------------------------------------------

            // The health fraction below which the Shapeless Sprite takes over.
            //
            // This was 15%, and 15% was unreachable in practice. Nothing steps
            // neatly into a band that thin: a 25-damage blaster round against a
            // 150 HP fighter is 17% in one hit, so the usual way to pass through
            // the window was to skip it entirely and die on the far side. A
            // transformation nobody can trigger is not a drawback, it is an
            // absent feature.
            //
            // At 35% the band is wide enough that any single hit lands inside it
            // rather than across it, and it still only opens when the fight has
            // genuinely gone wrong — which is the point of the form.
            //
            // Raised from 30% with the rest of the numbers below. See the note there.
            const SHAPELESS_THRESHOLD = 0.35;

            /*  What the form is actually worth.
             *
             *  These were all deliberately modest, and the reason was balance: the
             *  sprite was obtainable, so a form that swung the last third of a match
             *  too hard would have been the correct thing to farm. Vaulting removes
             *  that premise entirely. Nobody new can get this — the only holders are
             *  saves that already had it and testers using the dev grant — so it is
             *  not a thing to be balanced against the rest of the pool any more. It is
             *  the last one off the shelf, and it should feel like it.
             *
             *  So: faster, hits appreciably harder, and the heal is the real change.
             *  At the 35% trigger a 35% heal stands you back up at about seventy
             *  percent rather than half, which turns the form from "a slightly better
             *  death" into an actual second life.
             *
             *  It still cannot loop: shapelessForm is set before the heal lands,
             *  so being pushed back above the threshold does not re-arm it.        */
            const SHAPELESS_SPEED = 1.40;      // was 1.25
            const SHAPELESS_DAMAGE = 1.60;     // was 1.35
            const SHAPELESS_HEAL = 0.35;       // was 0.20
            // Accuracy, which means two different things depending on who is holding
            // the sprite. A player aims their own weapon, so their shots never
            // deviate — what varies for them is the damage roll, and tightening that
            // is what "more accurate" can honestly mean. An AI does have aim spread,
            // so it gets the other half. Both tightened further, same reasoning as
            // above: at 0.20 the player's ±variance is small enough that a shot which
            // should finish someone reliably does.
            const SHAPELESS_VARIANCE = 0.20;   // was 0.35 — multiplier on the weapon's damage spread
            const SHAPELESS_SPREAD = 0.35;     // was 0.50 — multiplier on AI aim deviation

            /** Below the threshold, a fighter carrying the Shapeless Sprite stops
             *  holding its shape. This is a transformation of the entity already on
             *  the board, not a second boss: it keeps its remaining health, so the
             *  form is a desperation move rather than another health bar to chew
             *  through. What it gains is speed and reach. */
            /*  The form itself, stated here rather than looked up.
             *
             *  It used to read the 'shapeless_man' roster entry, which lived with the
             *  Zero Event cast and went with them. Nothing else ever needed that row
             *  — the transformation only takes a name, a colour and a profile off it
             *  — so the four fields it actually used are the whole of what is left.  */
            const SHAPELESS_FORM = {
                id: 'shapeless_man', name: 'The Shapeless Man',
                color: '#6b5b7b', hp: 420, tacticalProfile: 'reckless'
            };

            function checkShapelessTransform(entity) {
                if (!entity || !entity.isAlive || entity.shapelessForm) return;
                if (!entityHasSprite(entity, 'shapelessSprite')) return;
                if (entity.health / entity.maxHealth > SHAPELESS_THRESHOLD) return;

                const data = SHAPELESS_FORM;
                entity.shapelessForm = true;
                entity.name = data.name;
                entity.color = data.color;
                entity.speedMult = data.speedMult || SHAPELESS_SPEED;
                entity.tacticalProfileOverride = data.tacticalProfile;

                // The form has to hit harder, not just move faster.
                //
                // Everything the transformation set before this was either cosmetic
                // (name, colour) or AI-only (speedMult, tactical profile), so a
                // player who triggered it got a shockwave, a new label and no change
                // whatsoever to the fight. Rebuilding the weapon is what makes it a
                // desperation form rather than a costume: it keeps the same gun on
                // the same trigger, and every round out of it lands harder.
                const shapelessBase = entity.weaponConfig ? entity.weaponConfig.damage : null;
                if (shapelessBase != null) {
                    entity.weaponConfig = getWeapon({
                        weapon: entity.weapon,
                        weaponDamage: shapelessBase * SHAPELESS_DAMAGE
                    });
                    // Accuracy, for a fighter whose shots already go where they are
                    // pointed. The player aims their own weapon, so aim spread is not
                    // what "accurate" can mean for them — what varies is the damage
                    // roll, which swings every hit by ±variance. Tightening it stops
                    // the low rolls, so a shot that should finish someone does.
                    entity.weaponConfig.variance = (entity.weaponConfig.variance || 0) * SHAPELESS_VARIANCE;
                }
                // And the other kind of accuracy, for when the form is on an AI —
                // Geno in his own boss fight. Without this his aim would get worse
                // on transforming, not better, because of the profile he switches to.
                entity.spreadScale = SHAPELESS_SPREAD;

                // Some health back, and said out loud. A number floating off the
                // fighter is how every other heal in the game reports itself, and a
                // silent one is indistinguishable from a broken one.
                const healed = Math.min(entity.maxHealth - entity.health, entity.maxHealth * SHAPELESS_HEAL);
                if (healed > 0) {
                    entity.health += healed;
                    if (floatNums.length < MAX_FLOATS) {
                        floatNums.push({
                            x: entity.x + (Math.random() - 0.5) * 18,
                            y: entity.y - CHARACTER_SIZE - 8,
                            text: '+' + Math.round(healed), life: 46, maxLife: 46, dy: -1.1,
                            color: '#6b5b7b', glow: '#c9b6dd'
                        });
                    }
                }
                spawnBoomBlast(entity.x, entity.y, 70);
                triggerScreenShake(12, 22);
                // Whichever half of the HUD this fighter owns has to be repainted,
                // or the transformation happens and the panel keeps showing who
                // they used to be.
                if (entity === mainEnemy) setEnemyHud(data, entity);
                if (entity === mainPlayer) syncPlayerHudCard();
            }

            // -- THE KAMINO SPRITE ------------------------------------------

            /** A clone of something the player built is called back to fight beside
             *  them. The function name keeps 'ZeroSprite' because the sprite's id
             *  does, and the id is what every save is keyed on.
             *
             *  Triggered on the same threshold the clone commanders use — 25 damage
             *  taken — so it reads as the same kind of thing: you are hurt, and help
             *  arrives. One call per round, and only a chance at that, because a
             *  guaranteed second fighter every round would be worth far more than
             *  any other sprite in the game.
             *
             *  Its whole effect depends on the player having made something, which
             *  is why the sprite refuses to drop at all for someone who has not —
             *  see its `eligible` in SPRITE_CATALOG. */
            function updateZeroSpriteBackup() {
                if (!mainPlayer || !mainPlayer.isAlive) return;
                if (!isSpriteEquipped('zeroSprite')) return;
                if (mainPlayer.calledZeroSprite) return;
                if (mainPlayer.health > mainPlayer.maxHealth - 25) return;

                mainPlayer.calledZeroSprite = true;

                // Compile the creations down to roster entries first, and only then
                // decide there is nobody to call. The old order set the once-per-round
                // flag, then rolled a 55% chance, then looked for a creation — so more
                // than half of all rounds the sprite did nothing at all and said
                // nothing about it, which is indistinguishable from being broken.
                //
                // It fires reliably now. The clone commanders' backup call is
                // deterministic on the same 25-damage threshold and that reads fine;
                // a Mythic that works half the time reads as a bug.
                const roster = createdCharacters.map(r => findRosterChar(r.id)).filter(Boolean);
                if (!roster.length) {
                    // Said out loud rather than returning quietly. This is the one
                    // way the sprite legitimately cannot work, and a player who has
                    // made nothing has no way to tell that from a failure.
                    showAnnouncement('The Zero Point has nothing of yours to send. Build something there and it will answer next time.',
                        '#ff5bd1', 5000, '🌀 ZERO SPRITE', 90, true);
                    return;
                }

                const data = roster[Math.floor(Math.random() * roster.length)];
                spawnBackupAlly(data, `${data.name} steps out of the Zero Point to stand with you.`,
                                '#ff5bd1', '🌀 ZERO SPRITE');
            }

            /** Stand a roster entry up beside the player, on the player's team, for
             *  the rest of the round. Shared by both backup sprites so the two can
             *  never drift apart in how an ally is built. */
            function spawnBackupAlly(data, line, color, title) {
                const ent = new Character(
                    mainPlayer.x + (Math.random() - 0.5) * 70,
                    mainPlayer.y + (Math.random() - 0.5) * 70,
                    data.color, data.arenaName || data.name, data.hp, data.weapon,
                    data.saberColor, data.isDroid, data.isWookiee, 'player', false,
                    data.isClone, data.weaponDamage, data.id
                );
                // The Zero Event cast writes this and it is read for everyone; an
                // ally that ignored it would fight on the weapon-derived default
                // instead of the profile its roster entry asked for.
                ent.tacticalProfileOverride = data.tacticalProfile || null;
                ent.speedMult = data.speedMult || 1;
                entities.push(ent);
                spawnBoomBlast(ent.x, ent.y, 60);
                showAnnouncement(line, color, 4000, title, 90, true);
                return ent;
            }

            // -- THE FURY SPRITE --------------------------------------------

            // How often the call is answered when somebody ELSE is carrying it.
            // Deliberately a real roll, unlike the Kamino Sprite next door, which had
            // its roll taken out because a Mythic that worked half the time read as
            // broken. The difference is that this one SAYS when it fails: a player
            // who hears Fury try and get nobody has watched the sprite work, which is
            // the thing a silent 55% never gave.
            const FURY_SPRITE_CHANCE = 0.6;

            // In Fury's own hands there is no roll. The sprite is his authority, and
            // anyone else carrying it is borrowing his phone — they get whoever
            // happens to pick up, he gets whoever he asks for. That is the entire
            // reason to pick him over a stronger fighter with the same sprite
            // equipped: 150 health is the lowest on this side of the roster, and a
            // guaranteed second body is what it buys.
            //
            // Kept as an id rather than folded into the roster entry because the
            // exception belongs to the SPRITE, not to the character: it is a fact
            // about who the sprite obeys.
            const FURY_SPRITE_OWNER_ID = 'fury';

            /** Who the Fury Sprite can call.
             *
             *  The season's hero column IS the Avengers — it is titled that — so this
             *  reads it rather than keeping a second list beside it: a fighter added
             *  to that column later becomes callable without touching this code.
             *
             *  Two exclusions. Fury himself, because he is the one making the call.
             *  And whoever is carrying the sprite, because backup that is a second
             *  copy of you is not backup. */
            function avengerBackupPool(caller) {
                return marvelSeason().heroes.ids
                    .filter(id => id !== 'fury' && id !== (caller && caller.characterId))
                    .map(findRosterChar)
                    // findRosterChar() is a plain id lookup and knows nothing about
                    // the vault or the shop, so without these two a retired fighter
                    // still answers the call — Fury dialling a Hulk who is not in
                    // the game — and so does an unbought one. The second matters now
                    // that Star-Lord has a price: being handed him free as backup
                    // is most of what the 900 credits buy.
                    //
                    // isCharacterUnlocked() is true for anything with no
                    // secretUnlock, so the seventeen free Avengers are unaffected.
                    .filter(c => c && !isCharacterRetired(c) && isCharacterUnlocked(c));
            }

            /** Fury puts the call out once the player has taken 25 damage — the same
             *  threshold the clone commanders and the Kamino Sprite use, so "you are
             *  hurt and help arrives" reads as one idea across all three. One attempt
             *  per round either way: a failed call is spent, not retried. */
            function updateFurySpriteBackup() {
                if (!mainPlayer || !mainPlayer.isAlive) return;
                if (!isSpriteEquipped('furySprite')) return;
                if (mainPlayer.calledFurySprite) return;
                if (mainPlayer.health > mainPlayer.maxHealth - 25) return;

                mainPlayer.calledFurySprite = true;

                const color = spriteRarity(getSprite('furySprite')).color;
                const title = '🕶️ FURY SPRITE';

                // Pool first, roll second — the same ordering fix the Kamino Sprite
                // needed. Rolling first would spend the attempt on a round where
                // there was nobody to send anyway.
                const pool = avengerBackupPool(mainPlayer);
                if (!pool.length) {
                    showAnnouncement('Fury has nobody left to call.', color, 4000, title, 90, true);
                    return;
                }

                // Fury carrying his own sprite never rolls — see FURY_SPRITE_OWNER_ID.
                // Written as a short-circuit rather than as `chance = isFury ? 1 : 0.6`
                // so that the guaranteed path is visibly a different path, and so no
                // future edit to the odds can accidentally reintroduce a roll he is
                // not supposed to be making.
                const isFury = mainPlayer.characterId === FURY_SPRITE_OWNER_ID;
                if (!isFury && Math.random() >= FURY_SPRITE_CHANCE) {
                    showAnnouncement('Fury puts the call out. Nobody is close enough to answer it.',
                        color, 4000, title, 90, true);
                    return;
                }

                const data = pool[Math.floor(Math.random() * pool.length)];
                spawnBackupAlly(data, isFury
                    ? `${data.name} answers Fury directly. Nobody was going to say no.`
                    : `${data.name} answers the call and drops in beside you.`,
                    color, title);
            }

            /** Runs the Shapeless transformation for whoever is carrying the sprite.
             *
             *  This used to be called from the event tick, for mainEnemy only. Two
             *  consequences, both silent: the player never transformed anywhere, and
             *  nobody transformed outside the event at all. The sprite's own
             *  description says it turns YOU into the Shapeless Man when badly hurt,
             *  so the only fighter it actually worked for was Geno.
             *
             *  Driven from update() now, so it applies to both principals in every
             *  match, which is what carrying the sprite is supposed to mean.
             */
            function updateShapelessTransform() {
                if (mainPlayer) checkShapelessTransform(mainPlayer);
                if (mainEnemy) checkShapelessTransform(mainEnemy);
                /*  Stane's and Blonsky's suit-up, for the side that has no button to
                 *  press. Ridden along here rather than given its own updater because
                 *  it is the same question asked once a frame — "has this fighter hit
                 *  the health where it becomes something else" — and the Shapeless
                 *  transform is already the place that asks it.
                 *
                 *  checkIronMongerAI() was written and then called from nowhere, which
                 *  is the third time this codebase has produced that exact bug (the
                 *  Zero Event cast's tacticalProfile, then the principals' copy of it).
                 *  An AI Stane stayed a man with a stun gun for the whole round. */
                if (mainEnemy) checkIronMongerAI(mainEnemy);
                // Deadpool's swap, for the side with no key to press. See
                // WEAPON_SWAP_IDS.
                if (mainEnemy) updateWeaponSwapAI(mainEnemy);
                // The Halloween commanders' skeletons, for the same side. See
                // HALLOWEEN_SUMMONS.
                if (mainEnemy) updateHalloweenSummonAI(mainEnemy);
            }


            function setupGame(playerCharacterId, enemyCharacterId, matchOpts = {}) {
                let actualEnemyId = enemyCharacterId;

                // Always close the pause menu and reset pause state when a new game begins
                gamePaused = false;
                pauseOverlay.classList.remove('active');
                // A pause can end without closePauseMenu() (Quit Battle from the
                // menu), and a clock left frozen would stop every timer in the next
                // fight. Then stamp frameNow fresh: the countdown draws the fighters
                // before the loop's first frame, and anything they set from frameNow
                // must not be measured from the last frame of the previous round.
                resumeBattleClock();
                frameNow = gameNow();

                // Every round starts from a clean input slate. Whatever was held
                // when the last one ended — and whatever keyup went missing while
                // the results overlay was up — must not carry into this match.
                // This is the choke point every route into a battle passes
                // through (first fight, Next Round, Rematch), so it is the one
                // place that can make that guarantee.
                resetKeyboardInput();
                resetTouchInput();

                // Defer announcements during battle. The held queue is not
                // emptied here: endGame releases it at the end of every round,
                // and emptying it here is what used to throw away everything
                // earned before Next Round. Rewards still waiting to be shown
                // keep playing into the countdown.
                deferAnnouncements = true;

                resetJabbaEventState();

                if (playerCharacterId === 'babu' && Math.random() <= 0.15) {
                    actualEnemyId = 'sith_c3po';
                    showAnnouncement("A dark protocol presence approaches... Sith C-3PO has intercepted your transmission! Duel him!", "#ffd700", 5000, "⚠️ INTERCEPTED", 50, true);
                }

                // Captured before the flag is cleared below, because the coach-card
                // gate at the tail of this function needs it: a "Next Round" is the
                // same fight continuing and must not raise the card.
                const startedFromNextRound = isNextRound;

                // Reset series on a fresh matchup; preserve on "Next Round"
                if (!isNextRound) {
                    // A sprite the opponent grabbed is theirs for the series and no
                    // longer. This is the line that ends it — a new matchup starts
                    // them empty-handed, while "Next Round" carries the grant over.
                    enemySpriteGrants = {};
                    playerWins = 0;
                    enemyWins = 0;
                }
                // Every round gets the full clock, Next Round included — see the
                // note on seriesTimeRemaining for why it is not per series any more.
                seriesTimeRemaining = SERIES_SECONDS;
                isNextRound = false;
                seriesPlayerCharId = playerCharacterId;
                seriesEnemyCharId = actualEnemyId;

                // Re-measure before anything is positioned. currentArena is already
                // settled by the caller (the arena buttons), and an arena carrying
                // its own worldScale changes the world
                // dimensions — which the spawn points immediately below, and the
                // cover and hazard placement further down, are all expressed in.
                // Measuring after any of that would strand the fighters in one
                // quadrant of an oversized map.
                resizeCanvas();

                const all = [...characters.heroes, ...characters.villains, ...characters.secret, ...characters.unplayable];
                pCharData = all.find(c => c.id === playerCharacterId);
                eCharData = all.find(c => c.id === actualEnemyId);

                // Use button-selected difficulty settings
                const ds = diffSettings[currentDifficulty];
                const eHp = Math.round(effectiveCharHp(eCharData) * ds.hpMult);

                // A forged weapon replaces the character's issued one. Its damage
                // is baked into the compiled config, so pCharData.weaponDamage —
                // which getWeapon() applies as an override — has to be withheld,
                // or the character's per-character tuning would overwrite what
                // the armorer actually made.
                const pWeaponKey = getEquippedWeaponKey(pCharData.id, pCharData.weapon);
                const pWeaponDamage = pWeaponKey === pCharData.weapon ? pCharData.weaponDamage : undefined;
                mainPlayer = new Character(canvasLogicalW / 4, canvasLogicalH / 2, pCharData.color, pCharData.arenaName || pCharData.name, effectiveCharHp(pCharData), pWeaponKey, pCharData.saberColor, pCharData.isDroid, pCharData.isWookiee, 'player', true, pCharData.isClone, pWeaponDamage, pCharData.id);
                mainEnemy = new Character(canvasLogicalW * 3 / 4, canvasLogicalH / 2, eCharData.color, eCharData.arenaName || eCharData.name, eHp, eCharData.weapon, eCharData.saberColor, eCharData.isDroid, eCharData.isWookiee, 'enemy', true, eCharData.isClone, eCharData.weaponDamage, eCharData.id);
                /*  A roster entry's `tacticalProfile` was being honoured for spawned
                 *  allies and for the Shapeless form and for nobody else — so the two
                 *  fighters it matters most for, the ones actually duelling, fell
                 *  through to the weapon-derived default every time.
                 *
                 *  That is the same bug the Zero Event cast already hit once ("written
                 *  thirteen times and read nowhere"), fixed there by copying the field
                 *  onto the ally in spawnAllyFighter and not here. Thor and The Thing
                 *  were not brawlers, Loki was not a duelist, Fury was not calculated:
                 *  all five were `disciplined`, because that is where a weapon the
                 *  profile table does not name ends up.
                 *
                 *  Note this is only reached through the roster field. Profiles set by
                 *  id in TACTICAL_ID_OVERRIDES were always working — getTacticalProfile
                 *  looks those up off `characterId`, which the constructor does take. */
                mainPlayer.tacticalProfileOverride = pCharData.tacticalProfile || null;
                mainEnemy.tacticalProfileOverride = eCharData.tacticalProfile || null;

                if (eCharData.id === 'carbonite_han') {
                    mainEnemy.isFrozen = true;
                    mainEnemy.color = '#888888';
                    mainEnemy.weaponConfig = getWeapon({ weapon: 'blaster', weaponDamage: eCharData.weaponDamage });
                }
                
                // Re-attach whatever the opponent won earlier in this series. The
                // Character objects are rebuilt every round, so the grant has to be
                // copied back onto the new one or it would silently expire after a
                // single round instead of lasting the series.
                mainEnemy.spriteGrants = Object.assign({}, enemySpriteGrants);

                entities = [mainPlayer, mainEnemy];

                // Carried health, for a match that is a continuation of one already
                // in progress rather than a new one — the Unstable Zero Point
                // throwing the player into a different arena is still the same fight
                // as far as their health bar is concerned.
                if (matchOpts.carryHp != null && mainPlayer) {
                    mainPlayer.health = Math.max(1, Math.min(mainPlayer.maxHealth, matchOpts.carryHp));
                }

                bullets = [];
                pickups = [];
                pickupSpawnTimer = 0;
                clashParticles = [];
                hitSparks = [];
                impactParticles = [];
                boomBlasts = [];
                saberTrails = [];
                dodgeFlashes = [];
                meleeSwings = [];
                screenShake = { intensity: 0, duration: 0 };
                slowMotion = { active: false, scale: 1, duration: 0 };
                killCamera = { active: false, target: null, zoom: 1, duration: 0 };
                comboKills = [];
                
                const comboEl = document.getElementById('comboCounter');
                if (comboEl) comboEl.classList.remove('active');
                clearTimeout(window.comboTimeout);

                playBattleMusic();

                // New battle session — invalidates any leftover countdown / hum from a prior match
                if (countdownTimerId != null) { clearTimeout(countdownTimerId); countdownTimerId = null; }
                if (saberHumTimerId != null) { clearTimeout(saberHumTimerId); saberHumTimerId = null; }
                if (gameLoopId) { cancelAnimationFrame(gameLoopId); gameLoopId = 0; }
                battleSession++;
                const thisBattleSession = battleSession;

                // ── SFX: lightsaber ignition on match start ────────────
                // Jedi and Sith blades have distinct snap-hisses, so a duel
                // between them ignites both. The hum that follows is whichever
                // blade the player is holding — you hear your own weapon.
                // The Electrostaff counts as a blade here: it now has its own ignite
                // and its own looping hum, so it takes the same match-start treatment
                // — ignite on the countdown, hum 900ms later.
                const saberWeaponKeys = ['lightsaber', 'darksaber', 'staff'];
                // Read off the built entities, not the roster entries: the player
                // may be carrying a forged blade rather than their issued one, and
                // Character normalises its `weapon` to the base pattern.
                const playerHasSaber = saberWeaponKeys.includes(mainPlayer.weapon);
                const enemyHasSaber  = saberWeaponKeys.includes(mainEnemy.weapon);
                if (playerHasSaber || enemyHasSaber) {
                    // A Set, so a Jedi-vs-Jedi (or Sith-vs-Sith) match doesn't
                    // fire the same ignite sample twice on the same frame.
                    const igniteKeys = new Set();
                    if (playerHasSaber) igniteKeys.add(saberSfx(mainPlayer, 'lightsaberIgnite'));
                    if (enemyHasSaber)  igniteKeys.add(saberSfx(mainEnemy,  'lightsaberIgnite'));
                    igniteKeys.forEach(key => playSound(key));

                    const humKey = saberSfx(playerHasSaber ? mainPlayer : mainEnemy, 'lightsaberHum');
                    saberHumTimerId = setTimeout(() => {
                        saberHumTimerId = null;
                        // Don't start the looping hum if this match was already left
                        if (thisBattleSession !== battleSession) return;
                        if (canvas.style.display !== 'block') return;
                        // Remember the blade so a pause can restore it on resume.
                        activeSaberHumKey = humKey;
                        // This timer keeps running while paused; starting the hum
                        // underneath the pause menu would be audible. Resuming
                        // starts it instead.
                        if (gamePaused) return;
                        playSound(humKey);
                    }, 900);
                }
                mainMenu.style.display = 'none';
                // Hide developer and settings UI during battles
                const devMenuToggleEl = document.getElementById('devMenuToggle');
                const devMenuPanelEl = document.getElementById('devMenuPanel');
                const settingsBtnEl = document.getElementById('settingsBtn');
                const settingsPanelEl = document.getElementById('settingsPanel');
                const fullscreenBtnEl = document.getElementById('fullscreenBtn');
                if (devMenuToggleEl) { devMenuToggleEl.classList.remove('is-visible'); devMenuToggleEl.style.display = 'none'; }
                if (devMenuPanelEl) devMenuPanelEl.style.display = 'none';
                if (settingsBtnEl) settingsBtnEl.style.display = 'none';
                if (settingsPanelEl) settingsPanelEl.style.display = 'none';
                if (fullscreenBtnEl) fullscreenBtnEl.style.display = 'none';
                canvas.style.display = 'block';
                resizeCanvas();
                hud.style.display = 'flex';
                messageOverlay.style.display = 'none';
                updateMobileControlsVisibility();

                // Portrait cards
                const playerPortrait = document.getElementById('playerPortrait');
                playerPortrait.textContent = weaponEmojiFor(pWeaponKey);
                playerPortrait.style.color = mainPlayer.color;
                playerPortrait.style.borderColor = mainPlayer.color;
                playerPortrait.style.boxShadow = `0 0 10px ${mainPlayer.color}55`;

                playerLabel.textContent = mainPlayer.name;
                playerLabel.style.color = mainPlayer.color;
                playerHealthBar.style.backgroundColor = mainPlayer.color;
                const playerWeaponLabel = document.getElementById('playerWeaponLabel');
                if (playerWeaponLabel) playerWeaponLabel.textContent = weaponLabelFor(pCharData);

                setEnemyHud(eCharData, mainEnemy);

                updateRoundPips();
                killCount = 0;
                playerDamageDealt = 0;
                matchSpecialsUsed = 0;
                playerShotsFired = 0;
                playerHitsLanded = 0;
                deathParticles = [];
                floatNums = [];
                playerTookDamage = false;
                resetChargeShot();
                // A borrowed floor lasts exactly one match. Carrying it into the next
                // one would leave the Zero Point wearing Hoth's snow with no
                // explanation for how it got there.
                zeroPointTerrain = null;
                spawnCover();
                spawnHazards();

                // ── 3-2-1 COUNTDOWN ──────────────────────────────────
                // Freeze the HUD timer until after the countdown
                countdownActive = true;
                const hudTimer = document.getElementById('hudTimer');
                if (hudTimer) {
                    hudTimer.style.display = 'none';
                    hudTimer.classList.remove('sudden-death');
                }
                let countdownStep = 0; // 0=3, 1=2, 2=1, 3=GO! → then start
                const countdownDurations = [700, 700, 700, 600]; // ms per step

                function drawCountdownFrame(label, subLabel) {
                    const w = canvasLogicalW, h = canvasLogicalH;
                    // Draw the arena background first so it isn't black
                    draw(0);
                    // Dim overlay
                    ctx.save();
                    ctx.fillStyle = 'rgba(0,0,0,0.55)';
                    ctx.fillRect(0, 0, w, h);

                    // Number or GO!
                    const isGo = label === 'GO!';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    ctx.font = `bold ${Math.round(h * (isGo ? 0.22 : 0.26))}px ${getCanvasFontFamily()}, sans-serif`;
                    const numColor = isGo ? '#00ff88' : '#ffffff';
                    ctx.fillStyle = numColor;
                    ctx.shadowColor = numColor;
                    ctx.shadowBlur = 50;
                    ctx.fillText(label, w * 0.5, h * 0.5);
                    ctx.restore();
                }

                function countdownTick() {
                    // Player left the fight (quit / return to base) — do not start timer or loop
                    if (thisBattleSession !== battleSession) return;
                    if (canvas.style.display !== 'block') return;

                    const labels = ['3', '2', '1', 'GO!'];
                    drawCountdownFrame(labels[countdownStep]);
                    const delay = countdownDurations[countdownStep];
                    countdownStep++;
                    if (countdownStep < labels.length) {
                        countdownTimerId = setTimeout(countdownTick, delay);
                    } else {
                        // Countdown done — start the real game
                        countdownTimerId = null;
                        if (thisBattleSession !== battleSession) return;
                        if (canvas.style.display !== 'block') return;
                        countdownActive = false;
                        gameStartTime = gameNow();
                        frameNow = gameStartTime;
                        // The countdown draws Thanos's charge arc, and that first ask
                        // is what sets the Snap's ready time (infinitySnapReadyAt is
                        // lazy). Clearing it here starts the 25 seconds at GO, which is
                        // what "the Snap starts empty every round" promises. It used to
                        // be measured from a stale frameNow and could open the round
                        // already charged.
                        for (const ent of entities) if (ent) ent.infinitySnapReadyAt = null;
                        startTimer();
                        lastGameFrameTime = 0;
                        gameLoopId = requestAnimationFrame(gameLoop);

                        // Shots used to home in on the nearest enemy on their own.
                        // Anyone who played the old build needs telling once that
                        // they are now doing the aiming, and where the switch is to
                        // hand it back. Not shown on touch, which still auto-aims.
                        if (!seenAimHint && !autoAimEnabled && !isCoarsePointer()) {
                            seenAimHint = true;
                            saveGameSettings();
                            showAnnouncement(
                                'You now aim your own shots — point with the mouse or the right stick. Prefer the old behaviour? Turn on Auto-Aim in ⚙️ Settings.',
                                // Shown during the countdown, so it is already inside
                                // the deferral window: instructions for the fight the
                                // player is about to start are worthless afterwards.
                                '#ffd700', 6000, '🎯 NEW: MANUAL AIM', 60, true
                            );
                        }
                    }
                }
                const beginCountdown = () => {
                    countdownTimerId = setTimeout(countdownTick, 50); // slight delay so canvas is rendered
                };

                // A cold save gets one card, in front of one fight — the controls it
                // needs and what a series is. Not on the menu, where it reads as a
                // wall, and not on a "Next Round", which is the same fight
                // continuing. It goes up before the countdown rather than inside it
                // (where the aim hint correctly sits): the aim hint is a banner you
                // can play past, this is a card you have to answer.
                if (!seenFirstFightCard && !startedFromNextRound) {
                    seenFirstFightCard = true;
                    saveGameSettings();
                    // Deferred by the same 50ms for the same reason the countdown is:
                    // the canvas has to be laid out before anything can be drawn into
                    // it. One arena frame goes down first so the card sits over the
                    // fight it is describing, not a black rectangle.
                    setTimeout(() => {
                        if (thisBattleSession !== battleSession) return;
                        if (canvas.style.display !== 'block') return;
                        draw(0);
                        openControlsOverlay({ coach: true, onDismiss: beginCountdown });
                    }, 50);
                } else {
                    beginCountdown();
                }
            }

            function fireProjectile(shooter, target, weaponConfig) {
                let angle = Math.atan2(target.y - shooter.y, target.x - shooter.x);
                // Blasters/bowcasters have natural spread; snipers are nearly
                // pin-accurate (the pack’s Boom Sniper has first-shot accuracy, so it
                // is at least as tight as the base rifle)
                if (weaponConfig.key === 'blaster' || weaponConfig.key === 'bowcaster') {
                    angle += (Math.random() - 0.5) * 0.14;
                } else if (weaponConfig.key === 'sniper' || weaponConfig.key === 'boomsniper') {
                    angle += (Math.random() - 0.5) * 0.02;
                }
                const dx = Math.cos(angle) * weaponConfig.speed;
                const dy = Math.sin(angle) * weaponConfig.speed;
                const projectile = new Projectile(shooter.x, shooter.y, dx, dy, weaponConfig, shooter);
                if (shooter.team === 'player') playerShotsFired++;
                if (weaponConfig.returnable) {
                    projectile.returnable = true;
                    projectile.returning = false;
                    projectile.travelled = 0;
                    projectile.maxDistance = Math.max(220, weaponConfig.length * 6);
                    projectile.returnSpeed = weaponConfig.speed * 1.1;
                }
                if (bullets.length < MAX_BULLETS) bullets.push(projectile);
                if (weaponConfig.magSize != null && shooter.magAmmo != null) {
                    shooter.magAmmo = Math.max(0, shooter.magAmmo - 1);
                }

                // ── SFX: fire sounds for all shooters ─────────────────
                playWeaponFireSfx(weaponConfig);
            }

            function fireSpreadProjectiles(shooter, target, weaponConfig, bulletCount = 5, spreadAngle = 0.5) {
                const baseAngle = Math.atan2(target.y - shooter.y, target.x - shooter.x);
                const step = spreadAngle / (bulletCount - 1);
                const startAngle = baseAngle - spreadAngle / 2;
                for (let i = 0; i < bulletCount; i++) {
                    const angle = startAngle + step * i;
                    const dx = Math.cos(angle) * weaponConfig.speed;
                    const dy = Math.sin(angle) * weaponConfig.speed;
                    const projectile = new Projectile(shooter.x, shooter.y, dx, dy, weaponConfig, shooter);
                    if (shooter.team === 'player') playerShotsFired++;
                    if (bullets.length < MAX_BULLETS) bullets.push(projectile);
                }
                // One trigger pull costs one round, however many projectiles left the
                // barrel — a shotgun shell is nine pellets, not nine shells, and the
                // spread powerup is a bonus rather than a 5× ammo tax. This is also
                // what the AI firing path has always done; the two used to disagree.
                if (weaponConfig.magSize != null && shooter.magAmmo != null) {
                    shooter.magAmmo = Math.max(0, shooter.magAmmo - 1);
                }
                playWeaponFireSfx(weaponConfig);
            }

            // Called for every entity every frame (targeting, and again for each shot),
            // so it allocates nothing: no filtered array, no reduce closure. Compares
            // squared distances to skip a sqrt per candidate — ordering is identical.
            function getClosestEnemy(entity) {
                let closest = null;
                let bestDistSq = Infinity;
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (!e.isAlive || e.team === entity.team) continue;
                    const dx = e.x - entity.x;
                    const dy = e.y - entity.y;
                    const distSq = dx * dx + dy * dy;
                    if (distSq < bestDistSq) {
                        bestDistSq = distSq;
                        closest = e;
                    }
                }
                return closest;
            }

            // ── MELEE SWINGS ───────────────────────────────────────────
            // Melee weapons used to be thrown projectiles and nothing else — the
            // glowing blade drawn on the character had no hitbox, so a "duel" was
            // two fighters lobbing their sabers at each other from across the
            // arena. Now the blade actually cuts:
            //
            //   fire (Space / LMB / A)  → swing an arc in front of you, hitting
            //                             everything inside it
            //   throw (Q / RMB / LT)    → the old thrown blade, now on a cooldown
            //                             AND disarming: while it is in flight you
            //                             cannot swing, because you are holding
            //                             nothing. That is what stops the throw
            //                             from being strictly better than swinging.
            //
            // A swing is COMMITTED, not instantaneous. It used to resolve on the
            // same frame the button went down, which meant melee had no rhythm to
            // it: there was no moment at which an attack could be read, baited or
            // punished, so a duel came down to whoever had more HP and a shorter
            // cooldown. Now a swing runs windup → cut → recovery, the direction is
            // locked at the moment of commit, and movement is slowed throughout.
            // Swinging at where someone *was* is a real mistake you can make.
            //
            // The windup is also when the blade is up, which is what makes the
            // deflect in tryDeflect() a timed act rather than a passive aura.
            const MELEE_SWING_ARC = 1.7;          // ~97° sweep
            const MELEE_SWING_MIN_COOLDOWN = 150; // floor, so the ammo pickup can't make swings free
            const MELEE_THROW_COOLDOWN = 1400;
            const MAX_MELEE_SWINGS = 24;
            // Windup is deliberately short. This is a twin-stick brawler, not a
            // souls-like — long enough to read and to punish, short enough that
            // melee still feels responsive under the hand.
            const MELEE_WINDUP_MS = 110;
            const MELEE_RECOVER_MS = 150;
            // How long the blade stays up past the cut, guarding. Covers the whole
            // windup plus this, so one swing is ~200ms of deflection out of a
            // ~500ms saber cycle.
            const MELEE_GUARD_TAIL_MS = 90;
            // Movement multiplier while committed to a swing. Not a full root —
            // being unable to move at all in a game with this much incoming fire
            // reads as a bug rather than as commitment.
            const MELEE_COMMIT_SLOW = 0.4;
            let meleeSwings = [];

            /** True while this entity is committed to a swing — winding up, or in
             *  the recovery after it. Movement is slowed and no new attack, throw
             *  or swing may start. */
            function isCommittedToSwing(e, now) {
                return now < (e.swingRecoverUntil || 0);
            }

            /** Movement scalar for an entity mid-swing. 1 when free.
             *
             *  Clobberin' is the one exemption. At the rate that window punches,
             *  the commitment is almost never off, so charging the usual slow for
             *  it would root The Thing in place for the whole two seconds — the
             *  ability would read as a penalty. "No slow on punch" is half of what
             *  the window is. See the CLOBBERIN' block. */
            function swingMoveScale(e, now) {
                if (isClobberin(e)) return 1;
                return isCommittedToSwing(e, now) ? MELEE_COMMIT_SLOW : 1;
            }

            /** How long after a swing before the next one may start.
             *
             *  One function because both the player branch and the AI branch need
             *  the answer and used to spell it out separately — the same drift the
             *  fire-sound chain and BLUNT_WEAPON_KEYS are one list for.
             *
             *  The floor is what stops the ammo pickup making swings free; during
             *  Clobberin' the weapon's own cooldown is simply not charged, which
             *  is what "punches super fast" is. The swing commitment still applies
             *  on top of whatever comes back from here, so the real ceiling is
             *  MELEE_WINDUP_MS + MELEE_RECOVER_MS. */
            function meleeSwingCooldown(e, effectiveCooldown) {
                if (isClobberin(e)) return Math.max(MELEE_SWING_MIN_COOLDOWN, Math.min(effectiveCooldown, CLOBBERIN_SWING_COOLDOWN));
                return Math.max(MELEE_SWING_MIN_COOLDOWN, effectiveCooldown);
            }

            /** Drop a committed swing on the floor. Called when the swinger is
             *  stunned, choked, knocked down or killed before the cut lands —
             *  otherwise the blow would still arrive out of a body that is
             *  currently being electrocuted. */
            function cancelMeleeSwing(e) {
                e.pendingSwingAt = 0;
                e.swingRecoverUntil = 0;
                e.guardUntil = 0;
            }

            /** How a melee weapon's strike should READ on screen.
             *
             *  Taken from the sprite kit's pose family rather than from a new
             *  field on every weapon, because the kit already knows which weapons
             *  are fists and which are claws — it has to, it draws them. One
             *  list, in one file, and a new melee weapon gets the right strike by
             *  joining the family it had to join anyway to be drawn at all.
             *
             *  'punch' — a straight thrust. Fists do not sweep.
             *  'rake'  — separate claw lines through the arc, not one solid edge.
             *  'sweep' — the blade arc everything else has always used.
             *
             *  Only the drawing changes. The hitbox stays the same cone for all
             *  three: narrowing the punch to match the line it now draws would be
             *  a balance change wearing an animation's clothes, and Hulk and The
             *  Thing would both quietly lose reach to either side. Both strikes
             *  show the covered arc some other way instead — see the shockwave in
             *  drawPunchStrike().                                                */
            function meleeStyleOf(entity) {
                const fam = SpriteKit.familyOf(entity.weapon, entity.weaponConfig);
                if (fam === 'fists') return 'punch';
                if (fam === 'claws') return 'rake';
                return 'sweep';
            }

            // Distance from the character's centre that a swing can reach. Built
            // from the weapon's own reach so it always matches the blade drawn on
            // screen — what you see is what connects.
            function getSwingReach(e) {
                return bodyRadius(e) + ((e.weaponConfig && e.weaponConfig.reach) || 30) * bodyScale(e);
            }

            /*  How big a fighter is, as a multiple of the standard body. 1 for
             *  everyone except Ant-Man in either form and his ants, which is why
             *  it is a field nobody else sets rather than a roster stat.
             *
             *  Read at the three places size has to mean something: a bolt
             *  hitting a body, a swing reaching one, and the sprite. Everything
             *  else that uses CHARACTER_SIZE (cover, walls, where the name plate
             *  sits) stays on the standard body. A giant clipping a pillar's
             *  edge is cosmetic; a giant a bolt passes through is not.         */
            function bodyScale(e) { return (e && e.sizeMult) || 1; }
            function bodyRadius(e) { return CHARACTER_SIZE * bodyScale(e); }

            // True while a returnable blade thrown by this entity is still out.
            // Scanned rather than tracked with a flag because a blade can leave the
            // bullet list through several paths (collected, blocked, owner died,
            // absorbed by cover) and a missed reset would disarm someone forever.
            function hasBladeInFlight(e) {
                for (let i = 0; i < bullets.length; i++) {
                    const b = bullets[i];
                    if (b.returnable && b.owner === e && !b.collected && !b.blocked) return true;
                }
                return false;
            }

            /** Commit to a swing in the direction of `aimTarget`.
             *
             *  The angle is captured HERE, at commit time, and never recomputed —
             *  that is the whole point of the change. The cut lands
             *  MELEE_WINDUP_MS later wherever the blade was already going, so a
             *  target that reads the windup and steps out of the arc does not get
             *  followed. Swinging early, or at a feint, costs you the recovery.
             *
             *  The swing sound also moves here, to the moment the blade starts
             *  moving, rather than to the moment it connects. */
            function beginMeleeSwing(attacker, aimTarget) {
                const cfg = attacker.weaponConfig;
                const angle = Math.atan2(aimTarget.y - attacker.y, aimTarget.x - attacker.x);

                attacker.pendingSwingAngle = angle;
                attacker.pendingSwingAt = frameNow + MELEE_WINDUP_MS;
                attacker.swingRecoverUntil = frameNow + MELEE_WINDUP_MS + MELEE_RECOVER_MS;

                // The blade is up from the instant the swing starts, so the guard
                // window opens on the windup — not on the cut. Deflecting is
                // something you do by starting a swing *before* the bolt arrives.
                if (cfg.deflects) {
                    attacker.guardAngle = angle;
                    attacker.guardUntil = frameNow + MELEE_WINDUP_MS + MELEE_GUARD_TAIL_MS;
                }

                // Sabers hum through the air, so they get a swing sample whether or
                // not they connect, and a hit layers swing-then-clash on top.
                //
                // Blunt weapons make no sound at all until they land. A wrench
                // swung through empty air is silent — the clang belongs to the
                // impact, and playing it on every whiff turned a miss into a hit to
                // the ear. Their noise is in applyStatusAndDamage() instead.
                if (!isBluntWeapon(cfg.key)) {
                    playSound(saberSfx(attacker, 'lightsaberSwing'), 80);
                }
            }

            /** Resolve a committed swing: sweep the arc and damage every enemy
             *  inside it. Damage is routed through applyStatusAndDamage with a
             *  projectile-shaped object so a swing gets the same knockback, status
             *  effects (zap stun, wrench knockdown), droid multipliers, sparks and
             *  damage numbers as a hit from the thrown version — no second copy of
             *  the damage rules. */
            function resolveMeleeSwing(attacker) {
                const cfg = attacker.weaponConfig;
                const angle = attacker.pendingSwingAngle;
                attacker.pendingSwingAt = 0;
                const reach = getSwingReach(attacker);
                // The spread pickup widens the sweep rather than throwing five
                // blades at once, which is what it used to do to melee users.
                const arc = frameNow < attacker.spreadUntil ? MELEE_SWING_ARC * 1.6 : MELEE_SWING_ARC;
                const half = arc / 2;

                const hit = {
                    damage: cfg.damage,
                    variance: cfg.variance || 0,
                    type: cfg.key,
                    color: cfg.color,
                    weaponConfig: cfg,
                    owner: attacker,
                    isSwing: true
                };

                let connected = false;
                for (let i = 0; i < entities.length; i++) {
                    const t = entities[i];
                    if (!t.isAlive || t.team === attacker.team) continue;
                    const dx = t.x - attacker.x;
                    const dy = t.y - attacker.y;
                    if (Math.hypot(dx, dy) > reach + bodyRadius(t)) continue;
                    // Signed angle to the target, wrapped into [-π, π] so a swing
                    // pointing near due west doesn't fail the comparison.
                    const delta = Math.atan2(Math.sin(Math.atan2(dy, dx) - angle),
                                             Math.cos(Math.atan2(dy, dx) - angle));
                    if (Math.abs(delta) > half) continue;
                    applyStatusAndDamage(t, hit);
                    connected = true;
                }

                // Accuracy counts a swing as one attack that either landed or did
                // not — otherwise cleaving three troopers at once would push the
                // end-of-round accuracy above 100%.
                if (attacker.team === 'player') {
                    playerShotsFired++;
                    if (connected) playerHitsLanded++;
                }

                if (meleeSwings.length < MAX_MELEE_SWINGS) {
                    meleeSwings.push({
                        owner: attacker, angle, arc, reach,
                        life: 10, maxLife: 10,
                        // Snapshotted with the rest of the swing rather than read
                        // off the owner while it draws, for the same reason angle
                        // and reach are: the effect outlives the frame that made
                        // it, and it should keep describing the blow it came from.
                        style: meleeStyleOf(attacker),
                        color: cfg.key === 'staff' ? cfg.color : (attacker.saberColor || attacker.color)
                    });
                }

                if (connected) triggerScreenShake(3, 6);
            }

            /** Land any swing whose windup has elapsed. Runs once per frame for
             *  every live entity, ahead of the per-entity action logic, so a
             *  committed cut resolves on time no matter what its owner is doing
             *  now — including standing still in recovery.
             *
             *  The interrupt check lives here rather than being left to the
             *  canAct gate in the action loop. Status effects are applied during
             *  the bullet phase, which runs after that gate, so a zap landing on
             *  frame N is not seen by the gate until frame N+1 — by which point
             *  this function would already have let the swing through. Asking
             *  directly is a frame tighter and does not depend on call order. */
            function resolvePendingSwings(aliveEntities) {
                for (let i = 0; i < aliveEntities.length; i++) {
                    const e = aliveEntities[i];
                    if (!e.pendingSwingAt) continue;
                    if (frameNow <= e.stunnedUntil || frameNow <= e.knockedOutUntil || frameNow < e.chokedUntil) {
                        cancelMeleeSwing(e);
                        continue;
                    }
                    if (frameNow >= e.pendingSwingAt) resolveMeleeSwing(e);
                }
            }

            function updateMeleeSwings(tickScale) {
                meleeSwings = meleeSwings.filter(s => {
                    s.life -= tickScale;
                    return s.life > 0;
                });
            }

            // The sweep is drawn as a widening wedge that fades out, anchored to
            // the swinger so it tracks them if the hit knocks them around.
            /** A punch is a line, not an arc: the fist goes out, lands, comes
             *  back, and the only wide thing about it is the shockwave.
             *
             *  That shockwave is doing a job beyond decoration. The hitbox is
             *  still the same cone every melee weapon cuts (see meleeStyleOf), so
             *  the covered arc has to stay legible somehow — and a ring spreading
             *  from a landed blow says "this far, and this far to either side"
             *  without reading as a blade sweep. */
            function drawPunchStrike(s, ox, oy, t, progress) {
                const ca = Math.cos(s.angle), sa = Math.sin(s.angle);
                // Out fast, back slower — peak extension a third of the way in.
                const ext = progress < 0.34
                    ? progress / 0.34
                    : Math.max(0, 1 - (progress - 0.34) / 0.66);
                const near = CHARACTER_SIZE;
                const fist = near + (s.reach - near) * ext;
                const fx = ox + ca * fist, fy = oy + sa * fist;

                ctx.save();
                ctx.lineCap = 'round';
                if (effectsEnabled()) {
                    ctx.shadowBlur = 16;
                    ctx.shadowColor = s.color;
                }

                // The arm behind the fist
                ctx.globalAlpha = 0.5 * t;
                ctx.strokeStyle = s.color;
                ctx.lineWidth = 9;
                ctx.beginPath();
                ctx.moveTo(ox + ca * near, oy + sa * near);
                ctx.lineTo(fx, fy);
                ctx.stroke();

                // The knuckles, with a hot core so the contact point is obvious
                ctx.globalAlpha = 0.85 * t;
                ctx.fillStyle = s.color;
                ctx.beginPath();
                ctx.arc(fx, fy, 7.5, 0, Math.PI * 2);
                ctx.fill();
                ctx.globalAlpha = 0.9 * t;
                ctx.fillStyle = '#ffffff';
                ctx.beginPath();
                ctx.arc(fx, fy, 3.2, 0, Math.PI * 2);
                ctx.fill();

                // The shockwave — how far the blow reached, and how wide
                ctx.globalAlpha = 0.3 * t;
                ctx.strokeStyle = s.color;
                ctx.lineWidth = 2 + 2 * ext;
                ctx.beginPath();
                ctx.arc(ox, oy, s.reach * (0.72 + 0.28 * ext), s.angle - s.arc / 2, s.angle + s.arc / 2);
                ctx.stroke();
                ctx.restore();
            }

            /** Claws rake. Four separate lines sweeping the same arc a blade
             *  would, because the gap between them is the entire read — a solid
             *  wedge with one bright edge is a sword cut whatever colour it is. */
            function drawClawRake(s, ox, oy, t, progress) {
                const half = s.arc / 2;
                const edge = -half + s.arc * Math.min(1, progress * 1.35);
                const CLAWS = 4;
                ctx.save();
                ctx.lineCap = 'round';
                if (effectsEnabled()) {
                    ctx.shadowBlur = 14;
                    ctx.shadowColor = s.color;
                }
                for (let c = 0; c < CLAWS; c++) {
                    // Fanned slightly apart and cut to staggered lengths, so they
                    // read as four separate points rather than one thick line.
                    const spread = (c - (CLAWS - 1) / 2) * 0.085;
                    const from = s.angle - half + spread;
                    const to = s.angle + edge + spread;
                    if (to <= from) continue;
                    const r = s.reach * (0.8 + 0.2 * (c / (CLAWS - 1)));

                    ctx.globalAlpha = 0.55 * t;
                    ctx.strokeStyle = s.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.arc(ox, oy, r, from, to);
                    ctx.stroke();

                    // Bright tip on each claw, the leading end of its own line
                    ctx.globalAlpha = 0.9 * t;
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = 1.6;
                    ctx.beginPath();
                    ctx.arc(ox, oy, r, Math.max(from, to - 0.22), to);
                    ctx.stroke();
                }
                ctx.restore();
            }

            function drawMeleeSwings() {
                if (!meleeSwings.length) return;
                for (let i = 0; i < meleeSwings.length; i++) {
                    const s = meleeSwings[i];
                    const t = Math.max(0, s.life / s.maxLife);
                    const progress = 1 - t;              // 0 → 1 over the swing
                    const ox = s.owner ? s.owner.x : 0;
                    const oy = s.owner ? s.owner.y : 0;
                    if (s.style === 'punch') { drawPunchStrike(s, ox, oy, t, progress); continue; }
                    if (s.style === 'rake')  { drawClawRake(s, ox, oy, t, progress); continue; }
                    const half = s.arc / 2;
                    // The leading edge sweeps from one side of the arc to the other
                    const edge = -half + s.arc * Math.min(1, progress * 1.35);

                    ctx.save();
                    ctx.globalAlpha = 0.5 * t;
                    ctx.fillStyle = s.color;
                    if (effectsEnabled()) {
                        ctx.shadowBlur = 18;
                        ctx.shadowColor = s.color;
                    }
                    ctx.beginPath();
                    ctx.moveTo(ox, oy);
                    ctx.arc(ox, oy, s.reach, s.angle - half, s.angle + edge);
                    ctx.closePath();
                    ctx.fill();

                    // Bright leading edge so the sweep reads as a blade, not a glow
                    ctx.globalAlpha = 0.9 * t;
                    ctx.strokeStyle = '#ffffff';
                    ctx.lineWidth = 2.5;
                    ctx.beginPath();
                    ctx.moveTo(ox + Math.cos(s.angle + edge) * CHARACTER_SIZE,
                               oy + Math.sin(s.angle + edge) * CHARACTER_SIZE);
                    ctx.lineTo(ox + Math.cos(s.angle + edge) * s.reach,
                               oy + Math.sin(s.angle + edge) * s.reach);
                    ctx.stroke();
                    ctx.restore();
                }
            }

            // The windup telegraph. A committed swing has to be READABLE — the
            // punish loop only exists if the other fighter can see the blade come
            // up and step out of the arc. Drawn as a hollow wedge at the locked
            // angle that fills in as the cut approaches, so the timing is legible
            // from the shape alone rather than from a colour the player has to
            // learn. Also drawn for the player's own swing, which is how they
            // learn the commitment is real.
            function drawSwingWindups() {
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (!e.isAlive || !e.pendingSwingAt) continue;
                    const remaining = e.pendingSwingAt - frameNow;
                    if (remaining <= 0) continue;

                    const progress = 1 - Math.max(0, Math.min(1, remaining / MELEE_WINDUP_MS));
                    const cfg = e.weaponConfig;
                    const arc = frameNow < e.spreadUntil ? MELEE_SWING_ARC * 1.6 : MELEE_SWING_ARC;
                    const half = arc / 2;
                    const reach = getSwingReach(e);
                    const angle = e.pendingSwingAngle;
                    const color = cfg.key === 'staff' ? cfg.color : (e.saberColor || e.color);

                    // A cocked fist telegraphs down the line of the punch, not as
                    // a cone — the wedge is what made it read as a wind-up swing.
                    // The faint outer arc still shows the reach that will actually
                    // be covered, for the same reason the shockwave does.
                    if (meleeStyleOf(e) === 'punch') {
                        const near = CHARACTER_SIZE;
                        const tip = near + (reach - near) * progress;
                        ctx.save();
                        ctx.lineCap = 'round';
                        if (effectsEnabled()) {
                            ctx.shadowBlur = 12;
                            ctx.shadowColor = color;
                        }
                        ctx.globalAlpha = 0.22 + 0.45 * progress;
                        ctx.strokeStyle = color;
                        ctx.lineWidth = 3 + 3 * progress;
                        ctx.beginPath();
                        ctx.moveTo(e.x + Math.cos(angle) * near, e.y + Math.sin(angle) * near);
                        ctx.lineTo(e.x + Math.cos(angle) * tip, e.y + Math.sin(angle) * tip);
                        ctx.stroke();

                        ctx.globalAlpha = 0.12 + 0.16 * progress;
                        ctx.lineWidth = 1.5;
                        ctx.beginPath();
                        ctx.arc(e.x, e.y, reach, angle - half, angle + half);
                        ctx.stroke();
                        ctx.restore();
                        continue;
                    }

                    ctx.save();
                    // Outline is faint at commit and firms up as the cut nears
                    ctx.globalAlpha = 0.18 + 0.32 * progress;
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 1.5;
                    if (effectsEnabled()) {
                        ctx.shadowBlur = 10;
                        ctx.shadowColor = color;
                    }
                    ctx.beginPath();
                    ctx.moveTo(e.x, e.y);
                    ctx.arc(e.x, e.y, reach, angle - half, angle + half);
                    ctx.closePath();
                    ctx.stroke();
                    ctx.restore();
                }
            }

            // ── LIGHTSABER DEFLECT ─────────────────────────────────────────
            // The single most recognisable exchange in Star Wars — a blade
            // batting blaster fire out of the air — was missing entirely. The
            // deflect sample was loaded and only ever played on bullet-vs-bullet
            // clashes, and a saber duellist facing a blaster at range had no
            // answer but to close the distance and hope.
            //
            // Deflection is tied to the swing rather than to a held block button:
            // it needs no new input (so it works on touch and gamepad for free),
            // it makes the swing a defensive act as well as an offensive one, and
            // it is timed, so it rewards reading the shooter instead of holding a
            // key. The window is the windup plus MELEE_GUARD_TAIL_MS — see
            // beginMeleeSwing().
            //
            // What is NOT deflectable, and why:
            //   - returnable blades: a thrown saber changes owner on deflect and
            //     would then try to fly home to the wrong person.
            //   - flamethrower / beam: continuous streams, not discrete shots.
            //     You cannot bat away fire.
            // Force lightning IS deflectable, because Yoda does exactly that.
            const DEFLECT_UNDEFLECTABLE = new Set(['flamethrower', 'beam']);

            function isDeflectable(b) {
                if (b.returnable) return false;
                if (b.weaponConfig && b.weaponConfig.melee) return false;
                return !DEFLECT_UNDEFLECTABLE.has(b.type);
            }

            /** Try to turn a bolt aside on `defender`'s blade. Returns true if the
             *  bolt was deflected, in which case it has already been re-aimed and
             *  re-owned and must NOT also be resolved as a hit.
             *
             *  A deflected bolt is sent back toward whoever fired it and changes
             *  ownership to the defender, so it can kill the shooter. That is the
             *  payoff that makes the timing worth attempting. */
            function tryDeflect(defender, b, now) {
                if (now >= (defender.guardUntil || 0)) return false;
                if (!isDeflectable(b)) return false;
                if (b.noCollideUntil && now < b.noCollideUntil) return false;

                const dx = b.x - defender.x;
                const dy = b.y - defender.y;
                const dist = Math.hypot(dx, dy);
                // The guard covers the arc the blade sweeps, out to its reach.
                if (dist > getSwingReach(defender)) return false;

                const half = MELEE_SWING_ARC / 2;
                const toBolt = Math.atan2(dy, dx);
                const delta = Math.atan2(Math.sin(toBolt - defender.guardAngle),
                                         Math.cos(toBolt - defender.guardAngle));
                if (Math.abs(delta) > half) return false;

                // Send it back at the shooter. Aiming at the shooter rather than
                // mirroring the incoming vector is the more satisfying and more
                // useful read of "deflect", and it is what the films show.
                const shooter = b.owner;
                const speed = Math.hypot(b.dx, b.dy) || (b.weaponConfig ? b.weaponConfig.speed : 8);
                let backAngle;
                if (shooter && shooter.isAlive) {
                    backAngle = Math.atan2(shooter.y - b.y, shooter.x - b.x);
                } else {
                    backAngle = Math.atan2(-b.dy, -b.dx);
                }
                // A little scatter, so a deflect is a threat rather than a
                // guaranteed reflected kill on whoever pulled the trigger.
                backAngle += (Math.random() - 0.5) * 0.25;

                b.dx = Math.cos(backAngle) * speed;
                b.dy = Math.sin(backAngle) * speed;
                b.rotation = backAngle;
                b.owner = defender;
                b.travelled = 0;                  // a deflected bolt gets its range back
                b.noCollideUntil = now + 60;      // don't re-deflect on the very next frame

                // A deflected bolt is now the deflector's attack, and if it lands
                // applyStatusAndDamage will credit them the hit. Count the shot
                // here so the pair stays balanced — without it, turning an enemy
                // bolt back into their chest would push end-of-round accuracy
                // above 100%, since the round the player "fired" was never counted.
                if (defender.team === 'player') playerShotsFired++;

                playSound('lightsaberDeflect', 90);
                const bladeColor = defender.weaponConfig.key === 'staff'
                    ? defender.weaponConfig.color
                    : (defender.saberColor || defender.color);
                spawnHitSparks(b.x, b.y, bladeColor, 8);
                if (defender.isMainEntity) triggerScreenShake(2, 4);
                return true;
            }

            /** True during the first half of the Cloud City rescue: Leia is alone on
             *  the platform with Han still frozen, and nothing has turned up yet.
             *
             *  Combat is off in this phase. There is nothing to shoot — Han is a
             *  frozen slab that takes no damage and never fights back — so letting
             *  the player blast away only muddies what the phase is asking for,
             *  which is to walk up to him and hold Interact. Weapons come back the
             *  instant the phase ends.
             *
             *  The same four conditions used to be spelled out at each site that
             *  cared; they are here so the fire gate and the interact prompt cannot
             *  drift apart about when the phase is running. */
            function isCarboniteRescuePhase() {
                return currentArena === 'cloudcity'
                    && pCharData && pCharData.id === 'leia'
                    && eCharData && eCharData.id === 'carbonite_han'
                    && !specialCloudCityJabbaSpawned;
            }

            function resetJabbaEventState() {
                specialCloudCityJabbaHold = 0;
                specialCloudCityJabbaSpawned = false;
                specialCloudCityJabbaCharacter = null;
                specialCloudCityGuardTimer = 0;
                playableJabbaGuardCount = 0;
                playableJabbaNextGuard = gameNow() + 2200;
            }

            function spawnJabbaHutt() {
                if (specialCloudCityJabbaSpawned) return;
                specialCloudCityJabbaSpawned = true;
                specialCloudCityGuardTimer = gameNow() + 2200;

                // Built from the roster's own Jabba entry rather than a second copy
                // of his stats, so the boss who turns up here is the same character
                // the player can unlock — same colour, health, and weapon — and the
                // HUD panel below can render him exactly as a picked opponent.
                const jabbaData = characters.secret.find(c => c.id === 'jabba');
                const jabba = new Character(
                    Math.min(canvasLogicalW - CHARACTER_SIZE - 60, Math.max(CHARACTER_SIZE + 60, mainEnemy.x + 80)),
                    Math.min(canvasLogicalH - CHARACTER_SIZE - 40, Math.max(CHARACTER_SIZE + 40, mainEnemy.y)),
                    jabbaData.color, jabbaData.name, jabbaData.hp, jabbaData.weapon, jabbaData.color,
                    false, false, 'enemy',
                    // Main entity: he is the opponent from here on, which keeps him
                    // out of the backup sub-bars now that he owns the enemy panel.
                    true,
                    false, 0
                );
                jabba.characterId = 'jabba';
                jabba.isJabba = true;
                jabba.lastShotTime = gameNow();
                entities.push(jabba);
                specialCloudCityJabbaCharacter = jabba;

                // Hand the enemy HUD over to him — name, portrait, weapon and a live
                // health bar, exactly as if he had been the opponent all along.
                setEnemyHud(jabbaData, jabba);

                // Han is off the field the moment the carbonite gives — freeing him
                // is the goal, and a freed Han standing about as an enemy would be a
                // target the player has no reason to shoot.
                //
                // Marked fled rather than killed: he is not a kill, and the "any
                // enemy still alive" test that ends the match must find Jabba
                // standing in his place. That is why Jabba is pushed first — for one
                // frame otherwise the arena has no living enemy and the match ends
                // in a win the instant the player frees him.
                const han = entities.find(x => x.characterId === 'carbonite_han' && x.isAlive);
                if (han) {
                    han.isAlive = false;
                    han.hasFled = true;
                    spawnHitSparks(han.x, han.y, '#9fd8ff', 16);
                }

                showAnnouncement('Jabba has arrived. He does not fight directly — his Gamorrean guards will come for you!', '#a67a1c', 5000, '🐸 JABBA ARRIVES', 50, true);
            }

            // ── JABBA: RUNS, NEVER FIGHTS ──────────────────────────────
            // He has no attack of his own — the Gamorreans do that for him — so his
            // entire behaviour is putting distance between himself and whoever is
            // hunting him, and milling about when nobody is close. Deliberately far
            // slower than the player: running him down should take a moment of
            // commitment, which is the window his guards exist to punish.
            const JABBA_SPEED = 1.5;          // vs PLAYER_SPEED 3.5 — always catchable
            const JABBA_PANIC_RANGE = 300;    // outside this he wanders instead of fleeing
            const JABBA_WANDER_DRIFT = 0.06;  // radians per tick of aimless heading change

            function updateJabbaHutt(e, tickScale) {
                if (e.wanderAngle == null) e.wanderAngle = Math.random() * Math.PI * 2;

                const threat = getClosestEnemy(e);
                const dist = threat ? Math.hypot(threat.x - e.x, threat.y - e.y) : Infinity;

                if (threat && dist < JABBA_PANIC_RANGE) {
                    // Directly away from the threat, with a slither on top so he is
                    // not a straight line the player can simply walk down.
                    e.wanderAngle = Math.atan2(e.y - threat.y, e.x - threat.x) + (Math.random() - 0.5) * 0.4;
                } else {
                    e.wanderAngle += (Math.random() - 0.5) * JABBA_WANDER_DRIFT * tickScale;
                }

                const minX = CHARACTER_SIZE, maxX = canvasLogicalW - CHARACTER_SIZE;
                const minY = CHARACTER_SIZE, maxY = canvasLogicalH - CHARACTER_SIZE;
                const step = JABBA_SPEED * tickScale;

                // Bounce the heading off the arena edge rather than letting him grind
                // along it — cornered and still shoving at a wall reads as stuck.
                if (e.x + Math.cos(e.wanderAngle) * step < minX || e.x + Math.cos(e.wanderAngle) * step > maxX) {
                    e.wanderAngle = Math.PI - e.wanderAngle;
                }
                if (e.y + Math.sin(e.wanderAngle) * step < minY || e.y + Math.sin(e.wanderAngle) * step > maxY) {
                    e.wanderAngle = -e.wanderAngle;
                }

                e.x = Math.max(minX, Math.min(maxX, e.x + Math.cos(e.wanderAngle) * step));
                e.y = Math.max(minY, Math.min(maxY, e.y + Math.sin(e.wanderAngle) * step));

                // He returns early from the entity sweep, so the shared tail never
                // runs for him — push him out of cover here or he slides through it.
                checkEntityCoverCollision(e, tickScale);
            }

            function spawnGamorreanGuard() {
                if (!specialCloudCityJabbaSpawned || !specialCloudCityJabbaCharacter || !specialCloudCityJabbaCharacter.isAlive) return;
                const activeGuards = entities.filter(e => e.isAlive && e.characterId === 'gamorrean_guard').length;
                if (activeGuards >= 3) return;
                const angle = Math.random() * Math.PI * 2;
                const spawnDist = 110 + Math.random() * 50;
                const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, specialCloudCityJabbaCharacter.x + Math.cos(angle) * spawnDist));
                const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, specialCloudCityJabbaCharacter.y + Math.sin(angle) * spawnDist));
                const guard = new Character(x, y, '#cc3333', 'Gamorrean Guard', 95, 'blaster', '#cc3333', false, false, 'enemy', false, false, 18);
                guard.characterId = 'gamorrean_guard';
                guard.lastShotTime = gameNow() - Math.random() * 600;
                entities.push(guard);
            }

            function spawnPlayableGamorreanGuard() {
                if (!mainPlayer || !mainPlayer.isAlive || !pCharData || pCharData.id !== 'jabba') return;
                const activeGuards = entities.filter(e => e.isAlive && e.characterId === 'gamorrean_guard').length;
                if (activeGuards >= 6) return;
                playableJabbaGuardCount++;
                const angle = Math.random() * Math.PI * 2;
                const spawnDist = 110 + Math.random() * 50;
                const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.x + Math.cos(angle) * spawnDist));
                const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.y + Math.sin(angle) * spawnDist));
                const guard = new Character(x, y, '#cc3333', 'Gamorrean Guard', 95, 'blaster', '#cc3333', false, false, 'player', false, true, 18);
                guard.characterId = 'gamorrean_guard';
                guard.lastShotTime = gameNow() - Math.random() * 600;
                entities.push(guard);
            }

            // ── ANZELLAN REPAIR CREW (droid backup) ─────────────────────
            const ANZELLAN_HP = 30;
            const BABU_FRIK_CHANCE = 0.15; // lucky chance Babu Frik leads the crew
            const ANZELLAN_HEAL_PER_SEC = 3.5; // per escort, applied to the droid

            function spawnAnzellanEscorts(droid) {
                const luckyBabu = Math.random() < BABU_FRIK_CHANCE;
                const escorts = [];
                const count = 3;
                for (let i = 0; i < count; i++) {
                    const isBabuFrik = luckyBabu && i === 0;
                    escorts.push({
                        isBabuFrik,
                        name: isBabuFrik ? 'Babu Frik' : 'Anzellan',
                        hp: isBabuFrik ? ANZELLAN_HP * 4 : ANZELLAN_HP,
                        maxHp: isBabuFrik ? ANZELLAN_HP * 4 : ANZELLAN_HP,
                        color: isBabuFrik ? '#d9b38c' : '#b58f65',
                        orbitAngle: (Math.PI * 2 / count) * i + Math.random() * 0.4,
                        orbitRadius: 34 + Math.random() * 10,
                        orbitSpeed: 0.045 + Math.random() * 0.02,
                        x: droid.x, y: droid.y
                    });
                }
                droid.anzellanEscorts = escorts;

                if (luckyBabu) {
                    showAnnouncement(`"Hey hey hey!" Babu Frik and his crew swoop in to patch up ${droid.name}!`, '#d9b38c', 4500, '🔧 BABU FRIK ARRIVES', 50, true);
                } else {
                    showAnnouncement(`Anzellan techs rush in to repair ${droid.name}!`, '#b58f65', 4000, '🔧 REPAIR CREW', 50, true);
                }
            }

            function updateAnzellanEscorts(entity, tickScale) {
                if (!entity.anzellanEscorts || entity.anzellanEscorts.length === 0) return;

                let healTotal = 0;
                entity.anzellanEscorts.forEach(esc => {
                    esc.orbitAngle += esc.orbitSpeed * tickScale;
                    esc.x = entity.x + Math.cos(esc.orbitAngle) * esc.orbitRadius;
                    esc.y = entity.y + Math.sin(esc.orbitAngle) * esc.orbitRadius;
                    healTotal += ANZELLAN_HEAL_PER_SEC / TARGET_FPS * tickScale;
                });

                if (entity.isAlive && entity.health < entity.maxHealth) {
                    entity.health = Math.min(entity.maxHealth, entity.health + healTotal);
                }

                // Escorts complete their job once the droid is fully repaired
                if (entity.health >= entity.maxHealth) {
                    entity.anzellanEscorts.forEach(esc => spawnHitSparks(esc.x, esc.y, esc.color, 8));
                    entity.anzellanEscorts = [];
                }

                // Escorts leave with their droid if it falls
                if (!entity.isAlive) {
                    entity.anzellanEscorts = [];
                }
            }

            function drawAnzellanEscorts(entity) {
                if (!entity.anzellanEscorts || entity.anzellanEscorts.length === 0) return;
                entity.anzellanEscorts.forEach(esc => {
                    ctx.save();
                    const pulse = Math.sin(Date.now() * 0.006 + esc.orbitAngle) * 0.15 + 0.85;
                    const radius = esc.isBabuFrik ? 10 : 7;

                    ctx.shadowBlur = 10;
                    ctx.shadowColor = esc.color;
                    ctx.fillStyle = esc.color;
                    ctx.beginPath();
                    ctx.arc(esc.x, esc.y, radius, 0, Math.PI * 2);
                    ctx.fill();

                    // Little goggle-eyes
                    ctx.fillStyle = '#111';
                    ctx.beginPath();
                    ctx.arc(esc.x - radius * 0.35, esc.y - radius * 0.15, radius * 0.22, 0, Math.PI * 2);
                    ctx.arc(esc.x + radius * 0.35, esc.y - radius * 0.15, radius * 0.22, 0, Math.PI * 2);
                    ctx.fill();

                    // Mini health ring
                    ctx.globalAlpha = pulse;
                    ctx.strokeStyle = esc.color;
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(esc.x, esc.y, radius + 4, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * (esc.hp / esc.maxHp)));
                    ctx.stroke();

                    ctx.restore();
                });
            }

            function applyStatusAndDamage(target, projectile) {
                let damage = projectile.damage;
                // Apply per-weapon variance: roll a random multiplier within ±variance range
                const variance = projectile.variance || 0;
                if (variance > 0) {
                    damage *= (1 - variance) + Math.random() * variance * 2;
                }
                damage = Math.round(damage);
                const now = gameNow();
                if (target === mainPlayer && invincibilityEnabled) return;

                // Dodge i-frames. Sits above the shield check on purpose: a hit
                // rolled through should not also burn the shield that was being
                // saved for the one you cannot roll. Bolts are additionally made
                // to pass *through* a dodging target at the collision site rather
                // than being consumed here — this is the backstop that also
                // covers melee arcs, which never reach that loop.
                if (isInvulnerable(target, now)) {
                    spawnDodgeNegation(target);
                    return;
                }

                // A raised Halloween shield, facing the hit. Below the dodge for the
                // same reason the pickup shield is, and above the pickup so a hit the
                // held shield stopped does not also spend the one-hit pickup.
                //
                // An exploding round still goes off on the shield: the fighter
                // holding it is spared, everyone standing round them is not. The
                // epicentre is never re-hit by detonateBoomBoom, so this cannot leak
                // through the shield it just struck.
                if (shieldBlocksHit(target, projectile)) {
                    spawnShieldBlock(target);
                    const blockedCfg = projectile.weaponConfig || WEAPON_LIBRARY[projectile.type];
                    if (blockedCfg && blockedCfg.explodes) {
                        detonateBoomBoom(target, damage, projectile.owner, blockedCfg.explodes);
                    }
                    return;
                }
                // Reads the weapon's own melee flag rather than re-listing the melee
                // keys here. The three hardcoded lists this replaced had drifted
                // apart — vibroblade was in one of them and missing from the other
                // two, so it silently got no knockback and drew no blade.
                const isMeleeWeapon = !!(projectile.weaponConfig ? projectile.weaponConfig.melee
                                                                 : WEAPON_LIBRARY[projectile.type]?.melee);

                // Anzellan repair crew acts as a living shield — hits are soaked by
                // the escorts before any damage reaches the droid they're protecting
                if (target.anzellanEscorts && target.anzellanEscorts.length > 0) {
                    const escort = target.anzellanEscorts[0];
                    escort.hp -= damage;
                    spawnHitSparks(escort.x, escort.y, escort.color, 12);
                    if (escort.hp <= 0) {
                        target.anzellanEscorts.shift();
                    }
                    return; // fully absorbed — the droid takes no damage
                }

                // Shield absorption
                if (target.shieldActive && now < target.shieldUntil) {
                    target.shieldActive = false;
                    target.shieldUntil = 0;
                    spawnHitSparks(target.x, target.y, '#00aaff', 15);
                    return; // Shield absorbs the hit completely
                }

                // Melee range bonus: +40% damage if shooter is within 100px
                const shooterDist = Math.hypot(target.x - projectile.owner.x, target.y - projectile.owner.y);
                if (isMeleeWeapon && shooterDist < 100) {
                    damage *= 1.4;
                }

                // Hulk Smash, applied here rather than at the swing so it covers
                // every route damage can take out of him rather than only the one he
                // has today, and so a punch wound up inside the window but landing
                // after it is billed at the rate it lands at. Multiplies whatever the
                // melee bonus already made of it: 82 -> 115 -> 172.
                damage *= hulkSmashDamageMult(projectile.owner);
                // Giant-Man hits harder; shrunk, he hits the same. See ANT_MAN_FORMS.
                damage *= antFormDamageMult(projectile.owner);

                if (projectile.type === 'zap') {
                    if (!target.isDroid) {
                        // 40% chance to resist stun entirely; if it lands, only 600ms stun
                        if (now > target.zapImmunityUntil && Math.random() > 0.4) {
                            // The later of the two: a plain assignment let a B1's
                            // 600ms zap cut a freeze or a choke short, so a choked
                            // fighter could walk and shoot while still being
                            // choked (balance review #9).
                            target.stunnedUntil = Math.max(target.stunnedUntil || 0, now + 600);
                            target.wasStunned = true;
                        }
                    }
                } else if (projectile.type === 'wrench') {
                    if (!target.isDroid) {
                        // 50% chance to resist knockdown; if it lands, only 900ms
                        if (now > target.wrenchImmunityUntil && Math.random() > 0.5) {
                            target.knockedOutUntil = Math.max(target.knockedOutUntil || 0, now + 900);
                            target.wasKnockedOut = true;
                        }
                    } else {
                        damage *= WEAPON_LIBRARY.wrench.vsDroidMultiplier; 
                    }
                } else if (projectile.type === 'mjolnir') {
                    // The hammer flattens people. Same knockdown the Wrench deals,
                    // on the same per-target immunity clock so it cannot be chained,
                    // and with the same droid exemption — a droid takes the weight
                    // as damage and stays upright. It deliberately does NOT borrow
                    // the Wrench's anti-droid multiplier: that is a tool for opening
                    // machines, not a consequence of being heavy.
                    if (!target.isDroid && now > target.wrenchImmunityUntil && Math.random() > 0.5) {
                        target.knockedOutUntil = now + 900;
                        target.wasKnockedOut = true;
                    }
                }

                // Knockback — melee hits punch harder
                const kbAngle = Math.atan2(target.y - projectile.owner.y, target.x - projectile.owner.x);
                const kbStrength = isMeleeWeapon ? 10 : 4;
                target.vx += Math.cos(kbAngle) * kbStrength;
                target.vy += Math.sin(kbAngle) * kbStrength;

                // The Reality Staff throws away everything above and rolls: a whole
                // number from 0 to the target's health, inclusive. Done last so
                // no multiplier can scale the roll past the bar. See realitystaff.
                const rollCfg = projectile.weaponConfig || WEAPON_LIBRARY[projectile.type];
                if (rollCfg && rollCfg.realityRoll) {
                    damage = Math.floor(Math.random() * (Math.ceil(target.health) + 1));
                }
                // Same place and same reason: the ants' 2 is a promise, and the
                // multipliers above would break it. See antbite.
                if (rollCfg && rollCfg.fixedDamage) damage = rollCfg.damage;

                target.updateHealth(damage);

                // ── SFX: hit sounds based on weapon type ──────────────
                // This is the only place a blunt weapon makes a sound: swinging and
                // throwing one are silent, so the clang always means contact.
                const pt = projectile.type;
                if (isBluntWeapon(pt)) {
                    // Fists have their own landing. Everything else blunt — the
                    // hammer, the axe, the scimitar, both sets of claws, the shield
                    // — keeps the shared clang, which is a metal-on-something noise
                    // and wrong for a punch.
                    playSound(isFistWeapon(pt) ? 'punch' : 'bluntHit', 120);
                } else if (pt === 'staff') {
                    // The staff is the one blade with its own impact sample; the
                    // Darksaber deliberately shares the lightsaber's.
                    playSound('electrostaffClash', 90);
                } else if (pt === 'lightsaber' || pt === 'darksaber') {
                    playSound('lightsaberClash', 90);
                } else if (pt === 'zap' || pt === 'lightning') {
                    playSound('zap', 350);
                }

                // Flame sets its target alight. Refreshes an existing burn rather
                // than adding to it — see igniteBurn().
                if (pt === 'flamethrower') igniteBurn(target, projectile.owner);

                // Ice locks its target in place. The Ice Legion's entire
                // contribution to stage 4 is that you stop being able to move away
                // from the Ice King, so the freeze rides on the weapon's own
                // freezeMs rather than on who fired it.
                if (projectile.weaponConfig && projectile.weaponConfig.poisonMs) {
                    applyPoison(target, projectile.owner);
                }
                /*  `freezeChance` is optional, and its absence means "always".
                 *  That is right for the Ice Blast and the Sonic Taser: being held
                 *  still IS those weapons, and they pay for it with damage so low
                 *  they cannot finish anyone on their own.
                 *
                 *  The Ice Dagger cannot have it for free. It is melee, so every
                 *  hit already lands inside the point-blank band, and a guaranteed
                 *  hold on a weapon that also hurts is a fighter nobody escapes.
                 *  So it rolls, and applyFreeze’s own immunity window (see
                 *  FREEZE_IMMUNITY_MS) stops a lucky streak becoming a lock.     */
                if (projectile.weaponConfig && projectile.weaponConfig.freezeMs) {
                    const chance = projectile.weaponConfig.freezeChance;
                    if (chance == null || Math.random() < chance) {
                        applyFreeze(target, projectile.weaponConfig.freezeMs);
                    }
                }

                // Spawn hit sparks and impact particles
                const sparkColor = isMeleeWeapon ? projectile.owner.saberColor || projectile.owner.color : projectile.color;
                spawnHitSparks(target.x, target.y, sparkColor, isMeleeWeapon ? 15 : 10);
                if (!isMeleeWeapon) {
                    spawnImpactParticles(target.x, target.y, projectile.color, 8);
                }

                // Track player damage for achievement
                if (target.team === 'player' && target.isMainEntity) playerTookDamage = true;
                // Track player damage dealt & accuracy
                if (projectile.owner.team === 'player' && target.team === 'enemy') {
                    playerDamageDealt += Math.round(damage);
                    // A swing counts its hit once in performMeleeSwing, however many
                    // enemies the arc caught — counting per target here would let a
                    // multi-hit sweep report better than 100% accuracy.
                    if (!projectile.isSwing) playerHitsLanded++;
                }

                // Hit flash — canvas + HUD portrait
                target.hitFlashUntil = now + 90;
                const portraitId = target.team === 'player' ? 'playerPortrait' : 'enemyPortrait';
                const portrait = document.getElementById(portraitId);
                if (portrait) {
                    portrait.classList.remove('hit-flash');
                    void portrait.offsetWidth;
                    portrait.classList.add('hit-flash');
                }

                // floating damage number
                const dmgRounded = Math.round(damage);
                if (floatNums.length < MAX_FLOATS) floatNums.push({ x: target.x + (Math.random()-0.5)*20, y: target.y - CHARACTER_SIZE - 10, text: dmgRounded, life: 45, maxLife: 45, dy: -1.2 });

                // Boom Boom sprite: the hit that just landed also detonates.
                // Placed at the very end so the direct hit resolves normally
                // first — the splash is measured against the damage that was
                // actually dealt, after variance and the melee bonus.
                //
                // Asks the owner rather than checking for the player, so an
                // opponent who beat them to the drop detonates too, and it is
                // aimed back at the player exactly as theirs is aimed at the enemy.
                //
                // A weapon can also carry its own blast, which is what the Quad
                // Blasters do. Checked first and with an `else`, so a Star-Lord who
                // also holds the sprite detonates ONCE — twice would stack two
                // splashes on one round and pay the crowd damage twice over. The
                // weapon's own blast wins because it is the tighter, tuned one.
                const hitCfg = projectile.weaponConfig || WEAPON_LIBRARY[projectile.type];
                const weaponBlast = hitCfg && hitCfg.explodes;
                if (weaponBlast) {
                    detonateBoomBoom(target, damage, projectile.owner, weaponBlast);
                } else if (entityHasSprite(projectile.owner, 'boomBoom')) {
                    detonateBoomBoom(target, damage, projectile.owner);
                }
            }

            // ── BOOM BOOM SPRITE: SPLASH DAMAGE ────────────────────────────
            // Turns every weapon the player carries into an area weapon. The
            // entity that was hit directly is NOT re-damaged here — it already
            // took the full hit — so this only ever reaches the enemies standing
            // around it, which is what makes the sprite worth its rarity in the
            // crowded fights (clone backup, droid squads) and near-worthless in a
            // one-on-one duel.
            //
            // Deliberately does not call applyStatusAndDamage recursively: doing
            // so would re-roll variance, re-apply stuns and burns to a whole
            // crowd off one shot, and detonate again for each entity caught,
            // which is an infinite loop.
            const BOOM_BOOM_RADIUS = 130;           // px from the entity that was hit
            const BOOM_BOOM_SPLASH_FRACTION = 0.55; // of the direct hit, at the epicentre
            const BOOM_BOOM_MIN_FRACTION = 0.25;    // floor at the rim, so the edge still stings

            /*  `opts` lets a WEAPON bring its own blast instead of the sprite's —
             *  see WEAPON_LIBRARY.quadblaster, the first and so far only one. A
             *  weapon that fires four rounds a pull cannot borrow numbers tuned for
             *  a single detonation: four full-sized blasts would be four screen
             *  shakes, fifty-six particles and 2.2x the sprite's splash off one
             *  trigger. So radius and fraction are arguments, and everything that
             *  scales with them — the shake, the particle count — scales too.
             *
             *  Omit `opts` and it is exactly the sprite it always was.            */
            function detonateBoomBoom(epicentre, directDamage, owner, opts) {
                if (!owner) return;
                const radius   = (opts && opts.radius)      || BOOM_BOOM_RADIUS;
                const fraction = (opts && opts.fraction)    || BOOM_BOOM_SPLASH_FRACTION;
                const minFrac  = (opts && opts.minFraction) || BOOM_BOOM_MIN_FRACTION;
                const scale    = radius / BOOM_BOOM_RADIUS;

                spawnBoomBlast(epicentre.x, epicentre.y, radius);
                spawnImpactParticles(epicentre.x, epicentre.y, '#ff9a3c',
                                     Math.max(6, Math.round(14 * scale)));
                // No explosion sample ships in sounds/ — the blunt-impact thump is
                // the closest thing to a concussion the game has. Throttled hard so
                // a minigun burst doesn't machine-gun the sample, which is also what
                // collapses a four-round Quad Blaster pull into one bang.
                playSound('bluntHit', 220);
                triggerScreenShake(Math.max(2, Math.round(4 * scale)), 10);

                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (e === epicentre || !e.isAlive) continue;
                    if (e.team === owner.team) continue; // no friendly fire — the sprite is a boon, not a liability
                    if (e === mainPlayer && invincibilityEnabled) continue;

                    const dist = Math.hypot(e.x - epicentre.x, e.y - epicentre.y);
                    if (dist > radius) continue;

                    // A raised Halloween shield facing the blast takes it.
                    if (shieldFaces(e, epicentre.x, epicentre.y)) {
                        spawnShieldBlock(e);
                        continue;
                    }

                    // Linear falloff from the epicentre out to the rim, floored so
                    // a target clipped by the edge still takes something.
                    const falloff = Math.max(minFrac, 1 - dist / radius);
                    const splash = Math.max(1, Math.round(directDamage * fraction * falloff));

                    // Same defences the direct path respects, in the same order:
                    // an escort soaks the blast, and a shield pops on it.
                    if (e.anzellanEscorts && e.anzellanEscorts.length > 0) {
                        const escort = e.anzellanEscorts[0];
                        escort.hp -= splash;
                        spawnHitSparks(escort.x, escort.y, escort.color, 8);
                        if (escort.hp <= 0) e.anzellanEscorts.shift();
                        continue;
                    }
                    if (e.shieldActive && gameNow() < e.shieldUntil) {
                        e.shieldActive = false;
                        e.shieldUntil = 0;
                        spawnHitSparks(e.x, e.y, '#00aaff', 10);
                        continue;
                    }

                    // Blown away from the blast, not from the shooter.
                    const kbAngle = Math.atan2(e.y - epicentre.y, e.x - epicentre.x);
                    e.vx += Math.cos(kbAngle) * 6;
                    e.vy += Math.sin(kbAngle) * 6;

                    e.updateHealth(splash);

                    // Only the player's own blasts count toward their damage stat —
                    // an enemy detonation must not pad the end-of-round figure.
                    if (owner === mainPlayer && e.team === 'enemy') playerDamageDealt += splash;
                    // Accuracy is untouched on purpose: the shot was already counted
                    // as one hit, and crediting a hit per enemy caught would push
                    // end-of-round accuracy past 100%.

                    e.hitFlashUntil = gameNow() + 90;
                    spawnHitSparks(e.x, e.y, '#ff9a3c', 8);
                    if (floatNums.length < MAX_FLOATS) {
                        floatNums.push({ x: e.x + (Math.random()-0.5)*20, y: e.y - CHARACTER_SIZE - 10, text: splash, life: 45, maxLife: 45, dy: -1.2 });
                    }
                }
            }

            // ── FORCE CHOKE (Darth Vader) ──────────────────────────────────
            // Vader's signature move, and the first per-character ability in the
            // game: press Interact (E / ✋ / Y) with an opponent inside
            // FORCE_CHOKE_RANGE and they seize up where they stand.
            //
            // The hold reuses the existing stun system — the same `stunnedUntil`
            // the zap sets — so a choked entity is already frozen out of every
            // action by the `canAct` gate in update(). What choke adds on top is
            // damage that bleeds off across the same window instead of landing in
            // one lump, plus its own visual so it doesn't read as a zap.
            //
            // The 15% is measured against the VICTIM's max HP, so the move stays
            // meaningful against a 280 HP Sith Lord and doesn't delete a 40 HP
            // battle droid outright. To measure it against Vader's own pool
            // instead, use `caster.maxHealth` in startForceChoke below.
            const FORCE_CHOKE_IDS = new Set(['vader', 'darth_vader']); // base Vader and the Elite unlock
            const FORCE_CHOKE_RANGE = 220;        // px. The duelist AI band is 60-140, so this is "closed in" without being melee-only
            const FORCE_CHOKE_DURATION = 2000;    // ms of hold, and the window the damage is spread over
            const FORCE_CHOKE_COOLDOWN = 8000;    // ms between casts — without this it is a stunlock
            const FORCE_CHOKE_HP_FRACTION = 0.15; // of the victim's max HP, total, across the hold
            const FORCE_CHOKE_TICK_MS = 500;      // how often a floating damage number is emitted

            // Rising-edge latch for the Interact input. Choke is a press, not a
            // hold like the carbonite rescue, so holding E through the cooldown
            // must not re-cast the moment it comes back up.
            let forceChokeInputLatched = false;

            // ── AI FORCE CHOKE ─────────────────────────────────────────────
            //
            // Same range, same eight-second cooldown, same two-second hold, same 15%
            // of the victim's health, and the same finisher on the end of it. What
            // the AI does not get is the player's timing: it rolls for the cast
            // rather than choosing the moment, so a Vader who has someone in range
            // takes a second or two to decide.
            //
            // The snap IS rolled for now, once per grip. It used to be automatic,
            // and with nothing in the choke able to stop it that made an AI Vader a
            // death sentence: anyone at or under about 65% health inside 220px was
            // dead the moment his cast roll came up — the hold's own 15% carried
            // them under the 50% line and the snap fired on the next frame, through
            // nothing they could press. AI_NECK_SNAP_CHANCE is decided when the grip
            // closes (see startForceChoke) so a failed roll means that whole grip is
            // just a choke, rather than re-rolling every frame until it lands.
            // The player's own Vader is untouched: a player snaps when they press.
            const AI_CHOKE_ROLL_MS = 900;
            const AI_CHOKE_CHANCE = 0.55;
            const AI_NECK_SNAP_CHANCE = 0.4;

            function updateAiForceChoke() {
                const now = gameNow();
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    // Only the body the player is driving is excluded, and only
                    // because it has a key for this. isMainEntity is NOT that test —
                    // the main enemy carries it too, so checking it here skipped
                    // every Vader anybody actually fights.
                    if (!e.isAlive || e === mainPlayer) continue;
                    if (!FORCE_CHOKE_IDS.has(e.characterId)) continue;

                    const snap = findNeckSnapTarget(e);
                    if (snap && snap.chokeSnapAllowed && !(snap === mainPlayer && invincibilityEnabled)) {
                        performNeckSnap(e, snap);
                        continue;
                    }

                    if (now < (e.forceChokeReadyAt || 0)) continue;
                    if (frameNow < (e.aiChokeRollAt || 0)) continue;
                    e.aiChokeRollAt = frameNow + AI_CHOKE_ROLL_MS;
                    if (Math.random() >= AI_CHOKE_CHANCE) continue;

                    const victim = findForceChokeTarget(e);
                    if (!victim) continue;
                    // Dev invincibility has to hold against this the way it holds
                    // against everything else: the choke and the snap both write
                    // health directly, well underneath the checks that enforce it.
                    if (victim === mainPlayer && invincibilityEnabled) continue;
                    startForceChoke(e, victim);
                }
            }


            /*  ── THE MARVEL SPECIALS ─────────────────────────────────────────
     *  Three more per-character abilities on the shape Force Choke and Spin Dash
     *  already set: an id set, a cooldown, an Interact press, a window.
     *
     *  All three fire through fireSpreadProjectiles() with a config of their own
     *  rather than the holder's weapon, which is what lets a special hit harder
     *  and reach further than the gun that fires it. Those configs are
     *  deliberately NOT in WEAPON_LIBRARY: nothing equips them, and every entry in
     *  that table has to carry a HUD emoji and answer to validate.js.
     *
     *  Like Spin Dash, these are player abilities — canX() asks isMainEntity, so
     *  an AI Iron Man fires repulsors and never opens the Unibeam. That matches
     *  the precedent rather than setting a new one; giving the AI a cast (as
     *  Vader's choke has) is a separate job.                                    */

            /*  Iron Man's special is two abilities behind one button, and which one
             *  he has is the mark he is wearing.
             *
             *  Mk 1-5 fly on fire. Every mark widens the cone, lengthens the reach,
             *  raises the damage and shortens the wait, so the same button visibly
             *  gets better four times before it becomes something else. The Mk 5 is
             *  roughly the Mandarin's Flame Blast and no more — the step up is meant
             *  to be the Mk 6, not the top of the fire.
             *
             *  Mk 6 and up get the Unibeam, which then stops changing: from there the
             *  suit grows instead (see applyIronManMark). One heavy discharge from the
             *  chest plate, five fast hard bolts in a narrow fan, so the shape rewards
             *  pointing it at someone rather than near them.                        */
            const UNIBEAM_IDS = new Set(['ironman']);
            const UNIBEAM_COOLDOWN = 9000;
            const UNIBEAM_CONFIG = { key: 'unibeam', label: 'Unibeam', damage: 26, variance: 0.08,
                speed: 15, spin: false, draw: 'bolt', color: '#dff6ff', length: 34,
                multishot: 5, multishotArc: 0.16, maxRange: 560 };
            let unibeamInputLatched = false;

            // The fire phase, at Mk 1 and at Mk 5. Everything between is interpolated
            // on ironManFireProgress(), so adding marks to the phase needs no new
            // numbers here — only IRONMAN_FIRE_MAX_MARK moves.
            const MK_FIRE_MIN = { shots: 4, damage: 6,  arc: 0.44, range: 240, cooldown: 9500 };
            const MK_FIRE_MAX = { shots: 8, damage: 13, arc: 0.52, range: 430, cooldown: 7500 };

            function ironManOnFire() { return ironManMark() <= IRONMAN_FIRE_MAX_MARK; }

            function ironManSpecialConfig() {
                if (!ironManOnFire()) return UNIBEAM_CONFIG;
                const t = ironManFireProgress();
                const lerp = (a, b) => a + (b - a) * t;
                return {
                    key: 'markfire', label: 'Mk ' + ironManMark() + ' Flamethrowers',
                    damage: Math.round(lerp(MK_FIRE_MIN.damage, MK_FIRE_MAX.damage)),
                    variance: 0.16, speed: 10, spin: false, draw: 'flame',
                    color: '#ff8a2b', length: 18,
                    multishot: Math.round(lerp(MK_FIRE_MIN.shots, MK_FIRE_MAX.shots)),
                    multishotArc: lerp(MK_FIRE_MIN.arc, MK_FIRE_MAX.arc),
                    maxRange: Math.round(lerp(MK_FIRE_MIN.range, MK_FIRE_MAX.range))
                };
            }

            function ironManSpecialCooldown() {
                if (!ironManOnFire()) return UNIBEAM_COOLDOWN;
                const t = ironManFireProgress();
                return Math.round(MK_FIRE_MIN.cooldown + (MK_FIRE_MAX.cooldown - MK_FIRE_MIN.cooldown) * t);
            }

            // Spider-Man. Three lobbed capsules that web what they hit: the damage is
            // small and the 1.5s hold is the point. freezeMs runs through the same
            // applyFreeze() the Ice Blast uses, so a webbed fighter is locked out
            // by the existing canAct() gate rather than by a second status system.
            const WEB_GRENADE_IDS = new Set(['spiderman']);
            const WEB_GRENADE_COOLDOWN = 8000;
            const WEB_GRENADE_CONFIG = { key: 'webgrenade', label: 'Web Grenade', damage: 15, variance: 0.10,
                speed: 8, spin: true, draw: 'bolt', color: '#f4f7ff', length: 22,
                multishot: 3, multishotArc: 0.28, maxRange: 430, freezeMs: 1500 };
            let webGrenadeInputLatched = false;

            // The Mandarin. The ring that answers the Ice Blast, and the one thing
            // it has over the Flamethrower is reach: 520px against the Flamethrower's
            // 300, in a wide seven-tongue fan. Per-tongue damage is low because at
            // that width several of them land at once.
            const FLAME_BLAST_IDS = new Set(['mandarin']);
            const FLAME_BLAST_COOLDOWN = 7000;
            const FLAME_BLAST_CONFIG = { key: 'flameblast', label: 'Flame Blast', damage: 9, variance: 0.16,
                speed: 11, spin: false, draw: 'flame', color: '#ff8a2b', length: 20,
                multishot: 7, multishotArc: 0.5, maxRange: 520 };
            let flameBlastInputLatched = false;

            /*  ── THE GOD BLAST ─────────────────────────────────────────────────
             *  Thor's, and the only thing he owns that reaches. Mjølnir is a melee
             *  weapon that happens to come home when thrown, so without this he has
             *  no answer at all to someone who simply backs away — which is the
             *  whole reason the blast is shaped the way it is.
             *
             *  Three bolts down a 0.05 rad line rather than a fan. At that width it
             *  is one stroke of lightning and not a spread, so all three land on
             *  whatever it was pointed at: 90 damage, reliably, every 9.5 seconds.
             *  The Unibeam's five bolts are worth 130 on paper and rather less than
             *  that at range, where the cone has opened. That is the trade — Thor's
             *  is smaller and certain, and it is all he gets.
             *
             *  700px is deliberately the longest reach of any special in the game.
             *  A duel opens about 529px apart, so this is the one ability that can
             *  cross the whole arena, because crossing it is otherwise something he
             *  has to do on foot with a hammer.                                   */
            // Ragnarok is Thor's clone and carries the same blast, so he is listed
            // here rather than given one of his own: everything about it is Thor's.
            const GOD_BLAST_IDS = new Set(['thor', 'ragnarok']);
            const GOD_BLAST_COOLDOWN = 9500;
            const GOD_BLAST_CONFIG = { key: 'godblast', label: 'God Blast', damage: 30, variance: 0.10,
                speed: 17, spin: false, draw: 'zap', color: '#dff0ff', length: 42,
                multishot: 3, multishotArc: 0.05, maxRange: 700 };
            let godBlastInputLatched = false;

            /*  ── SHAPESHIFTING ─────────────────────────────────────────────────
             *  Loki takes the shape of the nearest living enemy: their name, their
             *  colour, their weapon with its own damage and cooldown, their body
             *  type, their movement, and their health bar. For twelve seconds he is
             *  fighting as them.
             *
             *  WHAT IT DOES NOT TAKE, and why:
             *
             *  characterId stays Loki's. It is the key three other systems read —
             *  which special is on the Interact button, which contracts advance,
             *  which sidearm a droid carries — so handing it over would end the
             *  disguise permanently (he could not cast to drop it), would stop his
             *  own contracts counting, and would quietly hand him a second
             *  character's ability on the same button. The sprite still changes:
             *  SpriteKit.kitFor() is asked for the TARGET's kit and the result is
             *  pinned to `kit`, which kitFor() prefers over everything else.
             *
             *  Health is copied as a FRACTION, not as a number. Copying it outright
             *  would make the ability a heal against anything bigger than him and a
             *  execution against anything smaller. At half health he arrives at half
             *  health, whoever he has become, and the same conversion runs in
             *  reverse when it wears off.
             *
             *  The cooldown is longer than the duration on purpose: twelve seconds
             *  wearing it, two seconds as himself, then he may go again. There is no
             *  window in which he can hold a shape indefinitely by re-casting.     */
            const SHAPESHIFT_IDS = new Set(['loki']);
            const SHAPESHIFT_COOLDOWN = 14000;
            const SHAPESHIFT_DURATION = 12000;
            let shapeshiftInputLatched = false;

            /*  ── HULK SMASH ─────────────────────────────────────────────────
             *  Two seconds of twice the speed and half again the damage. No
             *  projectile, no blast, nothing that reaches: it is a window, and what
             *  he does with the window is the same thing he does the rest of the
             *  time, only faster and harder.
             *
             *  That shape is the point. The Gamma Fists are 900ms a swing and cannot
             *  touch anyone who keeps their distance, so the thing the Hulk actually
             *  lacks is not power, it is the ability to close. Doubling his speed for
             *  two seconds sells exactly that, and the damage rides along so the two
             *  seconds are worth spending rather than merely worth surviving.
             *
             *  Two seconds is barely two swings at 900ms, which is deliberate: the
             *  window is for arriving, and landing one 172-damage hit at the end of
             *  it is the whole reward. A 10s cooldown puts it at a fifth of the fight
             *  and lines up with the rest of the season's specials.
             *
             *  The speed goes through `speedMult`, which the player branch and the AI
             *  movement branch both read — the same route Spin Dash takes, and the
             *  reason neither needs a second code path. The damage goes through
             *  applyStatusAndDamage rather than through the swing, so it covers every
             *  way he could ever deal damage rather than only the one he has today.  */
            /*  ── THE IRON MONGER ───────────────────────────────────────────────
             *  Stane's Interact, and the only special in the game that is not a shot
             *  or a timed buff — it is a different fighter. He climbs into the suit
             *  and stays in it: no duration, no cooldown, no way back. One press, once
             *  a round, and everything about him changes.
             *
             *  Built on the Shapeless Man's machinery rather than a new system, which
             *  already does exactly this: rewrite name, colour, profile and weapon on
             *  a live entity and let everything downstream keep reading the same
             *  fields. What this adds over that one is the weapon KEY changing — the
             *  Shapeless form keeps the gun it had and multiplies it, where this
             *  swaps a taser for a pair of fists.
             *
             *  The health is the other half. 175 is deliberately poor, and the suit
             *  takes the bar to 250 — so the trade is that Stane is the most fragile
             *  villain in the season until the moment he stops being.
             *
             *  It keeps the FRACTION he had, the way Loki's shapeshift does. It used
             *  to fill the new bar, and that made the decision below a fake one: a
             *  full refill pays most for waiting, so the right press was always at
             *  1 HP — 175 health plus a fresh 250 for Stane, 140 plus 240 for Bruce.
             *  Now half a bar becomes half a bigger bar, so suiting up early buys
             *  more fighting time in the stronger form and suiting up late buys a
             *  bigger bar with little in it. That is a real timing choice.
             *
             *  Deliberately NOT reversible. Reversibility would make it a cooldown
             *  ability with an obvious best-use pattern; one-way makes it a decision.  */
            const TRANSFORM_FORMS = {
                stane: { name: 'Iron Monger', color: '#6f7a85', hp: 250, weapon: 'mongerfists',
                         profile: 'brawler', tag: '\u2699\uFE0F IRON MONGER',
                         line: 'Obadiah Stane gets into the suit.' },
                // Tankier than both of the fists it shares its numbers with — 255
                // against Hulk's 240 and The Thing's 225 — which is the one column a
                // fighter who has to be built into is allowed to lead. He also spends
                // the first half of the round at 160 holding a pistol.
                blonsky: { name: 'Abomination', color: '#6f8f3a', hp: 255, weapon: 'abomfists',
                           profile: 'brawler', tag: '\u2623\uFE0F ABOMINATION',
                           line: 'Blonsky takes the second dose.' },
                // The third, and the only one where the form is a fighter the game
                // already had: these are the vaulted Hulk record's own numbers \u2014
                // 240, gammafists, #4d9e3f \u2014 restated here rather than looked up,
                // because every other entry in this table is a literal and one row
                // reaching into `characters` to be different would be worse than
                // the duplication. If the Hulk record is retuned, this moves too.
                //
                // 240 against the Abomination's 255 keeps the comics order the game
                // already had, and it is the same 82 fists either way. What makes
                // him the harder of the two is Hulk Smash on the throw key.
                bruce:   { name: 'Hulk', color: '#4d9e3f', hp: 240, weapon: 'gammafists',
                           profile: 'brawler', tag: '\uD83D\uDC9A HULK',
                           line: 'Banner stops holding it back.' }
            };
            const IRON_MONGER_IDS = new Set(Object.keys(TRANSFORM_FORMS));
            // What an AI Stane waits for. The player chooses the moment; the AI does
            // not have a button, so it suits up when it starts losing — which is when
            // a player would, and is also exactly when Stane does it in the film.
            const IRON_MONGER_AI_THRESHOLD = 0.5;
            let ironMongerInputLatched = false;

            /*  ── POISON SPIT ── VAULTED: POISON SPIT ───────────────────────────
             *  OUT OF ROTATION. POISON_SPIT_VAULTED below is the switch, canPoisonSpit()
             *  is the single point of use it is filtered at, and everything under this
             *  comment is retained exactly as it was — the config, the cooldown, the
             *  fire routine, and applyPoison()/tickPoison() further down, which nothing
             *  else in the game calls. Flip the const to false and the whole ability
             *  comes back with no other edit.
             *
             *  Why it went: the Abomination is gamma, not venomous. Nothing in the
             *  comics or the film has Emil Blonsky spitting poison, and it was the one
             *  ability in the season with no source behind it — invented to solve a
             *  balance problem rather than to be a thing the character does.
             *
             *  WHAT IT COSTS, stated plainly because it is a real hole rather than a
             *  tidy-up: this was the entire argument for the Abomination carrying the
             *  Gamma Fists' numbers. Hulk, The Thing and he all punch for exactly 82,
             *  and the three were told apart by the health under the fists and by what
             *  else each could do. He now has nothing else — the transform is one-way
             *  and spends his Interact, so after it he is 255 health and a pair of
             *  fists with no answer at all to someone walking away. He is currently
             *  the plainest of the three, and if he needs something back it should be
             *  something the Abomination actually does.
             *
             *  ── the original note, kept for whoever unvaults it ────────────────
             *  The Abomination's, and the only reason he is not simply a third set of
             *  Gamma Fists. Hulk, The Thing and he all punch for exactly 82; the other
             *  two have no answer whatsoever to someone backing away, and this is his.
             *
             *  Bound to the THROW action rather than to Interact, because Interact is
             *  already the transform and a fighter cannot have two. That action is
             *  right click, Q, the on-screen throw button and the pad's throw binding
             *  all folded into one `throwHeld`, so binding here gets every input at
             *  once instead of only the mouse.
             *
             *  It is free to take because the fists it arrives with are `noThrow`:
             *  there is no blade to throw, so the throw action was doing nothing for
             *  this fighter and nothing else changes hands.
             *
             *  Three globs in a narrow fan, small on impact and nasty afterwards —
             *  8 up front against 50 over the following five seconds. `poisonMs` is
             *  read in applyStatusAndDamage exactly where `freezeMs` is.             */
            // Declared here rather than beside applyPoison/tickPoison further down,
            // because POISON_SPIT_CONFIG below reads the duration and a `const` is in
            // its temporal dead zone until the line that declares it runs. See the
            // note on applyPoison().
            const POISON_DURATION_MS = 5000;
            const POISON_TICK_MS = 500;
            const POISON_TICK_DAMAGE = 5;

            const POISON_SPIT_COOLDOWN = 6000;
            const POISON_SPIT_CONFIG = { key: 'poisonspit', label: 'Poison Spit', damage: 8,
                variance: 0.12, speed: 9, spin: false, draw: 'bolt', color: '#8fe04a', length: 18,
                multishot: 3, multishotArc: 0.22, maxRange: 440, poisonMs: POISON_DURATION_MS };
            let poisonSpitInputLatched = false;

            // VAULTED: POISON SPIT. The switch, and the one place it is read.
            // canPoisonSpit() is the only gate on the whole ability — the input
            // branch, the throw binding and startPoisonSpit() all sit behind it —
            // so filtering here takes it off the field without touching any of them.
            const POISON_SPIT_VAULTED = true;

            function canPoisonSpit(e) {
                if (POISON_SPIT_VAULTED) return false;
                return !!(e && e.isAlive && e.isMainEntity && e.ironMongerForm
                          && e.characterId === 'blonsky');
            }

            function startPoisonSpit(e) {
                const target = (e === mainPlayer) ? resolvePlayerAim(e) : getClosestEnemy(e);
                if (!target) return false;
                fireSpreadProjectiles(e, target, POISON_SPIT_CONFIG,
                                      POISON_SPIT_CONFIG.multishot, POISON_SPIT_CONFIG.multishotArc);
                e.poisonSpitReadyAt = frameNow + POISON_SPIT_COOLDOWN;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('zap', 300);
                return true;
            }

            function canIronMonger(e) {
                return !!(e && e.isAlive && e.isMainEntity
                          && IRON_MONGER_IDS.has(e.characterId) && !e.ironMongerForm);
            }

            function ironMongerTransform(e) {
                if (!e || !e.isAlive || e.ironMongerForm) return false;
                const form = TRANSFORM_FORMS[e.characterId];
                if (!form) return false;
                e.ironMongerForm = true;
                e.name = form.name;
                e.color = form.color;
                e.tacticalProfileOverride = form.profile;

                // The weapon key changes, so the config is rebuilt from the library
                // rather than patched — getWeapon() is the one place that knows how to
                // turn a key into a live config, and going through it means the fists
                // arrive with their reach, their noThrow and their melee flag intact.
                e.weapon = form.weapon;
                e.weaponConfig = getWeapon({ weapon: form.weapon });
                // A magazine belonging to the old weapon would otherwise sit there
                // counting down against fists that have no rounds.
                e.magAmmo = null;
                e.isReloading = false;

                // Same fraction of a bigger bar — see the note on TRANSFORM_FORMS.
                // Guarded against a zero maxHealth like applyShapeshiftForm is.
                const frac = e.maxHealth > 0 ? Math.max(0, Math.min(1, e.health / e.maxHealth)) : 1;
                const before = e.health;
                e.maxHealth = Math.max(e.maxHealth, form.hp);
                e.health = Math.max(1, Math.round(e.maxHealth * frac));
                const healed = e.health - before;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('bluntHit');
                spawnBoomBlast(e.x, e.y, 64);
                if (healed > 0 && floatNums.length < MAX_FLOATS) {
                    floatNums.push({ x: e.x, y: e.y - CHARACTER_SIZE - 10,
                        text: '+' + Math.round(healed), life: 48, maxLife: 48,
                        dy: -1.1, color: '#8fe9a0' });
                }
                // The card is now describing someone who no longer exists — new
                // name, new colour, new weapon, new bar. Works for either side:
                // the player presses the button, and checkIronMongerAI() does this
                // to the opponent's card while the player watches.
                refreshHudIdentity(e);
                // Banner's Interact becomes Hulk Smash the moment this returns, and
                // the key that got him here is still down. The smash branch keeps
                // its own latch, which is still up, so without this the same single
                // press would transform him and spend the smash window in the same
                // frame. Closing it here means the player has to let go and press
                // again — which is what pressing a button twice means everywhere
                // else in the game. Harmless for Stane and Blonsky: neither has a
                // smash, so the latch they are closing is one nothing reads.
                hulkSmashInputLatched = true;
                // forceShow, like every other mid-match callout. setupGame() sets
                // deferAnnouncements for the whole battle so end-of-match rewards
                // do not pile up over the fight, and without this flag the line
                // announcing the transform sat in that queue until the round was
                // over — a fighter changed shape in silence and the game mentioned
                // it on the results screen.
                showAnnouncement(form.line, form.color, 3200, form.tag, 70, true);
                return true;
            }

            /** The AI's way in, since it never presses anything. Checked once a frame
             *  from the same place the Shapeless transform is. */
            function checkIronMongerAI(e) {
                if (!e || e === mainPlayer) return;
                if (!canIronMonger(e)) return;
                if (e.health / e.maxHealth > IRON_MONGER_AI_THRESHOLD) return;
                ironMongerTransform(e);
            }

            /*  Hulk Smash belongs to whoever is currently the Hulk, and since the
             *  Hulk is vaulted that is exactly one thing: a transformed Bruce.
             *
             *  ON INTERACT, SHARING THE KEY WITH THE TRANSFORM. Banner is the one
             *  fighter in the game whose Interact does two different things, and
             *  which one it does is which side of the change he is on: press it as
             *  Banner and he becomes the Hulk, press it as the Hulk and the Hulk
             *  smashes. Nothing had to be sequenced for that — canIronMonger() goes
             *  false the instant the form lands and canHulkSmash() requires that
             *  same form, so the two are never both true and the existing chain of
             *  branches sorts itself out.
             *
             *  What DID have to be handled is the single press doing both. The two
             *  branches carry independent latches, so on the transform frame the
             *  smash branch would see Interact still held with its own latch still
             *  up and fire immediately — one tap, and the whole window burned before
             *  he had finished arriving. ironMongerTransform() closes the smash latch
             *  on the way through; see the note there.                             */
            const HULK_SMASH_IDS = new Set(['bruce']);
            const HULK_SMASH_DURATION = 2000;   // ms of smash
            const HULK_SMASH_COOLDOWN = 10000;  // ms between uses
            const HULK_SMASH_SPEED = 2;         // movement multiplier while smashing
            const HULK_SMASH_DAMAGE = 1.5;      // outgoing damage multiplier while smashing
            let hulkSmashInputLatched = false;

            /*  ── CLOBBERIN' ─────────────────────────────────────────────────
             *  The Thing's, and the other half of the pair with Hulk Smash above.
             *  Both are two-second self-buffs on the same fists; Hulk's multiplies
             *  what one punch is worth, this multiplies how many of them land.
             *
             *  Two things happen for the duration, and they are the whole ability:
             *
             *  1. The swing cooldown is halved. The fists' own 900ms is what makes
             *     them heavy, and for two seconds it drops to
             *     CLOBBERIN_SWING_COOLDOWN — see meleeSwingCooldown(). It used to
             *     drop all the way to the 150ms floor, which with the 260ms swing
             *     commitment landed about seven punches in the window, roughly
             *     800 damage against Hulk Smash's ~520 (three punches at 172;
             *     balance review #7). At 450ms it is five punches at 115, ~575,
             *     which is the matched pair this block says the two are meant to
             *     be: Hulk's punches are worth half again, The Thing throws
             *     nearly twice as many.
             *
             *  2. The movement penalty comes off. Every other melee fighter walks
             *     at MELEE_COMMIT_SLOW while committed, and at four punches a
             *     second that would leave him rooted for the whole window — the
             *     flurry would pin him in place and read as a punishment rather
             *     than as a power. swingMoveScale() returns 1 instead.
             *
             *  Damage is untouched on purpose. Clobberin' is rate and mobility;
             *  Hulk Smash is weight. Giving this one a damage multiplier as well
             *  would make it strictly the better button.                         */
            const CLOBBERIN_IDS = new Set(['thing']);
            const CLOBBERIN_DURATION = 2000;    // ms of clobberin'
            const CLOBBERIN_COOLDOWN = 11000;   // ms between uses — a second over Hulk's
            const CLOBBERIN_SWING_COOLDOWN = 450; // ms between punches in the window (fists are 900)
            let clobberinInputLatched = false;

            /*  ── THE SNAP ───────────────────────────────────────────────────
             *  Thanos's, and the only special in the game that is not damage. Every
             *  living enemy rolls once: SNAP_KILL_CHANCE of them turn to dust on
             *  the spot, and the rest are untouched. In a duel that is a coin toss
             *  on the round. With backup on the field it is the film: half of
             *  everything across from him, give or take the dice.
             *
             *  Rolled per enemy rather than once for the whole cast, so a crowd
             *  loses about half its number instead of all or nothing. One roll for
             *  everyone would make the Snap a coin toss on the whole match, and
             *  the backup would count for nothing.
             *
             *  Nothing blocks it. Not a dodge's i-frames, not a guard and not the
             *  health bar. It is not a hit, so none of the rules for hits apply.
             *  The one thing it skips is Carbonite Han (`isFrozen`), who is a set
             *  piece rather than a fighter. The dev menu's invincibility is kept
             *  as well, the same as everywhere else.
             *
             *  25 seconds, and the Gauntlet starts every round EMPTY rather than
             *  charged. A charged start would open every round on a coin toss,
             *  and half of all rounds would be over before either fighter had
             *  moved. Starting empty means the first 25 seconds are a fist fight,
             *  and the Snap is what he has earned for surviving it. After that,
             *  one Snap every 25 seconds is still a 50% kill on a clock, so the
             *  cooldown is the one number to move if it plays too strong.
             *
             *  Player-only, the season's rule for every Interact special (see
             *  canHulkSmash). An AI Thanos punches. Being on the wrong end of a
             *  coin toss you never got to call reads as the game cheating.        */
            const SNAP_IDS = new Set(['thanos']);
            const SNAP_KILL_CHANCE = 0.5;
            /*  Bosses and unlock fights are not dusted outright. A 50% instant kill
             *  every 25 seconds turned Cousin Crew (500), Sith C-3PO (320) and the
             *  Mustafar fight against Sith Anakin into coin tosses for anyone who
             *  owned Thanos, and those are fights other rewards are gated behind
             *  (balance review #8). A losing roll on one of them takes a quarter
             *  of their full health instead: it still matters, and it still
             *  finishes one who is nearly down, but it cannot skip the fight.
             *  A boss is anything named here or anything at SNAP_BOSS_HP and up,
             *  which nothing on the ordinary roster reaches (Elite Vader is 300). */
            const SNAP_BOSS_IDS = new Set(['sith_anakin', 'sith_c3po', 'cousin_crew']);
            const SNAP_BOSS_HP = 310;
            const SNAP_BOSS_SHARE = 0.25;
            function isSnapBoss(o) {
                return SNAP_BOSS_IDS.has(o.characterId) || (o.maxHealth || 0) >= SNAP_BOSS_HP;
            }
            const SNAP_COOLDOWN = 25000;        // ms, and also the charge at the start of a round
            let infinitySnapInputLatched = false;

            /*  ── ETERNITY'S CALL ────────────────────────────────────────────
             *  Interact puts one fighter from either Marvel column on the field
             *  beside her, built by spawnBackupAlly() exactly as the Fury Sprite
             *  builds its backup, so an ally is the same thing whichever door it
             *  came through.
             *
             *  NO COOLDOWN, ONE AT A TIME. The limit is the ally rather than the
             *  clock. While the last one is standing the press does nothing, and
             *  the moment it falls she can call the next. So how often she calls
             *  is decided by how fast the other side can kill what she sends.
             *
             *  The pool is both columns, minus her and minus anything the player
             *  could not pick. That is the same filter the Fury Sprite uses, and
             *  for the same reason: an unbought Thanos or Star-Lord arriving free
             *  as backup gives away what their price buys. Vaulted fighters (the
             *  Hulk record) stay out, as they do everywhere.
             *
             *  Player-only, like every other Interact special. An AI Eternity
             *  fights with the staff.                                          */
            const ETERNITY_IDS = new Set(['eternity']);
            let eternitySummonInputLatched = false;

            /*  ── ZERO SHOCK ─────────────────────────────────────────────────
             *  The only special with a duration rather than a single discharge, and it
             *  is two things at once: he opens a beam and holds it, and for as long as
             *  it is open a shock field stands around him.
             *
             *  That shape is the point of the ability. The beam wants range and the
             *  field only reaches a body-width or two, so holding it means choosing
             *  which of the two is doing the work — back off and it is a beam, stand
             *  in the middle of them and it is both.
             *
             *  Contact damage is rate-limited PER VICTIM, the same as the Spin Dash
             *  and for the same reason: one shared timer would let him bill a crowd
             *  once, and no timer at all would delete anyone standing next to him at
             *  sixty ticks a second.                                                */
            const ZERO_SHOCK_IDS = new Set(['zero']);
            /*  Buffed on the side that asks something of him. The beam is the safe
             *  half — it reaches 620px and he can hold it from anywhere — so its
             *  per-bolt damage is untouched and only the window moved. The field is
             *  the half that requires standing in the middle of the fight, and that
             *  is where the buff went: wider, and half again as hard per tick.
             *
             *  Raising the beam instead would have been simpler and worse. At two
             *  bolts a volley every 220ms it paid ~250-280 over a cast from 620px,
             *  tracking its target the whole time — one landed cast killed most of
             *  the roster (balance review #6). The volley is now 450ms: about five
             *  volleys, ~140 from the beam, which sits with the God Blast, Unibeam
             *  and Flame Blast (60-130) plus a little for the window. The field is
             *  untouched, so standing in the middle of them still pays the most.  */
            const ZERO_SHOCK_COOLDOWN = 8500;   // ms between casts
            const ZERO_SHOCK_DURATION = 2000;   // ms the beam stays open
            const ZERO_SHOCK_VOLLEY_MS = 450;   // how often the beam re-fires while held
            const ZERO_SHOCK_RADIUS = CHARACTER_SIZE * 4.2;
            const ZERO_SHOCK_DAMAGE = 22;       // per contact tick
            const ZERO_SHOCK_TICK_MS = 400;     // per-victim damage interval
            const ZERO_SHOCK_BEAM = { key: 'zeroshock', label: 'Zero Shock', damage: 14, variance: 0.08,
                speed: 16, spin: false, draw: 'zap', color: '#c9a6ff', length: 30,
                multishot: 2, multishotArc: 0.06, maxRange: 620 };
            let zeroShockInputLatched = false;

            function canZeroShock(e) { return !!(e && e.isAlive && e.isMainEntity && ZERO_SHOCK_IDS.has(e.characterId)); }
            function isZeroShocking(e) { return !!(e && e.zeroShockUntil && frameNow < e.zeroShockUntil); }

            function startZeroShock(e) {
                // Aimed once here only to refuse the cast with nothing to point at;
                // every volley below re-aims, so the beam tracks while it is open.
                if (!resolvePlayerAim(e)) return false;
                e.zeroShockUntil = frameNow + ZERO_SHOCK_DURATION;
                e.zeroShockReadyAt = frameNow + ZERO_SHOCK_COOLDOWN;
                // Keyed by the entity itself, not characterId: every stormtrooper,
                // B1 or ant in a squad shares an id, so an id key let only one of
                // each type take the field's damage per tick (balance review #12).
                e.zeroShockHits = new Map();
                e.zeroShockNextVolley = 0;
                matchSpecialsUsed++;
                // Not playSound('forceLightning'): that loop never stops on its own.
                // See startBoltHeldLightning.
                startBoltHeldLightning();
                spawnBoomBlast(e.x, e.y, ZERO_SHOCK_RADIUS);
                return true;
            }

            function updateZeroShock(e) {
                if (!e || !e.isAlive || !isZeroShocking(e)) return;

                // The beam, re-aimed every volley so it sweeps with him.
                if (frameNow >= (e.zeroShockNextVolley || 0)) {
                    const target = resolvePlayerAim(e);
                    if (target) {
                        fireSpreadProjectiles(e, target, ZERO_SHOCK_BEAM,
                                              ZERO_SHOCK_BEAM.multishot, ZERO_SHOCK_BEAM.multishotArc);
                    }
                    e.zeroShockNextVolley = frameNow + ZERO_SHOCK_VOLLEY_MS;
                }

                // The field.
                for (const other of entities) {
                    if (!other.isAlive || other.team === e.team) continue;
                    if (other.isFrozen) continue;
                    if (Math.hypot(other.x - e.x, other.y - e.y) > ZERO_SHOCK_RADIUS + CHARACTER_SIZE) continue;
                    const readyAt = e.zeroShockHits.get(other) || 0;
                    if (frameNow < readyAt) continue;
                    e.zeroShockHits.set(other, frameNow + ZERO_SHOCK_TICK_MS);
                    applyHazardDamage(other, ZERO_SHOCK_DAMAGE, '#a274ff');
                }
            }

            /** Two counter-rotating arcs and a rim, drawn under the fighter so the
             *  field reads as something he is standing inside rather than wearing. */
            function drawZeroShock(e) {
                if (!isZeroShocking(e)) return;
                const spin = frameNow * 0.006;
                ctx.save();
                ctx.translate(e.x, e.y);
                ctx.globalAlpha = 0.5;
                ctx.strokeStyle = '#c9a6ff';
                ctx.lineWidth = 2;
                if (effectsEnabled()) { ctx.shadowBlur = 16; ctx.shadowColor = '#a274ff'; }
                ctx.beginPath();
                ctx.arc(0, 0, ZERO_SHOCK_RADIUS, 0, Math.PI * 2);
                ctx.stroke();
                for (let i = 0; i < 2; i++) {
                    const dir = i ? -1 : 1;
                    ctx.beginPath();
                    ctx.arc(0, 0, ZERO_SHOCK_RADIUS - 6 - i * 5,
                            spin * dir + i * 2.1, spin * dir + i * 2.1 + Math.PI * 0.75);
                    ctx.stroke();
                }
                ctx.restore();
            }

            function canUnibeam(e)    { return !!(e && e.isAlive && e.isMainEntity && UNIBEAM_IDS.has(e.characterId)); }
            function canWebGrenade(e) { return !!(e && e.isAlive && e.isMainEntity && WEB_GRENADE_IDS.has(e.characterId)); }
            function canFlameBlast(e) { return !!(e && e.isAlive && e.isMainEntity && FLAME_BLAST_IDS.has(e.characterId)); }
            function canGodBlast(e)   { return !!(e && e.isAlive && e.isMainEntity && GOD_BLAST_IDS.has(e.characterId)); }

            /** Shared body for all three. Aims where the player is aiming, spends the
             *  cooldown only if a target actually resolved, and leaves the holder's
             *  own weapon, magazine and trigger state completely alone. */
            function fireSpecial(e, config, cooldownMs, readyKey, sfx, blastRadius) {
                const target = resolvePlayerAim(e);
                if (!target) return false;
                fireSpreadProjectiles(e, target, config, config.multishot, config.multishotArc);
                if (e === mainPlayer) matchSpecialsUsed++;
                e[readyKey] = frameNow + cooldownMs;
                // A function rather than a sound name for anything that has its own
                // cue — the flame weapons run through pulseFlamethrower(), which
                // sustains a loop instead of firing a one-shot sample.
                if (typeof sfx === 'function') sfx();
                else if (sfx) playSound(sfx, 200);
                spawnBoomBlast(e.x, e.y, blastRadius);
                return true;
            }

            /** Whichever of the two he has earned. The ready-at key is shared on
             *  purpose: it is one button on one cooldown, and crossing from fire to
             *  the Unibeam should not hand the player a free cast. */
            function startUnibeam(e) {
                const onFire = ironManOnFire();
                return fireSpecial(e, ironManSpecialConfig(), ironManSpecialCooldown(),
                                   'unibeamReadyAt', onFire ? pulseFlamethrower : startBoltHeldLightning,
                                   onFire ? 44 : 54);
            }
            function startWebGrenade(e) { return fireSpecial(e, WEB_GRENADE_CONFIG, WEB_GRENADE_COOLDOWN, 'webGrenadeReadyAt', 'bluntHit', 40); }
            // Also a flame weapon, and it was firing silently: same cue as the Mk 1-5.
            function startFlameBlast(e) { return fireSpecial(e, FLAME_BLAST_CONFIG, FLAME_BLAST_COOLDOWN, 'flameBlastReadyAt', pulseFlamethrower, 46); }
            /*  pulseForceLightning rather than playSound('forceLightning'): that
             *  sample is a LOOP (see sfxSounds.forceLightning.loop), and the only
             *  thing that ever cuts it is updateForceLightningLoop() watching the
             *  sustain clock that pulseForceLightning sets. Firing it directly
             *  starts a drone that nothing turns off until the match ends.       */
            function startGodBlast(e) { return fireSpecial(e, GOD_BLAST_CONFIG, GOD_BLAST_COOLDOWN, 'godBlastReadyAt', pulseForceLightning, 54); }

            /** The nearest living enemy, which is the whole targeting rule: no line
             *  of sight, no range limit, no cone. Whoever is closest is who he
             *  becomes. */
            function findShapeshiftTarget(e) {
                let best = null;
                let bestDist = Infinity;
                for (const other of entities) {
                    if (!other.isAlive || other === e || other.team === e.team) continue;
                    const d = Math.hypot(other.x - e.x, other.y - e.y);
                    if (d < bestDist) { bestDist = d; best = other; }
                }
                return best;
            }

            /** True for Loki, and true for anyone currently wearing a stolen shape —
             *  which is the same person, and is what lets him cast again to change
             *  shape rather than being locked into the first face he took. */
            function canShapeshift(e) {
                return !!(e && e.isAlive && e.isMainEntity
                          && (SHAPESHIFT_IDS.has(e.characterId) || e.shapeshiftFrom));
            }

            function startShapeshift(e) {
                const target = findShapeshiftTarget(e);
                if (!target) return false;

                // Snapshot who he really is, once. Re-casting mid-disguise must not
                // record the disguise as the thing to revert to.
                if (!e.shapeshiftFrom) {
                    e.shapeshiftFrom = {
                        name: e.name, color: e.color, saberColor: e.saberColor,
                        weapon: e.weapon, weaponConfig: e.weaponConfig,
                        maxHealth: e.maxHealth, kit: e.kit,
                        isDroid: e.isDroid, isWookiee: e.isWookiee, isClone: e.isClone,
                        speedMult: e.speedMult,
                        tacticalProfileOverride: e.tacticalProfileOverride
                    };
                }

                applyShapeshiftForm(e, {
                    name: target.name, color: target.color, saberColor: target.saberColor,
                    weaponConfig: target.weaponConfig,
                    maxHealth: target.maxHealth,
                    kit: (typeof SpriteKit !== 'undefined' && SpriteKit.kitFor)
                        ? SpriteKit.kitFor(target) : e.kit,
                    isDroid: target.isDroid, isWookiee: target.isWookiee, isClone: target.isClone,
                    speedMult: target.speedMult,
                    tacticalProfileOverride: target.tacticalProfileOverride
                });

                e.shapeshiftUntil = frameNow + SHAPESHIFT_DURATION;
                e.shapeshiftReadyAt = frameNow + SHAPESHIFT_COOLDOWN;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('dash');
                spawnBoomBlast(e.x, e.y, 48);
                return true;
            }

            /** Wear a form. Shared by the cast and by the revert, so the two can
             *  never drift into copying different fields. */
            function applyShapeshiftForm(e, form) {
                // Health as a fraction of the bar, never as a number — see the note
                // on SHAPESHIFT_IDS. Guarded against a zero maxHealth so a divide
                // cannot put a NaN in the health bar.
                const frac = e.maxHealth > 0 ? Math.max(0, Math.min(1, e.health / e.maxHealth)) : 1;

                e.name = form.name;
                e.color = form.color;
                e.saberColor = form.saberColor;
                // A copy, not the same object: a stolen weapon must not become a
                // shared config that some later per-entity tweak writes through.
                e.weaponConfig = Object.assign({}, form.weaponConfig);
                e.weapon = e.weaponConfig.key;
                e.maxHealth = form.maxHealth;
                e.health = Math.max(1, Math.round(e.maxHealth * frac));
                e.kit = form.kit;
                e.isDroid = !!form.isDroid;
                e.isWookiee = !!form.isWookiee;
                e.isClone = !!form.isClone;
                e.speedMult = form.speedMult || 1;
                e.tacticalProfileOverride = form.tacticalProfileOverride || null;

                // Everything below is state that belonged to the weapon he was
                // holding a frame ago and means nothing for the one he is holding
                // now. Left alone, a Mjølnir swing would land out of a blaster and
                // a stolen rifle would start life with someone else's magazine.
                cancelMeleeSwing(e);
                e.magAmmo = e.weaponConfig.magSize != null ? e.weaponConfig.magSize : null;
                e.isReloading = false;
                e.reloadEndsAt = 0;
                e.burstShot = 0;
                e.focusShots = 0;
                e.triggerReleased = true;
                e.throwReadyAt = 0;

                // Loki wearing someone else's shape is a transform too, and the
                // card has to follow it in both directions — into the disguise and
                // back out of it. Routed through the shared helper rather than the
                // player-only call this used to make, so the enemy panel keeps up
                // as well.
                refreshHudIdentity(e);
            }


            /** Drop the shape. Safe to call on someone who is not wearing one. */
            function endShapeshift(e) {
                if (!e || !e.shapeshiftFrom) return;
                const from = e.shapeshiftFrom;
                e.shapeshiftFrom = null;
                e.shapeshiftUntil = 0;
                applyShapeshiftForm(e, from);
                if (e.isAlive) spawnBoomBlast(e.x, e.y, 40);
            }

            /** Runs from the frame loop, ahead of the canAct gate, so a disguise
             *  expires on time even while its wearer is stunned or knocked down. */
            function updateShapeshift(e) {
                if (!e || !e.shapeshiftFrom) return;
                if (frameNow < (e.shapeshiftUntil || 0)) return;
                endShapeshift(e);
            }

            /*  ── WEAPON SWAP ────────────────────────────────────────────────
             *  Deadpool's, and the only Interact in the game that is not an
             *  ability: it puts one weapon away and draws the other. The id maps
             *  to the weapon he is NOT holding at the start of a round; the
             *  roster entry's `weapon` (or whatever the Armory equipped) is the
             *  other half.
             *
             *  The holstered weapon keeps its own magazine in `swapStash`, so a
             *  swap is never a free reload: put the Glock away on three rounds
             *  and it comes back on three. A reload in progress is cancelled by
             *  the holster, the way it would be in a hand.
             *
             *  Refused while a thrown katana is still out — he cannot draw a
             *  blade that is in the air, and swapping the config under a
             *  returning projectile would hand the catch to the wrong weapon.
             *
             *  The AI swaps too, which breaks the season's rule that an AI
             *  never presses Interact. The rule is there because the specials
             *  are bonuses; this is half of the fighter. An AI Deadpool that
             *  never drew the Glock would be a worse Killmonger. See
             *  updateWeaponSwapAI().                                             */
            const WEAPON_SWAP_IDS = { deadpool: 'glock' };
            // Floor between swaps, so mashing the key cannot stutter the sprite
            // between two poses. Short enough that it never gets in the way of a
            // real decision.
            const WEAPON_SWAP_COOLDOWN = 300;
            // The AI's bands, in px from the target. Inside the first it wants the
            // swords, outside the second it wants the gun, and in between it keeps
            // whatever it has, so it does not flicker on the line. The swords'
            // reach is 34 past the body, so 110 is about two steps from a cut.
            const WEAPON_SWAP_AI_MELEE_RANGE = 110;
            const WEAPON_SWAP_AI_GUN_RANGE = 190;
            // The AI's own floor, longer than the player's so it commits to a
            // choice instead of reading as indecisive.
            const WEAPON_SWAP_AI_COOLDOWN = 1200;
            let weaponSwapInputLatched = false;

            function canWeaponSwap(e) {
                return !!(e && e.isAlive && e.isMainEntity && !e.shapeshiftFrom
                          && WEAPON_SWAP_IDS[e.characterId]);
            }

            function weaponSwapReady(e) {
                return frameNow >= (e.weaponSwapReadyAt || 0) && !hasBladeInFlight(e);
            }

            function swapWeapon(e) {
                if (!canWeaponSwap(e) || !weaponSwapReady(e)) return false;
                const stash = e.swapStash || (() => {
                    const cfg = getWeapon({ weapon: WEAPON_SWAP_IDS[e.characterId] });
                    return { weaponConfig: cfg, magAmmo: cfg.magSize != null ? cfg.magSize : null };
                })();
                e.swapStash = { weaponConfig: e.weaponConfig, magAmmo: e.magAmmo };

                e.weaponConfig = stash.weaponConfig;
                e.weapon = e.weaponConfig.key;
                e.magAmmo = stash.magAmmo;
                // The same list applyShapeshiftForm() clears, for the same reason:
                // all of it belonged to the weapon that was in the hand a frame ago.
                cancelMeleeSwing(e);
                e.isReloading = false;
                e.reloadEndsAt = 0;
                e.burstShot = 0;
                e.focusShots = 0;
                e.triggerReleased = true;
                e.throwReadyAt = 0;

                e.weaponSwapReadyAt = frameNow + WEAPON_SWAP_COOLDOWN;
                playSound(e.weaponConfig.melee ? 'bluntHit' : 'dash', 120);
                refreshHudIdentity(e);
                return true;
            }

            /** The AI's half. Runs once a frame for the opponent, from the same
             *  place the Iron Monger check does. Swords when close, the gun when
             *  far, and the swords when the gun is dry rather than standing there
             *  reloading at knife range. */
            function updateWeaponSwapAI(e) {
                if (!e || e === mainPlayer || !canWeaponSwap(e)) return;
                const now = gameNow();
                if (now < e.stunnedUntil || now < e.knockedOutUntil || now < e.chokedUntil) return;
                if (frameNow < (e.weaponSwapAIReadyAt || 0)) return;
                const target = getClosestEnemy(e);
                if (!target) return;
                const dist = Math.hypot(target.x - e.x, target.y - e.y);
                const melee = !!e.weaponConfig.melee;
                const gunDry = !melee && (e.isReloading || e.magAmmo === 0);
                const want = (dist < WEAPON_SWAP_AI_MELEE_RANGE || gunDry) ? 'melee'
                           : dist > WEAPON_SWAP_AI_GUN_RANGE ? 'gun'
                           : null;
                if (!want || (want === 'melee') === melee) return;
                // A dry gun only makes swords worth it if the swords can reach;
                // past the gun band he may as well finish the reload.
                if (gunDry && dist > WEAPON_SWAP_AI_GUN_RANGE) return;
                if (swapWeapon(e)) e.weaponSwapAIReadyAt = frameNow + WEAPON_SWAP_AI_COOLDOWN;
            }

            /*  ── HALLOWEEN: THE SHIELD ──────────────────────────────────────
             *  All six Halloween fighters carry one, and it is the only Interact in
             *  the game that is HELD rather than pressed: up for as long as the key
             *  is down, and back down the frame it comes up. No timer and no
             *  cooldown, because that is the mechanic as it was asked for — what
             *  keeps it from being a wall the round can be waited out behind is
             *  everything it costs while it is up:
             *
             *    · it covers the FRONT only, 75° either side of where the fighter
             *      is facing. Anything that comes round the side still lands, so
             *      backup, summons and a second attacker all get through it;
             *    · nothing gets fired, swung or thrown while it is up — the weapon
             *      block in update() is skipped outright;
             *    · the fighter walks at 55%;
             *    · it cannot come up mid-swing. A committed cut stays committed,
             *      and a shield that cancelled one would be a second way out of
             *      the recovery that the dodge is meant to own.
             *
             *  What it stops: bolts, thrown blades, melee swings and the splash of
             *  an explosion — every hit that comes through applyStatusAndDamage or
             *  detonateBoomBoom from in front. What it does not stop: anything that
             *  is not a hit — a choke, a burn already lit, poison, a hazard — which
             *  is the same line the shield pickup draws.
             *
             *  `shieldRaised` is the whole of the state, and it is per entity, so a
             *  new round wipes it by building new Characters. Distinct from
             *  `shieldActive`, which is the one-hit pickup and has nothing to do
             *  with this.                                                         */
            const HALLOWEEN_SHIELD_IDS = new Set(['skeleton', 'hawlo', 'lordtreat', 'burntskeleton', 'wheen', 'lordtrick']);
            const HALLOWEEN_SHIELD_HALF_ARC = 75 * Math.PI / 180;
            const HALLOWEEN_SHIELD_MOVE_SCALE = 0.55;
            /*  The AI's half. It cannot see a key, so it raises the shield the way it
             *  already dodges — at a bolt it has actually seen coming, or a swing
             *  that has actually started — and rolls the difficulty's blockChance
             *  once per bolt or swing, the same 25/40/60/75% the bolt clash uses.
             *  It sees a little further ahead than its dodge does (380ms against
             *  Normal's 320), because a shield is raised rather than dived into.
             *
             *  Then it holds for 650ms and has to wait 450 before it can raise it
             *  again. Without that floor a Minigun or the Beam, which put a bolt on
             *  the way every frame, would keep an AI skeleton behind its shield for
             *  the whole round and it would never swing back.                   */
            const HALLOWEEN_SHIELD_AI_SIGHT_MS = 380;
            const HALLOWEEN_SHIELD_AI_HOLD_MS = 650;
            const HALLOWEEN_SHIELD_AI_REST_MS = 450;
            // Which side's shields are burnt. Read off the season rather than listed
            // again, so a villain added to that column later is drawn to match.
            const HALLOWEEN_BURNT_IDS = new Set(HALLOWEEN_SEASON.villains.ids);
            // The red aura is the Burnt Skeleton Warriors' alone, as asked — Wheen
            // and Lord Trick are burnt by allegiance, not by fire.
            const HALLOWEEN_AURA_IDS = new Set(['burntskeleton']);

            function canRaiseShield(e) {
                return !!(e && e.isAlive && HALLOWEEN_SHIELD_IDS.has(e.characterId));
            }

            function shieldMoveScale(e) {
                return e && e.shieldRaised ? HALLOWEEN_SHIELD_MOVE_SCALE : 1;
            }

            function setShieldRaised(e, up) {
                const want = !!up && canRaiseShield(e);
                if (!!e.shieldRaised === want) return;
                e.shieldRaised = want;
            }

            /** Does a raised shield on `target` face the point (sx, sy)? Measured
             *  against lastAimAngle, which draw() keeps pointed at whoever the
             *  fighter is facing — the same angle the shield is painted on, so what
             *  the player sees covered is what is covered. */
            function shieldFaces(target, sx, sy) {
                if (!target || !target.shieldRaised || !canRaiseShield(target)) return false;
                const toSrc = Math.atan2(sy - target.y, sx - target.x);
                const facing = target.lastAimAngle || 0;
                const delta = Math.atan2(Math.sin(toSrc - facing), Math.cos(toSrc - facing));
                return Math.abs(delta) <= HALLOWEEN_SHIELD_HALF_ARC;
            }

            /** Where a hit is arriving from. A bolt is asked which way it is flying
             *  rather than where its owner stands, so a thrown blade on its way home
             *  or a shot that came round cover is judged by its real approach; a
             *  swing has no flight, so it comes from the swordsman. */
            function shieldBlocksHit(target, projectile) {
                if (!target || !target.shieldRaised) return false;
                if (!projectile.isSwing && Number.isFinite(projectile.dx) && (projectile.dx || projectile.dy)) {
                    return shieldFaces(target, target.x - projectile.dx, target.y - projectile.dy);
                }
                const src = projectile.owner;
                return !!src && shieldFaces(target, src.x, src.y);
            }

            function spawnShieldBlock(target) {
                const a = target.lastAimAngle || 0;
                const r = bodyRadius(target) + 7;
                const burnt = HALLOWEEN_BURNT_IDS.has(target.characterId);
                spawnHitSparks(target.x + Math.cos(a) * r, target.y + Math.sin(a) * r,
                               burnt ? '#ff3b2f' : '#ffcf7a', 10);
                playSound('bluntHit', 120);
            }

            /** The AI's shield. Called from the AI branch of update() for every
             *  Halloween fighter it drives, ahead of movement so the 55% walk applies
             *  on the same frame the shield comes up. */
            function updateShieldAI(e, target, now) {
                if (e.shieldRaised) {
                    if (now < (e.shieldAIHoldUntil || 0)) return;
                    setShieldRaised(e, false);
                    e.shieldAIReadyAt = now + HALLOWEEN_SHIELD_AI_REST_MS;
                    return;
                }
                if (now < (e.shieldAIReadyAt || 0) || isCommittedToSwing(e, now)) return;

                // A bolt on its way, or a swing already wound up within reach.
                // Each one is rolled for once, keyed on the bolt itself or on the
                // moment the swing lands, so a bolt seen across six frames is still
                // one roll and not six.
                let seen = null;
                const threat = findIncomingThreat(e, HALLOWEEN_SHIELD_AI_SIGHT_MS);
                if (threat) {
                    seen = threat.bullet;
                } else if (target && target.pendingSwingAt && frameNow < target.pendingSwingAt
                           && Math.hypot(target.x - e.x, target.y - e.y) <= getSwingReach(target) + bodyRadius(e) + 10) {
                    seen = target.pendingSwingAt;
                }
                if (seen === null || e.shieldAIRolledFor === seen) return;
                e.shieldAIRolledFor = seen;
                if (Math.random() >= diffSettings[currentDifficulty].blockChance) return;
                setShieldRaised(e, true);
                e.shieldAIHoldUntil = now + HALLOWEEN_SHIELD_AI_HOLD_MS;
            }

            /*  Two layers, because the shield is in two places. Lowered, it is slung
             *  on the back — "the shield goes back" — and painted BEFORE the body so
             *  the body covers most of it. Raised, it is a curved face in front of
             *  the fighter, painted AFTER the body, spanning the middle of the arc it
             *  actually blocks.                                                    */
            function drawHalloweenShield(e, layer) {
                if (!canRaiseShield(e)) return;
                const raised = !!e.shieldRaised;
                if ((layer === 'front') !== raised) return;
                const burnt = HALLOWEEN_BURNT_IDS.has(e.characterId);
                const face = burnt ? '#2a2628' : '#8a5a2b';
                const rim  = burnt ? '#ff3b2f' : '#e8c070';
                const boss = burnt ? '#ff6a3d' : '#ff8c1a';
                const s = bodyScale(e);
                ctx.save();
                ctx.translate(e.x, e.y);
                ctx.rotate(e.lastAimAngle || 0);
                if (raised) {
                    const r = (CHARACTER_SIZE + 7) * s;
                    const half = HALLOWEEN_SHIELD_HALF_ARC * 0.62;
                    ctx.lineCap = 'round';
                    if (burnt) { ctx.shadowBlur = 12; ctx.shadowColor = '#ff2a1a'; }
                    ctx.strokeStyle = rim;
                    ctx.lineWidth = 10 * s;
                    ctx.beginPath(); ctx.arc(0, 0, r, -half, half); ctx.stroke();
                    ctx.shadowBlur = 0;
                    ctx.strokeStyle = face;
                    ctx.lineWidth = 6.5 * s;
                    ctx.beginPath(); ctx.arc(0, 0, r, -half * 0.94, half * 0.94); ctx.stroke();
                    ctx.fillStyle = boss;
                    ctx.beginPath(); ctx.arc(r, 0, 2.6 * s, 0, Math.PI * 2); ctx.fill();
                } else {
                    // Far enough back that a third of it shows past the body.
                    const bx = -CHARACTER_SIZE * 0.95 * s;
                    ctx.fillStyle = face;
                    ctx.strokeStyle = rim;
                    ctx.lineWidth = 2 * s;
                    ctx.beginPath(); ctx.arc(bx, 0, 8 * s, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
                    ctx.fillStyle = boss;
                    ctx.beginPath(); ctx.arc(bx, 0, 1.8 * s, 0, Math.PI * 2); ctx.fill();
                }
                ctx.restore();
            }

            /** The Burnt Skeleton Warriors' red aura. Painted under the body, so it
             *  reads as heat coming off them rather than as a disc laid over them —
             *  the Sith aura's flat fill on top would hide how dark they are, which
             *  is the other half of the look. */
            function drawBurntAura(e) {
                if (!HALLOWEEN_AURA_IDS.has(e.characterId)) return;
                const s = bodyScale(e);
                const pulse = reducedMotion ? 0.5 : 0.5 + 0.5 * Math.sin(Date.now() / 260 + e.x * 0.01);
                const r = (CHARACTER_SIZE + 13 + pulse * 4) * s;
                const g = ctx.createRadialGradient(e.x, e.y, CHARACTER_SIZE * 0.45 * s, e.x, e.y, r);
                g.addColorStop(0, 'rgba(255, 45, 20, 0.62)');
                g.addColorStop(0.55, 'rgba(255, 30, 10, 0.30)');
                g.addColorStop(1, 'rgba(255, 0, 0, 0)');
                ctx.save();
                ctx.fillStyle = g;
                ctx.beginPath(); ctx.arc(e.x, e.y, r, 0, Math.PI * 2); ctx.fill();
                ctx.restore();
            }

            /*  ── HALLOWEEN: THE SUMMONS ─────────────────────────────────────
             *  The four commanders raise skeletons on Q, which their blasters left
             *  with nothing to do. Once a ROUND: the Characters are rebuilt every
             *  round, so `halloweenSummonUsed` resets with them, and a skeleton
             *  raised in round one is not still standing in round two.
             *
             *  The skeletons come up in a ring around whoever raised them and fight
             *  on that side, whoever it is — the player, or the opponent. They do
             *  NOT crumble when their general falls. A round is won when every enemy
             *  is down, so an opposing Wheen's two burnt skeletons are two more
             *  fighters to beat, which is the whole of what makes the summon matter.
             *
             *  Wheen's `callIn` is the 2% asked for: on the same press, once in
             *  fifty, Lord Trick comes up with her skeletons. He arrives as a plain
             *  fighter on her side — shield, Halloween Blaster — but he is not a
             *  main entity, so he cannot raise skeletons of his own. That would turn
             *  a 2% surprise into three more bodies on top of it.                 */
            const HALLOWEEN_SUMMONS = {
                hawlo:     { unitId: 'skeleton',      count: 2 },
                lordtreat: { unitId: 'skeleton',      count: 3 },
                wheen:     { unitId: 'burntskeleton', count: 2, callIn: { id: 'lordtrick', chance: 0.02 } },
                lordtrick: { unitId: 'burntskeleton', count: 3 }
            };
            // How far from the summoner the ring is raised. Clear of the body and
            // close enough that the skeletons read as having come up at his feet.
            const HALLOWEEN_SUMMON_RING = 46;
            // When an AI commander raises his: as soon as he is hurt below 70%, and
            // otherwise somewhere 3 to 7 seconds into the round, so it does not land
            // on the opening frame every time and the player gets a moment first.
            const HALLOWEEN_SUMMON_AI_HEALTH = 0.7;
            const HALLOWEEN_SUMMON_AI_DELAY_MS = 3000;
            const HALLOWEEN_SUMMON_AI_JITTER_MS = 4000;
            let halloweenSummonInputLatched = false;

            function canHalloweenSummon(e) {
                return !!(e && e.isAlive && e.isMainEntity && HALLOWEEN_SUMMONS[e.characterId] && !e.halloweenSummonUsed);
            }

            /** One fighter, raised on the summoner's side. spawnBackupAlly() is the
             *  near miss: it always spawns next to the player and always on the
             *  player's team, and these have to come up next to an AI general on
             *  the enemy's just as well. */
            function spawnSummonedUnit(summoner, data, angle) {
                const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, summoner.x + Math.cos(angle) * HALLOWEEN_SUMMON_RING));
                const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, summoner.y + Math.sin(angle) * HALLOWEEN_SUMMON_RING));
                const ent = new Character(
                    x, y, data.color, data.arenaName || data.name, data.hp, data.weapon,
                    data.saberColor, data.isDroid, data.isWookiee, summoner.team, false,
                    data.isClone, data.weaponDamage, data.id
                );
                ent.tacticalProfileOverride = data.tacticalProfile || null;
                ent.speedMult = data.speedMult || 1;
                // Facing out of the ring, so the first frame does not have every
                // shield on the field pointed east.
                ent.lastAimAngle = angle;
                entities.push(ent);
                spawnBoomBlast(x, y, 40);
                return ent;
            }

            function performHalloweenSummon(e) {
                if (!canHalloweenSummon(e)) return false;
                const def = HALLOWEEN_SUMMONS[e.characterId];
                const unit = findRosterChar(def.unitId);
                if (!unit) return false;
                e.halloweenSummonUsed = true;

                const start = Math.random() * Math.PI * 2;
                for (let i = 0; i < def.count; i++) {
                    spawnSummonedUnit(e, unit, start + (i / def.count) * Math.PI * 2);
                }
                const lord = def.callIn && Math.random() < def.callIn.chance ? findRosterChar(def.callIn.id) : null;
                if (lord) spawnSummonedUnit(e, lord, start + Math.PI / def.count);

                const burnt = HALLOWEEN_BURNT_IDS.has(e.characterId);
                const color = burnt ? '#ff3b2f' : '#ff8c1a';
                const many = (def.count === 3 ? 'Three ' : 'Two ') + unit.name + 's';
                if (lord) {
                    showAnnouncement(`${many} rise for ${e.name} — and ${lord.name} answers the call!`,
                        '#ff3b2f', 4500, '🎃 ' + lord.name.toUpperCase(), 90, true);
                } else {
                    showAnnouncement(`${many} rise for ${e.name}.`, color, 3500, '💀 RISE', 90, true);
                }
                playSound('bluntHit', 120);
                if (e === mainPlayer) matchSpecialsUsed++;
                return true;
            }

            /** The opponent's summon, for the side with no Q to press. Runs once a
             *  frame from updateShapelessTransform(), beside Deadpool's swap. */
            function updateHalloweenSummonAI(e) {
                if (!e || e === mainPlayer || !canHalloweenSummon(e)) return;
                const now = gameNow();
                if (now < e.stunnedUntil || now < e.knockedOutUntil || now < e.chokedUntil) return;
                if (!e.halloweenSummonAIAt) {
                    e.halloweenSummonAIAt = frameNow + HALLOWEEN_SUMMON_AI_DELAY_MS + Math.random() * HALLOWEEN_SUMMON_AI_JITTER_MS;
                }
                const hurt = e.health < e.maxHealth * HALLOWEEN_SUMMON_AI_HEALTH;
                if (!hurt && frameNow < e.halloweenSummonAIAt) return;
                if (!getClosestEnemy(e)) return;
                performHalloweenSummon(e);
            }

            /*  ── HALLOWEEN: THE LORDS ───────────────────────────────────────
             *  Lord Treat is earned by winning five rounds as General Hawlo, and
             *  Lord Trick by five as General Wheen. "Matches" is rounds here for the
             *  same reason it is for the Jedi Hunter: a round is the unit the game
             *  records, in the per-fighter stats this reads.
             *
             *  The grants are written out flag by flag rather than through
             *  gameUnlocks[flag], because validate.js finds a secret's grant by
             *  searching for `gameUnlocks.<flag> = true`. A computed key would pass
             *  every test and still read to it as a fighter nobody can unlock.   */
            const HALLOWEEN_LORD_UNLOCKS = {
                lordtreat: { general: 'hawlo', wins: 5 },
                lordtrick: { general: 'wheen', wins: 5 }
            };

            function checkHalloweenLordUnlocks() {
                if (!pCharData) return;
                const pid = achievementCharId(pCharData);
                const earned = flag => {
                    const rule = HALLOWEEN_LORD_UNLOCKS[flag];
                    return pid === rule.general && !gameUnlocks[flag] && fighterStats(pid).wins >= rule.wins;
                };
                let lord = null;
                if (earned('lordtreat')) { gameUnlocks.lordtreat = true; lord = 'lordtreat'; }
                else if (earned('lordtrick')) { gameUnlocks.lordtrick = true; lord = 'lordtrick'; }
                if (!lord) return;
                persistGalacticUnlocks();
                rebuildAllRosters();
                const data = findRosterChar(lord);
                const rule = HALLOWEEN_LORD_UNLOCKS[lord];
                showAnnouncement(`${rule.wins} wins as ${pCharData.name} have called up their lord. ${data ? data.name : 'A new lord'} has joined your roster.`,
                    lord === 'lordtrick' ? '#ff3b2f' : '#ff8c1a', 6000, '🔓 CHARACTER UNLOCKED', 100);
            }

            /*  ══ THE HALLOWEEN EVENT ═══════════════════════════════════════════
             *  Six rounds against the Burnt Legion with a team of six real roster
             *  fighters: the player and five allies. The order is the owner's —
             *  5 Burnt Skeletons three at a time, 7 four at a time, General Wheen
             *  with 4, the first two again, then Lord Trick with 7. (It opened at
             *  15 / 20 / 10 / 20 and a full team died in round two; the owner cut
             *  rounds one and two to a third and had the rest scaled to match.)
             *
             *  It borrows what the Zero Event left behind (the full-width splash
             *  tile, the first-series lock, the renamed result buttons) and adds two
             *  cards in front of the fight (a warning and the team pick), waves that
             *  refill as skeletons fall, a take-over when the player's fighter dies,
             *  and deaths that stick until the Shop undoes them.
             *
             *  A run lives in halloweenRun and nowhere else: leaving the event, or
             *  the page, throws the run away. Deaths are the one thing written to
             *  the save, and they are written the moment they happen (see
             *  onHalloweenTeamDeath). The fallen store itself is declared up by
             *  gameUnlocks, because isCharacterRetired() reads it during boot.   */
            const HALLOWEEN_EVENT = {
                // Endor: the one arena that reads as woods at night. The event turns
                // the arena hazard off (spawnHazards), so an enemy is the only thing
                // that can kill a team fighter — which is the rule the warning card
                // states.
                arena: 'endor',
                minionId: 'burntskeleton',
                teamSize: 6,
                // `atOnce` is how many skeletons stand on the field at a time; a new
                // one walks in as each falls, until `total` have come. A boss is on
                // the field from the first second and does not count against atOnce.
                rounds: [
                    { total: 5, atOnce: 3 },
                    { total: 7, atOnce: 4 },
                    { boss: 'wheen',     total: 4, atOnce: 3 },
                    { total: 5, atOnce: 3 },
                    { total: 7, atOnce: 4 },
                    { boss: 'lordtrick', total: 7, atOnce: 4 }
                ],
                // Clearing it: 2,500 credits with nobody lost, 350 less per fighter
                // lost, never under 750 — five lost is the most a run can survive.
                reward: { full: 2500, perLoss: 350, min: 750 },
                // Gap between one skeleton falling and the next walking in, so a
                // wave reads as reinforcements arriving rather than respawns.
                spawnGapMs: 450
            };
            // Who the team card offers: Fox and Cody by name, then the Bone Guard
            // column, so a hero added to HALLOWEEN_SEASON turns up here by existing.
            function halloweenPoolIds() { return ['fox', 'cody', ...HALLOWEEN_SEASON.heroes.ids]; }
            // Fighters who may fill more than one slot and are not retired when they
            // fall. The pool has fewer names than the team has slots, so somebody
            // has to be rank and file — and Skeleton Warriors are already dead.
            const HALLOWEEN_EXPENDABLE_IDS = new Set(['skeleton']);

            let halloweenRun = null;        // see startHalloweenRun() for the shape
            let halloweenPrevArena = null;  // the player's own arena pick, put back on leaving
            const halloweenPick = { team: [], lead: 0 };

            const btnHalloween = document.getElementById('btnHalloween');
            const halloweenDisclaimer = document.getElementById('halloweenDisclaimer');
            const halloweenTeamOverlay = document.getElementById('halloweenTeamOverlay');

            function focusHalloweenButton(id) {
                const b = document.getElementById(id);
                if (!b) return;
                // Deferred past showSplashMenu()'s own deferred focus, which would
                // otherwise land on the splash underneath the card a tick later.
                setTimeout(() => { try { b.focus({ preventScroll: true }); } catch (e) { b.focus(); } }, 0);
            }

            /*  ── THE TILE ──────────────────────────────────────────────────────
             *  Locked until the first series win, as the Zero Event's was: a new
             *  player should not be able to lose Fox before playing a match. The
             *  lock is a class and aria-disabled rather than `disabled`, for the
             *  reason snap-intro.js gives — a disabled tile is unreachable by pad. */
            function refreshHalloweenTile() {
                if (!btnHalloween) return;
                const locked = !hasWonSeries;
                btnHalloween.classList.toggle('is-locked', locked);
                btnHalloween.setAttribute('aria-disabled', locked ? 'true' : 'false');
                const tag = document.getElementById('halloweenLockTag');
                if (tag) tag.style.display = locked ? '' : 'none';
            }
            if (btnHalloween) {
                btnHalloween.addEventListener('click', () => {
                    if (!hasWonSeries) return;
                    openHalloweenDisclaimer();
                });
            }

            /*  ── CARD 1: THE WARNING ───────────────────────────────────────────
             *  Shown every time, not once: the risk is permanent, so the reminder
             *  is too. Acknowledge goes on to the team card; Back goes nowhere.  */
            function openHalloweenDisclaimer() {
                if (!halloweenDisclaimer) return;
                halloweenDisclaimer.style.display = 'flex';
                focusHalloweenButton('halloweenAckBtn');
            }
            function closeHalloweenDisclaimer() {
                if (halloweenDisclaimer) halloweenDisclaimer.style.display = 'none';
            }
            const halloweenAckBtn = document.getElementById('halloweenAckBtn');
            if (halloweenAckBtn) halloweenAckBtn.addEventListener('click', () => { closeHalloweenDisclaimer(); openHalloweenTeamCard(); });
            const halloweenDisclaimerBackBtn = document.getElementById('halloweenDisclaimerBackBtn');
            if (halloweenDisclaimerBackBtn) halloweenDisclaimerBackBtn.addEventListener('click', () => { closeHalloweenDisclaimer(); setTimeout(() => focusFirstVisibleButton(splashMenu), 0); });

            /*  ── CARD 2: THE TEAM ──────────────────────────────────────────────
             *  Six slots. Tapping a pool tile fills the next one; tapping a named
             *  fighter's tile again takes them off, while a Skeleton Warrior tile
             *  adds another skeleton each tap. Each slot can be tapped to make that
             *  fighter the one the player controls ("Play as"), or crossed off.
             *  Start waits for a full team. Fallen and locked fighters are shown
             *  greyed with the reason, so the player can see who they are missing.*/
            function halloweenPoolChars() {
                return halloweenPoolIds().map(findRosterChar).filter(Boolean);
            }
            function openHalloweenTeamCard() {
                if (!halloweenTeamOverlay) return;
                halloweenPick.team = [];
                halloweenPick.lead = 0;
                renderHalloweenTeamCard();
                halloweenTeamOverlay.style.display = 'flex';
                const firstTile = halloweenTeamOverlay.querySelector('.hw-tile:not(:disabled)');
                if (firstTile) setTimeout(() => { try { firstTile.focus({ preventScroll: true }); } catch (e) { firstTile.focus(); } }, 0);
            }
            function closeHalloweenTeamCard() {
                if (halloweenTeamOverlay) halloweenTeamOverlay.style.display = 'none';
            }
            function renderHalloweenTeamCard() {
                const pool = document.getElementById('halloweenPool');
                const slots = document.getElementById('halloweenSlots');
                const count = document.getElementById('halloweenTeamCount');
                const startBtn = document.getElementById('halloweenStartBtn');
                if (!pool || !slots) return;
                const team = halloweenPick.team;
                const size = HALLOWEEN_EVENT.teamSize;
                if (halloweenPick.lead >= team.length) halloweenPick.lead = 0;

                pool.replaceChildren();
                halloweenPoolChars().forEach(char => {
                    const tile = document.createElement('button');
                    tile.type = 'button';
                    tile.className = 'hw-tile';
                    tile.dataset.character = char.id;
                    tile.style.borderLeftColor = char.color;
                    const picked = team.filter(id => id === char.id).length;
                    const expendable = HALLOWEEN_EXPENDABLE_IDS.has(char.id);
                    const fallen = isHalloweenFallen(char.id);
                    const locked = !isCharacterUnlocked(char);
                    let sub;
                    if (fallen) sub = 'Fallen · buy back in the Shop';
                    else if (locked) sub = 'Locked';
                    else if (expendable) sub = `${char.hp} HP · ${getWeapon(char).label} · can fill several slots`;
                    else sub = `${char.hp} HP · ${getWeapon(char).label}`;
                    tile.innerHTML = `<span class="hw-tile-name">${rosterWeaponEmoji(char)} ${char.name}</span><span class="hw-tile-sub">${sub}</span>`;
                    if (picked) {
                        tile.classList.add('is-picked');
                        if (expendable) {
                            const n = document.createElement('span');
                            n.className = 'hw-tile-count';
                            n.textContent = `×${picked}`;
                            tile.appendChild(n);
                        }
                    }
                    if (fallen || locked) {
                        tile.disabled = true;
                        tile.classList.add('is-fallen');
                    } else {
                        tile.addEventListener('click', () => {
                            if (picked && !expendable) {
                                const at = team.indexOf(char.id);
                                team.splice(at, 1);
                                if (halloweenPick.lead > at) halloweenPick.lead--;
                            } else if (team.length < size) {
                                team.push(char.id);
                            }
                            renderHalloweenTeamCard();
                        });
                    }
                    pool.appendChild(tile);
                });

                slots.replaceChildren();
                for (let i = 0; i < size; i++) {
                    const slot = document.createElement('div');
                    slot.className = 'hw-slot';
                    const id = team[i];
                    const char = id ? findRosterChar(id) : null;
                    if (!char) {
                        slot.textContent = `Slot ${i + 1}`;
                        slots.appendChild(slot);
                        continue;
                    }
                    slot.classList.add('is-filled');
                    slot.style.borderLeftColor = char.color;
                    const isLead = i === halloweenPick.lead;
                    if (isLead) slot.classList.add('is-lead');
                    const main = document.createElement('button');
                    main.type = 'button';
                    main.className = 'hw-slot-main';
                    main.title = isLead ? 'You play as this fighter' : 'Play as this fighter';
                    main.innerHTML = `<span>${char.name}</span><span class="hw-slot-lead">${isLead ? '▶ Play as' : 'Ally'}</span>`;
                    main.addEventListener('click', () => { halloweenPick.lead = i; renderHalloweenTeamCard(); });
                    const remove = document.createElement('button');
                    remove.type = 'button';
                    remove.className = 'hw-slot-remove';
                    remove.title = 'Remove from the team';
                    remove.setAttribute('aria-label', `Remove ${char.name}`);
                    remove.textContent = '✕';
                    remove.addEventListener('click', () => {
                        team.splice(i, 1);
                        if (halloweenPick.lead > i) halloweenPick.lead--;
                        renderHalloweenTeamCard();
                    });
                    slot.appendChild(main);
                    slot.appendChild(remove);
                    slots.appendChild(slot);
                }

                if (count) count.textContent = `Team ${team.length}/${size}`;
                if (startBtn) startBtn.disabled = team.length < size;
            }
            const halloweenStartBtn = document.getElementById('halloweenStartBtn');
            if (halloweenStartBtn) halloweenStartBtn.addEventListener('click', () => {
                if (halloweenPick.team.length < HALLOWEEN_EVENT.teamSize) return;
                startHalloweenRun();
            });
            const halloweenTeamBackBtn = document.getElementById('halloweenTeamBackBtn');
            if (halloweenTeamBackBtn) halloweenTeamBackBtn.addEventListener('click', () => { closeHalloweenTeamCard(); openHalloweenDisclaimer(); });

            /*  ── THE RUN ───────────────────────────────────────────────────────
             *  halloweenRun = {
             *      round: 0..5,                 index into HALLOWEEN_EVENT.rounds
             *      team:  [{ id, hp, alive }],  hp null = full; carried between rounds
             *      lead:  slot index the player is controlling
             *      lost:  team fighters killed so far (sets the reward)
             *      over:  true once the run has ended either way
             *      wave:  the live round, see setupHalloweenRound()
             *  }                                                                  */
            function startHalloweenRun() {
                closeHalloweenTeamCard();
                halloweenRun = {
                    round: 0,
                    team: halloweenPick.team.map(id => ({ id, hp: null, alive: true })),
                    lead: halloweenPick.lead,
                    lost: 0,
                    over: false,
                    cleared: false,
                    wave: null
                };
                if (halloweenPrevArena == null) halloweenPrevArena = currentArena;
                // The result and pause buttons are shared with every other fight.
                // endGame() restores these from BORROWED_BTN_DEFAULTS; the event's
                // own round end re-applies them each time.
                const pauseQuit = document.getElementById('pauseQuitBtn');
                if (pauseQuit) pauseQuit.textContent = '✕ Abandon the Run';
                splashMenu.style.display = 'none';
                setupHalloweenRound();
            }

            /** Put everything the event changed back. Safe to call when no run is
             *  on: Return to Base and the pause menu's Quit call it unconditionally. */
            function leaveHalloweenEvent() {
                const wasOn = !!halloweenRun || halloweenPrevArena != null;
                halloweenRun = null;
                if (halloweenPrevArena != null) {
                    currentArena = halloweenPrevArena;
                    halloweenPrevArena = null;
                }
                if (!wasOn) return false;
                resetBorrowedButtonLabels();
                const summary = document.getElementById('halloweenTeamSummary');
                if (summary) summary.style.display = 'none';
                // A fighter who fell this run is off every roster from here on.
                rebuildAllRosters();
                updateSecretFactionSectionVisibility();
                refreshSplashState();
                return true;
            }

            function describeHalloweenRound(def) {
                const skel = `${def.total} Burnt Skeleton Warriors`;
                if (def.boss) {
                    const boss = findRosterChar(def.boss);
                    return `${boss ? boss.name : def.boss} with ${skel}`;
                }
                return `${skel}, ${def.atOnce} at a time`;
            }

            /** Build one round on top of setupGame(). setupGame stands up the lead
             *  and one opponent and nothing else, so the board is rebuilt around
             *  them here: the allies beside the player, the boss (if any) kept, and
             *  the first wave of skeletons walked in on the far side. All of it is
             *  synchronous, so the 3-2-1 countdown already draws the full board. */
            function setupHalloweenRound() {
                const run = halloweenRun;
                if (!run) return;
                const def = HALLOWEEN_EVENT.rounds[run.round];
                const lead = run.team[run.lead];
                currentArena = HALLOWEEN_EVENT.arena;
                setupGame(lead.id, def.boss || HALLOWEEN_EVENT.minionId, { halloween: true });

                mainPlayer.halloweenSlot = run.lead;
                if (lead.hp != null) mainPlayer.health = Math.max(1, Math.min(mainPlayer.maxHealth, lead.hp));

                // Allies stand in a loose arc on the player's side of the field.
                const arc = [[-70, -95], [-70, 95], [-135, -35], [-135, 35], [-40, -165], [-40, 165]];
                const allies = [];
                run.team.forEach((slot, i) => {
                    if (i === run.lead || !slot.alive) return;
                    const data = findRosterChar(slot.id);
                    if (!data) return;
                    const [dx, dy] = arc[allies.length % arc.length];
                    const m = CHARACTER_SIZE * 2;
                    const x = Math.max(m, Math.min(canvasLogicalW - m, mainPlayer.x + dx));
                    const y = Math.max(m, Math.min(canvasLogicalH - m, mainPlayer.y + dy));
                    const ent = new Character(x, y, data.color, data.arenaName || data.name, data.hp, data.weapon,
                        data.saberColor, data.isDroid, data.isWookiee, 'player', false, data.isClone, data.weaponDamage, data.id);
                    ent.tacticalProfileOverride = data.tacticalProfile || null;
                    ent.speedMult = data.speedMult || 1;
                    ent.halloweenSlot = i;
                    if (slot.hp != null) ent.health = Math.max(1, Math.min(ent.maxHealth, slot.hp));
                    allies.push(ent);
                });

                const wave = { total: def.total, atOnce: def.atOnce, spawned: 0, nextSpawnAt: 0, boss: null };
                run.wave = wave;
                entities = [mainPlayer, ...allies];
                if (def.boss) {
                    // setupGame's opponent IS the boss, with the difficulty's health
                    // multiplier already on it. The owner's rule: a boss in the event
                    // cannot call backup — the skeletons walking in are its backup.
                    mainEnemy.halloweenSummonUsed = true;
                    wave.boss = mainEnemy;
                    entities.push(mainEnemy);
                } else {
                    // The opponent setupGame built is dropped: in a wave round every
                    // skeleton is rank and file, and mainEnemy is simply whichever one
                    // is standing (updateHalloweenWave keeps it pointed at a live one).
                    mainEnemy = null;
                }
                while (wave.spawned < wave.total && halloweenMinionsAlive() < wave.atOnce) spawnHalloweenMinion(true);
                if (!def.boss) setHalloweenWaveHud();

                showAnnouncement(describeHalloweenRound(def), '#ff8c1a', 5000,
                    `🎃 ROUND ${run.round + 1} OF ${HALLOWEEN_EVENT.rounds.length}`, 100, true);
            }

            function halloweenMinionsAlive() {
                let n = 0;
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (e.isAlive && e.halloweenMinion) n++;
                }
                return n;
            }
            function halloweenWaveHasMore() {
                return !!(halloweenRun && halloweenRun.wave && halloweenRun.wave.spawned < halloweenRun.wave.total);
            }

            /** Somewhere on the far third of the field, clear of cover and at least
             *  150px from every living team fighter, so a skeleton never appears on
             *  top of someone. Falls back to the right edge if the field is full. */
            function halloweenSpawnPoint() {
                const w = canvasLogicalW, h = canvasLogicalH, m = CHARACTER_SIZE * 2;
                for (let t = 0; t < 14; t++) {
                    const x = w * 0.66 + Math.random() * (w * 0.34 - m);
                    const y = m + Math.random() * (h - 2 * m);
                    let bad = false;
                    for (const c of coverObjects) {
                        if (c.alive && Math.abs(x - c.x) < c.w / 2 + CHARACTER_SIZE * 1.5 && Math.abs(y - c.y) < c.h / 2 + CHARACTER_SIZE * 1.5) { bad = true; break; }
                    }
                    if (!bad) {
                        for (const e of entities) {
                            if (e.isAlive && e.team === 'player' && Math.hypot(e.x - x, e.y - y) < 150) { bad = true; break; }
                        }
                    }
                    if (!bad) return { x, y };
                }
                return { x: w - m, y: h / 2 };
            }

            function spawnHalloweenMinion(initial) {
                const run = halloweenRun;
                const data = findRosterChar(HALLOWEEN_EVENT.minionId);
                if (!run || !run.wave || !data) return null;
                const p = halloweenSpawnPoint();
                // Raw roster health, like every other spawned unit: the difficulty's
                // hpMult is for the one opponent setupGame builds, and a wave of
                // skeletons at 1.45x would be a different event on Legend.
                const ent = new Character(p.x, p.y, data.color, data.arenaName || data.name, data.hp, data.weapon,
                    data.saberColor, data.isDroid, data.isWookiee, 'enemy', false, data.isClone, data.weaponDamage, data.id);
                ent.tacticalProfileOverride = data.tacticalProfile || null;
                ent.speedMult = data.speedMult || 1;
                ent.halloweenMinion = true;
                ent.lastShotTime = frameNow + Math.random() * 400;
                entities.push(ent);
                run.wave.spawned++;
                if (!run.wave.boss && (!mainEnemy || !mainEnemy.isAlive)) mainEnemy = ent;
                if (!initial) spawnBoomBlast(ent.x, ent.y, 40);
                return ent;
            }

            /** Per frame, from gameLoop: refill the field as skeletons fall, and in
             *  a wave round keep mainEnemy pointed at a living one, since the HUD,
             *  the sprite race and a few other places read it directly. */
            function updateHalloweenWave() {
                const run = halloweenRun;
                if (!run || !run.wave) return;
                const wave = run.wave;
                if (!wave.boss && (!mainEnemy || !mainEnemy.isAlive)) {
                    for (let i = 0; i < entities.length; i++) {
                        const e = entities[i];
                        if (e.isAlive && e.halloweenMinion) { mainEnemy = e; break; }
                    }
                }
                if (wave.spawned >= wave.total) return;
                if (halloweenMinionsAlive() >= wave.atOnce) { wave.nextSpawnAt = 0; return; }
                if (!wave.nextSpawnAt) { wave.nextSpawnAt = frameNow + HALLOWEEN_EVENT.spawnGapMs; return; }
                if (frameNow < wave.nextSpawnAt) return;
                spawnHalloweenMinion(false);
                wave.nextSpawnAt = 0;
            }

            /** The enemy panel in a wave round: there is no single opponent, so the
             *  card is the Legion itself and the bar is how much of the wave is
             *  left (updateHUD draws that part). */
            function setHalloweenWaveHud() {
                const data = findRosterChar(HALLOWEEN_EVENT.minionId);
                if (!data || !mainEnemy) return;
                setEnemyHud(data, mainEnemy);
                enemyLabel.textContent = 'THE BURNT LEGION';
                const portrait = document.getElementById('enemyPortrait');
                if (portrait) portrait.textContent = '💀';
            }
            function halloweenWaveLeft() {
                const wave = halloweenRun && halloweenRun.wave;
                if (!wave) return 0;
                return wave.total - wave.spawned + halloweenMinionsAlive();
            }

            /*  ── DEATHS ────────────────────────────────────────────────────────
             *  Called from Character.updateHealth the moment a team fighter's health
             *  reaches zero. A named fighter is written to the save right here, so
             *  quitting the fight — or the page — cannot undo it. Rosters are
             *  rebuilt when the fight is over (endHalloweenRound), not mid-frame. */
            function onHalloweenTeamDeath(ent) {
                const run = halloweenRun;
                if (!run || ent.halloweenSlot == null) return;
                const slot = run.team[ent.halloweenSlot];
                if (!slot || !slot.alive) return;
                slot.alive = false;
                slot.hp = 0;
                run.lost++;
                const expendable = HALLOWEEN_EXPENDABLE_IDS.has(slot.id);
                if (!expendable) {
                    halloweenFallen[slot.id] = true;
                    persistHalloweenFallen();
                }
                showAnnouncement(expendable
                    ? `${ent.name} has fallen. Skeletons do not stay down for good — this one is out for the run.`
                    : `${ent.name} has fallen, and stays fallen until bought back in the Shop.`,
                    '#ff3b2f', 4500, '💀 FALLEN', 100, true);
            }

            /** The player's fighter is dead: hand them the healthiest living
             *  teammate. Returns false when there is nobody left, which is the run
             *  ending. The old body keeps its slot (it is dead, and stays counted). */
            function halloweenTakeOver() {
                const run = halloweenRun;
                if (!run) return false;
                let best = null;
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (e.isAlive && e.team === 'player' && e.halloweenSlot != null && (!best || e.health > best.health)) best = e;
                }
                if (!best) return false;
                const fallen = mainPlayer;
                fallen.isMainEntity = false;
                best.isMainEntity = true;
                // An AI body may have its shield up or a swing in flight; the player's
                // first frame of input takes over from here, so only the grip has to
                // be let go — the input branch holds it only while Interact is held.
                best.shieldRaised = false;
                mainPlayer = best;
                run.lead = best.halloweenSlot;
                pCharData = findRosterChar(best.characterId) || pCharData;
                syncPlayerHudCard();
                showAnnouncement(`${fallen.name} is down. You fight on as ${best.name}.`, '#ff8c1a', 4000, '🎃 TAKE OVER', 100, true);
                return true;
            }

            /*  ── ROUND END ─────────────────────────────────────────────────────
             *  Takes endGame's place for an event round: no series, no match
             *  history, no mastery, no achievements — a wave of skeletons is not a
             *  duel and should not count as thirty of them. It shares the results
             *  overlay, with its buttons renamed the way the Zero Event's were. */
            function endHalloweenRound(playerWon) {
                const run = halloweenRun;
                if (!run) return;
                const rounds = HALLOWEEN_EVENT.rounds;
                const def = rounds[run.round];
                stopBattleSystems();

                // Bank the team: health for the living, and a death the hook missed
                // (there should be none) for anyone else.
                for (const e of entities) {
                    if (e.team !== 'player' || e.halloweenSlot == null) continue;
                    const slot = run.team[e.halloweenSlot];
                    if (!slot) continue;
                    if (e.isAlive) slot.hp = e.health;
                    else if (slot.alive) onHalloweenTeamDeath(e);
                }

                resetBorrowedButtonLabels();
                const nextRoundBtn = document.getElementById('nextRoundButton');
                const rematchBtn   = document.getElementById('rematchButton');
                const restartBtn   = document.getElementById('restartButton');
                const seriesDisplay = document.getElementById('seriesScoreDisplay');
                const pauseQuit = document.getElementById('pauseQuitBtn');
                if (pauseQuit) pauseQuit.textContent = '✕ Abandon the Run';
                const last = run.round === rounds.length - 1;
                let title, color, sub, healed = false;

                if (playerWon) {
                    if (def.boss) {
                        // Everyone still standing heals fully after a boss: the three
                        // rounds before it are one stage, and the next three another.
                        run.team.forEach(s => { if (s.alive) s.hp = null; });
                        healed = true;
                    }
                    if (last) {
                        run.over = true;
                        run.cleared = true;
                        const pay = Math.max(HALLOWEEN_EVENT.reward.min,
                            HALLOWEEN_EVENT.reward.full - HALLOWEEN_EVENT.reward.perLoss * run.lost);
                        const gained = awardCredits(pay);
                        saveGameSettings();
                        title = '★ THE BURNT LEGION IS BROKEN ★';
                        color = '#ff8c1a';
                        sub = `EVENT CLEARED · ${run.lost} LOST · +${gained} CREDITS`;
                        nextRoundBtn.style.display = 'none';
                        rematchBtn.style.display = 'inline-block';
                        rematchBtn.textContent = '🎃 Run It Again';
                        restartBtn.textContent = 'Return to Base';
                        spawnVictoryConfetti();
                    } else {
                        run.round++;
                        title = `ROUND ${run.round} CLEARED`;
                        color = '#ff8c1a';
                        sub = `NEXT · ROUND ${run.round + 1} OF ${rounds.length} · ${describeHalloweenRound(rounds[run.round]).toUpperCase()}`;
                        nextRoundBtn.style.display = 'inline-block';
                        nextRoundBtn.textContent = 'Continue ▶';
                        rematchBtn.style.display = 'none';
                        restartBtn.textContent = 'Quit the Event';
                    }
                } else {
                    run.over = true;
                    title = 'THE TEAM HAS FALLEN';
                    color = '#ff3b2f';
                    sub = `THE RUN ENDS IN ROUND ${run.round + 1} OF ${rounds.length}`;
                    nextRoundBtn.style.display = 'none';
                    rematchBtn.style.display = 'inline-block';
                    rematchBtn.textContent = '🎃 Try Again';
                    restartBtn.textContent = 'Quit the Event';
                }

                messageText.textContent = title;
                messageText.style.color = color;
                messageText.style.textShadow = `0 0 15px ${color}`;
                document.querySelector('.message-box').style.borderColor = color;
                seriesDisplay.textContent = sub;
                seriesDisplay.style.display = 'block';

                // The team, one line each: who is standing and on how much.
                const summary = document.getElementById('halloweenTeamSummary');
                if (summary) {
                    summary.replaceChildren();
                    run.team.forEach(slot => {
                        const data = findRosterChar(slot.id);
                        const row = document.createElement('div');
                        row.className = 'hw-summary-row' + (slot.alive ? '' : ' is-fallen');
                        row.style.borderLeftColor = data ? data.color : '#888';
                        const hp = slot.alive ? (slot.hp == null ? (data ? data.hp : 0) : Math.max(1, Math.round(slot.hp))) : 0;
                        row.innerHTML = `<span class="hw-summary-name">${data ? data.name : slot.id}</span>`
                            + `<span class="hw-summary-hp">${slot.alive ? (healed ? `${hp} HP · HEALED` : `${hp} HP`) : 'FALLEN'}</span>`;
                        summary.appendChild(row);
                    });
                    summary.style.display = 'grid';
                }

                const elapsed = Math.round((gameNow() - gameStartTime) / 1000);
                const endTimeEl = document.getElementById('endTime');
                const endKillsEl = document.getElementById('endKills');
                const endHPEl = document.getElementById('endHP');
                if (endTimeEl) { endTimeEl.textContent = `${Math.floor(elapsed / 60)}:${(elapsed % 60).toString().padStart(2, '0')}`; endTimeEl.style.color = color; }
                if (endKillsEl) { endKillsEl.textContent = killCount; endKillsEl.style.color = color; }
                if (endHPEl) { endHPEl.textContent = mainPlayer && mainPlayer.isAlive ? Math.max(0, Math.round(mainPlayer.health * 10) / 10) : 0; endHPEl.style.color = color; }
                const accPct = playerShotsFired > 0 ? Math.min(100, Math.round((playerHitsLanded / playerShotsFired) * 100)) : 0;
                const endDamageEl = document.getElementById('endDamage');
                const endHitsEl = document.getElementById('endHits');
                const endAccuracyEl = document.getElementById('endAccuracy');
                if (endDamageEl) { endDamageEl.textContent = playerDamageDealt; endDamageEl.style.color = color; }
                if (endHitsEl) { endHitsEl.textContent = playerHitsLanded; endHitsEl.style.color = color; }
                if (endAccuracyEl) { endAccuracyEl.textContent = playerShotsFired > 0 ? accPct + '%' : '—'; endAccuracyEl.style.color = color; }

                // Anyone who fell this round is off the rosters from here, so the
                // Shop and the team card both tell the truth the moment they open.
                rebuildAllRosters();
                updateSecretFactionSectionVisibility();

                flushAnnouncementQueue();
                messageOverlay.style.display = 'flex';
                updateMobileControlsVisibility();
                setTimeout(() => focusFirstVisibleButton(messageOverlay), 0);
            }

            /*  What the Interact button should say about itself. */
            function hasInteractAbility(e) {
                return canForceChoke(e) || canUnibeam(e) || canWebGrenade(e)
                    || canFlameBlast(e) || canZeroShock(e) || canGodBlast(e) || canShapeshift(e)
                    || canHulkSmash(e) || canClobberin(e) || canIronMonger(e)
                    || canInfinitySnap(e) || canEternitySummon(e) || canAntManResize(e)
                    || canWeaponSwap(e) || canRaiseShield(e);
            }

            function interactAbilityReady(e) {
                if (!e) return false;
                // Choke reads gameNow() directly; the rest run on frameNow (stamped from it).
                if (canForceChoke(e)) return gameNow() >= (e.forceChokeReadyAt || 0);
                if (canUnibeam(e))    return frameNow >= (e.unibeamReadyAt || 0);
                if (canWebGrenade(e)) return frameNow >= (e.webGrenadeReadyAt || 0);
                if (canFlameBlast(e)) return frameNow >= (e.flameBlastReadyAt || 0);
                if (canZeroShock(e))  return frameNow >= (e.zeroShockReadyAt || 0);
                if (canGodBlast(e))   return frameNow >= (e.godBlastReadyAt || 0);
                if (canShapeshift(e)) return frameNow >= (e.shapeshiftReadyAt || 0);
                // Always ready: it can only ever be used once, and canIronMonger()
                // stops being true afterwards.
                if (canIronMonger(e)) return true;
                // Below the transform on purpose. Banner shares one key between the
                // two, and while he is still Banner the button belongs to the change
                // — canIronMonger() answers first and canHulkSmash() is false anyway.
                if (canHulkSmash(e))  return frameNow >= (e.hulkSmashReadyAt || 0);
                if (canClobberin(e))  return frameNow >= (e.clobberinReadyAt || 0);
                if (canInfinitySnap(e)) return frameNow >= infinitySnapReadyAt(e);
                // No clock. Ready whenever the last ally is down.
                if (canEternitySummon(e)) return !eternitySummonActive(e);
                // E shrinks him, and does nothing while he is already small.
                if (canAntManResize(e)) return e.antForm !== 'small';
                if (canWeaponSwap(e)) return weaponSwapReady(e);
                return true;
            }

            /*  ── HULK SMASH ─────────────────────────────────────────────────
             *  Same shape as the dash above, and deliberately so — a timed self-buff
             *  is a timed self-buff, and there is nothing to gain by inventing a
             *  second way of expressing one. `isMainEntity` gates it to the player,
             *  which is the rule every Interact special in the season follows: an AI
             *  Hulk swings the fists and does not smash.                            */
            function canHulkSmash(e) {
                // `ironMongerForm` is the gate, same as canPoisonSpit's: Banner with
                // the gun still in his hand has nothing to smash with.
                return !!(e && e.isAlive && e.isMainEntity && e.ironMongerForm
                          && HULK_SMASH_IDS.has(e.characterId));
            }

            function isHulkSmashing(e) {
                return !!(e && e.hulkSmashUntil && frameNow < e.hulkSmashUntil);
            }

            /** The damage side of the smash, asked at the moment a hit resolves
             *  rather than at the moment it was thrown. For a 900ms swing that
             *  distinction is real: a punch wound up inside the window and landing
             *  after it should not still be a smash punch. */
            function hulkSmashDamageMult(e) {
                return isHulkSmashing(e) ? HULK_SMASH_DAMAGE : 1;
            }

            function startHulkSmash(e) {
                // Whatever he was moving at before the window, captured only on the
                // way in so re-smashing mid-smash cannot record the smash speed as
                // the base one. Same trap Spin Dash documents above.
                if (!e.hulkSmashActive) e.hulkSmashBaseSpeed = e.speedMult || 1;
                e.hulkSmashUntil = frameNow + HULK_SMASH_DURATION;
                e.hulkSmashReadyAt = frameNow + HULK_SMASH_COOLDOWN;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('bluntHit');
                spawnBoomBlast(e.x, e.y, 52);
                return true;
            }

            /** Holds the speed up for the duration and puts it back afterwards.
             *  Only ever touches what the smash itself set — clearing speedMult
             *  unconditionally would stamp on whatever else had a claim on it. */
            function updateHulkSmash(e) {
                if (!e || !e.isAlive) return;
                if (!isHulkSmashing(e)) {
                    if (e.hulkSmashActive) {
                        e.hulkSmashActive = false;
                        e.speedMult = e.hulkSmashBaseSpeed != null ? e.hulkSmashBaseSpeed : 1;
                    }
                    return;
                }
                e.hulkSmashActive = true;
                e.speedMult = (e.hulkSmashBaseSpeed != null ? e.hulkSmashBaseSpeed : 1) * HULK_SMASH_SPEED;
            }

            /** Gamma green, drawn under the fighter like the dash so it reads as
             *  something he is doing rather than something stuck to him. It pulses
             *  rather than spins: he is not travelling, he is winding up. */
            function drawHulkSmash(e) {
                if (!isHulkSmashing(e)) return;
                const left = (e.hulkSmashUntil - frameNow) / HULK_SMASH_DURATION;
                const pulse = 1 + Math.sin(frameNow * 0.02) * 0.08;
                ctx.save();
                ctx.translate(e.x, e.y);
                ctx.globalAlpha = 0.28 + 0.22 * left;
                ctx.strokeStyle = '#8cff6b';
                ctx.lineWidth = 3;
                ctx.shadowBlur = 18;
                ctx.shadowColor = '#8cff6b';
                for (let i = 0; i < 2; i++) {
                    ctx.beginPath();
                    ctx.arc(0, 0, (CHARACTER_SIZE * 1.7 + i * 7) * pulse, 0, Math.PI * 2);
                    ctx.stroke();
                }
                ctx.restore();
            }

            function canClobberin(e) {
                return !!(e && e.isAlive && e.isMainEntity && CLOBBERIN_IDS.has(e.characterId));
            }

            function isClobberin(e) {
                return !!(e && e.clobberinUntil && frameNow < e.clobberinUntil);
            }

            /*  No updateClobberin(), and that is not an omission. Hulk Smash and
             *  Spin Dash both have to hold `speedMult` up for their duration and
             *  put it back afterwards, which needs a per-frame hand on it. This
             *  one changes nothing that persists: both of its effects are read
             *  live off isClobberin() at the moment they matter — the cooldown in
             *  meleeSwingCooldown(), the movement in swingMoveScale() — so when
             *  the window lapses there is nothing left over to restore.          */
            function startClobberin(e) {
                e.clobberinUntil = frameNow + CLOBBERIN_DURATION;
                e.clobberinReadyAt = frameNow + CLOBBERIN_COOLDOWN;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('bluntHit');
                spawnBoomBlast(e.x, e.y, 48);
                return true;
            }

            function canInfinitySnap(e) {
                return !!(e && e.isAlive && e.isMainEntity && SNAP_IDS.has(e.characterId));
            }

            /** When the Gauntlet is next charged. Set lazily, on the first frame
             *  anything asks, rather than in the Character constructor, because
             *  frameNow is only advanced by the running loop. At construction
             *  time it can still be the last frame of the previous match, and a
             *  charge measured from then would be ready the moment the round
             *  opened. Characters are rebuilt every round, so this empties it
             *  again every round with nothing else to reset. */
            function infinitySnapReadyAt(e) {
                if (e.infinitySnapReadyAt == null) e.infinitySnapReadyAt = frameNow + SNAP_COOLDOWN;
                return e.infinitySnapReadyAt;
            }

            /** Blow a fighter away as dust. The death burst that updateHealth()
             *  draws is still underneath it. This is the drift that makes it read
             *  as the Snap rather than as an ordinary kill: slower, longer-lived,
             *  and in ash as well as their own colour. */
            function spawnSnapDust(target) {
                const ash = ['#8a7a66', '#6e6255', '#b3a38c', target.color];
                for (let k = 0; k < 28 && deathParticles.length < MAX_DEATH_PARTICLES; k++) {
                    // Blown mostly one way, the way the dust leaves the tile in
                    // the intro, with enough scatter to not look like a jet.
                    const a = -Math.PI * 0.15 + (Math.random() - 0.5) * 1.6;
                    const sp = Math.random() * 3.2 + 0.8;
                    deathParticles.push({
                        x: target.x + (Math.random() - 0.5) * CHARACTER_SIZE,
                        y: target.y + (Math.random() - 0.5) * CHARACTER_SIZE,
                        dx: Math.cos(a) * sp, dy: Math.sin(a) * sp - 0.6,
                        life: 70, maxLife: 70,
                        color: ash[k % ash.length], r: Math.random() * 2.4 + 1
                    });
                }
            }

            function performInfinitySnap(e) {
                e.infinitySnapReadyAt = frameNow + SNAP_COOLDOWN;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('neckSnap', 200);
                triggerScreenShake(6, 16);
                spawnBoomBlast(e.x, e.y, 60);

                let dusted = 0, spared = 0, resisted = 0;
                // A plain index loop over a snapshot: a kill can call backup
                // clones into flight and rewrite state on other entities, and the
                // roll must be over the enemies who were standing when he snapped.
                const standing = entities.filter(o => o.isAlive && o.team !== e.team && !o.isFrozen);
                for (let i = 0; i < standing.length; i++) {
                    const other = standing[i];
                    if (!other.isAlive) continue;
                    if (other === mainPlayer && invincibilityEnabled) { spared++; continue; }
                    const gone = Math.random() < SNAP_KILL_CHANCE;
                    if (gone && isSnapBoss(other) && other.health > other.maxHealth * SNAP_BOSS_SHARE) {
                        const dmg = Math.round(other.maxHealth * SNAP_BOSS_SHARE);
                        if (floatNums.length < MAX_FLOATS) {
                            floatNums.push({
                                x: other.x, y: other.y - CHARACTER_SIZE - 12,
                                text: '-' + dmg, life: 60, maxLife: 60, dy: -0.9,
                                color: '#e3b341', glow: '#e3b341'
                            });
                        }
                        if (e.team === 'player' && other.team === 'enemy') playerDamageDealt += dmg;
                        other.updateHealth(dmg);
                        resisted++;
                        continue;
                    }
                    if (floatNums.length < MAX_FLOATS) {
                        floatNums.push({
                            x: other.x, y: other.y - CHARACTER_SIZE - 12,
                            text: gone ? 'DUST' : 'SPARED', life: 60, maxLife: 60, dy: -0.9,
                            color: gone ? '#e3b341' : '#cfd6e0', glow: gone ? '#e3b341' : '#8a93a0'
                        });
                    }
                    if (!gone) { spared++; continue; }
                    dusted++;
                    // Whatever they had left, credited like a Neck Snap's.
                    if (e.team === 'player' && other.team === 'enemy') {
                        playerDamageDealt += Math.round(other.health);
                    }
                    spawnSnapDust(other);
                    other.updateHealth(other.health);
                }

                // forceShow: mid-battle, so it must not queue for the results
                // screen (see deferAnnouncements in setupGame).
                if (dusted || spared || resisted) {
                    showAnnouncement(dusted ? (spared || resisted ? 'Half of them are dust.' : 'Perfectly balanced.')
                                            : resisted ? 'Too strong to dust. The Gauntlet still hurt.'
                                            : 'The Gauntlet spared them. This time.',
                                     dusted ? '#e3b341' : '#cfd6e0', 2400, '🫰 THE SNAP', 70, true);
                }
                return true;
            }

            function canEternitySummon(e) {
                return !!(e && e.isAlive && e.isMainEntity && ETERNITY_IDS.has(e.characterId));
            }

            /** Is the fighter she last called still in the fight? Checked against
             *  `entities` as well as isAlive, so an ally left over from some other
             *  list can never hold the slot. */
            function eternitySummonActive(e) {
                const ally = e && e.eternitySummon;
                return !!(ally && ally.isAlive && entities.includes(ally));
            }

            /** Both Marvel columns, filtered the way the Fury Sprite's pool is. */
            function eternitySummonPool(caller) {
                const season = marvelSeason();
                return [...season.heroes.ids, ...season.villains.ids]
                    .filter(id => !ETERNITY_IDS.has(id) && id !== (caller && caller.characterId))
                    .map(findRosterChar)
                    .filter(c => c && !isCharacterRetired(c) && isCharacterUnlocked(c));
            }

            function performEternitySummon(e) {
                if (eternitySummonActive(e)) return false;
                const pool = eternitySummonPool(e);
                if (!pool.length) {
                    showAnnouncement('Nobody in either column can answer her.', '#6f86ff', 3000, '♾️ ETERNITY', 90, true);
                    return false;
                }
                const data = pool[Math.floor(Math.random() * pool.length)];
                e.eternitySummon = spawnBackupAlly(data,
                    `${data.name} is pulled out of reality to fight beside her.`, '#6f86ff', '♾️ ETERNITY');
                if (e === mainPlayer) matchSpecialsUsed++;
                return true;
            }

            /*  ── ANT-MAN ────────────────────────────────────────────────────
             *  Two specials on two keys, the only fighter with more than one:
             *  Q (the throw key, idle for fists) grows him, E shrinks him. Each
             *  lasts ANT_FORM_MS and then he is normal size again.
             *
             *  Pressing the key for the form he is already in does nothing, and
             *  pressing the other one switches straight across with a fresh 15
             *  seconds. Each form also has its own cooldown, ANT_FORM_COOLDOWN
             *  counted from when its 15 seconds would run out. With no cooldown,
             *  tapping Q again the moment Giant-Man ended kept 1.5x damage and
             *  double reach up permanently (balance review #10); now he is giant
             *  at most 15 seconds in every 25, and the same for small.
             *
             *  What each form is for:
             *    GIANT  twice the size, so twice the reach and twice the target,
             *           punches worth half as much again, and a slower walk.
             *    SMALL  half the size: bolts meant for a normal body sail past,
             *           he is quicker, and the reach shrinks with him. Damage is
             *           unchanged; being hard to hit is the whole of it.
             *
             *  Size is `sizeMult`, read by bodyScale() at the hit test, the swing
             *  reach and the sprite. Speed is held up and put back the way Hulk
             *  Smash does it, touching only what the form itself set.
             *
             *  Player-only, the season's rule for every special.               */
            const ANT_MAN_IDS = new Set(['antman']);
            const ANT_FORM_MS = 15000;
            const ANT_FORM_COOLDOWN = 10000;    // ms after a form's window before it can be entered again
            const ANT_MAN_FORMS = {
                giant: { size: 2.0, speed: 0.8,  damage: 1.5, label: 'GIANT-MAN', color: '#ff7a66' },
                small: { size: 0.5, speed: 1.35, damage: 1,   label: 'ANT-MAN',   color: '#ffb3a6' }
            };
            let antGrowInputLatched = false;
            let antShrinkInputLatched = false;

            function canAntManResize(e) {
                return !!(e && e.isAlive && e.isMainEntity && ANT_MAN_IDS.has(e.characterId));
            }

            function antFormDamageMult(e) {
                const f = e && e.antForm && ANT_MAN_FORMS[e.antForm];
                return f ? f.damage : 1;
            }

            function startAntForm(e, form) {
                if (e.antForm === form) return false;
                if (!e.antFormReadyAt) e.antFormReadyAt = {};
                if (frameNow < (e.antFormReadyAt[form] || 0)) return false;
                // Captured on the way in only, so switching straight from one form
                // to the other cannot record the first form's speed as his own.
                if (!e.antForm) e.antBaseSpeed = e.speedMult || 1;
                const f = ANT_MAN_FORMS[form];
                e.antForm = form;
                e.antFormUntil = frameNow + ANT_FORM_MS;
                e.antFormReadyAt[form] = e.antFormUntil + ANT_FORM_COOLDOWN;
                e.sizeMult = f.size;
                e.speedMult = e.antBaseSpeed * f.speed;
                if (e === mainPlayer) matchSpecialsUsed++;
                playSound('dash');
                spawnBoomBlast(e.x, e.y, form === 'giant' ? 70 : 30);
                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({ x: e.x, y: e.y - bodyRadius(e) - 12, text: f.label,
                                     life: 50, maxLife: 50, dy: -0.9, color: f.color, glow: f.color });
                }
                return true;
            }

            function endAntForm(e) {
                if (!e || !e.antForm) return;
                e.antForm = null;
                e.antFormUntil = 0;
                e.sizeMult = 1;
                e.speedMult = e.antBaseSpeed != null ? e.antBaseSpeed : 1;
                if (e.isAlive) spawnBoomBlast(e.x, e.y, 40);
            }

            /*  THE ANTS. Jabba's spawning, moved onto Ant-Man: one every
             *  ANT_SPAWN_MS, placed 110–160px from him, and never more than
             *  ANT_MAX_ALIVE of his standing at once (spawnPlayableGamorreanGuard
             *  is the model). Jabba also stops after six and loses the round,
             *  because he cannot fight; Ant-Man can, so the ants keep coming for
             *  as long as he is standing.
             *
             *  Automatic, so it runs for an AI Ant-Man too: the ants are his, not
             *  the player's. Only for a principal (isMainEntity), so an Ant-Man
             *  summoned as backup does not bring a colony along.
             *
             *  When he falls, his ants scatter. They are marked fled rather than
             *  killed: the round waits for every enemy that has not fled, so ants
             *  left standing would keep the round going after him, and fled ants
             *  do not count as kills.                                           */
            const ANT_SPAWN_MS = 2200;
            const ANT_MAX_ALIVE = 6;
            // 40, not 10. At 10 every ant died to the first hit it walked into:
            // against Venom six of them in a row reached him, were clawed once,
            // and landed nothing. 40 survives one ordinary hit, which is enough
            // for an ant to get its 2s in before it goes.
            const ANT_HP = 40;
            const ANT_SIZE = 0.35;

            function spawnAnt(owner) {
                const angle = Math.random() * Math.PI * 2;
                const dist = 110 + Math.random() * 50;
                const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, owner.x + Math.cos(angle) * dist));
                const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, owner.y + Math.sin(angle) * dist));
                const ant = new Character(x, y, '#8a2a1f', 'Ant', ANT_HP, 'antbite', '#8a2a1f',
                                          false, false, owner.team, false, false, undefined, 'ant');
                ant.sizeMult = ANT_SIZE;
                ant.antOwner = owner;
                ant.tacticalProfileOverride = 'brawler';
                entities.push(ant);
                spawnBoomBlast(x, y, 14);
            }

            function updateAntColony(owner) {
                if (!owner.isAlive) {
                    if (owner.antsScattered) return;
                    owner.antsScattered = true;
                    for (const ant of entities) {
                        if (ant.antOwner !== owner || !ant.isAlive) continue;
                        ant.isAlive = false;
                        ant.hasFled = true;
                        spawnHitSparks(ant.x, ant.y, '#8a2a1f', 4);
                    }
                    return;
                }
                // Lazily, for the reason infinitySnapReadyAt gives: frameNow at
                // construction can still be the last match's.
                if (owner.antNextSpawnAt == null) owner.antNextSpawnAt = frameNow + ANT_SPAWN_MS;
                if (frameNow < owner.antNextSpawnAt) return;
                owner.antNextSpawnAt = frameNow + ANT_SPAWN_MS;
                let alive = 0;
                for (const ant of entities) if (ant.antOwner === owner && ant.isAlive) alive++;
                if (alive < ANT_MAX_ALIVE) spawnAnt(owner);
            }

            /** Once a frame: form expiry for anyone in a form, and the colony for
             *  every principal Ant-Man. Runs ahead of the canAct gate, so a form
             *  ends on time even while he is stunned. */
            function updateAntMan() {
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (e.antForm && (frameNow >= e.antFormUntil || !e.isAlive)) endAntForm(e);
                    if (e.isMainEntity && ANT_MAN_IDS.has(e.characterId)) updateAntColony(e);
                }
            }

            /** Gold charge arc under his feet, the same shape as Vader's choke
             *  arc and for the same reason: nothing on the HUD shows a special's
             *  cooldown, and a 25-second one with no read on it is a button the
             *  player gives up pressing. */
            function drawInfinitySnapCharge(e) {
                const remain = Math.max(0, infinitySnapReadyAt(e) - frameNow);
                const frac = 1 - remain / SNAP_COOLDOWN;
                const r = CHARACTER_SIZE + 9;
                const start = Math.PI * 0.25;
                const sweep = Math.PI * 0.5;

                ctx.save();
                ctx.lineWidth = 2.5;
                ctx.lineCap = 'round';
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.beginPath();
                ctx.arc(e.x, e.y, r, start, start + sweep);
                ctx.stroke();

                if (frac > 0) {
                    const ready = remain <= 0;
                    ctx.strokeStyle = ready ? 'rgba(227,179,65,0.95)' : 'rgba(227,179,65,0.5)';
                    if (ready) { ctx.shadowBlur = 10; ctx.shadowColor = '#e3b341'; }
                    ctx.beginPath();
                    ctx.arc(e.x, e.y, r, start, start + sweep * Math.min(1, frac));
                    ctx.stroke();
                }
                ctx.restore();
            }

            /** Rock orange, drawn under the fighter like the smash it is paired
             *  with. Two counter-rotating arcs rather than Hulk's concentric
             *  pulse: his window is a fighter winding up, this one is a fighter
             *  already swinging, and the ring should say which. */
            function drawClobberin(e) {
                if (!isClobberin(e)) return;
                const left = (e.clobberinUntil - frameNow) / CLOBBERIN_DURATION;
                const spin = frameNow * 0.011;
                ctx.save();
                ctx.translate(e.x, e.y);
                ctx.globalAlpha = 0.30 + 0.24 * left;
                ctx.strokeStyle = '#ffb066';
                ctx.lineWidth = 3;
                ctx.shadowBlur = 18;
                ctx.shadowColor = '#ffb066';
                const r = CHARACTER_SIZE * 1.7;
                for (let i = 0; i < 2; i++) {
                    const dir = i ? -1 : 1;
                    const from = spin * dir + i * Math.PI;
                    ctx.beginPath();
                    ctx.arc(0, 0, r + i * 7, from, from + Math.PI * 1.15);
                    ctx.stroke();
                }
                ctx.restore();
            }

            /** Can this entity choke at all? Any Vader, on either side of the
             *  fight.
             *
             *  It used to require isMainEntity, so the choke existed only while a
             *  player was driving him: every Vader the game has ever put in front of
             *  someone stood there with the Force and used it to shoot. The two
             *  places that draw the cooldown ring and light the Interact button
             *  check isMainEntity themselves, so they are unaffected. */
            function canForceChoke(e) {
                return !!(e && e.isAlive && FORCE_CHOKE_IDS.has(e.characterId));
            }

            /** Nearest living opponent inside choke range, or null. */
            function findForceChokeTarget(caster) {
                let best = null;
                let bestDist = FORCE_CHOKE_RANGE;
                for (let i = 0; i < entities.length; i++) {
                    const other = entities[i];
                    if (!other.isAlive || other.team === caster.team) continue;
                    // Carbonite Han is a set piece, not a fighter — nothing in
                    // there to grip.
                    if (other.isFrozen) continue;
                    // A dodge in progress slips the grip, the way it slips every
                    // hit. The choke used to ignore i-frames entirely, so the one
                    // defensive button a player has did nothing against it. Skipped
                    // here rather than refused in startForceChoke() so nothing is
                    // cast and no cooldown is spent: a player whose target rolled
                    // can press again the moment the roll ends, and an AI Vader
                    // simply rolls for it again on his next tick.
                    if (isInvulnerable(other, gameNow())) continue;
                    const d = Math.hypot(other.x - caster.x, other.y - caster.y);
                    if (d < bestDist) { bestDist = d; best = other; }
                }
                return best;
            }

            function startForceChoke(caster, target) {
                const now = gameNow();
                caster.forceChokeReadyAt = now + FORCE_CHOKE_COOLDOWN;

                // Never shorten an existing hold — take whichever runs longer.
                target.stunnedUntil = Math.max(target.stunnedUntil, now + FORCE_CHOKE_DURATION);
                target.wasStunned = true;
                target.chokedUntil = now + FORCE_CHOKE_DURATION;
                target.chokedBy = caster;
                // Whether an AI caster may finish this grip with the snap, decided
                // once here — see AI_NECK_SNAP_CHANCE. A player-driven Vader never
                // reads it: he snaps when the key is pressed.
                target.chokeSnapAllowed = caster === mainPlayer || Math.random() < AI_NECK_SNAP_CHANCE;
                // Total damage is fixed at cast time so a pickup or chip damage
                // partway through cannot inflate or deflate what the choke owes.
                target.chokeDamageRemaining = target.maxHealth * FORCE_CHOKE_HP_FRACTION;
                target.chokeMsRemaining = FORCE_CHOKE_DURATION;
                target.chokeCredit = 0;
                target.chokeTickAccum = 0;
                target.chokeNextTickAt = now + FORCE_CHOKE_TICK_MS;
                // Held off the floor, not shoved across it — drop any momentum
                // the victim was carrying.
                target.vx = 0;
                target.vy = 0;

                playSound('forceChoke', 200);
                spawnHitSparks(target.x, target.y, '#ff2200', 10);
                triggerScreenShake(3, 8);
            }

            // ── NECK SNAP ──────────────────────────────────────────────
            // The finisher on the end of a choke. It is never selected directly:
            // it becomes available only while a choke is actually holding someone
            // who is at or below NECK_SNAP_HP_FRACTION, and it dies with the grip.
            //
            // Checked live rather than latched at cast time, so a choke that drags
            // the target under the threshold with its own damage arms the snap
            // mid-hold. Latching at cast would mean choking someone at 55%, watching
            // them bleed to 40%, and being told no — which reads as a bug.
            const NECK_SNAP_HP_FRACTION = 0.5;

            /** The entity `caster` could snap right now, or null. */
            function findNeckSnapTarget(caster) {
                if (!canForceChoke(caster)) return null;
                const now = gameNow();
                for (let i = 0; i < entities.length; i++) {
                    const e = entities[i];
                    if (!e.isAlive || e.chokedBy !== caster) continue;
                    if (now >= e.chokedUntil) continue;
                    if (e.health > e.maxHealth * NECK_SNAP_HP_FRACTION) continue;
                    return e;
                }
                return null;
            }

            function performNeckSnap(caster, target) {
                const remaining = target.health;

                // Release the grip first so the choke's own damage-over-two-seconds
                // cannot keep ticking into a corpse, then take the rest in one go.
                target.chokedUntil = 0;
                target.chokedBy = null;
                target.chokeDamageRemaining = 0;
                target.chokeMsRemaining = 0;
                target.chokeTickAccum = 0;
                target.stunnedUntil = 0;

                if (caster.team === 'player' && target.team === 'enemy') {
                    playerDamageDealt += Math.round(remaining);
                }
                target.updateHealth(remaining);

                playSound('neckSnap', 200);
                spawnHitSparks(target.x, target.y, '#ffffff', 18);
                triggerScreenShake(7, 14);
                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: target.x, y: target.y - CHARACTER_SIZE - 12,
                        text: 'KRK!', life: 55, maxLife: 55, dy: -1.0
                    });
                }

                // The achievement is the snap, the victim and the place — all three.
                if (caster.team === 'player'
                    && achievementCharId(eCharData) === 'fox'
                    && target.isMainEntity
                    && currentArena === 'coruscant') {
                    // immediate: this fires mid-fight, like comboMaster — it should
                    // land on the snap rather than queue behind the round banners.
                    tryUnlockAchievement('snap', true);
                }
            }

            // ── BURNING ────────────────────────────────────────────────────
            // The flamethrower's damage over time. Most of the weapon's output
            // used to land on contact; now the flame sets its target alight and
            // the fire finishes the job after the trigger is released.
            //
            // The duration REFRESHES rather than stacking, which is the whole
            // reason this is safe: the flamethrower puts out three projectiles
            // every 70ms — about 43 hits a second — and anything that stacked
            // per hit would multiply into an instant kill. Sustained fire
            // therefore keeps a target permanently alight but never burns it
            // faster than one tick per BURN_TICK_MS; the fire's real value is
            // the damage that keeps landing once you stop shooting or lose
            // sight of them.
            //
            // Droids burn like everyone else. Zap's stun and the wrench's
            // knockdown both exempt them, but neither of those is heat.
            /*  ── POISON ────────────────────────────────────────────────────────
             *  The Abomination's, and its own ticker rather than the burn with a green
             *  coat of paint. The two are meant to feel different and the numbers are
             *  where that lives: fire is 6 every 400ms for 3 seconds (45 total, fast
             *  and frightening), poison is 5 every 500ms for 5 seconds (50 total,
             *  slower and harder to outrun). A shared system with two configs would
             *  have been the same amount of code and would have made them one idea.
             *
             *  Structured exactly like the burn otherwise — same three fields on the
             *  entity, same refresh rule that stops a second application front-loading
             *  a tick, same team credit, same float. tickPoison() is called from the
             *  same place tickBurn() is, above the canAct gate, because a stunned
             *  target is still poisoned.                                             */
            // The three constants this section is built on are declared far above,
            // next to POISON_SPIT_CONFIG, and NOT here where they read most naturally.
            // POISON_SPIT_CONFIG is a `const` initialised around line 16300 and it
            // needs the duration; a `const` declared down here is in its temporal dead
            // zone at that moment, so reading it threw a ReferenceError that aborted
            // the whole DOMContentLoaded handler and booted to a blank screen. The
            // functions below are function declarations and hoist, so only the
            // constants had to move.
            function applyPoison(target, source) {
                if (!target || !target.isAlive) return;
                if (target === mainPlayer && invincibilityEnabled) return;
                const now = gameNow();
                if (now >= target.poisonedUntil) target.poisonNextTickAt = now + POISON_TICK_MS;
                target.poisonedUntil = now + POISON_DURATION_MS;
                target.poisonFromTeam = source && source.team;
            }

            function tickPoison(e) {
                if (!e.poisonedUntil) return;
                const now = gameNow();
                if (!e.isAlive || now >= e.poisonedUntil) {
                    e.poisonedUntil = 0;
                    e.poisonNextTickAt = 0;
                    e.poisonFromTeam = null;
                    return;
                }
                if (now < e.poisonNextTickAt) return;
                e.poisonNextTickAt = now + POISON_TICK_MS;

                const fromTeam = e.poisonFromTeam;
                e.updateHealth(POISON_TICK_DAMAGE);
                if (fromTeam === 'player' && e.team === 'enemy') {
                    playerDamageDealt += POISON_TICK_DAMAGE;
                }
                if (e.team === 'player' && e.isMainEntity) playerTookDamage = true;

                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: e.x + (Math.random() - 0.5) * 16,
                        y: e.y - CHARACTER_SIZE - 6,
                        text: POISON_TICK_DAMAGE, life: 38, maxLife: 38, dy: -1.0,
                        color: '#8fe04a'
                    });
                }
                spawnHitSparks(e.x, e.y, '#7fc23a', 4);
            }

            const BURN_DURATION_MS = 3000;
            const BURN_TICK_MS = 400;
            const BURN_TICK_DAMAGE = 6;

            /** Set (or refresh) a target alight. */
            function igniteBurn(target, source) {
                if (!target || !target.isAlive) return;
                if (target === mainPlayer && invincibilityEnabled) return;
                const now = gameNow();
                // First application schedules the opening tick; a refresh leaves
                // the existing cadence alone so re-igniting cannot front-load a
                // tick on every one of those 43 hits a second.
                if (now >= target.burningUntil) target.burnNextTickAt = now + BURN_TICK_MS;
                target.burningUntil = now + BURN_DURATION_MS;
                target.burnFromTeam = source && source.team;
            }

            /** Bleed one tick of a live burn.
             *
             *  Called for every entity from update() BEFORE the `canAct` gate, for
             *  the same reason tickForceChoke() is: a stunned or knocked-down
             *  target is still on fire, and anything behind that gate would stop
             *  burning the moment it was staggered. */
            function tickBurn(e) {
                if (!e.burningUntil) return;

                const now = gameNow();
                if (!e.isAlive || now >= e.burningUntil) {
                    e.burningUntil = 0;
                    e.burnNextTickAt = 0;
                    e.burnFromTeam = null;
                    return;
                }
                if (now < e.burnNextTickAt) return;
                e.burnNextTickAt = now + BURN_TICK_MS;

                const fromTeam = e.burnFromTeam;
                e.updateHealth(BURN_TICK_DAMAGE);

                // Credited like any other damage the player dealt. Accuracy is
                // deliberately untouched — the burn is not a shot, and counting
                // it would report over 100%, the same rule the choke follows.
                if (fromTeam === 'player' && e.team === 'enemy') {
                    playerDamageDealt += BURN_TICK_DAMAGE;
                }
                if (e.team === 'player' && e.isMainEntity) playerTookDamage = true;

                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: e.x + (Math.random() - 0.5) * 16,
                        y: e.y - CHARACTER_SIZE - 6,
                        text: BURN_TICK_DAMAGE, life: 38, maxLife: 38, dy: -1.0,
                        color: '#ff8c2b'
                    });
                }
                spawnHitSparks(e.x, e.y, '#ff7722', 4);
            }

            /** Bleed one frame of a live choke.
             *
             *  Called for every entity from update() BEFORE the `canAct` gate, and
             *  it has to stay there: the victim is stunned by definition, so
             *  anything living behind that gate would never tick. */
            function tickForceChoke(e, tickScale) {
                if (!e.chokedUntil) return;

                const now = gameNow();
                if (!e.isAlive || now >= e.chokedUntil || e.chokeMsRemaining <= 0) {
                    if (e.chokeTickAccum >= 1) emitChokeNumber(e);
                    e.chokedUntil = 0;
                    e.chokedBy = null;
                    e.chokeDamageRemaining = 0;
                    e.chokeMsRemaining = 0;
                    e.chokeCredit = 0;
                    e.chokeTickAccum = 0;
                    return;
                }

                // Spread what is left over the time that is left. Framed as a
                // proportion rather than a fixed per-ms rate so the last frame
                // always clears the remainder exactly, whatever the frame times.
                const stepMs = Math.min(e.chokeMsRemaining, 16.7 * tickScale);
                const dmg = e.chokeDamageRemaining * (stepMs / e.chokeMsRemaining);
                e.chokeMsRemaining -= stepMs;
                e.chokeDamageRemaining -= dmg;

                const chokedBy = e.chokedBy;
                e.updateHealth(dmg);

                // Credit the damage-dealt stat in whole points — the per-frame
                // slice rounds to zero on its own, so it is banked until it is
                // worth a point. Accuracy is deliberately untouched: a choke is
                // not a shot, and counting it would report over 100%.
                if (chokedBy && chokedBy.team === 'player' && e.team === 'enemy') {
                    e.chokeCredit += dmg;
                    const whole = Math.floor(e.chokeCredit);
                    if (whole > 0) {
                        playerDamageDealt += whole;
                        e.chokeCredit -= whole;
                    }
                }

                // One floating number every FORCE_CHOKE_TICK_MS rather than one a
                // frame, which would be an unreadable smear of tiny numbers.
                e.chokeTickAccum += dmg;
                if (now >= e.chokeNextTickAt) {
                    emitChokeNumber(e);
                    e.chokeNextTickAt = now + FORCE_CHOKE_TICK_MS;
                }
            }

            function emitChokeNumber(e) {
                const shown = Math.round(e.chokeTickAccum);
                e.chokeTickAccum = 0;
                if (shown <= 0) return;
                if (floatNums.length < MAX_FLOATS) {
                    floatNums.push({
                        x: e.x + (Math.random() - 0.5) * 20,
                        y: e.y - CHARACTER_SIZE - 10,
                        text: shown, life: 45, maxLife: 45, dy: -1.2
                    });
                }
            }

            /** The grip itself: a tendril from Vader's hand and a ring closing on
             *  the victim's throat. Drawn from Character.draw. */
            function drawForceChoke(target) {
                const now = gameNow();
                const remain = Math.max(0, target.chokedUntil - now);
                const t = 1 - remain / FORCE_CHOKE_DURATION; // 0 at the grab, 1 as it releases

                ctx.save();

                const src = target.chokedBy;
                if (src && src.isAlive) {
                    // The line wavers as it tightens — a straight cable reads as a
                    // laser, not a grip. Reduced motion gets the straight version.
                    const segments = reducedMotion ? 1 : 5;
                    const jitter = reducedMotion ? 0 : 4 * (1 - t);
                    ctx.strokeStyle = `rgba(255,45,45,${(0.6 - t * 0.3).toFixed(3)})`;
                    ctx.lineWidth = 2;
                    ctx.shadowBlur = 10;
                    ctx.shadowColor = '#ff2200';
                    ctx.beginPath();
                    ctx.moveTo(src.x, src.y);
                    for (let i = 1; i <= segments; i++) {
                        const f = i / segments;
                        const jx = i === segments ? 0 : (Math.random() - 0.5) * jitter * 2;
                        const jy = i === segments ? 0 : (Math.random() - 0.5) * jitter * 2;
                        ctx.lineTo(src.x + (target.x - src.x) * f + jx, src.y + (target.y - src.y) * f + jy);
                    }
                    ctx.stroke();
                }

                // Ring constricting toward the body over the hold.
                const ringR = CHARACTER_SIZE + 13 - t * 9;
                ctx.strokeStyle = `rgba(255,60,40,${(0.85 - t * 0.35).toFixed(3)})`;
                ctx.lineWidth = 2.5;
                ctx.shadowBlur = 14;
                ctx.shadowColor = '#ff2200';
                ctx.beginPath();
                ctx.arc(target.x, target.y, ringR, 0, Math.PI * 2);
                ctx.stroke();

                ctx.restore();
            }

            /** Cooldown arc under a player-controlled Vader: a full red ring means
             *  the choke is ready, a partial one shows it recharging. */
            function drawForceChokeCooldown(e) {
                const now = gameNow();
                const remain = Math.max(0, (e.forceChokeReadyAt || 0) - now);
                const frac = remain > 0 ? 1 - remain / FORCE_CHOKE_COOLDOWN : 1;
                const r = CHARACTER_SIZE + 9;
                const start = Math.PI * 0.25;
                const sweep = Math.PI * 0.5;

                ctx.save();
                ctx.lineWidth = 2.5;
                ctx.lineCap = 'round';
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.beginPath();
                ctx.arc(e.x, e.y, r, start, start + sweep);
                ctx.stroke();

                if (frac > 0) {
                    const ready = frac >= 1;
                    ctx.strokeStyle = ready ? 'rgba(255,60,40,0.9)' : 'rgba(255,60,40,0.5)';
                    if (ready) { ctx.shadowBlur = 8; ctx.shadowColor = '#ff2200'; }
                    ctx.beginPath();
                    ctx.arc(e.x, e.y, r, start, start + sweep * frac);
                    ctx.stroke();
                }
                ctx.restore();
            }

            function update(tickScale) {
                // Update visual effects
                updateScreenShake(tickScale);
                updateHitSparks(tickScale);
                updateImpactParticles(tickScale);
                updateBoomBlasts(tickScale);
                updateSaberTrails(tickScale);
                updateDodgeFlashes(tickScale);
                updateMeleeSwings(tickScale);
                updateLowHealthVignette();
                updateForceLightningLoop();
                updateFlamethrowerLoop();
                updateZeroSpriteBackup();
                updateFurySpriteBackup();
                updateShapelessTransform();
                for (const e of entities) if (e.hulkSmashUntil) updateHulkSmash(e);
                updateAntMan();
                for (const e of entities) if (e.zeroShockUntil) updateZeroShock(e);
                for (const e of entities) if (e.shapeshiftFrom) updateShapeshift(e);
                updateAiForceChoke();

                let aliveEntities = collectAlive(aliveScratch);

                aliveEntities.forEach(e => {
                    if (e.isClone && e.isMainEntity && e.health <= (e.maxHealth - 25) && !e.hasCalledBackup) {
                        const baseId = resolveCloneBaseId(e.characterId);
                        const isLeader = cloneBackupLeaders.has(baseId);
                        const backupInfo = cloneBackupUnit(baseId);

                        // Set even when nobody answers, so a clone with no battalion
                        // on record is not re-checked on every remaining frame.
                        e.hasCalledBackup = true;

                        if (backupInfo) {
                            // Commanders get the full battalion, captains one fewer,
                            // regular clones whoever they can round up (1-4).
                            const troopCount = isLeader
                                ? battalionSize(baseId)
                                : Math.floor(Math.random() * 4) + 1;

                            // The squad wears its battalion's colours rather than the
                            // colours of whoever called it, which is what makes it read
                            // as a unit arriving instead of as copies of one fighter.
                            // Matches what the dev menu's Call for Backup already did.
                            const unitDef = characters.heroes.find(c => c.id === backupInfo.unitId);
                            const squadColor = unitDef ? unitDef.color : e.color;

                            for(let i = 0; i < troopCount; i++) {
                                let offsetX = (Math.random() - 0.5) * 80;
                                let offsetY = (Math.random() - 0.5) * 80;

                                // Backup troopers are standard rank-and-file — they always carry
                                // blasters, even if the commander calling them in (e.g. Commander
                                // Thorn) wields a special weapon like a minigun.
                                const backupWeaponConfig = WEAPON_LIBRARY.blaster;
                                let backupDamage = backupWeaponConfig.damage * 0.5;
                                let backup = new Character(
                                    e.x + offsetX,
                                    e.y + offsetY,
                                    squadColor,
                                    backupInfo.name,
                                    50,
                                    'blaster',
                                    null,
                                    false,
                                    false,
                                    e.team,
                                    false,
                                    true,
                                    backupDamage
                                );
                                backup.health = 50;
                                backup.characterId = backupInfo.unitId;
                                backup.hasCalledBackup = true;
                                backup.lastShotTime = frameNow - Math.random() * 500;
                                entities.push(backup);
                            }
                        }
                    }

                    // Jedi Generals: when badly hurt, call in their clone commander
                    // in person, plus two rank-and-file troopers of the battalion.
                    if (!e.isClone && e.isMainEntity && jediBackupLeaders.has(e.characterId) && e.health <= (e.maxHealth - 25) && !e.hasCalledBackup) {
                        e.hasCalledBackup = true;
                        const commanderId = jediBackupArmy[e.characterId];
                        const troopInfo = cloneBackupArmy[commanderId];
                        const commanderDef = characters.heroes.find(c => c.id === commanderId);

                        // Two rank-and-file troopers of the battalion
                        for (let i = 0; i < 2; i++) {
                            let offsetX = (Math.random() - 0.5) * 80;
                            let offsetY = (Math.random() - 0.5) * 80;
                            const backupWeaponConfig = WEAPON_LIBRARY.blaster;
                            let backupDamage = backupWeaponConfig.damage * 0.5;
                            let trooper = new Character(
                                e.x + offsetX,
                                e.y + offsetY,
                                commanderDef ? commanderDef.color : e.color,
                                troopInfo ? troopInfo.name : 'Clone Trooper',
                                50,
                                'blaster',
                                null,
                                false,
                                false,
                                e.team,
                                false,
                                true,
                                backupDamage
                            );
                            trooper.health = 50;
                            trooper.characterId = troopInfo ? troopInfo.unitId : e.characterId;
                            trooper.hasCalledBackup = true;
                            trooper.lastShotTime = frameNow - Math.random() * 500;
                            entities.push(trooper);
                        }

                        // The commander arrives in person, tougher than a rank-and-file trooper
                        if (commanderDef) {
                            let cOffsetX = (Math.random() - 0.5) * 60;
                            let cOffsetY = (Math.random() - 0.5) * 60;
                            const commanderDamage = WEAPON_LIBRARY.blaster.damage * 0.75;
                            let commander = new Character(
                                e.x + cOffsetX,
                                e.y + cOffsetY,
                                commanderDef.color,
                                commanderDef.name,
                                90,
                                'blaster',
                                null,
                                false,
                                false,
                                e.team,
                                false,
                                true,
                                commanderDamage
                            );
                            commander.health = 90;
                            commander.characterId = commanderDef.id;
                            commander.hasCalledBackup = true;
                            commander.lastShotTime = frameNow - Math.random() * 500;
                            entities.push(commander);

                            // Troops are landing on the field right now — this has to
                            // be on screen as they arrive, like the player-triggered
                            // backup calls, not replayed after the match.
                            showAnnouncement(`${commanderDef.name} and the ${troopInfo ? troopInfo.name + 's' : 'troopers'} move in, General!`, '#00cfff', 3500, '📡 BACKUP CALLED', 50, true);
                        }
                    }

                    // Droid repair crew: below 35% health, a droid calls in Anzellan
                    // techs to hover around it, patch it up, and shield it from harm.
                    if (e.isDroid && e.isMainEntity && e.health <= e.maxHealth * 0.35 && !e.hasCalledAnzellans) {
                        e.hasCalledAnzellans = true;
                        spawnAnzellanEscorts(e);
                    }
                });

                // Re-collect: the sweep above can spawn backup squads and Anzellan
                // escorts, which must act on the same frame they appear.
                aliveEntities = collectAlive(aliveScratch);

                // Committed swings land here, ahead of the action loop below. A cut
                // whose windup has elapsed must resolve whatever its owner is doing
                // this frame — including being in recovery and taking no action at
                // all — so it cannot live inside the per-entity branch that returns
                // early for stunned or non-acting entities.
                resolvePendingSwings(aliveEntities);

                aliveEntities.forEach(e => {
                    const now = frameNow;

                    // Both must run ahead of the canAct gate below — a choked
                    // entity is stunned by definition, and a burning one is still
                    // burning while staggered. Everything past that gate is
                    // skipped for an entity that cannot act.
                    tickForceChoke(e, tickScale);
                    tickBurn(e);
                    tickPoison(e);
                    // Ahead of the canAct gate on purpose: hands keep working
                    // through a stagger, so a reload already under way finishes
                    // even while its owner is stunned, choked or knocked down.
                    tickReload(e, now);

                    if (now > e.stunnedUntil && e.wasStunned) {
                        e.wasStunned = false;
                        e.zapImmunityUntil = now + 1000;
                    }
                    if (now > e.knockedOutUntil && e.wasKnockedOut) {
                        e.wasKnockedOut = false;
                        e.wrenchImmunityUntil = now + 3000; 
                    }

                    const canAct = now > e.stunnedUntil && now > e.knockedOutUntil;
                    if (!canAct) {
                        // Being zapped, knocked down or choked drops the blade
                        // mid-swing. Without this the cut still lands out of a body
                        // that is currently being electrocuted, and the stun stops
                        // being a real interrupt.
                        cancelMeleeSwing(e);
                        // A stun knocks a held shield down with the blade — the
                        // hold is a grip, and a choked fighter has none.
                        e.shieldRaised = false;
                        return;
                    }

                    if (e.isMainEntity && e.team === 'player') {
                        let moveX = 0, moveY = 0;
                        if (keys['ArrowLeft'] || keys[keyBindings.left]) moveX -= 1;
                        if (keys['ArrowRight'] || keys[keyBindings.right]) moveX += 1;
                        if (keys['ArrowUp'] || keys[keyBindings.up]) moveY -= 1;
                        if (keys['ArrowDown'] || keys[keyBindings.down]) moveY += 1;

                        if (touchMove.active) {
                            moveX = touchMove.x;
                            moveY = touchMove.y;
                        }
                        if (padState.active) {
                            moveX = padState.moveX;
                            moveY = padState.moveY;
                        }

                        // Every player action is readable from all three input methods:
                        // keyboard, the on-screen touch buttons, and a gamepad.
                        // `keys` is keyed by normalized name, so the lower-case
                        // entry is the only one that can ever be set — the paired
                        // upper-case checks these used to carry were the other
                        // half of the stuck-key bug and are now unreachable.
                        const interactHeld = !!(keys[keyBindings.interact] || touchInteract || padState.interact);
                        const dodgeHeld    = !!(keys[keyBindings.dodge] || touchDodge || padState.dodge);
                        const reloadHeld   = !!(keys[keyBindings.reload] || touchReload || padState.reload);
                        const throwHeld    = !!(keys[keyBindings.throw] || touchThrow || padState.throwBlade || mouseThrow);
                        // The Abomination spits instead of throwing. Checked before the
                        // melee branch below rather than inside it, because his fists
                        // are noThrow and would never reach a throw case at all.
                        if (canPoisonSpit(e)) {
                            if (throwHeld && !poisonSpitInputLatched
                                && frameNow >= (e.poisonSpitReadyAt || 0)) {
                                startPoisonSpit(e);
                            }
                            poisonSpitInputLatched = throwHeld;
                        } else {
                            poisonSpitInputLatched = false;
                        }

                        // Ant-Man grows on Q. His fists are noThrow, so the key had
                        // nothing else to do for him. Edge-triggered like every
                        // special; startAntForm() refuses a form he is already in.
                        if (canAntManResize(e)) {
                            if (throwHeld && !antGrowInputLatched) startAntForm(e, 'giant');
                            antGrowInputLatched = throwHeld;
                        } else {
                            antGrowInputLatched = false;
                        }

                        // Force Choke (E / ✋ / Y) — Vader only, and edge-triggered:
                        // one press is one choke, so leaning on the key through the
                        // cooldown does not re-cast the instant it comes back up.
                        // No conflict with the carbonite hold below — that needs the
                        // player to be Leia, and this needs them to be Vader.
                        if (canForceChoke(e)) {
                            if (interactHeld && !forceChokeInputLatched) {
                                // Snap takes priority over choke on the same key.
                                // They cannot really collide — choke is on an 8s
                                // cooldown and a snap only exists inside the 2s
                                // grip — but the order makes the intent explicit:
                                // a second press during a hold finishes it.
                                const snapTarget = findNeckSnapTarget(e);
                                if (snapTarget) {
                                    performNeckSnap(e, snapTarget);
                                } else if (now >= e.forceChokeReadyAt) {
                                    const victim = findForceChokeTarget(e);
                                    if (victim) startForceChoke(e, victim);
                                }
                            }
                            forceChokeInputLatched = interactHeld;
                        } else {
                            forceChokeInputLatched = false;
                        }

                        // The three Marvel specials, on the same key and the same
                        // edge-triggered shape. No two of these can collide either:
                        // one character each.
                        if (canUnibeam(e)) {
                            if (interactHeld && !unibeamInputLatched && frameNow >= (e.unibeamReadyAt || 0)) {
                                startUnibeam(e);
                            }
                            unibeamInputLatched = interactHeld;
                        } else {
                            unibeamInputLatched = false;
                        }

                        if (canWebGrenade(e)) {
                            if (interactHeld && !webGrenadeInputLatched && frameNow >= (e.webGrenadeReadyAt || 0)) {
                                startWebGrenade(e);
                            }
                            webGrenadeInputLatched = interactHeld;
                        } else {
                            webGrenadeInputLatched = false;
                        }

                        if (canFlameBlast(e)) {
                            if (interactHeld && !flameBlastInputLatched && frameNow >= (e.flameBlastReadyAt || 0)) {
                                startFlameBlast(e);
                            }
                            flameBlastInputLatched = interactHeld;
                        } else {
                            flameBlastInputLatched = false;
                        }

                        // Stane's. Same edge-triggered shape as the rest, with no
                        // readiness clock in front of it — canIronMonger() goes false
                        // the moment he is in the suit, which is the whole gate.
                        if (canIronMonger(e)) {
                            if (interactHeld && !ironMongerInputLatched) {
                                ironMongerTransform(e);
                            }
                            ironMongerInputLatched = interactHeld;
                        } else {
                            ironMongerInputLatched = false;
                        }

                        if (canZeroShock(e)) {
                            if (interactHeld && !zeroShockInputLatched && frameNow >= (e.zeroShockReadyAt || 0)) {
                                startZeroShock(e);
                            }
                            zeroShockInputLatched = interactHeld;
                        } else {
                            zeroShockInputLatched = false;
                        }

                        // Asgard's two. Same key, same edge trigger, and the same
                        // one-character-each rule that keeps every branch above
                        // from colliding — with one addition: canShapeshift() is
                        // also true while Loki is wearing someone else, which is
                        // what lets a second press change shape rather than
                        // stranding him in the first face he took.
                        if (canGodBlast(e)) {
                            if (interactHeld && !godBlastInputLatched && frameNow >= (e.godBlastReadyAt || 0)) {
                                startGodBlast(e);
                            }
                            godBlastInputLatched = interactHeld;
                        } else {
                            godBlastInputLatched = false;
                        }

                        if (canShapeshift(e)) {
                            if (interactHeld && !shapeshiftInputLatched && frameNow >= (e.shapeshiftReadyAt || 0)) {
                                startShapeshift(e);
                            }
                            shapeshiftInputLatched = interactHeld;
                        } else {
                            shapeshiftInputLatched = false;
                        }

                        // One character each, so this cannot collide with any branch
                        // above it either.
                        // Shares the Interact key with Banner's transform, which sits
                        // a few branches above — see the note on HULK_SMASH_IDS for
                        // why that is safe and for the one thing that had to be done
                        // about it.
                        if (canHulkSmash(e)) {
                            if (interactHeld && !hulkSmashInputLatched && frameNow >= (e.hulkSmashReadyAt || 0)) {
                                startHulkSmash(e);
                            }
                            hulkSmashInputLatched = interactHeld;
                        } else {
                            hulkSmashInputLatched = false;
                        }

                        if (canClobberin(e)) {
                            if (interactHeld && !clobberinInputLatched && frameNow >= (e.clobberinReadyAt || 0)) {
                                startClobberin(e);
                            }
                            clobberinInputLatched = interactHeld;
                        } else {
                            clobberinInputLatched = false;
                        }

                        // Deadpool's swap. Same edge-triggered shape, and one
                        // character, so it cannot collide with anything above.
                        if (canWeaponSwap(e)) {
                            if (interactHeld && !weaponSwapInputLatched) swapWeapon(e);
                            weaponSwapInputLatched = interactHeld;
                        } else {
                            weaponSwapInputLatched = false;
                        }

                        // Thanos. One character, so this cannot collide either.
                        if (canInfinitySnap(e)) {
                            if (interactHeld && !infinitySnapInputLatched && frameNow >= infinitySnapReadyAt(e)) {
                                performInfinitySnap(e);
                            }
                            infinitySnapInputLatched = interactHeld;
                        } else {
                            infinitySnapInputLatched = false;
                        }

                        // Eternity. Edge-triggered like the rest, with no readiness
                        // clock: performEternitySummon() refuses while the last ally
                        // is still standing, which is the only limit she has.
                        if (canEternitySummon(e)) {
                            if (interactHeld && !eternitySummonInputLatched) {
                                performEternitySummon(e);
                            }
                            eternitySummonInputLatched = interactHeld;
                        } else {
                            eternitySummonInputLatched = false;
                        }

                        // Ant-Man shrinks on E; Q, above, is the other half.
                        if (canAntManResize(e)) {
                            if (interactHeld && !antShrinkInputLatched) startAntForm(e, 'small');
                            antShrinkInputLatched = interactHeld;
                        } else {
                            antShrinkInputLatched = false;
                        }

                        // Halloween shield: held, not pressed — see HALLOWEEN_SHIELD_IDS.
                        // Once up it stays up for as long as the key does, but it
                        // cannot be raised out of a committed swing.
                        if (canRaiseShield(e)) {
                            setShieldRaised(e, interactHeld && (e.shieldRaised || !isCommittedToSwing(e, now)));
                        }

                        // Halloween summons on Q, once a round. The four who have one
                        // carry blasters, so the key had nothing else to do for them.
                        if (canHalloweenSummon(e)) {
                            if (throwHeld && !halloweenSummonInputLatched) performHalloweenSummon(e);
                            halloweenSummonInputLatched = throwHeld;
                        } else {
                            halloweenSummonInputLatched = false;
                        }

                        if (isCarboniteRescuePhase()) {
                            const han = entities.find(x => x.characterId === 'carbonite_han' && x.isAlive);
                            if (han && interactHeld && Math.hypot(han.x - e.x, han.y - e.y) < 80) {
                                specialCloudCityJabbaHold += 16.7 * tickScale;
                                if (specialCloudCityJabbaHold >= 1200) {
                                    spawnJabbaHutt();
                                }
                            } else {
                                specialCloudCityJabbaHold = 0;
                            }
                        } else if (!interactHeld) {
                            specialCloudCityJabbaHold = 0;
                        }

                        // Dodge mechanic (Shift / 💨 / B) — Jabba cannot dodge.
                        // A dodge also breaks a committed swing: rolling is the
                        // one thing that gets you out of your own recovery, which
                        // is what keeps melee commitment from feeling like a trap.
                        if (e.characterId !== 'jabba' && dodgeHeld && !e.isDodging && now > e.dodgeCooldown) {
                            e.dodgeCooldown = now + 1500;
                            cancelMeleeSwing(e);

                            // Dodge in movement direction, else toward wherever the
                            // player is aiming (the nearest enemy, when auto-aimed)
                            let dodgeAngle = 0;
                            if (moveX !== 0 || moveY !== 0) {
                                dodgeAngle = Math.atan2(moveY, moveX);
                            } else {
                                const target = resolvePlayerAim(e);
                                if (target) {
                                    dodgeAngle = Math.atan2(target.y - e.y, target.x - e.x);
                                }
                            }

                            startDodge(e, now, dodgeAngle, PLAYER_DODGE_MS, PLAYER_DODGE_IFRAME_MS, 12);
                        }

                        if (e.isDodging && now > e.dodgeEnd) {
                            e.isDodging = false;
                        }

                        const spaceHeld = !!(keys[keyBindings.fire] || touchFire || padState.fire || mouseFire);
                        // Re-arm the semi-auto latch the instant the trigger comes up.
                        // Every input path (key, mouse, touch, pad) folds into
                        // spaceHeld, so this covers all of them at once.
                        if (!spaceHeld) e.triggerReleased = true;
                        if (moveX !== 0 || moveY !== 0) {
                            const mag = Math.min(1, Math.hypot(moveX, moveY));
                            const angle = Math.atan2(moveY, moveX);
                            const jabbaSlug   = e.characterId === 'jabba' ? 0.3 : 1;
                            // Drawing something back slows you to 45%, whatever it is.
                            // The old form named bowcaster and computer by key and
                            // also slugged the bowcaster on `spaceHeld` alone — before
                            // a draw had actually started — so it now asks the weapon
                            // whether it charges and the state whether it is charging.
                            const chargeSlug  = (chargeConfigOf(e.weaponConfig) && (spaceHeld || isCharging())) ? 0.45 : 1;
                            // A swing plants your feet, and a root tangle or the
                            // tide drags. The dodge branch still wins outright,
                            // which is what lets a roll both cancel recovery and
                            // tear free of a slowing zone.
                            const speedMultiplier = e.isDodging ? 2.5
                                : jabbaSlug * chargeSlug * swingMoveScale(e, now) * hazardMoveScale(e) * shieldMoveScale(e);
                            // e.speedMult is the per-entity movement override. The AI
                            // branch has always applied it; this one never did, so
                            // anything that made a fighter faster was silently
                            // AI-only — including the Shapeless form, whose entire
                            // mechanical effect for a player was therefore nothing.
                            const ownSpeed = e.speedMult || 1;
                            e.x += Math.cos(angle) * PLAYER_SPEED * mag * tickScale * speedMultiplier * ownSpeed;
                            e.y += Math.sin(angle) * PLAYER_SPEED * mag * tickScale * speedMultiplier * ownSpeed;
                        }

                        // Weapons are holstered for the whole opening phase of the
                        // Cloud City rescue — see isCarboniteRescuePhase(). This
                        // gates the entire block, so firing, charging, reloading and
                        // blade throws all stop together rather than leaving one
                        // action live; they all come back the moment it ends.
                        // A raised Halloween shield holsters everything the same way:
                        // nothing is fired, swung or thrown from behind it.
                        if (e.characterId !== 'jabba' && !isCarboniteRescuePhase() && !e.shieldRaised) {
                            const ammoBoostActive = now < e.ammoBoostUntil;
                            const effectiveCooldown = ammoBoostedCooldown(e.weaponConfig, ammoBoostActive);

                            // ── RELOAD (R / 🔄 / X) — only for weapons carrying a magazine ──
                            // Starting one is all this does — tickReload() above
                            // finishes it, for the player and the AI alike.
                            if (e.weaponConfig.magSize != null) {
                                if (!e.isReloading && e.magAmmo < e.weaponConfig.magSize && reloadHeld) {
                                    e.isReloading = true;
                                    e.reloadEndsAt = now + e.weaponConfig.reloadMs;
                                }
                            }

                            if (chargeConfigOf(e.weaponConfig)) {
                                // ── CHARGED SHOT ───────────────────────────
                                // One block for the Bowcaster, the Computer and the
                                // Bow. See the chargeShot declaration for why there
                                // is one of these rather than three.
                                const cc = chargeConfigOf(e.weaponConfig);
                                if (spaceHeld && now - e.lastShotTime > effectiveCooldown) {
                                    // Keyed by weapon, so a draw belongs to the thing
                                    // that started it and cannot be released by
                                    // whatever the fighter is holding a frame later.
                                    if (chargeShot.key !== e.weapon) {
                                        chargeShot.key = e.weapon;
                                        chargeShot.startedAt = now;
                                        // The wind-up starts on the frame the draw
                                        // does. Silent for every weapon that names
                                        // no draw sample — see CHARGE_DRAW_SFX.
                                        startChargeDrawSfx(e.weapon);
                                    }
                                    chargeShot.amount = Math.min(1, (now - chargeShot.startedAt) / cc.ms);
                                } else if (!spaceHeld && isCharging()) {
                                    // Release — fire proportional to the draw.
                                    //
                                    // The draw is read and cleared BEFORE the shot,
                                    // so the wind-up whine is already stopped when
                                    // the discharge sounds. The other way round
                                    // leaves the two overlapping for a frame, which
                                    // on the Repulsors is audible.
                                    const amount = chargeShot.amount;
                                    resetChargeShot();
                                    const target = resolvePlayerAim(e);
                                    if (target) {
                                        const shot = chargedConfigFor(e.weaponConfig, amount);
                                        // Multishot survives the draw. The three
                                        // weapons that charged before this all fire a
                                        // single projectile, so this branch only ever
                                        // called fireProjectile — and routing the
                                        // Repulsors through it would have quietly
                                        // dropped Iron Man from two bolts to one on
                                        // every charged release. Mirrors the dispatch
                                        // in NORMAL FIRE below.
                                        if (shot.multishot > 1) {
                                            fireSpreadProjectiles(e, target, shot, shot.multishot,
                                                                  focusedArc(e, shot, now));
                                        } else {
                                            fireProjectile(e, target, shot);
                                        }
                                        e.lastShotTime = now;
                                    }
                                }
                            } else if (e.weaponConfig.melee) {
                                // ── MELEE: SWING + THROW ──────────────────────────
                                // Both actions need a blade in hand, so both are
                                // blocked while a thrown one is still coming back —
                                // and now also while a swing is still committed,
                                // which is what stops the recovery from being
                                // cancelled by simply attacking again.
                                const armed = !hasBladeInFlight(e) && !isCommittedToSwing(e, now);
                                const swingCooldown = meleeSwingCooldown(e, effectiveCooldown);

                                if (spaceHeld && armed && now - e.lastShotTime > swingCooldown) {
                                    const target = resolvePlayerAim(e);
                                    if (target) {
                                        beginMeleeSwing(e, target);
                                        e.lastShotTime = now;
                                    }
                                }

                                if (throwHeld && armed && !e.weaponConfig.noThrow && now >= (e.throwReadyAt || 0)) {
                                    const target = resolvePlayerAim(e);
                                    if (target) {
                                        fireProjectile(e, target, e.weaponConfig);
                                        e.throwReadyAt = now + MELEE_THROW_COOLDOWN;
                                    }
                                }
                            } else if (spaceHeld && now - e.lastShotTime > burstAwareCooldown(e, effectiveCooldown, now) && canFireWeapon(e, now)
                                       && (!e.weaponConfig.semiAuto || e.triggerReleased)) {
                                // ── NORMAL FIRE ───────────────────────────────────
                                let target = resolvePlayerAim(e);
                                if (target) {
                                    if (now < e.spreadUntil) {
                                        fireSpreadProjectiles(e, target, e.weaponConfig, 5, 0.5);
                                    } else if (e.weaponConfig.multishot > 1) {
                                        fireSpreadProjectiles(e, target, e.weaponConfig, e.weaponConfig.multishot, focusedArc(e, e.weaponConfig, now));
                                    } else {
                                        fireProjectile(e, target, e.weaponConfig);
                                    }
                                    noteShotFired(e, now);
                                    // Latch the trigger down — a semi-auto weapon will
                                    // not fire again until spaceHeld goes false above.
                                    e.triggerReleased = false;
                                }
                            }

                            // ── DROID SIDEARM (RMB / Q / LT / 🌀) ─────────────
                            // Deliberately outside the weapon chain above rather
                            // than another branch in it: the sidearm runs on its
                            // own cooldown, so a droid can hold zap fire on the
                            // primary and put blaster bolts in between instead of
                            // choosing one weapon per trigger pull.
                            //
                            // These droids are never melee, so the secondary input
                            // is otherwise unused — reusing it gets mouse, keyboard,
                            // touch and gamepad support with no new bindings.
                            const sidearm = getSidearmConfig(e);
                            if (sidearm && throwHeld) {
                                // Through the same floor as the main gun. This was the one
                                // path the 2026-10-10 Ammo fix missed: a cooldown of 0 here
                                // fired a 25-damage bolt every frame for the whole boost,
                                // about 1,500 DPS at 60 Hz and 3,600 at 144 Hz.
                                const sidearmCooldown = ammoBoostedCooldown(sidearm, ammoBoostActive);
                                if (now - e.lastSidearmShotTime > sidearmCooldown) {
                                    const target = resolvePlayerAim(e);
                                    if (target) {
                                        // fireProjectile reads everything — damage,
                                        // spread, bolt art, fire SFX — off the config
                                        // it is handed, so passing the blaster gives a
                                        // real blaster shot rather than a reskinned zap.
                                        fireProjectile(e, target, sidearm);
                                        e.lastSidearmShotTime = now;
                                    }
                                }
                            }
                        }
                    } else {
                        if (e.isJabba || e.characterId === 'jabba') {
                            updateJabbaHutt(e, tickScale);
                            return;
                        }
                        if (e.characterId === 'carbonite_han' || e.isFrozen) return;
                        
                        // Handle fleeing clones
                        if (e.isFleeing) {
                            // Continue fleeing towards the edge but stop at boundary
                            e.x += e.vx * tickScale;
                            e.y += e.vy * tickScale;
                            e.x = Math.max(CHARACTER_SIZE, Math.min(canvasLogicalW - CHARACTER_SIZE, e.x));
                            e.y = Math.max(CHARACTER_SIZE, Math.min(canvasLogicalH - CHARACTER_SIZE, e.y));
                            // Slow down when near edge
                            e.vx *= 0.95;
                            e.vy *= 0.95;
                            // Remove from game if stopped at edge
                            if (Math.abs(e.vx) < 0.5 && Math.abs(e.vy) < 0.5) {
                                e.isAlive = false;
                            }
                            return;
                        }
                        
                        let target = getClosestEnemy(e);
                        if (target) {
                            const angleToTarget = Math.atan2(target.y - e.y, target.x - e.x);
                            const dist = Math.hypot(target.x - e.x, target.y - e.y);
                            const ds = diffSettings[currentDifficulty];
                            const tac = getTacticalProfile(e);
                            // e.speedMult is a per-entity override on top of the
                            // tactical profile, for units that move off-profile.
                            let moveSpeed = PLAYER_SPEED * ds.aiSpeed * tac.speedMult * (e.speedMult || 1);

                            // Melee fighters have to actually get within blade
                            // range now. The tactical profiles were written when a
                            // "melee" attack was a thrown projectile, so a duelist's
                            // 60–140px comfort band would leave it hovering just
                            // outside its own reach, swinging at nothing. Override
                            // the band with the weapon's real reach and leave every
                            // other profile trait (dodging, flanking, retreat) alone.
                            const isMeleeFighter = !!e.weaponConfig.melee;
                            const swingReach = isMeleeFighter ? getSwingReach(e) + CHARACTER_SIZE : 0;
                            // The AI is committed by exactly the same rules as the
                            // player — it plants its feet mid-swing, which is what
                            // gives the player a window to punish a whiffed cut —
                            // and it is dragged by the same slowing zones.
                            // Drawing a bow costs the AI the same 45% the player pays
                            // for it. Without this an archer would glide around at full
                            // speed with the string back, which is both unfair and
                            // unreadable — the slow is half the tell.
                            // The shield decision comes first so its 55% walk lands on
                            // the frame it goes up, the same as the player's.
                            if (canRaiseShield(e)) updateShieldAI(e, target, now);
                            moveSpeed *= swingMoveScale(e, now) * hazardMoveScale(e)
                                       * (aiIsDrawing(e) ? 0.45 : 1) * shieldMoveScale(e);
                            let effMinRange = isMeleeFighter ? swingReach * 0.45 : tac.minRange;
                            let effMaxRange = isMeleeFighter ? swingReach * 0.85 : tac.maxRange;

                            // ── REACTIVE LAYER ─────────────────────────────
                            const rx = aiReactions();

                            // Punish. The target is reloading, or locked into a
                            // swing that has not landed — the exact windows the
                            // player was given to exploit. Collapse the comfort
                            // band and close, so the opening is actually taken
                            // rather than politely observed from mid-range.
                            const punishing = rx.punish > 0 && targetIsPunishable(target, now)
                                              && Math.random() < rx.punish;
                            if (punishing) {
                                effMinRange = isMeleeFighter ? swingReach * 0.35 : Math.min(effMinRange, 40);
                                effMaxRange = isMeleeFighter ? swingReach * 0.8  : Math.min(effMaxRange, 90);
                            }

                            // Cover usage: Find nearest cover when low health (threshold
                            // scales with how defensively this character's tactics play)
                            // (the nearest one, and not during the break after a stint
                            // behind one — see aiTakeCover)
                            let nearCover = null;
                            if (e.health < e.maxHealth * (tac.retreatHealthPct + 0.2) && now >= (e.coverBreakUntil || 0)) {
                                let nearest = 150;
                                for (const c of coverObjects) {
                                    if (!c.alive) continue;
                                    const coverDist = Math.hypot(c.x - e.x, c.y - e.y);
                                    if (coverDist < nearest) {
                                        nearest = coverDist;
                                        nearCover = c;
                                    }
                                }
                            }

                            // Flanking behavior: Try to get behind target
                            const flankingAngle = angleToTarget + Math.PI;
                            const isLegend = currentDifficulty === 'legend';
                            const isHardOrLegend = currentDifficulty === 'hard' || isLegend;
                            const flankChance = (isLegend ? 0.10 : (isHardOrLegend ? 0.03 : 0.015)) * tac.flankMult;
                            let shouldFlank = Math.random() < flankChance && dist > effMinRange;

                            // Improved AI: Strafing behavior
                            const strafeAngle = angleToTarget + Math.PI / 2;
                            const strafeDir = Math.sin(now * 0.003 + e.x * 0.01) > 0 ? 1 : -1;
                            
                            // Improved AI: Predictive shooting
                            let targetX = target.x;
                            let targetY = target.y;
                            // The speed test is not an optimisation. `unarmed` is a
                            // real weapon in the library and its projectile speed is
                            // 0, so this divide handed back Infinity, and Infinity
                            // times a target standing still is NaN. That NaN went
                            // into predictedAngle, out through the movement below,
                            // and the entity's x/y were NaN from the first frame of
                            // the round onward: it vanished off the canvas, and
                            // every hazard's `distance > radius` test compared
                            // against NaN, came back false and counted it as a hit —
                            // so it was invisible AND being ground down from wherever
                            // the hazard happened to be.
                            //
                            // The Zero Event's Creepers are the only entities that
                            // carry `unarmed` and move, which is why it read as a
                            // Creeper bug: they were on the board through the 3-2-1
                            // and gone the moment the round started.
                            //
                            // Nothing without a projectile has a lead to compute —
                            // a Creeper does not shoot, it walks at you — so the
                            // aim simply stays on the target.
                            if (dist > 100 && e.weaponConfig.speed > 0) {
                                // Predict where target will be based on their velocity
                                const bulletTime = dist / e.weaponConfig.speed;
                                targetX += target.vx * bulletTime * 0.5;
                                targetY += target.vy * bulletTime * 0.5;
                            }
                            const predictedAngle = Math.atan2(targetY - e.y, targetX - e.x);

                            // Movement logic with strafing, flanking, and cover
                            // Check for nearby pickups that AI should seek
                            let seekingPickup = false;
                            for (const p of pickups) {
                                const distToPickup = Math.hypot(p.x - e.x, p.y - e.y);
                                // A sprite outranks every other drop and is worth
                                // crossing the whole arena for, so it is tested
                                // before the 300px proximity gate the others sit
                                // behind. Only the opponent proper chases it —
                                // minions cannot claim one anyway.
                                if (p.type === 'sprite') {
                                    if (e === mainEnemy && !entityHasSprite(e, p.spriteId)) {
                                        const pickupAngle = Math.atan2(p.y - e.y, p.x - e.x);
                                        // Slightly quicker than its normal pace: the
                                        // race should feel urgent, and a kiter would
                                        // otherwise amble toward a Mythic prize.
                                        e.x += Math.cos(pickupAngle) * moveSpeed * 1.15 * tickScale;
                                        e.y += Math.sin(pickupAngle) * moveSpeed * 1.15 * tickScale;
                                        seekingPickup = true;
                                        break;
                                    }
                                    continue;
                                }
                                if (distToPickup < 300) {
                                    // AI seeks health when below its retreat threshold (+ margin)
                                    if (p.type === 'health' && e.health < e.maxHealth * (tac.retreatHealthPct + 0.2)) {
                                        const pickupAngle = Math.atan2(p.y - e.y, p.x - e.x);
                                        e.x += Math.cos(pickupAngle) * moveSpeed * tickScale;
                                        e.y += Math.sin(pickupAngle) * moveSpeed * tickScale;
                                        seekingPickup = true;
                                        break;
                                    }
                                    // AI seeks shield when below its retreat threshold
                                    if (p.type === 'shield' && e.health < e.maxHealth * tac.retreatHealthPct && !e.shieldActive) {
                                        const pickupAngle = Math.atan2(p.y - e.y, p.x - e.x);
                                        e.x += Math.cos(pickupAngle) * moveSpeed * tickScale;
                                        e.y += Math.sin(pickupAngle) * moveSpeed * tickScale;
                                        seekingPickup = true;
                                        break;
                                    }
                                    // AI seeks ammo when not boosted
                                    if (p.type === 'ammo' && now >= e.ammoBoostUntil) {
                                        const pickupAngle = Math.atan2(p.y - e.y, p.x - e.x);
                                        e.x += Math.cos(pickupAngle) * moveSpeed * tickScale;
                                        e.y += Math.sin(pickupAngle) * moveSpeed * tickScale;
                                        seekingPickup = true;
                                        break;
                                    }
                                    // AI seeks spread powerup when not active
                                    if (p.type === 'spread' && now >= e.spreadUntil) {
                                        const pickupAngle = Math.atan2(p.y - e.y, p.x - e.x);
                                        e.x += Math.cos(pickupAngle) * moveSpeed * tickScale;
                                        e.y += Math.sin(pickupAngle) * moveSpeed * tickScale;
                                        seekingPickup = true;
                                        break;
                                    }
                                }
                            }
                            
                            // Standing in lava while trading shots is not a tactic.
                            // Outranks every other movement choice below, including
                            // chasing a pickup — nothing on the field is worth
                            // burning health for, tick after tick.
                            const harm = rx.hazard ? standingInHarm(e) : null;
                            let via = null;
                            if (harm) {
                                const outAngle = Math.atan2(e.y - harm.y, e.x - harm.x);
                                e.x += Math.cos(outAngle) * moveSpeed * 1.2 * tickScale;
                                e.y += Math.sin(outAngle) * moveSpeed * 1.2 * tickScale;
                            } else if (!seekingPickup) {
                                if (nearCover && e.health < e.maxHealth * tac.retreatHealthPct
                                    && aiTakeCover(e, nearCover, target, moveSpeed, tickScale, now)) {
                                    // Moving behind cover, or holding there
                                } else if (shouldFlank) {
                                    // Flank around target
                                    e.x += Math.cos(flankingAngle) * (moveSpeed * 0.8) * tickScale;
                                    e.y += Math.sin(flankingAngle) * (moveSpeed * 0.8) * tickScale;
                                } else if (dist > effMaxRange && (via = aiCoverDetour(e, target.x, target.y))) {
                                    // A block is in the way: round its corner first
                                    const va = Math.atan2(via.y - e.y, via.x - e.x);
                                    e.x += Math.cos(va) * moveSpeed * tickScale;
                                    e.y += Math.sin(va) * moveSpeed * tickScale;
                                } else if (dist > effMaxRange) {
                                    // Move toward target with strafe
                                    e.x += (Math.cos(predictedAngle) * 0.7 + Math.cos(strafeAngle) * strafeDir * 0.3) * moveSpeed * tickScale;
                                    e.y += (Math.sin(predictedAngle) * 0.7 + Math.sin(strafeAngle) * strafeDir * 0.3) * moveSpeed * tickScale;
                                } else if (dist < effMinRange) {
                                    // Back away while strafing
                                    e.x -= (Math.cos(predictedAngle) * 0.6 - Math.cos(strafeAngle) * strafeDir * 0.4) * (moveSpeed * 0.8) * tickScale;
                                    e.y -= (Math.sin(predictedAngle) * 0.6 - Math.sin(strafeAngle) * strafeDir * 0.4) * (moveSpeed * 0.8) * tickScale;
                                } else {
                                    // Pure strafe at optimal range
                                    e.x += Math.cos(strafeAngle) * strafeDir * (moveSpeed * 0.5) * tickScale;
                                    e.y += Math.sin(strafeAngle) * strafeDir * (moveSpeed * 0.5) * tickScale;
                                }
                            }

                            // Threat reaction: roll out of a bolt that is actually
                            // on its way, rather than dodging on a dice roll.
                            //
                            // This is the single biggest change in how a fight
                            // reads. The old dodge fired at random, only when the
                            // AI was already nearly dead, and had no relationship
                            // to anything the player did — so it never looked like
                            // the opponent had seen the shot. Now it sidesteps
                            // *perpendicular* to the incoming bolt, which is both
                            // the correct evasion and legible as one.
                            let reacted = false;
                            // A raised shield is already this fighter's answer to the
                            // bolt, so it does not also roll out of the way of it.
                            if (rx.threat && now > e.dodgeCooldown && !e.isDodging && !e.shieldRaised) {
                                const threat = findIncomingThreat(e, rx.reactionMs);
                                if (threat) {
                                    // Perpendicular to the bolt, toward whichever
                                    // side the entity is already leaning.
                                    const side = (e.vx * -threat.uy + e.vy * threat.ux) >= 0 ? 1 : -1;
                                    const dodgeAngle = Math.atan2(threat.ux * side, -threat.uy * side);
                                    e.dodgeCooldown = now + 900;
                                    cancelMeleeSwing(e);
                                    startDodge(e, now, dodgeAngle, AI_DODGE_MS, AI_DODGE_IFRAME_MS, 9);
                                    reacted = true;
                                }
                            }

                            // Panic dodge when badly hurt — the original behaviour,
                            // kept as a fallback for difficulties with no threat
                            // scanning and for entities that have already reacted.
                            if (!reacted && !e.shieldRaised && e.health < e.maxHealth * Math.max(tac.retreatHealthPct, 0.15) && now > e.dodgeCooldown && Math.random() < 0.02 * tac.dodgeMult) {
                                e.dodgeCooldown = now + 2000;
                                cancelMeleeSwing(e);
                                const dodgeAngle = angleToTarget + (Math.random() - 0.5) * Math.PI;
                                startDodge(e, now, dodgeAngle, AI_DODGE_MS, AI_DODGE_IFRAME_MS, 8);
                            }

                            if (e.isDodging && now > e.dodgeEnd) {
                                e.isDodging = false;
                            }

                            // Shooting with reduced deviation for harder difficulties
                            // (and tighter groupings for naturally precise fighters)
                            const ammoBoostActive = now < e.ammoBoostUntil;
                            const effectiveCooldown = ammoBoostedCooldown(e.weaponConfig, ammoBoostActive);

                            // ── RELOAD (AI) ────────────────────────────
                            // The AI carries a magazine on the same terms the
                            // player does, so it has to work the same lulls:
                            // top up while there is no shot to take, and never
                            // stand in the open feeding one round at a time.
                            // canFireWeapon() still force-starts a reload the
                            // moment the mag runs dry, so this only ever pulls
                            // that decision earlier — and its reload is a real
                            // window, one targetIsPunishable() already teaches
                            // the other side to attack.
                            if (!isMeleeFighter) {
                                beginReloadIfNeeded(e, now, () => !(dist <= effMaxRange * 1.5
                                    && (!rx.los || hasLineOfFire(e.x, e.y, target.x, target.y))));
                            }

                            // Melee AI swings when the target is inside its arc and
                            // throws to punish someone backing off — but only
                            // sometimes, so a duel doesn't become both fighters
                            // permanently disarmed with their blades in the air.
                            if (e.shieldRaised) {
                                // Behind the shield: no swing, no throw, no shot,
                                // exactly as for the player.
                            } else if (isMeleeFighter) {
                                const armed = !hasBladeInFlight(e) && !isCommittedToSwing(e, now);
                                const swingCooldown = meleeSwingCooldown(e, effectiveCooldown);
                                if (armed && dist <= swingReach && now - e.lastShotTime > swingCooldown) {
                                    beginMeleeSwing(e, target);
                                    e.lastShotTime = now;
                                } else if (armed && !e.weaponConfig.noThrow && dist > swingReach && now >= (e.throwReadyAt || 0)) {
                                    // Harder difficulties are quicker to take the shot
                                    const throwChance = currentDifficulty === 'legend' ? 0.05
                                                      : currentDifficulty === 'hard' ? 0.03 : 0.015;
                                    if (Math.random() < throwChance) {
                                        fireProjectile(e, target, e.weaponConfig);
                                        e.throwReadyAt = now + MELEE_THROW_COOLDOWN;
                                    }
                                }
                            } else if (now - e.lastShotTime > burstAwareCooldown(e, effectiveCooldown, now) && canFireWeapon(e, now)
                                       && (!rx.los || hasLineOfFire(e.x, e.y, target.x, target.y))
                                       && aiChargeReady(e, now, dist)) {
                                // aiChargeReady() is where a charging weapon spends its
                                // draw. It returns true immediately for everything that
                                // does not charge, so the whole ranged path below is
                                // unchanged for the other forty-odd weapons — and for a
                                // Bow or a Bowcaster it holds the branch closed until
                                // the string is back far enough to be worth loosing.
                                //
                                // Deliberately LAST in the condition: the line-of-fire
                                // and cooldown gates get to say no first, so the AI does
                                // not stand there drawing at the back of a crate.
                                // Melee never reaches here — it swings and throws in
                                // the branch above — so this is purely ranged aim.
                                //
                                // The line-of-fire gate is what stops the AI
                                // emptying a magazine into the back of a crate. It
                                // holds fire instead, and because the movement code
                                // above keeps strafing, holding fire is what makes
                                // it walk out from behind the obstruction on its own
                                // — cover became something both sides use rather
                                // than scenery only the player understood.
                                // e.spreadScale is a per-entity aim multiplier on top
                                // of the profile's, so something can be made more
                                // accurate without being given a different set of
                                // tactics. The Shapeless form needs exactly that: it
                                // runs on the `reckless` profile, which carries the
                                // worst spread in the game at 1.3, so tightening its
                                // aim by swapping profiles would also stop it being
                                // reckless.
                                let deviation = (Math.random() - 0.5) * ds.aiSpread * tac.spreadMult * (e.spreadScale || 1);
                                if (e.weaponConfig.key === 'sniper' || e.weaponConfig.key === 'boomsniper') {
                                    deviation *= 0.15;
                                }
                                
                                // What actually leaves the bow. For everything that does
                                // not charge this IS e.weaponConfig, unchanged.
                                const shotConfig = aiShotConfig(e);
                                // Use predicted angle for better accuracy on harder difficulties
                                // (or always, for characters whose tactics call for it)
                                const baseAngle = (isHardOrLegend || tac.alwaysPredictive) ? predictedAngle : angleToTarget;
                                const deviatedAngle = baseAngle + deviation;
                                if (now < e.spreadUntil) {
                                    const spreadCount = 5;
                                    const spreadArc = 0.5;
                                    const stepAngle = spreadArc / (spreadCount - 1);
                                    const startAngle = deviatedAngle - spreadArc / 2;
                                    for (let i = 0; i < spreadCount; i++) {
                                        const a = startAngle + stepAngle * i;
                                        const sdx = Math.cos(a) * shotConfig.speed;
                                        const sdy = Math.sin(a) * shotConfig.speed;
                                        if (bullets.length < MAX_BULLETS) bullets.push(new Projectile(e.x, e.y, sdx, sdy, shotConfig, e));
                                    }
                                } else if (shotConfig.multishot > 1) {
                                    const spreadCount = shotConfig.multishot;
                                    const spreadArc = focusedArc(e, shotConfig, now);
                                    const stepAngle = spreadCount > 1 ? spreadArc / (spreadCount - 1) : 0;
                                    const startAngle = deviatedAngle - spreadArc / 2;
                                    for (let i = 0; i < spreadCount; i++) {
                                        const a = startAngle + stepAngle * i;
                                        const sdx = Math.cos(a) * shotConfig.speed;
                                        const sdy = Math.sin(a) * shotConfig.speed;
                                        if (bullets.length < MAX_BULLETS) bullets.push(new Projectile(e.x, e.y, sdx, sdy, shotConfig, e));
                                    }
                                } else {
                                    const dx = Math.cos(deviatedAngle) * shotConfig.speed;
                                    const dy = Math.sin(deviatedAngle) * shotConfig.speed;
                                    if (bullets.length < MAX_BULLETS) bullets.push(new Projectile(e.x, e.y, dx, dy, shotConfig, e));
                                }
                                noteShotFired(e, now);
                                releaseAiCharge(e);
                                if (e.weaponConfig.magSize != null && e.magAmmo != null) {
                                    e.magAmmo = Math.max(0, e.magAmmo - 1);
                                }

                                // ── SFX: AI shoot sounds ───────────────
                                playWeaponFireSfx(e.weaponConfig);
                            }
                        }
                    }

                    // Apply knockback velocity (decay matched to TARGET_FPS)
                    const kbDecay = Math.pow(0.78, tickScale);
                    e.x += e.vx * tickScale; e.y += e.vy * tickScale;
                    e.vx *= kbDecay; e.vy *= kbDecay;
                    if (Math.abs(e.vx) < 0.05) e.vx = 0;
                    if (Math.abs(e.vy) < 0.05) e.vy = 0;

                    // Cover push-out
                    checkEntityCoverCollision(e, tickScale);

                    e.x = Math.max(CHARACTER_SIZE, Math.min(canvasLogicalW - CHARACTER_SIZE, e.x));
                    e.y = Math.max(CHARACTER_SIZE, Math.min(canvasLogicalH - CHARACTER_SIZE, e.y));

                    updateAnzellanEscorts(e, tickScale);
                });

                if (specialCloudCityJabbaSpawned && specialCloudCityJabbaCharacter && specialCloudCityJabbaCharacter.isAlive && frameNow > specialCloudCityGuardTimer) {
                    spawnGamorreanGuard();
                    specialCloudCityGuardTimer = frameNow + 2200;
                }

                bullets.forEach(b => b.step(tickScale));

                // ── BULLET CLASH ───────────────────────────────────────
                // Only opposing-team bullets of the same type can ever clash, so the
                // live bullets are split by team and one side is dropped into a coarse
                // spatial hash. The old form compared every bullet against every other
                // one: against MAX_BULLETS = 200 that is ~20,000 distance tests per
                // frame, which a Beam or Flamethrower user reaches easily and which
                // was enough to tank the frame rate on a phone. Cells are one block
                // radius across, so checking the 3×3 neighbourhood around a bullet is
                // guaranteed to find every partner within range.
                const BLOCK_RADIUS = 12;
                const BLOCK_RADIUS_SQ = BLOCK_RADIUS * BLOCK_RADIUS;
                const ds = diffSettings[currentDifficulty];
                const blockChance = ds.blockChance;
                const blockNow = frameNow;

                clashTeamA.length = 0;
                clashTeamB.length = 0;
                for (let i = 0; i < bullets.length; i++) {
                    const b = bullets[i];
                    if (b.blocked || !b.owner) continue;
                    if ((b.noCollideUntil || 0) > blockNow) continue;
                    if (b.owner.team === 'player') clashTeamA.push(b);
                    else clashTeamB.push(b);
                }

                if (clashTeamA.length > 0 && clashTeamB.length > 0) {
                    clashGrid.clear();
                    for (let i = 0; i < clashTeamA.length; i++) {
                        const a = clashTeamA[i];
                        const key = (Math.floor(a.x / BLOCK_RADIUS) * 73856093) ^ Math.floor(a.y / BLOCK_RADIUS);
                        let cell = clashGrid.get(key);
                        if (!cell) {
                            cell = [];
                            clashGrid.set(key, cell);
                        }
                        cell.push(a);
                    }

                    for (let i = 0; i < clashTeamB.length; i++) {
                        const b = clashTeamB[i];
                        if (b.blocked) continue;
                        const bcx = Math.floor(b.x / BLOCK_RADIUS);
                        const bcy = Math.floor(b.y / BLOCK_RADIUS);
                        // Once b either clashes or is waved through it is resolved for
                        // this frame — blocked bullets are gone and passed-through ones
                        // are immune, so neither can pair again. Matches the old
                        // pairwise loop, which skipped them on every later pair.
                        let resolved = false;
                        for (let ox = -1; ox <= 1 && !resolved; ox++) {
                            for (let oy = -1; oy <= 1 && !resolved; oy++) {
                                const cell = clashGrid.get(((bcx + ox) * 73856093) ^ (bcy + oy));
                                if (!cell) continue;
                                for (let k = 0; k < cell.length; k++) {
                                    const a = cell[k];
                                    if (a.blocked || a.type !== b.type) continue;
                                    if ((a.noCollideUntil || 0) > blockNow) continue;
                                    const dx = a.x - b.x;
                                    const dy = a.y - b.y;
                                    if (dx * dx + dy * dy >= BLOCK_RADIUS_SQ) continue;

                                    if (Math.random() < blockChance) {
                                        a.blocked = true;
                                        b.blocked = true;
                                        // Opposing bolts cancelling mid-air was the one
                                        // impact in the game with sparks but no sound.
                                        //
                                        // Flame is the exception: it looses three
                                        // projectiles every 70ms, so two flamethrowers
                                        // facing each other would machine-gun this
                                        // sample under the roar. The roar is the only
                                        // sound that weapon makes.
                                        //
                                        // The Halloween weapons clang instead. Two
                                        // Skeleton Swords meeting in the air are steel
                                        // on steel, and the Halloween Blaster's round
                                        // already lands on BluntHit when it explodes, so
                                        // neither should ever ring like a lightsaber.
                                        if (a.type === 'skeletonsword' || a.type === 'halloweenblaster') playSound('bluntHit', 90);
                                        else if (a.type !== 'flamethrower') playSound('lightsaberDeflect', 90);
                                        for (let s = 0; s < 8; s++) {
                                            if (clashParticles.length >= MAX_CLASH_PARTICLES) break;
                                            const sparkAngle = Math.random() * Math.PI * 2;
                                            const speed = Math.random() * 3 + 1;
                                            clashParticles.push({
                                                x: (a.x + b.x) / 2, y: (a.y + b.y) / 2,
                                                dx: Math.cos(sparkAngle) * speed, dy: Math.sin(sparkAngle) * speed,
                                                life: 18, maxLife: 18,
                                                color: a.type === 'zap' ? '#7efcff' : '#ffaa00'
                                            });
                                        }
                                    } else {
                                        // Pass through — immunity stops them re-colliding next frame
                                        a.noCollideUntil = blockNow + 350;
                                        b.noCollideUntil = blockNow + 350;
                                    }
                                    resolved = true;
                                    break;
                                }
                            }
                        }
                    }
                }

                const hitTargets = collectAlive(hitTargetScratch);

                // Only entities that are actually guarding right now can deflect,
                // and there is normally at most one of them on the field. Gathered
                // once per frame rather than rescanned inside the per-bullet loop
                // below: that loop already runs up to MAX_BULLETS times, and a
                // Beam or Flamethrower user fills it, so a nested scan over every
                // entity would be thousands of wasted property reads a frame for a
                // list that is usually empty.
                deflectorScratch.length = 0;
                for (let i = 0; i < hitTargets.length; i++) {
                    const g = hitTargets[i];
                    if (g.weaponConfig && g.weaponConfig.deflects && frameNow < (g.guardUntil || 0)) {
                        deflectorScratch.push(g);
                    }
                }
                const deflectors = deflectorScratch;

                bullets = bullets.filter(b => {
                    if (b.blocked) return false;
                    if (!b.owner) return false;
                    if (b.collected) return false;
                    if (b.returnable && b.owner && !b.owner.isAlive) return false;

                    // A spent arrow used to be skipped past every test below — no hit,
                    // no cover, no deflection — so it could only ever leave the screen.
                    // It is a live object again on purpose: a dead arrow drifting off
                    // the line CAN still catch someone, and when it does it hits twice
                    // as hard. That is the whole appeal of the thing. The doubling is
                    // not applied here; it is baked into the projectile's own `damage`
                    // the moment it goes spent, so every path that reads damage off the
                    // bullet gets it without knowing this rule exists.

                    // A lit barrier eats bolts outright. Checked before cover so a
                    // shield standing over a crate still stops the shot, and before
                    // the hit test so a fighter sheltering behind one is genuinely
                    // safe for as long as it holds.
                    if (hazardBlocksPoint(b.x, b.y, 4, frameNow)) {
                        if (b.returnable && !b.returning) { b.beginReturn(); return true; }
                        if (b.returnable && b.returning) return true;
                        spawnImpactParticles(b.x, b.y, b.color, 5);
                        return false;
                    }

                    // Cover collision
                    if (checkBulletCoverCollision(b)) {
                        if (b.returnable && !b.returning) {
                            b.beginReturn();
                            return true;
                        }
                        if (b.returnable && b.returning) {
                            return true;
                        }
                        return false;
                    }

                    let hit = false;

                    // Deflection runs ahead of the hit test and over a wider
                    // radius than it — the blade reaches well past the body, so a
                    // bolt has to be turned aside before it is ever close enough
                    // to count as a hit. A deflected bolt changes owner inside
                    // tryDeflect, so it stays in the world and is re-tested
                    // against its new enemies from the next frame on.
                    let deflected = false;
                    for (let i = 0; i < deflectors.length; i++) {
                        const guard = deflectors[i];
                        if (guard.team === b.owner.team) continue;
                        if (tryDeflect(guard, b, frameNow)) { deflected = true; break; }
                    }
                    if (deflected) return true;

                    for (let i = 0; i < hitTargets.length; i++) {
                        let target = hitTargets[i];
                        if (!target.isAlive) continue;
                        // A dodging target is not there to be hit. Skipping the
                        // target rather than absorbing the bolt means the shot
                        // sails on past and can still hit whoever is behind them,
                        // which is what makes a well-timed roll read as evasion
                        // instead of as immunity.
                        if (isInvulnerable(target, frameNow)) {
                            // Noted once per bolt, not once per frame of overlap —
                            // a bullet spends several frames crossing a body and
                            // would otherwise stack up four "DODGE" readouts.
                            if (!b.dodgeNoted && Math.hypot(b.x - target.x, b.y - target.y) < bodyRadius(target)) {
                                b.dodgeNoted = true;
                                spawnDodgeNegation(target);
                            }
                            continue;
                        }
                        if (b.owner.team !== target.team) {
                            if (Math.hypot(b.x - target.x, b.y - target.y) < bodyRadius(target)) {
                                if (b.returnable && !b.returning) {
                                    // Outgoing: hit enemy, start returning (no damage yet, handled below)
                                    applyStatusAndDamage(target, b);
                                    b.beginReturn();
                                    break;
                                }
                                if (b.returnable && b.returning) {
                                    // Return trip: hit enemy again — deal damage but keep flying back to owner
                                    applyStatusAndDamage(target, b);
                                    break;
                                }
                                if (!b.returnable) {
                                    applyStatusAndDamage(target, b);
                                    hit = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (hit) return false;
                    if (b.returnable && !b.returning && (b.x <= -30 || b.x >= canvasLogicalW + 30 || b.y <= -30 || b.y >= canvasLogicalH + 30)) {
                        b.beginReturn();
                        return true;
                    }
                    if (b.returnable && b.returning) return true;
                    return b.x > -30 && b.x < canvasLogicalW + 30 && b.y > -30 && b.y < canvasLogicalH + 30;
                });

                // ── ARENA-SPECIFIC MECHANICS ───────────────────────────────
                const now = frameNow;

                // Hazards run after movement and combat have both resolved, so a
                // shove from a speeder or a closing door is the last word on where
                // an entity ends up this frame rather than something the movement
                // code immediately overwrites.
                updateHazards(tickScale);

                // Pickup spawning system
                if (gameStartTime > 0) {
                    pickupSpawnTimer += 16.7 * tickScale;
                    if (pickupSpawnTimer >= PICKUP_SPAWN_TIME && pickups.length === 0) {
                        pickupSpawnTimer = 0;
                        // Spawn a pickup in a random cover-free spot. A sprite can
                        // take this slot instead of an ordinary drop — see
                        // rollSpriteDrop() for the rarity odds and who is eligible.
                        const spriteDrop = rollSpriteDrop();
                        const type = spriteDrop ? 'sprite' : PICKUP_TYPES[Math.floor(Math.random() * PICKUP_TYPES.length)];
                        let validSpot = false;
                        let attempts = 0;
                        let px, py;
                        
                        while (!validSpot && attempts < 50) {
                            px = CHARACTER_SIZE + 50 + Math.random() * (canvasLogicalW - CHARACTER_SIZE * 2 - 100);
                            py = CHARACTER_SIZE + 50 + Math.random() * (canvasLogicalH - CHARACTER_SIZE * 2 - 100);
                            
                            // Check if spot is free of cover
                            validSpot = true;
                            for (const c of coverObjects) {
                                if (!c.alive) continue;
                                const dist = Math.hypot(c.x - px, c.y - py);
                                if (dist < c.w/2 + 30) {
                                    validSpot = false;
                                    break;
                                }
                            }
                            attempts++;
                        }
                        
                        if (validSpot) {
                            pickups.push({
                                x: px,
                                y: py,
                                type: type,
                                spriteId: spriteDrop ? spriteDrop.id : null,
                                spawnTime: now
                            });
                            if (spriteDrop) {
                                // Both fighters race for this one, so it has to be
                                // called out — it must not look like another health
                                // pack. forceShow: mid-match announcements are
                                // deferred, and this one is only useful right now.
                                showAnnouncement(`A ${spriteRarity(spriteDrop).label} sprite has materialised on the field. Reach ${spriteDrop.name} before your opponent does.`,
                                    spriteRarity(spriteDrop).color, 4000, `${spriteDrop.icon} SPRITE DROP`, 100, true);
                            }
                        }
                    }
                }

                // Pickup collision detection
                pickups = pickups.filter(p => {
                    const pickupRadius = 20;
                    for (const e of aliveEntities) {
                        if (Math.hypot(e.x - p.x, e.y - p.y) < pickupRadius + CHARACTER_SIZE) {
                            // A sprite is a duel prize: only the two principals can
                            // claim it. Letting a backup clone or a spawned guard
                            // walk off with a Mythic would decide it by accident.
                            if (p.type === 'sprite') {
                                if (e !== mainPlayer && e !== mainEnemy) continue;
                                claimSpritePickup(e, p.spriteId);
                                return false;
                            }
                            // Apply pickup effect
                            if (p.type === 'health') {
                                e.health = Math.min(e.maxHealth, e.health + 25);
                                spawnHitSparks(e.x, e.y, '#00ff00', 10);
                            } else if (p.type === 'shield') {
                                e.shieldActive = true;
                                e.shieldUntil = now + 10000; // Shield lasts 10 seconds
                                spawnHitSparks(e.x, e.y, '#00aaff', 10);
                            } else if (p.type === 'ammo') {
                                e.ammoBoostUntil = now + 4000; // Ammo boost lasts 4 seconds
                                spawnHitSparks(e.x, e.y, '#ffaa00', 10);
                            } else if (p.type === 'spread') {
                                e.spreadUntil = now + 8000; // Spread shot lasts 8 seconds
                                spawnHitSparks(e.x, e.y, '#ff00ff', 10);
                            }
                            return false; // Remove pickup
                        }
                    }
                    return true; // Keep pickup
                });

                const clashDrag = Math.pow(0.85, tickScale);
                clashParticles = clashParticles.filter(p => {
                    p.x += p.dx * tickScale; p.y += p.dy * tickScale;
                    p.dx *= clashDrag; p.dy *= clashDrag;
                    p.life -= tickScale;
                    return p.life > 0;
                });
            }

            function draw(tickScale) {
                applyWorldTransform();
                // In world units, so this covers the whole field whatever the
                // arena's scale — which is the whole canvas either way.
                ctx.clearRect(0, 0, canvasLogicalW, canvasLogicalH);

                // Apply screen shake
                ctx.save();
                applyScreenShake();

                // ── Arena background ───────────────────────────────────
                const arenaStyle = ARENAS[currentArena] || ARENAS.space;
                arenaStyle.bg(canvasLogicalW, canvasLogicalH, tickScale);

                // ── Space arena: animated starfield ───────────────────
                if (currentArena === 'space') {
                    starLayers.forEach(layer => {
                        layer.stars.forEach(st => {
                            st.x -= layer.speed * tickScale;
                            if (st.x < 0) { st.x = canvasLogicalW; st.y = Math.random() * canvasLogicalH; }
                            st.twinkle += 0.04 * tickScale;
                            const alpha = layer.alpha * (0.7 + 0.3 * Math.sin(st.twinkle));
                            ctx.fillStyle = `rgba(255,255,255,${alpha})`;
                            ctx.beginPath(); ctx.arc(st.x, st.y, layer.size, 0, Math.PI * 2); ctx.fill();
                        });
                    });
                }

                // subtle grid
                ctx.strokeStyle = arenaStyle.grid;
                ctx.lineWidth = 1;
                // One path, one stroke — this used to issue ~40 separate stroke calls
                // per frame, each with its own state validation cost.
                ctx.beginPath();
                for (let i = 0; i < canvasLogicalW; i += 40) { ctx.moveTo(i, 0); ctx.lineTo(i, canvasLogicalH); }
                for (let i = 0; i < canvasLogicalH; i += 40) { ctx.moveTo(0, i); ctx.lineTo(canvasLogicalW, i); }
                ctx.stroke();

                // ── Pickups ───────────────────────────────────────────────
                pickups.forEach(p => {
                    ctx.save();
                    const pulse = Math.sin(frameNow * 0.005) * 0.2 + 0.8;

                    if (p.type === 'sprite') {
                        // Deliberately unlike the four round drops: a rarity-coloured
                        // diamond that turns and flares, so it reads as "rare thing,
                        // go get it" at a glance rather than as another health pack.
                        const sprite = getSprite(p.spriteId);
                        const rarity = spriteRarity(sprite);
                        const spin = frameNow * 0.002;
                        ctx.translate(p.x, p.y);
                        ctx.shadowBlur = 22;
                        ctx.shadowColor = rarity.color;
                        ctx.globalAlpha = pulse;
                        ctx.fillStyle = rarity.color;
                        ctx.rotate(spin);
                        ctx.beginPath();
                        ctx.moveTo(0, -17); ctx.lineTo(13, 0); ctx.lineTo(0, 17); ctx.lineTo(-13, 0);
                        ctx.closePath();
                        ctx.fill();
                        ctx.rotate(-spin);
                        ctx.globalAlpha = 1;
                        ctx.shadowBlur = 0;
                        ctx.font = '15px sans-serif';
                        ctx.textAlign = 'center';
                        ctx.textBaseline = 'middle';
                        ctx.fillText(sprite ? sprite.icon : '✨', 0, 1);
                        ctx.restore();
                        return;
                    }

                    if (p.type === 'health') {
                        ctx.fillStyle = `rgba(0, 255, 0, ${pulse})`;
                        ctx.shadowBlur = 15;
                        ctx.shadowColor = '#00ff00';
                        ctx.beginPath();
                        ctx.arc(p.x, p.y, 15, 0, Math.PI * 2);
                        ctx.fill();
                        // Cross
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(p.x - 8, p.y);
                        ctx.lineTo(p.x + 8, p.y);
                        ctx.moveTo(p.x, p.y - 8);
                        ctx.lineTo(p.x, p.y + 8);
                        ctx.stroke();
                    } else if (p.type === 'shield') {
                        ctx.fillStyle = `rgba(0, 170, 255, ${pulse})`;
                        ctx.shadowBlur = 15;
                        ctx.shadowColor = '#00aaff';
                        ctx.beginPath();
                        ctx.arc(p.x, p.y, 15, 0, Math.PI * 2);
                        ctx.fill();
                        // Shield icon
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.arc(p.x, p.y, 10, Math.PI, 0);
                        ctx.lineTo(p.x + 10, p.y + 5);
                        ctx.lineTo(p.x - 10, p.y + 5);
                        ctx.closePath();
                        ctx.stroke();
                    } else if (p.type === 'ammo') {
                        ctx.fillStyle = `rgba(255, 170, 0, ${pulse})`;
                        ctx.shadowBlur = 15;
                        ctx.shadowColor = '#ffaa00';
                        ctx.beginPath();
                        ctx.arc(p.x, p.y, 15, 0, Math.PI * 2);
                        ctx.fill();
                        // Lightning bolt
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 3;
                        ctx.beginPath();
                        ctx.moveTo(p.x + 5, p.y - 10);
                        ctx.lineTo(p.x - 5, p.y);
                        ctx.lineTo(p.x, p.y);
                        ctx.lineTo(p.x - 5, p.y + 10);
                        ctx.lineTo(p.x + 5, p.y);
                        ctx.lineTo(p.x, p.y);
                        ctx.closePath();
                        ctx.stroke();
                    } else if (p.type === 'spread') {
                        ctx.fillStyle = `rgba(255, 0, 255, ${pulse})`;
                        ctx.shadowBlur = 15;
                        ctx.shadowColor = '#ff00ff';
                        ctx.beginPath();
                        ctx.arc(p.x, p.y, 15, 0, Math.PI * 2);
                        ctx.fill();
                        // Spread/fan icon — three diverging lines
                        ctx.strokeStyle = '#ffffff';
                        ctx.lineWidth = 2.5;
                        ctx.beginPath();
                        ctx.moveTo(p.x - 8, p.y + 8);
                        ctx.lineTo(p.x + 9, p.y - 4);
                        ctx.moveTo(p.x - 8, p.y + 8);
                        ctx.lineTo(p.x + 9, p.y + 2);
                        ctx.moveTo(p.x - 8, p.y + 8);
                        ctx.lineTo(p.x + 9, p.y + 8);
                        ctx.stroke();
                    }
                    ctx.restore();
                });

                // ── Cover objects ──────────────────────────────────────
                drawCovers();

                // Under the fighters and bolts: a hazard is terrain, and drawing it
                // over the top would hide the thing the player needs to see most.
                drawHazards();

                entities.forEach(e => {
                    // The player's blade and saber trail face wherever they are
                    // aiming — that facing is the only feedback showing where a
                    // melee throw will actually go before it is released.
                    if (!e.isAlive) return;
                    const facing = (e.isMainEntity && e.team === 'player') ? resolvePlayerAim(e) : getClosestEnemy(e);
                    e.draw(facing);
                });
                entities.forEach(e => {
                    if (e.isAlive) drawAnzellanEscorts(e);
                });

                bullets.forEach(b => b.draw());

                // clash particles
                clashParticles.forEach(p => {
                    if (p.life <= 0) return;
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
                    ctx.fillStyle = p.color;
                    ctx.shadowBlur = 6;
                    ctx.shadowColor = p.color;
                    ctx.beginPath(); ctx.arc(p.x, p.y, 2.5, 0, Math.PI * 2); ctx.fill();
                    ctx.restore();
                });

                // death explosion particles
                const deathDrag = Math.pow(0.88, tickScale);
                deathParticles = deathParticles.filter(p => {
                    p.x += p.dx * tickScale; p.y += p.dy * tickScale;
                    p.dx *= deathDrag; p.dy *= deathDrag;
                    p.life -= tickScale;
                    if (p.life <= 0) return false;
                    
                    ctx.save();
                    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
                    ctx.fillStyle = p.color;
                    ctx.shadowBlur = 8; ctx.shadowColor = p.color;
                    ctx.beginPath(); ctx.arc(p.x, p.y, Math.max(0, p.r * (p.life / p.maxLife)), 0, Math.PI * 2); ctx.fill();
                    ctx.restore();
                    return true;
                });

                // floating damage numbers
                const floatDrag = Math.pow(0.96, tickScale);
                floatNums = floatNums.filter(fn => {
                    fn.y += fn.dy * tickScale;
                    fn.dy *= floatDrag;
                    fn.life -= tickScale;
                    if (fn.life <= 0) return false;

                    const alpha = Math.max(0, fn.life / fn.maxLife);
                    ctx.save();
                    ctx.globalAlpha = alpha;
                    ctx.font = `bold ${Math.round(11 + (1 - alpha) * 4)}px ${getCanvasFontFamily()}, sans-serif`;
                    ctx.textAlign = 'center';
                    // Every earlier entry has already been moved this frame, so
                    // the one being placed is checked against where they are now.
                    if (!fn.placed) placeFloatNum(fn, floatNums);
                    // Optional per-number tint, so burn ticks can read as fire
                    // rather than as another hit. Everything that omits it keeps
                    // the white-on-red it has always had.
                    ctx.fillStyle = fn.color || '#ffffff';
                    ctx.shadowBlur = 6; ctx.shadowColor = fn.glow || '#ff4444';
                    ctx.fillText(fn.text, fn.x, fn.y);
                    ctx.restore();
                    return true;
                });

                // ── NEW VISUAL EFFECTS ──────────────────────────────────
                drawSwingWindups();
                drawMeleeSwings();
                drawSaberTrails();
                drawHitSparks();
                drawImpactParticles();
                drawBoomBlasts();
                drawDodgeFlashes();
                drawAimReticle();
                drawLowHealthVignette();

                /*  ── CHARGE METER ────────────────────────────────────
                 *  A ring that fills clockwise around the player as the shot is drawn.
                 *  Was written twice, once per charging weapon, differing only in the
                 *  colour — so the colour is now a field on the weapon's charge block
                 *  and this is drawn once. The white-at-full and the CHARGED label are
                 *  unchanged from the pair it replaces.                             */
                // The player's draw, then every AI draw. An archer winding up a 51 with
                // no tell is exactly the "cheap hit" the blast doors were given a
                // warning flash to avoid, so the AI gets the identical ring.
                const chargeRings = [];
                if (isCharging() && chargeShot.amount > 0 && mainPlayer && mainPlayer.isAlive) {
                    chargeRings.push({ e: mainPlayer, amount: chargeShot.amount });
                }
                for (const ent of entities) {
                    if (ent === mainPlayer || !ent.isAlive) continue;
                    if (aiIsDrawing(ent) && ent.aiChargeAmount > 0) {
                        chargeRings.push({ e: ent, amount: ent.aiChargeAmount });
                    }
                }
                for (const ring of chargeRings) {
                    const p = ring.e;
                    const cc = chargeConfigOf(p.weaponConfig);
                    const tint = (cc && cc.ring) || '#ffffff';
                    const full = ring.amount >= 0.99;
                    const r = CHARACTER_SIZE + 8 + ring.amount * 10;
                    const arcEnd = -Math.PI / 2 + ring.amount * Math.PI * 2;
                    ctx.save();
                    // Track glow
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, r, -Math.PI / 2, arcEnd);
                    ctx.strokeStyle = full ? '#ffffff' : tint;
                    ctx.lineWidth = 4;
                    ctx.shadowBlur = 18;
                    ctx.shadowColor = full ? ((cc && cc.ringFull) || '#ffffff') : tint;
                    ctx.globalAlpha = 0.55 + ring.amount * 0.45;
                    ctx.stroke();
                    // Pulsing dot at tip
                    const tipX = p.x + Math.cos(arcEnd) * r;
                    const tipY = p.y + Math.sin(arcEnd) * r;
                    ctx.beginPath();
                    ctx.arc(tipX, tipY, 3 + ring.amount * 3, 0, Math.PI * 2);
                    ctx.fillStyle = tint;
                    ctx.shadowBlur = 20;
                    ctx.globalAlpha = 1;
                    ctx.fill();
                    // Charge label when nearly full
                    if (ring.amount >= 0.9) {
                        ctx.fillStyle = '#ffffff';
                        ctx.font = `10px ${getCanvasFontFamily()}`;
                        ctx.textAlign = 'center';
                        ctx.fillText('CHARGED', p.x, p.y - CHARACTER_SIZE - 15);
                    }
                    ctx.restore();
                }

                // Restore screen shake transform
                ctx.restore();
            }

            function hpColor(pct) {
                if (pct > 0.5) {
                    const t = (pct - 0.5) / 0.5;
                    const r = Math.round(255 * (1-t)), g = 255, b = 0;
                    return `rgb(${r},${g},${b})`;
                } else {
                    const t = pct / 0.5;
                    const r = 255, g = Math.round(255 * t), b = 0;
                    return `rgb(${r},${g},${b})`;
                }
            }

            // updateHUD runs every frame. Writing to .style / .textContent always
            // dirties layout even when the value is identical, so cache the last
            // written value on the node and skip no-op writes.
            /** Point the enemy half of the HUD — portrait, name, weapon, health bar —
             *  at a character. Given the roster entry it renders exactly as that
             *  character would if it had been the opponent from the start, which is
             *  the whole point: mid-match, Jabba has to look like a picked opponent
             *  rather than a bolted-on boss.
             *
             *  `entity` is what the bar and HP readout follow each frame; `charData`
             *  supplies the cosmetic identity. They are separate arguments because
             *  the entity is spawned in code and the roster entry is data. */
            function setEnemyHud(charData, entity) {
                hudEnemyEntity = entity;

                const enemyPortrait = document.getElementById('enemyPortrait');
                if (enemyPortrait) {
                    enemyPortrait.textContent = weaponEmoji[charData.weapon] || '⚔️';
                    enemyPortrait.style.color = entity.color;
                    enemyPortrait.style.borderColor = entity.color;
                    enemyPortrait.style.boxShadow = `0 0 10px ${entity.color}55`;
                }

                enemyLabel.textContent = entity.name;
                enemyLabel.style.color = entity.color;
                enemyHealthBar.style.backgroundColor = entity.color;

                const enemyWeaponLabel = document.getElementById('enemyWeaponLabel');
                if (enemyWeaponLabel) enemyWeaponLabel.textContent = getWeapon(charData).label.toUpperCase();

                // Opponents flagged noHealthBar (Carbonite Han) show no bar and no
                // HP readout. Set explicitly both ways rather than only hidden: the
                // HUD nodes live across matches and across this swap, so a bar
                // hidden once would stay hidden for every opponent after it — which
                // is exactly what would happen to Jabba, taking over from Han.
                const hideHp = !!charData.noHealthBar;
                const hpContainer = enemyHealthBar.parentElement;
                if (hpContainer) hpContainer.style.display = hideHp ? 'none' : '';
                if (enemyHealthText) enemyHealthText.style.display = hideHp ? 'none' : '';
            }

            function setBarStyle(el, pct) {
                if (!el) return;
                const w = `${pct * 100}%`;
                const c = hpColor(pct);
                if (el._lastW !== w) { el.style.width = w; el._lastW = w; }
                if (el._lastC !== c) { el.style.backgroundColor = c; el._lastC = c; }
            }
            function setTextCached(el, str) {
                if (!el) return;
                if (el._lastText !== str) { el.textContent = str; el._lastText = str; }
            }

            /** The health line for one HUD panel. Whoever is holding a weapon with
             *  a magazine shows it — the player always did, and the opponent does
             *  now, so counting an enemy's shots and catching them mid-reload is
             *  information the fight actually gives you. Weapons without a
             *  magazine (sabers, the plain blaster) just show health. */
            function hudStatusText(ent) {
                const hp = `HP: ${Math.round(ent.health)}`;
                const cfg = ent.weaponConfig;
                if (!cfg || cfg.magSize == null || ent.magAmmo == null) return hp;
                if (ent.isReloading) return `${hp} | RELOADING...`;
                return `${hp} | AMMO: ${ent.magAmmo}/${cfg.magSize}`;
            }

            function updateHUD() {
                if (!mainPlayer || !mainEnemy) return;
                // The enemy panel does not always track mainEnemy: the Cloud City
                // rescue hands it over to Jabba once Han is freed. See setEnemyHud().
                const hudEnemy = hudEnemyEntity || mainEnemy;
                const pPct = mainPlayer.health / mainPlayer.maxHealth;
                setBarStyle(playerHealthBar, pPct);
                setTextCached(playerHealthText, hudStatusText(mainPlayer));
                if (halloweenRun && halloweenRun.wave && !halloweenRun.wave.boss) {
                    // A wave round has no one opponent, so the enemy bar is the wave:
                    // how many of the round's skeletons are still to be put down,
                    // standing or yet to walk in.
                    const left = halloweenWaveLeft();
                    setBarStyle(enemyHealthBar, left / halloweenRun.wave.total);
                    setTextCached(enemyHealthText, `${left} LEFT`);
                } else {
                    const ePct = hudEnemy.health / hudEnemy.maxHealth;
                    setBarStyle(enemyHealthBar, ePct);
                    setTextCached(enemyHealthText, hudStatusText(hudEnemy));
                }

                const timerEl = document.getElementById('hudTimer');
                if (timerEl && timerEl.style.display !== 'none') {
                    const rs = Math.max(0, Math.floor(seriesTimeRemaining));
                    const m = Math.floor(rs / 60);
                    const s = rs % 60;
                    setTextCached(timerEl, `${m}:${s.toString().padStart(2, '0')}`);
                    if (rs <= 30) timerEl.classList.add('sudden-death');
                    else timerEl.classList.remove('sudden-death');
                }

                // This used to blow away and rebuild every backup bar via innerHTML
                // on both teams, every frame — a full teardown + style recalc +
                // layout 120x/second. Now nodes are only created or removed when the
                // number of living backups actually changes.
                const renderSubBars = (teamStr, containerId) => {
                    const container = document.getElementById(containerId);
                    if (!container) return;
                    const backups = subBarScratch;
                    backups.length = 0;
                    for (let i = 0; i < entities.length; i++) {
                        const e = entities[i];
                        if (e.isAlive && !e.isMainEntity && e.team === teamStr) backups.push(e);
                    }
                    while (container.childElementCount > backups.length) {
                        container.removeChild(container.lastElementChild);
                    }
                    while (container.childElementCount < backups.length) {
                        const wrapper = document.createElement('div');
                        wrapper.style.cssText = 'flex:1;background-color:#111;border-radius:3px;border:1px solid #444;overflow:hidden;';
                        const bar = document.createElement('div');
                        bar.style.height = '100%';
                        wrapper.appendChild(bar);
                        container.appendChild(wrapper);
                    }
                    for (let i = 0; i < backups.length; i++) {
                        const wrapper = container.children[i];
                        if (!wrapper || !wrapper.firstElementChild) continue;
                        setBarStyle(wrapper.firstElementChild, backups[i].health / backups[i].maxHealth);
                    }
                };

                renderSubBars('player', 'playerSubBars');
                renderSubBars('enemy', 'enemySubBars');

            }

            function saveMatchHistory(playerWon) {
                try {
                    const history = loadVersioned('galacticDuelHistory', []);
                    history.unshift({
                        date: new Date().toLocaleDateString(),
                        player: pCharData ? (pCharData.arenaName || pCharData.name) : '?',
                        enemy: eCharData ? (eCharData.arenaName || eCharData.name) : '?',
                        result: playerWon ? 'W' : 'L',
                        difficulty: currentDifficulty,
                        damage: playerDamageDealt,
                        accuracy: playerShotsFired > 0 ? Math.min(100, Math.round((playerHitsLanded / playerShotsFired) * 100)) : null
                    });
                    if (history.length > MAX_HISTORY_ENTRIES) history.pop();
                    saveVersioned('galacticDuelHistory', history);

                    // Show streak banner and check achievements
                    let streak = 0;
                    for (const h of history) { if (h.result === 'W') streak++; else break; }
                    const banner = document.getElementById('streakBanner');
                    if (streak >= 2 && playerWon) {
                        banner.textContent = `🔥 ${streak}-WIN STREAK`;
                        banner.style.display = 'block';
                        setTimeout(() => { banner.style.display = 'none'; }, 3500);
                    }
                    
                    // Win streak achievements
                    if (streak >= 3) tryUnlockAchievement('winStreak3');
                    if (streak >= 5) tryUnlockAchievementWithAnnouncement('winStreak5', 'Five consecutive victories have proven your mastery of the blade. Mace Windu (Elite) has joined your roster.', '#9900cc');
                    if (streak >= 10) tryUnlockAchievement('winStreak10');
                } catch(e) {}
            }

            /*  The one place match stats and contract progress are written. Called
             *  off the round result, beside saveMatchHistory(), because everything it
             *  needs — the fighters, the arena, the damage and accuracy counters —
             *  is already settled there and nowhere else has to be touched.
             *
             *  Deliberately not in the game loop: a per-frame increment would be a
             *  second source of truth for numbers this already owns.                */
            function recordMatchStats(playerWon) {
                try {
                    if (!pCharData) return;
                    const pid       = achievementCharId(pCharData);
                    const weaponKey = getEquippedWeaponKey(pCharData.id, pCharData.weapon);
                    const accuracy  = playerShotsFired > 0
                        ? Math.min(100, Math.round((playerHitsLanded / playerShotsFired) * 100))
                        : null;
                    // An arena is "new" only if the player has never PICKED it. Zero
                    // Event stages choose their own, so they are not picks and do not
                    // close out the newArena contract.
                    const arenaIsNew = !matchStats.arenasPlayed.includes(currentArena);

                    const f = fighterStats(pid);
                    f.fights++;
                    if (playerWon) f.wins++;
                    f.damage += playerDamageDealt;
                    f.kills  += killCount;
                    // 10 for turning up, 15 for winning, 1 per 100 damage dealt.
                    f.xp += 10 + (playerWon ? 15 : 0) + Math.floor(playerDamageDealt / 100);

                    if (arenaIsNew) matchStats.arenasPlayed.push(currentArena);
                    if (weaponKey && !matchStats.weaponsUsed.includes(weaponKey)) {
                        matchStats.weaponsUsed.push(weaponKey);
                    }
                    saveMatchStats();

                    // playerWins was already incremented by endGame, so this round is
                    // the deciding one exactly when the threshold has just been met.
                    const saberWeapons = ['lightsaber', 'darksaber'];
                    const roundCtx = {
                        won: playerWon,
                        seriesWon: playerWon && playerWins >= SERIES_WINS_NEEDED,
                        difficulty: currentDifficulty,
                        isSaber: saberWeapons.includes(pCharData.weapon),
                        isBlaster: pCharData.weapon === 'blaster',
                        arenaIsNew,
                        enemyIsVillain: !!(eCharData && VILLAIN_ID_SET.has(eCharData.id)),
                        damage: playerDamageDealt,
                        accuracy,
                        kills: killCount,
                        // From here down, only Stark's board asks.
                        charId: pCharData.id,
                        isIronMan: pCharData.id === 'ironman',
                        isGroot: pCharData.id === 'groot',
                        isMarvel: !!pCharData.marvel,
                        enemyIsMarvel: !!(eCharData && eCharData.marvel),
                        weaponKey,
                        specials: matchSpecialsUsed,
                        // playerTookDamage is already tracked for the low-health
                        // vignette, so 'flawless' costs nothing new.
                        flawless: playerWon && !playerTookDamage
                    };
                    advanceContracts(roundCtx);
                    advanceStarkContract(roundCtx);
                    advanceGrootContract(roundCtx);
                } catch (e) {}
            }

            /** Feeds one round's result to today's three contracts. A contract that
             *  is already claimed is left alone; progress is clamped at the target so
             *  a bar cannot read past full. */
            function advanceContracts(ctx) {
                let changed = false;
                contractState.list.forEach(c => {
                    if (c.claimed || c.progress >= c.target) return;
                    const def = contractById(c.id);
                    if (!def) return;
                    const step = def.advance(ctx) || 0;
                    if (step > 0) {
                        c.progress = Math.min(c.target, c.progress + step);
                        changed = true;
                    }
                });
                if (changed) saveVersioned('galacticDuelContracts', contractState);
            }

            function updateRoundPips() {
                const render = (containerId, wins, color) => {
                    const container = document.getElementById(containerId);
                    if (!container) return;
                    container.style.display = '';
                    container.innerHTML = '';
                    container.style.color = color;
                    for (let i = 0; i < SERIES_WINS_NEEDED; i++) {
                        const pip = document.createElement('div');
                        pip.className = 'round-pip' + (i < wins ? ' won' : '');
                        container.appendChild(pip);
                    }
                };
                if (pCharData) render('playerPips', playerWins, pCharData.color);
                if (eCharData) render('enemyPips', enemyWins, eCharData.color);
            }

            function updateComboCounter() {
                const comboEl = document.getElementById('comboCounter');
                if (!comboEl) return;
                
                const now = gameNow();
                const activeCombos = comboKills.filter(k => now - k < 5000);
                
                if (activeCombos.length >= 2) {
                    comboEl.innerHTML = `<span class="combo-label">COMBO</span>${activeCombos.length}x`;
                    comboEl.classList.add('active');
                    
                    // Auto-hide after combo window expires
                    clearTimeout(window.comboTimeout);
                    window.comboTimeout = setTimeout(() => {
                        comboEl.classList.remove('active');
                    }, 5000);
                } else {
                    comboEl.classList.remove('active');
                }
            }

            // Every banner a round can end on, keyed by how it ended and then by who
            // won. endGame takes those two facts and looks the wording up, rather
            // than each call site supplying its own text and colour — which is what
            // let the two Jabba endings drift into private vocabulary, and what once
            // made a hex string the real source of truth for whether the player won.
            //
            // Colour always follows the outcome, never the ending: a win on the clock
            // is still blue. Adding another kind of ending means adding one entry
            // here, not another pair of literals at a call site.
            const ROUND_ENDINGS = {
                knockout: {
                    win:  { message: 'VICTORY ACHIEVED', color: '#00A4FF' },
                    loss: { message: 'DEFEATED',         color: '#FF3333' },
                },
                // Clock ran out — decided on remaining health, so it is called out
                // separately. The player should know they were not knocked down.
                timeout: {
                    win:  { message: 'TIME — VICTORY!',  color: '#00A4FF' },
                    loss: { message: 'TIME — DEFEATED',  color: '#FF3333' },
                },
            };

            function endGame(playerWon, ending = 'knockout') {
                // An event round has its own ending: no series, no history, no
                // mastery. Everything below is for a duel.
                if (halloweenRun && !halloweenRun.over) { endHalloweenRound(playerWon); return; }
                const table = ROUND_ENDINGS[ending] || ROUND_ENDINGS.knockout;
                const { message, color } = playerWon ? table.win : table.loss;

                // Stop timer, countdown leftovers, looping SFX, and the game loop
                stopBattleSystems();

                if (playerWon) playerWins++; else enemyWins++;
                updateRoundPips();
                saveMatchHistory(playerWon);
                recordMatchStats(playerWon);

                // Losing an equipped sprite is the price of ANY defeat — a single
                // round, not the series. Losing round one of a best-of-three takes
                // it, and the rest of the series is then fought without it.
                //
                // Sits here, on the round result itself, rather than in the
                // seriesOver branch below: that branch only runs on the last round
                // of a series, so a loss in an earlier round would never reach it.
                //
                // forceShow because announcements are deferred during a match and
                // this one has to land on the defeat that caused it, not surface
                // later behind a queue.
                if (!playerWon && equippedSpriteId) {
                    const lost = getSprite(equippedSpriteId);
                    loseSprite(equippedSpriteId);
                    if (lost) {
                        showAnnouncement(`Defeat has cost you the ${lost.name} sprite. It is now listed in the Shop for ${lost.cost} credits, or you can find it again on the battlefield.`,
                            spriteRarity(lost).color, 6000, `${lost.icon} SPRITE LOST`, 100, true);
                    }
                }

                // ── Achievement checks ─────────────────────────────────
                if (playerWon) {
                    totalWins++;
                    if (totalWins === 1) tryUnlockAchievementWithAnnouncement('firstWin', 'Your first victory is won, and a new path opens before you. Finn (Elite) has joined your roster.', '#0066ff');
                    if (eCharData && eCharData.isDroid) tryUnlockAchievement('droidSlayer');
                    if (currentArena === 'hoth') tryUnlockAchievement('hothSurvivor');
                    if (!playerTookDamage) tryUnlockAchievement('noHits');
                    if (!playerTookDamage) tryUnlockAchievement('perfectVictory');
                    arenasWonIn.add(currentArena);
                    if (arenasWonIn.size >= 5) tryUnlockAchievement('arenaExplorer');
                    if (eCharData) {
                        villainsDefeated.add(eCharData.id);
                        if (villainsDefeated.size >= 5) tryUnlockAchievement('villainSlayer');
                        if (achievementCharId(eCharData) === 'vader') tryUnlockAchievement('vaderSlayer');
                    }
                    if (pCharData && BOUNTY_HUNTER_IDS.has(pCharData.id)) tryUnlockAchievement('bountyHunter');
                    if (pCharData && pCharData.id === 'han') {
                        hanWinCount++;
                        if (hanWinCount >= 3) tryUnlockAchievement('millenniumRun');
                    }
                    const saberWeapons = ['lightsaber','darksaber'];
                    if (pCharData && saberWeapons.includes(pCharData.weapon)) {
                        saberWinCount++;
                        if (saberWinCount >= 3) tryUnlockAchievement('saberMaster');
                        saberWinCount2++;
                        if (saberWinCount2 >= 5) tryUnlockAchievement('saberMaster2');
                    }
                    if (pCharData && pCharData.weapon === 'blaster') {
                        blasterWinCount++;
                        if (blasterWinCount >= 5) tryUnlockAchievement('blasterMaster');
                    }
                    if (currentArena === 'space') {
                        spaceWinCount++;
                        if (spaceWinCount >= 5) tryUnlockAchievement('spaceSpecialist');
                    }
                    
                    // Vader consecutive wins tracking
                    if (achievementCharId(pCharData) === 'vader') {
                        if (lastPlayedCharacterId === 'vader') {
                            vaderConsecutiveWins++;
                        } else {
                            vaderConsecutiveWins = 1;
                        }
                        if (vaderConsecutiveWins >= 10) {
                            tryUnlockAchievementWithAnnouncement('vaderConquest', 'Ten consecutive conquests have unleashed his true power. Darth Vader (Elite) has joined your roster.', '#cc0000');
                        }
                    } else {
                        vaderConsecutiveWins = 0;
                    }
                    lastPlayedCharacterId = achievementCharId(pCharData);
                    
                    // Villain win tracking for jediHunter achievement
                    if (playerWon && pCharData && VILLAIN_ID_SET.has(pCharData.id)) {
                        villainWinCount++;
                        if (villainWinCount >= 10) {
                            tryUnlockAchievementWithAnnouncement('jediHunter', "Ten villainous victories have proven you a true Jedi Hunter. Gen. Grievous has joined your roster.", '#00ffcc');
                        }
                    }
                    
                    persistAchievementCounters();
                    
                    // Senator Palpatine unlock: Win as Darth Maul vs Qui-Gon on Naboo
                    if (pCharData && eCharData && currentArena === 'naboo' && !gameUnlocks.senatorPalpatine) {
                        if (pCharData.id === 'maul' && eCharData.id === 'quigon') {
                            gameUnlocks.senatorPalpatine = true;
                            persistGalacticUnlocks();
                            rebuildSecretRoster();
                            updateSecretFactionSectionVisibility();
                            showAnnouncement("Qui-Gon has fallen on Naboo, exactly as the Sith foresaw. Senator Palpatine has joined your roster.", "#c8a84b", 6000, "🔓 CHARACTER UNLOCKED", 100);
                        }
                    }

                    // Lord Treat and Lord Trick, off five round wins as their
                    // general. recordMatchStats() has already counted this one.
                    checkHalloweenLordUnlocks();

                }

                // A loss ends a run of consecutive Vader wins (Dark Lord's Reign).
                // Losing used to leave the count alone; what broke the run was
                // leaving the series, which also wiped every other counter.
                if (!playerWon && vaderConsecutiveWins > 0) {
                    vaderConsecutiveWins = 0;
                    persistAchievementCounters();
                }

                // Senator Palpatine unlock (defeat path): Lose as Qui-Gon vs Darth Maul on Naboo
                if (!playerWon && pCharData && eCharData && currentArena === 'naboo' && !gameUnlocks.senatorPalpatine) {
                    if (pCharData.id === 'quigon' && eCharData.id === 'maul') {
                        gameUnlocks.senatorPalpatine = true;
                        persistGalacticUnlocks();
                        rebuildSecretRoster();
                        updateSecretFactionSectionVisibility();
                        showAnnouncement("The Jedi could not stop what was already set in motion on Naboo. Senator Palpatine has joined your roster.", "#c8a84b", 6000, "🔓 CHARACTER UNLOCKED", 100);
                    }
                }

                // Tarfful unlock: Defeat Commander Gree as Yoda on Kashyyyk
                if (playerWon && pCharData && eCharData && currentArena === 'kashyyyk' && !gameUnlocks.tarffulUnlock) {
                    if (pCharData.id === 'yoda' && eCharData.id === 'gree') {
                        gameUnlocks.tarffulUnlock = true;
                        persistGalacticUnlocks();
                        rebuildSecretRoster();
                        updateSecretFactionSectionVisibility();
                        showAnnouncement("Commander Gree has fallen to Yoda's blade on Kashyyyk. Tarfful has joined your roster.", "#8b7355", 6000, "🔓 CHARACTER UNLOCKED", 100);
                    }
                }

                // The results overlay is shared, and the event rewrites its buttons.
                // Restoring the shipped labels here — before anything decides to
                // change them — is what stops one mode's wording leaking into the
                // other's screens.
                resetBorrowedButtonLabels();
                // The event's team list shares this box too.
                const teamSummary = document.getElementById('halloweenTeamSummary');
                if (teamSummary) teamSummary.style.display = 'none';

                const seriesOver = playerWins >= SERIES_WINS_NEEDED || enemyWins >= SERIES_WINS_NEEDED;
                const nextRoundBtn = document.getElementById('nextRoundButton');
                const rematchBtn   = document.getElementById('rematchButton');
                const seriesDisplay = document.getElementById('seriesScoreDisplay');

                if (seriesOver) {
                    nextRoundBtn.style.display = 'none';
                    rematchBtn.style.display = 'inline-block';
                    const finalMsg = playerWins >= SERIES_WINS_NEEDED ? '★ SERIES VICTORY ★' : '✗ SERIES DEFEAT';
                    messageText.textContent = finalMsg;
                    seriesDisplay.textContent = `FINAL: ${playerWins} — ${enemyWins}`;

                    if (playerWins >= SERIES_WINS_NEEDED) {
                        spawnVictoryConfetti();
                    }

                    // Award credits for winning series
                    if (playerWins >= SERIES_WINS_NEEDED) {
                        let creditsEarned = 10; // Default credits per series

                        // Calculate bonus credits based on opponent strength in freeplay
                        if (pCharData && eCharData) {
                            const playerHP = pCharData.hp;
                            const enemyHP = eCharData.hp;
                            const strengthRatio = enemyHP / playerHP;

                            // Bonus credits for stronger opponents
                            if (strengthRatio > 1.5) {
                                creditsEarned += 15; // Very strong opponent
                            } else if (strengthRatio > 1.2) {
                                creditsEarned += 10; // Strong opponent
                            } else if (strengthRatio > 1.0) {
                                creditsEarned += 5; // Slightly stronger opponent
                            }

                            // Difficulty bonus
                            if (currentDifficulty === 'legend') {
                                creditsEarned += 15;
                            } else if (currentDifficulty === 'hard') {
                                creditsEarned += 10;
                            } else if (currentDifficulty === 'easy') {
                                creditsEarned = Math.max(5, creditsEarned - 5);
                            }
                        }

                        const gained = awardCredits(creditsEarned);
                        // One decided series won is what unlocks the Zero Event. This
                        // is the only place a series is settled in the player's
                        // favour, so it is the only place that has to say so.
                        hasWonSeries = true;
                        saveGameSettings();
                        refreshSplashState();
                        showAnnouncement(creditAwardLine(gained), '#ffd700', 3000, 'CREDITS', 40);
                    }
                } else {
                    nextRoundBtn.style.display = 'inline-block';
                    rematchBtn.style.display = 'none';
                    messageText.textContent = message;
                    seriesDisplay.textContent = `SERIES: ${playerWins} — ${enemyWins}`;
                }
                seriesDisplay.style.display = 'block';

                messageText.style.color = color;
                messageText.style.textShadow = `0 0 15px ${color}`;
                document.querySelector('.message-box').style.borderColor = color;

                const elapsed = Math.round((gameNow() - gameStartTime) / 1000);
                const mins = Math.floor(elapsed / 60);
                const secs = elapsed % 60;
                const endTimeEl = document.getElementById('endTime');
                const endKillsEl = document.getElementById('endKills');
                const endHPEl = document.getElementById('endHP');
                if (endTimeEl) endTimeEl.textContent = `${mins}:${secs.toString().padStart(2,'0')}`;
                if (endKillsEl) endKillsEl.textContent = killCount;
                if (endHPEl) endHPEl.textContent = mainPlayer ? Math.max(0, Math.round(mainPlayer.health * 10) / 10) : 0;
                if (endTimeEl) endTimeEl.style.color = color;
                if (endKillsEl) endKillsEl.style.color = color;
                if (endHPEl) endHPEl.style.color = color;

                // Post-match round stats
                const accPct = playerShotsFired > 0 ? Math.min(100, Math.round((playerHitsLanded / playerShotsFired) * 100)) : 0;
                const endDamageEl = document.getElementById('endDamage');
                const endHitsEl = document.getElementById('endHits');
                const endAccuracyEl = document.getElementById('endAccuracy');
                if (endDamageEl) endDamageEl.textContent = playerDamageDealt;
                if (endHitsEl) endHitsEl.textContent = playerHitsLanded;
                if (endAccuracyEl) endAccuracyEl.textContent = playerShotsFired > 0 ? accPct + '%' : '—';
                if (endDamageEl) endDamageEl.style.color = color;
                if (endHitsEl) endHitsEl.style.color = color;
                if (endAccuracyEl) endAccuracyEl.style.color = color;

                // Speed Demon achievement check
                if (playerWon && elapsed < 30) {
                    tryUnlockAchievementWithAnnouncement('speedDemon', 'A duel won in under thirty seconds — speed worthy of a Sith Lord. Darth Maul (Elite) has joined your roster.', '#cc0000');
                }

                // Every round, not just the last one, and last, after everything
                // above has had its say. It used to sit inside the series-over
                // branch, before the series credits and Speed Demon: anything
                // earned in an earlier round was thrown away by Next Round, and
                // the credits line went up live in the same instant as the first
                // held reward and replaced it. Now it all queues in order.
                flushAnnouncementQueue();

                messageOverlay.style.display = 'flex';
                updateMobileControlsVisibility();
                setTimeout(() => focusFirstVisibleButton(messageOverlay), 0);
            }

            function startTimer() {
                // An event round has no clock: it ends when the wave is dead or the
                // team is. The timer element stays hidden, so updateHUD skips it.
                if (halloweenRun) return;
                const timerEl = document.getElementById('hudTimer');
                if (timerEl) {
                    timerEl.style.display = 'block';
                    timerEl.classList.remove('sudden-death');
                    // Don't reset seriesTimeRemaining here - setupGame sets it for every round
                    const m = Math.floor(seriesTimeRemaining / 60);
                    const s = Math.floor(seriesTimeRemaining % 60);
                    setTextCached(timerEl, `${m}:${s.toString().padStart(2, '0')}`);
                }
            }

            function gameLoop(timeStamp) {
                // Hard stop if the player has left the fight (menu / quit / end screen)
                if (canvas.style.display !== 'block' || countdownActive) {
                    gameLoopId = 0;
                    return;
                }
                if (messageOverlay && messageOverlay.style.display === 'flex') {
                    gameLoopId = 0;
                    return;
                }
                // Paused means paused, whatever is queued.
                //
                // openPauseMenu() stops the game by cancelling the pending frame and
                // nothing else, which works only for as long as exactly one frame is
                // ever in flight. Anything that queues a second one — a mid-frame
                // re-setup, a gamepad press handled from inside the loop, a rapid
                // pause/resume — leaves an orphan that keeps calling itself, and the
                // fight carries on underneath the menu with no way to stop it.
                //
                // Checking the flag here ends that whole class of problem: an orphan
                // frame arrives, sees the pause, and retires itself instead of
                // scheduling another.
                if (gamePaused) {
                    gameLoopId = 0;
                    return;
                }

                // Single stamp for the whole frame — update() and draw() read
                // frameNow rather than calling the clock again. Battle time, not
                // wall time: see BATTLE CLOCK at the top of the file.
                frameNow = gameNow();

                const ts = timeStamp ?? performance.now();
                const rawDt = lastGameFrameTime ? (ts - lastGameFrameTime) / 1000 : 1 / TARGET_FPS;
                lastGameFrameTime = ts;
                let dt = Math.min(Math.max(rawDt, 0.001), 0.05);
                if (!Number.isFinite(dt)) dt = 1 / TARGET_FPS;

                // FPS sample (wall-clock, not slow-mo scaled). Sampled unconditionally
                // so the auto-downgrade watchdog still has data with the meter hidden.
                fpsFrames++;
                fpsAccumMs += rawDt * 1000;
                if (fpsAccumMs >= 500) {
                    fpsDisplay = Math.round((fpsFrames * 1000) / fpsAccumMs);
                    fpsFrames = 0;
                    fpsAccumMs = 0;
                    if (showFpsMeter) {
                        const el = document.getElementById('fpsMeter');
                        if (el) {
                            el.textContent = `${fpsDisplay} FPS`;
                            el.classList.toggle('fps-warn', fpsDisplay < 50 && fpsDisplay >= 30);
                            el.classList.toggle('fps-bad', fpsDisplay < 30);
                        }
                    }
                    checkPerformanceWatchdog(fpsDisplay);
                }

                // Apply slow motion to delta time
                updateSlowMotion(dt);
                if (slowMotion.active) {
                    dt *= slowMotion.scale;
                }

                let tickScale = dt * TARGET_FPS;
                if (!Number.isFinite(tickScale)) tickScale = 1;

                if (!mainPlayer.isAlive) {
                    // In the Halloween event a dead fighter hands the player a living
                    // teammate; the round only ends when there is nobody to hand.
                    if (!(halloweenRun && halloweenTakeOver())) {
                        // The old Snap! also unlocked here, from dying as Fox to Vader.
                        // Krk! is specifically the player performing the neck snap, so
                        // the only place it can unlock is performNeckSnap().
                        endGame(false);
                        return;
                    }
                }

                if (specialCloudCityJabbaSpawned && specialCloudCityJabbaCharacter && !specialCloudCityJabbaCharacter.isAlive && mainPlayer.isAlive) {
                    if (!gameUnlocks.jabbaUnlock) {
                        tryUnlockAchievement('jabbaUnlock');
                        gameUnlocks.jabbaUnlock = true;
                        persistGalacticUnlocks();
                        rebuildSecretRoster();
                        updateSecretFactionSectionVisibility();
                        showAnnouncement('The crime lord of Tatooine has been brought down at last. Jabba the Hutt has joined your roster.', '#a67a1c', 5000, '🔓 CHARACTER UNLOCKED', 100);
                    }
                    endGame(true);
                    return;
                }
                
                // A Zero Event stage ends when the BOSS falls, not when the last
                // creeper does. The waves respawn, so waiting for the board to
                // clear would mean a stage that can never be finished — and the
                // player killing wave units after the boss is down is mopping up,
                // not still fighting.
                // Existence test only, so it short-circuits instead of building and
                // discarding an array of survivors every frame.
                //
                // The event's waves refill here, before the test below, so a board
                // that is empty for the 450ms between one skeleton falling and the
                // next walking in does not read as a cleared round.
                updateHalloweenWave();
                let anyEnemyAlive = false;
                for (let i = 0; i < entities.length && !anyEnemyAlive; i++) {
                    const e = entities[i];
                    if (e.team === 'enemy' && e.isAlive && !e.hasFled) { anyEnemyAlive = true; break; }
                }
                if (!anyEnemyAlive && !halloweenWaveHasMore()) {
                    if (eCharData && eCharData.id === 'sith_c3po') {
                        unlockUltimatePalpatine();
                    }
                    if (pCharData && pCharData.id === 'obiwan' && currentArena === 'mustafar' && eCharData && eCharData.id === 'sith_anakin') {
                        tryUnlockAchievement('highGround');
                        if (!gameUnlocks.charredAnakin) {
                            gameUnlocks.charredAnakin = true;
                            persistGalacticUnlocks();
                            rebuildSecretRoster();
                            updateSecretFactionSectionVisibility();
                            showAnnouncement("Anakin has fallen on Mustafar, scarred but not broken. Charred Anakin has joined your roster.", "#ff4400", 6000, "🔓 CHARACTER UNLOCKED", 100);
                        }
                    }
                    if (achievementCharId(pCharData) === 'mando' && currentArena === 'mandalore' && eCharData && eCharData.id === 'gideon') {
                        tryUnlockAchievementWithAnnouncement('mandoDarksaber', 'This is the way — the Darksaber recognizes its rightful bearer. The Mandalorian (Elite) has joined your roster.', '#8a8f99');
                    }
                    if (pCharData && pCharData.id === 'raddus' && currentArena === 'deathstar' && eCharData && eCharData.id === 'krennic') {
                        tryUnlockAchievementWithAnnouncement('bazeUnlock', 'By defeating the Director, you have honored the sacrifice of the Rogue One crew. Baze Malbus has joined your roster.', '#7a6a55');
                    }
                    if (achievementCharId(pCharData) === 'cluster' && currentArena === 'clustercoast') {
                        tryUnlockAchievement('poiRoi');
                    }
                    if (pCharData && pCharData.id === ZERO_POINT_ENCOUNTER.playerId
                        && currentArena === ZERO_POINT_ENCOUNTER.arena
                        && eCharData && eCharData.id === ZERO_POINT_ENCOUNTER.opponentId) {
                        unlockGeno();
                    }
                    endGame(true);
                    return;
                }

                if (pCharData && pCharData.id === 'jabba') {
                    if (gameNow() > playableJabbaNextGuard) {
                        if (playableJabbaGuardCount < 6) {
                            spawnPlayableGamorreanGuard();
                            playableJabbaNextGuard = gameNow() + 2200;
                        } else {
                            endGame(false);
                            return;
                        }
                    }
                }

                // No clock in a Halloween round — see startTimer().
                if (!halloweenRun) {
                    seriesTimeRemaining -= dt;
                    if (seriesTimeRemaining <= 0) {
                        seriesTimeRemaining = 0;
                        if (!mainPlayer || !mainEnemy) return;
                        const pPct = mainPlayer.health / mainPlayer.maxHealth;
                        const ePct = mainEnemy.health / mainEnemy.maxHealth;
                        // The player has to be strictly ahead to take a round on time.
                        // A dead heat used to go to the player, which paid out a win
                        // for three minutes of hiding behind a crate with neither side
                        // landing a hit. Level on health is not winning.
                        if (pPct > ePct) endGame(true, 'timeout');
                        else endGame(false, 'timeout');
                        return;
                    }
                }

                if (debugStrictErrors) {
                    // Development: let it throw. Swallowing the error keeps the loop
                    // running on a corrupted frame, which turns a crash into a subtle
                    // misbehaviour several seconds later that is far harder to trace.
                    update(tickScale);
                    draw(tickScale);
                } else {
                    // Shipped build: a single bad frame should not end the match.
                    try {
                        update(tickScale);
                        draw(tickScale);
                    } catch (err) {
                        console.error('Galactic Legends game loop error:', err);
                    }
                }
                
                updateHUD();
                updateComboCounter();
                updateTouchActionButtons();
                updateAimCursor();
                gameLoopId = requestAnimationFrame(gameLoop);
            }

            /** How many world units across the current arena is, per screen pixel.
             *  1 for every ordinary arena; larger makes the field bigger than the
             *  window and zooms the view out to match. */
            function arenaWorldScale() {
                const a = ARENAS[currentArena];
                return (a && a.worldScale) || 1;
            }

            /** World units → device pixels. Dividing by worldScale is the entire
             *  mechanism behind an oversized arena: gameplay keeps working in world
             *  units and the view simply pulls back far enough to show them all. */
            function applyWorldTransform() {
                ctx.setTransform(canvasDpr / worldScale, 0, 0, canvasDpr / worldScale, 0, 0);
            }

            function resizeCanvas() {
                // Use the container's actual rendered size so the logical resolution
                // matches whatever window size the player has.
                const container = canvas.parentElement;
                const cssW = container.clientWidth  || (window.innerWidth  - 20);
                const cssH = container.clientHeight || (window.innerHeight - 20);

                // The world may be larger than the screen showing it.
                worldScale = arenaWorldScale();
                canvasLogicalW = cssW * worldScale;
                canvasLogicalH = cssH * worldScale;

                // Cap device pixel ratio on Low/Balanced to cut fill-rate cost
                let dprCap = performanceMode === 'low' ? 1 : performanceMode === 'balanced' ? 1.5 : 2;
                // Phones report DPR 3 with a fraction of a desktop's fill rate.
                // Rendering 3x native is the single largest mobile cost, so cap harder.
                if (isCoarsePointer()) dprCap = Math.min(dprCap, performanceMode === 'high' ? 1.5 : 1);
                canvasDpr = Math.min(dprCap, window.devicePixelRatio || 1);
                // Backing store is sized from the SCREEN, not the world — a bigger
                // arena is shown zoomed out, not rendered into a bigger buffer.
                canvas.width = Math.floor(cssW * canvasDpr);
                canvas.height = Math.floor(cssH * canvasDpr);
                applyWorldTransform();

                // Re-seed stars and arena particles to fit the canvas size
                initStars();
                invalidateArenaCaches();
                updateMobileControlsVisibility();
            }

            restartButton.addEventListener('click', () => {
                messageOverlay.style.display = 'none';
                canvas.style.display = 'none';
                hud.style.display = 'none';
                opponentMenu.style.display = 'none';
                stopBattleSystems();
                // "Quit the Event", when the event has borrowed this button: the run
                // is thrown away and the shared buttons get their words back.
                leaveHalloweenEvent();
                // "Return to Base" means the splash — Shop, Armory, Kamino and the
                // Dossier live there. It used to stop at fighter select, which had no
                // way onward to the splash, so credits won in a fight could not be
                // spent without reloading the page. showMainMenu() still runs first
                // for the menu music and the arena-button refresh it does.
                showMainMenu();
                showSplashMenu();
                selectedPlayerCharId = null;
                resetSeriesAndEffects();
                resetTouchInput();
                resetKeyboardInput();
                resizeCanvas();
                updateMobileControlsVisibility();
                flushAnnouncementQueue();
            });

            const nextRoundButton = document.getElementById('nextRoundButton');
            if (nextRoundButton) {
                nextRoundButton.addEventListener('click', () => {
                    messageOverlay.style.display = 'none';
                    updateMobileControlsVisibility();
                    // "Continue" in the Halloween event: the next round of the run.
                    if (halloweenRun && !halloweenRun.over) { setupHalloweenRound(); return; }
                    isNextRound = true;
                    setupGame(seriesPlayerCharId, seriesEnemyCharId);
                });
            }

            const rematchButton = document.getElementById('rematchButton');
            if (rematchButton) {
                rematchButton.addEventListener('click', () => {
                    messageOverlay.style.display = 'none';
                    updateMobileControlsVisibility();
                    // "Try Again" / "Run It Again" after a Halloween run: back to the
                    // splash and straight into the team card, because a run is never
                    // resumed and the team may have changed — someone may be dead.
                    if (halloweenRun) {
                        canvas.style.display = 'none';
                        hud.style.display = 'none';
                        stopBattleSystems();
                        resetSeriesAndEffects();
                        showMainMenu();
                        showSplashMenu();
                        leaveHalloweenEvent();
                        openHalloweenTeamCard();
                        return;
                    }
                    // Start a fresh series with the same matchup and arena
                    resetSeriesAndEffects();
                    setupGame(seriesPlayerCharId, seriesEnemyCharId);
                });
            }

            // ── PAUSE MENU ─────────────────────────────────────────────
            const pauseOverlay   = document.getElementById('pauseOverlay');
            const pauseResumeBtn = document.getElementById('pauseResumeBtn');
            const pauseQuitBtn   = document.getElementById('pauseQuitBtn');
            const pauseBackupBtn = document.getElementById('pauseBackupBtn');

            // Call for Backup is dev-only, but it is still an unlimited win button on
            // a dev host — a playtest propped up by six squads of reinforcements says
            // nothing about whether the balance actually works. Capped per series and
            // put on a cooldown so the number of times it was leaned on is visible.
            const PAUSE_BACKUP_MAX_USES = 3;
            const PAUSE_BACKUP_COOLDOWN_MS = 20000;
            let pauseBackupUses = 0;
            let pauseBackupReadyAt = 0;

            function resetPauseBackupBudget() {
                pauseBackupUses = 0;
                pauseBackupReadyAt = 0;
            }

            function refreshPauseBackupButton() {
                if (!pauseBackupBtn) return;
                // Dev hosts only, and only for the characters who actually have
                // troops to call: Jedi Generals and clone commanders.
                if (!isDevMenuHost() || !pCharData || !canCallBackup(pCharData.id)) {
                    pauseBackupBtn.style.display = 'none';
                    return;
                }
                pauseBackupBtn.style.display = 'block';
                const remaining = PAUSE_BACKUP_MAX_USES - pauseBackupUses;
                const cooldownLeft = Math.max(0, pauseBackupReadyAt - gameNow());
                if (remaining <= 0) {
                    pauseBackupBtn.disabled = true;
                    pauseBackupBtn.textContent = '📡 Backup Spent (0 left)';
                } else if (cooldownLeft > 0) {
                    pauseBackupBtn.disabled = true;
                    pauseBackupBtn.textContent = `📡 Backup Cooling (${Math.ceil(cooldownLeft / 1000)}s)`;
                } else {
                    pauseBackupBtn.disabled = false;
                    pauseBackupBtn.textContent = `📡 Call for Backup (${remaining} left)`;
                }
            }

            function isInBattle() {
                return canvas.style.display === 'block'
                    && messageOverlay.style.display !== 'flex';
            }

            function openPauseMenu() {
                if (!isInBattle() || gamePaused) return;
                gamePaused = true;
                // Stops every combat timer where it stands — see BATTLE CLOCK.
                freezeBattleClock();
                cancelAnimationFrame(gameLoopId);
                // Cut the loops, which would otherwise drone on under the menu.
                // One-shots still in flight are left to finish — they are brief, and
                // clipping them all at the instant of pausing sounds worse than
                // letting the last clash ring out.
                stopAllSfx();
                refreshPauseBackupButton();
                pauseOverlay.classList.add('active');
                updateMobileControlsVisibility();
                pauseResumeBtn.focus();
            }

            function closePauseMenu() {
                if (!gamePaused) return;
                gamePaused = false;
                resumeBattleClock();
                pauseOverlay.classList.remove('active');
                updateMobileControlsVisibility();
                // Bring back the blade hum the pause silenced. Lightning is not
                // restored here on purpose: it restarts on the next shot, and
                // resuming into a crackle the player is no longer causing is wrong.
                if (activeSaberHumKey) playSound(activeSaberHumKey);
                lastGameFrameTime = 0; // prevent huge dt spike after pause
                gameLoopId = requestAnimationFrame(gameLoop);
            }

            function spawnPauseBackup() {
                if (!mainPlayer || !mainPlayer.isAlive || !pCharData) return;

                // Jedi Generals get their own dedicated call-in: their clone
                // commander in person, plus two rank-and-file troopers.
                if (jediBackupLeaders.has(pCharData.id)) {
                    const commanderId = jediBackupArmy[pCharData.id];
                    const troopInfo = cloneBackupArmy[commanderId];
                    const commanderDef = characters.heroes.find(c => c.id === commanderId);

                    for (let i = 0; i < 2; i++) {
                        const angle = Math.random() * Math.PI * 2;
                        const dist  = 100 + Math.random() * 70;
                        const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.x + Math.cos(angle) * dist));
                        const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.y + Math.sin(angle) * dist));
                        const trooper = new Character(x, y, commanderDef ? commanderDef.color : pCharData.color, troopInfo ? troopInfo.name : 'Clone Trooper', 50, 'blaster', null, false, false, 'player', false, true, 12.5);
                        trooper.characterId     = troopInfo ? troopInfo.unitId : pCharData.id;
                        trooper.hasCalledBackup = true;
                        trooper.lastShotTime    = gameNow() - Math.random() * 600;
                        entities.push(trooper);
                    }

                    if (commanderDef) {
                        const angle = Math.random() * Math.PI * 2;
                        const dist  = 90 + Math.random() * 50;
                        const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.x + Math.cos(angle) * dist));
                        const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.y + Math.sin(angle) * dist));
                        const commander = new Character(x, y, commanderDef.color, commanderDef.name, 90, 'blaster', null, false, false, 'player', false, true, 18.75);
                        commander.characterId     = commanderDef.id;
                        commander.hasCalledBackup = true;
                        commander.lastShotTime    = gameNow() - Math.random() * 600;
                        entities.push(commander);
                    }

                    const jediLabel = commanderDef
                        ? `${commanderDef.name} and the ${troopInfo ? troopInfo.name + 's' : 'troopers'} move in, General!`
                        : 'Reinforcements inbound!';
                    showAnnouncement(jediLabel, '#00cfff', 3500, '📡 BACKUP CALLED', 50, true);
                    return;
                }

                // Clone commanders and captains call their own legion by name.
                // Anyone else has no one to call — canCallBackup() keeps the
                // button off for them.
                const baseId = resolveCloneBaseId(pCharData.id);
                if (!cloneBackupLeaders.has(baseId)) return;

                const info = cloneBackupArmy[baseId];
                const cloneCharDef = characters.heroes.find(c => c.id === info.unitId);
                const squadColor = cloneCharDef ? cloneCharDef.color : pCharData.color;

                const count = battalionSize(baseId);

                for (let i = 0; i < count; i++) {
                    const angle = (i / count) * Math.PI * 2 + Math.random() * 0.4;
                    const dist  = 100 + Math.random() * 70;
                    const x = Math.min(canvasLogicalW - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.x + Math.cos(angle) * dist));
                    const y = Math.min(canvasLogicalH - CHARACTER_SIZE, Math.max(CHARACTER_SIZE, mainPlayer.y + Math.sin(angle) * dist));
                    const trooper = new Character(x, y, squadColor, info.name, 50, 'blaster', null,
                                                  false, false, 'player', false, true, 20);
                    trooper.characterId     = info.unitId;
                    trooper.hasCalledBackup = true;
                    trooper.lastShotTime    = gameNow() - Math.random() * 600;
                    entities.push(trooper);
                }

                const rank = cloneCaptains.has(baseId) ? 'Captain' : 'Commander';
                showAnnouncement(`${info.name}s moving in, ${rank}!`, '#00cfff', 3500, '📡 BACKUP CALLED', 50, true);
            }

            pauseResumeBtn.addEventListener('click', closePauseMenu);
            pauseBackupBtn.addEventListener('click', () => {
                // Re-check rather than trusting the disabled attribute — the pad and
                // the keyboard can both reach this button.
                if (!pCharData || !canCallBackup(pCharData.id)) return;
                if (pauseBackupUses >= PAUSE_BACKUP_MAX_USES) return;
                if (gameNow() < pauseBackupReadyAt) return;
                pauseBackupUses++;
                pauseBackupReadyAt = gameNow() + PAUSE_BACKUP_COOLDOWN_MS;
                spawnPauseBackup();
                refreshPauseBackupButton();
                closePauseMenu();
            });
            pauseQuitBtn.addEventListener('click', () => {
                gamePaused = false;
                resumeBattleClock();
                pauseOverlay.classList.remove('active');
                canvas.style.display = 'none';
                hud.style.display = 'none';
                messageOverlay.style.display = 'none';
                stopBattleSystems();
                showMainMenu();
                // "Abandon the Run": the event started from the splash, so it ends
                // there too, not on a fighter select the player never visited.
                if (leaveHalloweenEvent()) showSplashMenu();
                selectedPlayerCharId = null;
                resetSeriesAndEffects();
                resetTouchInput();
                resetKeyboardInput();
                resizeCanvas();
                updateMobileControlsVisibility();
                flushAnnouncementQueue();
            });

            window.addEventListener('keydown', e => {
                const key = normalizeKey(e);
                if (!key) return;   // autofill / IME / synthetic event with no key
                keys[key] = true;
                lastKeyboardUseAt = Date.now();

                // Escape: toggle pause during battle
                if (key === 'Escape') {
                    if (gamePaused) {
                        closePauseMenu();
                    } else if (isInBattle()) {
                        openPauseMenu();
                    } else if (!e.defaultPrevented) {
                        // Out of battle, Escape on the two pick screens steps back
                        // one screen, as a gamepad's B already does. Only when one of
                        // them is the top layer: every overlay above them has its own
                        // Escape handling. Typing in a search box, it just leaves the
                        // box rather than throwing the player out of the screen.
                        const layer = getActiveUiLayer();
                        const active = document.activeElement;
                        if (layer && (layer.id === 'mainMenu' || layer.id === 'opponentMenu')) {
                            if (active && active.tagName === 'INPUT' && active.type === 'text') {
                                active.blur();
                            } else if (layer.id === 'mainMenu') {
                                showSplashMenu();
                            } else {
                                const back = document.getElementById('backBtn');
                                if (back) back.click();
                            }
                        }
                    }
                }

                // Both halves compare against the normalized name, so the combo
                // works whichever key is pressed first and whatever Shift is doing.
                if ((key === '4' && keys['f']) || (key === 'f' && keys['4'])) {
                    if (opponentMenu.style.display !== 'none') {
                        specialCloudCityJabbaForce = true;
                        showAnnouncement('Jabba test mode enabled. Next Cloud City Leia surprise will summon Carbonite Han.', '#ff6600', 4000, '🛠️ DEV MODE');
                    }
                }
            });
            window.addEventListener('keyup', e => {
                const key = normalizeKey(e);
                if (key) keys[key] = false;
            });

            // Focus left the window mid-press, so the keyup is never coming.
            // Without this, alt-tabbing while holding a movement key leaves the
            // fighter walking into a wall on return. Mouse buttons were already
            // cleared on blur for exactly this reason; keys were not.
            window.addEventListener('blur', resetKeyboardInput);
            document.addEventListener('visibilitychange', () => {
                if (!document.hidden) return;
                resetKeyboardInput();
                // Leaving the tab mid-fight pauses it. The browser stops drawing a
                // hidden tab, so the fight was frozen anyway — but the clock was not,
                // and looping sounds (Force Lightning, the Beam, the Flamethrower, a
                // saber hum) droned on with nobody there. openPauseMenu() freezes
                // the battle clock and cuts the loops; the player resumes when back.
                if (isInBattle() && !gamePaused) openPauseMenu();
            });

            window.addEventListener('resize', resizeCanvas);
            resizeCanvas();

            /*  Runs last on purpose. The splash is up from the first paint (CSS, not
             *  showSplashMenu), so its tiles have to be filled in here — and this is
             *  the first point at which everything they read is initialised, since
             *  forgedWeapons and createdCharacters are declared thousands of lines
             *  after loadGameSettings() is called.                                 */
            // Each step runs through bootStep(), so a bad save costs one step
            // rather than the whole start-up.
            bootStep(loadMatchStats);
            bootStep(loadContracts);
            // After the roster is built — it writes onto the character record, and
            // `characters` is a const declared far below loadGameSettings().
            bootStep(applyIronManMark);
            // After applyIronManMark(), because whether the board is closed at all
            // depends on the mark it just worked out.
            bootStep(loadStarkContract);
            // Same pair of calls the suit needs, for the same reasons: the level has
            // to be written onto the roster record before anything reads it, and the
            // standing order has to be restored before the Dossier can draw it.
            bootStep(applyGrootLevel);
            bootStep(loadGrootContract);
            // Both of the above rewrite a roster record's name, hp and weapon,
            // and both run after the columns were built. Without this the button
            // still said "Iron Man" while its own stat card said "Iron Man Mk 4",
            // until something unrelated rebuilt the column.
            bootStep(rebuildAllRosters);
            bootStep(rebuildOpponentRosters);
            // Seed on first run after this update, so an existing save does not open
            // to a pill claiming the whole catalogue is new.
            bootStep(() => { if (!shopSeenIds.length) markShopSeen(); });
            bootStep(refreshSplashState);
            // A save that has already seen the Snap goes straight to the end state
            // here, before the loading screen lifts — otherwise the retired tiles
            // are on screen for the whole load and then vanish. The intro itself
            // still starts later, from maybePlay(), which needs measurable tiles.
            if (window.SnapIntro) bootStep(() => SnapIntro.applyIfSnapped());
            // Arm the click trigger here too. maybePlay() was only being called
            // once the loading screen lifted, which left a window where clicking
            // the menu did nothing at all — and worse, that dead click still
            // started the lobby track, so the run-up below had already lost its
            // sync before the intro was even listening. Arming needs no
            // measurements; only play() does. While the Snap is vaulted there is
            // nothing to arm: this settles a fresh save to the end state instead.
            bootStep(offerSnapIntro);
            // The arena picker reads snapHasHappened() through isArenaRetired(), so
            // it has to be rebuilt once that flag is known.
            bootStep(refreshArenaButtons);
        });
